// No Slow: the item-use slowdown left out.
fn sunset_noslow_hook(input: [f32; 2], item_use: Option<f32>, sneaking: Option<f32>) -> std::ops::ControlFlow<[f32; 2]> {
    use std::sync::atomic::Ordering::Relaxed;
    if item_use.is_some() && sunset_flags::NO_SLOW.load(Relaxed) {
        // The slowdown by No Slow's factor instead of the game's: the input without it, scaled (modify_input with
        // Some(factor) would come back into this hook for ever).
        let factor = f32::from_bits(sunset_flags::NO_SLOW_FACTOR.load(Relaxed)).clamp(0.2, 1.0);
        let [x, z] = modify_input(input, None, sneaking);
        return std::ops::ControlFlow::Break([x * factor, z * factor]);
    }
    std::ops::ControlFlow::Continue(())
}

// Streamer Mode: sign text in the world is drawn with the names replaced, centred again on its new width.
fn sunset_streamer_sign(scene: &Scene, call: &TextCall, out: &mut Vec<Vertex>) -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    let Some(text) = crate::hud::sunset_streamer::protect_str(&call.text) else {
        return std::ops::ControlFlow::Continue(());
    };
    let width = text.chars().map(|c| (scene.glyph)(c).advance).sum::<f32>().ceil();
    let shown = TextCall { x: -((width as i32) / 2) as f32, text, ..call.clone() };
    crate::hud::sunset_streamer::guarded(|| draw_text(scene, &shown, out));
    std::ops::ControlFlow::Break(())
}

// No Render's Hide hurt cam: no tilt of the view when you are hurt.
fn sunset_hurt_cam() -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::screen_effects::sunset_overlay::NO_HURT.load(std::sync::atomic::Ordering::Relaxed) {
        std::ops::ControlFlow::Break(())
    } else {
        std::ops::ControlFlow::Continue(())
    }
}

// Debug Report's chat log: each line as it comes into the chat.
fn sunset_debug_chat(content: &crate::text::Text, source: crate::chat::ChatSource) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return; }

    crate::chat::sunset_chat_log::added(content, source);
}

// Xray: a section's blocks read while a mesh is built.
fn sunset_xray_unpack(out: &mut [u32; 4096], value: ()) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return; }

    crate::mesher::sunset_xray::filter_all(out);
    value
}

// Xray: a block read while a mesh is built.
fn sunset_xray_get(chunk: &Chunk, x: i32, y: i32, z: i32, value: u32) -> u32 {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return value; }

    crate::mesher::sunset_xray::filter(value, [chunk.x * 16 + (x & 15), y, chunk.z * 16 + (z & 15)])
}

// No Render: water, lava and powder snow fog turned into plain air.
fn sunset_fog_hook(world: &World, facts: &BlockFacts, camera: [f64; 3], near: &NearPlane) -> std::ops::ControlFlow<FogType> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use std::sync::atomic::Ordering::Relaxed;
    let (water, lava) = (sunset_fog::NO_WATER.load(Relaxed), sunset_fog::NO_LAVA.load(Relaxed));
    if !(water || lava) || sunset_fog::busy() {
        return std::ops::ControlFlow::Continue(());
    }
    sunset_fog::set_busy(true);
    let found = fog_type(world, facts, camera, near);
    sunset_fog::set_busy(false);
    std::ops::ControlFlow::Break(match found {
        FogType::Water if water => FogType::Atmospheric,
        FogType::Lava | FogType::PowderSnow if lava => FogType::Atmospheric,
        other => other,
    })
}

// Atmosphere's Custom fog. The game clears the distance fog here when its Fog option is off; Sunset turns the option
// off while Custom fog is on, and sets the fog's distances and colour here instead (in air: water and lava keep
// theirs).
fn sunset_ambience_fog(fog: &mut FogData, input: &FogInputs) -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    let custom = *sunset_fog::CUSTOM.lock().unwrap_or_else(|e| e.into_inner());
    let Some((start, end, rgb, cover)) = custom.filter(|_| input.fog_type == FogType::Atmospheric) else {
        return std::ops::ControlFlow::Continue(());
    };
    (fog.environmental_start, fog.environmental_end) = (start, end);
    (fog.render_distance_start, fog.render_distance_end) = (start, end);
    fog.color = [rgb[0], rgb[1], rgb[2], fog.color[3]];
    if cover {
        fog.sky_end = end;
    }
    std::ops::ControlFlow::Break(())
}

// As the fonts load, Sunset's goes into the resources.
fn sunset_font_hook(root: &Path) {
    sunset_font::install(root);
}

// The same for the HUD atlas, which loads its fonts over a pack overlay since nightly 9f42064.
fn sunset_font_over_hook(root: &Path) {
    sunset_font::install(root);
}

// Sunset's glyphs: the coverage goes in the alpha over white, which an ordinary blend wants, instead of grey in
// every channel (which blends as the coverage squared and thins every edge), and a touch of weight is added.
// Only grey texels are changed, so the bitmap fonts' white and transparent ones stay as they are.
fn sunset_patches(this: &Font) -> std::ops::ControlFlow<Vec<Patch>> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if sunset_font::STYLE.load(std::sync::atomic::Ordering::Relaxed) == 0 {
        return std::ops::ControlFlow::Continue(());
    }
    let mut patches = std::mem::take(&mut this.cache.borrow_mut().region.pending);
    for patch in &mut patches {
        for px in patch.rgba.chunks_exact_mut(4) {
            if px[0] == px[3] && px[1] == px[3] && px[2] == px[3] {
                let coverage = f32::from(px[3]) / 255.0;
                px.copy_from_slice(&[255, 255, 255, (coverage.powf(0.8) * 255.0).round() as u8]);
            }
        }
    }
    std::ops::ControlFlow::Break(patches)
}

// Streamer Mode: text is measured as it will be drawn, names replaced, so what is centred or wrapped by its width
// still lines up.
fn sunset_streamer_width(font: &Font, s: &str) -> std::ops::ControlFlow<f32> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match crate::hud::sunset_streamer::protect_str(s) {
        Some(t) => std::ops::ControlFlow::Break(crate::hud::sunset_streamer::guarded(|| font.width(&t))),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// Streamer Mode: a styled text is measured as it will be drawn, names replaced.
fn sunset_streamer_width_text(font: &Font, t: &Text) -> std::ops::ControlFlow<f32> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match crate::hud::sunset_streamer::protect(t) {
        Some(t) => std::ops::ControlFlow::Break(crate::hud::sunset_streamer::guarded(|| font.width_text(&t))),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// The native depth-tested stroke is skipped only for an owned visual frame.
// No pipeline, buffer, pass, or gameplay state is changed.
fn sunset_block_overlay_draw() -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if sunset_block_overlay_flags::active() {
        std::ops::ControlFlow::Break(())
    } else {
        std::ops::ControlFlow::Continue(())
    }
}

// Restore and release cached device objects before Horizon replaces its renderer.
fn sunset_atmosphere_release(renderer: &mut Renderer) {
    sunset_atmosphere_renderer::release(renderer);
}

// Renderer::render is a macro-free supported Mixins HEAD boundary.
fn sunset_atmosphere_render(renderer: &mut Renderer, frame: &Frame<'_>) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return; }

    sunset_atmosphere_renderer::prepare(renderer, frame);
}

// The procedural field owns stars only after a custom sky pipeline succeeded.
// This restores vanilla stars automatically on every disabled or unsupported frame.
fn sunset_atmosphere_stars() -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if super::sunset_atmosphere_renderer::owns_sky() {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

fn sunset_crosshair_rect(
    batch: &crate::hud::HudBatch,
    x: f32,
    y: f32,
    w: f32,
    h: f32,
    rect: crate::hud::Rect,
    color: u32,
) -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::hud::sunset_crosshair::suppress_mark(batch, x, y, w, h, rect, color) {
        std::ops::ControlFlow::Break(())
    } else {
        std::ops::ControlFlow::Continue(())
    }
}

// No Render: the dark sheet drawn behind an inventory, a book, a trade and the like is left out.
fn sunset_menu_dark(this: &HudBatch, x: f32, y: f32, w: f32, h: f32, color: u32) -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use std::sync::atomic::Ordering::Relaxed;
    if crate::screen_effects::sunset_overlay::NO_MENU.load(Relaxed)
        && x == 0.0
        && y == 0.0
        && w == this.width
        && h == this.height
        && color == rgba(16, 16, 16, 160)
    {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// Streamer Mode: every text drawn in the game's font (HUD, chat, tab list, scoreboard, titles, boss bars, tooltips,
// screens, name tags in the world) is drawn with the names it hides replaced.
fn sunset_streamer_text(
    batch: &mut HudBatch,
    atlas: &HudAtlas,
    text: &crate::text::Text,
    x: f32,
    y: f32,
    color: u32,
    shadow: bool,
    world: bool,
    outline: Option<(u32, [f32; 2])>,
) -> std::ops::ControlFlow<f32> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match crate::hud::sunset_streamer::protect(text) {
        Some(t) => std::ops::ControlFlow::Break(crate::hud::sunset_streamer::guarded(|| {
            batch.styled_text(atlas, &t, x, y, color, shadow, world, outline)
        })),
        None => std::ops::ControlFlow::Continue(()),
    }
}

