// No Render: the blur behind the pause menu and other screens is left out with the dark sheet.
fn sunset_menu_blur() -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::screen_effects::sunset_overlay::NO_MENU.load(std::sync::atomic::Ordering::Relaxed) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// Xray: while a section mesh is built, only the listed blocks are there. Clear Water: the built mesh's water is
// drawn fainter and lighter. On mesh_reusing, the meshing workers' path (Mesher::mesh goes through it too).
fn sunset_xray_hook(
    this: &mut Mesher<'_>,
    region: &[[Option<&Chunk>; 3]; 3],
    sy: i32,
    out: &mut SectionMesh,
    scratch: &mut MeshScratch,
) -> std::ops::ControlFlow<SectionMesh> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use std::sync::atomic::Ordering::Relaxed;
    let (xray, water) = (sunset_xray::ON.load(Relaxed), sunset_water::on());
    if !(xray || water) || sunset_xray::meshing() {
        return std::ops::ControlFlow::Continue(());
    }
    if let Some(c) = region[1][1].filter(|_| xray) {
        sunset_xray::set_origin([c.x * 16, c.min_y() + sy * 16, c.z * 16]);
    }
    sunset_xray::set_meshing(true);
    let mut mesh = this.mesh_reusing(region, sy, std::mem::take(out), scratch);
    sunset_xray::set_meshing(false);
    if water {
        sunset_water::clear(&mut mesh);
    }
    std::ops::ControlFlow::Break(mesh)
}

// No Render: a hidden particle made outside the options path is not kept.
fn sunset_particle_push(particle: &Particle) -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if sunset_particles::hidden(particle.ty) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// No Render: a hidden particle is not made at all.
fn sunset_particle_add(options: &ParticleOptions) -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if sunset_particles::hidden(options.ty) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// No Render: the screen overlays the player chose to hide are left out.
fn sunset_overlay_hook(this: &ScreenEffects, input: &ScreenInputs<'_>) -> std::ops::ControlFlow<Vec<ScreenQuad>> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use std::sync::atomic::Ordering::Relaxed;
    let (fire, liquid, wall, gui) = (
        sunset_overlay::NO_FIRE.load(Relaxed),
        sunset_overlay::NO_LIQUID.load(Relaxed),
        sunset_overlay::NO_WALL.load(Relaxed),
        sunset_overlay::NO_GUI.load(Relaxed),
    );
    if !(fire || liquid || wall || gui) || sunset_overlay::busy() {
        return std::ops::ControlFlow::Continue(());
    }
    sunset_overlay::set_busy(true);
    let none: &[GuiDraw] = &[];
    let changed = ScreenInputs {
        sprites: input.sprites,
        flags: input.flags,
        aspect: input.aspect,
        partial: input.partial,
        block_overlay: if wall { None } else { input.block_overlay.clone() },
        water: if liquid { None } else { input.water },
        on_fire: input.on_fire && !fire,
        fire_lower: input.fire_lower,
        gui_overlays: if gui { none } else { input.gui_overlays },
    };
    let quads = this.build(&changed);
    sunset_overlay::set_busy(false);
    std::ops::ControlFlow::Break(quads)
}

// Clear Water: a water sprite is laid out at every lower opacity just before itself, so its own layer follows them.
fn sunset_water_sprites(this: &mut Sprites, root: &Path, name: &str, decoded: &crate::sprite_cache::Decoded) -> std::ops::ControlFlow<Result<u32>> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use crate::mesher::sunset_water as w;
    let Some(sprite) = w::SPRITES.iter().position(|s| *s == name) else {
        return std::ops::ControlFlow::Continue(());
    };
    let path = name.trim_start_matches("minecraft:");
    let mut copies = [0; w::STEPS];
    for (step, layer) in copies.iter_mut().enumerate() {
        let mut copy = decoded.clone();
        copy.frames = w::faded(&decoded.frames, step);
        copy.opaque = false;
        copy.has_transparent |= step == 0;
        copy.translucent = step > 0;
        match this.register(root, &["sunset:", path, "_", &step.to_string()].concat(), copy) {
            Ok(l) => *layer = l,
            Err(e) => return std::ops::ControlFlow::Break(Err(e)),
        }
    }
    w::set_layers(sprite, this.native.len() as u32, copies);
    std::ops::ControlFlow::Continue(())
}

// HUD's Tab game modes: a spectator's or creative player's name in the tab list gets its tag.
fn sunset_tab_modes_name(p: &TabPlayer, board: &Scoreboard) -> std::ops::ControlFlow<Text> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match crate::tab_list::sunset_tab_modes::marked(p, board) {
        Some(name) => std::ops::ControlFlow::Break(name),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// HUD's Tab game modes switched on or off (or Sunset stopped): the cached tab list is drawn again with the names as
// they are now.
fn sunset_tab_modes_layout(this: &mut TabList) {
    if crate::tab_list::sunset_tab_modes::changed(horizon_protocol::connection::sunset_lifecycle::RUNTIME.running()) {
        this.cache = None;
    }
}

// No Render: the shade behind the pause menu in a world is left out.
fn sunset_pause_dark(in_world: bool) -> std::ops::ControlFlow<()> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if in_world && crate::screen_effects::sunset_overlay::NO_MENU.load(std::sync::atomic::Ordering::Relaxed) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// Timer: the frame's elapsed time, scaled.
fn sunset_timer_hook(this: &mut FixedStep, elapsed: std::time::Duration) -> std::ops::ControlFlow<u32> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use std::sync::atomic::Ordering::Relaxed;
    let m = f32::from_bits(sunset_timer::MULT.load(Relaxed));
    if m == 1.0 || sunset_timer::BUSY.swap(true, Relaxed) {
        return std::ops::ControlFlow::Continue(());
    }
    let ticks = this.advance(elapsed.mul_f32(m));
    sunset_timer::BUSY.store(false, Relaxed);
    std::ops::ControlFlow::Break(ticks)
}

// Hand View's No equip drop: the hands stay up when the held item changes or the attack cooldown runs, and a new
// item shows at once. Its 1.8 Animations: the hand does not dip after a hit (1.8 had no cooldown), as Horizon's own
// Combat feel Legacy raises it, but still drops and rises for a new item.
fn sunset_equip_hold(this: &mut HandHeights, hands_busy: bool, swap_scale: f32, changed: [bool; 2]) -> std::ops::ControlFlow<[bool; 2]> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use crate::first_person::sunset_hand_view as view;
    if view::NO_EQUIP_DROP.load(std::sync::atomic::Ordering::Relaxed) {
        (this.main, this.old_main, this.off, this.old_off) = (1.0, 1.0, 1.0, 1.0);
        return std::ops::ControlFlow::Break(changed);
    }
    if view::LEGACY.load(std::sync::atomic::Ordering::Relaxed) {
        return std::ops::ControlFlow::Break(this.tick_with(hands_busy, swap_scale, changed, true));
    }
    std::ops::ControlFlow::Continue(())
}

// Hand View's No sway: the hands do not lag behind the view as it turns.
fn sunset_sway() -> std::ops::ControlFlow<[f32; 2]> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::first_person::sunset_hand_view::NO_SWAY.load(std::sync::atomic::Ordering::Relaxed) {
        return std::ops::ControlFlow::Break([0.0, 0.0]);
    }
    std::ops::ControlFlow::Continue(())
}

// RF Click: R and F become the mouse buttons before the game sees the key.
fn sunset_rf_click(event: &mut winit::event::WindowEvent) {
    crate::game::sunset_hands::rf_event(event);
}

// The window's events as they come, before any screen: the text the keyboard layout makes (the GUI's text editor types
// it), and presses, releases and focus for the binds (a Hold bind lets go even when a screen took the release) and the
// combat macros.
fn sunset_window_event(event: &winit::event::WindowEvent) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return; }

    crate::game::sunset::text_event(event);
    crate::game::sunset::bind_event(event);
    if let winit::event::WindowEvent::Focused(false) = event {
        crate::game::sunset_combat_macros::focus_lost();
        crate::game::sunset_hands::rf_focus_lost();
    }
}

// Reach: the block reach, plus Reach's extra.
fn sunset_reach(game: &crate::game::Game<'_>) -> std::ops::ControlFlow<f64> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match crate::game::sunset_player::reach_extra() {
        Some(extra) => std::ops::ControlFlow::Break(if game.creative { 5.0 } else { 4.5 } + extra),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// Liquid Interact: when the crosshair meets no block, the water or lava it meets counts as one.
fn sunset_liquid_pick(game: &crate::game::Game<'_>) -> std::ops::ControlFlow<Option<Hit>> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match crate::game::sunset_parity::liquid_pick(game) {
        Some(hit) => std::ops::ControlFlow::Break(hit),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// Before each tick: keys held for the player, flight, step height.
fn sunset_pretick(game: &mut crate::game::Game<'_>) {
    crate::game::sunset::pre_tick(game);
}

// HUD construction runs before native world submission, even with F1 active.
fn sunset_atmosphere_sync(game: &crate::game::Game<'_>) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return; }

    crate::game::sunset_atmosphere::sync(game);
}

// HUD construction runs before Renderer::render submits this frame's outline.
// Reset before its early exits or config reads, then publish style ownership.
fn sunset_block_overlay_render(game: &crate::game::Game<'_>) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return; }

    use horizon_client::gfx::sunset_block_overlay_flags as flags;
    flags::publish(false);
    if !game.native_window() || !game.native_on(crate::game::sunset::ID) {
        return;
    }
    crate::game::sunset::ensure_loaded(game);
    flags::publish(crate::game::sunset_block_overlay::suppress_native_outline(game));
