// Run after native jump/input processing, before moving: preserve a ballistic velocity as well as displacement.
// Merely overriding move_self's Y produces a one-tick position lift followed by the old vertical velocity.
fn sunset_legacy_jump(world: &mut MotionWorld<'_, '_, '_>) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return; }
    let across = crate::motion::sunset_motion::take_legacy_velocity();
    if let Some(scale) = crate::motion::sunset_motion::take_ballistic_jump() {
        let power = if scale.is_finite() && scale > 0.0 {
            horizon_world::living_motion::jump_power(world, scale as f32).ok()
        } else { None };
        let Some(power) = power.filter(|p| p.is_finite() && *p > 0.0) else {
            // A zero/invalid jump attribute or block factor must not become a horizontal-only launch.
            crate::motion::sunset_motion::set_across(None);
            return;
        };
        world.player.velocity.y = f64::from(power);
        world.player.fall_distance = 0.0;
        world.player.needs_sync = true;
        crate::motion::sunset_motion::set_up(Some(f64::from(power)));
    }
    if let Some([x, z]) = across && x.is_finite() && z.is_finite() {
        world.player.velocity.x = x;
        world.player.velocity.z = z;
    }
}

// Speed: the player's own move across the ground, when Speed sets it.
fn sunset_self_move(value: Vec3) -> Vec3 {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return value; }

    crate::motion::sunset_motion::self_move(value)
}

// Velocity: the push of each flowing fluid block on the player, scaled.
fn sunset_flow(value: Result<Vec3>) -> Result<Vec3> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return value; }

    value.map(crate::motion::sunset_motion::liquid_flow)
}

// Client Spoofer: single player sends Horizon's own brand.
fn sunset_client_local() {
    crate::net::sunset_client_brand::next(None);
}

// Copies of the packets Crystal Aura and Anchor Aura learn from, as the game takes them in (after Anti trap dropped its
// spawns, Backtrack held back what came while its player moved away, and Knockback Delay the pushes it delays), and
// Client Spoofer's watch for the Login packets its join packets follow. The session comes too: what Backtrack and
// Knockback Delay hold belongs to the session it came from, and the connection's boundaries are counted for Fake Lag.
fn sunset_packet_tap(session: &Session, value: Vec<Event>) -> Vec<Event> {
    crate::net::sunset_packets::note(session, &value);
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() {
        // Preserve incoming server authority: release delayed packets, without
        // calling observers, filters or plugin handlers while stopped.
        let value = crate::net::sunset_packets::backtrack_hold(session, value);
        return crate::net::sunset_packets::hold(session, value);
    }
    let value = crate::net::sunset_packets::trap_filter(value);
    let value = crate::net::sunset_packets::backtrack_hold(session, value);
    let value = crate::net::sunset_packets::hold(session, value);
    crate::net::sunset_packets::seen(&value);
    crate::net::sunset_client_brand::seen(&value);
    crate::net::sunset_packets::gui_move_hold(value)
}

// Configuration payloads otherwise do not become game events. Observe the identifier and
// minecraft:register's channel list only.
fn sunset_server_scan_config_channel(
    payload: &horizon_protocol::packets::configuration::CustomPayload,
) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return; }

    crate::net::sunset_packets::scan_config(payload);
}

// Client Spoofer: the brand of the connection being made, Horizon's own otherwise.
fn sunset_client_brand() -> std::ops::ControlFlow<Vec<u8>> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match crate::net::sunset_client_brand::payload() {
        Some(data) => std::ops::ControlFlow::Break(data),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// Flight: the next move packet carries the position when the anti kick asks for it. A move packet whose ground Sunset
// changed: the game compares with the ground the server was told.
fn sunset_sync(this: &mut PositionSender) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return; }

    if crate::player_sync::sunset_sync::take() {
        this.reminder = 20;
    }
    if let Some(told) = crate::player_sync::sunset_sync::take_ground() {
        this.on_ground = told;
    }
}

// Streamer Mode: Horizon's own screens measure text as it will be drawn, names replaced.
fn sunset_streamer_ui_measure(ui: &Ui<'_>, face: Face, size: f32, text: &str) -> std::ops::ControlFlow<f32> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match horizon_client_render::hud::sunset_streamer::protect_str(text) {
        Some(t) => std::ops::ControlFlow::Break(horizon_client_render::hud::sunset_streamer::guarded(|| {
            ui.measure(face, size, &t)
        })),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// Streamer Mode: Horizon's own screens (its title screen and menus, in their own font) draw and measure text with
// the names replaced.
fn sunset_streamer_ui(
    ui: &mut Ui<'_>,
    face: Face,
    size: f32,
    line: f32,
    x: f32,
    y: f32,
    color: u32,
    text: &str,
) -> std::ops::ControlFlow<f32> {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match horizon_client_render::hud::sunset_streamer::protect_str(text) {
        Some(t) => std::ops::ControlFlow::Break(horizon_client_render::hud::sunset_streamer::guarded(|| {
            ui.text_line(face, size, line, x, y, color, &t)
        })),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// Debug Report's packet log: each packet the client sends, as it goes on the wire.
fn sunset_debug_wire(body: &[u8]) {
    if !crate::connection::sunset_lifecycle::RUNTIME.running() { return; }

    crate::connection::sunset_wire::sent(body);
}

