// No Slow's switch, read by the movement input hook.
use std::sync::atomic::{AtomicBool, AtomicU32};

pub static NO_SLOW: AtomicBool = AtomicBool::new(false);
pub static NO_SLOW_FACTOR: AtomicU32 = AtomicU32::new(1.0_f32.to_bits());

// Access to the private native click counters, kept in their owning module.
pub fn counts(input: &super::InteractionInput) -> [u32; 3] { input.clicks }

pub fn cancel(input: &mut super::InteractionInput, owned: [u32; 3]) {
    for (pending, ours) in input.clicks.iter_mut().zip(owned) {
        *pending = pending.saturating_sub(ours);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn panic_cancels_owned_clicks_and_preserves_physical_clicks() {
        let mut input = super::super::InteractionInput::default();
        for button in [super::super::Button::Attack, super::super::Button::Use,
            super::super::Button::Use, super::super::Button::Pick] { input.press(button); }
        cancel(&mut input, [0, 1, 0]);
        assert_eq!(counts(&input), [1, 1, 1]);
        cancel(&mut input, [0, 1, 0]);
        assert_eq!(counts(&input), [1, 0, 1]);
    }
}

// Debug Report's chat log: every line that comes into the chat (the server's, players' and the client's own), as
// plain text without its colour codes, with the time it came. Kept even when the Chat option hides it, and past the
// chat's own 100.

use std::collections::VecDeque;
use std::sync::Mutex;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::SystemTime;

const KEEP: usize = 500;

#[derive(Clone)]
pub struct Line {
    pub at: SystemTime,
    pub source: crate::chat::ChatSource,
    pub text: String,
}

static LOG: Mutex<VecDeque<Line>> = Mutex::new(VecDeque::new());
// Lines ever added: the plugin API's chat event reads the ones after the count it saw last.
static ADDED: AtomicU64 = AtomicU64::new(0);

pub fn added(content: &crate::text::Text, source: crate::chat::ChatSource) {
    let text: String = content.strip_legacy().plain().chars().map(|c| if c.is_control() { ' ' } else { c }).collect();
    let mut log = LOG.lock().unwrap_or_else(|e| e.into_inner());
    if log.len() == KEEP {
        log.pop_front();
    }
    log.push_back(Line { at: SystemTime::now(), source, text });
    ADDED.fetch_add(1, Ordering::Relaxed);
}

// The count of lines added so far, and the lines kept that came after `seen` of them (none the first time: u64::MAX).
pub fn since(seen: u64) -> (u64, Vec<Line>) {
    let log = LOG.lock().unwrap_or_else(|e| e.into_inner());
    let total = ADDED.load(Ordering::Relaxed);
    let new = usize::try_from(total.saturating_sub(seen)).unwrap_or(usize::MAX).min(log.len());
    (total, log.iter().skip(log.len() - new).cloned().collect())
}

// The lines kept, oldest first.
pub fn lines() -> Vec<Line> {
    LOG.lock().unwrap_or_else(|e| e.into_inner()).iter().cloned().collect()
}

// No Render's fog switches, read by the fog type hook, and Atmosphere's Custom fog (start, end, colour, Cover
// horizon band), read where the game would clear the fog.
use std::cell::Cell;
use std::sync::Mutex;
use std::sync::atomic::AtomicBool;

pub static CUSTOM: Mutex<Option<(f32, f32, [f32; 3], bool)>> = Mutex::new(None);

pub static NO_WATER: AtomicBool = AtomicBool::new(false);
pub static NO_LAVA: AtomicBool = AtomicBool::new(false);
thread_local! {
    pub static BUSY: Cell<bool> = const { Cell::new(false) };
}
pub fn busy() -> bool {
    BUSY.with(Cell::get)
}
pub fn set_busy(v: bool) {
    BUSY.with(|b| b.set(v));
}

// Sunset's own fonts, so its menu and HUD don't use Minecraft's bitmap one. Horizon reads TrueType fonts from
// the resources, so each file and its definition are written there before the fonts load.
use std::path::Path;
use std::sync::atomic::{AtomicBool, AtomicU8, Ordering};

use super::sunset_fontdata::FONTS;

// The HUD's Font choice: 0 is the game's own font, 1 and up the fonts of sunset_fontdata::FONTS in order.
pub static STYLE: AtomicU8 = AtomicU8::new(1);
// Set while a header is drawn: it takes the font's bolder weight.
pub static BOLD: AtomicBool = AtomicBool::new(false);
pub static READY: AtomicBool = AtomicBool::new(false);
// The GUI scale the glyphs were last drawn for (f32 bits).
static SCALE: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);

// The STYLE for a name HUD > Font offers: Minecraft's own is 0, a font its place in the list, and anything else (a
// choice from an older version) the first.
pub fn style(label: &str) -> u8 {
    match super::sunset_fontdata::LABELS.iter().position(|l| *l == label) {
        Some(i) if i < FONTS.len() => i as u8 + 1,
        Some(_) => 0,
        None => 1,
    }
}

fn put(path: &Path, bytes: &[u8]) -> bool {
    if std::fs::read(path).is_ok_and(|have| have == bytes) {
        return true;
    }
    std::fs::write(path, bytes).is_ok()
}

// Called as the game's fonts load: puts the fonts where they look.
pub fn install(root: &Path) {
    let dir = root.join("assets").join("sunset").join("font");
    let mut ok = std::fs::create_dir_all(&dir).is_ok();
    for (name, regular, bold, size) in FONTS {
        for (stem, data) in [(name.to_owned(), regular), (format!("{name}-bold"), bold)] {
            let definition = format!(
                r#"{{"providers":[{{"type":"ttf","file":"sunset:{stem}.ttf","size":{size:.1},"oversample":4.0,"shift":[0.0,0.0]}}]}}"#
            );
            ok = ok && put(&dir.join(format!("{stem}.json")), definition.as_bytes()) && put(&dir.join(format!("{stem}.ttf")), data);
        }
    }
    READY.store(ok, Ordering::Relaxed);
    // The fonts are new: tune them again at the next draw.
    SCALE.store(0, Ordering::Relaxed);
}

// Draws the glyphs at the screen's own pixel size: one oversampled pixel for each screen pixel, so each glyph
// lands on whole screen pixels and the text is sharp at any GUI scale instead of being scaled from a fixed bitmap.
// The height is nudged so the capitals are a whole number of pixels tall, and their top and bottom edges are
// crisp. Called as text is drawn.
pub fn sync(font: &super::Font, gui_scale: f32) {
    use ab_glyph::Font as _;
    use std::sync::atomic::Ordering::Relaxed;
    if f32::from_bits(SCALE.load(Relaxed)) == gui_scale {
        return;
    }
    SCALE.store(gui_scale.to_bits(), Relaxed);
    {
        let mut cache = font.cache.borrow_mut();
        for (id, set) in cache.sets.iter_mut() {
            let Some(size) = id
                .strip_prefix("sunset:")
                .and_then(|n| FONTS.iter().find(|f| f.0 == n.strip_suffix("-bold").unwrap_or(n)))
                .map(|f| f.3)
            else {
                continue;
            };
            for provider in set.providers.iter_mut() {
                if let super::Provider::TrueType(_, tt) = provider {
                    let units = tt.font.units_per_em().unwrap_or(1000.0);
                    let k = tt.font.height_unscaled() / units;
                    // The capitals' height as a share of the em: the H at an em of 1000 pixels.
                    let cap = tt
                        .font
                        .outline_glyph(tt.font.glyph_id('H').with_scale(ab_glyph::PxScale::from(1000.0 * k)))
                        .map_or(0.7, |o| o.px_bounds().height() / 1000.0);
                    let em = (size * gui_scale).round().max(1.0);
                    let tall = (cap * em).round().max(1.0) / cap;
                    tt.oversample = gui_scale;
                    tt.scale = ab_glyph::PxScale { x: em * k, y: tall * k };
                    tt.shift = (0.0, 0.0);
                }
            }
        }
    }
    font.reset_cache();
}

pub fn enabled() -> bool {
    STYLE.load(Ordering::Relaxed) != 0 && READY.load(Ordering::Relaxed)
}

// A line of text in the chosen font.
pub fn text(s: &str) -> crate::text::Text {
    let name = FONTS.get(usize::from(STYLE.load(Ordering::Relaxed)).wrapping_sub(1)).map_or(FONTS[0].0, |f| f.0);
    let bold = if BOLD.load(Ordering::Relaxed) { "-bold" } else { "" };
    crate::text::Text::styled(
        s,
        crate::text::Style {
            font: Some(format!("sunset:{name}{bold}")),
            ..Default::default()
        },
    )
}

// Atmosphere's settings handed to the renderer crate, numbers only.
use std::sync::Mutex;

#[derive(Clone, Copy, Debug)]
pub struct Config {
    pub enabled: bool,
    /// The game must positively identify a live Overworld before enabling the sky.
    pub world_supported: bool,
    /// 0 Space, 1 Aurora, 2 Ringed Planet.
    pub mode: u32,
    pub brightness: f32,
    pub strength: f32,
    pub stars: f32,
    /// Zero pauses the procedural animation.
    pub speed: f32,
    pub day_blend: f32,
    /// 0 Performance, 1 Balanced, 2 Detailed.
    pub quality: u32,
}

impl Default for Config {
    fn default() -> Self {
        DEFAULT
    }
}

const DEFAULT: Config = Config {
    enabled: false,
    world_supported: false,
    mode: 0,
    brightness: 1.0,
    strength: 1.0,
    stars: 1.0,
    speed: 1.0,
    day_blend: 0.65,
    quality: 1,
};

static CONFIG: Mutex<Config> = Mutex::new(DEFAULT);

fn finite(value: f32, fallback: f32, maximum: f32) -> f32 {
    if value.is_finite() {
        value.clamp(0.0, maximum)
    } else {
        fallback
    }
}

pub fn configure(mut config: Config) {
    config.mode = config.mode.min(2);
    config.quality = config.quality.min(2);
    config.brightness = finite(config.brightness, 1.0, 2.0);
    config.strength = finite(config.strength, 1.0, 2.0);
    config.stars = finite(config.stars, 1.0, 2.0);
    config.speed = finite(config.speed, 1.0, 2.0);
    config.day_blend = finite(config.day_blend, 0.65, 1.0);
    *CONFIG
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner) = config;
}

pub(super) fn snapshot() -> Config {
    *CONFIG
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
}

// Specializes only Horizon's resident vanilla sky pipeline. The existing world pass,
// group 0 Globals buffer, camera, celestial bodies, depth and target remain Horizon's.
// Unchanged frames add no allocation, buffer upload, draw call or render pass.
use std::cell::RefCell;
use std::time::{Duration, Instant};

use super::sunset_atmosphere_flags::{Config, snapshot};
use super::wgsl_prefix::{TERRAIN, section};
use super::{Frame, Renderer};

const DEBOUNCE: Duration = Duration::from_millis(250);
const ENTRY: &str = "
@fragment fn fs_sunset_atmosphere(in: SkyOut) -> @location(0) vec4<f32> {
    let ray = view_ray(in.ndc);
    return vec4(sunset_atmosphere(ray), 1.0);
}
";

#[derive(Clone, Copy, PartialEq, Eq)]
struct Key([u32; 7]);

impl From<Config> for Key {
    fn from(c: Config) -> Self {
        Self([
            c.mode,
            c.brightness.to_bits(),
            c.strength.to_bits(),
            c.stars.to_bits(),
            c.speed.to_bits(),
            c.day_blend.to_bits(),
            c.quality,
        ])
    }
}

struct State {
    device: wgpu::Device,
    globals: wgpu::Buffer,
    format: wgpu::TextureFormat,
    original: wgpu::RenderPipeline,
    shader: Option<wgpu::ShaderModule>,
    effect: Option<(Key, wgpu::RenderPipeline)>,
    requested: Key,
    changed_at: Instant,
    failed: Option<Key>,
    active: bool,
}

// Horizon has one active renderer on the window thread. The release_surface and
// Game::finish_perf HEAD hooks drop this cache while Renderer/Instance are still alive.
// GPU resources must never survive until the window thread's TLS destructors.
thread_local! {
    static STATE: RefCell<Option<State>> = const { RefCell::new(None) };
}

fn shader(device: &wgpu::Device) -> Option<wgpu::ShaderModule> {
    let text = [
        section(TERRAIN, "struct Globals {", "@group(0) @binding(1)"),
        section(TERRAIN, "fn linear_fog(", "fn apply_fog("),
        section(TERRAIN, "struct SkyOut {", "// rendertype_lines"),
        super::sunset_atmosphere_shader::ATMOSPHERE_WGSL,
        ENTRY,
    ]
    .concat();
    let module = match naga::front::wgsl::parse_str(&text) {
        Ok(module) => module,
        Err(error) => {
            log::warn!("Sunset sky disabled: {}", error.emit_to_string(&text));
            return None;
        }
    };
    if let Err(error) = naga::valid::Validator::new(
        naga::valid::ValidationFlags::all(),
        naga::valid::Capabilities::default(),
    )
    .validate(&module)
    {
        log::warn!("Sunset sky disabled: {error}");
        return None;
    }
    let scope = device.push_error_scope(wgpu::ErrorFilter::Validation);
    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("Sunset original procedural sky"),
        source: wgpu::ShaderSource::Naga(std::borrow::Cow::Owned(module)),
    });
    if let Some(error) = pollster::block_on(scope.pop()) {
        log::warn!("Sunset sky disabled: {error}");
        return None;
    }
    Some(module)
}

fn pipeline(
    renderer: &Renderer,
    shader: &wgpu::ShaderModule,
    config: Config,
) -> Option<wgpu::RenderPipeline> {
    let constants = [
        ("SUNSET_MODE", f64::from(config.mode)),
        ("SUNSET_BRIGHTNESS", f64::from(config.brightness)),
        ("SUNSET_STRENGTH", f64::from(config.strength)),
        ("SUNSET_STARS", f64::from(config.stars)),
        ("SUNSET_SPEED", f64::from(config.speed)),
        ("SUNSET_DAY_BLEND", f64::from(config.day_blend)),
        ("SUNSET_QUALITY", f64::from(config.quality)),
    ];
    let device = &renderer.device;
    let scope = device.push_error_scope(wgpu::ErrorFilter::Validation);
    let layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("Sunset sky existing terrain globals"),
        bind_group_layouts: &[Some(&renderer.terrain_layout)],
        ..Default::default()
    });
    let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
        label: Some("Sunset Space / Aurora sky"),
        layout: Some(&layout),
        vertex: wgpu::VertexState {
            module: shader,
            entry_point: Some("vs_sky"),
            compilation_options: Default::default(),
            buffers: &[],
        },
        primitive: Default::default(),
        depth_stencil: Some(wgpu::DepthStencilState {
            format: wgpu::TextureFormat::Depth32Float,
            depth_write_enabled: Some(false),
            depth_compare: Some(wgpu::CompareFunction::Always),
            stencil: Default::default(),
            bias: Default::default(),
        }),
        multisample: Default::default(),
        fragment: Some(wgpu::FragmentState {
            module: shader,
            entry_point: Some("fs_sunset_atmosphere"),
            compilation_options: wgpu::PipelineCompilationOptions {
                constants: &constants,
                ..Default::default()
            },
            targets: &[Some(wgpu::ColorTargetState {
                format: renderer.config.format.remove_srgb_suffix(),
                blend: None,
                write_mask: wgpu::ColorWrites::ALL,
            })],
        }),
        multiview_mask: None,
        cache: None,
    });
    if let Some(error) = pollster::block_on(scope.pop()) {
        log::warn!("Sunset sky settings unavailable; using vanilla sky: {error}");
        return None;
    }
    Some(pipeline)
}

fn supported(renderer: &Renderer, frame: &Frame<'_>, config: Config) -> bool {
    config.enabled
        && config.world_supported
        && !renderer.suspended
        && !frame.title
        && frame.skybox
        && !frame.end_sky
        && !frame.nether_lighting
        && !frame.sky_blocked
        && !frame.underwater
        && frame.pack.eye_in == 0
        && frame.environment_fog.is_none()
        && renderer.native.is_none()
        && renderer.pack_post.is_none()
}

pub(super) fn prepare(renderer: &mut Renderer, frame: &Frame<'_>) {
    let config = snapshot();
    let enabled = supported(renderer, frame, config);
    STATE.with(|cell| {
        let mut slot = cell.borrow_mut();
        if let Some(state) = slot.as_mut() {
            state.active = false;
        }
        if let Some(state) = slot.as_ref()
            && (state.device != renderer.device
                || state.globals != renderer.globals
                || state.format != renderer.config.format.remove_srgb_suffix())
        {
            // A renderer replacing its device already has its own vanilla pipeline.
            *slot = None;
        }
        if !enabled {
            if let Some(state) = slot.as_ref() {
                renderer.sky = state.original.clone();
            }
            return;
        }
        let key = Key::from(config);
        let state = slot.get_or_insert_with(|| State {
            device: renderer.device.clone(),
            globals: renderer.globals.clone(),
            format: renderer.config.format.remove_srgb_suffix(),
            original: renderer.sky.clone(),
            shader: shader(&renderer.device),
            effect: None,
            requested: key,
            changed_at: Instant::now(),
            failed: None,
            active: false,
        });
        if state.requested != key {
            state.requested = key;
            state.changed_at = Instant::now();
        }
        let current = state.effect.as_ref().map(|(key, _)| *key);
        // Keep the prior effect during a slider drag; compile only the settled value.
        let settled = current.is_none() || state.changed_at.elapsed() >= DEBOUNCE;
        if current != Some(key) && state.failed != Some(key) && settled {
            if let Some(shader) = state.shader.as_ref() {
                match pipeline(renderer, shader, config) {
                    Some(pipeline) => {
                        state.effect = Some((key, pipeline));
                        state.failed = None;
                    }
                    None => {
                        state.failed = Some(key);
                        state.effect = None;
                        // A validated, bounded specialization failing on this device is
                        // terminal until renderer replacement; slider edits cannot retry it.
                        state.shader = None;
                    }
                }
            }
        }
        renderer.sky = state
            .effect
            .as_ref()
            .map_or_else(|| state.original.clone(), |(_, pipeline)| pipeline.clone());
        state.active = state.effect.is_some();
    });
}

pub(super) fn owns_sky() -> bool {
    STATE.with(|cell| cell.borrow().as_ref().is_some_and(|state| state.active))
}

pub fn release(renderer: &mut Renderer) {
    // Shutdown may be exceptional; never attempt to re-enter an already-destroyed TLS.
    let _ = STATE.try_with(|cell| {
        let mut slot = cell.borrow_mut();
        if let Some(state) = slot.as_ref()
            && state.device == renderer.device
            && state.globals == renderer.globals
        {
            renderer.sky = state.original.clone();
            *slot = None;
        }
    });
}

// Atmosphere's sky, made in the shader alone (no textures, no ray marching, nothing kept from frame to frame).
// The renderer appends this to its existing Globals/sky declarations. Quality specializes
// a bounded 2/4/6-octave cloud field and 1/2/3 star layers; all modes use one cached pipeline.
pub const ATMOSPHERE_WGSL: &str = r#"
override SUNSET_MODE: u32 = 0u;
override SUNSET_BRIGHTNESS: f32 = 1.0;
override SUNSET_STRENGTH: f32 = 1.0;
override SUNSET_STARS: f32 = 1.0;
override SUNSET_SPEED: f32 = 1.0;
override SUNSET_DAY_BLEND: f32 = 1.0;
override SUNSET_QUALITY: u32 = 1u;

// Integer mixing keeps a world cell's seed independent of camera and animation time.
fn sunset_hash(cell: vec3<i32>) -> u32 {
    let p = bitcast<vec3<u32>>(cell);
    var h = p.x * 1597334677u ^ p.y * 3812015801u ^ p.z * 2798796415u;
    h = (h ^ (h >> 16u)) * 2246822519u;
    h = (h ^ (h >> 13u)) * 3266489917u;
    return h ^ (h >> 16u);
}
fn sunset_random(cell: vec3<i32>) -> f32 {
    return f32(sunset_hash(cell) >> 8u) * (1.0 / 16777216.0);
}
fn sunset_noise(p: vec3<f32>) -> f32 {
    let cell = vec3<i32>(floor(p));
    let f = fract(p);
    let s = f * f * (3.0 - 2.0 * f);
    let a = mix(sunset_random(cell), sunset_random(cell + vec3(1, 0, 0)), s.x);
    let b = mix(sunset_random(cell + vec3(0, 1, 0)), sunset_random(cell + vec3(1, 1, 0)), s.x);
    let c = mix(sunset_random(cell + vec3(0, 0, 1)), sunset_random(cell + vec3(1, 0, 1)), s.x);
    let d = mix(sunset_random(cell + vec3(0, 1, 1)), sunset_random(cell + vec3(1, 1, 1)), s.x);
    return mix(mix(a, b, s.y), mix(c, d, s.y), s.z);
}
fn sunset_cloud(position: vec3<f32>) -> vec2<f32> {
    var p = position;
    var sum = vec2(0.0);
    var amplitude = 0.5;
    var weight = 0.0;
    let octaves = 2u + min(SUNSET_QUALITY, 2u) * 2u;
    // The literal cap is part of the performance contract, even if specialization fails.
    for (var i = 0u; i < 6u; i++) {
        if i >= octaves { break; }
        let n = sunset_noise(p);
        sum += vec2(n, 1.0 - abs(n * 2.0 - 1.0)) * amplitude;
        weight += amplitude;
        // Rotate the domain between octaves to avoid axis-aligned cloud structure.
        p = vec3(p.y + p.z * 0.4, p.z - p.x * 0.4, p.x + p.y * 0.4) * 1.91 + vec3(7.1, 13.7, 3.9);
        amplitude *= 0.49;
    }
    return sum / weight;
}

// A thin spherical slice through a seeded 3-D lattice: no longitude seam or polar pinching.
// Seeds stay inside their cells with enough margin that the star's support never clips.
fn sunset_star_layer(ray: vec3<f32>, scale: f32, seed: i32, footprint: f32, time: f32) -> vec3<f32> {
    let p = ray * scale;
    let cell = vec3<i32>(floor(p)) + vec3(seed);
    let h = sunset_hash(cell);
    let center = vec3(
        f32(h & 1023u), f32((h >> 10u) & 1023u), f32((h >> 20u) & 1023u)
    ) * (0.64 / 1023.0) + vec3(0.18);
    let delta = fract(p) - center;
    let distance_to_star = length(delta);
    let rare = f32(h >> 30u) / 3.0;
    let radius = mix(0.055, 0.105, rare * rare * rare);
    let pixel = max(footprint * scale, 0.0001);
    let core = 1.0 - smoothstep(max(radius - pixel, 0.0), radius + pixel, distance_to_star);
    // Keep subpixel stars from becoming overbright as their filtered footprint grows.
    let coverage = min(1.0, radius * radius / (pixel * pixel));
    let halo = max(0.0, 1.0 - distance_to_star / 0.16);
    let twinkle = 0.88 + 0.12 * sin(time * 0.37 + f32(h & 255u));
    let tint = mix(vec3(0.58, 0.73, 1.0), vec3(1.0, 0.82, 0.71), f32(h & 255u) / 255.0);
    return tint * ((core * coverage * (0.65 + rare * 1.4)) + halo * halo * 0.035) * twinkle;
}

fn sunset_space(ray: vec3<f32>, time: f32) -> vec3<f32> {
    // Pre-normalized constants also avoid a Naga 30 override-folding edge case.
    let normal = vec3(0.511383, 0.641735, -0.571546);
    let across = vec3(-0.745241, 0.0, -0.666795);
    let along = vec3(-0.427905, 0.766926, 0.478247);
    let p = vec3(dot(ray, across), dot(ray, along), dot(ray, normal));
    let drift = vec3(time * 0.0008, -time * 0.0003, 0.0);
    let warp = vec2(sunset_noise(p * 2.6 + drift + vec3(4.7)),
                    sunset_noise(p * 2.6 + drift + vec3(19.3, 2.1, 8.4)));
    let field = sunset_cloud(p * vec3(4.2, 4.2, 6.4) + vec3(warp * 1.7, 0.0) + drift);
    let latitude = p.z + (warp.x - 0.5) * 0.31;
    let envelope = exp(-latitude * latitude * 5.2);
    let cloud = smoothstep(0.27, 0.76, field.x) * envelope;
    let filament = pow(clamp(field.y, 0.0, 1.0), 3.0) * cloud;
    let pink = smoothstep(0.28, 0.72, warp.y + field.x * 0.18);
    let tint = mix(vec3(0.035, 0.12, 0.62), vec3(0.75, 0.025, 0.42), pink);
    let dust = exp(-abs(latitude + (field.x - 0.5) * 0.35) * 29.0)
        * smoothstep(0.26, 0.64, warp.y);
    let emission = (tint * cloud * 1.45 + vec3(0.22, 0.16, 0.37) * filament * filament)
        * (1.0 - dust * 0.86);
    return vec3(0.002, 0.003, 0.012) + vec3(0.006, 0.009, 0.032) * envelope
        + emission * clamp(SUNSET_STRENGTH, 0.0, 2.0);
}

fn sunset_aurora(ray: vec3<f32>, time: f32, footprint: f32) -> vec3<f32> {
    let azimuth = atan2(ray.z, ray.x);
    var glow = vec3(0.0);
    // Three analytic curtains, not an unbounded volumetric ray march. All azimuth
    // frequencies are integers so atan2's branch cut cannot form a visible seam.
    for (var i = 0u; i < 3u; i++) {
        let layer = f32(i);
        let phase = time * 0.035 + layer * 2.1;
        let folds = sin(azimuth * 9.0 + phase + sin(azimuth * 3.0 - phase) * 1.3);
        let base = 0.12 + layer * 0.12 + sin(azimuth * 2.0 + phase) * 0.13 + folds * 0.035;
        let height = ray.y - base;
        let rise = smoothstep(-footprint * 2.0, 0.027 + footprint * 2.0, height);
        let fall = exp(-max(height, 0.0) * (7.0 + layer));
        let rays = 0.35 + 0.65 * pow(0.5 + 0.5 * sin(azimuth * 113.0 + folds * 2.0 + phase), 3.0);
        let curtain = rise * fall * rays;
        let tint = mix(vec3(0.025, 0.65, 0.32), vec3(0.29, 0.055, 0.58),
            smoothstep(0.02, 0.31, height));
        glow += tint * curtain * (0.7 - layer * 0.15);
    }
    return vec3(0.002, 0.007, 0.021) + glow * clamp(SUNSET_STRENGTH, 0.0, 2.0);
}

fn sunset_ringed_planet(ray: vec3<f32>, background: vec3<f32>, footprint: f32, time: f32) -> vec3<f32> {
    // Radius one at distance six: 9.59 degrees apparent radius, world anchored.
    // All fixed directions are pre-normalized; no constant normalize folding.
    let planet_center = vec3(3.0, 3.0, 4.2426407);
    let axis = vec3(0.15003751, 0.97024259, -0.19004752);
    let light = vec3(-0.63142230, 0.35079017, -0.69155776);
    let projection = dot(ray, planet_center);
    let pixel = max(footprint * 6.0, 0.0001);
    // The full annulus (including its largest filter) fits in radius 2.22.
    // Most sky rays cannot hit it: skip all sphere/ring sqrt, division and sine.
    let bound = max(2.24, 1.0 + pixel);
    if projection <= 0.0 || projection * projection < 36.0 - bound * bound {
        return background;
    }
    let discriminant = projection * projection - 35.0;
    let impact = sqrt(max(36.0 - projection * projection, 0.0));
    let sphere_mask = (1.0 - smoothstep(1.0 - pixel, 1.0 + pixel, impact))
        * select(0.0, 1.0, projection > 0.0);
    let sphere_t = projection - sqrt(max(discriminant, 0.0));
    var planet = vec3(0.0);
    if sphere_mask > 0.0 {
        let hit = ray * sphere_t - planet_center;
        let normal = hit / max(length(hit), 0.0001);
        let latitude = dot(normal, axis);
        let flow = sin(latitude * 43.0 + sin(normal.x * 9.0 + normal.z * 5.0) * 0.65 + time * 0.002);
        let bands = 0.5 + 0.5 * flow;
        let pigment = mix(vec3(0.23, 0.16, 0.34), vec3(0.88, 0.62, 0.43), bands * 0.65 + 0.22);
        let daylight = max(dot(normal, light), 0.0);
        planet = pigment * (0.10 + daylight * 1.10);
        let rim = pow(1.0 - max(dot(normal, -ray), 0.0), 3.0);
        planet += vec3(0.12, 0.18, 0.39) * rim * (0.2 + daylight);
    }
    var ring_alpha = 0.0;
    var ring_color = vec3(0.0);
    var ring_t = 100.0;
    let denominator = dot(ray, axis);
    // The forward, finite interval excludes near-parallel intersections before
    // division can magnify their precision error into an unbounded ring radius.
    if abs(denominator) > 0.0001 {
        let t = 2.5545370 / denominator;
        if t > 0.0 && t < 12.0 {
            let relative = ray * t - planet_center;
            let radius = length(relative);
            let ring_pixel = clamp(footprint * t / max(abs(denominator), 0.08), 0.0001, 0.12);
            let annulus = smoothstep(1.23 - ring_pixel, 1.28 + ring_pixel, radius)
                * (1.0 - smoothstep(2.05 - ring_pixel, 2.10 + ring_pixel, radius));
            let gap = smoothstep(1.69 - ring_pixel, 1.73 + ring_pixel, radius)
                * (1.0 - smoothstep(1.79 - ring_pixel, 1.83 + ring_pixel, radius));
            let fine = 1.0 - smoothstep(0.008, 0.035, ring_pixel);
            let grain = 0.67 + sin(radius * 73.0) * 0.15
                + sin(radius * 211.0) * 0.08 * fine;
            let pigment = mix(vec3(0.34, 0.24, 0.47), vec3(0.95, 0.72, 0.60), grain);
            // Test the ray from this ring point toward the light against the sphere.
            let toward_light = dot(relative, light);
            let shadow_disc = toward_light * toward_light - (dot(relative, relative) - 1.0);
            let shadow = select(1.0, 0.16, toward_light < 0.0 && shadow_disc > 0.0);
            ring_color = pigment * shadow * 0.85;
            ring_alpha = annulus * (1.0 - gap * 0.88) * (0.65 + grain * 0.30);
            ring_t = t;
        }
    }
    // Back rings disappear behind the opaque disc; front rings cross its face.
    // Stars are already in background and cannot shine through the solid sphere.
    let opacity = clamp(SUNSET_STRENGTH, 0.0, 1.0);
    var color = mix(background, ring_color, ring_alpha * opacity);
    color = mix(color, planet, sphere_mask * opacity);
    if ring_t < sphere_t && sphere_mask > 0.0 {
        color = mix(color, ring_color, ring_alpha * opacity);
    }
    return color;
}

// Called once from the sky fragment entry, before terrain/hand/UI render passes.
fn sunset_atmosphere(ray: vec3<f32>) -> vec3<f32> {
    // Derivatives must execute before any per-pixel early return.
    let footprint = max(length(dpdx(ray)), length(dpdy(ray)));
    let night = 1.0 - smoothstep(-0.10, 0.15, globals.sun.y);
    let visibility = mix(clamp(SUNSET_DAY_BLEND, 0.0, 1.0), 1.0, night);
    let horizon = smoothstep(-0.12, 0.16, ray.y);
    let blend = visibility * horizon;
    if blend <= 0.0 { return sky_along_ray(ray); }
    let time = globals.misc.y * clamp(SUNSET_SPEED, 0.0, 3.0);
    var color: vec3<f32>;
    if SUNSET_MODE == 1u {
        color = sunset_aurora(ray, time, footprint);
    } else {
        color = sunset_space(ray, time);
    }
    var stars = sunset_star_layer(ray, 113.0, 17, footprint, time);
    if SUNSET_QUALITY > 0u {
        stars += sunset_star_layer(ray, 237.0, 151, footprint, time) * 0.62;
    }
    if SUNSET_QUALITY > 1u {
        stars += sunset_star_layer(ray, 371.0, 401, footprint, time) * 0.28;
    }
    color += stars * clamp(SUNSET_STARS, 0.0, 2.0);
    if SUNSET_MODE == 2u {
        color = sunset_ringed_planet(ray, color, footprint, time);
    }
    // Compress bright cores without HDR alpha conventions or bloom dependencies.
    color = vec3(1.0) - exp(-max(color, vec3(0.0)) * clamp(SUNSET_BRIGHTNESS, 0.0, 2.0));
    // Meet the existing horizon/fog gently; do not recolor geometry or the lower void.
    // Native sky includes disc trigonometry and sunrise fan intersections. Avoid
    // evaluating it over the opaque custom sky, where its contribution is zero.
    if blend >= 1.0 { return color; }
    return mix(sky_along_ray(ray), color, blend);
}
"#;

// Published afresh during HUD construction, before this frame is submitted,
// including disabled and hidden frames. draw_outline runs on the same thread.
// Other renderer entry points use loading_frame(), which has no outline edges.
use std::cell::Cell;

thread_local! {
    static ACTIVE: Cell<bool> = const { Cell::new(false) };
}

pub fn active() -> bool {
    ACTIVE.with(Cell::get)
}

pub fn publish(suppress: bool) {
    ACTIVE.with(|active| active.set(suppress));
}

// Public bridge in horizon_client::hud. The renderer thread publishes one
// small fixed frame at hud_layers HEAD; HUD emission consumes no game locks.

use super::{HudAtlas, HudBatch, Rect, rgba};
use std::cell::Cell;

#[derive(Clone, Copy)]
pub struct Frame {
    rects: [[f32; 4]; 10],
    colors: [u32; 10],
    len: usize,
    crosshair_uv: Option<[f32; 4]>,
}

impl Frame {
    pub const fn empty() -> Self {
        Self { rects: [[0.0; 4]; 10], colors: [0; 10], len: 0, crosshair_uv: None }
    }

    pub fn set_crosshair(&mut self, uv: [f32; 4]) {
        self.crosshair_uv = Some(uv);
    }

    pub fn push(&mut self, rect: [f32; 4], argb: u32) {
        if self.len < self.rects.len() {
            self.rects[self.len] = rect;
            self.colors[self.len] = argb;
            self.len += 1;
        }
    }
}

thread_local! {
    static FRAME: Cell<Frame> = const { Cell::new(Frame::empty()) };
    static ACTIVE: Cell<bool> = const { Cell::new(false) };
    static MARK: Cell<Option<[f32; 4]>> = const { Cell::new(None) };
    static PENDING: Cell<bool> = const { Cell::new(false) };
}

pub fn set_frame(frame: Frame) {
    FRAME.with(|current| current.set(frame));
    MARK.with(|mark| mark.set(frame.crosshair_uv));
    PENDING.with(|pending| pending.set(false));
    ACTIVE.with(|active| active.set(frame.len != 0 && frame.crosshair_uv.is_some()));
}

// The vanilla mark is the white 15x15 sprite at this integer GUI origin.
// UV comparison uses the actual resource atlas. Suppressing zero vertices
// leaves invert_since(start) empty; attack-indicator ranges stay untouched.
pub fn suppress_mark(batch: &HudBatch, x: f32, y: f32, w: f32, h: f32, rect: Rect, color: u32) -> bool {
    if !ACTIVE.with(Cell::get) || w != 15.0 || h != 15.0 || color != u32::MAX
        || x != ((batch.width as i32 - 15) / 2) as f32
        || y != ((batch.height as i32 - 15) / 2) as f32
        || !batch.scale.is_finite() || batch.scale <= 0.0
    {
        return false;
    }
    if MARK.with(Cell::get) != Some([rect.u0, rect.v0, rect.u1, rect.v1]) {
        return false;
    }
    PENDING.with(|pending| pending.set(true));
    true
}

pub fn draw(batch: &mut HudBatch, atlas: &HudAtlas) {
    if !PENDING.with(|pending| pending.replace(false)) {
        return;
    }
    // Later HUD sprite calls take the inactive fast path. Every frame resets
    // both flags before any eligibility gates, including early screen exits.
    ACTIVE.with(|active| active.set(false));
    let frame = FRAME.with(Cell::get);
    for i in 0..frame.len {
        let [x, y, w, h] = frame.rects[i].map(|v| v / batch.scale);
        let [a, r, g, b] = frame.colors[i].to_be_bytes();
        batch.fill_quad(atlas, [[x, y], [x + w, y], [x + w, y + h], [x, y + h]], rgba(r, g, b, a));
    }
}

// Streamer Mode's names, read wherever text is drawn or measured: each name (lower case) and what shows in its place.
// A name is matched as a whole word of name characters (letters, digits and _, all a Minecraft name can hold), any
// case, across the styled pieces a text is made of; the replacement takes the style of the name's first character.
use crate::text::{Span, Style, Text};
use std::cell::Cell;
use std::collections::HashMap;
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};
use std::sync::{Arc, RwLock};

static ON: AtomicBool = AtomicBool::new(false);
// The lengths of the names, a bit each (bit n: a name n characters long).
static LENGTHS: AtomicU32 = AtomicU32::new(0);
static NAMES: RwLock<Option<Arc<HashMap<String, String>>>> = RwLock::new(None);
const LONGEST: usize = 16;

thread_local! {
    // A replaced text being drawn or measured: it is not looked at again.
    static INSIDE: Cell<bool> = const { Cell::new(false) };
}

// The names to hide (None: Streamer Mode off).
pub fn set(names: Option<HashMap<String, String>>) {
    let lengths = names.as_ref().map_or(0, |n| n.keys().filter(|k| k.len() <= LONGEST).fold(0u32, |m, k| m | 1 << k.len()));
    LENGTHS.store(lengths, Ordering::Release);
    ON.store(names.as_ref().is_some_and(|n| !n.is_empty()), Ordering::Release);
    *NAMES.write().unwrap_or_else(|e| e.into_inner()) = names.map(Arc::new);
}

fn names() -> Option<Arc<HashMap<String, String>>> {
    if !ON.load(Ordering::Acquire) || INSIDE.with(Cell::get) {
        return None;
    }
    NAMES.read().unwrap_or_else(|e| e.into_inner()).clone()
}

// Draws or measures a replaced text without looking at it again.
pub fn guarded<R>(f: impl FnOnce() -> R) -> R {
    INSIDE.with(|inside| inside.set(true));
    let out = f();
    INSIDE.with(|inside| inside.set(false));
    out
}

fn name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

// The replacement for the word chars[from..to], if it is a name.
fn lookup<'a>(names: &'a HashMap<String, String>, chars: &[char], from: usize, to: usize) -> Option<&'a str> {
    if to - from > LONGEST {
        return None;
    }
    let mut buf = [0u8; LONGEST];
    for (i, c) in chars[from..to].iter().enumerate() {
        buf[i] = c.to_ascii_lowercase() as u8;
    }
    names.get(std::str::from_utf8(&buf[..to - from]).ok()?).map(String::as_str)
}

// Each name in `chars`: where it starts and ends, and its replacement. A legacy section-sign code (the sign and the
// character after it) is formatting, not part of a word.
fn find<'a>(names: &'a HashMap<String, String>, chars: &[char]) -> Vec<(usize, usize, &'a str)> {
    let mut found = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\u{a7}' {
            i += 2;
            continue;
        }
        if !name_char(chars[i]) {
            i += 1;
            continue;
        }
        let start = i;
        while i < chars.len() && name_char(chars[i]) {
            i += 1;
        }
        if let Some(to) = lookup(names, chars, start, i) {
            found.push((start, i, to));
        }
    }
    found
}

// Whether `chars` (a text's characters in order) hold a word that is a name, without allocating: most text drawn
// or measured each frame holds none and goes no further. A section-sign code does not break a word here (the text is
// resolved before it is replaced), so this may say yes where the full look finds nothing, never no where it would.
fn holds_name(names: &HashMap<String, String>, lengths: u32, chars: impl Iterator<Item = char>) -> bool {
    let mut buf = [0u8; LONGEST];
    let (mut len, mut long, mut code) = (0usize, false, false);
    let word = |buf: &[u8; LONGEST], len: usize, long: bool| {
        !long && len > 0 && lengths & (1 << len) != 0 && std::str::from_utf8(&buf[..len]).is_ok_and(|w| names.contains_key(w))
    };
    for c in chars {
        if code {
            code = false;
        } else if c == '\u{a7}' {
            code = true;
        } else if name_char(c) {
            if len < LONGEST {
                buf[len] = c.to_ascii_lowercase() as u8;
                len += 1;
            } else {
                long = true;
            }
        } else {
            if word(&buf, len, long) {
                return true;
            }
            (len, long) = (0, false);
        }
    }
    word(&buf, len, long)
}

// A text may hold a name (Streamer Mode on, not inside a replaced text already).
fn may_hold(chars: impl Iterator<Item = char>) -> bool {
    if !ON.load(Ordering::Acquire) || INSIDE.with(Cell::get) {
        return false;
    }
    let guard = NAMES.read().unwrap_or_else(|e| e.into_inner());
    guard.as_ref().is_some_and(|names| holds_name(names, LENGTHS.load(Ordering::Acquire), chars))
}

// Plain text with the names replaced, or None when it holds none.
pub fn protect_str(s: &str) -> Option<String> {
    if !may_hold(s.chars()) {
        return None;
    }
    let names = names()?;
    let chars: Vec<char> = s.chars().collect();
    let found = find(&names, &chars);
    if found.is_empty() {
        return None;
    }
    let mut out = String::with_capacity(s.len());
    let mut at = 0;
    for (from, to, with) in found {
        out.extend(&chars[at..from]);
        out.push_str(with);
        at = to;
    }
    out.extend(&chars[at..]);
    Some(out)
}

// A styled text with the names replaced (its § codes resolved first), or None when it holds none.
pub fn protect(text: &Text) -> Option<Text> {
    if !may_hold(text.spans.iter().flat_map(|span| span.text.chars())) {
        return None;
    }
    let names = names()?;
    let text = text.resolved();
    let styled: Vec<(char, &Style)> = text.chars().collect();
    let chars: Vec<char> = styled.iter().map(|&(c, _)| c).collect();
    let found = find(&names, &chars);
    if found.is_empty() {
        return None;
    }
    let mut out = Text::default();
    let mut push = |s: &str, style: &Style| match out.spans.last_mut() {
        Some(last) if last.style == *style => last.text.push_str(s),
        _ => out.spans.push(Span { text: s.to_owned(), style: style.clone() }),
    };
    let mut at = 0;
    let mut one = [0u8; 4];
    for (from, to, with) in found {
        for &(c, style) in &styled[at..from] {
            push(c.encode_utf8(&mut one), style);
        }
        push(with, styled[from].1);
        at = to;
    }
    for &(c, style) in &styled[at..] {
        push(c.encode_utf8(&mut one), style);
    }
    Some(out)
}

