mod tests {
    use super::*;

    fn map(pairs: &[(&str, &str)]) -> HashMap<String, String> {
        pairs.iter().map(|(a, b)| (a.to_string(), b.to_string())).collect()
    }

    #[test]
    fn the_quick_look_finds_every_name_the_full_one_does() {
        let names = map(&[("vstxx", "You"), ("notch", "Player 1")]);
        let holds = |s: &str| holds_name(&names, 1 << 5, s.chars());
        for s in ["<vstxx> hi", "NOTCH", "kill by Notch.", "x notch y", "\u{a7}cvstxx\u{a7}r", "\u{a7}aNotch"] {
            assert!(!find(&names, &s.chars().filter(|&c| c != '\u{a7}').collect::<Vec<_>>()).is_empty() || s.contains('\u{a7}'));
            assert!(holds(s), "{s}");
        }
        assert!(holds("No\u{a7}ltch"), "a code inside a word does not split it");
        for s in ["notches", "vstx", "hello there", "", "a_very_long_word_with_notch_inside"] {
            assert!(!holds(s), "{s}");
        }
    }

    #[test]
    fn names_are_whole_words_in_any_case() {
        let names = map(&[("vstxx", "You"), ("notch", "Player 1")]);
        let chars = |s: &str| s.chars().collect::<Vec<_>>();
        let f = |s: &str| find(&names, &chars(s)).into_iter().map(|(a, b, w)| (a, b, w.to_owned())).collect::<Vec<_>>();
        assert_eq!(f("<VSTXX> hi Notch!"), vec![(1, 6, "You".into()), (11, 16, "Player 1".into())]);
        assert!(f("vstxx2 notched xvstxx").is_empty(), "a longer word is another name");
        assert_eq!(f("[VIP] vstxx's"), vec![(6, 11, "You".into())]);
        assert!(f("aaaaaaaaaaaaaaaaaaaaaaa").is_empty());
        assert_eq!(f("\u{a7}cvstxx\u{a7}r"), vec![(2, 7, "You".into())]);
    }

    #[test]
    fn styled_names_keep_the_first_characters_style_and_split_spans_are_caught() {
        set(Some(map(&[("vstxx", "You")])));
        let red = Style::color(0xFF0000);
        let mut t = Text::default();
        t.spans.push(Span { text: "<vs".into(), style: Style::default() });
        t.spans.push(Span { text: "txx".into(), style: red.clone() });
        t.spans.push(Span { text: "> hi".into(), style: Style::default() });
        let out = protect(&t).expect("a name split over two spans");
        assert_eq!(out.plain(), "<You> hi");
        assert_eq!(protect_str("\u{a7}avstxx joined").as_deref(), Some("\u{a7}aYou joined"), "a colour code is not part of the name");
        assert_eq!(protect_str("VSTXX joined").as_deref(), Some("You joined"));
        assert_eq!(protect_str("nobody here"), None);
        assert_eq!(guarded(|| protect_str("vstxx")), None, "a replaced text is not looked at again");
        set(None);
        assert_eq!(protect_str("vstxx"), None);
    }
}

// The game's own bars, as HUD's Mount HUD and food settings ask (set by Sunset each tick): the food row also while
// riding, the mount's hearts moved up over it, the XP bar instead of a jump bar that isn't charging; the held
// food's hunger and saturation drawn on the row, the saturation you have, and the exhaustion under it.
use super::{Blend, GuiDraw, HealthHud, HealthInputs, experience_colored as experience_layout};
use std::borrow::Cow;
use std::cell::Cell;
use std::ops::ControlFlow;
use std::sync::Mutex;

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Bars {
    // Mount HUD on: the food row and the XP bar while riding.
    pub mount: bool,
    // Riding with Mount HUD on, no jump charging and no waypoints: the XP bar over the jump bar.
    pub mount_xp: bool,
    // How far the mount's hearts move up: the food row, and the air bubbles when they show.
    pub raise: i32,
    // Food and saturation once the held food is eaten.
    pub preview: Option<(i32, f32)>,
    pub saturation: bool,
    // Exhaustion, from 0 to 4 (a point of saturation or food goes at 4).
    pub exhaustion: Option<f32>,
}

pub static BARS: Mutex<Bars> = Mutex::new(Bars { mount: false, mount_xp: false, raise: 0, preview: None, saturation: false, exhaustion: None });

thread_local! {
    static INSIDE: Cell<bool> = const { Cell::new(false) };
}

pub fn bars() -> Bars {
    *BARS.lock().unwrap_or_else(|e| e.into_inner())
}

// The food icons' spots: from the right end of the row, (x, y) of the n-th.
fn icon(w: i32, h: i32, n: i32) -> (i32, i32) {
    (w / 2 + 91 - n * 8 - 9, h - 39)
}

fn sprite(name: &'static str, (x, y): (i32, i32), color: u32) -> GuiDraw {
    GuiDraw::Sprite { sprite: Cow::Borrowed(name), x, y, w: 9, h: 9, region: None, color, blend: Blend::Textured }
}

fn fill(x0: i32, y0: i32, x1: i32, y1: i32, color: u32) -> GuiDraw {
    GuiDraw::Fill { x0, y0, x1, y1, color }
}

// A gold frame round the n-th icon for `points` (0 to 2) of saturation: a whole frame for two, the right half for one.
fn frame(out: &mut Vec<GuiDraw>, (x, y): (i32, i32), points: f32, color: u32) {
    if points <= 0.0 {
        return;
    }
    let left = if points >= 2.0 { x } else { x + 9 - (9.0 * points / 2.0).ceil() as i32 };
    out.push(fill(left, y, x + 9, y + 1, color));
    out.push(fill(left, y + 8, x + 9, y + 9, color));
    out.push(fill(x + 8, y + 1, x + 9, y + 8, color));
    if points >= 2.0 {
        out.push(fill(x, y + 1, x + 1, y + 8, color));
    }
}

// HealthHud::layout: the game's own layout, with the food row while riding and the food overlays.
pub fn layout(hud: &mut HealthHud, i: &HealthInputs, w: i32, h: i32) -> ControlFlow<Vec<GuiDraw>> {
    if INSIDE.with(Cell::get) {
        return ControlFlow::Continue(());
    }
    let b = bars();
    let riding = b.mount && i.vehicle_hearts > 0;
    let food_row = i.vehicle_hearts == 0 || riding;
    let overlays = food_row && (b.preview.is_some() || b.saturation || b.exhaustion.is_some());
    if !riding && !overlays {
        return ControlFlow::Continue(());
    }
    let own = HealthInputs { vehicle_hearts: if riding { 0 } else { i.vehicle_hearts }, ..*i };
    let mut out = Vec::new();
    // Exhaustion under the icons, from the right end.
    if let Some(e) = b.exhaustion.filter(|_| food_row) {
        let width = (81.0 * (e / 4.0).clamp(0.0, 1.0)).round() as i32;
        let (right, y) = (w / 2 + 91, h - 39);
        if width > 0 {
            out.push(fill(right - width, y, right, y + 9, 0x60FF_FFFF));
        }
    }
    INSIDE.with(|c| c.set(true));
    // The game lays the air bubbles out here too, over the food row it draws for `own`; the mount's hearts go up over
    // both (`raise`).
    out.extend(hud.layout(&own, w, h));
    INSIDE.with(|c| c.set(false));
    if !food_row {
        return ControlFlow::Break(out);
    }
    // Flashing, as the game's own blink: half a second each way.
    let pulse = ((i.millis % 1000) as f32 / 1000.0 * std::f32::consts::TAU).sin() * 0.5 + 0.5;
    let alpha = |a: f32| (((0.25 + 0.6 * a) * 255.0) as u32) << 24;
    if b.saturation {
        for n in 0..10 {
            frame(&mut out, icon(w, h, n), (i.saturation - 2.0 * n as f32).min(2.0), 0xFFFF_C800);
        }
    }
    if let Some((food, saturation)) = b.preview {
        let full = if i.hunger { "hud/food_full_hunger" } else { "hud/food_full" };
        let half = if i.hunger { "hud/food_half_hunger" } else { "hud/food_half" };
        for n in 0..10 {
            let point = n * 2 + 1;
            if point >= i.food && point < food {
                out.push(sprite(full, icon(w, h, n), alpha(pulse) | 0xFF_FFFF));
            } else if point == food && point > i.food {
                out.push(sprite(half, icon(w, h, n), alpha(pulse) | 0xFF_FFFF));
            }
            if b.saturation {
                let now = (i.saturation - 2.0 * n as f32).clamp(0.0, 2.0);
                let then = (saturation - 2.0 * n as f32).min(2.0);
                if then > now {
                    frame(&mut out, icon(w, h, n), then, alpha(pulse) | 0xFF_C800);
                }
            }
        }
    }
    ControlFlow::Break(out)
}

// vehicle_health: the mount's hearts moved up over the food row.
pub fn raise(mut draws: Vec<GuiDraw>) -> Vec<GuiDraw> {
    let b = bars();
    if b.mount && b.raise != 0 {
        for d in &mut draws {
            if let GuiDraw::Sprite { y, .. } = d {
                *y -= b.raise;
            }
        }
    }
    draws
}

// experience_colored: with Mount HUD's XP bar, the bar the game leaves out for the jump bar (in a resource pack's
// level number colours, as the game's own).
pub fn experience(
    colours: [Option<u32>; 2],
    w: i32,
    h: i32,
    progress: f32,
    level: i32,
    bar: bool,
    width: &dyn Fn(&str) -> i32,
) -> ControlFlow<Vec<GuiDraw>> {
    if bar || INSIDE.with(Cell::get) || !bars().mount_xp {
        return ControlFlow::Continue(());
    }
    INSIDE.with(|c| c.set(true));
    let draws = experience_layout(colours, w, h, progress, level, true, width);
    INSIDE.with(|c| c.set(false));
    ControlFlow::Break(draws)
}

// Where the scoreboard sidebar would draw, and how far to move it: shared between the game crate (which frames it for
// the chat layout editor and sets the offset from where it was dragged) and the render crate's sidebar draw (which
// measures the natural box and applies the offset). Written anew for Sunset.
use crate::hud_layout::GuiDraw;
use std::sync::atomic::{AtomicBool, AtomicI32, Ordering::Relaxed};

// The natural box of the sidebar (GUI pixels), as the last draw measured it.
static NAT_X: AtomicI32 = AtomicI32::new(0);
static NAT_Y: AtomicI32 = AtomicI32::new(0);
static NAT_W: AtomicI32 = AtomicI32::new(0);
static NAT_H: AtomicI32 = AtomicI32::new(0);
// How far the HUD wants it moved from that box.
static OFF_X: AtomicI32 = AtomicI32::new(0);
static OFF_Y: AtomicI32 = AtomicI32::new(0);
static CUSTOM: AtomicBool = AtomicBool::new(false);
// It drew this frame (cleared as the HUD reads it, so a sidebar that stops showing stops being framed).
static SHOWN: AtomicBool = AtomicBool::new(false);

// The sidebar just built `draws` at their natural place: record the box they cover, then slide them if a custom place
// was set. Called from the sidebar's RETURN hook.
pub fn apply(draws: &mut [GuiDraw]) {
    let (mut x0, mut y0, mut x1, mut y1) = (i32::MAX, i32::MAX, i32::MIN, i32::MIN);
    for d in draws.iter() {
        let (ax, ay, bx, by) = match d {
            GuiDraw::Fill { x0, y0, x1, y1, .. } => (*x0, *y0, *x1, *y1),
            GuiDraw::Text { x, y, .. } => (*x, *y, *x, *y + 9),
            _ => continue,
        };
        x0 = x0.min(ax);
        y0 = y0.min(ay);
        x1 = x1.max(bx);
        y1 = y1.max(by);
    }
    if x0 == i32::MAX {
        return;
    }
    NAT_X.store(x0, Relaxed);
    NAT_Y.store(y0, Relaxed);
    NAT_W.store(x1 - x0, Relaxed);
    NAT_H.store(y1 - y0, Relaxed);
    SHOWN.store(true, Relaxed);
    if CUSTOM.load(Relaxed) {
        let (dx, dy) = (OFF_X.load(Relaxed), OFF_Y.load(Relaxed));
        if dx != 0 || dy != 0 {
            for d in draws.iter_mut() {
                shift(d, dx, dy);
            }
        }
    }
}

// Move one draw by (dx, dy): every coordinate it carries.
fn shift(d: &mut GuiDraw, dx: i32, dy: i32) {
    match d {
        GuiDraw::Fill { x0, y0, x1, y1, .. } => {
            *x0 += dx;
            *x1 += dx;
            *y0 += dy;
            *y1 += dy;
        }
        GuiDraw::Text { x, y, .. }
        | GuiDraw::Sprite { x, y, .. }
        | GuiDraw::AtlasSprite { x, y, .. }
        | GuiDraw::Blit { x, y, .. }
        | GuiDraw::Item { x, y, .. } => {
            *x += dx;
            *y += dy;
        }
        GuiDraw::Push(_) | GuiDraw::Pop => {}
    }
}

// The natural box of the sidebar this frame (x, y, w, h in GUI pixels), if it drew; cleared as it is read.
pub fn natural() -> Option<(i32, i32, i32, i32)> {
    SHOWN
        .swap(false, Relaxed)
        .then(|| (NAT_X.load(Relaxed), NAT_Y.load(Relaxed), NAT_W.load(Relaxed), NAT_H.load(Relaxed)))
}

// How far to move the sidebar from its natural place (0, 0 to leave it): set by the HUD from where it was dragged.
pub fn set_offset(custom: bool, dx: i32, dy: i32) {
    CUSTOM.store(custom, Relaxed);
    OFF_X.store(dx, Relaxed);
    OFF_Y.store(dy, Relaxed);
}

// Clear Water's switches, read by the mesher's hook (on its worker threads)
// and set by the game. Every water sprite is laid out again at each lower
// opacity next to the block sprites, so fainter water is only another layer on
// its vertices: no texture reload, the world is just rebuilt.
use std::sync::RwLock;
use std::sync::atomic::{AtomicU32, Ordering::Relaxed};

// Opacity steps: copies at 0/20, 1/20 ... 19/20 of the water's own alpha; STEPS is the water as it is.
pub const STEPS: usize = 20;
pub const SPRITES: [&str; 3] = ["minecraft:block/water_still", "minecraft:block/water_flow", "minecraft:block/water_overlay"];
pub static LEVEL: AtomicU32 = AtomicU32::new(STEPS as u32);
// How far the water's colour goes towards its brightest channel, in hundredths.
pub static TINT: AtomicU32 = AtomicU32::new(0);
// Each water sprite's own layer and its copies' layers, faintest first.
static LAYERS: RwLock<[(u32, [u32; STEPS]); 3]> = RwLock::new([(u32::MAX, [0; STEPS]); 3]);

pub fn on() -> bool {
    (LEVEL.load(Relaxed) as usize) < STEPS || TINT.load(Relaxed) > 0
}
pub fn set_layers(sprite: usize, own: u32, copies: [u32; STEPS]) {
    if let Ok(mut l) = LAYERS.write() {
        l[sprite] = (own, copies);
    }
}
// A sprite's frames with every pixel's alpha at step/STEPS of its own.
pub fn faded(frames: &[Vec<u8>], step: usize) -> Vec<Vec<u8>> {
    let scale = |a: u8| (u32::from(a) * step as u32 / STEPS as u32) as u8;
    frames.iter().map(|f| f.chunks_exact(4).flat_map(|p| [p[0], p[1], p[2], scale(p[3])]).collect()).collect()
}
// A section's water drawn with the copy at the chosen opacity and its tint lightened.
pub fn clear(mesh: &mut super::SectionMesh) {
    let (level, tint) = (LEVEL.load(Relaxed) as usize, TINT.load(Relaxed).min(100));
    let Ok(layers) = LAYERS.read() else {
        return;
    };
    for v in &mut mesh.translucent {
        let own = u32::from(v.layer & !super::OPAQUE_LAYER);
        let Some((_, copies)) = layers.iter().find(|(l, _)| *l == own) else {
            continue;
        };
        if level < STEPS {
            v.layer = v.layer & super::OPAQUE_LAYER | copies[level] as u16;
        }
        if tint > 0 {
            let rgb = [0, 8, 16].map(|s| v.color >> s & 255);
            let top = rgb.into_iter().max().unwrap_or(0);
            let lit = rgb.map(|c| c + (top - c) * tint / 100);
            v.color = v.color & 0xFF00_0000 | lit[0] | lit[1] << 8 | lit[2] << 16;
        }
    }
    // The renderer reads the layers a mesh uses from this list, not from its vertices.
    if level < STEPS {
        for (_, copies) in layers.iter() {
            if mesh.translucent.iter().any(|v| u32::from(v.layer & !super::OPAQUE_LAYER) == copies[level]) {
                mesh.note_sprite_layer(copies[level] as u16);
            }
        }
        mesh.finish_sprite_layers();
    }
}

// Xray's switches, read by the mesher's hooks (on its worker threads) and set
// by the game. While a thread builds a section mesh, blocks that are not on
// the list (or at a remembered place) read as air.
use std::cell::Cell;
use std::collections::HashSet;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{LazyLock, RwLock};

pub static ON: AtomicBool = AtomicBool::new(false);
pub static VISIBLE: LazyLock<RwLock<HashSet<u32>>> = LazyLock::new(|| RwLock::new(HashSet::new()));
// Blocks shown wherever they are, whatever they are: the ones the player placed (Show placed blocks).
pub static PLACED: LazyLock<RwLock<HashSet<[i32; 3]>>> = LazyLock::new(|| RwLock::new(HashSet::new()));
static ANY_PLACED: AtomicBool = AtomicBool::new(false);
thread_local! {
    pub static MESHING: Cell<bool> = const { Cell::new(false) };
    // The lowest corner of the section being meshed, in blocks.
    static ORIGIN: Cell<[i32; 3]> = const { Cell::new([0; 3]) };
}
pub fn meshing() -> bool {
    MESHING.with(Cell::get)
}
pub fn set_meshing(v: bool) {
    MESHING.with(|b| b.set(v));
}
pub fn set_origin(at: [i32; 3]) {
    ORIGIN.with(|o| o.set(at));
}
pub fn set_placed(at: HashSet<[i32; 3]>) {
    ANY_PLACED.store(!at.is_empty(), Ordering::Relaxed);
    if let Ok(mut set) = PLACED.write() {
        *set = at;
    }
}
fn placed(at: [i32; 3]) -> bool {
    ANY_PLACED.load(Ordering::Relaxed) && PLACED.read().is_ok_and(|set| set.contains(&at))
}
// One block state as the mesh builder sees it, at a place in the world.
pub fn filter(v: u32, at: [i32; 3]) -> u32 {
    if v == 0 || !ON.load(Ordering::Relaxed) || !meshing() {
        return v;
    }
    match VISIBLE.read() {
        Ok(set) if !set.contains(&v) && !placed(at) => 0,
        _ => v,
    }
}
// A whole section's states (the one being meshed).
pub fn filter_all(out: &mut [u32; 4096]) {
    if !ON.load(Ordering::Relaxed) || !meshing() {
        return;
    }
    let [x0, y0, z0] = ORIGIN.with(Cell::get);
    let any = ANY_PLACED.load(Ordering::Relaxed);
    let (Ok(set), Ok(places)) = (VISIBLE.read(), PLACED.read()) else {
        return;
    };
    for (i, v) in out.iter_mut().enumerate() {
        let (x, y, z) = (i as i32 & 15, i as i32 >> 8, i as i32 >> 4 & 15);
        if *v != 0 && !set.contains(v) && !(any && places.contains(&[x0 + x, y0 + y, z0 + z])) {
            *v = 0;
        }
    }
}

// Options > Mods' rows are `ModList::installed`, and the screen keeps indices into them: the open
// native mod pages on its stack and the native key waiting to be bound. A row removed while the
// screen may be open (Sunset's, after Panic) closes what pointed at it and moves the later ones up,
// so no page or key binding is left showing or changing another mod.
use super::{OptionsUi, Page};

pub fn removed(ui: &mut OptionsUi, row: usize) {
    if let Some(at) = ui.stack.iter().position(|p| *p == Page::NativeMod(row)) {
        // Back to the list the page was opened from; a page opened on its own leaves the list.
        ui.stack.truncate(at);
        if ui.stack.last() != Some(&Page::Mods) {
            ui.stack.push(Page::Mods);
        }
        ui.scroll = 0.0;
        ui.scrollbar_drag_y = None;
    }
    for page in &mut ui.stack {
        if let Page::NativeMod(i) = page
            && *i > row
        {
            *i -= 1;
        }
    }
    match ui.selected_native_key {
        Some((i, _)) if i == row => {
            ui.selected_native_key = None;
            if ui.selected_key == Some(super::NATIVE_KEY) {
                ui.selected_key = None;
            }
        }
        Some((i, k)) if i > row => ui.selected_native_key = Some((i - 1, k)),
        _ => {}
    }
    // Keyboard and pad focus name widgets of the page as it was drawn.
    if ui.page() == Page::Mods {
        ui.focus = None;
        ui.focus_from_keyboard = false;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_removed_row_closes_its_page_and_moves_the_later_ones_up() {
        let mut ui = OptionsUi::default();
        ui.stack = vec![Page::Main, Page::Mods, Page::NativeMod(2)];
        ui.selected_key = Some(super::super::NATIVE_KEY);
        ui.selected_native_key = Some((2, 1));
        removed(&mut ui, 2);
        assert_eq!(ui.stack, [Page::Main, Page::Mods]);
        assert_eq!((ui.selected_key, ui.selected_native_key), (None, None));

        ui.stack = vec![Page::Main, Page::Mods, Page::NativeMod(3)];
        ui.selected_key = Some(super::super::NATIVE_KEY);
        ui.selected_native_key = Some((3, 0));
        removed(&mut ui, 1);
        assert_eq!(ui.stack, [Page::Main, Page::Mods, Page::NativeMod(2)]);
        assert_eq!(ui.selected_native_key, Some((2, 0)));
        assert!(ui.selected_key.is_some());

        // Opened straight on the page (`open_at`): the list takes its place.
        ui.stack = vec![Page::NativeMod(0)];
        removed(&mut ui, 0);
        assert_eq!(ui.stack, [Page::Mods]);

        // An earlier row's page is left alone.
        ui.stack = vec![Page::Main, Page::Mods, Page::NativeMod(0)];
        removed(&mut ui, 4);
        assert_eq!(ui.stack, [Page::Main, Page::Mods, Page::NativeMod(0)]);
    }
}

// No Render's particle switches, read where particles are made (so a hidden one costs no work) and set by the game:
// every particle hidden, or the types listed.
use super::ParticleType;
use std::sync::RwLock;
use std::sync::atomic::{AtomicBool, Ordering};

static ALL: AtomicBool = AtomicBool::new(false);
static ANY: AtomicBool = AtomicBool::new(false);
static HIDDEN: RwLock<Vec<ParticleType>> = RwLock::new(Vec::new());

pub fn hidden(ty: ParticleType) -> bool {
    ALL.load(Ordering::Relaxed) || ANY.load(Ordering::Relaxed) && HIDDEN.read().is_ok_and(|h| h.contains(&ty))
}

// All hidden, or the types a list names (`flame, minecraft:explosion`).
pub fn set(all: bool, list: &str) {
    let types: Vec<ParticleType> = list.split(',').filter_map(|n| ParticleType::from_name(n.trim())).collect();
    ALL.store(all, Ordering::Relaxed);
    ANY.store(!types.is_empty(), Ordering::Relaxed);
    if let Ok(mut h) = HIDDEN.write() {
        *h = types;
    }
}

// Every particle type's name, for the picker.
pub fn names() -> Vec<&'static str> {
    ParticleType::ALL.iter().map(|t| t.name()).collect()
}

// No Render's overlay switches, read by the screen overlay hook.
use std::cell::Cell;
use std::sync::atomic::AtomicBool;

pub static NO_FIRE: AtomicBool = AtomicBool::new(false);
pub static NO_LIQUID: AtomicBool = AtomicBool::new(false);
pub static NO_WALL: AtomicBool = AtomicBool::new(false);
pub static NO_GUI: AtomicBool = AtomicBool::new(false);
pub static NO_MENU: AtomicBool = AtomicBool::new(false);
// ClickGUI's Inventory blur: your inventory blurs the world behind it.
pub static INVENTORY_BLUR: AtomicBool = AtomicBool::new(false);
// No Render's Hide hurt cam: the view doesn't tilt when you are hurt (or die).
pub static NO_HURT: AtomicBool = AtomicBool::new(false);
thread_local! {
    pub static BUSY: Cell<bool> = const { Cell::new(false) };
