    if text.chars().count() > 256 {
        return Err("A chat message takes 256 characters at most (servers kick longer ones).".to_owned());
    }
    if game.remote.is_none() {
        return Err("Not connected: chat in a world only.".to_owned());
    }
    game.send_chat(text);
