#[derive(Default)]
struct Cs {
    on: HashSet<String>,
    surround_timer: u32,
    trap_delay: u32,
    trap_placed: bool,
    trap_positions: Vec<[i32; 3]>,
    auto_trap_target: Option<u32>,
    auto_trap_timer: u32,
    auto_trap_placed: bool,
    web_target: Option<u32>,
    // Only when falling: the player falling, and the webs put under them in this fall.
    web_fall: Option<(u32, u32)>,
    // Offhand: ticks since its last move, and whether its warning was said.
    offhand_ticks: u32,
    offhand_warned: bool,
    exp_repairing: Option<usize>,
    aim_before: [f32; 2],
    aim_frame: Option<Instant>,
    aim_target: Option<super::sunset_antibot::Token>,
    aim_last: [f64; 2],
}

static CS: Mutex<Option<Cs>> = Mutex::new(None);

fn cs<R>(f: impl FnOnce(&mut Cs) -> R) -> R {
    let mut g = CS.lock().unwrap_or_else(|e| e.into_inner());
    f(g.get_or_insert_with(Cs::default))
}

// True on the tick a module turns on.
fn activated(name: &str, on: bool) -> bool {
    cs(|c| {
        if on {
            c.on.insert(name.to_owned())
        } else {
            c.on.remove(name);
            false
        }
    })
}

pub(super) fn tick(game: &mut Game<'_>, mods: &[Module]) {
    show_clear();
    let get = |n: &str| mods.iter().find(|m| m.name == n);
    for name in ["Surround", "Self Trap", "Auto Trap", "Self Web", "Auto Web", "Auto EXP"] {
        let Some(m) = get(name).filter(|m| m.on) else {
            activated(name, false);
            continue;
        };
        // Activation waits for the world: a module turned on from
        // the chat box starts the tick after.
        if !in_world(game) {
            continue;
        }
        let just = activated(name, true);
        match name {
            "Surround" => surround(game, m, just),
            "Self Trap" => self_trap(game, m, just),
            "Auto Trap" => auto_trap(game, m, just),
            "Self Web" => self_web(game, m),
            "Auto Web" => auto_web(game, m),
            _ => auto_exp(game, m),
        }
    }
}

fn blocks_slot(game: &Game<'_>, list: &str) -> Option<usize> {
    find_held(game, |n| listed(list, n))
}

// ---- Surround

fn surround(game: &mut Game<'_>, m: &Module, just: bool) {
    if just && m.p("Center") == "On activate" {
        center_player(game);
    }
    let delay = m.n("Delay (ticks)") as u32;
    let waited = cs(|c| {
        let t = c.surround_timer;
        c.surround_timer += 1;
        t
    });
    if waited < delay {
        return;
    }
    let Some(p) = game.player.as_ref() else {
        return;
    };
    if m.b("Toggle on Y change") && (game.previous_position.y - p.position.y).abs() > 1e-9 {
        toggle_off(game, "Surround");
        return;
    }
    if m.b("Only on ground") && !p.ground.on_ground {
        return;
    }
    let Some(slot) = blocks_slot(game, m.t("Blocks")) else {
        return;
    };
    if m.p("Center") == "Always" {
        center_player(game);
    }
    let Some(at) = block_pos(game) else {
        return;
    };
    let (per_tick, rotate) = (m.n("Blocks per tick") as u32, m.b("Rotate"));
    let mut placed = 0;
    let mut complete = true;
    let put = |game: &mut Game<'_>, p: [i32; 3], placed: &mut u32| -> bool {
        show(p, 0x40FF_5050);
        place_block(game, p, slot, rotate, true) && {
            *placed += 1;
            *placed >= per_tick
        }
    };
    'sides: for d in HORIZONTAL {
        let p = [at[0] + d[0], at[1], at[2] + d[2]];
        if !m.b("Air place") && !has_support(game, p) && replaceable(game, p) {
            let below = [p[0], p[1] - 1, p[2]];
            if put(game, below, &mut placed) {
                break 'sides;
            }
            if replaceable(game, below) {
                complete = false;
            }
        }
        if put(game, p, &mut placed) {
            break 'sides;
        }
        if replaceable(game, p) {
            complete = false;
        }
    }
    if m.b("Double height") && complete {
        for d in HORIZONTAL {
            let p = [at[0] + d[0], at[1] + 1, at[2] + d[2]];
            if put(game, p, &mut placed) {
                break;
            }
            if replaceable(game, p) {
                complete = false;
            }
        }
    }
    cs(|c| c.surround_timer = 0);
    // Complete once every block is in the world: one sent this tick isn't yet.
    if complete && placed == 0 && m.b("Toggle on complete") {
        toggle_off(game, "Surround");
        return;
    }
    if !complete && m.p("Center") == "Incomplete" {
        center_player(game);
    }
}

// ---- Self Trap

fn self_trap(game: &mut Game<'_>, m: &Module, just: bool) {
    if just {
        cs(|c| {
            c.trap_positions.clear();
            c.trap_delay = 0;
            c.trap_placed = false;
        });
        if m.b("Center") {
            center_player(game);
        }
    }
    let slot = blocks_slot(game, m.t("Blocks"));
    let (placed, empty) = cs(|c| (c.trap_placed, c.trap_positions.is_empty()));
    if m.b("Turn off") && ((placed && empty) || slot.is_none()) {
        if slot.is_none() {
            report(game, "No Self Trap blocks in your hotbar or offhand.");
        }
        toggle_off(game, "Self Trap");
        return;
    }
    let Some(slot) = slot else {
        cs(|c| c.trap_positions.clear());
        return;
    };
    let Some(at) = feet_block(game) else {
        return;
    };
    let mut want: Vec<[i32; 3]> = Vec::new();
    let sides = |y: i32| HORIZONTAL.iter().map(move |d| [d[0], y, d[2]]);
    match m.p("Top mode") {
        "Full" => {
            want.push([0, 2, 0]);
            want.extend(sides(1));
        }
        "Top" => want.push([0, 2, 0]),
        "Anti face place" => want.extend(sides(1)),
        _ => {}
    }
    if m.p("Bottom mode") == "Single" {
        want.push([0, -1, 0]);
    }
    let positions: Vec<[i32; 3]> = want
        .into_iter()
        .map(|d| [at[0] + d[0], at[1] + d[1], at[2] + d[2]])
        .filter(|&p| can_place(game, p, true))
        .collect();
    for &p in &positions {
        show(p, 0x40FF_5050);
    }
    let delay = m.n("Place delay") as u32;
    let go = cs(|c| {
        c.trap_positions = positions.clone();
        let go = c.trap_delay >= delay && !positions.is_empty();
        if !go {
            c.trap_delay += 1;
        }
        go
    });
    if go {
        let p = *positions.last().unwrap_or(&at);
        if place_block(game, p, slot, m.b("Rotate"), true) {
            cs(|c| {
                c.trap_positions.retain(|x| *x != p);
                c.trap_placed = true;
            });
        }
        cs(|c| c.trap_delay = 0);
    }
}

// ---- Auto Trap

fn target_by_id(game: &Game<'_>, id: u32) -> Option<Target> {
    other_players(game).into_iter().find(|t| t.id == id)
}

fn bad_target(game: &Game<'_>, t: &Option<Target>, range: f64) -> bool {
    match (t, game.eye_position()) {
        (Some(t), Some(eye)) => t.health <= 0.0 || dist(eye, t.pos) > range,
        _ => true,
    }
}

fn auto_trap(game: &mut Game<'_>, m: &Module, just: bool) {
    if just {
        cs(|c| {
            c.auto_trap_target = None;
            c.auto_trap_timer = 0;
            c.auto_trap_placed = false;
        });
    }
    let target_id = cs(|c| c.auto_trap_target);
    let Some(slot) = blocks_slot(game, m.t("Blocks")) else {
        return;
    };
    let range = m.n("Target range");
    let mut target = target_id.and_then(|id| target_by_id(game, id));
    if bad_target(game, &target, range) {
        target = player_target(game, range, m.p("Priority"));
        cs(|c| c.auto_trap_target = target.as_ref().map(|t| t.id));
        if target.is_none() {
            // Everything placed and nobody left to trap.
            if m.b("Self toggle") && cs(|c| std::mem::take(&mut c.auto_trap_placed)) {
                toggle_off(game, "Auto Trap");
            }
            return;
        }
    }
    let Some(t) = target else {
        return;
    };
    let (place_range, walls) = (m.n("Place range"), m.n("Walls range"));
    let eps = 1e-5;
    let y = t.lo[1].floor() as i32;
    let mut corners: Vec<[i32; 2]> = vec![
        [t.lo[0].floor() as i32, t.lo[2].floor() as i32],
        [t.lo[0].floor() as i32, (t.hi[2] - eps).floor() as i32],
        [(t.hi[0] - eps).floor() as i32, t.lo[2].floor() as i32],
        [(t.hi[0] - eps).floor() as i32, (t.hi[2] - eps).floor() as i32],
    ];
    corners.dedup();
    let mut positions: Vec<[i32; 3]> = Vec::new();
    let mut add = |game: &Game<'_>, p: [i32; 3]| {
        if !positions.contains(&p) && can_place(game, p, true) && in_reach(game, p, place_range, walls) {
            positions.push(p);
        }
    };
    for [x, z] in corners {
        let at = |dx: i32, dy: i32, dz: i32| [x + dx, y + dy, z + dz];
        match m.p("Top blocks") {
            "Full" => {
                for d in [at(0, 2, 0), at(1, 1, 0), at(-1, 1, 0), at(0, 1, 1), at(0, 1, -1)] {
                    add(game, d);
                }
            }
            "Face" => {
                for d in [at(1, 1, 0), at(-1, 1, 0), at(0, 1, 1), at(0, 1, -1)] {
                    add(game, d);
                }
            }
            "Top" => add(game, at(0, 2, 0)),
            _ => {}
        }
        match m.p("Bottom blocks") {
            "Platform" => {
                for d in [at(0, -1, 0), at(1, -1, 0), at(-1, -1, 0), at(0, -1, 1), at(0, -1, -1)] {
                    add(game, d);
                }
            }
            "Full" => {
                for d in [at(0, -1, 0), at(1, 0, 0), at(-1, 0, 0), at(0, 0, -1), at(0, 0, 1)] {
                    add(game, d);
                }
            }
            "Single" => add(game, at(0, -1, 0)),
            _ => {}
        }
    }
    // The furthest first.
    if let Some(me) = player_pos(game) {
        positions.sort_by(|a, b| dist(me, center_of(*b)).total_cmp(&dist(me, center_of(*a))));
    }
    for &p in &positions {
        show(p, 0x40FF_5050);
    }
    if m.b("Self toggle") && cs(|c| c.auto_trap_placed) && positions.is_empty() {
        cs(|c| c.auto_trap_placed = false);
        toggle_off(game, "Auto Trap");
        return;
    }
    let delay = m.n("Place delay") as u32;
    let ready = cs(|c| {
        if c.auto_trap_timer >= delay && !positions.is_empty() {
            c.auto_trap_timer = 0;
            true
        } else {
            c.auto_trap_timer += 1;
            false
        }
    });
    if ready {
        let mut count = 0;
        for p in positions {
            if count >= m.n("Blocks per tick") as u32 {
                break;
            }
            if place_block(game, p, slot, m.b("Rotate"), true) {
                cs(|c| c.auto_trap_placed = true);
                count += 1;
            }
        }
    }
}

// ---- Webs

fn self_web(game: &mut Game<'_>, m: &Module) {
    let go = match m.p("Mode") {
        "Smart" => player_target(game, m.n("Range"), "Lowest distance").is_some(),
        _ => true,
    };
    if !go {
        return;
    }
    let Some(slot) = find_held(game, |n| n == "cobweb") else {
        report(game, "No cobwebs in your hotbar or offhand.");
        if m.b("Auto toggle") {
            toggle_off(game, "Self Web");
        }
        return;
    };
    if let Some(at) = feet_block(game) {
        place_block(game, at, slot, m.b("Rotate"), false);
        if m.b("Double place") {
            place_block(game, [at[0], at[1] + 1, at[2]], slot, m.b("Rotate"), false);
        }
    }
    if m.b("Auto toggle") {
        toggle_off(game, "Self Web");
    }
}

fn auto_web(game: &mut Game<'_>, m: &Module) {
    let range = m.n("Target range");
    let id = cs(|c| c.web_target);
    let mut target = id.and_then(|i| target_by_id(game, i));
    if bad_target(game, &target, range) {
        target = player_target(game, range, m.p("Priority"));
        cs(|c| c.web_target = target.as_ref().map(|t| t.id));
    }
    let Some(t) = target else {
        return;
    };
    let Some(slot) = find_held(game, |n| n == "cobweb") else {
        return;
    };
    let mut pos = t.pos;
    if m.b("Only when falling") {
        // A web where they will land, at most Max webs per fall; a fall ends on the ground or with a new target.
        let landed = game.mobs.iter().find(|x| x.id == t.id).is_none_or(|x| x.on_ground);
        let placed = cs(|c| match c.web_fall {
            Some((id, n)) if id == t.id && !landed => n,
            _ => {
                c.web_fall = Some((t.id, 0));
                0
            }
        });
        if landed || f64::from(placed) >= m.n("Max webs per fall") {
            return;
        }
        let Some(landing) = landing(game, &t).filter(|l| l[1] < t.pos[1] - 0.5) else {
            return;
        };
        pos = landing;
    } else if m.b("Predict movement") {
        let k = m.n("Ticks to predict");
        for i in 0..3 {
            pos[i] += (t.pos[i] - t.prev[i]) * k;
        }
    }
    let at = [pos[0].floor() as i32, pos[1].floor() as i32, pos[2].floor() as i32];
    let (range, walls) = (m.n("Place range"), m.n("Walls range"));
    let ok = |game: &Game<'_>, p: [i32; 3]| replaceable(game, p) && in_reach(game, p, range, walls);
    if ok(game, at) {
        place_block(game, at, slot, m.b("Rotate"), false);
        show(at, 0x40FF_FFFF);
        cs(|c| {
            if let Some((_, n)) = c.web_fall.as_mut() {
                *n += 1;
            }
        });
    }
    let up = [at[0], at[1] + 1, at[2]];
    if m.b("Doubles") && ok(game, up) {
        place_block(game, up, slot, m.b("Rotate"), false);
        show(up, 0x40FF_FFFF);
    }
}

// Where a falling player comes down: their last tick's motion carried on (gravity 0.08, drag 0.98 up and down and
// 0.91 across, in quarter steps, up to 80 ticks) until a solid block is under their box.
fn landing(game: &Game<'_>, t: &Target) -> Option<[f64; 3]> {
    let mut v = [t.pos[0] - t.prev[0], t.pos[1] - t.prev[1], t.pos[2] - t.prev[2]];
    let half = ((t.hi[0] - t.lo[0]) / 2.0).max(0.15);
    let mut at = t.pos;
    for _ in 0..80 {
        for _ in 0..4 {
            let next = [at[0] + v[0] / 4.0, at[1] + v[1] / 4.0, at[2] + v[2] / 4.0];
            if v[1] <= 0.0 && solid_under(game, next, half) {
                return Some([next[0], (next[1] - 1.0e-4).floor() + 1.0, next[2]]);
            }
            at = next;
        }
        if at[1] <= -64.0 {
            return None;
        }
        v = [v[0] * 0.91, (v[1] - 0.08) * 0.98, v[2] * 0.91];
    }
    None
}

fn solid_under(game: &Game<'_>, at: [f64; 3], half: f64) -> bool {
    let y = (at[1] - 0.001).floor() as i32;
    let f = |v: f64| v.floor() as i32;
    (f(at[0] - half + 0.001)..=f(at[0] + half - 0.001))
        .any(|x| (f(at[2] - half + 0.001)..=f(at[2] + half - 0.001)).any(|z| !is_air(game, [x, y, z]) && facts(game, [x, y, z]).full_collision))
}

// Auto Web's Web key: a web on the face you look at, from the hotbar, with the slot back after.
pub(super) fn web_key(game: &mut Game<'_>, key: &str, pressed: bool) {
    let Some(m) = with(|s| s.module("Auto Web").filter(|m| m.on).cloned()) else {
        return;
    };
    if !pressed || gui_open() || !game.native_playing() || super::sunset::key_from_text(m.t("Web key")).is_none_or(|k| super::sunset::key_from_text(key) != Some(k)) {
        return;
    }
    let (Some(hit), Some(slot)) = (game.pick(), find_held(game, |n| n == "cobweb")) else {
        return;
    };
    let at = if replaceable(game, hit.pos) { hit.pos } else { [hit.pos[0] + hit.face[0], hit.pos[1] + hit.face[1], hit.pos[2] + hit.face[2]] };
    if in_reach(game, at, m.n("Place range"), m.n("Walls range")) {
        place_block(game, at, slot, false, true);
        show(at, 0x40FF_FFFF);
    }
}

// ---- Offhand (its module is in combat_inventory.rs, with the careful totem moves)

// What the offhand should hold this tick.
pub(super) enum Want {
    Nothing,
    Totem,
    Item(&'static str),
}

// Sunset's Offhand: the chosen Item (a totem by Auto Totem), a golden apple or potion while you hold right click with
// Right gapple or Sword pot (or always with a sword or axe in hand).
pub(super) fn offhand_want(game: &Game<'_>, m: &Module) -> Want {
    use winit::event::MouseButton;
    if game.player.is_none() {
        return Want::Nothing;
    }
    let main = game.inventory.get(game.selected).and_then(|s| s.as_ref()).map(|s| short(&s.item).to_owned()).unwrap_or_default();
    let (sword, axe) = (main.ends_with("_sword"), main.ends_with("_axe"));
    // A right click that is not using what the main hand holds.
    let usable = matches!(main.as_str(), "bow" | "trident" | "crossbow") || game.res.items().get(&format!("minecraft:{main}")).is_some_and(|i| i.food.is_some());
    let clicking = (game.physical_buttons.contains(&MouseButton::Right) || game.right) && game.native_playing() && !usable;
    // Totem on low health (an SMP offhand): at Totem health or under, a totem whatever Item says, unless your
    // shield is up (Wait while shielding).
    let low = m.b("Totem on low health")
        && game.player.as_ref().is_some_and(|p| p.health.health() <= m.n("Totem health") as f32)
        && !(m.b("Wait while shielding") && super::sunset_hands::shielding(game));
    let item = if low {
        "Totem"
    } else if m.b("Right gapple") {
        if clicking && (!m.b("Sword gapple") || sword) { "Enchanted gapple" } else { m.p("Item") }
    } else if (sword || axe) && m.b("Always gap on sword") {
        "Enchanted gapple"
    } else if m.b("Sword pot") {
        if sword && clicking { "Potion" } else { m.p("Item") }
    } else if (sword || axe) && m.b("Always pot on sword") {
        "Potion"
    } else {
        m.p("Item")
    };
    match item {
        "Totem" => Want::Totem,
        "Gapple" => Want::Item("golden_apple"),
        "Enchanted gapple" => Want::Item("enchanted_golden_apple"),
        "Shield" => Want::Item("shield"),
        "Potion" => Want::Item("potion"),
        "Crystal" => Want::Item("end_crystal"),
        _ => Want::Nothing,
    }
}

// The quick way: pick the item up, put it in the offhand slot, put back what was there; at most every Delay ticks,
// from the main inventory (and the hotbar with Hotbar).
pub(super) fn offhand_click(game: &mut Game<'_>, m: &Module, want: &str) {
    use horizon_client::menu::Input::Pickup;
    if !inventory_idle(game) {
        return;
    }
    let has = |s: &Option<horizon_client::items::ItemStack>| s.as_ref().is_some_and(|s| short(&s.item) == want);
    let ready = cs(|c| {
        c.offhand_ticks += 1;
        c.offhand_ticks
    }) > m.n("Delay (ticks)") as u32;
    if has(&game.offhand) || !ready {
        return;
    }
    let from = if m.b("Hotbar") { 0 } else { 9 };
    match (from..36).find(|&i| game.inventory.get(i).is_some_and(has)) {
        None => {
            if !cs(|c| std::mem::replace(&mut c.offhand_warned, true)) {
                super::sunset_util::report(game, "Offhand: chosen item not found.");
            }
        }
        Some(i) => {
            if !super::sunset::menu_click(game, &[(i, Pickup), (504, Pickup), (i, Pickup)]) {
                return;
            }
            cs(|c| {
                c.offhand_warned = false;
                c.offhand_ticks = 0;
            });
        }
    }
}

// ---- Auto EXP

fn needs_repair(game: &Game<'_>, stack: &Option<horizon_client::items::ItemStack>, threshold: f64) -> bool {
    let Some(s) = stack else {
        return false;
    };
    if s.enchantment_level("minecraft:mending") == 0 {
        return false;
    }
    let max = game.res.items().get(&s.item).map_or(0, |i| i.max_damage);
    max > 0 && f64::from(max.saturating_sub(s.damage)) / f64::from(max) * 100.0 <= threshold
}

fn auto_exp(game: &mut Game<'_>, m: &Module) {
    if m.b("Only on ground") && !game.player.as_ref().is_some_and(|p| p.ground.on_ground) {
        return;
    }
    // 0 to 3 armor, 10 the main hand, 11 the offhand.
    let item_at = |game: &Game<'_>, i: usize| -> Option<horizon_client::items::ItemStack> {
        match i {
            0..=3 => game.armor[i].clone(),
            10 => game.inventory.get(game.selected).cloned().flatten(),
            _ => game.offhand.clone(),
        }
    };
    let mut repairing = cs(|c| c.exp_repairing);
    if repairing.is_none() {
        if m.p("Mode") != "Hands" {
            repairing = (0..4).find(|&i| needs_repair(game, &game.armor[i], m.n("Min threshold %")));
        }
        if m.p("Mode") != "Armor" && repairing.is_none() {
            repairing = [10usize, 11].into_iter().find(|&i| needs_repair(game, &item_at(game, i), m.n("Min threshold %")));
        }
    }
    cs(|c| c.exp_repairing = repairing);
    let Some(i) = repairing else {
        return;
    };
    if !needs_repair(game, &item_at(game, i), m.n("Max threshold %")) {
        cs(|c| c.exp_repairing = None);
        return;
    }
    let slot = match find_hotbar(game, |n| n == "experience_bottle") {
        Some(s) => s,
        None => {
            if !m.b("Replenish") {
                return;
            }
            let Some(src) = find_inventory(game, |n| n == "experience_bottle") else {
                return;
            };
            // Into the chosen hotbar slot.
            let to = m.n("EXP slot") as usize - 1;
            super::sunset::menu_click(game, &[(src, horizon_client::menu::Input::Pickup), (to, horizon_client::menu::Input::Pickup), (src, horizon_client::menu::Input::Pickup)]);
            return;
        }
    };
    // Throw it at your feet.
    let yaw = game.yaw;
    super::sunset::turn_then("EXP Thrower", yaw, 90.0, move |game| {
        let before = game.selected;
        hold(game, slot);
        let seq = sequence(game);
        game.send(S::UseItem(play::UseItem { hand: 0, sequence: seq, yaw, pitch: 90.0 }));
        hold(game, before);
    });
}

// ---- Aim Assist around your own mouse turn once a frame
//
// Only ever adds to what your hand is doing. Pull: moving the mouse toward the target turns you a bit further toward
// it. Stickiness: while the crosshair is on the target your own turning is slowed. Tracking: while on (or almost on)
// the target, follows part of its movement across your screen. One target is kept until it leaves the cone, so it
// does not flick between people. Mace dive: falling onto someone the cone and range widen, tracking is full, and it
// also pulls on its own.

use horizon_client::collisions::SceneCollisions;
use horizon_client::mobs::Mob;
use horizon_core::geometry::{Vec3, VoxelShape};
use horizon_core::position::BlockPos;
use horizon_world::collision_context::{CollisionContext, CollisionEntity, CollisionItem};
use horizon_world::entity_obstruction::EntityIdentity;
use horizon_world::registry::BlockStateId;
use horizon_world::world_ray::{RayBlockMode, RayFluidMode, RayWorld, clip_world};

fn yaw_of(v: [f64; 3]) -> f64 {
    (-v[0]).atan2(v[2]).to_degrees()
}

fn pitch_of(v: [f64; 3]) -> f64 {
    -v[1].atan2((v[0] * v[0] + v[2] * v[2]).sqrt()).to_degrees()
}

// Mth.wrapDegrees.
fn wrap(d: f64) -> f64 {
    (d + 180.0).rem_euclid(360.0) - 180.0
}

fn view_vector(yaw: f32, pitch: f32) -> [f64; 3] {
    let (y, p) = (f64::from(yaw).to_radians(), f64::from(pitch).to_radians());
    [-y.sin() * p.cos(), -p.sin(), y.cos() * p.cos()]
}

fn angle_between(a: [f64; 3], b: [f64; 3]) -> f64 {
    let n = (a[0] * a[0] + a[1] * a[1] + a[2] * a[2]).sqrt().max(1e-9);
    ((a[0] * b[0] + a[1] * b[1] + a[2] * b[2]) / n).clamp(-1.0, 1.0).acos()
}

fn sub(a: [f64; 3], b: [f64; 3]) -> [f64; 3] {
    [a[0] - b[0], a[1] - b[1], a[2] - b[2]]
}

// A box as its low and high corners.
type Box3 = [[f64; 3]; 2];

fn centre(b: &Box3) -> [f64; 3] {
    std::array::from_fn(|i| (b[0][i] + b[1][i]) / 2.0)
}

// The box where this frame draws a mob, shrunk by `inset` (AABB.deflate, which keeps low below high).
fn drawn_box(mob: &Mob, alpha: f64, inset: f64) -> Box3 {
    let b = mob.bounds();
    let (lo, hi) = (b.min_position(), b.max_position());
    let (lo, hi) = ([lo.x, lo.y, lo.z], [hi.x, hi.y, hi.z]);
    let (prev, now) = ([mob.previous.x, mob.previous.y, mob.previous.z], [mob.position.x, mob.position.y, mob.position.z]);
    let mut out = [[0.0; 3]; 2];
    for i in 0..3 {
        let off = (prev[i] - now[i]) * (1.0 - alpha);
        let (a, z) = (lo[i] + off + inset, hi[i] + off - inset);
        out[0][i] = a.min(z);
        out[1][i] = a.max(z);
    }
    out
}

// The point of the box closest to the look ray, at the box's distance.
fn closest_point(b: &Box3, eye: [f64; 3], look: [f64; 3]) -> [f64; 3] {
    let d = dist(eye, centre(b));
    std::array::from_fn(|i| (eye[i] + look[i] * d).clamp(b[0][i], b[1][i]))
}

// `Level.clip` with `ClipContext.Block.COLLIDER`, no fluids and your collision context.
struct ColliderRays<'a, 'r> {
    scene: SceneCollisions<'a, 'r>,
    context: CollisionContext<'static>,
}

impl RayWorld for ColliderRays<'_, '_> {
    type Error = std::io::Error;
    type Block = BlockStateId;
    type Fluid = ();
    fn block_state(&mut self, p: BlockPos) -> std::io::Result<BlockStateId> {
        Ok(self.scene.world.block(p.x, p.y, p.z))
    }
    fn fluid_state(&mut self, _: BlockPos) -> std::io::Result<()> {
        Ok(())
    }
    fn block_shape(&mut self, state: BlockStateId, p: BlockPos, _: RayBlockMode) -> std::io::Result<VoxelShape> {
        let binding = self.scene.binding;
        binding
            .collision_shape_with_context(&mut self.scene, state, p, &self.context)
            .map_err(|e| std::io::Error::other(format!("{e:?}")))
    }
    fn interaction_shape(&mut self, _: BlockStateId, _: BlockPos) -> std::io::Result<VoxelShape> {
        Ok(VoxelShape::empty())
    }
    fn fluid_is_source(&mut self, _: ()) -> std::io::Result<bool> {
        Ok(false)
    }
    fn fluid_is_empty(&mut self, _: ()) -> std::io::Result<bool> {
        Ok(true)
    }
    fn fluid_is_water(&mut self, _: ()) -> std::io::Result<bool> {
        Ok(false)
    }
    fn fluid_shape(&mut self, _: (), _: BlockPos) -> std::io::Result<VoxelShape> {
        Ok(VoxelShape::empty())
    }
}

// Nothing solid between the eyes and `to` (`d` away): the ray misses, or stops no nearer than 0.01 short of it.
pub(super) fn clip_clear(game: &Game<'_>, eye: [f64; 3], to: [f64; 3], d: f64) -> bool {
    let Some(p) = game.player.as_ref() else {
        return false;
    };
    let mut rays = ColliderRays {
        scene: SceneCollisions { world: &game.world, binding: game.collision, subject: None },
        context: CollisionContext::for_entity(
            CollisionEntity {
                identity: EntityIdentity(0),
                kind: horizon_world::collision_context::EntityContextKind::Player,
                y: p.position.y,
                descending: p.shift_key_down,
                main_hand: Some(CollisionItem::EMPTY),
            },
            false,
        ),
    };
    let from = Vec3::new(eye[0], eye[1], eye[2]);
    clip_world(&mut rays, from, Vec3::new(to[0], to[1], to[2]), RayBlockMode::Collider, RayFluidMode::None, 4096)
        .is_ok_and(|r| r.miss || r.hit.location.distance_squared(from).sqrt() >= d - 0.01)
}

// `Entity.isInvisibleTo`: invisible, unless on your team and the team sees friendly invisibles.
fn invisible_to_you(game: &Game<'_>, e: &Mob) -> bool {
    let own = game.score.board.players_team(&game.options.player_name());
    e.invisible && !(horizon_client::scoreboard::teams_allied(own, game.mob_team(e.id)) && own.is_some_and(|t| t.see_friendly_invisibles))
}

// `Weapons.isWeapon`: a sword, axe or spear (by their item tags), a mace or a trident in the main hand.
pub(super) fn holds_weapon(game: &Game<'_>) -> bool {
    let tags = &game.res.items().item_tags;
    game.inventory.get(game.selected).and_then(|s| s.as_ref()).is_some_and(|s| {
        let item = &*s.item;
        item == "minecraft:mace"
            || item == "minecraft:trident"
            || ["minecraft:swords", "minecraft:axes", "minecraft:spears"].iter().any(|t| tags.get(*t).is_some_and(|t| t.contains(item)))
    })
}

// One frame's view: the eyes and the look at the frame's partial tick, and the settings in force.
struct Aim<'a, 'g> {
    game: &'a Game<'g>,
    m: &'a Module,
    eye: [f64; 3],
    look: [f64; 3],
    alpha: f64,
    range: f64,
    own: Option<u32>,
}

impl<'a> Aim<'a, '_> {
    fn boxed(&self, e: &Mob) -> Box3 {
        drawn_box(e, self.alpha, self.m.n("Aim inset"))
    }

    // `Targets.matches`: alive and visible to you, never yourself or an armour stand (Horizon keeps those apart);
    // players and hostile mobs as chosen. Friends, bots (Anti bot) and teammates (Ignore teams) are left alone.
    fn matches(&self, e: &Mob) -> bool {
        let player = e.kind.id == "minecraft:player";
        let wanted = if player { self.m.b("Players") } else { e.hostile() && self.m.b("Hostiles") };
        wanted
            && Some(e.id) != self.own
            && combat_eligible(self.game, self.m, e)
            && !invisible_to_you(self.game, e)
    }

    // A target, within `half_cone` degrees of the crosshair, in range and not behind a block.
    fn valid(&self, e: &Mob, half_cone: f64) -> bool {
        if !self.matches(e) {
            return false;
        }
        let aim = closest_point(&self.boxed(e), self.eye, self.look);
        let to = sub(aim, self.eye);
        let d = dist(self.eye, aim);
        if d < 1e-4 || angle_between(to, self.look).to_degrees() > half_cone {
            return false;
        }
        if self.m.p("Range shape") == "Column" {
            let height = self.m.n("Column height");
            if to[0].hypot(to[2]) > self.range || (height > 0.0 && to[1].abs() > height) {
                return false;
            }
        } else if d > self.range {
            return false;
        }
        clip_clear(self.game, self.eye, aim, d)
    }

    // The target nearest the crosshair.
    fn pick(&self, cone: f64) -> Option<&'a Mob> {
        let game: &'a Game<'_> = self.game;
        let angle = |e: &Mob| angle_between(sub(closest_point(&self.boxed(e), self.eye, self.look), self.eye), self.look);
        game.mobs.iter().filter(|e| self.valid(e, cone / 2.0)).min_by(|a, b| angle(a).total_cmp(&angle(b)))
    }
}

// In the world with no screen open, not a spectator, holding a weapon (with Only with a weapon), and the mouse
// turning you rather than a free camera.
fn aim_allowed(game: &Game<'_>, m: &Module) -> bool {
    in_world(game)
        && !gui_open()
        && !game.spectator()
        && !super::sunset_render::camera_takes_mouse()
        && (!m.b("Only with a weapon") || holds_weapon(game))
        // Pause while mining: not while you break a block. Only while turning: only in a frame your mouse turned you.
        && !(m.b("Pause while mining") && game.mining.is_some())
        && !(m.b("Only while turning") && cs(|c| c.aim_before) == [game.yaw, game.pitch])
}

// Before your own mouse turn this frame.
pub(super) fn aim_before(game: &Game<'_>) {
    let rot = [game.yaw, game.pitch];
    cs(|c| c.aim_before = rot);
}

// After it: how far to turn you on top of it, in degrees.
fn aim_turn(game: &Game<'_>, m: &Module, dt: f64) -> [f64; 2] {
    let Some(p) = game.player.as_ref() else {
        return [0.0; 2];
    };
    let dive = m.b("Mace dive") && !p.ground.on_ground && !p.fall_flying && p.velocity.y < 0.0 && p.fall_distance >= m.n("Dive from fall of");
    let (cone, range, tracking) = if dive {
        (m.n("Dive cone (degrees)"), m.n("Dive range"), m.n("Dive tracking"))
    } else {
        (m.n("Cone (degrees)"), m.n("Range"), m.n("Tracking"))
    };
    let alpha = game.clock.camera_fraction();
    let lerp = |a: f64, b: f64| a + alpha * (b - a);
    let was = game.previous_position;
    let eye = [
        lerp(was.x, p.position.x),
        lerp(was.y, p.position.y) + f64::from(p.dimensions.eye_height),
        lerp(was.z, p.position.z),
    ];
    let look = view_vector(game.yaw, game.pitch);
    let aim = Aim { game, m, eye, look, alpha, range, own: own_id(game) };
    let (previous, last, before) = cs(|c| (c.aim_target, c.aim_last, c.aim_before));
    let kept = previous
        .filter(|token| super::sunset_antibot::current(*token))
        .and_then(|token| game.mobs.iter().find(|e| e.id == token.id))
        .filter(|e| aim.valid(e, cone / 2.0 * m.n("Keep target")));
    let Some(target) = kept.or_else(|| aim.pick(cone)) else {
        cs(|c| c.aim_target = None);
        return [0.0; 2];
    };
    let b = aim.boxed(target);
    let middle = sub(centre(&b), eye);
    let (yaw_to, pitch_to) = (yaw_of(middle), pitch_of(middle));
    // The gap from the crosshair to the nearest point of the hitbox, zero when already on it.
    let to = sub(closest_point(&b, eye, look), eye);
    let (yaw, pitch) = (f64::from(game.yaw), f64::from(game.pitch));
    let gap_yaw = wrap(yaw_of(to) - yaw);
    let gap_pitch = pitch_of(to) - pitch;
    let gap = gap_yaw.hypot(gap_pitch);
    let on_target = gap < 0.05;
    let mut turn = [0.0; 2];
    // Tracking fades out as the crosshair drifts off the hitbox, instead of switching off at a hard edge.
    let within = m.n("Track within (degrees)");
    let identity = super::sunset_antibot::token(target.id);
    if previous.is_some() && previous == identity && gap < within {
        let t = tracking * (1.0 - gap / within);
        turn[0] += wrap(yaw_to - last[0]) * t;
        turn[1] += (pitch_to - last[1]) * t;
    }
    if dive && !on_target && dt > 0.0 {
        let f = 1.0 - (-m.n("Dive magnet") * dt).exp();
        turn[0] += gap_yaw * f;
        turn[1] += gap_pitch * f;
    }
    let user = [wrap(yaw - f64::from(before[0])), pitch - f64::from(before[1])];
    let moved = user[0].hypot(user[1]);
    if moved > 1e-4 {
        // Stickiness ramps in over the last degree, so there is no hard edge to stutter on.
        let stick = m.n("Stickiness") * (1.0 - gap).clamp(0.0, 1.0);
        turn[0] -= user[0] * stick;
        turn[1] -= user[1] * stick;
        if !on_target && gap_yaw * user[0] + gap_pitch * user[1] > 0.0 {
            let extra = gap.min(m.n("Pull") * moved);
            turn[0] += gap_yaw / gap * extra;
            turn[1] += gap_pitch / gap * extra;
        }
    }
    cs(|c| {
        c.aim_target = identity;
        c.aim_last = [yaw_to, pitch_to];
    });
    turn
}

// After your own mouse turn this frame.
pub(super) fn aim_after(game: &mut Game<'_>) {
    let now = Instant::now();
    let dt = cs(|c| c.aim_frame.replace(now)).map_or(0.0, |t| now.duration_since(t).as_secs_f64().min(0.05));
    let Some(m) = with(|s| s.module("Aim Assist").filter(|m| m.on).cloned()).filter(|m| aim_allowed(game, m)) else {
        reset_aim();
        return;
    };
    let turn = match m.p("Mode") {
        "Simple" => { cs(|c| c.aim_target = None); simple_turn(game, &m, dt) },
        "Duelkit" => { simple_reset(); aim_turn(game, &m, dt) },
        _ => { reset_aim(); return; },
    };
    // turn_player takes mouse units, 0.15 degrees each (Entity.turn), and keeps the interpolation in step.
    if turn != [0.0; 2] {
        game.turn_player(turn[0] / 0.15, turn[1] / 0.15);
    }
}


// ---- Aim Assist's Simple mode:
// A worker step for each millisecond since the last frame (at most 100) eases a velocity toward the
// target's side, a little faster the further off, the nearer, and when it jumps about; a slow random drift is added;
// the frame turns you by the whole mouse counts that adds up to at your sensitivity. Horizontal only unless Aim
// vertically. With Require mouse down it aims only while you hold attack, at the target it took when you pressed.
// While your own mouse turns you away on an axis, it lets go on that axis instead of pulling against you.

#[derive(Default)]
struct Simple {
    target: Option<super::sunset_antibot::Token>,
    retarget: i32,
    swap: i32,
    sample: i32,
    offset: (i32, i32),
    drift: (i32, i32),
    drift_timer: f64,
    counts: (f32, f32),
    h_velocity: f32,
    h_buffer: f32,
    v_velocity: f32,
    v_buffer: f32,
    yaw_boost: f32,
    pitch_boost: f32,
    prev_target: (f64, f64),
    prev_left: bool,
    prev_above: bool,
    last_angle: f64,
    rng: u64,
    shared: u64,
}

static SIMPLE: Mutex<Option<Simple>> = Mutex::new(None);

fn xorshift(state: &mut u64) -> u64 {
    if *state == 0 {
        *state = 0x9e37_79b9_7f4a_7c15;
    }
    *state ^= *state << 13;
    *state ^= *state >> 7;
    *state ^= *state << 17;
    *state
}

fn below(state: &mut u64, bound: i32) -> i32 {
    (xorshift(state) % bound.max(1) as u64) as i32
}

fn between(state: &mut u64, lo: i32, hi: i32) -> i32 {
    lo + below(state, hi - lo)
}

fn uniform(state: &mut u64, lo: f64, hi: f64) -> f64 {
    lo + (xorshift(state) >> 11) as f64 / (1u64 << 53) as f64 * (hi - lo)
}

// The degrees from your yaw to the point (0 to 180), and whether it is on your left.
fn yaw_off(from: [f64; 3], yaw: f32, to: [f64; 3]) -> (f64, bool) {
    let want = (-(to[0] - from[0])).atan2(to[2] - from[2]).to_degrees();
    let d = wrap(want - f64::from(yaw));
    (d.abs(), d < 0.0)
}

impl Simple {
    fn forget(&mut self) {
        *self = Self { rng: self.rng, shared: self.shared, ..Self::default() };
    }
    fn reset_turn(&mut self) {
        self.counts = (0.0, 0.0);
        self.offset = (0, 0);
        self.drift = (0, 0);
    }

    // `updateDrift`: now and then a count of drift one way or the other.
    fn update_drift(&mut self) {
        self.drift_timer += 1.0;
        if self.drift_timer >= f64::from(250 + below(&mut self.rng, 50)) {
            self.drift_timer = f64::from(between(&mut self.rng, -100, -50));
            self.offset = (between(&mut self.rng, -1, 2), between(&mut self.rng, -1, 2));
        }
        let (mut h, mut v) = self.offset;
        below(&mut self.rng, 10);
        below(&mut self.rng, 10);
        if below(&mut self.rng, 10) < 2 {
            h = 0;
        }
        if below(&mut self.rng, 10) < 2 {
            v = 0;
        }
        if self.drift_timer < 0.0 {
            (h, v) = (0, 0);
        }
        if below(&mut self.rng, 20) == 1 {
            self.drift.0 += h;
            self.drift.1 += v;
        }
        if (self.counts.0 > 0.0 && self.drift.0 < 0) || (self.counts.0 < 0.0 && self.drift.0 > 0) {
            self.drift.0 = 0;
        }
    }

    // `applyRotation`: one step's counts toward the target. `feet` and `look` are yours; `strafe` your strafe key
    // (left positive).
    fn step(&mut self, m: &Module, feet: [f64; 3], look: (f32, f32), strafe: f32, aim: [f64; 3], tick_pos: [f64; 3]) {
        self.update_drift();
        let motion = (aim[0] - self.prev_target.0, aim[2] - self.prev_target.1);
        self.prev_target = (aim[0], aim[2]);
        let predicted = [aim[0] + motion.0 * 1.7, aim[1], aim[2] + motion.1 * 1.7];
        let (angle, left) = yaw_off(feet, look.0, predicted);
        let horizontal = (aim[0] - feet[0]).hypot(aim[2] - feet[2]);
        let pitch_to = -(aim[1] - feet[1]).atan2(horizontal).to_degrees();
        let vertical = wrap(f64::from(look.1) - pitch_to) as i32;
        let above = vertical < 0;
        let dead_zone = vertical.abs() - 10;
        let distance = dist(feet, tick_pos) as f32;
        let mut h_force = 1.0 + uniform(&mut self.shared, 0.0, 2.0) as f32 + (angle / 50.0) as f32;
        let v_force = 1.0 + uniform(&mut self.shared, 0.0, 2.0) as f32 + dead_zone.abs() as f32 / 50.0;
        if (angle - self.last_angle).abs() > 6.0 {
            h_force += (angle / 35.0) as f32;
        }
        h_force += ((9.0 - distance) / 2.5 - 2.0).max(0.0);
        let away = if left { strafe < 0.0 } else { strafe > 0.0 };
        if m.b("Strafe increase") && away {
            h_force *= 1.6;
        }
        if distance < 0.5 {
            h_force /= 5.0;
        }
        let mut h_acc = h_force / 90.0 * if left { -1.0 } else { 1.0 };
        let mut v_acc = v_force / 90.0 * if above { 1.0 } else { -1.0 };
        if angle < 5.0 {
            h_acc = 0.0;
            self.h_velocity *= 0.7;
            if if left { strafe > 0.0 } else { strafe < 0.0 } {
                self.h_velocity *= 0.5;
            }
        }
        if left != self.prev_left {
            self.h_velocity = -self.h_velocity;
            self.h_buffer = -self.h_buffer;
            self.counts.0 = 0.0;
        }
        if above != self.prev_above {
            self.v_buffer = -self.v_buffer;
            self.v_velocity = -self.v_velocity;
            self.counts.1 = 0.0;
        }
        if dead_zone < 5 {
            v_acc = 0.0;
            self.v_buffer *= 0.7;
        }
        self.h_buffer += h_acc;
        self.v_velocity += v_acc;
        if self.h_velocity.abs() > 10.0 {
            self.h_buffer = 0.0;
            self.h_velocity = 0.0;
            return;
        }
        let mut h_adjust = self.h_velocity * 0.15;
        if angle <= 9.0 {
            h_adjust = (f64::from(h_adjust) / (10.0 - angle)) as f32;
        }
        if h_adjust.is_nan() {
            self.h_buffer = 0.0;
            self.h_velocity = 0.0;
            return;
        }
        // queueHorizontal: the speed eases off once within 10 degrees.
        if h_adjust == 0.0 {
            self.counts.0 = 0.0;
        } else {
            let mut speed = m.n("Horizontal speed") as f32;
            let int_angle = yaw_off(feet, look.0, tick_pos).0 as i32 as f32;
            if int_angle <= 10.0 {
                self.pitch_boost = speed;
            }
            if self.pitch_boost > 0.0 {
                speed -= self.pitch_boost / 3.0;
                self.pitch_boost -= int_angle / 200.0;
            }
            self.counts.0 += speed * h_adjust * 5.0;
        }
        if m.b("Aim vertically") {
            let v_adjust = self.v_buffer * 0.15;
            if v_adjust.is_nan() {
                self.v_velocity = 0.0;
                self.v_buffer = 0.0;
                return;
            }
            if v_adjust == 0.0 {
                self.counts.1 = 0.0;
            } else {
                let mut speed = m.n("Vertical speed") as f32;
                let a = vertical.abs() as f32;
                if a <= 10.0 {
                    self.yaw_boost = speed;
                }
                if self.yaw_boost > 0.0 {
                    speed -= self.yaw_boost / 3.0;
                    self.yaw_boost -= a / 200.0;
                }
                self.counts.1 += speed * v_adjust * 5.0;
            }
        }
        self.prev_above = above;
        self.prev_left = left;
        self.sample += 1;
        if self.sample > 10 {
            self.last_angle = angle;
            self.sample = 0;
        }
    }
}

// This frame's turn in degrees (yaw, pitch).
fn simple_turn(game: &Game<'_>, m: &Module, dt: f64) -> [f64; 2] {
    let Some(p) = game.player.as_ref() else {
        return [0.0; 2];
    };
    let alpha = game.clock.camera_fraction();
    let lerp = |a: f64, b: f64| a + alpha * (b - a);
    let was = game.previous_position;
    let feet = [lerp(was.x, p.position.x), lerp(was.y, p.position.y), lerp(was.z, p.position.z)];
    let tick_feet = [p.position.x, p.position.y, p.position.z];
    let eye = [feet[0], feet[1] + f64::from(p.dimensions.eye_height), feet[2]];
    let look = (game.yaw, game.pitch);
    let aim = Aim {
        game,
        m,
        eye,
        look: view_vector(game.yaw, game.pitch),
        alpha,
        range: m.n("Distance"),
        own: own_id(game),
    };
    let held = |k: winit::keyboard::KeyCode| game.keys.contains(&k) || game.physical_keys.contains(&k);
    let strafe = f32::from(u8::from(held(winit::keyboard::KeyCode::KeyA))) - f32::from(u8::from(held(winit::keyboard::KeyCode::KeyD)));
    let down = game.left || game.physical_buttons.contains(&winit::event::MouseButton::Left);
    let require = m.b("Require mouse down");
    let (distance, half) = (m.n("Distance"), m.n("Max angle") / 2.0);
    // isValidTarget: alive, nearer than Distance (whole blocks), within half Max angle (whole degrees).
    let valid = |e: &Mob| {
        let at = [e.position.x, e.position.y, e.position.z];
        let point = closest_point(&aim.boxed(e), eye, aim.look);
        aim.matches(e) && dist(tick_feet, at) < f64::from(distance as i32)
            && yaw_off(tick_feet, look.0, at).0 as i32 <= half as i32
            && clip_clear(game, eye, point, dist(eye, point))
    };
    let best = || {
        game.mobs
            .iter()
            .filter(|e| valid(e))
            .min_by_key(|e| yaw_off(tick_feet, look.0, [e.position.x, e.position.y, e.position.z]).0 as i32)
            .and_then(|e| super::sunset_antibot::token(e.id))
    };
    let steps = (dt * 1000.0).round().min(100.0) as u32;
    let mut g = SIMPLE.lock().unwrap_or_else(|e| e.into_inner());
    let s = g.get_or_insert_with(Simple::default);
    // Revalidate before consuming any buffered turn, even on frames with no
    // millisecond worker step. Holding attack never exempts a retained target.
    if (require && !down) || s.target.is_some_and(|token|
        !super::sunset_antibot::current(token)
            || !game.mobs.iter().any(|e| e.id == token.id && valid(e)))
    { s.forget(); }
    for _ in 0..steps {
        if require && !down {
            s.forget();
            continue;
        }
        if !require {
            s.retarget += 1;
            let invalid = s.target.is_none();
            if s.retarget > 700 || invalid {
                let next = best();
                if next != s.target { s.forget(); }
                s.target = next;
                s.retarget = 0;
            }
        } else if s.target.is_none() {
            s.target = best();
        }
        let Some(e) = s.target.and_then(|token| game.mobs.iter().find(|e| e.id == token.id)) else {
            s.reset_turn();
            continue;
        };
        // The velocity buffers swap every ten steps.
        s.swap += 1;
        if s.swap > 10 {
            s.v_buffer = s.v_velocity;
            s.h_velocity = s.h_buffer;
            s.h_buffer = 0.0;
            s.v_velocity = 0.0;
            s.swap = 0;
        }
        let at = [lerp(e.previous.x, e.position.x), lerp(e.previous.y, e.position.y), lerp(e.previous.z, e.position.z)];
        s.step(m, feet, look, strafe, at, [e.position.x, e.position.y, e.position.z]);
    }
    if s.target.is_none() {
        return [0.0; 2];
    }
    // onPreRenderTick: the drift, then whole counts at your sensitivity's degrees per count.
    s.counts.0 += s.drift.0 as f32;
    s.counts.1 += s.drift.1 as f32;
    let whole = (s.counts.0.trunc(), s.counts.1.trunc());
    s.counts = (s.counts.0 - whole.0, s.counts.1 - whole.1);
    s.drift = (0, 0);
    let per = f64::from(super::sunset_rotation::degrees_per_count(f64::from(game.settings.sensitivity)));
    let mut turn = [f64::from(whole.0) * per, f64::from(whole.1) * per];
    // You turning one way this frame (a mouse count or more) and the assist the other: it lets go on that axis rather
    // than pull against you, and starts again from rest once you stop. A tug of war in whole counts with a random
    // force each step nets out to the view going back and forth every other frame: the flicker when you pull away.
    let before = cs(|c| c.aim_before);
    let user = [wrap(f64::from(game.yaw) - f64::from(before[0])), f64::from(game.pitch) - f64::from(before[1])];
    if user[0].abs() >= per / 2.0 && (turn[0] * user[0] < 0.0 || f64::from(s.h_velocity) * user[0] < 0.0) {
        turn[0] = 0.0;
        (s.h_velocity, s.h_buffer, s.counts.0) = (0.0, 0.0, 0.0);
    }
    if user[1].abs() >= per / 2.0 && (turn[1] * user[1] < 0.0 || f64::from(s.v_buffer) * user[1] < 0.0) {
        turn[1] = 0.0;
        (s.v_velocity, s.v_buffer, s.counts.1) = (0.0, 0.0, 0.0);
    }
    turn
}

fn simple_reset() {
    *SIMPLE.lock().unwrap_or_else(|e| e.into_inner()) = None;
}
pub(super) fn reset_aim() {
    cs(|c| { c.aim_target = None; c.aim_last = [0.0; 2]; });
    simple_reset();
}
pub(super) fn aim_target_id() -> Option<u32> {
    if with(|s| s.module("Aim Assist").is_some_and(|m| m.p("Mode") == "Simple")) {
        SIMPLE.lock().unwrap_or_else(|e| e.into_inner()).as_ref().and_then(|s| s.target.map(|t| t.id))
    } else { cs(|c| c.aim_target.map(|t| t.id)) }
}
pub(super) fn click_eligible(game: &Game<'_>, m: &Module, mob: &Mob, players_only: bool) -> bool {
    combat_eligible(game, m, mob) && !invisible_to_you(game, mob)
        && if mob.kind.id == "minecraft:player" { m.b("Players") } else { !players_only }
}

// ---- Crystal Optimizer

// Called when you attack: if an end crystal is on the crosshair, hit it now and
// remove it from your screen, then the click is done. Some(instant) when it
// took the click.
pub(super) fn crystal_attack(game: &mut Game<'_>) -> Option<bool> {
    let m = super::sunset::with(|s| s.module("Crystal Optimizer").filter(|m| m.on).cloned())?;
    // Skip with weakness: a hit under Weakness may not break it, so it stays shown until the server says.
    if !m.b("Instant break") || !in_world(game) || (m.b("Skip with weakness") && game.potions.effects.get("weakness").is_some()) {
        return None;
    }
    let eye = game.eye_position()?;
    let dir = view_vector(game.yaw, game.pitch);
    let reach = m.n("Reach");
    let mut best: Option<(f64, u32)> = None;
    for c in &game.crystals {
        if c.id == 0 || c.invulnerable {
            continue;
        }
        let lo = horizon_core::geometry::Vec3::new(c.position.x - 1.0, c.position.y, c.position.z - 1.0);
        let hi = horizon_core::geometry::Vec3::new(c.position.x + 1.0, c.position.y + 2.0, c.position.z + 1.0);
        let b = horizon_core::geometry::Aabb::new(lo, hi);
        if let Some(d) = super::ray_box(eye, dir, reach, b)
            && best.is_none_or(|(bd, _)| d < bd)
        {
            let at = [eye[0] + dir[0] * d, eye[1] + dir[1] * d, eye[2] + dir[2] * d];
            if clear_line(game, at, [i32::MIN; 3]) {
                best = Some((d, c.id));
            }
        }
    }
    let (_, id) = best?;
    game.send(S::Attack(play::Attack { id: id as i32 }));
    if m.b("Swing") {
        game.swing_arm();
        game.send(S::Punch(horizon_protocol::packets::Empty));
    }
    game.reset_attack_strength();
    game.crystals.retain(|c| c.id != id);
    Some(false)
}

// One owner of the hotbar and the next look at a time (Crystal Aura, Anchor Aura, a macro, Auto Eat): the others
// wait. Dropped on a new world, life or connection.
use super::sunset_combat_lease::Lease;
use super::{Dim, Game};
use std::sync::{Arc, Mutex};
type Session = Arc<Mutex<Option<Arc<horizon_protocol::connection::Counters>>>>;
#[derive(Default)]
struct State {
    lease: Lease,
    session: Option<Session>,
    dim: Option<Dim>,
    entity: Option<i32>,
    live: bool,
}
static STATE: Mutex<Option<State>> = Mutex::new(None);
fn with<R>(f: impl FnOnce(&mut State) -> R) -> R {
    let mut guard = STATE.lock().unwrap_or_else(|e| e.into_inner());
    f(guard.get_or_insert_with(State::default))
}
fn alive(game: &Game<'_>) -> bool {
    game.remote.is_some()
        && !game.spectator()
        && game.player.as_ref().is_some_and(|p| p.health.health().is_finite() && p.health.health() > 0.0)
}
fn same(game: &Game<'_>, s: &State) -> bool {
    s.dim == Some(game.dim)
        && s.entity == game.remote.as_ref().map(|r| r.entity_id)
        && match (&s.session, &game.remote) {
            (Some(old), Some(remote)) => Arc::ptr_eq(old, &remote.session.counters),
            (None, None) => true,
            _ => false,
        }
}

// Cleanup may run after master-off, but must never apply an old connection's use state to a new scene.
pub(super) fn same_scene(game: &Game<'_>) -> bool { with(|s| same(game, s)) }
// Returns an identity change or live deactivation. Callers cancel transient
// state AFTER this invalidates stale tickets, preventing old-scene restoration.
pub(super) fn begin_tick(game: &Game<'_>) -> bool {
    let live = game.native_on(super::sunset::ID) && alive(game);
    with(|s| {
        let session = game.remote.as_ref().map(|r| r.session.counters.clone());
        let changed = !same(game, s) || (s.live && !live);
        if changed || !live {
            s.lease.clear();
        }
        s.live = live;
        s.session = session;
        s.dim = Some(game.dim);
        s.entity = game.remote.as_ref().map(|r| r.entity_id);
        s.lease.begin(game.ticks);
        changed
    })
}
// Master-off/Panic must restore still-owned slots before clearing the ledger.
// Preserve an EXISTING live ticket only; never resurrect or adopt a scene here.
pub(super) fn prepare_cleanup(game: &Game<'_>) {
    with(|s| {
        if !s.live || !alive(game) || !same(game, s) {
            s.lease.clear();
            s.live = false;
        }
    });
}
pub(super) fn claim(owner: &'static str) -> bool {
    with(|s| s.live && s.lease.claim(owner))
}
pub(super) fn owns(owner: &str) -> bool {
    with(|s| s.live && s.lease.owner == Some(owner))
}
pub(super) fn available(owner: &str) -> bool {
    with(|s| s.live && s.lease.owner.is_none_or(|current| current == owner))
}
pub(super) fn release(owner: &str) {
    with(|s| s.lease.release(owner));
}
pub(super) fn owner() -> Option<&'static str> {
    with(|s| s.lease.owner)
}
pub(super) fn reset() {
    with(|s| {
        s.lease.clear();
        s.session = None;
        s.dim = None;
        s.entity = None;
        s.live = false;
    });
}
#[must_use]
pub(super) struct Finish {
    owner: &'static str,
    ticket: Option<u64>,
}
impl Finish {
    pub(super) fn current(&self) -> bool {
        self.ticket.is_some() && with(|s| s.live && s.lease.ticket(self.owner) == self.ticket)
    }
}
impl Drop for Finish {
    fn drop(&mut self) {
        if let Some(ticket) = self.ticket {
            with(|s| s.lease.finish(self.owner, ticket));
        }
    }
}
pub(super) fn finish(owner: &'static str) -> Finish {
    Finish { owner, ticket: with(|s| s.lease.ticket(owner)) }
}

