            .bool("Double hand", false)
            .text("Double hand on", "anchors,crystals,obsidian,sword,mace")
            .num("Double hand sensitivity", 1.0, 0.5, 1.5, 0.05)
            .num("Reswap delay (ticks)", 1.0, 1.0, 10.0, 1.0)
            .bool("Totem on low health", false)
            .num("Totem health", 5.0, 1.0, 20.0, 0.5)
            .bool("Wait while shielding", true),
    ]
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Phase {
    Swap,
    Await,
}

// One Hover move: from the swap click to the server's confirmation.
struct Job {
    lease: control::Finish,
    owner: &'static str,
    settings: Module,
    slots: [usize; 2],
    before: [Option<ItemStack>; 2],
    menu: (i32, String),
    wire: [Option<usize>; 2],
    phase: Phase,
    began: Instant,
    swap: Option<Swap<ItemStack>>,
    unsafe_ticks: u8,
    revision: Option<i32>,
}

// Auto Totem (Offhand's Item Totem): while the offhand holds no totem and the main inventory or
// hotbar has one, one swap-with-offhand click on it (the first, or a random one with Random slot) in your inventory:
// the one open, else one opened for it (Open inventory; closed again with Close inventory), or with Silent open the
// inventory clicked with no screen, the look the server has held and your move keys and clicks held until a Silent
// move delay after it ends. Inventory only waits for you to open it. Each step waits a Totem delay, and a click waits
// to be seen (the slot changes, or 1.5 s) before the next; one that changed nothing is not tried again on the same
// slots.
#[derive(Default)]
struct Totem {
    due: Option<Instant>,
    pending: Option<Pending>,
    stall: Option<Vec<Option<ItemStack>>>,
    opened: bool,
    silent: bool,
    suppress: bool,
    action_at: Option<Instant>,
    look: Option<(f32, f32)>,
    took: bool,
    seed: u64,
    work: Option<Work>,
}

// What a tick asks of Auto Totem. Its clicks and closes go out in the next frame, after the tick's end packet, as a
// click on a screen does; Grim's PacketOrderO flags one sent between the tick's move
// and its end, where the tick's modules run.
enum Work {
    Step(Module),
    WindDown(Module),
    Stop,
}

struct Pending {
    slot: usize,
    expected: Option<ItemStack>,
    revision: Option<i32>,
    menu: i32,
    deadline: Instant,
}

impl Totem {
    fn active(&self) -> bool {
        self.opened || self.silent || self.pending.is_some()
    }

    fn next(&mut self) -> u64 {
        if self.seed == 0 {
            self.seed = 0x70e7_d1ce;
        }
        self.seed ^= self.seed << 13;
        self.seed ^= self.seed >> 7;
        self.seed ^= self.seed << 17;
        self.seed
    }

    fn unit(&mut self) -> f64 {
        (self.next() >> 11) as f64 / (1u64 << 53) as f64
    }

    // The next step's wait in ms: even across the range, or with Extra randomization a normal spread round its middle
    // (a quarter of the range each way), kept in the range, and an 18 % chance of a longer pause on top.
    fn delay(&mut self, (min, max): (u64, u64), extra: bool) -> u64 {
        let (min, max) = (min.min(max) as f64, min.max(max) as f64);
        if !extra {
            return (min + (max - min) * self.unit()).round() as u64;
        }
        let range = (max - min).max(1.0);
        let sd = (range / 4.0).max(1.0);
        let (u1, u2) = (self.unit().max(f64::MIN_POSITIVE), self.unit());
        let gaussian = (-2.0 * u1.ln()).sqrt() * (std::f64::consts::TAU * u2).cos();
        let mut wait = (min + range * 0.5 + gaussian * sd).clamp(min, max);
        if self.unit() < 0.18 {
            let (low, high) = ((range * 1.25).max(120.0), (range * 3.25).max(350.0));
            wait += low + (high - low) * self.unit();
        }
        wait.max(1.0).round() as u64
    }

    // Your keys stay held from the silent open until a Silent move delay (picked again each tick) after its last
    // click or tick.
    fn suppress_tick(&mut self, now: Instant, (min, max): (u64, u64)) -> bool {
        if self.suppress {
            let (low, high) = (min.min(max) as f64, min.max(max) as f64);
            let sample = (low + (high - low) * self.unit()) as u64;
            let elapsed = self.action_at.map_or(u64::MAX, |at| now.saturating_duration_since(at).as_millis() as u64);
            if elapsed >= sample {
                self.suppress = false;
            }
        }
        if self.silent {
            self.action_at = Some(now);
        }
        self.suppress
    }
}

type Session = (i32, super::Dim, Arc<dyn Any + Send + Sync>);

#[derive(Default)]
struct State {
    connection: Option<Session>,
    tick: u64,
    job: Option<Job>,
    failures: Vec<(&'static str, Failure<ItemStack>)>,
    next: u64,
    totem: Totem,
    // The tick a hit went out: a throw waits for the next one. (A use does not: the packets of a tick's use can go
    // on the wire as the next tick starts, and Throwables' next use is due then.)
    last_hit: Option<u64>,
    // Packets sent in a tick: (tick, count), for Burst's cap.
    sent: (u64, u32),
    burst: u32,
}

static STATE: Mutex<Option<State>> = Mutex::new(None);

fn state<R>(f: impl FnOnce(&mut State) -> R) -> R {
    let mut guard = STATE.lock().unwrap_or_else(|e| e.into_inner());
    f(guard.get_or_insert_with(State::default))
}

// A module turned on or off: its move in progress stops (the slot goes back, the inventory it opened closes).
pub(super) fn toggled(game: &mut Game<'_>, name: &str) {
    state(|s| s.job.take_if(|j| j.settings.name == name));
    if name == INV {
        totem_stop(game);
    }
}

fn reset() {
    for owner in OWNERS {
        sunset::cancel_turns(owner);
        control::release(owner);
    }
    state(|s| *s = State::default());
}

// Sunset off or gone: what is in progress is undone in this world, then everything dropped.
pub(super) fn cancel(game: &mut Game<'_>) {
    if state(|s| s.connection.as_ref().is_some_and(|old| same_session(game, old))) {
        totem_stop(game);
    }
    post_tick(game);
    reset();
}

fn session(game: &Game<'_>) -> Option<Session> {
    let r = game.remote.as_ref()?;
    Some((r.entity_id, game.dim, r.session.counters.clone()))
}

fn same_session(game: &Game<'_>, old: &Session) -> bool {
    game.remote.as_ref().is_some_and(|r| {
        r.entity_id == old.0 && game.dim == old.1 && Arc::as_ptr(&r.session.counters) as *const () == Arc::as_ptr(&old.2) as *const ()
    })
}

fn alive(game: &Game<'_>) -> bool {
    game.native_window()
        && game.native_on(sunset::ID)
        && game.remote.is_some()
        && !game.spectator()
        && !game.creative
        && !sunset::gui_open()
        && matches!(game.screen, Screen::Playing | Screen::Inventory)
        && game.selected < 9
        && game.player.as_ref().is_some_and(|p| p.health.health().is_finite() && p.health.health() > 0.0)
}

// Playing with nothing else going on: no menu, nothing carried, used or mined.
fn plain(game: &Game<'_>) -> bool {
    alive(game)
        && game.screen == Screen::Playing
        && game.remote_menu().0 == 0
        && game.carried.is_none()
        && game.using.is_none()
        && game.mining.is_none()
        && super::remote::sunset_remote::breaking(game).is_none()
}

fn stack(game: &mut Game<'_>, slot: usize) -> Option<ItemStack> {
    game.slot_mut(slot).clone()
}

fn is_totem(stack: &Option<ItemStack>) -> bool {
    stack.as_ref().is_some_and(|s| &*s.item == "minecraft:totem_of_undying" && s.count == 1)
}

fn slot_setting(m: &Module) -> usize {
    policy::delay(m.n("Hotbar slot"), 9).clamp(1, 9) as usize - 1
}

fn fail(game: &mut Game<'_>, job: Job) {
    state(|s| {
        s.failures.retain(|(owner, _)| *owner != job.owner);
        s.failures.push((job.owner, Failure { slots: job.slots, before: job.before }));
        s.next = game.ticks.saturating_add(4);
    });
}

// Starts moving `from` to `to` (the offhand or a hotbar slot) by one swap click.
fn schedule(game: &mut Game<'_>, m: &Module, owner: &'static str, from: usize, to: usize) -> bool {
    if from == to || !(to < 9 || to == OFFHAND) || game.carried.is_some() {
        return false;
    }
    let before = [stack(game, from), stack(game, to)];
    if !before.iter().flatten().all(|s| game.res.items().get(&s.item).is_some_and(|info| s.count > 0 && s.count <= info.max_stack)) {
        return false;
    }
    if before[0].is_none()
        || before[0] == before[1]
        || state(|s| s.failures.iter().any(|(o, f)| *o == owner && f.blocks([from, to], &before)))
    {
        return false;
    }
    let menu = game.remote_menu();
    let wire = [Game::menu_slot_index(&menu.1, from), Game::menu_slot_index(&menu.1, to)];
    if wire[0].is_none() || (to != OFFHAND && wire[1].is_none()) || !control::claim(owner) {
        return false;
    }
    let lease = control::finish(owner);
    if !lease.current() {
        return false;
    }
    state(|s| {
        s.job = Some(Job {
            lease,
            owner,
            settings: m.clone(),
            slots: [from, to],
            before,
            menu,
            wire,
            phase: Phase::Swap,
            began: Instant::now(),
            swap: None,
            unsafe_ticks: 0,
            revision: None,
        })
    });
    run_job(game, std::slice::from_ref(m));
    true
}

// One step of the move in progress. False: there is none.
fn run_job_step(game: &mut Game<'_>, mods: &[Module]) -> bool {
    let Some(mut job) = state(|s| s.job.take()) else {
        return false;
    };
    if !mods.iter().any(|m| m.on && m == &job.settings) {
        return true;
    }
    if !job.lease.current()
        || !alive(game)
        || game.remote_menu() != job.menu
        || game.carried.is_some()
        || (job.phase == Phase::Swap && game.inventory_target().0 != Some(job.slots[0]))
        // The server's 5 s at most to confirm, and a second more.
        || job.began.elapsed() > Duration::from_secs(6)
        || !control::claim(job.owner)
    {
        fail(game, job);
        return true;
    }
    match job.phase {
        Phase::Swap => {
            // A click in a menu while you move or sprint: a server may take it for cheating; wait up to 10 ticks.
            if !super::remote::sunset_combat_remote::quiet(game) {
                job.unsafe_ticks = job.unsafe_ticks.saturating_add(1);
                if job.unsafe_ticks > 10 {
                    fail(game, job);
                } else {
                    state(|s| s.job = Some(job));
                }
                return true;
            }
            if [stack(game, job.slots[0]), stack(game, job.slots[1])] != job.before {
                fail(game, job);
                return true;
            }
            job.swap = Swap::new(job.slots, job.before.clone(), game.ticks);
            if job.swap.is_none() {
                fail(game, job);
                return true;
            }
            job.phase = Phase::Await;
            job.began = Instant::now();
            job.revision = super::remote::sunset_combat_remote::container_state(game);
            let ([from, to], menu) = (job.slots, job.menu.clone());
            state(|s| s.job = Some(job));
            if !super::remote::sunset_combat_remote::swap_unpredicted(game, &menu, from, to)
                && let Some(job) = state(|s| s.job.take())
            {
                fail(game, job);
            }
        }
        Phase::Await => {
            let timeout = policy::confirmation_ticks(super::remote::sunset_combat_remote::latency(game));
            match job.swap.as_ref().map_or(Status::Rejected, |s| s.status(game.ticks, timeout)) {
                Status::Waiting => state(|s| s.job = Some(job)),
                Status::Confirmed => state(|s| s.next = game.ticks.saturating_add(1)),
                _ => fail(game, job),
            }
        }
    }
    true
}

// The steps already due this tick (at most 4); waiting for the server never spins.
fn run_job(game: &mut Game<'_>, mods: &[Module]) -> bool {
    let mut used = false;
    for _ in 0..4 {
        let before = state(|s| s.job.as_ref().map(|j| j.phase));
        if !run_job_step(game, mods) {
            break;
        }
        used = true;
        let next = state(|s| s.job.as_ref().map(|j| j.phase));
        if next.is_none_or(|phase| phase == Phase::Await || Some(phase) == before) {
            break;
        }
    }
    used
}

// The server's packets (copies, in order): what they say the swapped slots hold.
pub(super) fn packet(game: &Game<'_>, packet: &C) {
    if matches!(packet, C::Login(_) | C::Respawn(_) | C::Disconnect(_)) {
        state(|s| *s = State::default());
        return;
    }
    state(|s| {
        if !s.connection.as_ref().is_some_and(|old| same_session(game, old)) {
            return;
        }
        let Some(job) = s.job.as_mut().filter(|j| j.phase == Phase::Await) else {
            return;
        };
        let revision = match packet {
            C::ContainerSetSlot(p) if p.container == job.menu.0 => Some(p.state),
            C::ContainerSetContent(p) if p.container == job.menu.0 => Some(p.state),
            _ => None,
        };
        if let Some(revision) = revision {
            if job.revision.is_some_and(|previous| !policy::revision_current(previous, revision)) {
                return;
            }
            job.revision = Some(revision);
        }
        let Some(swap) = job.swap.as_mut() else {
            return;
        };
        match packet {
            C::ContainerSetSlot(p) if p.slot >= 0 => {
                for i in 0..2 {
                    if (p.container == job.menu.0 && job.wire[i] == Some(p.slot as usize))
                        || (p.container == 0 && policy::player_wire(job.slots[i]) == Some(p.slot as usize))
                    {
                        swap.observe(job.slots[i], &game.to_stack(&p.item));
                    }
                }
            }
            C::ContainerSetContent(p) => {
                for i in 0..2 {
                    let wire = if p.container == job.menu.0 {
                        job.wire[i]
                    } else if p.container == 0 {
                        policy::player_wire(job.slots[i])
                    } else {
                        None
                    };
                    if let Some(item) = wire.and_then(|wire| p.items.get(wire)) {
                        swap.observe(job.slots[i], &game.to_stack(item));
                    }
                }
                if p.carried.is_some() {
                    swap.reject();
                }
            }
            C::SetPlayerInventory(p) => {
                if let Some(slot) = policy::player_internal(p.slot) {
                    swap.observe(slot, &game.to_stack(&p.item));
                }
            }
            C::SetCursorItem(p) if p.item.is_some() => swap.reject(),
            C::OpenScreen(_) => swap.reject(),
            _ => {}
        }
    });
}

// Offhand: the item it wants by quick clicks, a totem by Auto Totem, and Hover.
fn offhand(game: &mut Game<'_>, m: &Module) -> bool {
    use super::sunset_combat::Want;
    let want = super::sunset_combat::offhand_want(game, m);
    let totem = matches!(want, Want::Totem);
    if !totem {
        state(|s| s.totem.work = Some(Work::WindDown(m.clone())));
    }
    if let Want::Item(item) = want {
        super::sunset_combat::offhand_click(game, m, item);
    }
    (totem && auto_totem(game, m)) || (m.b("Hover") && hover(game, m))
}

// The totems Show totem count puts beside Offhand in the module list: the main inventory's, the hotbar's and the
// offhand's.
static TOTEMS: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);

pub(super) fn totem_count() -> u32 {
    TOTEMS.load(Ordering::Relaxed)
}

fn count_totems(game: &Game<'_>) -> u32 {
    let totems = |s: &Option<ItemStack>| s.as_ref().filter(|s| &*s.item == "minecraft:totem_of_undying").map_or(0, |s| s.count);
    game.inventory.iter().take(36).map(totems).sum::<u32>() + totems(&game.offhand)
}

// The player's own inventory, shown: Auto Totem opens it as the game does.
fn open_inventory(game: &mut Game<'_>) {
    game.reset_inventory_clicks();
    game.screen = Screen::Inventory;
    game.capture(false);
}

pub(super) fn close_inventory(game: &mut Game<'_>) {
    game.close_container();
    game.screen = Screen::Playing;
    game.capture(true);
}

// The slots and the carried stack: a click that changed nothing is not tried again while they stay so.
fn contents(game: &Game<'_>) -> Vec<Option<ItemStack>> {
    game.inventory.iter().take(36).cloned().chain([game.offhand.clone(), game.carried.clone()]).collect()
}

// The swap-with-offhand click (SWAP, button 40) on `slot`: the game's own click, predicted here and numbered with its
// menu state. Never on a locked slot.
fn swap_to_offhand(game: &mut Game<'_>, slot: usize) -> bool {
    !super::sunset_loadouts::locked(slot)
        && game.remote_menu_ops(&[(Some(slot), 40, horizon_client::menu::Input::Swap)])
}

// A silent session ends: the server's look goes back to yours, and the inventory it used is closed on the server
// (not when a container took its place: that container's close does it).
fn end_silent(game: &mut Game<'_>, t: &mut Totem, now: Instant, close: bool) {
    t.silent = false;
    t.look = None;
    t.action_at = Some(now);
    sunset::cancel_turns(INV);
    control::release(INV);
    if close && game.remote_menu().0 == 0 {
        game.close_container();
    }
}

// Equipped, no totems, or stalled: the inventory Auto Totem opened closes, a silent session ends.
fn wind_down(game: &mut Game<'_>, m: &Module, t: &mut Totem, now: Instant) -> bool {
    if t.silent {
        end_silent(game, t, now, true);
        return true;
    }
    let opened = std::mem::take(&mut t.opened);
    if opened && m.b("Close inventory") && game.screen == Screen::Inventory && game.remote_menu().0 == 0 {
        close_inventory(game);
        return true;
    }
    false
}

// One step; true when it did something (opened, clicked, closed).
fn totem_step(game: &mut Game<'_>, m: &Module, t: &mut Totem, now: Instant) -> bool {
    let container = game.remote_menu().0;
    let screen = game.screen == Screen::Inventory;
    // Another window: Auto Totem waits; a silent session ends there.
    if t.silent && container != 0 {
        t.pending = None;
        end_silent(game, t, now, false);
        return true;
    }
    if t.pending.as_ref().is_some_and(|p| p.menu != container) || (t.opened && !t.silent && !screen && t.pending.is_some()) {
        totem_cancel(game, t, now);
        return false;
    }
    if let Some(p) = &t.pending {
        if stack(game, p.slot) != p.expected || game.carried.is_some() {
            t.pending = None;
        } else if super::remote::sunset_combat_remote::container_state(game) != p.revision || now >= p.deadline {
            t.pending = None;
            t.stall = Some(contents(game));
        } else {
            return false;
        }
    }
    if container != 0 {
        return false;
    }
    if t.stall.as_ref().is_some_and(|c| *c == contents(game)) || is_totem(&game.offhand) {
        return wind_down(game, m, t, now);
    }
    let sources: Vec<usize> = (9..36).chain(0..9).filter(|&i| is_totem(&game.inventory[i]) && !super::sunset_loadouts::locked(i)).collect();
    if sources.is_empty() {
        return wind_down(game, m, t, now);
    }
    if !(screen || t.silent) {
        if m.b("Inventory only") || !m.b("Open inventory") {
            return false;
        }
        if m.b("Silent open") {
            // Another module has the hand or the look: not now.
            if !control::claim(INV) {
                return false;
            }
            (t.silent, t.suppress, t.action_at, t.look) = (true, true, Some(now), Some((game.yaw, game.pitch)));
            return true;
        }
        t.opened = true;
        open_inventory(game);
        return true;
    }
    if game.carried.is_some() {
        return false;
    }
    let source = if m.b("Random slot") { sources[(t.next() % sources.len() as u64) as usize] } else { sources[0] };
    let (expected, revision) = (stack(game, source), super::remote::sunset_combat_remote::container_state(game));
    if !swap_to_offhand(game, source) {
        return false;
    }
    t.pending = Some(Pending { slot: source, expected, revision, menu: container, deadline: now + Duration::from_millis(1500) });
    if t.silent {
        t.action_at = Some(now);
    }
    true
}

fn totem_cancel(game: &mut Game<'_>, t: &mut Totem, now: Instant) {
    t.pending = None;
    t.opened = false;
    if t.silent {
        end_silent(game, t, now, true);
    }
}

// Each tick with Item Totem: the next frame's step, and the look a silent session holds. True while a step is under
// way.
fn auto_totem(game: &mut Game<'_>, m: &Module) -> bool {
    TOTEMS.store(count_totems(game), Ordering::Relaxed);
    let (look, active) = state(|s| {
        s.totem.work = Some(Work::Step(m.clone()));
        (s.totem.look, s.totem.active())
    });
    if let Some((yaw, pitch)) = look {
        sunset::turn(INV, yaw, pitch);
    }
    active
}

// A step once its Totem delay is over.
fn totem_frame(game: &mut Game<'_>, m: &Module) {
    let now = Instant::now();
    let mut t = state(|s| std::mem::take(&mut s.totem));
    if t.due.is_none_or(|due| now >= due) {
        let acted = totem_step(game, m, &mut t, now);
        let range = (m.n("Shortest totem delay (ms)") as u64, m.n("Longest totem delay (ms)") as u64);
        let wait = t.delay(range, m.b("Extra randomization"));
        t.due = (acted || t.active()).then(|| now + Duration::from_millis(wait));
    }
    state(|s| s.totem = t);
}

// Each frame: what the last tick asked of Auto Totem, in the world it was asked in.
pub(super) fn frame(game: &mut Game<'_>) {
    if super::sunset_gui_move::inventory_busy() { return; }
    let Some(work) = state(|s| s.totem.work.take()) else {
        return;
    };
    if !alive(game) || !state(|s| s.connection.as_ref().is_some_and(|old| same_session(game, old))) {
        return;
    }
    match work {
        Work::Step(m) => totem_frame(game, &m),
        Work::WindDown(m) => totem_wind_down(game, &m),
        Work::Stop => totem_stop(game),
    }
}

// Another Item, or Offhand off: what Auto Totem opened closes.
fn totem_wind_down(game: &mut Game<'_>, m: &Module) {
    let mut t = state(|s| std::mem::take(&mut s.totem));
    if t.active() {
        t.pending = None;
        wind_down(game, m, &mut t, Instant::now());
    }
    t.due = None;
    state(|s| s.totem = t);
}

fn totem_stop(game: &mut Game<'_>) {
    let mut t = state(|s| std::mem::take(&mut s.totem));
    if t.opened && game.screen == Screen::Inventory && game.remote_menu().0 == 0 && game.carried.is_none() {
        close_inventory(game);
    }
    totem_cancel(game, &mut t, Instant::now());
    state(|s| s.totem = Totem { seed: t.seed, took: t.took, ..Totem::default() });
}

// Before the game's tick: Silent open's hold on your move keys and clicks.
pub(super) fn pre_tick(game: &mut Game<'_>, m: Option<&Module>) {
    let held = state(|s| match m {
        Some(m) => {
            let range = (m.n("Shortest silent move delay (ms)") as u64, m.n("Longest silent move delay (ms)") as u64);
            s.totem.suppress_tick(Instant::now(), range)
        }
        None => std::mem::take(&mut s.totem.suppress),
    });
    if held && m.is_some() {
        for k in HELD_KEYS {
            game.keys.remove(&k);
        }
        (game.left, game.right) = (false, false);
        state(|s| s.totem.took = true);
    }
}

const HELD_KEYS: [winit::keyboard::KeyCode; 6] = {
    use winit::keyboard::KeyCode::*;
    [KeyW, KeyA, KeyS, KeyD, Space, ControlLeft]
};

// After the game's tick: the keys and clicks held go back to what you hold.
pub(super) fn post_tick(game: &mut Game<'_>) {
    if state(|s| std::mem::take(&mut s.totem.took)) {
        give_back(game);
    }
}

fn give_back(game: &mut Game<'_>) {
    use winit::event::MouseButton;
    for k in HELD_KEYS {
        if game.physical_keys.contains(&k) {
            game.keys.insert(k);
        }
    }
    game.left = game.physical_buttons.contains(&MouseButton::Left);
    game.right = game.physical_buttons.contains(&MouseButton::Right);
}

fn hover(game: &mut Game<'_>, m: &Module) -> bool {
    if game.screen != Screen::Inventory || game.carried.is_some() {
        return false;
    }
    let menu = game.remote_menu();
    let Some(from) = game.inventory_target().0.filter(|s| *s != OFFHAND && *s != 200 && Game::menu_slot_index(&menu.1, *s).is_some())
    else {
        return false;
    };
    if !is_totem(&stack(game, from)) {
        return false;
    }
    let to = if !is_totem(&game.offhand) {
        OFFHAND
    } else if m.b("Hotbar refill") {
        slot_setting(m)
    } else {
        return false;
    };
    !is_totem(&stack(game, to)) && schedule(game, m, HOVER, from, to)
}

fn can_use(game: &Game<'_>, item: &ItemStack) -> bool {
    let Some(info) = game.res.items().get(&item.item) else {
        return false;
    };
    item.count > 0 && !game.cooldowns.is_on_cooldown(&horizon_client::cooldowns::group(item, info.use_cooldown.as_ref()))
}

// What Fast Use's Throwables throw faster: an experience bottle, ender pearl, wind charge, snowball or egg, or splash
// or lingering potion in hand as its settings say, off cooldown (a use on cooldown still sends its packet); with Off
// hand, one in the offhand while the hand is empty or holds a weapon (the game tries the main hand first).
pub(super) fn thrown_in_hand(game: &Game<'_>, m: &Module) -> bool {
    if !m.b("Throwables") {
        return false;
    }
    let wanted = |s: &ItemStack| {
        let ticked = match util::short(&s.item) {
            "experience_bottle" => m.b("Experience bottles"),
            "ender_pearl" => m.b("Ender pearls"),
            "wind_charge" => m.b("Wind charges"),
            "snowball" | "egg" | "blue_egg" | "brown_egg" => m.b("Snowballs and eggs"),
            "splash_potion" | "lingering_potion" => m.b("Splash potions"),
            _ => false,
        };
        ticked && can_use(game, s)
    };
    let main = game.inventory[game.selected].as_ref();
    let weapon = main.is_none_or(|s| ["_sword", "_axe", "_spear", ":mace", ":trident"].iter().any(|w| s.item.ends_with(w)));
    main.is_some_and(wanted) || (m.b("Off hand") && weapon && game.offhand.as_ref().is_some_and(wanted))
}

fn holding_use(game: &Game<'_>) -> bool {
    game.right || game.physical_buttons.contains(&winit::event::MouseButton::Right)
}

// Throwables: the game's own use, with its use delay cut to Throw delay (Delay) or one tick (Every tick, Burst); it
// waits while a look is on its way or another module has the hand. (A use this tick was the game's own: the next one
// is a tick away, and the use hook holds it back if something else goes out first.)
fn fast_xp(game: &mut Game<'_>, m: &Module) {
    if !plain(game) || game.left || !holding_use(game) || !thrown_in_hand(game, m) {
        return;
    }
    if sunset::turn_pending() || !control::available(XP) {
        game.use_delay = game.use_delay.max(2);
        return;
    }
    game.use_delay = match m.p("Throw mode") {
        "Delay" => game.use_delay.min(m.n("Throw delay") as u32),
        _ => 1,
    };
}

// The use hook: Throwables hold back a use the tick it must wait.
pub(super) fn intercept_use(game: &mut Game<'_>) -> bool {
    if !plain(game) || !holding_use(game) || !with(|s| s.module(XP).is_some_and(|m| m.on && thrown_in_hand(game, m))) {
        return false;
    }
    let blocked = sunset::turn_pending() || !control::available(XP) || state(|s| s.last_hit == Some(game.ticks));
    if blocked {
        game.use_delay = game.use_delay.max(2);
    }
    blocked
}

// Burst: the uses the game's own one brings with it this tick, each as one more click would be (so before the
// tick's move packet), while the tick has sent fewer than BURST_CAP packets. A use aimed at a block is three (the use
// on it, the use, the swing), so a tick sends at most 7 + 3 + the game's own 3 + its move and end: 15, 300 a second,
// well under the 500 a second Paper allows. Only throwables without a cooldown.
static BURSTING: AtomicBool = AtomicBool::new(false);
const BURST_CAP: u32 = 8;

pub(super) fn bursting() -> bool {
    BURSTING.load(Ordering::Relaxed)
}

pub(super) fn burst_more(game: &Game<'_>) -> bool {
    let Some(m) = with(|s| s.module(XP).filter(|m| m.on && m.p("Throw mode") == "Burst").cloned()) else {
        return false;
    };
    let item = game.held().filter(|s| s.count > 1).map(|s| util::short(&s.item).to_owned());
    let free = item.is_some_and(|i| matches!(i.as_str(), "experience_bottle" | "snowball" | "egg" | "blue_egg" | "brown_egg" | "splash_potion" | "lingering_potion"));
    let more = free
        && plain(game)
        && thrown_in_hand(game, &m)
        && state(|s| {
            let sent = if s.sent.0 == game.ticks { s.sent.1 } else { 0 };
            if !bursting() {
                s.burst = 0;
            }
            s.burst += 1;
            s.burst < m.n("Burst") as u32 && sent < BURST_CAP
        });
    BURSTING.store(more, Ordering::Relaxed);
    more
}

// What went on the wire: hits, and every packet for Burst's count.
pub(super) fn forwarded(game: &Game<'_>, packet: &S) {
    let hit = matches!(packet, S::Attack(_));
    state(|s| {
        if !s.connection.as_ref().is_some_and(|old| same_session(game, old)) {
            return;
        }
        if hit {
            s.last_hit = Some(game.ticks);
        }
        s.sent = if s.sent.0 == game.ticks { (game.ticks, s.sent.1 + 1) } else { (game.ticks, 1) };
    });
}

pub(super) fn tick(game: &mut Game<'_>, mods: &[Module]) {
    if !alive(game) {
        cancel(game);
        return;
    }
    if super::sunset_gui_move::inventory_busy() { return; }
    let ticks = game.ticks;
    if state(|s| s.connection.as_ref().is_none_or(|old| !same_session(game, old)) || ticks < s.tick) {
        reset();
        state(|s| s.connection = session(game));
    }
    state(|s| s.tick = ticks);
    let get = |name: &str| mods.iter().find(|m| m.name == name && m.on);
    if run_job(game, mods) {
        return;
    }
    if ticks < state(|s| s.next) {
        return;
    }
    if let Some(m) = get(INV) {
        if offhand(game, m) {
            return;
        }
    } else if state(|s| s.totem.active()) {
        state(|s| s.totem.work = Some(Work::Stop));
    }
    if let Some(m) = get(XP).filter(|m| m.b("Throwables")) {
        fast_xp(game, m);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn totem_delays_stay_in_range_with_an_occasional_long_pause() {
        let mut t = Totem::default();
        let even: Vec<_> = (0..200).map(|_| t.delay((100, 120), false)).collect();
        assert!(even.iter().all(|d| (100..=120).contains(d)));
        let spread: Vec<_> = (0..400).map(|_| t.delay((100, 120), true)).collect();
        assert!(spread.iter().all(|d| *d >= 100 && *d <= 120 + 350));
        assert!(spread.iter().any(|d| *d > 200), "occasional long pause");
        assert!(spread.iter().filter(|d| **d <= 120).count() > 250);
        // A random slot reaches every one of them.
        let picked: std::collections::BTreeSet<_> = (0..32).map(|_| t.next() % 2).collect();
        assert_eq!(picked.len(), 2);
    }

    #[test]
    fn silent_open_holds_keys_until_a_move_delay_after_the_session() {
        let start = Instant::now();
        let mut t = Totem { silent: true, suppress: true, action_at: Some(start), ..Totem::default() };
        // A session renews its time each tick (50 ms apart): held all through it.
        for tick in 0..=8 {
            assert!(t.suppress_tick(start + Duration::from_millis(tick * 50), (150, 150)), "held all session");
        }
        let end = start + Duration::from_millis(400);
        t.silent = false;
        t.action_at = Some(end);
        assert!(t.suppress_tick(end + Duration::from_millis(140), (150, 150)));
        assert!(!t.suppress_tick(end + Duration::from_millis(150), (150, 150)));
        assert!(!t.suppress_tick(end + Duration::from_millis(160), (150, 150)), "released for good");
    }
}

// The owner combat_control.rs keeps: claimed each tick it is used, dropped when it lapses.
#[derive(Default)]
pub(super) struct Lease {
    pub owner: Option<&'static str>,
    tick: u64,
    seen: u64,
    ticket: u64,
}
impl Lease {
    pub fn begin(&mut self, tick: u64) {
        if tick < self.tick || tick.saturating_sub(self.seen) > 10 {
            self.clear();
        }
        self.tick = tick;
    }
    pub fn claim(&mut self, owner: &'static str) -> bool {
        if self.owner.is_some_and(|current| current != owner) {
            return false;
        }
        if self.owner.is_none() {
            self.ticket = self.ticket.wrapping_add(1);
        }
        self.owner = Some(owner);
        self.seen = self.tick;
        true
    }
    pub fn release(&mut self, owner: &str) {
        if self.owner == Some(owner) {
            self.clear();
        }
    }
    pub fn clear(&mut self) {
        self.owner = None;
        self.ticket = self.ticket.wrapping_add(1);
    }
    pub fn ticket(&self, owner: &str) -> Option<u64> {
        (self.owner == Some(owner)).then_some(self.ticket)
    }
    pub fn finish(&mut self, owner: &str, ticket: u64) {
        if self.ticket(owner) == Some(ticket) {
            self.clear();
        }
    }
}

// Crystal Aura's and Anchor Aura's Macro (Rust's Crystal Macro and Anchor Macro, PR #16): a right click with a crystal
// or anchor does the whole place and break (or place, charge, set off) as fast as the server takes it. Each starts from
// your own click, at what you look at. Its settings are the aura module's, while that module's Macro section is on.
use super::sunset::{self, Module, gui_open, hold, with};
use super::sunset_explosive_damage::{Blast, clear_line, observed_local_damage};
use super::sunset_explosive_policy::{Budget, in_range};
use super::sunset_macro_policy::{self as policy, Kind, Sequence, Step, Wait};
use super::sunset_util::{self as util, OFFHAND};
use super::{Dim, Game};
use horizon_protocol::{
    connection::Counters,
    packets::{
        Empty,
        play::{self, Serverbound as S},
    },
};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use winit::event::MouseButton;

// The owners of the hotbar and look while a macro runs (sunset_combat_control), and the modules they are sections of.
const CRYSTAL: &str = "Crystal Macro";
const ANCHOR: &str = "Anchor Macro";
const CRYSTAL_MODULE: &str = "Crystal Aura";
const ANCHOR_MODULE: &str = "Anchor Aura";
const MACRO: &str = "Macro";
type Session = Arc<Mutex<Option<Arc<Counters>>>>;

// The settings of `owner`'s macro: its module, while on with the Macro section on.
fn macro_module(owner: &str) -> Option<Module> {
    let name = if owner == ANCHOR { ANCHOR_MODULE } else { CRYSTAL_MODULE };
    with(|s| s.module(name).filter(|m| m.on && m.b(MACRO)).cloned())
}

#[derive(Clone, Copy, Debug)]
struct Click {
    pos: [i32; 3],
    face: i32,
    hit: [f64; 3],
}
#[derive(Clone, Copy, Debug)]
enum Action {
    Use { step: Step, click: Click, slot: usize, select: Option<usize>, destination: [i32; 3], before: u32 },
    Attack { id: u32, at: [f64; 3], aim: [f64; 3], slot: usize },
}
impl Action {
    fn step(self) -> Step {
        match self {
            Self::Use { step, .. } => step,
            Self::Attack { .. } => Step::CrystalBreak,
        }
    }
    fn aim(self) -> [f64; 3] {
        match self {
            Self::Use { click, .. } => click.hit,
            Self::Attack { aim, .. } => aim,
        }
    }
}
#[derive(Clone)]
struct Run {
    owner: &'static str,
    settings: Arc<Module>,
    sequence: Sequence,
    pos: [i32; 3],
    previous: usize,
    owned: usize,
    session: Session,
    entity: i32,
    dimension: Dim,
    pending: Option<(Action, Option<u64>)>,
    ready: u64,
    crystal: Option<u32>,
    guard: Option<[i32; 3]>,
    token: u64,
    queued_at: Option<Instant>,
    deadline: u64,
    replace_click: Option<Click>,
    guard_block: Option<u32>,
    guard_tries: u8,
    guard_confirmed: bool,
}
struct AnchorPress {
    tick: u64,
    session: Session,
    entity: i32,
    dimension: Dim,
    start_allowed: bool,
}
struct State {
    run: Option<Run>,
    anchor_press: Option<AnchorPress>,
    token: u64,
    anchor_latched: bool,
    retries: policy::Retries,
    last_session: Option<Session>,
    last_deed: Option<u64>,
    pace_gap: u64,
    random: u64,
    main: Option<(usize, Option<horizon_client::items::ItemStack>, u64)>,
    // Wait for hurt time: the run whose second anchor waits, and since when.
    hurt_wait: Option<(u64, u64)>,
}
static STATE: Mutex<State> = Mutex::new(State {
    run: None,
    anchor_press: None,
    token: 0,
    anchor_latched: false,
    retries: policy::Retries::new(),
    last_session: None,
    last_deed: None,
    pace_gap: 0,
    random: 0,
    main: None,
    hurt_wait: None,
});
fn state<R>(f: impl FnOnce(&mut State) -> R) -> R {
    f(&mut STATE.lock().unwrap_or_else(|e| e.into_inner()))
}
static USER_RIGHT: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
pub(super) fn user_mouse(game: &Game<'_>, button: MouseButton, pressed: bool) {
    if button == MouseButton::Right {
        let user = !pressed
            || (super::sunset_combat_control::owner().is_none_or(|o| o == CRYSTAL || o == ANCHOR)
                && game.native_playing()
                && !gui_open());
        if user {
            USER_RIGHT.store(pressed, std::sync::atomic::Ordering::Relaxed);
        }
        // Retain a guard-only quick edge even while inventory/lease conditions
        // pause macro startup. It can consume a protected anchor fallback, but
        // cannot become a delayed macro start after the pause clears.
        if pressed && game.native_playing() && game.native_on(sunset::ID) && !gui_open() {
            if let Some(remote) = game.remote.as_ref() {
                state(|s| {
                    s.anchor_press = Some(AnchorPress {
                        tick: game.ticks,
                        session: remote.session.counters.clone(),
                        entity: remote.entity_id,
                        dimension: game.dim,
                        start_allowed: user && allowed(game) && anchor_can_click(game),
                    })
                });
            }
        }
    }
}
pub(super) fn focus_lost() {
    USER_RIGHT.store(false, std::sync::atomic::Ordering::Relaxed);
    state(|s| s.anchor_press = None);
}
fn physical_use(game: &Game<'_>) -> bool {
    let bound = game.settings.keys.get("key.use");
    if let Some(button) = horizon_client::keybinds::mouse_button(bound) {
        return game.physical_buttons.contains(&button);
    }
    horizon_client::keybinds::key_code(bound).is_some_and(|key| game.physical_keys.contains(&key))
}
fn down(game: &Game<'_>) -> bool {
    // play_mouse receives canonical Right after native rebinding for keyboard,
    // mouse and ctl. Its shadow preserves quick edges without another key hook.
    physical_use(game) || USER_RIGHT.load(std::sync::atomic::Ordering::Relaxed)
}

// The native use path reads canonical Sneak, which includes rebound keys and
// ToggleKeyMapping state. Raw physical Shift is a screen modifier, not this.
fn anchor_can_click(game: &Game<'_>) -> bool {
    !game.keys.contains(&winit::keyboard::KeyCode::ShiftLeft)
}
fn allowed(game: &Game<'_>) -> bool {
    game.native_window()
        && game.native_on(sunset::ID)
        && util::in_world(game)
        && !gui_open()
        && !game.spectator()
        && game.riding.is_none()
        && game.selected < 9
        && game.using.is_none()
        && game.mining.is_none()
        && !game.left
        && !super::sunset_player::gap_eating()
        && util::inventory_idle(game)
        && !with(|s| ["Blink", "Auto EXP"].iter().any(|n| s.is_on(n)))
        && game.player.as_ref().is_some_and(|p| p.health.health().is_finite() && p.health.health() > 0.)
        && game.mobs.len() <= 256
        && game.crystals.len() <= 256
}
fn same_session(game: &Game<'_>, run: &Run) -> bool {
    game.dim == run.dimension
        && game
            .remote
            .as_ref()
            .is_some_and(|r| r.entity_id == run.entity && Arc::ptr_eq(&r.session.counters, &run.session))
}
fn enabled(run: &Run) -> bool {
    macro_module(run.owner).is_some_and(|m| &m == run.settings.as_ref())
}

// Explicit OFF/ON transitions invalidate the previous accepted manual intent.
// Another macro's current sequence is independent and must retain its lease.
pub(super) fn toggled(game: &mut Game<'_>, name: &str, _on: bool) {
    let name = match name {
        CRYSTAL_MODULE => CRYSTAL,
        ANCHOR_MODULE => ANCHOR,
        _ => return,
    };
    if state(|s| s.run.as_ref().is_some_and(|run| run.owner == name)) {
        reset(game);
    }
    state(|s| {
        if name == ANCHOR {
            s.anchor_press = None;
            s.anchor_latched = false;
        }
        if name == CRYSTAL {
            s.retries.clear();
            s.last_deed = None;
            s.pace_gap = 0;
            s.main = None;
        }
    });
}

// GUI/death/world transitions cancel the transaction; restoration is allowed
// only while the same session and selected slot are still owned by this run.
pub(super) fn reset(game: &mut Game<'_>) {
    let run = state(|s| {
        s.token = s.token.wrapping_add(1);
        s.anchor_press = None;
        s.run.take()
    });
    sunset::cancel_turns(CRYSTAL);
    sunset::cancel_turns(ANCHOR);
    if let Some(run) = run {
        if super::sunset_combat_control::owns(run.owner)
            && same_session(game, &run)
            && game.using.is_none()
            && !super::sunset_player::gap_eating()
        {
            if let Some(previous) =
                policy::restore(run.previous, run.owned, game.selected, run.settings.b("Switch back"))
            {
                hold(game, previous);
            }
        }
        super::sunset_combat_control::release(run.owner);
    }
}
fn complete(game: &mut Game<'_>) {
    let anchor = state(|s| {
        s.run
            .as_ref()
            .is_some_and(|r| r.sequence.kind == Kind::Anchor && r.sequence.step == Step::Done && same_session(game, r))
    });
    reset(game);
    if anchor {
        state(|s| s.anchor_latched = false);
    }
}
pub(super) fn active() -> bool {
    state(|s| s.run.is_some())
}

fn stack(game: &Game<'_>, slot: usize, name: &str) -> bool {
    let stack = if slot == OFFHAND { game.offhand.as_ref() } else { game.inventory.get(slot).and_then(|v| v.as_ref()) };
    stack.is_some_and(|s| s.count > 0 && util::short(&s.item) == name)
}
fn item_slot(game: &Game<'_>, name: &str) -> Option<usize> {
    util::find_held(game, |n| n == name).filter(|&slot| stack(game, slot, name))
}

// Unknown runtime components cannot establish that main-hand use passes.
// Native item prototypes provide the ordinary component facts. Cosmetic and
// durability wire additions do not alter use; removals are conservatively unknown.
fn known_click_patch(stack: &horizon_client::items::ItemStack) -> bool {
    if stack.extra.as_ref().is_some_and(|extra| !extra.other.is_empty()) {
        return false;
    }
    let Some(patch) = stack.wire_patch() else {
        return true;
    };
    use horizon_protocol::{buf::Reader, item::component as c};
    let mut reader = Reader::new(&patch);
    let Ok(added) = reader.count(64) else {
        return false;
    };
    if reader.count(64).ok() != Some(0) {
        return false;
    }
    for _ in 0..added {
        let Ok(kind) = reader.varint() else {
            return false;
        };
        if !matches!(
            kind,
            c::DAMAGE
                | c::ENCHANTMENTS
                | c::CUSTOM_NAME
                | c::ITEM_NAME
                | c::LORE
                | c::REPAIR_COST
                | c::ITEM_MODEL
                | c::CUSTOM_MODEL_DATA
                | c::TOOLTIP_DISPLAY
                | c::ENCHANTMENT_GLINT_OVERRIDE
        ) {
            return false;
        }
        let Ok(length) = reader.count(reader.remaining()) else {
            return false;
        };
        if reader.bytes(length).is_err() {
            return false;
        }
    }
    reader.remaining() == 0
}
fn click_facts(game: &Game<'_>, slot: usize) -> policy::ClickFacts {
    let Some(stack) = game.inventory.get(slot).and_then(|stack| stack.as_ref()).filter(|s| s.count > 0) else {
        return policy::ClickFacts { empty: true, ..Default::default() };
    };
    let Some(info) = game.items().get(&stack.item) else {
        return policy::ClickFacts::default();
    };
    let has = |name: &str| info.components.iter().any(|component| component == name);
    let tag = |name: &str| game.items().item_tags.get(name).is_some_and(|items| items.contains(&*stack.item));
    policy::ClickFacts {
        empty: false,
        known: known_click_patch(stack),
        consuming: has("minecraft:consumable"),
        blocking: has("minecraft:blocks_attacks"),
        kinetic: has("minecraft:kinetic_weapon"),
        equip_swap: info.equip_slot.is_some() && info.swappable,
        sword: tag("minecraft:swords"),
        axe: tag("minecraft:axes"),
        mace: util::short(&stack.item) == "mace",
        totem: util::short(&stack.item) == "totem_of_undying",
    }
}
fn crystal_route(game: &Game<'_>, name: &str, base: bool, preferred: usize) -> Option<policy::UseRoute> {
    policy::placement_route(
        game.selected,
        preferred,
        std::array::from_fn(|slot| stack(game, slot, name)),
        std::array::from_fn(|slot| policy::click_through(click_facts(game, slot), base)),
        stack(game, OFFHAND, name),
    )
}
fn crystal_use_action(
    game: &Game<'_>,
    run: &Run,
    step: Step,
    click: Click,
    name: &str,
    destination: [i32; 3],
) -> Option<Action> {
    let base = matches!(util::short(&util::facts(game, click.pos).name), "obsidian" | "bedrock");
    let route = crystal_route(game, name, base, run.previous)?;
    let selected = route.select.unwrap_or(game.selected);
    Some(Action::Use {
        step,
        click,
        select: route.select,
        slot: if route.offhand { OFFHAND } else { selected },
        destination,
        before: game.world.block(destination[0], destination[1], destination[2]).0,
    })
}

fn anchor_charge(game: &Game<'_>, p: [i32; 3]) -> Option<u8> {
    if !game.world.loaded(p[0], p[2]) {
        return None;
    }
    let b = game.world.block(p[0], p[1], p[2]);
    if !game.is_anchor(b) {
        return None;
    }
    game.pack.assets.registry.state(b)?.properties.get("charges")?.parse::<u8>().ok().filter(|n| *n <= 4)
}
fn center(p: [i32; 3], crystal: bool) -> [f64; 3] {
    [f64::from(p[0]) + 0.5, f64::from(p[1]) + if crystal { 1. } else { 0.5 }, f64::from(p[2]) + 0.5]
}
fn name_is(game: &Game<'_>, p: [i32; 3], name: &str) -> bool {
    util::short(&util::facts(game, p).name) == name
}
fn inert(game: &Game<'_>, p: [i32; 3]) -> bool {
    game.world.loaded(p[0], p[2])
        && util::facts(game, p).full_collision
        && matches!(
            util::short(&util::facts(game, p).name),
            "stone"
                | "cobblestone"
                | "obsidian"
                | "crying_obsidian"
                | "bedrock"
                | "deepslate"
                | "cobbled_deepslate"
                | "dirt"
                | "grass_block"
                | "netherrack"
                | "end_stone"
                | "netherite_block"
        )
}
fn visible(game: &Game<'_>, click: Click, budget: &mut Budget) -> bool {
    let Some(eye) = game.eye_position() else {
        return false;
    };
    let Some(end) = policy::outside(click.hit, click.face) else {
        return false;
    };
    let Some((range, _)) = super::sunset_explosive_tactics::interaction_ranges(game) else {
        return false;
    };
    game.world.loaded(click.pos[0], click.pos[2])
        && in_range(eye, click.hit, range)
        && clear_line(game, eye, end, None, budget)
}
fn support(game: &Game<'_>, p: [i32; 3], budget: &mut Budget) -> Option<Click> {
    if !game.world.loaded(p[0], p[2]) || !util::can_place(game, p, true) {
        return None;
    }
    for (d, face) in [([0, -1, 0], 1), ([0, 1, 0], 0), ([0, 0, -1], 3), ([0, 0, 1], 2), ([-1, 0, 0], 5), ([1, 0, 0], 4)]
    {
        let n = std::array::from_fn(|i| p[i] + d[i]);
        if !inert(game, n) {
            continue;
        }
        let hit = std::array::from_fn(|i| f64::from(n[i]) + 0.5 - f64::from(d[i]) * 0.5);
        let click = Click { pos: n, face, hit };
        if visible(game, click, budget) {
            return Some(click);
        }
    }
    None
}
fn sent_anchor_click(game: &Game<'_>, p: [i32; 3], budget: &mut Budget) -> Option<Click> {
    let eye = game.eye_position()?;
    let (yaw, pitch) = super::sunset_combat_wire::sent_look(game)?;
    if !yaw.is_finite() || !pitch.is_finite() {
        return None;
    }
    let (yaw, pitch) = (f64::from(yaw).to_radians(), f64::from(pitch).to_radians());
    let direction = [-yaw.sin() * pitch.cos(), -pitch.sin(), yaw.cos() * pitch.cos()];
    let (range, _) = super::sunset_explosive_tactics::interaction_ranges(game)?;
    let hit = game.clip_ray(eye, direction, range)?;
    if hit.pos != p {
        return None;
    }
    let click = Click { pos: hit.pos, face: policy::face(hit.face)?, hit: hit.point };
    visible(game, click, budget).then_some(click)
}
fn anchor_click(game: &Game<'_>, p: [i32; 3], budget: &mut Budget) -> Option<Click> {
    sent_anchor_click(game, p, budget).or_else(|| fallback_anchor_click(game, p, budget))
}
fn anchor_deed_click(game: &Game<'_>, p: [i32; 3], budget: &mut Budget, actual: bool) -> Option<Click> {
    if actual { sent_anchor_click(game, p, budget) } else { anchor_click(game, p, budget) }
}
fn fallback_anchor_click(game: &Game<'_>, p: [i32; 3], budget: &mut Budget) -> Option<Click> {
    let eye = game.eye_position()?;
    let c = center(p, false);
    let axis = (0..3).max_by(|&a, &b| (eye[a] - c[a]).abs().total_cmp(&(eye[b] - c[b]).abs()))?;
    let positive = eye[axis] >= c[axis];
    let mut hit = c;
    hit[axis] += if positive { 0.5 } else { -0.5 };
    let face = match (axis, positive) {
        (0, false) => 4,
        (0, true) => 5,
        (1, false) => 0,
        (1, true) => 1,
        (2, false) => 2,
        _ => 3,
    };
    let click = Click { pos: p, face, hit };
    visible(game, click, budget).then_some(click)
}
fn crystal_room(game: &Game<'_>, p: [i32; 3]) -> bool {
    crystal_space(game, p, true)
}
fn crystal_space(game: &Game<'_>, p: [i32; 3], require_base: bool) -> bool {
    if p[1] < -64
        || p[1] >= 318
        || !game.world.loaded(p[0], p[2])
        || (require_base && !matches!(util::short(&util::facts(game, p).name), "obsidian" | "bedrock"))
        || !util::is_air(game, [p[0], p[1] + 1, p[2]])
    {
        return false;
    }
    let c = center(p, true);
    let hits = |b: horizon_core::geometry::Aabb| {
        let (a, z) = (b.min_position(), b.max_position());
        a.x < c[0] + 0.5 && z.x > c[0] - 0.5 && a.y < c[1] + 2. && z.y > c[1] && a.z < c[2] + 0.5 && z.z > c[2] - 0.5
    };
    !game.player.as_ref().is_some_and(|p| hits(p.bounds()))
        && !game.mobs.iter().any(|m| !m.removed && hits(m.bounds()))
        && !game.crystals.iter().any(|e| {
            (e.position.x - c[0]).abs() < 1.5
                && (e.position.z - c[2]).abs() < 1.5
                && e.position.y < c[1] + 2.
                && e.position.y + 2. > c[1]
        })
}
fn crystal_on(game: &Game<'_>, p: [i32; 3]) -> Option<u32> {
    let c = center(p, true);
    game.crystals
        .iter()
        .find(|e| e.id != 0 && !e.invulnerable && in_range(c, [e.position.x, e.position.y, e.position.z], 0.25))
        .map(|e| e.id)
}
fn direction(game: &Game<'_>) -> [f64; 3] {
    let (y, p) = (f64::from(game.yaw).to_radians(), f64::from(game.pitch).to_radians());
    [-y.sin() * p.cos(), -p.sin(), y.cos() * p.cos()]
}
fn crosshair_crystal(game: &Game<'_>, budget: &mut Budget) -> Option<(u32, [f64; 3], [f64; 3])> {
    match cursor_entity(game).ok()?? {
        CursorEntity::Crystal { id, at, aim } => {
            let eye = game.eye_position()?;
            let end = std::array::from_fn(|i| aim[i] + (eye[i] - aim[i]) * 1.0e-5);
            clear_line(game, eye, end, None, budget).then_some((id, at, aim))
        }
        CursorEntity::Other => None,
    }
}
// Anchor intent deliberately uses a block-only outline ray. Crystal intent
// additionally refuses a nearer observed pickable entity through crystal_click.
fn camera_click(game: &Game<'_>) -> Option<Click> {
    let (range, _) = super::sunset_explosive_tactics::interaction_ranges(game)?;
    let hit = game.clip_ray(game.eye_position()?, direction(game), range)?;
    Some(Click { pos: hit.pos, face: policy::face(hit.face)?, hit: hit.point })
}
#[derive(Clone, Copy, Debug)]
enum CursorEntity {
    Crystal { id: u32, at: [f64; 3], aim: [f64; 3] },
    Other,
}
// No allocation: one bounded pass over the native pickable collections. An
// invalid observed box or overfull scene refuses the macro's crystal plan.
fn cursor_entity(game: &Game<'_>) -> Result<Option<CursorEntity>, ()> {
    let (blocks, entities) = super::sunset_explosive_tactics::interaction_ranges(game).ok_or(())?;
    let eye = game.eye_position().ok_or(())?;
    let dir = direction(game);
    if !eye.iter().chain(dir.iter()).all(|v| v.is_finite()) {
        return Err(());
    }
    let count = game
        .mobs
        .len()
        .saturating_add(game.crystals.len())
        .saturating_add(game.boats.len())
        .saturating_add(game.carts.len())
        .saturating_add(game.armor_stands.len())
        .saturating_add(game.cushions.len())
        .saturating_add(game.item_frames.len())
        .saturating_add(game.paintings.len())
        .saturating_add(game.creatures.projectiles.len());
    if count > 768 {
        return Err(());
    }
    // A wall beyond the block interaction range still occludes an entity
    // when a server grants a larger entity interaction range.
    let wall = game.clip_ray(eye, dir, blocks.max(entities)).map(|hit| util::dist(eye, hit.point));
    let mut best: Option<(f64, CursorEntity)> = None;
    let mut offer = |lo: [f64; 3], hi: [f64; 3], what: CursorEntity| -> Result<(), ()> {
        if !(0..3).all(|i| lo[i].is_finite() && hi[i].is_finite() && lo[i] <= hi[i]) {
            return Err(());
        }
        if let Some(hit) = policy::ray(eye, dir, lo, hi, entities) {
            let distance = util::dist(eye, hit);
            if wall.is_none_or(|d| distance < d) && best.as_ref().is_none_or(|(d, _)| distance < *d) {
                let what = match what {
                    CursorEntity::Crystal { id, at, .. } => CursorEntity::Crystal { id, at, aim: hit },
                    other => other,
                };
                best = Some((distance, what));
            }
        }
        Ok(())
    };
    let corners = |b: horizon_core::geometry::Aabb| {
        let (lo, hi) = (b.min_position(), b.max_position());
        ([lo.x, lo.y, lo.z], [hi.x, hi.y, hi.z])
    };
    // Offer non-crystals first so an exact tie cannot click through one.
    for mob in &game.mobs {
        if mob.removed
            || !mob.alive()
            || Some(mob.id) == game.riding
            || super::remote::sunset_combat_remote::player_mode(game, mob.id) == Some(3)
        {
            continue;
        }
        let (lo, hi) = corners(mob.bounds());
        offer(lo, hi, CursorEntity::Other)?;
    }
    for stand in &game.armor_stands {
        if !stand.marker && stand.health > 0.0 {
            let (lo, hi) = corners(stand.bounds());
            offer(lo, hi, CursorEntity::Other)?;
        }
    }
    for boat in &game.boats {
        if Some(boat.id) != game.riding {
            let (lo, hi) = corners(boat.bounds());
            offer(lo, hi, CursorEntity::Other)?;
        }
    }
    for cart in &game.carts {
        if Some(cart.id) != game.riding {
            let (lo, hi) = corners(cart.bounds());
            offer(lo, hi, CursorEntity::Other)?;
        }
    }
    for cushion in &game.cushions {
        if Some(cushion.id) != game.riding {
            let (lo, hi) = cushion.bounds();
            offer(lo, hi, CursorEntity::Other)?;
        }
    }
    for frame in &game.item_frames {
        let (lo, hi) = frame.bounds();
        offer(lo, hi, CursorEntity::Other)?;
    }
    for painting in &game.paintings {
        let (lo, hi) = painting.bounds();
        offer(lo, hi, CursorEntity::Other)?;
    }
    for projectile in &game.creatures.projectiles {
        if super::deflect::redirectable(projectile) {
            let (lo, hi) = corners(projectile.aabb());
            offer(lo.map(|n| n - 1.0), hi.map(|n| n + 1.0), CursorEntity::Other)?;
        }
    }
    // Native dragon helper already accepts the caller's actual reach.
    let dragon = game.remote_dragon_part_hit(eye, dir, entities).map(|(_, distance, _)| distance);
    drop(offer);
    if let Some(distance) = dragon {
        if distance.is_finite()
            && wall.is_none_or(|d| distance < d)
            && best.as_ref().is_none_or(|(d, _)| distance <= *d)
        {
            best = Some((distance, CursorEntity::Other));
        }
    }
    for crystal in &game.crystals {
        if crystal.id == 0 {
            continue;
        }
        let at = [crystal.position.x, crystal.position.y, crystal.position.z];
        if !at.iter().all(|v| v.is_finite()) {
            return Err(());
        }
        if let Some(aim) =
            policy::ray(eye, dir, [at[0] - 1., at[1], at[2] - 1.], [at[0] + 1., at[1] + 2., at[2] + 1.], entities)
        {
            let distance = util::dist(eye, aim);
            if wall.is_none_or(|d| distance < d) && best.as_ref().is_none_or(|(d, _)| distance < *d) {
                best = Some((
                    distance,
                    if crystal.invulnerable {
                        CursorEntity::Other
                    } else {
                        CursorEntity::Crystal { id: crystal.id, at, aim }
                    },
                ));
            }
        }
    }
    Ok(best.map(|(_, entity)| entity))
}
fn crystal_click(game: &Game<'_>) -> Option<Click> {
    if cursor_entity(game).ok()?.is_some() {
        return None;
    }
    camera_click(game)
}
fn crystal_intent(
    game: &Game<'_>,
    settings: &Module,
    preferred: usize,
    budget: &mut Budget,
) -> Option<([i32; 3], Step, Option<u32>)> {
    if let Some((id, at, _)) = crosshair_crystal(game, budget) {
        return Some((
            [at[0].floor() as i32, at[1].floor() as i32 - 1, at[2].floor() as i32],
            Step::CrystalBreak,
            Some(id),
        ));
    }
    let click = crystal_click(game)?;
    if matches!(util::short(&util::facts(game, click.pos).name), "obsidian" | "bedrock") {
        return (crystal_room(game, click.pos) && crystal_route(game, "end_crystal", true, preferred).is_some())
            .then_some((click.pos, Step::CrystalPlace, None));
    }
    if !settings.b("Auto obsidian")
        || !inert(game, click.pos)
        || crystal_route(game, "obsidian", false, preferred).is_none()
        || crystal_route(game, "end_crystal", true, preferred).is_none()
    {
        return None;
    }
    let normal = match click.face {
        0 => [0, -1, 0],
        1 => [0, 1, 0],
        2 => [0, 0, -1],
        3 => [0, 0, 1],
        4 => [-1, 0, 0],
        5 => [1, 0, 0],
        _ => return None,
    };
    let target = std::array::from_fn(|i| click.pos[i] + normal[i]);
    (util::can_place(game, target, true) && crystal_space(game, target, false) && visible(game, click, budget))
        .then_some((target, Step::Base, None))
}
fn random(s: &mut State) -> u64 {
    s.random = s.random.wrapping_add(0x9e3779b97f4a7c15);
    let mut n = s.random;
    n = (n ^ (n >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
    n = (n ^ (n >> 27)).wrapping_mul(0x94d049bb133111eb);
    n ^ (n >> 31)
}
// The nearest enemy player within 10 blocks is still in hurt time.
fn enemy_hurt(game: &Game<'_>) -> bool {
    let Some(me) = util::player_pos(game) else {
        return false;
    };
    game.mobs
        .iter()
        .filter(|t| util::player_enemy(game, t))
        .map(|t| (t.hurt_time, util::dist(me, [t.position.x, t.position.y, t.position.z])))
        .filter(|(_, d)| *d <= 10.0)
        .min_by(|a, b| a.1.total_cmp(&b.1))
        .is_some_and(|(hurt, _)| hurt > 0)
}
fn delay_for(run: &Run, step: Step) -> f64 {
    match step {
        Step::Base => run.settings.n("Obsidian delay"),
        Step::CrystalPlace => run.settings.n("Place delay"),
        Step::CrystalBreak => run.settings.n("Break delay"),
        _ => run.settings.n("Delay"),
    }
}
pub(super) fn note_main(game: &Game<'_>) {
    let current = &game.inventory[game.selected];
    state(|s| {
        if s.main
            .as_ref()
            .is_none_or(|(slot, stack, tick)| *slot != game.selected || stack != current || game.ticks < *tick)
        {
            s.main = Some((game.selected, current.clone(), game.ticks));
        }
    });
}
pub(super) fn enchant_damage(game: &Game<'_>, stack: &horizon_client::items::ItemStack) -> bool {
    let mut sum = 0.0f32;
    for (id, level) in stack.enchantments() {
        let Some(enchantment) = game.items().enchantments.get(id) else {
            return false;
        };
        for effect in enchantment.effects["minecraft:damage"].as_array().into_iter().flatten() {
            if effect.get("requirements").is_some_and(|v| !v.is_null()) || effect["effect"]["type"] != "minecraft:add" {
                return false;
            }
            sum += horizon_client::enchant::level_value(&effect["effect"]["value"], *level);
        }
    }
    sum.is_finite() && sum > 0.0
}
// Strength and weakness on a bare hand's attack damage (what Game::effect_attack_bonus gave before 66f3981).
fn effect_attack_bonus(game: &Game<'_>) -> f32 {
    let fx = &game.potions.effects;
    fx.amplifier("strength").map_or(0.0, |a| 3.0 * (a + 1) as f32) - fx.amplifier("weakness").map_or(0.0, |a| 4.0 * (a + 1) as f32)
}
pub(super) fn weapon_route(game: &Game<'_>) -> Option<usize> {
    let bare = 1.0 + effect_attack_bonus(game);
    let mut fallback = None;
    for slot in std::iter::once(game.selected).chain((0..9).filter(|slot| *slot != game.selected)) {
        let Some(stack) = game.inventory[slot].as_ref() else {
            if bare > 0.0 {
                if slot == game.selected {
                    return Some(slot);
                }
                fallback.get_or_insert(slot);
            }
            continue;
        };
        let Some(info) = game.items().get(&stack.item) else {
            continue;
        };
        if stack.count == 0
            || horizon_client::spear::Kinetic::of(&stack.item).is_some()
            || game.cooldowns.is_on_cooldown(&horizon_client::cooldowns::group(stack, info.use_cooldown.as_ref()))
        {
            continue;
        }
        if enchant_damage(game, stack) {
            return Some(slot);
        }
        if (bare + info.attack_damage).is_finite() && bare + info.attack_damage > 0.0 {
            if slot == game.selected {
                return Some(slot);
            }
            fallback.get_or_insert(slot);
        }
    }
    fallback
}
pub(super) fn weak_settling(game: &Game<'_>) -> bool {
    let bare = 1.0 + effect_attack_bonus(game);
    bare <= 0.0
        && !game.inventory[game.selected].as_ref().is_some_and(|s| enchant_damage(game, s))
        && state(|s| s.main.as_ref().is_none_or(|(_, _, since)| game.ticks < *since || game.ticks - *since < 2))
}
fn planned_blast(kind: Kind, pos: [i32; 3]) -> Blast {
    match kind {
        Kind::Anchor => Blast::anchor(pos),
        Kind::Crystal => {
            Blast::explosion([f64::from(pos[0]) + 0.5, f64::from(pos[1]) + 1.0, f64::from(pos[2]) + 0.5], 6.0)
        }
    }
}
fn loot_allowed(game: &Game<'_>, run: &Run) -> bool {
    super::sunset_loot_guard::allows(game, planned_blast(run.sequence.kind, run.pos), run.settings.b("Protect loot"))
}
fn safe_blast(
    game: &mut Game<'_>,
    settings: &Module,
    kind: Kind,
    blast: Blast,
    detonation_slot: Option<usize>,
    budget: &mut Budget,
) -> bool {
    if !super::sunset_loot_guard::allows(game, blast, settings.b("Protect loot")) {
        return false;
    }
    let Some(player) = game.player.as_ref() else {
        return false;
    };
    let health = f64::from(player.health.health() + player.health.absorption());
    if !health.is_finite() || health <= 0.0 {
        return false;
    }
    // Use the hand that this accepted deed will actually select, rather than
    // a different currently-held item before a Double replacement selection.
    if kind == Kind::Anchor
        && (detonation_slot.is_some_and(|slot| stack(game, slot, "totem_of_undying"))
            || stack(game, OFFHAND, "totem_of_undying"))
    {
        return true;
    }
    let Some(own) = observed_local_damage(game, blast, budget) else {
        return false;
    };
    if super::sunset_explosive_tactics::endangered(own, health, game.creative) {
        return false;
    }
    kind != Kind::Crystal || own <= settings.n("Max self damage")
}

fn body_points(game: &Game<'_>) -> Option<Vec<[f64; 3]>> {
    let b = game.player.as_ref()?.bounds();
    let (lo, hi) = (b.min_position(), b.max_position());
    super::sunset_explosive_policy::samples(lo.components(), hi.components())
}
fn guard_open_points(game: &Game<'_>, anchor: [i32; 3], budget: &mut Budget) -> Option<(usize, Vec<[f64; 3]>)> {
    let points = body_points(game)?;
    let total = points.len();
    let blast = center(anchor, false);
    let mut open = Vec::with_capacity(total);
    for point in points {
        match super::sunset_explosive_damage::known_line(game, point, blast, Some(anchor), budget)? {
            true => open.push(point),
            false => {}
        }
    }
    Some((total, open))
}
fn covered(game: &Game<'_>, anchor: [i32; 3], budget: &mut Budget) -> bool {
    guard_open_points(game, anchor, budget)
        .is_some_and(|(total, open)| policy::guard_already_covered(total, open.len()))
}
fn guard_slot(game: &Game<'_>, run: &Run) -> Option<usize> {
    guard_slot_at(game, run.pos, run.settings.p("Mode") == "Double")
}
fn guard_slot_at(game: &Game<'_>, anchor: [i32; 3], double: bool) -> Option<usize> {
    let mut weaker = None;
    for slot in 0..9 {
        let Some(stack) = game.inventory[slot].as_ref().filter(|s| s.count > 0) else {
            continue;
        };
        if util::short(&stack.item) == "glowstone" {
            continue;
        }
        let Some(state) = game.items().get(&stack.item).and_then(|i| i.block) else {
            continue;
        };
        let facts = game.res.facts().get(state);
        if !facts.full_collision
            || facts.block_entity
            || matches!(util::short(&facts.name), "tnt" | "respawn_anchor")
            || facts.classes.iter().any(|c| c.ends_with("FallingBlock"))
        {
            continue;
        }
        if facts.explosion_resistance >= 600.0 {
            return Some(slot);
        }
        weaker.get_or_insert(slot);
    }
    if weaker.is_some() {
        return weaker;
    }
    let needed = u32::from(anchor_charge(game, anchor).unwrap_or(0) == 0) + u32::from(double);
    let count = game.inventory[..9]
        .iter()
        .flatten()
        .filter(|s| util::short(&s.item) == "glowstone")
        .fold(0u32, |n, s| n.saturating_add(s.count));
    (count > needed).then(|| util::find_hotbar(game, |n| n == "glowstone")).flatten()
}
fn guard_place(game: &Game<'_>, anchor: [i32; 3], budget: &mut Budget) -> Option<([i32; 3], Click)> {
    let feet = util::block_pos(game)?;
    let eye = game.eye_position()?;
    let player = game.player.as_ref()?.bounds();
    let (_, points) = guard_open_points(game, anchor, budget)?;
    let needed = policy::guard_shade_needed(points.len())?;
    let blast = center(anchor, false);
    let mut cells = Vec::with_capacity(12);
    for dx in -1..=1 {
        for dz in -1..=1 {
            if dx != 0 || dz != 0 {
                cells.push([feet[0] + dx, feet[1], feet[2] + dz]);
            }
        }
    }
    for d in [[1, 0], [-1, 0], [0, 1], [0, -1]] {
        let p = [anchor[0] + d[0], anchor[1], anchor[2] + d[1]];
        if !cells.contains(&p) {
            cells.push(p);
        }
    }
    let mut ranked = Vec::with_capacity(12);
    for cell in cells {
        let lo = cell.map(f64::from);
        let hi = lo.map(|n| n + 1.0);
        let box_ = horizon_core::geometry::Aabb::new(
            horizon_core::geometry::Vec3::new(lo[0], lo[1], lo[2]),
            horizon_core::geometry::Vec3::new(hi[0], hi[1], hi[2]),
        );
        if cell == anchor
            || box_.intersects(player)
            || policy::ray(eye, std::array::from_fn(|i| blast[i] - eye[i]), lo, hi, util::dist(eye, blast)).is_some()
        {
            continue;
        }
        let shade = points
            .iter()
            .filter(|point| {
                policy::ray(**point, std::array::from_fn(|i| blast[i] - point[i]), lo, hi, util::dist(**point, blast))
                    .is_some()
            })
            .count();
        if shade < needed {
            continue;
        }
        ranked.push((cell, shade, util::dist(center(cell, false), blast)));
    }
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then(a.2.total_cmp(&b.2)));
    for (cell, _, _) in ranked {
        if let Some(click) = support(game, cell, budget) {
            return Some((cell, click));
        }
    }
    None
}
fn use_action(game: &Game<'_>, step: Step, click: Click, slot: usize, destination: [i32; 3]) -> Action {
    Action::Use {
        step,
        click,
        slot,
        select: None,
        destination,
        before: game.world.block(destination[0], destination[1], destination[2]).0,
    }
}
fn detonator(game: &Game<'_>) -> Option<usize> {
    // Partial charged anchors pass to offhand glowstone; never accidentally
    // charge during a transaction that was approved as a detonation.
    if stack(game, OFFHAND, "glowstone") {
        return None;
    }
    util::find_hotbar(game, |n| n == "totem_of_undying")
        .or_else(|| (0..9).find(|&slot| combat_item(game, game.inventory[slot].as_ref())))
}
fn melee_item(game: &Game<'_>, stack: &horizon_client::items::ItemStack) -> bool {
    util::short(&stack.item) == "mace"
        || ["minecraft:swords", "minecraft:axes"]
            .iter()
            .any(|tag| game.items().item_tags.get(*tag).is_some_and(|items| items.contains(&*stack.item)))
}
fn combat_item(game: &Game<'_>, stack: Option<&horizon_client::items::ItemStack>) -> bool {
    stack.is_none_or(|stack| {
        stack.count == 0 || util::short(&stack.item) == "totem_of_undying" || melee_item(game, stack)
    })
}
fn recognized_hand(game: &Game<'_>, kind: Kind) -> bool {
    let held = game.inventory.get(game.selected).and_then(|s| s.as_ref());
    match kind {
        Kind::Crystal => {
            stack(game, game.selected, "end_crystal")
                || (stack(game, OFFHAND, "end_crystal") && combat_item(game, held))
                || (held.is_some_and(|s| melee_item(game, s))
                    && (game.offhand.is_none() || stack(game, OFFHAND, "totem_of_undying"))
                    && util::find_hotbar(game, |n| n == "end_crystal").is_some())
        }
        Kind::Anchor => true, // Actual ray intent and detonator preflight decide.
    }
}

// Called immediately before vanilla's native use-item operation. True consumes
// that one operation, including repeats during an owned manual sequence.
pub(super) fn intercept_use(game: &mut Game<'_>) -> bool {
    // Native use clicks are consumed on an input tick, after a quick release
    // may already have cleared held state. Retain only one fresh press in the
    // same remote session; consuming it here never starts a held Crystal run.
    let press = state(|s| s.anchor_press.take()).filter(|press| {
        game.ticks >= press.tick
            && game.ticks - press.tick <= 2
            && game.dim == press.dimension
            && game
                .remote
                .as_ref()
                .is_some_and(|r| r.entity_id == press.entity && Arc::ptr_eq(&r.session.counters, &press.session))
    });
    let held = down(game);
    if !held && press.is_none() {
        return false;
    }
    if let Some(kind) = state(|s| s.run.as_ref().map(|r| r.sequence.kind)) {
        return held || kind == Kind::Anchor;
    }
    let anchor = macro_module(ANCHOR);
    if state(|s| s.anchor_latched) && anchor.is_some() {
        return true;
    }
    let pick = game.pick().map(|hit| (hit.pos, hit.face));
    if game.native_window() && game.native_on(sunset::ID) && util::in_world(game) && !game.anchor_works() {
        if let (Some(m), Some((p, _))) = (anchor.as_ref(), pick) {
            if anchor_charge(game, p).is_some()
                && !super::sunset_loot_guard::allows(game, Blast::anchor(p), m.b("Protect loot"))
            {
                return true;
            }
        }
    }
    if !held && !press.is_some_and(|p| p.start_allowed) {
        return false;
    }
    if !allowed(game) {
        return false;
    }
    let crystal = macro_module(CRYSTAL);
    if anchor.is_none() && crystal.is_none() {
        return false;
    }
    if !super::sunset_explosive_tactics::refresh(game) {
        return false;
    }
    let pick = camera_click(game).map(|click| {
        (
            click.pos,
            match click.face {
                0 => [0, -1, 0],
                1 => [0, 1, 0],
                2 => [0, 0, -1],
                3 => [0, 0, 1],
                4 => [-1, 0, 0],
                _ => [1, 0, 0],
            },
        )
    });
    let mut budget = Budget::new(16);
    let on_anchor = pick.is_some_and(|(p, _)| anchor_charge(game, p).is_some());
    let anchor_intent = on_anchor || stack(game, game.selected, "respawn_anchor");
    if !held && !anchor_intent {
        return false;
    }
    let (settings, kind, pos, step, cid) = if anchor_intent {
        let Some(m) = anchor else {
            return false;
        };
        if game.anchor_works() || !anchor_can_click(game) {
            return false;
        }
        let Some((p, face)) = pick else {
            return false;
        };
        let target = if on_anchor {
            p
        } else {
            if !inert(game, p) || policy::face(face).is_none() {
                return false;
            }
            std::array::from_fn(|i| p[i] + face[i])
        };
        if !on_anchor && support(game, target, &mut budget).is_none() {
            return false;
        }
        if !super::sunset_loot_guard::allows(game, Blast::anchor(target), m.b("Protect loot")) {
            return true;
        }
        if !recognized_hand(game, Kind::Anchor) || stack(game, OFFHAND, "glowstone") {
            return false;
        }
        if !policy::anchor_supplied(
            anchor_charge(game, target).is_some_and(|charge| charge > 0),
            util::find_hotbar(game, |name| name == "glowstone").is_some(),
            detonator(game).is_some(),
        ) {
            return false;
        }
        if m.b("Safe anchor")
            && m.p("If unguarded") == "Cancel"
            && guard_slot_at(game, target, m.p("Mode") == "Double").is_none()
        {
            return false;
        }
        (m, Kind::Anchor, target, if on_anchor { Step::Guard } else { Step::AnchorPlace }, None)
    } else {
        let Some(m) = crystal.filter(|_| recognized_hand(game, Kind::Crystal)) else {
            return false;
        };
        if let Some((cid, at, _)) = crosshair_crystal(game, &mut budget) {
            let p = [at[0].floor() as i32, at[1].floor() as i32 - 1, at[2].floor() as i32];
            (m, Kind::Crystal, p, Step::CrystalBreak, Some(cid))
        } else {
            let Some(click) = crystal_click(game) else {
                return false;
            };
            let p = click.pos;
            let face = match click.face {
                0 => [0, -1, 0],
                1 => [0, 1, 0],
                2 => [0, 0, -1],
                3 => [0, 0, 1],
                4 => [-1, 0, 0],
                _ => [1, 0, 0],
            };
            if matches!(util::short(&util::facts(game, p).name), "obsidian" | "bedrock") {
                if !crystal_room(game, p) {
                    return false;
                }
                (m, Kind::Crystal, p, Step::CrystalPlace, None)
            } else {
                if !m.b("Auto obsidian") || !inert(game, p) || item_slot(game, "obsidian").is_none() {
                    return false;
                }
                let target = std::array::from_fn(|i| p[i] + face[i]);
                if support(game, target, &mut budget).is_none() {
                    return false;
                }
                (m, Kind::Crystal, target, Step::Base, None)
            }
        }
    };
    if kind == Kind::Crystal && step != Step::CrystalBreak {
        let Some(click) = crystal_click(game) else {
            return false;
        };
        let base = matches!(util::short(&util::facts(game, click.pos).name), "obsidian" | "bedrock");
        let item = if step == Step::Base { "obsidian" } else { "end_crystal" };
        if crystal_route(game, item, base, game.selected).is_none()
            || (step == Step::Base && crystal_route(game, "end_crystal", true, game.selected).is_none())
        {
            return false;
        }
    }
    if !super::sunset_loot_guard::allows(game, planned_blast(kind, pos), settings.b("Protect loot")) {
        return true;
    }
    let owner = if kind == Kind::Anchor { ANCHOR } else { CRYSTAL };
    if !super::sunset_combat_control::claim(owner) {
        return false;
    }
    let Some(remote) = game.remote.as_ref() else {
        super::sunset_combat_control::release(owner);
        return false;
    };
    state(|s| {
        if s.last_session.as_ref().is_none_or(|old| !Arc::ptr_eq(old, &remote.session.counters)) {
            s.retries.clear();
            s.last_deed = None;
            s.pace_gap = 0;
            s.main = None;
            s.last_session = Some(remote.session.counters.clone());
        }
        s.token = s.token.wrapping_add(1);
        if kind == Kind::Anchor {
            s.anchor_latched = true;
        }
        s.run = Some(Run {
            owner,
            sequence: Sequence::new(kind, step, settings.p("Mode") == "Double"),
            settings: Arc::new(settings),
            pos,
            previous: game.selected,
            owned: game.selected,
            session: remote.session.counters.clone(),
            entity: remote.entity_id,
            dimension: game.dim,
            pending: None,
            ready: game.ticks,
            crystal: cid,
            guard: None,
            token: s.token,
            queued_at: None,
            deadline: game.ticks.saturating_add(if kind == Kind::Anchor { 5 } else { 60 }),
            replace_click: None,
            guard_block: None,
            guard_tries: 0,
            guard_confirmed: false,
        });
    });
    // Ownership starts before the intercepted vanilla packet could be sent.
    true
}

fn observed(game: &Game<'_>, action: Action, run: &Run) -> bool {
    match action {
        Action::Attack { id, .. } => !game.crystals.iter().any(|c| c.id == id),
        Action::Use { step, destination, before, .. } => match step {
            Step::Base => name_is(game, destination, "obsidian"),
            Step::Guard => run.guard_block.is_some_and(|expected| {
                game.res.facts().get(horizon_world::registry::BlockStateId(expected)).name
                    == util::facts(game, destination).name
            }),
            Step::CrystalPlace => crystal_on(game, destination).is_some(),
            Step::AnchorPlace => anchor_charge(game, destination).is_some(),
            Step::Charge => {
                game.world.block(destination[0], destination[1], destination[2]).0 != before
                    && anchor_charge(game, destination).is_some_and(|n| n > 0)
            }
            Step::Detonate => !game.is_anchor(game.world.block(destination[0], destination[1], destination[2])),
            _ => false,
        },
    }
}
fn next_action(game: &mut Game<'_>, run: &Run, budget: &mut Budget, actual: bool) -> Option<Action> {
    if run.sequence.kind == Kind::Anchor && !anchor_can_click(game) {
        return None;
    }
    let p = run.pos;
    let step = run.sequence.step;
    match step {
        Step::Base | Step::Guard => {
            let destination = if step == Step::Guard { run.guard? } else { p };
            let click = if step == Step::Base {
                let click = crystal_click(game)?;
                if crystal_intent(game, &run.settings, run.previous, budget)?.0 != p || !visible(game, click, budget) {
                    return None;
                }
                let normal = match click.face {
                    0 => [0, -1, 0],
                    1 => [0, 1, 0],
                    2 => [0, 0, -1],
                    3 => [0, 0, 1],
                    4 => [-1, 0, 0],
                    5 => [1, 0, 0],
                    _ => return None,
                };
                let route = crystal_route(game, "obsidian", false, run.previous)?;
                let slot = if route.offhand { OFFHAND } else { route.select.unwrap_or(game.selected) };
                let native =
                    super::remote::sunset_aura_base::BaseClick { clicked: click.pos, normal, point: click.hit };
                let range = super::sunset_explosive_tactics::interaction_ranges(game)?.0;
                let mut rays = 12;
                if !super::remote::sunset_aura_base::valid(game, p, slot, native, range, &mut rays) {
                    return None;
                }
                click
            } else {
                support(game, destination, budget)?
            };
            if step == Step::Base {
                crystal_use_action(game, run, step, click, "obsidian", destination)
            } else {
                Some(use_action(game, step, click, guard_slot(game, run)?, destination))
            }
        }
        Step::CrystalPlace => {
            if !crystal_room(game, p) {
                return None;
            }
            let click = crystal_click(game)?;
            if click.pos != p {
                return None;
            }
            // Placement is not a detonation. Its geometry and native loot
            // veto remain required; a later break reevaluates actual damage.
            if !visible(game, click, budget) {
                return None;
            }
            crystal_use_action(game, run, step, click, "end_crystal", p)
        }
        Step::CrystalBreak => {
            if !super::remote::sunset_combat_remote::sprint_synced(game) {
                return None;
            }
            // Perfect timing: the break waits for the nearest enemy's hurt time to run out, so the blast counts.
            if run.settings.b("Perfect timing") && enemy_hurt(game) {
                return None;
            }
            let id = run.crystal.or_else(|| crystal_on(game, p))?;
            if !state(|s| s.retries.allows(id, game.ticks)) {
                return None;
            }
            // The manual crystal must remain on the real camera ray. Silent
            // automation never searches for a different nearby crystal.
            let (hit_id, at, aim) = crosshair_crystal(game, budget)?;
            if hit_id != id || !safe_blast(game, &run.settings, Kind::Crystal, Blast::explosion(at, 6.0), None, budget)
            {
                return None;
            }
            let slot = weapon_route(game)?;
            if slot == game.selected && weak_settling(game) {
                return None;
            }
            Some(Action::Attack { id, at, aim, slot })
        }
        Step::AnchorPlace => {
            if game.anchor_works() {
                return None;
            }
            let click = if let Some(click) = run.replace_click.filter(|_| run.sequence.refilled) {
                let eye = game.eye_position()?;
                let (yaw, pitch) = super::sunset_combat_wire::sent_look(game)?;
                let (yaw, pitch) = (f64::from(yaw).to_radians(), f64::from(pitch).to_radians());
                let direction = [-yaw.sin() * pitch.cos(), -pitch.sin(), yaw.cos() * pitch.cos()];
                let lo = p.map(f64::from);
                let hi = lo.map(|n| n + 1.0);
                policy::ray(eye, direction, lo, hi, super::sunset_explosive_tactics::interaction_ranges(game)?.0)?;
                if !visible(game, click, budget) {
                    return None;
                }
                click
            } else {
                support(game, p, budget)?
            };
            Some(use_action(game, step, click, item_slot(game, "respawn_anchor")?, p))
        }
        Step::Charge => {
            if game.anchor_works() || anchor_charge(game, p).is_none_or(|n| n >= 4) {
                return None;
            }
            Some(use_action(game, step, anchor_deed_click(game, p, budget, actual)?, item_slot(game, "glowstone")?, p))
        }
        Step::Detonate => {
            if game.anchor_works() || anchor_charge(game, p).is_none_or(|n| n == 0) {
                return None;
            }
            if run.settings.b("Safe anchor")
                && run.settings.p("If unguarded") == "Cancel"
                && !run.guard_confirmed
                && !covered(game, p, budget)
            {
                return None;
            }
            let slot = if run.sequence.remaining > 1 {
                util::find_hotbar(game, |n| n == "respawn_anchor")?
            } else {
                detonator(game)?
            };
            if !safe_blast(game, &run.settings, Kind::Anchor, Blast::anchor(p), Some(slot), budget) {
                return None;
            }
            Some(use_action(game, step, anchor_deed_click(game, p, budget, actual)?, slot, p))
        }
        Step::Done => None,
    }
}

pub(super) fn tick(game: &mut Game<'_>, modules: &[Module], _ticks: u64) {
    if !active() && !modules.iter().any(|m| m.on && (m.name == CRYSTAL_MODULE || m.name == ANCHOR_MODULE) && m.b(MACRO)) {
        return;
    }
    if game.selected < 9 {
        note_main(game);
    }
    if !game.native_playing() || gui_open() {
        focus_lost();
    }
    if game.ticks % 20 == 0 {
        state(|s| s.retries.retain(|id| game.crystals.iter().any(|c| c.id == id)));
    }
    if !down(game) {
        state(|s| s.anchor_latched = false);
    }
    let Some(mut run) = state(|s| s.run.clone()) else {
        return;
    };
    if !allowed(game)
        || (run.sequence.kind == Kind::Anchor && !anchor_can_click(game))
        || !same_session(game, &run)
        || !enabled(&run)
        || !loot_allowed(game, &run)
        || game.selected != run.owned
        || game.ticks >= run.deadline
        || (run.sequence.kind == Kind::Crystal && !down(game))
        || !super::sunset_combat_control::claim(run.owner)
    {
        reset(game);
        return;
    }
    if let Some((action, sent)) = run.pending {
        let Some(sent) = sent else {
            if run.queued_at.is_some_and(|t| t.elapsed() > Duration::from_millis(200)) {
                reset(game);
            }
            return;
        };
        let observation = observed(game, action, &run);
        let timeout = if action.step() == Step::Guard {
            run.ready.saturating_sub(sent).max(1)
        } else if run.sequence.kind == Kind::Crystal {
            u64::from(super::sunset_prediction::rtt(game).saturating_add(2).clamp(4, 20))
        } else {
            run.deadline.saturating_sub(sent)
        };
        let wait = policy::wait(sent, game.ticks, observation, timeout);
        match wait {
            Wait::Pending => return,
            Wait::Expired => {
                if action.step() == Step::Guard && run.guard_tries < 2 {
                    run.pending = None;
                    run.guard = None;
                    state(|s| s.run = Some(run));
                    return;
                }
                reset(game);
                return;
            }
            Wait::Acknowledged => {
                if action.step() == Step::Guard {
                    run.guard_confirmed = true;
                }
                if action.step() == Step::CrystalPlace {
                    run.crystal = crystal_on(game, run.pos);
                }
                run.sequence.acknowledged(action.step());
                run.pending = None;
                state(|s| {
                    if s.run.as_ref().is_some_and(|r| r.token == run.token) {
                        s.run = Some(run.clone());
                    }
                });
            }
        }
    }
    if !super::sunset_explosive_tactics::refresh(game) {
        reset(game);
        return;
    }
    if run.sequence.kind == Kind::Crystal {
        let mut budget = Budget::new(8);
        if let Some((pos, step, cid)) = crystal_intent(game, &run.settings, run.previous, &mut budget) {
            run.pos = pos;
            run.sequence = Sequence::new(Kind::Crystal, step, false);
            run.crystal = cid;
        } else {
            run.deadline = game.ticks.saturating_add(60);
            state(|s| s.run = Some(run));
            return;
        }
        // The held ray is replanned only after any real prior transaction was
        // observed; it never continues a pinned old base after the camera moved.
        run.deadline = game.ticks.saturating_add(60);
        state(|s| s.run = Some(run.clone()));
    }
    if run.sequence.step == Step::Done {
        complete(game);
        return;
    }
    if game.ticks < run.ready {
        return;
    }
    if run.sequence.kind == Kind::Crystal
        && !state(|s| policy::action_due(s.last_deed, game.ticks, delay_for(&run, run.sequence.step), s.pace_gap))
    {
        return;
    }
    // Wait for hurt time: the second anchor of a Double waits (half a second at most) for the nearest enemy's hurt
    // time to run out, so its blast counts.
    if run.sequence.kind == Kind::Anchor && run.sequence.step == Step::AnchorPlace && run.sequence.refilled && run.settings.b("Wait for hurt time") {
        let since = state(|s| match s.hurt_wait {
            Some((token, tick)) if token == run.token => tick,
            _ => s.hurt_wait.insert((run.token, game.ticks)).1,
        });
        if enemy_hurt(game) && game.ticks < since + 10 {
            return;
        }
    }
    let mut budget = Budget::new(24);
    if run.sequence.step == Step::Guard {
        if !run.settings.b("Safe anchor") || covered(game, run.pos, &mut budget) {
            run.sequence.acknowledged(Step::Guard);
        } else if run.guard.is_none() {
            run.guard = guard_place(game, run.pos, &mut budget).map(|(p, _)| p);
            if run.guard.is_none() || guard_slot(game, &run).is_none() {
                if run.settings.p("If unguarded") == "Cancel" {
                    reset(game);
                    return;
                }
                run.sequence.acknowledged(Step::Guard);
            }
        }
    }
    if run.sequence.step == Step::Charge && anchor_charge(game, run.pos).is_some_and(|n| n > 0) {
        run.sequence.acknowledged(Step::Charge);
    }
    if run.sequence.step == Step::Detonate && run.sequence.remaining > 1 {
        let eligible = sent_anchor_click(game, run.pos, &mut budget).is_some_and(|click| {
            policy::double_eligible(
                run.settings.p("Mode") == "Double",
                click.face,
                run.pos[1],
                game.player.as_ref().map_or(i32::MAX, |p| p.position.y.floor() as i32),
                util::find_hotbar(game, |n| n == "respawn_anchor").is_some(),
                util::find_hotbar(game, |n| n == "glowstone").is_some(),
            )
        });
        if !eligible {
            run.sequence.remaining = 1;
        }
    }
    state(|s| {
        if s.run.as_ref().is_some_and(|r| r.token == run.token) {
            s.run = Some(run.clone());
        }
    });
    let Some(action) = next_action(game, &run, &mut budget, false) else {
        if run.sequence.kind == Kind::Crystal {
            return;
        }
        reset(game);
        return;
    };
    if run.sequence.kind == Kind::Crystal
        && !state(|s| policy::action_due(s.last_deed, game.ticks, delay_for(&run, action.step()), s.pace_gap))
    {
        return;
    }
    queue(game, &run, action);
}

fn queue(game: &mut Game<'_>, run: &Run, action: Action) {
    let Some(eye) = game.eye_position() else {
        reset(game);
        return;
    };
    let token = run.token;
    let owner = run.owner;
    let queued = Instant::now();
    state(|s| {
        if let Some(r) = s.run.as_mut().filter(|r| r.token == token) {
            r.pending = Some((action, None));
            r.queued_at = Some(queued);
        }
    });
    let (yaw, pitch) = sunset::look_at(eye, action.aim());
    let accepted = sunset::try_turn_then(owner, yaw, pitch, move |game| {
        let Some(run) =
            state(|s| s.run.clone()).filter(|r| r.token == token && r.pending.is_some_and(|(_, sent)| sent.is_none()))
        else {
            return;
        };
        if queued.elapsed() > Duration::from_millis(200)
            || !allowed(game)
            || (run.sequence.kind == Kind::Anchor && !anchor_can_click(game))
            || !same_session(game, &run)
            || !enabled(&run)
            || !loot_allowed(game, &run)
            || game.selected != run.owned
            || !super::sunset_combat_control::owns(owner)
            || !game.eye_position().is_some_and(|now| in_range(now, eye, 0.5))
            || (run.sequence.kind == Kind::Crystal && !down(game))
        {
            reset(game);
            return;
        }
        if !super::sunset_explosive_tactics::refresh(game) {
            reset(game);
            return;
        }
        let mut budget = Budget::new(24);
        let Some(fresh) = next_action(game, &run, &mut budget, true) else {
            reset(game);
            return;
        };
        // A stale look must never be reused for a changed hand, face or entity.
        let same = match (action, fresh) {
            (Action::Attack { id, at, slot, .. }, Action::Attack { id: b, at: c, slot: d, .. }) => {
                id == b && slot == d && in_range(at, c, 0.01)
            }
            (
                Action::Use { step, click, slot, select, destination, before },
                Action::Use { step: b, click: c, slot: d, select: selected, destination: e, before: f },
            ) => {
                step == b
                    && slot == d
                    && select == selected
                    && destination == e
                    && before == f
                    && click.pos == c.pos
                    && click.face == c.face
                    && in_range(click.hit, c.hit, 1.0e-4)
            }
            _ => false,
        };
        if !same {
            reset(game);
            return;
        }
        // Native f32 sent angles can shift a same-face contact by tiny roundoff.
        // Send the newly clipped cursor, never the queued old point.
        let action = fresh;
        match action {
            Action::Attack { id, slot, .. } => {
                if slot != game.selected {
                    hold(game, slot);
                    state(|s| {
                        if let Some(r) = s.run.as_mut().filter(|r| r.token == token) {
                            r.owned = slot;
                        }
                    });
                    note_main(game);
                }
                if weak_settling(game) {
                    state(|s| {
                        if let Some(r) = s.run.as_mut().filter(|r| r.token == token) {
                            r.pending = None;
                            r.queued_at = None;
                            r.ready = game.ticks.saturating_add(1);
                        }
                    });
                    return;
                }
                game.send(S::Attack(play::Attack { id: id as i32 }));
                game.reset_attack_strength();
                state(|s| s.retries.sent(id, game.ticks));
            }
            Action::Use { click, slot, select, step, .. } => {
                // Reselecting a pass-through main hand is part of the accepted
                // deed, not planning; preserve the existing session/slot lease.
                if let Some(selected) = select {
                    hold(game, selected);
                    note_main(game);
                    state(|s| {
                        if let Some(r) = s.run.as_mut().filter(|r| r.token == token) {
                            r.owned = selected;
                        }
                    });
                }
                if slot != OFFHAND {
                    hold(game, slot);
                    note_main(game);
                    state(|s| {
                        if let Some(r) = s.run.as_mut().filter(|r| r.token == token) {
                            r.owned = slot;
                        }
                    });
                }
                let sequence = util::sequence(game);
                game.send(S::UseItemOn(play::UseItemOn {
                    hand: i32::from(slot == OFFHAND),
                    pos: click.pos,
                    face: click.face,
                    cursor: std::array::from_fn(|i| (click.hit[i] - f64::from(click.pos[i])) as f32),
                    inside: false,
                    world_border: false,
                    sequence,
                }));
                state(|s| {
                    if let Some(r) = s.run.as_mut().filter(|r| r.token == token) {
                        if step == Step::Guard {
                            r.guard_tries = r.guard_tries.saturating_add(1);
                            r.guard_block = game
                                .stack_in(slot)
                                .and_then(|stack| game.items().get(&stack.item))
                                .and_then(|i| i.block)
                                .map(|id| id.0);
                        }
                        if step == Step::Detonate && r.sequence.remaining > 1 {
                            r.replace_click = Some(click);
                        }
                    }
                });
            }
        }
        game.swing_arm();
        game.send(S::Punch(Empty));
        let delay = delay_for(&run, action.step());
        state(|s| {
            if run.sequence.kind == Kind::Crystal {
                s.last_deed = Some(game.ticks);
                s.pace_gap = if run.settings.b("Human pace") { policy::human_gap(random(s)) } else { 0 };
            }
            if let Some(r) = s.run.as_mut().filter(|r| r.token == token) {
                r.pending = Some((action, Some(game.ticks)));
                if action.step() == Step::Guard && r.settings.p("If unguarded") == "Detonate" {
                    r.pending = None;
                    r.sequence.acknowledged(Step::Guard);
                }
                r.queued_at = None;
                r.ready = game.ticks.saturating_add(if run.sequence.kind == Kind::Crystal {
                    1
                } else {
                    delay.clamp(0., 5.) as u64 + 1
                });
                let window = if run.sequence.kind == Kind::Crystal {
                    60
                } else if action.step() == Step::Guard && run.settings.p("If unguarded") == "Cancel" {
                    u64::from(super::sunset_prediction::rtt(game).saturating_add(2).clamp(4, 20))
                } else {
                    5
                };
                r.deadline = r.ready.saturating_add(window);
            }
        });
    });
    if !accepted {
        state(|s| {
            if let Some(r) = s.run.as_mut().filter(|r| r.token == token) {
                r.pending = None;
                r.queued_at = None;
            }
        });
    }
}

// What went on the wire last (after Sunset changed it): the look and the sprint the server has.
use super::{Dim, Game};
use horizon_protocol::packets::play::Serverbound as S;
use std::sync::{Arc, Mutex};
type Session = Arc<Mutex<Option<Arc<horizon_protocol::connection::Counters>>>>;
static LOOK: Mutex<Option<(Session, Dim, (f32, f32))>> = Mutex::new(None);
static SPRINT: Mutex<Option<(Session, Dim, bool)>> = Mutex::new(None);
static INPUT: Mutex<Option<(Session, Dim, u8)>> = Mutex::new(None);
pub(super) fn sent_look(game: &Game<'_>) -> Option<(f32, f32)> {
    LOOK.lock()
        .unwrap_or_else(|e| e.into_inner())
        .as_ref()
        .filter(|(session, dim, _)| {
            *dim == game.dim
                && game.remote.as_ref().is_some_and(|remote| Arc::ptr_eq(session, &remote.session.counters))
        })
        .map(|(_, _, rotation)| *rotation)
}
pub(super) fn sent_sprinting(game: &Game<'_>) -> bool {
    SPRINT
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .as_ref()
        .filter(|(session, dim, _)| {
            *dim == game.dim
                && game.remote.as_ref().is_some_and(|remote| Arc::ptr_eq(session, &remote.session.counters))
        })
        .is_some_and(|(_, _, sprinting)| *sprinting)
}
pub(super) fn sent_input(game: &Game<'_>) -> u8 {
    INPUT
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .as_ref()
        .filter(|(session, dim, _)| {
            *dim == game.dim
                && game.remote.as_ref().is_some_and(|remote| Arc::ptr_eq(session, &remote.session.counters))
        })
        .map_or(0, |(_, _, input)| *input)
}
// Lifecycle bookkeeping only: keep native sendChanges retry caches accurate
// while ordinary module observers are stopped.
pub(super) fn observe(game: &Game<'_>, packet: &S) {
    if let (S::PlayerInput(input), Some(remote)) = (packet, &game.remote) {
        *INPUT.lock().unwrap_or_else(|e| e.into_inner()) =
            Some((remote.session.counters.clone(), game.dim, input.flags));
    }
    if let (S::PlayerCommand(command), Some(remote)) = (packet, &game.remote)
        && command.id == remote.entity_id
        && matches!(command.action, 1 | 2)
    {
        *SPRINT.lock().unwrap_or_else(|e| e.into_inner()) =
            Some((remote.session.counters.clone(), game.dim, command.action == 1));
    }
    let rotation = match packet {
        S::MovePlayerPosRot(p) => Some((p.yaw, p.pitch)),
        S::MovePlayerRot(p) => Some((p.yaw, p.pitch)),
        S::AcceptTeleportation(p) => Some((p.yaw, p.pitch)),
        _ => None,
    };
    if let (Some(rotation), Some(remote)) = (rotation, &game.remote) {
        *LOOK.lock().unwrap_or_else(|e| e.into_inner()) = Some((remote.session.counters.clone(), game.dim, rotation));
    }
}

// The one place that tells Sunset a packet is going on the wire now, whether the send hook let it through or Fake Lag
// let it go later, so every module that tracks what the server has hears of each packet once, at the time it goes.
pub(super) fn delivered(game: &Game<'_>, packet: &S) {
    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() {
        observe(game, packet);
        return;
    }
    forwarded(game, packet);
    super::sunset_cart::sent(game, packet);
    super::sunset_render::sent(game, packet);
    super::sunset_drain::sent(game, packet);
    super::sunset_effects::sent(game, packet);
    super::sunset_lag::sent(game, packet);
    super::sunset_backtrack::sent(game, packet);
}

pub(super) fn forwarded(game: &Game<'_>, packet: &S) {
    observe(game, packet);
    if !game.native_window() || !game.native_on(super::sunset::ID) {
        if game.native_window() {
            super::sunset_gui_move::forwarded(game, packet);
        }
        return;
    }
    super::sunset_gui_move::forwarded(game, packet);
    super::sunset_inventory_slots::sent(packet);
    if let S::Attack(p) = packet {
        attack_slow(game, p.id);
    }
    super::sunset_prediction::forwarded(game, packet);
    super::sunset_melee::forwarded(game, packet);
    super::sunset_auto_mace::forwarded(game, packet);
    super::sunset_combat_inventory::forwarded(game, packet);
}

pub(super) fn reset_look() {
    *LOOK.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *SPRINT.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *INPUT.lock().unwrap_or_else(|e| e.into_inner()) = None;
}

// Player.attack's own side, on the attacking client: a hit on a player with a sprint and over 0.9 of the charge
// knocks back, and the attacker's speed across is cut to 0.6 and the sprint stops. The game's remote attack (and every
// Sunset hit) sends the packet only, but Grim counts the cut as certain then (PacketPlayerAttack: minAttackSlow) and
// keeps no uncut move, so the next movement takes it, before it runs (motion_flags' attack slow).
// The charge is the game's own (getAttackStrengthScale): the attack speed of the item the last tick held
// (`attack_item`), not of one switched in for this hit. Its modifiers come with the player's tick, on the server too,
// so a sword charged long ago swapped for a mace still hits charged, and the cut is due.
fn attack_slow(game: &Game<'_>, id: i32) {
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let charge = game.hand_strength.scale(0.5, game.main_hand_attack_speed());
    let player = super::remote::sunset_combat_remote::is_player(game, id);
    let cut = p.sprinting && charge > 0.9 && player;
    if cut {
        horizon_client::motion::sunset_motion::add_attack_slow(game.ticks);
    }
}

// Crosshair: Sunset's own crosshair, drawn as shapes. Each hud_layers call hands the frame to the hud crate's hook,
// which draws it only where the game draws its own crosshair.

use super::Game;
use super::sunset::{Category, ID, Module};
use super::sunset_crosshair_math::{Style, geometry};
use horizon_client::hud::sunset_crosshair::{self as bridge, Frame};
use horizon_client::hud::HudBatch;

pub(super) fn defaults() -> Vec<Module> {
    vec![Module::new(
        "Crosshair",
        Category::Render,
        "Custom crosshair.",
    )
    .pick("Mode", &["Cross", "Dot"])
    .num("Length", 6.0, 1.0, 32.0, 1.0)
    .num("Gap", 3.0, 0.0, 32.0, 1.0)
    .num("Thickness", 1.0, 1.0, 8.0, 1.0)
    .bool("Center dot", false)
    .num("Dot size", 2.0, 1.0, 8.0, 1.0)
    .num("Outline", 1.0, 0.0, 4.0, 1.0)
    .colour("Color", "White")
    .colour("Outline color", "Black")]
}

// Called at HEAD Game::hud_layers. Reset before every gate, including an early
// screen/loading exit, so a previous enabled frame cannot suppress vanilla.
pub(super) fn prepare(game: &Game<'_>, size: [u32; 2]) {
    bridge::set_frame(Frame::empty());
    if !game.native_window() || !game.native_on(ID) || !game.native_playing()
        || game.player.is_none() || game.ui.hide_gui || !game.camera_type.first_person()
        || game.debug_crosshair() || (game.spectator() && !game.spectator_crosshair())
    {
        return;
    }
    super::sunset::ensure_loaded(game);
    // Sunset leaves Screen::Playing active while its pointer-driven ClickGUI
    // is open. This extra gate covers that overlay, including its close frame.
    if super::sunset::gui_open() {
        return;
    }
    // Borrow settings under the existing state lock, copying only scalar
    // values. Unlike snapshot()/Module::clone(), this allocates nothing.
    let settings = super::sunset::with(|s| {
        let m = s.module("Crosshair").filter(|m| m.on)?;
        Some((Style {
            dot_only: m.p("Mode") == "Dot",
            center_dot: m.b("Center dot"),
            length: m.n("Length"),
            gap: m.n("Gap"),
            thickness: m.n("Thickness"),
            dot_size: m.n("Dot size"),
            outline: m.n("Outline"),
        }, m.c("Color"), m.c("Outline color")))
    });
    let Some((style, color, outline_color)) = settings else {
        return;
    };
    let Some(shape) = geometry(size, 1.0, style) else {
        return;
    };
    let mut frame = Frame::empty();
    let Some(mark) = game.gui.atlas.sprites.get("gui/sprites/hud/crosshair") else {
        return;
    };
    frame.set_crosshair([mark.u0, mark.v0, mark.u1, mark.v1]);
    // All outlines precede all foreground bars, so neighboring outlines
    // never cover the cross itself at small gaps or large thicknesses.
    if shape.outline > 0.0 {
        for rect in shape.rects() {
            frame.push(rect.expanded(shape.outline).gui(1.0), outline_color);
        }
    }
    for rect in shape.rects() {
        frame.push(rect.gui(1.0), color);
    }
    bridge::set_frame(frame);
}

// Runs after vanilla's mark and indicators, within the host show_hud branch.
// The bridge draws only if that mark was actually suppressed this frame.
pub(super) fn draw(game: &Game<'_>, batch: &mut HudBatch) {
    bridge::draw(batch, &game.gui.atlas);
}

// The crosshair's shapes, with no allocation. Sizes and edges are in physical pixels; only the last step uses the
// HUD's GUI scale.

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub(super) struct Rect {
    pub(super) x: f32,
    pub(super) y: f32,
    pub(super) width: f32,
    pub(super) height: f32,
}

impl Rect {
    pub(super) fn expanded(self, pixels: f32) -> Self {
        Self {
            x: self.x - pixels,
            y: self.y - pixels,
            width: self.width + 2.0 * pixels,
            height: self.height + 2.0 * pixels,
        }
    }

    pub(super) fn gui(self, scale: f32) -> [f32; 4] {
        [self.x / scale, self.y / scale, self.width / scale, self.height / scale]
    }
}

#[derive(Clone, Copy, Debug)]
pub(super) struct Style {
    pub(super) dot_only: bool,
    pub(super) center_dot: bool,
    pub(super) length: f64,
    pub(super) gap: f64,
    pub(super) thickness: f64,
    pub(super) dot_size: f64,
    pub(super) outline: f64,
}

#[derive(Clone, Copy, Debug)]
pub(super) struct Geometry {
    rects: [Rect; 5],
    len: usize,
    pub(super) outline: f32,
}

impl Geometry {
    pub(super) fn rects(&self) -> &[Rect] {
        &self.rects[..self.len]
    }
}

fn pixels(value: f64, default: f64, min: f64, max: f64) -> f32 {
    let value = if value.is_finite() { value } else { default };
    value.round().clamp(min, max) as f32
}

// An odd-width mark cannot be centered exactly on an even-width viewport and
// still have integer edges. Choose the nearest crisp center, at most half a
// physical pixel towards the upper left. All arms share that center.
fn centered(size: u32, width: f32) -> f32 {
    ((size as f32 - width) * 0.5).floor()
}

pub(super) fn geometry(size: [u32; 2], scale: f32, style: Style) -> Option<Geometry> {
    // At larger sizes f32 cannot represent every physical-pixel edge. Real
    // render targets are well below this; fail closed instead of drawing NaNs.
    if size.into_iter().any(|s| s == 0 || s > (1 << 23)) || !scale.is_finite() || scale <= 0.0 {
        return None;
    }
    let length = pixels(style.length, 6.0, 1.0, 32.0);
    let gap = pixels(style.gap, 3.0, 0.0, 32.0);
    let thickness = pixels(style.thickness, 1.0, 1.0, 8.0);
    let dot_size = pixels(style.dot_size, 2.0, 1.0, 8.0);
    let mut out = Geometry {
        rects: [Rect::default(); 5],
        len: 0,
        outline: pixels(style.outline, 1.0, 0.0, 4.0),
    };
    if !style.dot_only {
        let x = centered(size[0], thickness);
        let y = centered(size[1], thickness);
        out.rects[..4].copy_from_slice(&[
            Rect { x: x - gap - length, y, width: length, height: thickness },
            Rect { x: x + thickness + gap, y, width: length, height: thickness },
            Rect { x, y: y - gap - length, width: thickness, height: length },
            Rect { x, y: y + thickness + gap, width: thickness, height: length },
        ]);
        out.len = 4;
    }
    if style.dot_only || style.center_dot {
        out.rects[out.len] = Rect {
            x: centered(size[0], dot_size),
            y: centered(size[1], dot_size),
            width: dot_size,
            height: dot_size,
        };
        out.len += 1;
    }
    Some(out)
}

// Crystal Aura (Rust's, PR #16): places end crystals (and
// the obsidian under them, Auto Obsidian) and breaks them on enemy players, for the damage it can see they take and
// never more than Max Self Damage to you or a friend. Only crystals the server has shown are hit; a placement waits for
// its crystal or a timeout.
use super::remote::sunset_aura_base::{self as base_native, BaseClick};
use super::sunset::{self, Category, Module, gui_open, own_id, with};
use super::sunset_crystal_setup_policy as setup;
use super::sunset_explosive_aura::Rating;
use super::sunset_explosive_damage::{Blast, clear_line, local_damage_at};
use super::sunset_explosive_policy::{Budget, in_range};
use super::{sunset_explosive_choice::Kind, sunset_explosive_tactics as tactics};
use horizon_world::registry::BlockStateId;
use std::{any::Any, sync::Arc};
type SetupScene = (i32, super::Dim, Arc<dyn Any + Send + Sync>);
use super::Game;
use super::sunset_util::{self as util, Target};
use super::{sunset_faceplace_policy as face, sunset_lead_policy as lead, sunset_prediction as prediction};
use horizon_protocol::packets::{
    Empty,
    play::{self, Clientbound as C, Serverbound as S},
};
use std::sync::Mutex;
use std::time::{Duration, Instant};

const NAME: &str = "Crystal Aura";
const MAX_ENTITIES: usize = 512;
const MAX_CANDIDATES: usize = 4;
// Evaluate up to eight crystal and obsidian setups after ranking them by potential damage.
const MAX_SETUPS: usize = 8;
// A crystal or obsidian spot it has turned toward this long without reaching it is left alone for SKIP_TICKS
// (Anchor Aura does the same).
const AIM_TICKS: u64 = 12;
const SKIP_TICKS: u64 = 40;
const PREDICTIONS: usize = 24;

mod state {
    // Unit direction, slab intersection with the actual entity bounds. Return
    // the first contact, including the eye when it is already inside the box.
    pub(super) fn ray_box(
        eye: [f64; 3],
        direction: [f64; 3],
        lo: [f64; 3],
        hi: [f64; 3],
        range: f64,
    ) -> Option<[f64; 3]> {
        if !eye
            .iter()
            .chain(direction.iter())
            .chain(lo.iter())
            .chain(hi.iter())
            .chain([range].iter())
            .all(|v| v.is_finite())
            || range < 0.0
            || (0..3).any(|i| lo[i] > hi[i])
        {
            return None;
        }
        let norm = direction.iter().map(|v| v * v).sum::<f64>().sqrt();
        if norm < 1.0e-12 {
            return None;
        }
        let dir = direction.map(|v| v / norm);
        let (mut near, mut far) = (0.0f64, range);
        for i in 0..3 {
            if dir[i].abs() < 1.0e-12 {
                if eye[i] < lo[i] || eye[i] > hi[i] {
                    return None;
                }
            } else {
                let a = (lo[i] - eye[i]) / dir[i];
                let b = (hi[i] - eye[i]) / dir[i];
                near = near.max(a.min(b));
                far = far.min(a.max(b));
                if near > far {
                    return None;
                }
            }
        }
        Some(std::array::from_fn(|i| eye[i] + dir[i] * near))
    }
    pub(super) fn ray_end(eye: [f64; 3], hit: [f64; 3]) -> [f64; 3] {
        let length = (0..3).map(|i| (hit[i] - eye[i]).powi(2)).sum::<f64>().sqrt();
        if length <= 1.0e-5 {
            return eye;
        }
        std::array::from_fn(|i| hit[i] + (eye[i] - hit[i]) / length * 1.0e-5)
    }

    #[derive(Clone, Copy, Debug, PartialEq)]
    pub(super) enum Action {
        Place([i32; 3]),
        Base([i32; 3]),
        Break(u32, [f64; 3]),
    }
    #[derive(Clone, Copy, Debug)]
    pub(super) struct Waiting {
        pub action: Action,
        pub sent: u64,
    }
    #[derive(Default)]
    pub(super) struct Clock {
        pub crystals: usize,
        pub queued: bool,
        pub waiting: Option<Waiting>,
        pub next: u64,
        pub next_base: u64,
        pub next_place: u64,
        pub next_break: u64,
        pub generation: u64,
    }
    impl Clock {
        pub fn suspend(&mut self) {
            self.queued = false;
            self.generation = self.generation.wrapping_add(1);
        }
        pub fn reset(&mut self) {
            let generation = self.generation.wrapping_add(1);
            *self = Self { generation, ..Self::default() };
        }
        pub fn sent(&mut self, action: Action, tick: u64, delay: u64) {
            self.queued = false;
            self.waiting = Some(Waiting { action, sent: tick });
            self.next = tick.saturating_add(delay.max(1));
            match action {
                Action::Base(_) | Action::Place(_) => {
                    self.next_base = self.next;
                    self.next_place = self.next;
                }
                Action::Break(_, _) => self.next_break = self.next,
            }
        }
        pub fn observe(&mut self, tick: u64, acknowledged: bool) {
            if self.waiting.is_some_and(|w| acknowledged || tick.saturating_sub(w.sent) >= 30) {
                self.waiting = None;
            }
        }

        pub fn available(&self) -> bool {
            !self.queued && self.waiting.is_none()
        }
        pub fn due(&self, action: Action, tick: u64) -> bool {
            self.available()
                && tick
                    >= match action {
                        Action::Base(_) => self.next_base,
                        Action::Place(_) => self.next_place,
                        Action::Break(_, _) => self.next_break,
                    }
        }
    }
}
