pub(super) fn visible(m: &Module, name: &str) -> bool {
    match name {
        "Circles self only" | "Circle radius" | "Circle duration (ms)" | "Circle thickness" | "Circle glow" => m.b("Jump circles"),
        "Trail mode" | "Trails self only" | "Trail duration (ms)" | "Trail size" => m.b("Trails"),
        "Particle amount" | "Particle lifespan (s)" | "Particle physics" | "On totem pops" => m.b("Hit particles"),
        "Weather mode" | "Density" | "Weather radius" | "Weather speed" | "Weather size" => m.b("Weather"),
        "Custom color" => m.p("Color") == "Custom",
        _ => true,
    }
}

// ---- shapes

// A filled circle on screen.
pub(super) fn disc(out: &mut impl Canvas, [x, y]: [f32; 2], r: f32, argb: u32) {
    const N: usize = 12;
    if r < 0.3 || argb >> 24 == 0 {
        return;
    }
    let rim = |k: usize| {
        let a = k as f32 * TAU / N as f32;
        [x + r * a.cos(), y + r * a.sin()]
    };
    for k in (0..N).step_by(2) {
        out.quad([[x, y], rim(k), rim(k + 1), rim(k + 2)], argb);
    }
}

// A soft dot: a faint wide halo, a brighter middle, a bright core.
pub(super) fn glow(out: &mut impl Canvas, at: [f32; 2], r: f32, argb: u32) {
    let a = (argb >> 24) as f32;
    let with = |k: f32| ((a * k).round().clamp(0.0, 255.0) as u32) << 24 | (argb & 0x00FF_FFFF);
    disc(out, at, r * 2.2, with(0.12));
    disc(out, at, r * 1.4, with(0.3));
    disc(out, at, r * 0.7, with(0.85));
}

// `rgb` mixed toward white (t > 0) or black (t < 0) by |t|.
pub(super) fn shade(rgb: u32, t: f32) -> u32 {
    let to = if t >= 0.0 { 255.0 } else { 0.0 };
    let k = t.abs().min(1.0);
    let ch = |s: u32| {
        let c = ((rgb >> s) & 0xFF) as f32;
        ((c + (to - c) * k).round() as u32) << s
    };
    ch(16) | ch(8) | ch(0)
}

pub(super) fn mix(a: u32, b: u32, t: f32) -> u32 {
    let t = t.clamp(0.0, 1.0);
    let ch = |s: u32| {
        let (x, y) = (((a >> s) & 0xFF) as f32, ((b >> s) & 0xFF) as f32);
        ((x + (y - x) * t).round() as u32) << s
    };
    ch(16) | ch(8) | ch(0)
}

pub(super) fn alpha(rgb: u32, a: f32) -> u32 {
    ((a.clamp(0.0, 1.0) * 255.0).round() as u32) << 24 | (rgb & 0x00FF_FFFF)
}

// A flat ring round `at` in the ground's plane: its band `thickness` wide at `radius`, with a fainter `glow` band
// either side.
fn ring(cam: &Camera, out: &mut impl Canvas, at: [f64; 3], radius: f32, thickness: f32, glow: f32, rgb: u32, a: f32) {
    const N: usize = 48;
    if !cam.sees(at, f64::from(radius + thickness + glow)) {
        return;
    }
    let point = |r: f32, k: usize| {
        let t = k as f32 * TAU / N as f32;
        cam.project([at[0] + f64::from(r * t.cos()), at[1], at[2] + f64::from(r * t.sin())])
    };
    let (inner, outer) = (radius - thickness / 2.0, radius + thickness / 2.0);
    let bands = [(inner - glow, inner, a * 0.3), (inner, outer, a), (outer, outer + glow, a * 0.3)];
    for (lo, hi, a) in bands.into_iter().filter(|b| b.1 > b.0.max(0.0)) {
        let colour = alpha(rgb, a);
        let lo = lo.max(0.0);
        for k in 0..N {
            if let (Some(p), Some(q), Some(r), Some(s)) = (point(lo, k), point(hi, k), point(hi, k + 1), point(lo, k + 1)) {
                out.quad([p, q, r, s], colour);
            }
        }
    }
}

// A flat oval on the ground at `at`, its long side along `yaw` (half sizes, blocks).
fn oval(cam: &Camera, out: &mut impl Canvas, at: [f64; 3], yaw: f32, half: [f32; 2], argb: u32) {
    const N: usize = 12;
    let (s, c) = yaw.to_radians().sin_cos();
    let (fwd, right) = ([-s, c], [c, s]);
    let rim = |k: usize| {
        let t = k as f32 * TAU / N as f32;
        let (w, l) = (half[0] * t.cos(), half[1] * t.sin());
        cam.project([at[0] + f64::from(right[0] * w + fwd[0] * l), at[1], at[2] + f64::from(right[1] * w + fwd[1] * l)])
    };
    let Some(mid) = cam.project(at) else {
        return;
    };
    for k in (0..N).step_by(2) {
        if let (Some(a), Some(b), Some(c)) = (rim(k), rim(k + 1), rim(k + 2)) {
            out.quad([mid, a, b, c], argb);
        }
    }
}

// ---- state

struct Circle {
    at: [f64; 3],
    born: Instant,
    life: f32,
}

#[derive(Clone, Copy, PartialEq)]
enum Trail {
    Footstep,
    Ring,
    Spark,
}

struct Mark {
    at: [f64; 3],
    yaw: f32,
    kind: Trail,
    vel: [f64; 3],
    shade: f32,
    born: Instant,
    life: f32,
}

struct Spark {
    prev: [f64; 3],
    at: [f64; 3],
    vel: [f64; 3],
    pop: bool,
    born: Instant,
}

struct Drop {
    at: [f64; 3],
    vel: [f64; 3],
    age: f32,
    life: f32,
    phase: f32,
    shade: f32,
}

#[derive(Default)]
struct Fx {
    // Players last tick: on the ground, and their y; where the last trail mark went, and which foot.
    last: Vec<(u32, bool, f64)>,
    steps: Vec<(u32, [f64; 3], bool)>,
    circles: Vec<Circle>,
    marks: Vec<Mark>,
    sparks: Vec<Spark>,
    drops: Vec<Drop>,
    weather_from: Option<[f64; 3]>,
    frame: Option<Instant>,
    epoch: Option<Instant>,
    // A player's shield put out by an axe: until when (tick).
    broken: Vec<(u32, u64)>,
    // Each player's or mob's totem pops (event 35) since they appeared: Nametags' Totem pops.
    pops: Vec<(u32, u32)>,
    roll: u64,
}

static FX: Mutex<Option<Fx>> = Mutex::new(None);

fn st<R>(f: impl FnOnce(&mut Fx) -> R) -> R {
    f(FX.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Fx::default))
}

fn random(fx: &mut Fx) -> f64 {
    fx.roll = (fx.roll ^ 0x9E37_79B9_7F4A_7C15).wrapping_mul(0xBF58_476D_1CE4_E5B9) | 1;
    fx.roll ^= fx.roll >> 31;
    (fx.roll >> 11) as f64 / (1u64 << 53) as f64
}

fn module() -> Option<Module> {
    with(|s| s.module(NAME).filter(|m| m.on).cloned())
}

fn colour(m: &Module) -> u32 {
    if m.p("Color") == "Custom" { m.c("Custom color") & 0x00FF_FFFF } else { accent() & 0x00FF_FFFF }
}

// Where your hits and pops start sparks: a mob's middle.
fn sparks_at(fx: &mut Fx, m: &Module, at: [f64; 3], count: usize, pop: bool) {
    let cap = (m.n("Particle lifespan (s)") * 20.0) as usize;
    for _ in 0..count {
        if fx.sparks.len() > cap {
            break;
        }
        let p = [at[0] + (random(fx) - 0.5) * 0.5, at[1] + random(fx) + 0.5, at[2] + (random(fx) - 0.5) * 0.5];
        // Blocks a tick: up to an eighth across, up to an eighth up.
        let vel = [(random(fx) - 0.5) * 0.25, random(fx) * 0.125, (random(fx) - 0.5) * 0.25];
        fx.sparks.push(Spark { prev: p, at: p, vel, pop, born: Instant::now() });
    }
}

fn mob_feet(game: &Game<'_>, id: u32) -> Option<[f64; 3]> {
    game.mobs.iter().find(|mob| mob.id == id).map(|mob| [mob.position.x, mob.position.y, mob.position.z])
}

// Your attack on a mob: Hit particles off it.
pub(super) fn sent(game: &Game<'_>, packet: &S) {
    let S::Attack(a) = packet else {
        return;
    };
    let (Some(m), Ok(id)) = (module().filter(|m| m.b("Hit particles")), u32::try_from(a.id)) else {
        return;
    };
    if let Some(at) = mob_feet(game, id) {
        st(|fx| sparks_at(fx, &m, at, m.n("Particle amount") as usize, false));
    }
}

// A player's totem pop (event 35): twice the sparks; a shield put out (event 30): remembered five seconds for ESP.
pub(super) fn packet(game: &Game<'_>, packet: &C) {
    let C::EntityEvent(e) = packet else {
        return;
    };
    let Ok(id) = u32::try_from(e.id) else {
        return;
    };
    let player = game.mobs.iter().any(|mob| mob.id == id && mob.kind.id == "minecraft:player");
    if e.event == 30 && player {
        let until = game.ticks + 100;
        st(|fx| {
            fx.broken.retain(|(i, _)| *i != id);
            fx.broken.push((id, until));
        });
    }
    if e.event == 35 {
        st(|fx| match fx.pops.iter_mut().find(|(i, _)| *i == id) {
            Some((_, n)) => *n += 1,
            None => fx.pops.push((id, 1)),
        });
    }
    if e.event == 35
        && player
        && let Some(m) = module().filter(|m| m.b("Hit particles") && m.b("On totem pops"))
        && let Some(at) = mob_feet(game, id)
    {
        st(|fx| sparks_at(fx, &m, at, m.n("Particle amount") as usize * 2, true));
    }
}

// ESP's shield colours: a player's shield put out by an axe in the last five seconds.
pub(super) fn shield_broken(game: &Game<'_>, id: u32) -> bool {
    st(|fx| fx.broken.iter().any(|&(i, until)| i == id && game.ticks < until))
}

// ---- the tick: jumps, trail marks, spark physics

fn solid(game: &Game<'_>, p: [f64; 3]) -> bool {
    let b = p.map(|v| v.floor() as i32);
    !super::sunset_util::replaceable(game, b)
}

// How many totems a player or mob has popped since they appeared (a respawn or rejoin starts again).
pub(super) fn pops(id: u32) -> u32 {
    st(|fx| fx.pops.iter().find(|(i, _)| *i == id).map_or(0, |(_, n)| *n))
}

pub(super) fn tick(game: &Game<'_>) {
    st(|fx| {
        fx.broken.retain(|&(_, until)| game.ticks < until);
        fx.pops.retain(|(id, _)| game.mobs.iter().any(|mob| mob.id == *id && mob.alive()));
    });
    let Some(m) = module().filter(|_| game.player.is_some()) else {
        st(|fx| {
            let broken = std::mem::take(&mut fx.broken);
            *fx = Fx { broken, roll: fx.roll, ..Fx::default() };
        });
        return;
    };
    let me = own_id(game);
    let mut players: Vec<(u32, [f64; 3], bool, f32)> = Vec::new();
    if let (Some(p), Some(id)) = (game.player.as_ref(), me) {
        players.push((id, [p.position.x, p.position.y, p.position.z], p.ground.on_ground, game.yaw));
    }
    players.extend(
        game.mobs
            .iter()
            .filter(|mob| mob.kind.id == "minecraft:player" && Some(mob.id) != me && mob.alive() && !mob.removed)
            .map(|mob| (mob.id, [mob.position.x, mob.position.y, mob.position.z], mob.on_ground, mob.yaw)),
    );
    let now = Instant::now();
    st(|fx| {
        let mut seen = Vec::with_capacity(players.len());
        for &(id, at, ground, yaw) in &players {
            let own = Some(id) == me;
            // Jump circles: off the ground since last tick and going up.
            let before = fx.last.iter().find(|l| l.0 == id).copied();
            if m.b("Jump circles")
                && (own || !m.b("Circles self only"))
                && let Some((_, was_ground, was_y)) = before
                && was_ground
                && !ground
                && at[1] - was_y > 0.05
            {
                fx.circles.push(Circle { at: [at[0], was_y + 0.01, at[2]], born: now, life: (m.n("Circle duration (ms)") / 1000.0) as f32 });
            }
            seen.push((id, ground, at[1]));
            // Trails: a mark each so far walked on the ground.
            if m.b("Trails") && (own || !m.b("Trails self only")) && ground {
                let kind = match m.p("Trail mode") {
                    "Ring" => Trail::Ring,
                    "Particles" => Trail::Spark,
                    _ => Trail::Footstep,
                };
                let spacing = match kind {
                    Trail::Spark => 0.25,
                    Trail::Ring => 0.65,
                    Trail::Footstep => 0.75,
                };
                let life = (m.n("Trail duration (ms)") / 1000.0) as f32;
                match fx.steps.iter().position(|s| s.0 == id) {
                    None => fx.steps.push((id, at, false)),
                    Some(i) if ((at[0] - fx.steps[i].1[0]).powi(2) + (at[2] - fx.steps[i].1[2]).powi(2)).sqrt() >= spacing => {
                        let left = fx.steps[i].2;
                        match kind {
                            Trail::Footstep => {
                                let (s, c) = (f64::from(yaw.to_radians().sin()), f64::from(yaw.to_radians().cos()));
                                let side = if left { -0.18 } else { 0.18 };
                                let foot = [at[0] + c * side, at[1] + 0.02, at[2] + s * side];
                                fx.marks.push(Mark { at: foot, yaw, kind, vel: [0.0; 3], shade: 0.5, born: now, life });
                            }
                            Trail::Spark => {
                                for _ in 0..4 {
                                    let a = random(fx) * std::f64::consts::TAU;
                                    let speed = 0.025 + random(fx) * 0.05;
                                    let vel = [a.cos() * speed, 0.05 + random(fx) * 0.05, a.sin() * speed];
                                    let shade = random(fx) as f32;
                                    fx.marks.push(Mark { at, yaw, kind, vel, shade, born: now, life });
                                }
                            }
                            Trail::Ring => {
                                let shade = random(fx) as f32;
                                fx.marks.push(Mark { at: [at[0], at[1] + 0.01, at[2]], yaw, kind, vel: [0.0; 3], shade, born: now, life });
                            }
                        }
                        fx.steps[i] = (id, at, !left);
                    }
                    Some(_) => {}
                }
            }
        }
        fx.last = seen;
        fx.steps.retain(|s| players.iter().any(|p| p.0 == s.0));
        fx.circles.retain(|c| c.born.elapsed().as_secs_f32() < c.life);
        fx.marks.retain(|k| k.born.elapsed().as_secs_f32() < k.life);
        // Sparks fall slowly, bounce off blocks (with Particle physics) and go after Particle lifespan or 20 blocks off.
        let life = m.n("Particle lifespan (s)") as f32;
        let physics = m.b("Particle physics");
        let eye = game.eye_position().unwrap_or([0.0; 3]);
        for s in &mut fx.sparks {
            s.prev = s.at;
            if physics {
                if solid(game, [s.at[0], s.at[1], s.at[2] + s.vel[2]]) {
                    s.vel[2] *= -0.8;
                }
                if solid(game, [s.at[0], s.at[1] + s.vel[1], s.at[2]]) {
                    s.vel = [s.vel[0] * 0.999, s.vel[1] * -0.6, s.vel[2] * 0.999];
                }
                if solid(game, [s.at[0] + s.vel[0], s.at[1], s.at[2]]) {
                    s.vel[0] *= -0.8;
                }
            }
            s.at = [s.at[0] + s.vel[0], s.at[1] + s.vel[1], s.at[2] + s.vel[2]];
            s.vel[1] -= if s.pop { 0.01375 } else { 0.00375 };
        }
        fx.sparks.retain(|s| s.born.elapsed().as_secs_f32() < life && super::sunset_util::dist(eye, s.at) <= 20.0);
    });
}

// ---- weather

fn new_drop(game: &Game<'_>, fx: &mut Fx, mode: &str, around: [f64; 3], radius: f64) -> Option<Drop> {
    let a = random(fx) * std::f64::consts::TAU;
    let d = random(fx).sqrt() * radius;
    let (x, z) = (around[0] + a.cos() * d, around[2] + a.sin() * d);
    let r = |fx: &mut Fx| random(fx) - 0.5;
    let (y, vel, life) = match mode {
        "Snow" => (around[1] - 3.0 + random(fx) * 23.0, [r(fx) * 0.02, -0.06, r(fx) * 0.02], 600.0),
        "Fireflies" => (around[1] - 1.0 + random(fx) * 6.0, [r(fx) * 0.015, r(fx) * 0.01, r(fx) * 0.015], 400.0),
        "Embers" => (around[1] - 4.0 + random(fx) * 12.0, [r(fx) * 0.01, 0.05 + random(fx) * 0.02, r(fx) * 0.01], 300.0),
        _ => (around[1] - 4.0 + random(fx) * 28.0, [0.0, -0.45, 0.0], 200.0),
    };
    let at = [x, y, z];
    // Rain and snow only fall under open sky.
    if matches!(mode, "Rain" | "Snow") && (1..=32).any(|k| solid(game, [x, y + f64::from(k), z])) {
        return None;
    }
    if solid(game, at) {
        return None;
    }
    let (phase, shade) = ((random(fx) * std::f64::consts::TAU) as f32, random(fx) as f32);
    Some(Drop { at, vel, age: (random(fx) * life * 0.5) as f32, life: life as f32, phase, shade })
}

fn weather(game: &Game<'_>, fx: &mut Fx, m: &Module, dt: f32) {
    let Some(eye) = game.eye_position() else {
        return;
    };
    let (mode, density, radius) = (m.p("Weather mode"), m.n("Density") as usize, m.n("Weather radius"));
    let refill = fx.drops.is_empty() || fx.weather_from.is_some_and(|w| super::sunset_util::dist(w, eye) > 16.0);
    fx.weather_from = Some(eye);
    let tries = if refill { density * 6 } else { (dt * (density / 20).max(1) as f32).ceil() as usize };
    for _ in 0..tries {
        if fx.drops.len() >= density {
            break;
        }
        if let Some(d) = new_drop(game, fx, mode, eye, radius) {
            fx.drops.push(d);
        }
    }
    let step = f64::from(dt) * m.n("Weather speed");
    for d in &mut fx.drops {
        d.at = [d.at[0] + d.vel[0] * step, d.at[1] + d.vel[1] * step, d.at[2] + d.vel[2] * step];
        d.age += dt * m.n("Weather speed") as f32;
    }
    let far = radius * 1.6;
    fx.drops.retain(|d| d.age <= d.life && super::sunset_util::dist(d.at, eye) <= far && !solid(game, d.at));
}

// ---- the frame

pub(super) fn draw(game: &Game<'_>, cam: &Camera, mods: &[Module], out: &mut impl Canvas) {
    let Some(m) = mods.iter().find(|m| m.name == NAME && m.on) else {
        return;
    };
    let rgb = colour(m);
    let (bright, dark) = (shade(rgb, 0.3), shade(rgb, -0.3));
    let partial = game.clock.camera_fraction();
    st(|fx| {
        let now = Instant::now();
        let dt = fx.frame.map_or(0.0, |f| (now - f).as_secs_f32() * 20.0).min(4.0);
        fx.frame = Some(now);
        if m.b("Weather") {
            weather(game, fx, m, dt);
        } else {
            fx.drops.clear();
        }
        let ease = |f: f32| 1.0 - (1.0 - f) * (1.0 - f);
        // Jump circles: grow to Circle radius, in over the first fifth of their time, out over the rest.
        let (thick, glow_w, radius) = (m.n("Circle thickness") as f32, m.n("Circle glow") as f32, m.n("Circle radius") as f32);
        for c in &fx.circles {
            let f = c.born.elapsed().as_secs_f32() / c.life;
            let a = if f < 0.2 { f / 0.2 } else { 1.0 - (f - 0.2) / 0.8 };
            ring(cam, out, c.at, 0.1 + (radius - 0.1) * ease(f), thick, glow_w, bright, a.clamp(0.0, 1.0));
        }
        let size = m.n("Trail size") as f32;
        for k in &fx.marks {
            let f = k.born.elapsed().as_secs_f32() / k.life;
            let a = 1.0 - f * f;
            match k.kind {
                Trail::Footstep => {
                    oval(cam, out, k.at, k.yaw, [0.25 * size, 0.42 * size], alpha(shade(rgb, -0.4), a * 0.45));
                    oval(cam, out, k.at, k.yaw, [0.16 * size, 0.3 * size], alpha(rgb, a));
                }
                Trail::Ring => ring(cam, out, k.at, (0.05 + 0.55 * ease(f)) * size, 0.018, 0.12, mix(dark, bright, k.shade), a),
                Trail::Spark => {
                    let t = f64::from(k.life * f * 20.0);
                    let at = [k.at[0] + k.vel[0] * t, k.at[1] + k.vel[1] * t - 0.0009 * t * t + 0.05, k.at[2] + k.vel[2] * t];
                    if let (Some(p), Some(px)) = (cam.project(at), cam.pixels_per_block(at)) {
                        glow(out, p, (1.6 - 0.5 * f) * 0.05 * size * px, alpha(mix(dark, bright, k.shade), a));
                    }
                }
            }
        }
        let life = m.n("Particle lifespan (s)") as f32;
        let t = fx.epoch.get_or_insert(now).elapsed().as_secs_f32();
        for (i, s) in fx.sparks.iter().enumerate() {
            let at = [0, 1, 2].map(|k| s.prev[k] + (s.at[k] - s.prev[k]) * partial);
            let (Some(p), Some(px)) = (cam.project(at), cam.pixels_per_block(at)) else {
                continue;
            };
            let f = s.born.elapsed().as_secs_f32() / life;
            let wave = ((t * 4.0 + i as f32 * 0.55).sin() + 1.0) * 0.5;
            glow(out, p, if s.pop { 0.14 } else { 0.09 } * px, alpha(mix(dark, bright, wave), 1.0 - f));
        }
        let mode = m.p("Weather mode");
        let wsize = m.n("Weather size") as f32 * 0.04;
        let reach = m.n("Weather radius") * 1.5;
        for d in &fx.drops {
            if super::sunset_util::dist(d.at, cam.eye()) > reach {
                continue;
            }
            let f = d.age / d.life;
            let mut a = if f < 0.1 { f / 0.1 } else if f > 0.7 { (1.0 - f) / 0.3 } else { 1.0 };
            a *= match mode {
                "Fireflies" => 0.35 + 0.65 * ((d.age * 0.12 + d.phase).sin() * 0.5 + 0.5),
                "Embers" => 0.6 + 0.4 * ((d.age * 0.4 + d.phase).sin() * 0.5 + 0.5),
                _ => 1.0,
            };
            let tint = if m.p("Color") == "Custom" { rgb } else { mix(dark, bright, d.shade) };
            let (Some(p), Some(px)) = (cam.project(d.at), cam.pixels_per_block(d.at)) else {
                continue;
            };
            match mode {
                "Rain" => {
                    let w = (0.5 * wsize * px).max(1.0);
                    let h = 4.5 * wsize * px;
                    out.fill([p[0] - w / 2.0, p[1] - h, w, h], alpha(tint, a * 0.8));
                }
                "Snow" => disc(out, p, 0.8 * wsize * px, alpha(tint, a)),
                "Fireflies" => glow(out, p, 1.25 * wsize * px * 0.5, alpha(tint, a)),
                _ => glow(out, p, 0.7 * wsize * px * 0.5, alpha(tint, a)),
            }
        }
    });
}

// ESP's 2D box extras: the box's style (a full box, its corners, or side brackets) with a dark edge under it, a glow
// round it, a health bar on one side (with the health as a number), the name over it and the distance under it;
// and Shield colors, a player's box coloured by their shield (held or raised, or put out by an axe in the last five
// seconds).
use super::Game;
use super::sunset::{Camera, Canvas, Module, outline};
use super::sunset_effects::{alpha, mix};
use horizon_client::mobs::Mob;

#[derive(Clone, Copy, PartialEq)]
enum Style {
    Box,
    Corners,
    Brackets,
}

#[derive(Clone, Copy, PartialEq)]
enum Side {
    Left,
    Right,
    Bottom,
    Top,
}

#[derive(Clone, Copy, PartialEq)]
enum ShieldMode {
    Always,
    Raised,
    Broken,
}

// ESP's 2D settings, read once a frame.
pub(super) struct TwoD {
    style: Style,
    fill: Option<f64>,
    health: Option<Side>,
    health_text: bool,
    names: bool,
    distance: bool,
    glow: bool,
    shield: Option<(ShieldMode, u32, u32)>,
}

impl TwoD {
    pub(super) fn of(m: &Module) -> Self {
        Self {
            style: match m.p("2D style") {
                "Corners" => Style::Corners,
                "Brackets" => Style::Brackets,
                _ => Style::Box,
            },
            fill: (m.p("Shape mode") != "Lines").then(|| m.n("Fill opacity")),
            health: m.b("Health bar").then(|| match m.p("Health side") {
                "Right" => Side::Right,
                "Bottom" => Side::Bottom,
                "Top" => Side::Top,
                _ => Side::Left,
            }),
            health_text: m.b("Health text"),
            names: m.b("2D names"),
            distance: m.b("2D distance"),
            glow: m.b("Glow"),
            shield: m.b("Shield colors").then(|| {
                let mode = match m.p("Shield mode") {
                    "Raised" => ShieldMode::Raised,
                    "Broken" => ShieldMode::Broken,
                    _ => ShieldMode::Always,
                };
                (mode, m.c("Shield color"), m.c("Broken shield color"))
            }),
        }
    }
    // Whether a 2D box needs more than the plain outline.
    pub(super) fn extras(&self) -> bool {
        self.style != Style::Box || self.health.is_some() || self.names || self.distance || self.glow
    }
}

// Shield colors: the box's colour for a player by their shield, if it says one.
pub(super) fn shield_colour(game: &Game<'_>, two: &TwoD, mob: &Mob) -> Option<u32> {
    let (mode, up, broken) = two.shield?;
    if mob.kind.id != "minecraft:player" {
        return None;
    }
    let has = |item: &Option<std::sync::Arc<str>>| item.as_deref() == Some("minecraft:shield");
    let holds = has(&mob.extra.main_hand) || has(&mob.extra.off_hand);
    let raised = mob.extra.blocking && mob.extra.using_item > 0;
    let out = super::sunset_effects::shield_broken(game, mob.id);
    match mode {
        _ if out && mode != ShieldMode::Raised => Some(broken),
        ShieldMode::Always if holds => Some(up),
        ShieldMode::Raised if raised => Some(up),
        _ => None,
    }
}

fn bar(out: &mut impl Canvas, r: [f32; 4], argb: u32) {
    if r[2] > 0.0 && r[3] > 0.0 {
        out.fill(r, argb);
    }
}

// The box round a mob as the 2D settings say. True when it was on screen.
pub(super) fn draw(game: &Game<'_>, cam: &Camera, out: &mut impl Canvas, two: &TwoD, mob: &Mob, lo: [f64; 3], hi: [f64; 3], d: f64, argb: u32, lw: f32) -> bool {
    let Some([x1, y1, x2, y2]) = cam.corners(lo, hi).and_then(|p| cam.bounds(&p)) else {
        return false;
    };
    let (w, h) = (x2 - x1, y2 - y1);
    if w < 3.0 || h < 3.0 {
        return false;
    }
    let a = (argb >> 24) as f32 / 255.0;
    let shadow = alpha(0, a * 0.47);
    if two.glow {
        for i in 1..=4 {
            let grow = 2.0 * i as f32;
            outline(out, [x1 - grow, y1 - grow, x2 + grow, y2 + grow], alpha(argb, a * 0.14 * (1.0 - i as f32 / 5.0)), lw, false);
        }
    }
    if let Some(fill) = two.fill {
        out.fill([x1, y1, w, h], alpha(argb, a * fill as f32));
    }
    let t = lw.max(1.0);
    match two.style {
        Style::Box => {
            outline(out, [x1 - 1.0, y1 - 1.0, x2 + 1.0, y2 + 1.0], shadow, t, false);
            outline(out, [x1, y1, x2, y2], argb, t, false);
        }
        Style::Corners => {
            let len = (w.min(h) * 0.28).max(2.0);
            for (colour, grow) in [(shadow, 1.0), (argb, 0.0)] {
                let (l, r, top, bottom) = (x1 - grow, x2 + grow, y1 - grow, y2 + grow);
                for (x, dx) in [(l, 1.0), (r, -1.0)] {
                    for (y, dy) in [(top, 1.0), (bottom, -1.0)] {
                        let across = if dx > 0.0 { [x, y - t / 2.0, len, t] } else { [x - len, y - t / 2.0, len, t] };
                        let down = if dy > 0.0 { [x - t / 2.0, y, t, len] } else { [x - t / 2.0, y - len, t, len] };
                        bar(out, across, colour);
                        bar(out, down, colour);
                    }
                }
            }
        }
        Style::Brackets => {
            let len = (h * 0.35).max(2.0);
            let mid = (y1 + y2) / 2.0;
            for (colour, grow) in [(shadow, 1.0), (argb, 0.0)] {
                for x in [x1 - grow, x2 + grow] {
                    bar(out, [x - t / 2.0, y1 - grow, t, len], colour);
                    bar(out, [x - t / 2.0, mid - len * 0.2, t, len * 0.4], colour);
                    bar(out, [x - t / 2.0, y2 + grow - len, t, len], colour);
                }
            }
        }
    }
    if let Some(side) = two.health {
        let frac = (mob.health / mob.kind.max_health.max(1.0)).clamp(0.0, 1.0);
        let colour = 0xFF00_0000 | mix(0xFF4A4A, 0x78F58C, frac);
        let back = alpha(0, a * 0.6);
        let (track, full) = match side {
            Side::Left => ([x1 - 5.0, y1, 2.0, h], [x1 - 5.0, y2 - h * frac, 2.0, h * frac]),
            Side::Right => ([x2 + 3.0, y1, 2.0, h], [x2 + 3.0, y2 - h * frac, 2.0, h * frac]),
            Side::Bottom => ([x1, y2 + 3.0, w, 2.0], [x1, y2 + 3.0, w * frac, 2.0]),
            Side::Top => ([x1, y1 - 5.0, w, 2.0], [x1, y1 - 5.0, w * frac, 2.0]),
        };
        bar(out, [track[0] - 0.5, track[1] - 0.5, track[2] + 1.0, track[3] + 1.0], back);
        bar(out, full, colour);
        if two.health_text {
            let hp = (mob.health.max(0.0).round() as i32).to_string();
            let tw = game.native_text_width(&hp);
            let at = match side {
                Side::Left => [track[0] - tw - 2.0, full[1] - 4.0],
                Side::Right => [track[0] + 4.0, full[1] - 4.0],
                Side::Bottom => [x1 + w * frac - tw / 2.0, track[1] + 3.0],
                Side::Top => [x1 + w * frac - tw / 2.0, track[1] - 11.0],
            };
            out.text(&hp, at, 0xF0F0F5);
        }
    }
    if two.names {
        let mut name = String::new();
        super::sunset_util::name_into(game, mob, &mut name);
        let tw = game.native_text_width(&name);
        let at = [(x1 + x2) / 2.0 - tw / 2.0, y1 - 14.0];
        out.fill([at[0] - 3.0, at[1] - 2.0, tw + 6.0, 12.0], alpha(0x10_1016, a * 0.6));
        out.text(&name, at, 0xF0F0FA);
    }
    if two.distance {
        let text = format!("{}m", d.round() as i64);
        let tw = game.native_text_width(&text);
        let at = [(x1 + x2) / 2.0 - tw / 2.0, y2 + 4.0];
        out.fill([at[0] - 2.0, at[1] - 1.0, tw + 4.0, 11.0], alpha(0x10_1016, a * 0.5));
        out.text(&text, at, 0xC8C8DC);
    }
    true
}

// Crystal Aura and Anchor Aura, run together: one acts at a time (the better hit first), and the box each would use
// next is drawn.
use super::sunset::{self, Module};
use super::{Game, Screen};
use std::sync::atomic::AtomicBool;
use std::sync::atomic::Ordering;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
struct View {
    session: Arc<Mutex<Option<Arc<horizon_protocol::connection::Counters>>>>,
    dim: super::Dim,
    pos: [f64; 3],
    from: [f64; 3],
    moved: Instant,
    shown: Instant,
    damage: f64,
    own: f64,
    tick: u64,
}
static VIEWS: Mutex<[Option<View>; 2]> = Mutex::new([None, None]);
static CRYSTAL_ON: AtomicBool = AtomicBool::new(false);
pub(super) fn show(game: &Game<'_>, anchor: bool, pos: [i32; 3], rating: super::sunset_explosive_choice::Rating) {
    let Some(remote) = game.remote.as_ref() else {
        return;
    };
    let now = Instant::now();
    let pos = pos.map(f64::from);
    let mut guard = VIEWS.lock().unwrap_or_else(|e| e.into_inner());
    let previous = guard[usize::from(anchor)].as_ref().filter(|v| {
        v.dim == game.dim
            && Arc::ptr_eq(&v.session, &remote.session.counters)
            && v.shown.elapsed() < Duration::from_millis(500)
    });
    let (from, moved) =
        previous.map_or((pos, now), |v| if v.pos == pos { (v.from, v.moved) } else { (slide(v, now), now) });
    guard[usize::from(anchor)] = Some(View {
        session: remote.session.counters.clone(),
        dim: game.dim,
        pos,
        from,
        moved,
        shown: now,
        damage: rating.full_damage,
        own: rating.self_damage,
        tick: game.ticks,
    });
}
fn slide(view: &View, now: Instant) -> [f64; 3] {
    let fraction = (now.duration_since(view.moved).as_secs_f64() / 0.12).clamp(0.0, 1.0);
    let progress = 1.0 - (1.0 - fraction).powi(3);
    std::array::from_fn(|i| view.from[i] + (view.pos[i] - view.from[i]) * progress)
}
pub(super) fn clear_view(anchor: bool) {
    VIEWS.lock().unwrap_or_else(|e| e.into_inner())[usize::from(anchor)] = None;
}
pub(super) fn draw(
    game: &Game<'_>,
    camera: &sunset::Camera,
    modules: &[Module],
    out: &mut impl sunset::Canvas,
    _width: f32,
) {
    let now = Instant::now();
    let views = VIEWS.lock().unwrap_or_else(|e| e.into_inner()).each_ref().map(|v| {
        v.as_ref()
            .filter(|v| {
                v.dim == game.dim
                    && game.ticks >= v.tick
                    && now.duration_since(v.shown) < Duration::from_millis(500)
                    && game.remote.as_ref().is_some_and(|r| Arc::ptr_eq(&r.session.counters, &v.session))
            })
            .map(|v| {
                (
                    slide(v, now),
                    v.damage,
                    v.own,
                    ((0.5 - now.duration_since(v.shown).as_secs_f64()) / 0.35).clamp(0.0, 1.0),
                )
            })
    });
    for (index, name) in ["Crystal Aura", "Anchor Aura"].iter().enumerate() {
        let Some(module) = modules.iter().find(|m| m.name == *name && m.on && m.b("Aura") && m.b("Render")) else {
            continue;
        };
        let Some((lo, damage, own, alpha)) = views[index] else {
            continue;
        };
        let color = module.t("Render color");
        let color = color
            .strip_prefix('#')
            .or_else(|| color.strip_prefix("0x"))
            .and_then(|s| u32::from_str_radix(s, 16).ok())
            .or_else(|| color.parse::<i32>().ok().map(|n| n as u32))
            .map(|n| if n <= 0x00ff_ffff { n | 0xff00_0000 } else { n })
            .unwrap_or(0xffff_ffff);
        let color = (((f64::from(color >> 24) * alpha).round() as u32) << 24) | (color & 0xffffff);
        super::sunset_visual::draw_box(
            camera,
            out,
            &super::sunset_visual::Look::BOXED,
            lo,
            lo.map(|v| v + 1.0),
            color,
            1.5,
        );
        let top = [lo[0] + 0.5, lo[1] + 1.25, lo[2] + 0.5];
        if let Some([x, y]) = camera.project(top) {
            let label = format!("{damage:.1}  self {own:.1}");
            let width = game.native_text_width(&label);
            out.text(&label, [x - width * 0.5, y], color & 0xffffff);
        }
    }
}

pub(super) use super::sunset_explosive_choice::Rating;
use super::sunset_explosive_choice::prefer_first;

pub(super) fn can_act(game: &Game<'_>) -> bool {
    game.native_window()
        && game.native_on(sunset::ID)
        && game.native_playing()
        && game.screen == Screen::Playing
        && game.remote.is_some()
        && !sunset::gui_open()
        && !game.spectator()
        && game.selected < 9
        && game.using.is_none()
        && game.mining.is_none()
        && super::remote::sunset_remote::breaking(game).is_none()
        && !super::sunset_player::gap_eating()
        && !super::sunset_explosive_tactics::use_conflicts(game)
        && super::sunset_util::inventory_idle(game)
        && game.player.as_ref().is_some_and(|p| p.health.health().is_finite() && p.health.health() > 0.0)
        && sunset::CRIT_STAGE.load(Ordering::Relaxed) == 0
        && super::sunset_combat_control::owner().is_none_or(|o| o == "Crystal Aura" || o == "Anchor Aura")
        && !sunset::with(|s| ["Blink", "Nuker", "Scaffold"].iter().any(|name| s.is_on(name)))
}

pub(super) fn tick(game: &mut Game<'_>, modules: &[Module], ticks: u64) {
    super::sunset_prediction::tick(game);
    // Each module's Aura section (its Macro section is combat_macros.rs's).
    let crystal = modules.iter().find(|m| m.name == "Crystal Aura" && m.on && m.b("Aura"));
    let anchor = modules.iter().find(|m| m.name == "Anchor Aura" && m.on && m.b("Aura"));
    if CRYSTAL_ON.swap(crystal.is_some(), Ordering::Relaxed) && crystal.is_none() {
        super::sunset_crystal_aura::disabled(game);
    }
    if crystal.is_none() && anchor.is_none() {
        super::sunset_crystal_aura::cleanup_shared(game);
    }
    if anchor.is_none() {
        super::sunset_anchor_aura::disabled(game);
    }
    if crystal.is_none() && anchor.is_none() {
        return;
    }
    if !super::sunset_explosive_tactics::refresh(game) || !can_act(game) {
        if crystal.is_some() {
            super::sunset_crystal_aura::paused(game);
        }
        if anchor.is_some() {
            super::sunset_anchor_aura::paused(game);
        }
        return;
    }
    if crystal.is_some()
        && !super::sunset_crystal_aura::owns_selection(game)
        && !super::sunset_explosive_tactics::may_take_hand(game)
    {
        super::sunset_crystal_aura::idle(game);
        super::sunset_anchor_aura::idle(game);
        return;
    }
    // Prepare each at most once, then claim only the chosen action. A pending
    // server acknowledgement is not a new inventory/rotation owner.
    let c = crystal.and_then(|m| super::sunset_crystal_aura::prepare(game, Some(m), ticks)).filter(|r| r.valid());
    super::sunset_anchor_aura::rival(if crystal.is_some() { super::sunset_crystal_aura::opening_value() } else { 0.0 });
    let a = anchor.and_then(|m| super::sunset_anchor_aura::prepare(game, m, ticks)).filter(|r| r.valid());
    let crystal_first = match (c, a) {
        (Some(c), Some(a)) => prefer_first(c, a, ticks % 2 == 0),
        (Some(_), None) => true,
        _ => false,
    };
    if c.is_none() && a.is_none() {
        let c = super::sunset_crystal_aura::lookahead();
        let a = super::sunset_anchor_aura::lookahead();
        let first = match (c, a) {
            (Some(c), Some(a)) => prefer_first(c, a, true),
            (Some(_), None) => true,
            _ => false,
        };
        if first {
            if let Some(m) = crystal {
                super::sunset_crystal_aura::advance_look(game, m);
            }
        } else if let Some(m) = anchor {
            super::sunset_anchor_aura::advance_look(game, m);
        }
        return;
    }
    if crystal_first {
        if let Some(m) = crystal {
            super::sunset_crystal_aura::execute(game, m, ticks);
        }
    } else if a.is_some() {
        if let Some(m) = anchor {
            super::sunset_anchor_aura::execute(game, m, ticks);
        }
    }
}

// Which explosive action goes first, Crystal Aura's or Anchor Aura's, from what each would deal and cost.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Kind {
    CrystalHit,
    AnchorHit,
    Charge,
    CrystalPlace,
    ObsidianPlace,
    AnchorPlace,
}

#[derive(Clone, Copy, Debug)]
pub(super) struct Rating {
    pub kind: Kind,
    pub target_damage: f64,
    pub target_health: f64,
    pub self_damage: f64,
    pub held_totem: bool,
    pub ready_in: u16,
    pub look_credit: f64,
    pub full_damage: f64,
}

impl Rating {
    pub(super) fn new(
        kind: Kind,
        target_damage: f64,
        target_health: f64,
        self_damage: f64,
        held_totem: bool,
        ready_in: u16,
    ) -> Self {
        Self {
            kind,
            target_damage,
            target_health,
            self_damage,
            held_totem,
            ready_in,
            look_credit: 0.0,
            full_damage: target_damage,
        }
    }
    pub(super) fn planning_value(self) -> f64 {
        self.value() + self.look_credit
    }

    pub(super) fn valid(self) -> bool {
        [self.target_damage, self.target_health, self.self_damage].iter().all(|n| n.is_finite() && *n >= 0.0)
            && self.target_health > 0.0
    }
    pub(super) fn lethal(self) -> bool {
        self.target_damage >= self.target_health
    }
    pub(super) fn value(self) -> f64 {
        self.target_damage.min(self.target_health) - 0.5 * self.self_damage
            + if !self.lethal() {
                0.0
            } else if self.held_totem {
                500.0
            } else {
                1000.0
            }
    }
}

// Preserve scan order for exact ties; ready-in is a tie break within one kind.
// This accepts a bounded caller slice; no world scan or packet side effects.
pub(super) fn select(candidates: &[Rating]) -> Option<usize> {
    let mut best: [Option<usize>; 6] = [None; 6];
    let slot = |k| match k {
        Kind::CrystalHit => 0,
        Kind::AnchorHit => 1,
        Kind::Charge => 2,
        Kind::CrystalPlace => 3,
        Kind::ObsidianPlace => 4,
        Kind::AnchorPlace => 5,
    };
    for (i, c) in candidates.iter().copied().enumerate() {
        if !c.valid() {
            continue;
        }
        let at = slot(c.kind);
        if best[at].is_none_or(|old| {
            c.value() > candidates[old].value()
                || c.value() == candidates[old].value() && c.ready_in < candidates[old].ready_in
        }) {
            best[at] = Some(i);
        }
    }
    match (best[0], best[1]) {
        (Some(crystal), Some(anchor)) => {
            let (c, a) = (candidates[crystal], candidates[anchor]);
            Some(if a.value() > c.value() + 1.0 || a.lethal() && !c.lethal() { anchor } else { crystal })
        }
        (Some(i), None) | (None, Some(i)) => Some(i),
        (None, None) => best[2..].iter().copied().flatten().next(),
    }
}

#[derive(Clone, Copy, Debug, Default)]
pub(super) struct Stage {
    pub immediate_crystal: bool,
    pub opening_crystal: bool,
    pub crystal_receipt_pending: bool,
    pub existing_anchor_now: bool,
    pub existing_anchor_opening: bool,
}
impl Stage {
    pub(super) fn new_crystal(self) -> bool {
        !(self.immediate_crystal || self.opening_crystal || self.crystal_receipt_pending)
    }
    pub(super) fn new_anchor(self) -> bool {
        !(self.existing_anchor_now || self.existing_anchor_opening)
    }
}

pub(super) fn opening_horizon(action_steps: u32, opens_in: u32) -> u32 {
    action_steps.max(opens_in)
}

// A block can be placeable but its future crystal can be outside attack reach.
// Check the entity shape, not its center or the clicked block top.
pub(super) fn future_crystal_breakable(eye: [f64; 3], base: [i32; 3], entity_range: f64) -> bool {
    if !eye.iter().all(|n| n.is_finite()) || !entity_range.is_finite() || entity_range <= 0.1 {
        return false;
    }
    let min = [f64::from(base[0]) - 0.5, f64::from(base[1]) + 1.0, f64::from(base[2]) - 0.5];
    let max = [min[0] + 2.0, min[1] + 2.0, min[2] + 2.0];
    let squared = (0..3)
        .map(|i| {
            let n = eye[i].clamp(min[i], max[i]) - eye[i];
            n * n
        })
        .sum::<f64>();
    squared <= (entity_range - 0.1).powi(2)
}

#[cfg(test)]
mod tests {
    use super::*;
    fn c(kind: Kind, target_damage: f64) -> Rating {
        Rating {
            kind,
            target_damage,
            target_health: 20.0,
            self_damage: 0.0,
            held_totem: false,
            ready_in: 0,
            look_credit: 0.0,
            full_damage: target_damage,
        }
    }
    #[test]
    fn setup_advances_existing_cycle_before_new_cycle() {
        assert_eq!(select(&[c(Kind::AnchorPlace, 19.0), c(Kind::CrystalPlace, 15.0), c(Kind::Charge, 6.0)]), Some(2));
    }
    #[test]
    fn crystal_wins_small_anchor_improvement_and_equal_margin() {
        assert_eq!(select(&[c(Kind::CrystalHit, 8.0), c(Kind::AnchorHit, 9.0)]), Some(0));
        assert_eq!(select(&[c(Kind::CrystalHit, 8.0), c(Kind::AnchorHit, 9.01)]), Some(1));
    }
    #[test]
    fn apparent_lethal_anchor_beats_nonlethal_crystal() {
        let mut anchor = c(Kind::AnchorHit, 3.0);
        anchor.target_health = 3.0;
        assert_eq!(select(&[c(Kind::CrystalHit, 19.0), anchor]), Some(1));
    }
    #[test]
    fn observed_totem_pop_and_kill_have_different_priority() {
        let kill = c(Kind::CrystalHit, 20.0);
        let mut pop = kill;
        pop.held_totem = true;
        assert_eq!(select(&[pop, kill]), Some(1));
    }
    #[test]
    fn readiness_breaks_only_equal_within_kind() {
        let mut a = c(Kind::CrystalPlace, 8.0);
        a.ready_in = 3;
        let mut b = a;
        b.ready_in = 1;
        assert_eq!(select(&[a, b, c(Kind::AnchorPlace, 19.0)]), Some(1));
    }
    #[test]
    fn rejects_nonfinite_and_negative_scores_inputs() {
        assert_eq!(select(&[c(Kind::CrystalHit, f64::NAN), c(Kind::AnchorHit, -1.0)]), None);
    }
    #[test]
    fn pending_or_opening_crystal_blocks_another_placement() {
        assert!(Stage::default().new_crystal());
        assert!(!Stage { opening_crystal: true, ..Stage::default() }.new_crystal());
        assert!(!Stage { crystal_receipt_pending: true, ..Stage::default() }.new_crystal());
    }
    #[test]
    fn waiting_existing_anchor_blocks_fresh_anchor() {
        assert!(!Stage { existing_anchor_opening: true, ..Stage::default() }.new_anchor());
        assert!(Stage::default().new_anchor());
        assert_eq!(opening_horizon(2, 8), 8);
    }
    #[test]
    fn placement_reach_alone_does_not_make_crystal_breakable() {
        assert!(!future_crystal_breakable([0.0, 2.0, 0.5], [4, 0, 0], 3.0));
        assert!(future_crystal_breakable([0.0, 2.0, 0.5], [3, 0, 0], 3.0));
    }
    #[test]
    fn box_boundary_is_used_rather_than_crystal_center() {
        assert!(future_crystal_breakable([0.0, 2.0, 0.5], [3, 0, 0], 3.0));
        assert!(!future_crystal_breakable([f64::INFINITY, 2.0, 0.5], [3, 0, 0], 3.0));
    }
}

pub(super) fn prefer_first(first: Rating, second: Rating, _tie_first: bool) -> bool {
    select(&[first, second]) == Some(0)
}

// What an explosion would do to you or a target, from Horizon's own collision shapes and damage rules: never
// changes the world, equipment or anything else.
