fn reduced(mut defenses: Defenses<'_>, damage: f32) -> Option<f64> {
    if ![defenses.armor, defenses.toughness, f64::from(defenses.protection)].iter().all(|x| x.is_finite() && *x >= 0.0)
        || defenses.resistance.is_some_and(|n| !(0..=255).contains(&n))
    {
        return None;
    }
    let armored = damage_reduction::after_armor(&mut defenses, damage).ok()?;
    let result = damage_reduction::after_magic(&mut defenses, armored).ok()?;
    (result.is_finite() && result >= 0.0).then_some(f64::from(result))
}

pub(super) fn local_damage(game: &mut Game<'_>, blast: Blast, budget: &mut Budget) -> Option<Prediction> {
    local_damage_at(game, blast, [0.0; 3], budget)
}
pub(super) fn local_damage_at(
    game: &mut Game<'_>,
    blast: Blast,
    offset: [f64; 3],
    budget: &mut Budget,
) -> Option<Prediction> {
    if !offset.iter().all(|v| v.is_finite()) {
        return None;
    }
    let p = game.player.as_mut()?;
    let armor = p.attribute("minecraft:armor").ok()?;
    let toughness = p.attribute("minecraft:armor_toughness").ok()?;
    let resistance = p.status.resistance;
    let protection = p.status.protection(blast.source());
    let feet = [p.position.x + offset[0], p.position.y + offset[1], p.position.z + offset[2]];
    let bounds = p.bounds().move_by(Vec3::new(offset[0], offset[1], offset[2]));
    let (min, max) = (bounds.min_position(), bounds.max_position());
    let damage = raw(game, feet, [min.x, min.y, min.z], [max.x, max.y, max.z], blast, budget)?;
    let source = source(game, blast)?;
    let scaling = source.definition().scaling;
    let observed = observed_difficulty(game);
    let estimate =
        reduced(Defenses { source, armor, toughness, resistance, protection }, difficulty(damage, observed, scaling))?;
    Some(Prediction { estimate })
}

// Offensive target pipeline: difficulty -> native shield -> hurt window ->
// native armor/magic. Self and friend bounds continue to use the full blast.
#[derive(Clone, Copy)]
pub(super) struct TargetHurtRaw {
    victim: u32,
    blast: Blast,
    raw: f32,
}
impl TargetHurtRaw {
    pub(super) fn raw_before_armor(self) -> f32 {
        self.raw
    }
}

fn target_blocked(game: &Game<'_>, target: &Target, blast: Blast, scaled: f32) -> Option<f32> {
    use horizon_world::blocking_rules::{DamageReduction, TypeMatchWorld};
    let Some((stack, elapsed)) = super::sunset_prediction::blocking_hand(target.id, game.ticks)? else {
        return Some(0.0);
    };
    let Some(component) = game.blocks_attacks(&stack) else {
        return Some(0.0);
    };
    // Native protocol cannot decode a customized blocks_attacks patch. Never
    // manufacture custom component facts from an ordinary shield prototype.
    if stack.extra.as_ref().is_some_and(|e| !e.other.is_empty()) {
        return None;
    }
    if elapsed < (component.delay_seconds * 20.0).round().max(0.0) as u64 {
        return Some(0.0);
    }
    let damage_type = blast.source();
    let tags = &game.stations().enchantments.damage_tags;
    let matches = |spec: &str| match spec.strip_prefix('#') {
        Some(tag) => tags.get(tag).is_some_and(|set| set.contains(damage_type)),
        None => spec == damage_type,
    };
    if component.bypassed_by.as_deref().is_some_and(matches) {
        return Some(0.0);
    }
    let mob = game.mobs.iter().find(|m| m.id == target.id)?;
    let yaw = f64::from(mob.head_yaw).to_radians();
    let delta = [blast.center[0] - target.pos[0], blast.center[2] - target.pos[2]];
    let length = delta[0].hypot(delta[1]);
    let cosine = if length < 1e-4 { 0.0 } else { (-yaw.sin() * delta[0] + yaw.cos() * delta[1]) / length };
    let angle = cosine.clamp(-1.0, 1.0).acos();
    struct Known;
    impl TypeMatchWorld for Known {
        type Error = ();
        type Set = bool;
        fn source_in_set(&mut self, value: bool) -> Result<bool, ()> {
            Ok(value)
        }
    }
    let mut blocked = 0.0;
    for reduction in &component.reductions {
        let native = DamageReduction {
            horizontal_angle: reduction.horizontal_angle,
            types: reduction.types.as_ref().map(|set| set.iter().any(|spec| matches(spec))),
            base: reduction.base,
            factor: reduction.factor,
        };
        blocked += native.resolve(&mut Known, scaled, angle).ok()?;
    }
    (blocked.is_finite() && blocked >= 0.0).then_some(blocked.min(scaled))
}
pub(super) fn target_hurt_raw_at(
    game: &Game<'_>,
    target: &Target,
    blast: Blast,
    budget: &mut Budget,
) -> Option<TargetHurtRaw> {
    game.mobs.iter().find(|m| m.id == target.id && !m.removed && m.alive())?;
    let raw = raw(game, target.pos, target.lo, target.hi, blast, budget)?;
    let source = source(game, blast)?;
    let scaled =
        if target.player { difficulty(raw, observed_difficulty(game), source.definition().scaling) } else { raw };
    let blocked = if target.player { target_blocked(game, target, blast, scaled)? } else { 0.0 };
    let raw = scaled - blocked;
    (raw.is_finite() && raw >= 0.0).then_some(TargetHurtRaw { victim: target.id, blast, raw })
}
pub(super) fn reduce_target_hurt_raw(game: &Game<'_>, target: &Target, sample: TargetHurtRaw, raw: f32) -> Option<f64> {
    if sample.victim != target.id || !raw.is_finite() || raw < 0.0 || raw > sample.raw {
        return None;
    }
    let mob = game.mobs.iter().find(|m| m.id == target.id && !m.removed && m.alive())?;
    let (armor, toughness) = mob.worn_armor();
    let resistance = mob.extra.effects.iter().find(|e| e.0 == "resistance" && e.1 != 0).map(|e| e.2);
    let protection = horizon_client::mobs::gear::protection(mob, horizon_client::mobs::DamageKind::Explosion);
    reduced(
        Defenses {
            source: source(game, sample.blast)?,
            armor: f64::from(mob.kind.armor + armor),
            toughness: f64::from(mob.kind.armor_toughness + toughness),
            resistance,
            protection,
        },
        raw,
    )
}

// A caller that distinguishes open from covered must also distinguish unknown.
// Reuse the existing strict loaded-chunk collider query and shared ray budget.
pub(super) fn known_line(
    game: &Game<'_>,
    from: [f64; 3],
    to: [f64; 3],
    ignored: Option<[i32; 3]>,
    budget: &mut Budget,
) -> Option<bool> {
    if !budget.line() {
        return None;
    }
    clear(&mut rays(game, from[1], ignored), from, to)
}

// Ordinary observed local estimate for explicitly requested manual actions.
// Unknown equipment components cannot silently borrow prototype defenses.
pub(super) fn observed_local_damage(game: &mut Game<'_>, blast: Blast, budget: &mut Budget) -> Option<f64> {
    if !equipment_known(game) {
        return None;
    }
    local_damage(game, blast, budget).map(|p| p.estimate).filter(|damage| damage.is_finite() && *damage >= 0.0)
}

// Crystal Aura and Anchor Aura's shared limits: the work a tick may do, the reach checks, an explosion's raw damage.

pub(super) fn in_range(from: [f64; 3], to: [f64; 3], range: f64) -> bool {
    if !range.is_finite() || range < 0.0 || !from.iter().chain(to.iter()).all(|x| x.is_finite()) {
        return false;
    }
    let squared = (0..3).map(|i| (from[i] - to[i]).powi(2)).sum::<f64>();
    squared.is_finite() && squared <= range * range
}

// Same sample locations as the pinned engine's ServerExplosion exposure grid.
// Refuse giant/invalid boxes rather than allocating or casting unbounded rays.
pub(super) fn samples(min: [f64; 3], max: [f64; 3]) -> Option<Vec<[f64; 3]>> {
    if !(0..3).all(|i| {
        min[i].is_finite()
            && max[i].is_finite()
            && min[i].abs() <= 30_000_000.0
            && max[i].abs() <= 30_000_000.0
            && max[i] >= min[i]
            && max[i] - min[i] <= 16.0
    }) {
        return None;
    }
    let step: [f64; 3] = std::array::from_fn(|i| 1.0 / ((max[i] - min[i]) * 2.0 + 1.0));
    let offset =
        [(1.0 - (1.0 / step[0]).floor() * step[0]) / 2.0, 0.0, (1.0 - (1.0 / step[2]).floor() * step[2]) / 2.0];
    let mut result = Vec::with_capacity(64);
    let mut x = 0.0;
    while x <= 1.0 {
        let mut y = 0.0;
        while y <= 1.0 {
            let mut z = 0.0;
            while z <= 1.0 {
                if result.len() >= 256 {
                    return None;
                }
                result.push([
                    min[0] + (max[0] - min[0]) * x + offset[0],
                    min[1] + (max[1] - min[1]) * y,
                    min[2] + (max[2] - min[2]) * z + offset[2],
                ]);
                z += step[2];
            }
            y += step[1];
        }
        x += step[0];
    }
    Some(result)
}

pub(super) fn raw_damage(distance: f64, power: f32, exposure: f32) -> Option<f32> {
    if !distance.is_finite()
        || distance < 0.0
        || !power.is_finite()
        || power <= 0.0
        || power > 8.0
        || !exposure.is_finite()
        || !(0.0..=1.0).contains(&exposure)
    {
        return None;
    }
    let diameter = f64::from(power * 2.0);
    let normalized = distance / diameter;
    if normalized > 1.0 {
        return Some(0.0);
    }
    let impact = (1.0 - normalized) * f64::from(exposure);
    // The pinned engine converts to f32, without integer rounding.
    Some(((impact * impact + impact) / 2.0 * 7.0 * diameter + 1.0) as f32)
}

// A prediction reserves all exposure rays before any are cast. Both limits are
// absolute even if malformed dimensions/settings arrive from a server/config.
// Create once per aura tick and reuse for all candidates AND all friend checks.
#[derive(Clone, Debug)]
pub(super) struct Budget {
    limit: usize,
    pub predictions: usize,
    pub rays: usize,
    pub rejected: usize,
}

impl Budget {
    pub(super) fn new(max_predictions: usize) -> Self {
        Self { limit: max_predictions.min(64), predictions: 0, rays: 0, rejected: 0 }
    }

    pub(super) fn prediction(&mut self, rays: usize) -> bool {
        if self.predictions >= self.limit || rays > 256 || self.rays.saturating_add(rays) > 4096 {
            self.rejected = self.rejected.saturating_add(1);
            return false;
        }
        self.predictions += 1;
        self.rays += rays;
        true
    }

    pub(super) fn line(&mut self) -> bool {
        if self.rays >= 4096 {
            self.rejected = self.rejected.saturating_add(1);
            return false;
        }
        self.rays += 1;
        true
    }
}

// What Crystal Aura and Anchor Aura share each tick: the reach attributes, the players to hit and spare, the look.
use super::sunset_util::Target;
use super::{Dim, Game};
use super::{sunset_prediction as prediction, sunset_util as util};
use std::sync::{Arc, Mutex};
type Connection = Arc<Mutex<Option<Arc<horizon_protocol::connection::Counters>>>>;
struct Context {
    session: Connection,
    dim: Dim,
    id: i32,
    tick: u64,
    block: f64,
    entity: f64,
    focus: Option<u32>,
}
static CONTEXT: Mutex<Option<Context>> = Mutex::new(None);
fn same(game: &Game<'_>, c: &Context) -> bool {
    game.dim == c.dim
        && game.remote.as_ref().is_some_and(|r| r.entity_id == c.id && Arc::ptr_eq(&r.session.counters, &c.session))
}
pub(super) fn refresh(game: &mut Game<'_>) -> bool {
    let Some(remote) = game.remote.as_ref() else {
        return false;
    };
    let (session, id) = (remote.session.counters.clone(), remote.entity_id);
    let Some(player) = game.player.as_mut() else {
        return false;
    };
    let Some((block, entity)) = player
        .attribute("minecraft:block_interaction_range")
        .ok()
        .zip(player.attribute("minecraft:entity_interaction_range").ok())
    else {
        return false;
    };
    if ![block, entity].iter().all(|n| n.is_finite() && *n > 0.1 && *n <= 64.0) {
        return false;
    }
    let mut guard = CONTEXT.lock().unwrap_or_else(|e| e.into_inner());
    let focus = guard.as_ref().filter(|c| same(game, c)).and_then(|c| c.focus);
    *guard = Some(Context { session, dim: game.dim, id, tick: game.ticks, block, entity, focus });
    true
}
fn range(game: &Game<'_>, entity: bool) -> f64 {
    CONTEXT
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .as_ref()
        .filter(|c| same(game, c) && c.tick == game.ticks)
        .map_or(0.0, |c| if entity { c.entity } else { c.block })
}
// Exact current interaction attributes for manual cursor picking. Autonomous
// planners retain their own small placement/rotation margins below.
pub(super) fn interaction_ranges(game: &Game<'_>) -> Option<(f64, f64)> {
    let guard = CONTEXT.lock().unwrap_or_else(|e| e.into_inner());
    let c = guard.as_ref().filter(|c| same(game, c) && c.tick == game.ticks)?;
    Some((c.block, c.entity))
}
pub(super) fn block_range(game: &Game<'_>) -> f64 {
    (range(game, false) - 0.1).max(0.0)
}
pub(super) fn anchor_range(game: &Game<'_>) -> f64 {
    (range(game, false) - 0.01).max(0.0)
}
pub(super) fn entity_range(game: &Game<'_>) -> f64 {
    (range(game, true) - 0.1).max(0.0)
}
pub(super) fn target_score(distance: f64, focused: bool, weak: bool) -> f64 {
    distance - if focused { 2.0 } else { 0.0 } - if weak { 2.0 } else { 0.0 }
}
pub(super) fn players(game: &Game<'_>) -> Option<(Vec<Target>, Vec<Target>)> {
    if game.mobs.len() > 512 {
        return None;
    }
    let p = game.player.as_ref()?;
    let feet = [p.position.x, p.position.y, p.position.z];
    let own = game.remote.as_ref()?.entity_id as u32;
    let names = super::sunset::with(|s| s.friends.clone());
    let focus =
        CONTEXT.lock().unwrap_or_else(|e| e.into_inner()).as_ref().filter(|c| same(game, c)).and_then(|c| c.focus);
    let (mut targets, mut friends) = (Vec::new(), Vec::new());
    for mob in &game.mobs {
        if mob.kind.id != "minecraft:player" || mob.removed || !mob.alive() || mob.id == own {
            continue;
        }
        let t = util::mob_target(mob);
        if !t.pos.iter().chain(t.lo.iter()).chain(t.hi.iter()).all(|v| v.is_finite()) {
            return None;
        }
        let friend =
            game.remote_player_name(mob.id).is_some_and(|name| names.iter().any(|f| f.eq_ignore_ascii_case(name)));
        if friend {
            friends.push(t);
        } else if util::dist(feet, t.pos) < 10.0 && util::player_enemy(game, mob) {
            targets.push(t);
        }
    }
    let score = |t: &Target| {
        target_score(
            util::dist(feet, t.pos),
            focus == Some(t.id),
            prediction::effective_health(game, t).unwrap_or(f64::from(t.health)) <= 10.0,
        )
    };
    targets.sort_by(|a, b| score(a).total_cmp(&score(b)));
    targets.truncate(3);
    if let Some(c) = CONTEXT.lock().unwrap_or_else(|e| e.into_inner()).as_mut().filter(|c| same(game, c)) {
        c.focus = targets.first().map(|t| t.id);
    }
    Some((targets, friends))
}
pub(super) fn breakable(game: &Game<'_>, base: [i32; 3]) -> bool {
    game.eye_position().is_some_and(|eye| {
        super::sunset_explosive_choice::future_crystal_breakable(eye, base, entity_range(game) + 0.1)
    })
}
pub(super) fn endangered(damage: f64, health: f64, creative: bool) -> bool {
    !damage.is_finite()
        || !health.is_finite()
        || damage < 0.0
        || health <= 0.0
        || !creative && damage * 1.15 + 2.0 >= health
}
pub(super) fn friend_health(game: &Game<'_>, t: &Target) -> f64 {
    prediction::effective_health(game, t).unwrap_or(f64::from(t.health))
}
pub(super) fn fixed_look(game: &Game<'_>) -> bool {
    game.riding.is_some()
        || game.player.as_ref().is_some_and(|p| p.fall_flying || p.auto_spin_attack_ticks > 0 || p.swimming)
        || super::sunset_render::camera_takes_mouse()
}
pub(super) fn next_look(game: &Game<'_>, desired: (f32, f32), speed: f64) -> (f32, f32) {
    if fixed_look(game) {
        return (game.yaw, game.pitch);
    }
    let base = super::sunset_combat_wire::sent_look(game).unwrap_or((game.yaw, game.pitch));
    let quantum = horizon_client::mouse::degrees_per_count(game.look_options());
    let random = {
        use horizon_core::random::{LegacyRandom, RandomSource};
        static RANDOM: Mutex<Option<LegacyRandom>> = Mutex::new(None);
        let mut random = RANDOM.lock().unwrap_or_else(|e| e.into_inner());
        random.get_or_insert_with(|| LegacyRandom::new(game.ticks as i64)).next_double()
    };
    super::sunset_aura_policy::rotation_step([base.0, base.1], [desired.0, desired.1], quantum, speed, random)
        .map_or((game.yaw, game.pitch), |[yaw, pitch]| (yaw, pitch))
}
pub(super) fn same_camera(game: &Game<'_>) -> bool {
    super::sunset_combat_wire::sent_look(game).is_some_and(|(yaw, pitch)| {
        ((yaw - game.yaw + 180.0).rem_euclid(360.0) - 180.0).abs() <= 2.0 && (pitch - game.pitch).abs() <= 2.0
    })
}
pub(super) fn aim_eye(game: &Game<'_>) -> Option<[f64; 3]> {
    let eye = game.eye_position()?;
    if fixed_look(game) {
        return Some(eye);
    }
    let p = game.player.as_ref()?;
    // Standing on the ground the game still adds gravity to the velocity, but the eyes don't go down: aiming from
    // there flattened the look at a crystal spot near your feet until it fell short or ran past reach.
    let fall = if p.ground.on_ground { p.velocity.y.max(0.0) } else { p.velocity.y };
    let velocity = [p.velocity.x, fall, p.velocity.z];
    velocity.iter().all(|v| v.is_finite()).then(|| std::array::from_fn(|i| eye[i] + velocity[i]))
}
// The auras take the hotbar from whatever you hold (a pickaxe, food, blocks: walking up to someone, you rarely hold
// a sword) and give it back after, except a golden apple you keep ready to eat. While you use the item (right click,
// eating, mining) they wait.
pub(super) fn may_take_hand(game: &Game<'_>) -> bool {
    !game
        .inventory
        .get(game.selected)
        .and_then(|s| s.as_ref())
        .is_some_and(|s| matches!(util::short(&s.item), "golden_apple" | "enchanted_golden_apple"))
}
pub(super) fn use_conflicts(game: &Game<'_>) -> bool {
    if !game.right {
        return false;
    }
    fn name(s: Option<&horizon_client::items::ItemStack>) -> Option<&str> {
        s.map(|s| util::short(&s.item))
    }
    let main = game.inventory.get(game.selected).and_then(|s| s.as_ref());
    if matches!(name(main), Some("respawn_anchor" | "glowstone")) {
        return true;
    }
    // Right click held with a block, food or anything else of your own in hand: you are using it.
    if !matches!(name(main), Some("end_crystal" | "obsidian")) && !combat_item(game, main) {
        return true;
    }
    let off = game.offhand.as_ref();
    !matches!(name(off), Some("end_crystal" | "obsidian")) && !combat_item(game, off)
}
pub(super) fn combat_item(game: &Game<'_>, stack: Option<&horizon_client::items::ItemStack>) -> bool {
    stack.is_none_or(|s| {
        s.count == 0
            || matches!(util::short(&s.item), "mace" | "totem_of_undying")
            || ["minecraft:swords", "minecraft:axes"]
                .iter()
                .any(|tag| game.items().item_tags.get(*tag).is_some_and(|items| items.contains(&*s.item)))
    })
}
pub(super) fn friend_damage(
    game: &Game<'_>,
    target: &Target,
    blast: super::sunset_explosive_damage::Blast,
    budget: &mut super::sunset_explosive_policy::Budget,
) -> Option<f64> {
    use super::sunset_explosive_damage as damage;
    let sample = damage::target_hurt_raw_at(game, target, blast, budget)?;
    damage::reduce_target_hurt_raw(game, target, sample, sample.raw_before_armor())
}

// Modules (Client): a switch for every module, by category; the menu leaves out the ones switched off. Binds,
// commands, profiles and saved settings reach them all the same; only the ClickGUI, its search and the Options pages
// skip them. Modules itself always shows, so a switch can always be put back.

use super::sunset::{CATEGORIES, Category, Module};

pub(super) const NAME: &str = "Modules";

// The modules hidden until their switch is on (the extras of Extra Modules, Pearl Catch now shown).
pub(super) const HIDDEN: &[&str] = &[
    "Slippy",
    "Self Web",
    "Jesus",
    "Trident Boost",
    "Step",
    "Wind Jump",
    "Mine Through Mobs",
    "RF Click",
    "Fake Player",
];

// Its switches are every module in `modules`, by category in the menu's order.
pub(super) fn defaults(modules: &[Module]) -> Module {
    let mut m = Module::new(NAME, Category::Client, "Shows or hides each module in the menu.");
    for category in CATEGORIES {
        for name in modules.iter().filter(|m| m.category == category).map(|m| m.name) {
            m = m.bool(name, !HIDDEN.contains(&name));
        }
    }
    m
}

// The modules the menu leaves out now.
pub(super) fn hidden(modules: &[Module]) -> Vec<&'static str> {
    let Some(list) = modules.iter().find(|m| m.name == NAME) else {
        return HIDDEN.to_vec();
    };
    list.settings.iter().map(|s| s.name).filter(|name| *name != NAME && !list.b(name)).collect()
}

// Client: the things that are not cheats (Unlock All Recipes, in World, works in recipes.rs). Client Sort, like
// Client Sort: three small buttons down the right of each part of an inventory screen (sort_buttons.rs),
// Sort, Fill Stacks and Restock. Sort goes in creative order, by count with Shift, by name with Ctrl and by id with Alt; Horizon's
// sort key does the same, on the hotbar only while the pointer is on it. The clicks go out a few a tick, an operation
// at least two ticks after the one before. Shift fill shift-clicks the slot under the pointer
// while you hold Shift and the left button.

use super::sunset::{Category, Module};
use super::Game;
use horizon_client::items::ItemStack;
use horizon_client::menu::Input;
use std::collections::VecDeque;
use std::sync::Mutex;
use std::sync::atomic::{AtomicBool, Ordering};
use winit::keyboard::KeyCode;

// A key past any real one.
const LAST: usize = 1 << 40;
const CLICKS_PER_TICK: usize = 4;
const GAP_TICKS: u32 = 2;

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new("Unlock All Recipes", Category::World,
            "Shows every recipe as unlocked."),
        Module::new("Profiles", Category::Client, "Saved settings to load."),
        Module::new("Client Sort", Category::Client,
            "Sorts inventories in your order.")
            .bool("Shift fill", false)
            .num("Fill CPS", 15.0, 1.0, 20.0, 1.0),
    ]
}

// Client Sort is on (read by the buttons' hooks each frame).
static ON: AtomicBool = AtomicBool::new(false);

// Shift fill: the slot under the pointer this frame, the last slot it clicked, and when the
// next click may go.
struct Fill {
    hovered: Option<usize>,
    last: Option<usize>,
    next: Option<std::time::Instant>,
    roll: u64,
}

static FILL: Mutex<Fill> = Mutex::new(Fill { hovered: None, last: None, next: None, roll: 0x5EED });

fn fill<R>(f: impl FnOnce(&mut Fill) -> R) -> R {
    f(&mut FILL.lock().unwrap_or_else(|e| e.into_inner()))
}

// The inventory screen's draw: the slot under the pointer.
pub(super) fn note_hover(slot: Option<usize>) {
    fill(|f| f.hovered = slot);
}

// Shift fill, each tick with Shift and the left button held over an inventory screen and nothing carried: the slot
// under the pointer is shift-clicked, Fill CPS (one either side) a second; the slot just clicked again only one time
// in five.
fn shift_fill(game: &mut Game<'_>, m: &Module) {
    let held = (game.physical_buttons.contains(&winit::event::MouseButton::Left) || game.left)
        && [KeyCode::ShiftLeft, KeyCode::ShiftRight].iter().any(|k| game.physical_keys.contains(k) || game.keys.contains(k));
    let now = std::time::Instant::now();
    let Some(slot) = fill(|f| f.hovered).filter(|_| held && game.carried.is_none()) else {
        fill(|f| f.last = None);
        return;
    };
    let roll = fill(|f| {
        f.roll ^= f.roll << 13;
        f.roll ^= f.roll >> 7;
        f.roll ^= f.roll << 17;
        (f.roll >> 11) as f64 / (1u64 << 53) as f64
    });
    if fill(|f| f.next.is_some_and(|due| now < due) || (f.last == Some(slot) && roll < 0.8)) {
        return;
    }
    game.tweak_click(slot, 0, Input::QuickMove);
    let cps = (m.n("Fill CPS") - 1.0 + roll * 2.0).clamp(1.0, 20.0);
    fill(|f| {
        f.last = Some(slot);
        f.next = Some(now + std::time::Duration::from_secs_f64(1.0 / cps));
    });
}

pub(super) fn on() -> bool {
    ON.load(Ordering::Relaxed)
}

// The operations still to do, each its clicks (slot id, quick move or not), and the ticks to wait before the next.
struct Queue {
    ops: VecDeque<VecDeque<(usize, bool)>>,
    wait: u32,
}

static QUEUE: Mutex<Queue> = Mutex::new(Queue { ops: VecDeque::new(), wait: 0 });

pub(super) fn shutdown(game: &mut Game<'_>) {
    ON.store(false, Ordering::Relaxed);
    queue(|q| { q.ops.clear(); q.wait = 0; });
    fill(|f| { f.hovered = None; f.last = None; f.next = None; });
    super::recipe_book::sunset_recipes::sync(game, false);
}

fn queue<R>(f: impl FnOnce(&mut Queue) -> R) -> R {
    f(&mut QUEUE.lock().unwrap_or_else(|e| e.into_inner()))
}

// Horizon's sort of `slots` (its sort key; the buttons are Client Sort's own), done Client Sort's way. True when it
// took it.
pub(super) fn sort(game: &mut Game<'_>, slots: &[usize]) -> bool {
    if !on() || !game.native_on(super::sunset::ID) {
        return false;
    }
    let hotbar: Vec<usize> = (0..9).collect();
    let slots = if game.inventory_target().0.is_some_and(|s| s < 9) { &hotbar } else { slots };
    operate(game, 0, slots);
    true
}

// One of the buttons' operations on the part `slots`: 0 sort, 1 fill stacks, 2 restock. Queued after any still going.
pub(super) fn operate(game: &mut Game<'_>, op: usize, slots: &[usize]) {
    if game.carried.is_some() {
        return;
    }
    // Slots Loadouts locks take no part.
    let slots: Vec<usize> = slots.iter().copied().filter(|&s| !super::sunset_loadouts::locked(s)).collect();
    let slots = &slots[..];
    let clicks: VecDeque<(usize, bool)> = match op {
        0 => sort_clicks(game, slots).into_iter().map(|s| (s, false)).collect(),
        1 => fill_clicks(game, slots).into(),
        _ => restock_clicks(game, slots).into(),
    };
    queue(|q| q.ops.push_back(clicks));
}

// What faces this part: a container's slots face your inventory, your inventory faces the container (or, with none,
// the hotbar).
fn other_side(game: &Game<'_>, slots: &[usize]) -> Vec<usize> {
    if slots.first().is_some_and(|&s| s >= 300) {
        return (0..36).filter(|&s| !super::sunset_loadouts::locked(s)).collect();
    }
    let container: Vec<usize> = game.slots().into_iter().filter(|s| (300..500).contains(s)).collect();
    if container.is_empty() { (0..9).collect() } else { container }
}

// Left clicks that sort `slots`: creative order, Shift by count, Ctrl by name, Alt by id.
fn sort_clicks(game: &mut Game<'_>, slots: &[usize]) -> Vec<usize> {
    let alt = game.physical_keys.contains(&KeyCode::AltLeft) || game.physical_keys.contains(&KeyCode::AltRight);
    let (ctrl, shift) = (game.has_control_down(), game.has_shift_down());
    let views: Vec<Option<ItemStack>> = slots.iter().map(|&s| game.slot_view(s)).collect();
    let totals = |item: &str| views.iter().flatten().filter(|s| &*s.item == item).map(|s| s.count as usize).sum::<usize>();
    let registry = &game.res.items().registry_order;
    let rank = |s: &ItemStack| -> horizon_client::inv_sort::Rank {
        let name = s.custom_name().unwrap_or_else(|| game.pack.names.display_item(&s.item));
        let creative = game.creative_screen.order_of(s).unwrap_or(LAST);
        if alt {
            (registry.iter().position(|r| *r == s.item).unwrap_or(LAST), name)
        } else if ctrl {
            (0, name.to_lowercase())
        } else if shift {
            (LAST - totals(&s.item).min(LAST), format!("{creative:012}"))
        } else {
            (creative, name)
        }
    };
    let max = |s: &ItemStack| game.max_stack(s);
    horizon_client::inv_sort::plan(&views, &rank, &max).into_iter().map(|i| slots[i]).collect()
}

// Fill Stacks: each stack here short of full takes the same item from the other side (pick it up, click the stack
// here, put back what is left), as the counts will be after each move.
fn fill_clicks(game: &mut Game<'_>, slots: &[usize]) -> Vec<(usize, bool)> {
    let side = other_side(game, slots);
    let mut here: Vec<(usize, Option<ItemStack>)> = slots.iter().map(|&s| (s, game.slot_view(s))).collect();
    let mut there: Vec<(usize, Option<ItemStack>)> = side.iter().map(|&s| (s, game.slot_view(s))).collect();
    let mut clicks = Vec::new();
    for (to, stack) in &mut here {
        let Some(stack) = stack else {
            continue;
        };
        let max = game.max_stack(stack);
        for (from, source) in &mut there {
            if stack.count >= max {
                break;
            }
            let Some(src) = source.as_mut().filter(|v| v.same_item_same_components(stack)) else {
                continue;
            };
            let moved = src.count.min(max - stack.count);
            stack.count += moved;
            src.count -= moved;
            clicks.extend([(*from, false), (*to, false)]);
            if src.count > 0 {
                clicks.push((*from, false));
            } else {
                *source = None;
            }
        }
    }
    clicks
}

// Restock: each stack here whose item the other side already has is quick-moved across.
fn restock_clicks(game: &mut Game<'_>, slots: &[usize]) -> Vec<(usize, bool)> {
    let side = other_side(game, slots);
    let there: Vec<ItemStack> = side.iter().filter_map(|&s| game.slot_view(s)).collect();
    slots
        .iter()
        .filter(|&&s| game.slot_view(s).is_some_and(|v| there.iter().any(|t| t.same_item_same_components(&v))))
        .map(|&s| (s, true))
        .collect()
}

// Each tick: Horizon's sort (its key) on while Client Sort is, and the next clicks of an operation; none once the
// screen they were for has closed.
pub(super) fn tick(game: &mut Game<'_>, mods: &[Module]) {
    super::recipe_book::sunset_recipes::sync(game, mods.iter().any(|m| m.name == "Unlock All Recipes" && m.on));
    let on = mods.iter().any(|m| m.name == "Client Sort" && m.on);
    ON.store(on, Ordering::Relaxed);
    if on {
        game.settings.extras.sort = true;
    }
    if game.screen != super::Screen::Inventory {
        queue(|q| q.ops.clear());
        fill(|f| f.hovered = None);
        return;
    }
    if let Some(m) = mods.iter().find(|m| m.name == "Client Sort" && m.on && m.b("Shift fill")) {
        shift_fill(game, m);
    }
    let now: Vec<(usize, bool)> = queue(|q| {
        if q.wait > 0 {
            q.wait -= 1;
            return Vec::new();
        }
        let Some(op) = q.ops.front_mut() else {
            return Vec::new();
        };
        let now = op.drain(..CLICKS_PER_TICK.min(op.len())).collect();
        if op.is_empty() {
            q.ops.pop_front();
            q.wait = GAP_TICKS;
        }
        now
    });
    for (slot, quick) in now {
        game.tweak_click(slot, 0, if quick { Input::QuickMove } else { Input::Pickup });
    }
}

// The facts Face Place needs about a target: health, the blocks round its feet, its armour's wear.
use super::{
    sunset_durability_patch::{self as durability_patch, Prototype},
    sunset_faceplace_policy::ArmorCondition,
};
use horizon_client::{blocks::BlockFacts, items::ItemStack, world::World};
use horizon_core::{geometry::Vec3, position::BlockPos};
pub fn horizontal_resistance(world: &World, facts: &BlockFacts, feet: Vec3) -> [Option<f32>; 4] {
    if !feet.is_finite() || feet.components().iter().any(|v| v.abs() > 30_000_000.0) {
        return [None; 4];
    }
    let pos = BlockPos::containing(feet);
    [[1, 0], [-1, 0], [0, 1], [0, -1]].map(|[x, z]| {
        let p = pos.offset(x, 0, z);
        if !world.loaded(p.x, p.z) {
            return None;
        }
        let resistance = facts.get(world.block(p.x, p.y, p.z)).explosion_resistance;
        resistance.is_finite().then_some(resistance)
    })
}
pub fn armor(stack: &ItemStack, prototype: Prototype) -> Option<ArmorCondition> {
    if stack.count == 0 {
        return None;
    }
    let patch = stack.wire_patch();
    // A changed locally decoded stack can lose its exact wire patch. Saved
    // unmodelled components must not silently fall back to ordinary prototypes.
    if patch.is_none() && stack.extra.as_ref().is_some_and(|e| !e.other.is_empty()) {
        return None;
    }
    durability_patch::resolve(prototype, stack.damage, patch.as_deref())
}

// Face Place: a lower damage floor when the target is low on health, in a hole, or its armour is nearly broken.
#[derive(Clone, Copy, Debug, Default)]
pub struct ArmorCondition {
    /// Already resolved native components: unbreakable is false here.
    pub damageable: bool,
    pub maximum: u32,
    pub lost: u32,
}
impl ArmorCondition {
    pub fn low(self) -> bool {
        self.damageable
            && self.maximum > 0
            && u64::from(self.maximum.saturating_sub(self.lost)) * 10 <= u64::from(self.maximum)
    }
}
#[derive(Clone, Copy, Debug, Default)]
pub struct FaceFacts {
    /// Actual health plus absorption; None means the observer cannot establish it.
    pub effective_health: Option<f64>,
    /// Four horizontal neighbors at the target's CURRENT feet cell.
    pub neighbor_resistance: [Option<f32>; 4],
    pub armor: [Option<ArmorCondition>; 4],
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Reason {
    Normal,
    Forced,
    LowHealth,
    Hole,
    LowArmor,
}
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Threshold {
    pub minimum: f64,
    pub reason: Reason,
}
fn health(facts: &FaceFacts) -> Option<f64> {
    facts.effective_health.filter(|v| v.is_finite() && *v > 0.0)
}
pub fn crystal(configured: f64, enabled: bool, forced: bool, breaking: bool, facts: &FaceFacts) -> Option<Threshold> {
    if !configured.is_finite() || configured < 0.0 {
        return None;
    }
    let reason = if forced {
        Reason::Forced
    } else if !enabled {
        Reason::Normal
    } else if health(facts).is_some_and(|hp| hp <= 10.0) {
        Reason::LowHealth
    } else if facts.neighbor_resistance.iter().all(|r| r.is_some_and(|v| v.is_finite() && v >= 600.0)) {
        Reason::Hole
    } else if facts.armor.iter().flatten().any(|a| a.low()) {
        Reason::LowArmor
    } else {
        Reason::Normal
    };
    let minimum = if reason == Reason::Normal { configured } else { configured.min(2.0) };
    Some(Threshold { minimum: minimum * if breaking { 0.6 } else { 1.0 }, reason })
}
pub fn anchor(configured: f64, effective_health: Option<f64>) -> Option<f64> {
    if !configured.is_finite() || configured < 0.0 {
        return None;
    }
    Some(effective_health.filter(|v| v.is_finite() && *v > 0.0).map_or(configured, |hp| configured.min(hp)))
}
/// Call only AFTER raw hurt-window adjustment and native defense reduction.
/// Unknown absorption never establishes estimated lethality.
pub fn sufficient(incremental_estimate: f64, threshold: f64, effective_health: Option<f64>) -> bool {
    incremental_estimate.is_finite()
        && incremental_estimate >= 0.0
        && threshold.is_finite()
        && threshold >= 0.0
        && (incremental_estimate >= threshold
            || effective_health.is_some_and(|hp| hp.is_finite() && hp > 0.0 && incremental_estimate >= hp))
}

// Flight's experimental strategies (NCP Hover, NCP Burst, NCP Bounce, Old NCP), each with its own state and
// lifecycle: Idle, Preparing (waiting for its start conditions), Active, Recovery (after a setback, real knockback or a
// burst's end: no override of its own until it settles). Abilities and Velocity stay in runtime_movement.rs; these never take
// the false ground claim or the Packet anti kick those use (runtime_movement.rs gates both on `experimental`).
//
// Written from how the old movement strategies behave (Old NCP after how a 1.8 client's hover moves), not copied from
// any client's code, and for testing against a specific NoCheatPlus build: no mode here is known to pass anything.
// - Hover: vertical speed held at zero, horizontal movement left as the game makes it, and the height sent raised by
//   1e-5 plus, every other tick, a random 1e-10 to 1e-5 (the offset is never negative).
// - Burst: on the ground with room above, a jump with a large horizontal impulse (Burst speed, blocks a tick) that
//   decays by Burst friction each tick; the fall is softened while it lasts; it ends falling, slowed, or after
//   20 ticks, then waits to land (Burst repeat for the next one).
// - Bounce: a cycle of Bounce period ticks: the movement is saved, held at a stop, then given back scaled by Bounce
//   boost (upward at most a jump's 0.42).
// - Old NCP: the old NoCheatPlus hover as 1.8 clients flew it: no vertical speed at all (the height stays where it was),
//   each move packet's height raised by 1e-5 and then, on alternate ticks, raised or lowered by a random 1e-10 to 1e-5,
//   a move packet every tick, and the move across the 1.8 strafe at the allowed distance (legacy_speed: walking's
//   0.221, a sprint's 1.3 of it whenever the keys could sprint, Speed's 20% a level) along your keys, nothing kept of the
//   last move but a random 1/2000 at most. There is no up or down.

use super::Game;
use super::sunset::Module;
use std::sync::Mutex;
use std::sync::atomic::{AtomicBool, Ordering};
use winit::keyboard::KeyCode;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Strategy {
    Hover,
    Burst,
    Bounce,
    OldNcp,
}

impl Strategy {
    // The experimental strategy a Flight Mode names, if it names one.
    pub(super) fn of(mode: &str) -> Option<Self> {
        match mode {
            "NCP Hover" => Some(Self::Hover),
            "NCP Burst" => Some(Self::Burst),
            "NCP Bounce" => Some(Self::Bounce),
            "Old NCP" => Some(Self::OldNcp),
            _ => None,
        }
    }
}

pub(super) fn experimental(mode: &str) -> bool {
    Strategy::of(mode).is_some()
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(super) enum Phase {
    #[default]
    Idle,
    Preparing,
    Active,
    Recovery,
}

#[derive(Debug, Default)]
struct State {
    strategy: Option<Strategy>,
    phase: Phase,
    ticks: u32,
    // Burst's speed now, blocks a tick.
    speed: f64,
    // Whether the last tick's horizontal movement was this strategy's (taken back when it stops).
    owns_momentum: bool,
    // Bounce's saved movement.
    saved: Option<[f64; 3]>,
    recover: u32,
    // The height added to this tick's move packet (Hover, Old NCP).
    offset: Option<f64>,
    // Old NCP's last move across.
    last_across: [f64; 2],
    rng: u64,
    corrections: u32,
    knocks: u32,
    bursts: u32,
}

static STATE: Mutex<Option<State>> = Mutex::new(None);

fn state<R>(f: impl FnOnce(&mut State) -> R) -> R {
    f(STATE.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(|| State { rng: 0x9e37_79b9_7f4a_7c15, ..State::default() }))
}

fn unit(rng: &mut u64) -> f64 {
    *rng ^= *rng << 13;
    *rng ^= *rng >> 7;
    *rng ^= *rng << 17;
    (*rng >> 11) as f64 / (1u64 << 53) as f64
}

// ---- the strategies' rules, apart from the game (unit tested)

// Hover's height offset for a tick: 1e-5, and every other tick a random 1e-10 to 1e-5 more.
pub(super) fn hover_offset(tick: u32, rng: &mut u64) -> f64 {
    let extra = if tick % 2 == 0 { 1e-10 + unit(rng) * (1e-5 - 1e-10) } else { 0.0 };
    1e-5 + extra
}

// Old NCP's height offset for a tick: 1e-5, then a random 1e-10 to 1e-5 added on even ticks and taken away on odd ones.
pub(super) fn old_ncp_offset(tick: u64, rng: &mut u64) -> f64 {
    let r = 1e-10 + unit(rng) * (1e-5 - 1e-10);
    1e-5 + if tick % 2 == 0 { r } else { -r }
}

// Old NCP's move across for this tick, before the tick moves you (None while it recovers from a setback or knockback).
pub(super) fn old_ncp_across(game: &mut Game<'_>) -> Option<[f64; 2]> {
    use super::sunset_legacy_speed::{allowed_distance, strafe_move};
    if state(|s| s.recover > 0 || s.phase == Phase::Recovery) {
        return None;
    }
    let (input, allowance) = super::sunset::legacy_strafe_frame(game)?;
    let ground = game.player.as_ref()?.ground.on_ground;
    let friction = if ground { 0.6 * 0.91 } else { 0.91 };
    Some(state(|s| {
        let keep = unit(&mut s.rng) / 2000.0;
        let residual = [s.last_across[0] * friction, s.last_across[1] * friction];
        let across = strafe_move(allowed_distance(allowance, input), input, residual, keep);
        s.last_across = across;
        across
    }))
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub(super) struct BurstCfg {
    pub(super) speed: f64,
    pub(super) friction: f64,
    pub(super) repeat: bool,
}

// What a Burst tick does to the movement: jump, set the horizontal speed, set the vertical speed.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub(super) struct BurstOut {
    pub(super) jump: bool,
    pub(super) horizontal: Option<f64>,
    pub(super) vertical: Option<f64>,
}

// One Burst tick from its phase, ticks and speed, and the player's: on the ground, room above, vertical speed.
pub(super) fn burst_tick(phase: Phase, ticks: u32, speed: f64, bursts: u32, ground: bool, room: bool, vy: f64, cfg: BurstCfg)
    -> (Phase, f64, BurstOut) {
    match phase {
        Phase::Idle | Phase::Preparing => {
            if bursts > 0 && !cfg.repeat {
                return (Phase::Idle, 0.0, BurstOut::default());
            }
            if ground && room {
                (Phase::Active, cfg.speed, BurstOut { jump: true, horizontal: Some(cfg.speed), vertical: Some(0.42) })
            } else {
                (Phase::Preparing, 0.0, BurstOut::default())
            }
        }
        Phase::Active => {
            let speed = speed * cfg.friction.clamp(0.5, 0.999);
            // Ends falling fast, slowed to about a sprint, or after 20 ticks; landing ends it too.
            if (ground && ticks > 1) || vy < -0.3 || speed < 0.3 || ticks >= 20 {
                return (Phase::Recovery, 0.0, BurstOut::default());
            }
            // The fall softened while it lasts: no more than a slow drop.
            let vertical = (vy < 0.0).then(|| vy.max(-0.05));
            (Phase::Active, speed, BurstOut { jump: false, horizontal: Some(speed), vertical })
        }
        Phase::Recovery => (if ground { Phase::Idle } else { Phase::Recovery }, 0.0, BurstOut::default()),
    }
}

// Bounce: the movement for tick `t` of its cycle, from the movement now and what was saved.
pub(super) fn bounce_tick(t: u32, period: u32, boost: f64, now: [f64; 3], saved: Option<[f64; 3]>) -> ([f64; 3], Option<[f64; 3]>) {
    let period = period.max(2);
    match t % period {
        0 => (now, Some(now)),
        x if x + 1 < period => ([0.0; 3], saved),
        _ => {
            let s = saved.unwrap_or(now);
            ([s[0] * boost, (s[1] * boost).clamp(-0.42, 0.42), s[2] * boost], None)
        }
    }
}

// ---- in the game

// The way you move, as a unit vector on the ground (your keys along your yaw, or straight ahead with none).
fn heading(game: &Game<'_>) -> [f64; 2] {
    let held = |k: KeyCode| f64::from(u8::from(game.keys.contains(&k)));
    let (forward, left) = (held(KeyCode::KeyW) - held(KeyCode::KeyS), held(KeyCode::KeyA) - held(KeyCode::KeyD));
    let (forward, left) = if forward == 0.0 && left == 0.0 { (1.0, 0.0) } else { (forward, left) };
    let yaw = f64::from(game.yaw).to_radians();
    let (fx, fz) = (-yaw.sin(), yaw.cos());
    let (lx, lz) = (fz, -fx);
    let (x, z) = (fx * forward + lx * left, fz * forward + lz * left);
    let len = x.hypot(z).max(1e-9);
    [x / len, z / len]
}

// One tick of the experimental strategy Flight's Mode names (runtime_movement.rs flight_post calls it in place of Abilities'
// and Velocity's work).
pub(super) fn tick(game: &mut Game<'_>, m: &Module) {
    let Some(strategy) = Strategy::of(m.p("Mode")) else {
        return;
    };
    // A new strategy starts from nothing.
    if state(|s| s.strategy != Some(strategy)) {
        stop(game);
        state(|s| s.strategy = Some(strategy));
    }
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let ground = p.ground.on_ground;
    let (velocity, position) = ([p.velocity.x, p.velocity.y, p.velocity.z], [p.position.x, p.position.y, p.position.z]);
    // Recovery after a setback or real knockback: hands off until it has passed.
    let recovering = state(|s| {
        s.offset = None;
        if s.recover > 0 {
            s.recover -= 1;
            s.phase = Phase::Recovery;
            return true;
        }
        if s.phase == Phase::Recovery && strategy != Strategy::Burst {
            s.phase = Phase::Idle;
        }
        false
    });
    if recovering {
        state(|s| s.owns_momentum = false);
        return;
    }
    match strategy {
        Strategy::Hover => {
            let offset = state(|s| {
                s.phase = Phase::Active;
                s.ticks = s.ticks.wrapping_add(1);
                let t = s.ticks;
                hover_offset(t, &mut s.rng)
            });
            state(|s| s.offset = (!ground).then_some(offset));
            if let Some(p) = game.player.as_mut() {
                p.velocity.y = 0.0;
            }
        }
        Strategy::OldNcp => {
            let tick = game.ticks;
            state(|s| {
                s.phase = Phase::Active;
                s.ticks = s.ticks.wrapping_add(1);
                s.offset = Some(old_ncp_offset(tick, &mut s.rng));
            });
            if let Some(p) = game.player.as_mut() {
                p.velocity.y = 0.0;
            }
        }
        Strategy::Burst => {
            let feet = [position[0].floor() as i32, position[1].floor() as i32, position[2].floor() as i32];
            let room = (2..4).all(|dy| super::sunset_util::is_air(game, [feet[0], feet[1] + dy, feet[2]]));
            let cfg = BurstCfg { speed: m.n("Burst speed"), friction: m.n("Burst friction"), repeat: m.b("Burst repeat") };
            let (phase, ticks, speed, bursts) = state(|s| (s.phase, s.ticks, s.speed, s.bursts));
            // Damage fly: the hit itself starts a burst, in the air too.
            let ground = ground || damage(|d| std::mem::take(&mut d.fresh));
            let (next, speed, out) = burst_tick(phase, ticks, speed, bursts, ground, room, velocity[1], cfg);
            let dir = heading(game);
            state(|s| {
                if next == Phase::Active && phase != Phase::Active {
                    s.bursts += 1;
                    s.ticks = 0;
                } else {
                    s.ticks = s.ticks.saturating_add(1);
                }
                s.phase = next;
                s.speed = speed;
                s.owns_momentum = out.horizontal.is_some();
            });
            if let Some(p) = game.player.as_mut() {
                if let Some(h) = out.horizontal {
                    (p.velocity.x, p.velocity.z) = (dir[0] * h, dir[1] * h);
                }
                if let Some(v) = out.vertical {
                    p.velocity.y = v;
                }
                if out.jump {
                    p.ground.on_ground = false;
                }
            }
        }
        Strategy::Bounce => {
            let period = m.n("Bounce period (ticks)") as u32;
            let boost = m.n("Bounce boost");
            let (t, saved) = state(|s| {
                s.phase = Phase::Active;
                let t = s.ticks;
                s.ticks = s.ticks.wrapping_add(1);
                (t, s.saved)
            });
            let (out, saved) = bounce_tick(t, period, boost, velocity, saved);
            state(|s| {
                s.saved = saved;
                s.owns_momentum = true;
            });
            if let Some(p) = game.player.as_mut() {
                (p.velocity.x, p.velocity.y, p.velocity.z) = (out[0], out[1], out[2]);
            }
        }
    }
}

// The height Hover adds to this tick's move packet.
pub(super) fn offset() -> Option<f64> {
    state(|s| s.offset)
}

// The server set you back: hands off for `pause` ticks, nothing saved kept; a self damage under way is over.
pub(super) fn correction(pause: u32) {
    damage(|d| d.broken = true);
    state(|s| {
        if s.strategy.is_some() {
            s.recover = pause.max(1);
            s.corrections += 1;
            s.saved = None;
            s.speed = 0.0;
            s.offset = None;
            s.phase = Phase::Recovery;
        }
    });
}

// Real knockback came: it is the server's movement, not to be held or replayed. Hands off for 10 ticks; with Damage fly
// on it is what the flight starts from instead (`damage_tick`).
pub(super) fn knocked(velocity: [f64; 3]) {
    if damage(|d| {
        d.knock = Some(velocity);
        d.trigger != Trigger::Off
    }) {
        return;
    }
    state(|s| {
        // Old NCP's strafe and held height take over the knockback as a 1.8 client's do: no recovery for it.
        if s.strategy.is_some_and(|k| k != Strategy::OldNcp) {
            s.recover = s.recover.max(10);
            s.knocks += 1;
            s.saved = None;
            s.phase = Phase::Recovery;
        }
    });
}

// Flight off, another mode, Panic or a new world: the horizontal speed a strategy gave is taken back (gravity and your
// own keys are left as they are), and nothing is kept.
pub(super) fn stop(game: &mut Game<'_>) {
    let owned = state(|s| {
        let owned = s.owns_momentum;
        let (corrections, knocks, rng) = (s.corrections, s.knocks, s.rng);
        *s = State { corrections, knocks, rng, ..State::default() };
        owned
    });
    if owned && let Some(p) = game.player.as_mut() {
        p.velocity.x = 0.0;
        p.velocity.z = 0.0;
    }
}

// A new world or life: the player is new, so only the state goes (Damage fly waits again, its health unknown).
pub(super) fn reset() {
    damage(|d| {
        (d.phase, d.hurt, d.owed, d.knock, d.carry, d.broken, d.health) = (Wait::Armed, false, false, None, None, false, None);
    });
    state(|s| {
        let (corrections, knocks, rng) = (s.corrections, s.knocks, s.rng);
        *s = State { corrections, knocks, rng, ..State::default() };
    });
}

// ---- Damage fly
//
// Flight's Damage fly, over every Mode: Flight waits (no flight, no false ground, no anti kick: you move as the game
// moves you, and Speed works) until you are hurt, then flies in its Mode for Damage time ticks; another hurt meanwhile
// starts the time again. Then it waits again, or (After damage Disable) turns off.
// - The hit's knockback (SetEntityMotion for you, with the hurt or just after) is the speed anticheats that allow a
//   hit's velocity for a while allow, so the flight starts from it: its speed across the ground times Damage boost,
//   along the knockback (Keep) or your keys (Redirect), and its rise as it came. Velocity mode, which sets the
//   movement each tick, carries it on at the air's 0.91 a tick; the other modes leave it to the game's friction. An
//   anticheat that predicts movement (Grim, Horizon's) expects the knockback exactly: only Keep with a boost of 1
//   matches it, and the flight after it is checked as any flight is.
// - Self damage, standing on the ground: a fall the server counts by vanilla's rules, told in position packets while
//   you stay where you are. The server deals it on the landing; a hurt then opens the window like any other.
//   - Burst (default): in one tick, pairs of moves BURST_STEP up and back down, off the ground, then the ground. A
//     Bukkit server fires PlayerMoveEvent, which its anticheat checks movement on (NoCheatPlus), only for a move of
//     more than 1/16 block from where it last fired, so none of these reaches it; the server's own movement code
//     still adds each drop to the fall. First a fall just past the safe distance (a 1.8 server's `ceil(fall - 3)`
//     costs half a heart), and when that brings no hurt one past it by 1.05 (a modern server's
//     `floor(fall + 1e-6 - 3)`); the height that worked is kept. Over a hundred packets in a tick: a packet-rate check
//     may count them, and Horizon's own server kicks for a second position packet in a tick (use Spread there).
//   - Spread: the game's own move packets, one a tick, while you are held still: up at most a jump's 0.42 a tick to
//     the safe distance plus 1.05, down as gravity pulls, then the ground. Plainly a climb to a checked move.
//   An anticheat that predicts movement (Grim, Horizon's) sees either. A failed try (a setback, you moved, no hurt)
//   waits two seconds before the next; three in a row and it only waits for other damage until Flight is turned on
//   again.

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(super) enum Trigger {
    #[default]
    Off,
    Wait,
    SelfDamage,
}

impl Trigger {
    pub(super) fn of(setting: &str) -> Self {
        match setting {
            "Wait" => Self::Wait,
            "Self damage" => Self::SelfDamage,
            _ => Self::Off,
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(super) enum Wait {
    // Waiting for a hurt.
    #[default]
    Armed,
    // Self damage: the tick of its fall this tick's move tells (the last one past its heights: the landing).
    Falling(usize),
    // Self damage landed: ticks since, waiting for the server's hurt.
    Landed(u32),
    // Flying: ticks left, this one included.
    Open(u32),
    // Over with After damage Disable: Flight goes off.
    Spent,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) struct DamageCfg {
    pub(super) trigger: Trigger,
    pub(super) window: u32,
    pub(super) again: bool,
}

// The ticks a self damage's landing waits for the server's hurt before it counts as failed, and a failed try waits.
const LANDED_WAIT: u32 = 20;
const RETRY_WAIT: u64 = 40;
// Burst's step: under the 1/16 block (squared 1/256) a Bukkit server's PlayerMoveEvent needs, with room for where it
// last fired being a little off to the side.
pub(super) const BURST_STEP: f64 = 0.049;
// Self damage tries that bring no hurt before it stops trying.
const MOST_FAILS: u32 = 3;
// How far past the safe fall distance a fall goes for a point of damage under a modern server's rule.
const FALL_EXTRA: f64 = 1.05;

// One tick of Damage fly's wait (not Off): the phase now, from the last one and this tick's news: a hurt (never while
// a self damage still falls; that one is kept for its landing), whether a self damage may start, whether the one
// falling broke (a setback, you moved). `fall`: the self damage's heights.
pub(super) fn wait_tick(phase: Wait, cfg: DamageCfg, hurt: bool, can_start: bool, broken: bool, fall: usize) -> Wait {
    if hurt && phase != Wait::Spent {
        return Wait::Open(cfg.window.max(1));
    }
    match phase {
        Wait::Armed if cfg.trigger == Trigger::SelfDamage && can_start => Wait::Falling(0),
        Wait::Armed => Wait::Armed,
        Wait::Falling(_) if broken => Wait::Armed,
        Wait::Falling(t) if t < fall => Wait::Falling(t + 1),
        Wait::Falling(_) => Wait::Landed(0),
        Wait::Landed(w) if w < LANDED_WAIT => Wait::Landed(w + 1),
        Wait::Landed(_) => Wait::Armed,
        Wait::Open(n) if n > 1 => Wait::Open(n - 1),
        Wait::Open(_) if cfg.again => Wait::Armed,
        Wait::Open(_) | Wait::Spent => Wait::Spent,
    }
}

// Self damage's fall: the heights above where you stand its moves tell, one a tick: up at most a jump's 0.42 a tick to
// `top`, then down as gravity pulls (0.08 a tick, 0.98 drag) to 0. The server counts the way down: `top`.
pub(super) fn fall_heights(top: f64) -> Vec<f64> {
    let up = (top / 0.42).ceil().max(1.0) as usize;
    let mut out: Vec<f64> = (1..=up).map(|k| top * k as f64 / up as f64).collect();
    let (mut y, mut v) = (top, 0.0);
    while y > 0.0 {
        v = (v - 0.08) * 0.98;
        y = (y + v).max(0.0);
        out.push(y);
    }
    out
}

// Burst's moves above where you stand, in order: (height, on the ground). The drops add up to at least `top`; none is
// more than `step`.
pub(super) fn burst_moves(top: f64, step: f64) -> Vec<(f64, bool)> {
    let pairs = (top / step).ceil().max(1.0) as usize;
    let mut out = Vec::with_capacity(pairs * 2 + 1);
    for _ in 0..pairs {
        out.push((step, false));
        out.push((0.0, false));
    }
    out.push((0.0, true));
    out
}

// The knockback Damage fly flies on with: its speed across the ground times `boost`, along it or along `toward`
// (Redirect), and its rise as it came.
pub(super) fn kick(knock: [f64; 3], boost: f64, toward: Option<[f64; 2]>) -> [f64; 3] {
    let across = knock[0].hypot(knock[2]);
    let speed = across * boost.max(0.0);
    let [x, z] = match toward {
        Some(d) => d,
        None if across > 0.0 => [knock[0] / across, knock[2] / across],
        None => [0.0, 0.0],
    };
    [x * speed, knock[1], z * speed]
}

#[derive(Debug, Default)]
struct Damage {
    trigger: Trigger,
    phase: Wait,
    // A hurt since the last tick, and one that came while a self damage still fell (for its landing).
    hurt: bool,
    owed: bool,
    // The server's last knockback, kept until the window uses it (or the tick ends without one open).
    knock: Option<[f64; 3]>,
    // Velocity mode's knockback speed across the ground, carried on.
    carry: Option<[f64; 2]>,
    // The window opened this tick (NCP Burst starts from the hit).
    fresh: bool,
    heights: Vec<f64>,
    base: [f64; 3],
    broken: bool,
    fails: u32,
    // When the next try may start; why the tries in a row failed; the fall the try under way tells, and the one a
    // Burst got a hurt from.
    retry_at: u64,
    reasons: Vec<&'static str>,
    try_top: f64,
    burst_top: Option<f64>,
    health: Option<f32>,
    hurts: u32,
    windows: u32,
    self_damages: u32,
}

static DAMAGE: Mutex<Option<Damage>> = Mutex::new(None);
// Whether Flight may fly this tick: Damage fly Off, or its window open. The move packet's false ground and anti kick
// read it.
static OPEN: AtomicBool = AtomicBool::new(true);
// A Spread self damage holds you still: Speed and the like wait.
static SELF_FALLING: AtomicBool = AtomicBool::new(false);

fn damage<R>(f: impl FnOnce(&mut Damage) -> R) -> R {
    f(DAMAGE.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Damage::default))
}

pub(super) fn damage_open() -> bool {
    OPEN.load(Ordering::Relaxed)
}

// A Spread self damage is under way: movement modules leave you be.
pub(super) fn self_falling() -> bool {
    SELF_FALLING.load(Ordering::Relaxed)
}

// You were hurt (a DamageEvent for you).
pub(super) fn hurt() {
    damage(|d| d.hurt = true);
}

// Your health as the server set it: lower than before is a hurt too (a server that sends no DamageEvent).
pub(super) fn health(now: f32) {
    damage(|d| {
        if d.health.is_some_and(|h| now < h - 1e-3) {
            d.hurt = true;
        }
        d.health = Some(now);
    });
}

// Velocity mode's carried knockback.
pub(super) fn carry() -> Option<[f64; 2]> {
    damage(|d| d.carry)
}

// This tick's move as a self damage tells it: the height sent and whether it lands.
pub(super) fn fall_move() -> Option<(f64, bool)> {
    damage(|d| match d.phase {
        Wait::Falling(t) if t < d.heights.len() => Some((d.base[1] + d.heights[t], false)),
        Wait::Falling(_) => Some((d.base[1], true)),
        _ => None,
    })
}

// Flight off: the next turning on starts from waiting, with self damage's tries back.
pub(super) fn damage_reset() {
    damage(|d| {
        let (hurts, windows, self_damages, health, burst_top) = (d.hurts, d.windows, d.self_damages, d.health, d.burst_top);
        *d = Damage { hurts, windows, self_damages, health, burst_top, ..Damage::default() };
    });
    OPEN.store(true, Ordering::Relaxed);
    SELF_FALLING.store(false, Ordering::Relaxed);
}

// Whether a self damage may start now, and the safe fall distance: on the ground, out of water, above Self damage
// health, nothing of an earlier fall still counted, and room above for a climb of `climb` blocks.
fn self_damage_safe(game: &mut Game<'_>, m: &Module, climb: f64) -> Option<f64> {
    if game.creative || game.spectator() || !super::sunset::fall_clean() {
        return None;
    }
    let p = game.player.as_mut()?;
    if !p.ground.on_ground || p.flying || p.fall_flying || p.fluids.was_touching_water || p.health.health() <= m.n("Self damage health") as f32 {
        return None;
    }
    let safe = p.attribute("minecraft:safe_fall_distance").ok().unwrap_or(3.0);
    let (x, y, z) = (p.position.x, p.position.y, p.position.z);
    let (from, to) = ((y + 1.8).floor() as i32, (y + 1.8 + climb).floor() as i32);
    let mut columns: Vec<[i32; 2]> = [(-0.3, -0.3), (0.3, -0.3), (-0.3, 0.3), (0.3, 0.3)]
        .iter()
        .map(|(dx, dz)| [(x + dx).floor() as i32, (z + dz).floor() as i32])
        .collect();
    columns.dedup();
    let clear = columns.iter().all(|[cx, cz]| (from..=to).all(|by| super::sunset_util::is_air(game, [*cx, by, *cz])));
    clear.then_some(safe)
}

// Damage fly's tick, before the game's moves the player (with Flight on): whether Flight flies this tick. It stands you
// still through a self damage, starts the window's flight from the knockback, and turns Flight off when it is spent.
pub(super) fn damage_tick(game: &mut Game<'_>, m: &Module) -> bool {
    let trigger = Trigger::of(m.p("Damage fly"));
    if trigger == Trigger::Off {
        if damage(|d| d.trigger != Trigger::Off) {
            damage_reset();
        }
        damage(|d| d.knock = None);
        OPEN.store(true, Ordering::Relaxed);
        return true;
    }
    if damage(|d| d.trigger != trigger) {
        damage_reset();
        damage(|d| d.trigger = trigger);
    }
    let cfg = DamageCfg { trigger, window: m.n("Damage time (ticks)") as u32, again: m.p("After damage") == "Wait again" };
    let burst = m.p("Self damage method") != "Spread";
    let now = game.ticks;
    let (prev, len, base, fails, retry_at, burst_top) = damage(|d| (d.phase, d.heights.len(), d.base, d.fails, d.retry_at, d.burst_top));
    // Not with Blink holding moves: these would pass what it holds.
    let ready = trigger == Trigger::SelfDamage && prev == Wait::Armed && fails < MOST_FAILS && now >= retry_at
        && !super::sunset::with(|s| s.is_on("Blink"));
    let top = ready
        .then(|| self_damage_safe(game, m, if burst { BURST_STEP } else { 3.0 + FALL_EXTRA }))
        .flatten()
        .map(|safe| match (burst, burst_top) {
            (true, Some(top)) => top,
            (true, None) if fails == 0 => safe + 0.1,
            _ => safe + FALL_EXTRA,
        });
    let here = game.player.as_ref().map(|p| [p.position.x, p.position.y, p.position.z]);
    let falling = matches!(prev, Wait::Falling(t) if t < len);
    let moved = falling && here.is_none_or(|h| (0..3).any(|i| (h[i] - base[i]).abs() > 0.05));
    let (next, gave_up, send) = damage(|d| {
        let hurt = std::mem::take(&mut d.hurt);
        d.owed |= falling && hurt;
        let hurt = !falling && (hurt || std::mem::take(&mut d.owed));
        let setback = std::mem::take(&mut d.broken);
        let broken = falling && (setback || moved);
        let mut next = wait_tick(d.phase, cfg, hurt, top.is_some(), broken, len);
        d.hurts += u32::from(hurt);
        d.fresh = matches!(next, Wait::Open(_)) && !matches!(d.phase, Wait::Open(_));
        d.windows += u32::from(d.fresh);
        let failed = next == Wait::Armed && matches!(d.phase, Wait::Falling(_) | Wait::Landed(_));
        if failed {
            d.fails += 1;
            d.retry_at = now + RETRY_WAIT;
            d.reasons.push(match d.phase {
                Wait::Landed(_) => "no hurt",
                _ if setback => "setback",
                _ => "moved",
            });
        }
        if matches!(next, Wait::Open(_)) {
            // A Burst that brought it: its height is the one to use from now on.
            if burst && matches!(d.phase, Wait::Landed(_)) {
                d.burst_top = Some(d.try_top);
            }
            d.fails = 0;
            d.reasons.clear();
        } else {
            d.carry = None;
            d.knock = None;
        }
        let mut send = None;
        if next == Wait::Falling(0)
            && let (Some(top), Some(h)) = (top, here)
        {
            d.self_damages += 1;
            d.try_top = top;
            if burst {
                // All of it this tick: next, the wait for the hurt.
                send = Some((h, top));
                next = Wait::Landed(0);
            } else {
                d.heights = fall_heights(top);
                d.base = h;
            }
        }
        d.phase = next;
        let gave_up = (failed && d.fails == MOST_FAILS).then(|| d.reasons.join(", "));
        (next, gave_up, send)
    });
    if let Some(reasons) = gave_up {
        super::sunset_util::report(game, &format!("Flight: self damage brought no hurt three times ({reasons}); it waits for damage instead."));
    }
    if let Some((at, top)) = send {
        use horizon_protocol::packets::play::{self, Serverbound as S};
        // Past Sunset's own changes to moves (the look, the ground, the fall it keeps): these are the fall as it is.
        super::sunset_gui_move::direct(|| {
            for (dy, ground) in burst_moves(top, BURST_STEP) {
                game.send(S::MovePlayerPos(play::MovePlayerPos { x: at[0], y: at[1] + dy, z: at[2], flags: u8::from(ground) }));
            }
        });
    }
    match next {
        Wait::Falling(_) => {
            // Still through the fall: no keys, no speed across, and a position in every move packet.
            horizon_client::motion::sunset_motion::set_freeze(true);
            if let Some(p) = game.player.as_mut() {
                p.velocity.x = 0.0;
                p.velocity.z = 0.0;
            }
            horizon_client::player_sync::sunset_sync::remind();
        }
        Wait::Open(_) => match damage(|d| d.knock.take()) {
            Some(knock) => {
                let toward = (m.p("Knockback") == "Redirect").then(|| heading(game));
                let v = kick(knock, m.n("Damage boost"), toward);
                if let Some(p) = game.player.as_mut() {
                    p.velocity = horizon_core::geometry::Vec3::new(v[0], v[1], v[2]);
                }
                damage(|d| d.carry = Some([v[0], v[2]]));
            }
            None => damage(|d| d.carry = d.carry.map(|[x, z]| [x * 0.91, z * 0.91]).filter(|[x, z]| x.hypot(*z) > 0.01)),
        },
        Wait::Spent => {
            super::sunset::toggle_named(game, "Flight", false);
            super::sunset_util::report(game, "Flight off: its damage time is over.");
        }
        _ => {}
    }
    let open = matches!(next, Wait::Open(_));
    OPEN.store(open, Ordering::Relaxed);
    SELF_FALLING.store(matches!(next, Wait::Falling(_)), Ordering::Relaxed);
    open
}

// The Debug Report's line.
pub(super) fn report(out: &mut String) {
    use std::fmt::Write;
    let (strategy, phase, ticks, speed, recover, corrections, knocks, bursts) =
        state(|s| (s.strategy, s.phase, s.ticks, s.speed, s.recover, s.corrections, s.knocks, s.bursts));
    if let Some(strategy) = strategy {
        let _ = writeln!(out, "- Flight strategy: {strategy:?}, {phase:?} for {ticks} ticks, speed {speed:.3}, recovery {recover}, \
            {corrections} setbacks, {knocks} knockbacks, {bursts} bursts");
    }
    let (trigger, wait, hurts, windows, self_damages, fails) = damage(|d| (d.trigger, d.phase, d.hurts, d.windows, d.self_damages, d.fails));
    if trigger != Trigger::Off {
        let _ = writeln!(out, "- Flight damage fly: {trigger:?}, {wait:?}, {hurts} hurts, {windows} windows, {self_damages} self damages \
            ({fails} failed in a row)");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn old_ncp_offset_alternates_around_its_raise() {
        let mut rng = 7;
        for t in 0..200u64 {
            let o = old_ncp_offset(t, &mut rng);
            if t % 2 == 0 {
                assert!(o > 1e-5 && o < 2e-5, "{t}: {o}");
            } else {
                assert!(o < 1e-5 && o > 0.0, "{t}: {o}");
            }
        }
        assert_eq!(Strategy::of("Old NCP"), Some(Strategy::OldNcp));
        assert!(experimental("Old NCP"));
    }

    #[test]
    fn hover_offset_is_small_and_never_negative() {
        let mut rng = 7;
        for t in 0..200 {
            let o = hover_offset(t, &mut rng);
            if t % 2 == 1 {
                assert_eq!(o, 1e-5);
            } else {
                assert!((1e-5 + 1e-10..=2e-5).contains(&o), "{o}");
            }
        }
    }

    #[test]
    fn a_burst_waits_for_room_then_decays_and_ends() {
        let cfg = BurstCfg { speed: 9.0, friction: 0.935, repeat: false };
        // No room above: it waits.
        assert_eq!(burst_tick(Phase::Idle, 0, 0.0, 0, true, false, 0.0, cfg).0, Phase::Preparing);
        let (phase, speed, out) = burst_tick(Phase::Preparing, 0, 0.0, 0, true, true, 0.0, cfg);
        assert_eq!((phase, speed, out.jump, out.horizontal), (Phase::Active, 9.0, true, Some(9.0)));
        // Each tick 0.935 of the last, the fall softened.
        let (phase, speed, out) = burst_tick(Phase::Active, 1, 9.0, 1, false, true, -0.2, cfg);
        assert_eq!(phase, Phase::Active);
        assert!((speed - 8.415).abs() < 1e-9);
        assert_eq!(out.vertical, Some(-0.05));
        // It ends after 20 ticks, then waits to land; without Burst repeat no second one.
        assert_eq!(burst_tick(Phase::Active, 20, 3.0, 1, false, true, 0.0, cfg).0, Phase::Recovery);
        assert_eq!(burst_tick(Phase::Recovery, 0, 0.0, 1, false, true, 0.0, cfg).0, Phase::Recovery);
        assert_eq!(burst_tick(Phase::Recovery, 0, 0.0, 1, true, true, 0.0, cfg).0, Phase::Idle);
        assert_eq!(burst_tick(Phase::Idle, 0, 0.0, 1, true, true, 0.0, cfg).0, Phase::Idle);
        assert_eq!(burst_tick(Phase::Idle, 0, 0.0, 1, true, true, 0.0, BurstCfg { repeat: true, ..cfg }).0, Phase::Active);
    }

    #[test]
    fn bounce_saves_stops_and_gives_back() {
        let v = [0.3, 0.1, -0.2];
        let (out, saved) = bounce_tick(0, 4, 1.5, v, None);
        assert_eq!((out, saved), (v, Some(v)));
        assert_eq!(bounce_tick(1, 4, 1.5, [9.0; 3], saved).0, [0.0; 3]);
        assert_eq!(bounce_tick(2, 4, 1.5, [9.0; 3], saved).0, [0.0; 3]);
        let (out, saved) = bounce_tick(3, 4, 1.5, [0.0; 3], saved);
        assert!((out[0] - 0.45).abs() < 1e-9 && (out[1] - 0.15).abs() < 1e-9 && (out[2] + 0.3).abs() < 1e-9);
        assert_eq!(saved, None);
        // Upward never past a jump.
        assert_eq!(bounce_tick(3, 4, 2.0, [0.0; 3], Some([0.0, 0.4, 0.0])).0[1], 0.42);
    }

    #[test]
    fn damage_fly_waits_flies_its_time_and_waits_again_or_ends() {
        let cfg = DamageCfg { trigger: Trigger::Wait, window: 3, again: true };
        assert_eq!(wait_tick(Wait::Armed, cfg, false, true, false, 0), Wait::Armed, "Wait never deals itself damage");
        let mut phase = wait_tick(Wait::Armed, cfg, true, false, false, 0);
        let mut flown = 0;
        while let Wait::Open(_) = phase {
            flown += 1;
            phase = wait_tick(phase, cfg, flown == 2, false, false, 0);
            if flown == 2 {
                assert_eq!(phase, Wait::Open(3), "another hurt starts the time again");
            }
        }
        assert_eq!((flown, phase), (5, Wait::Armed));
        let once = DamageCfg { again: false, ..cfg };
        assert_eq!(wait_tick(Wait::Open(1), once, false, false, false, 0), Wait::Spent);
        assert_eq!(wait_tick(Wait::Spent, once, true, false, false, 0), Wait::Spent, "spent stays spent until Flight is off");
    }

    #[test]
    fn self_damage_falls_lands_then_waits_for_the_hurt() {
        let cfg = DamageCfg { trigger: Trigger::SelfDamage, window: 20, again: true };
        assert_eq!(wait_tick(Wait::Armed, cfg, false, false, false, 0), Wait::Armed, "not without room or health");
        let heights = fall_heights(4.05);
        let mut phase = wait_tick(Wait::Armed, cfg, false, true, false, heights.len());
        let mut ticks = 0;
        while let Wait::Falling(_) = phase {
            ticks += 1;
            phase = wait_tick(phase, cfg, false, true, false, heights.len());
        }
        assert_eq!((ticks, phase), (heights.len() + 1, Wait::Landed(0)), "each height, then the landing");
        assert_eq!(wait_tick(Wait::Landed(3), cfg, true, false, false, 0), Wait::Open(20));
        assert_eq!(wait_tick(Wait::Landed(LANDED_WAIT), cfg, false, true, false, 0), Wait::Armed, "no hurt: a failed try");
        assert_eq!(wait_tick(Wait::Falling(4), cfg, false, true, true, heights.len()), Wait::Armed, "a setback ends it");
        // The fall: never more than a jump up, gravity down, and the server counts all of it.
        let top = heights.iter().copied().fold(0.0, f64::max);
        assert!((top - 4.05).abs() < 1e-9 && *heights.last().unwrap() == 0.0, "{heights:?}");
        let mut last = 0.0;
        let mut counted = 0.0;
        for h in &heights {
            assert!(h - last <= 0.42 + 1e-9, "{heights:?}");
            counted += (last - h).max(0.0);
            last = *h;
        }
        assert!((counted - 4.05).abs() < 1e-9);
        assert_eq!((counted + 1e-6 - 3.0f64).floor(), 1.0, "one point of fall damage at the default safe distance");
        assert!(heights.len() <= 24, "about a second: {}", heights.len());
    }

    #[test]
    fn a_burst_stays_under_bukkits_move_event_and_adds_up_the_fall() {
        for top in [3.1, 4.05] {
            let moves = burst_moves(top, BURST_STEP);
            assert_eq!(moves.last(), Some(&(0.0, true)), "it ends on the ground");
            assert!(moves[..moves.len() - 1].iter().all(|m| !m.1), "everything before is off the ground");
            let (mut last, mut counted) = (0.0, 0.0);
            for &(h, _) in &moves {
                let d: f64 = h - last;
                assert!(d * d < 1.0 / 256.0, "{d}: a move Bukkit would report");
                counted += (last - h).max(0.0);
                last = h;
            }
            assert!(counted >= top && counted < top + BURST_STEP, "{counted}");
        }
        // 1.8: ceil(fall - 3) is half a heart just past 3; modern servers want a fall past 4.
        assert_eq!((3.1f64 - 3.0).ceil(), 1.0);
        assert_eq!((3.1f64 + 1e-6 - 3.0).floor(), 0.0);
        assert!(burst_moves(4.05, BURST_STEP).len() < 200);
    }

    #[test]
    fn the_knockback_is_kept_turned_and_scaled() {
        let knock = [0.3, 0.36, 0.4];
        let kept = kick(knock, 1.0, None);
        assert!((0..3).all(|i| (kept[i] - knock[i]).abs() < 1e-12), "Keep with a boost of 1 is the knockback as sent: {kept:?}");
        let v = kick(knock, 2.0, Some([0.0, -1.0]));
        assert!(v[0].abs() < 1e-12 && (v[2] + 1.0).abs() < 1e-12 && v[1] == 0.36, "{v:?}");
        assert_eq!(kick([0.0, 0.4, 0.0], 3.0, None), [0.0, 0.4, 0.0]);
        assert_eq!(kick(knock, 0.0, None)[0], 0.0);
        assert_eq!(Trigger::of("Self damage"), Trigger::SelfDamage);
        assert_eq!(Trigger::of("Off"), Trigger::Off);
    }
}

// Gear ESP (Mob Gear ESP before 1.0): what mobs and players carry, as far as it can be seen.
//
// Mob gear: mobs wearing or holding what players lose (a listed item, a listed enchantment, a named piece) are boxed,
// the pieces that gave them away shown above them, and with Chat named once.
//
// Player gear: each player near you, rebuilt from what the server shows of them. Two rows above their name (above
// Nametags' tag when it draws one):
// - Now: what they wear and hold this moment (head, chest, legs, feet, main hand, off hand), as the server sent it:
//   known.
// - Carried: what they are known to have had and not seen to have lost. Seen held or worn before, picked up (the
//   server tells who picks an item up, and the item is known), or given away by use (a pearl, potion, snowball, egg,
//   wind charge, arrow or trident they threw or shot) of something never seen in their hands. An item seen used since
//   it was last seen (thrown, shot, eaten to the last, a totem popped) may be gone and is marked so (dimmed, "?").
//   Then how many of their 36 inventory slots nothing is known of.
// What breaks (the server's item break event) or dies with them is forgotten; so is anything not seen for Forget
// after. Nothing guessed is shown as known: counts are those last seen, and only the Now row is the present.
//
// The server sends another player's armour and main hand with their components (enchantments, damage, count) and their
// off hand by id only, so an off hand piece has no count or enchantments here.

use super::sunset::{Camera, Canvas, Category, Module};
use super::sunset_util::*;
use super::sunset_visual::{Look, draw_box};
use super::Game;
use horizon_client::items::ItemStack;
use horizon_protocol::packets::play::Clientbound as C;
use std::collections::{HashMap, HashSet};
use std::fmt::Write;
use std::sync::Mutex;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};

pub(super) const NAME: &str = "Gear ESP";

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new(NAME, Category::Render, "Shows what mobs and players around you carry.")
            .bool("Mob gear", true)
            .text("Items", "netherite_*,diamond_sword,diamond_axe,diamond_pickaxe,diamond_shovel,diamond_hoe,mace,elytra,totem_of_undying,shulker_box,*_shulker_box,enchanted_golden_apple,ender_pearl")
            .text("Enchantments", "mending,frost_walker,soul_speed,swift_sneak,binding_curse,vanishing_curse")
            .bool("Named items", true)
            .bool("Chat", true)
            .bool("Mob items", true)
            .colour("Color", "Pink")
            .num("Fill opacity", 0.25, 0.0, 1.0, 0.05)
            .bool("Player gear", true)
            .bool("Carried", true)
            .bool("Unknown slots", true)
            .num("Player range", 48.0, 8.0, 256.0, 8.0)
            .num("Icon size", 12.0, 8.0, 16.0, 1.0)
            .num("Forget after (s)", 300.0, 30.0, 1800.0, 30.0),
    ]
}

pub(super) fn visible(m: &Module, name: &str) -> bool {
    match name {
        "Items" | "Enchantments" | "Named items" | "Chat" | "Mob items" | "Color" | "Fill opacity" => m.b("Mob gear"),
        "Carried" | "Player range" | "Icon size" | "Forget after (s)" => m.b("Player gear"),
        "Unknown slots" => m.b("Player gear") && m.b("Carried"),
        _ => true,
    }
}

// ---- Player gear's book: what is known of each player's things (pure, unit tested)

// The slots a player shows: main hand, off hand, head, chest, legs, feet.
pub(super) const SHOWN: usize = 6;
const OFF_HAND: usize = 1;
// Their inventory slots, besides the off hand and armour.
const INVENTORY: u32 = 36;
const MOST_ITEMS: usize = 24;
const MOST_PLAYERS: usize = 128;

// How an item came to be known.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum How {
    Held,
    Worn,
    Picked,
    // Only from using it (a pearl thrown, an arrow shot): they had one.
    Used,
}

#[derive(Clone, Debug)]
struct Known {
    key: String,
    stack: ItemStack,
    // The count last seen (the main hand's and picked up ones); None when the server never said.
    count: Option<u32>,
    how: How,
    // Seen used since it was last seen whole: it may be gone.
    spent: bool,
    seen: u64,
}

#[derive(Debug, Default)]
struct Player {
    items: Vec<Known>,
    // What each shown slot had last tick, and the main hand's count then.
    last: [Option<String>; SHOWN],
    last_count: Option<u32>,
    using: bool,
    // An item they threw or shot from their hand since the last sighting.
    threw: Option<String>,
    seen: u64,
}

// One item of the Carried row.
#[derive(Clone, Debug, PartialEq)]
pub(super) struct Carried {
    pub(super) stack: ItemStack,
    pub(super) count: Option<u32>,
    // Seen whole and not used since; false: it may be gone, or only its use was seen.
    pub(super) likely: bool,
}

#[derive(Debug, Default)]
pub(super) struct Book {
    players: HashMap<String, Player>,
}

// What tells two pieces apart: the item, its enchantments and its name (not its wear or count).
pub(super) fn key(stack: &ItemStack) -> String {
    let mut k = stack.item.to_string();
    let mut enchants: Vec<(String, u32)> = stack.enchantments().iter().map(|(e, l)| (e.to_string(), *l)).collect();
    enchants.sort();
    for (e, l) in enchants {
        let _ = write!(k, "|{e}{l}");
    }
    if let Some(name) = stack.custom_name() {
        let _ = write!(k, "|{name}");
    }
    k
}

// Consumables whose last one, used, leaves the hand empty.
fn consumable(item: &str) -> bool {
    let id = short(item);
    id.ends_with("potion") || id.ends_with("apple") || id.ends_with("pearl") || id.ends_with("_bottle") || id.ends_with("charge")
        || matches!(id, "snowball" | "egg" | "blue_egg" | "brown_egg" | "firework_rocket" | "totem_of_undying" | "chorus_fruit" | "golden_carrot"
            | "cooked_beef" | "cooked_porkchop" | "bread" | "end_crystal")
}

impl Book {
    fn player(&mut self, name: &str, now: u64, forget: u64) -> Option<&mut Player> {
        if !self.players.contains_key(name) {
            if self.players.len() >= MOST_PLAYERS {
                self.players.retain(|_, p| now.saturating_sub(p.seen) < forget);
                if self.players.len() >= MOST_PLAYERS {
                    return None;
                }
            }
            self.players.insert(name.to_owned(), Player::default());
        }
        self.players.get_mut(name)
    }

    fn note(p: &mut Player, stack: &ItemStack, count: Option<u32>, how: How, spent: bool, now: u64, by_id: bool) {
        let k = key(stack);
        // An off hand piece comes by id only: it is the one of that item already known, if any.
        let found = p.items.iter().position(|i| i.key == k).or_else(|| by_id.then(|| p.items.iter().position(|i| i.stack.item == stack.item)).flatten());
        match found {
            Some(i) => {
                let item = &mut p.items[i];
                if !by_id || item.key == k {
                    item.stack = stack.clone();
                }
                item.count = count.or(item.count);
                // What shows or was picked up is whole again; use marks it spent.
                if how != How::Used {
                    item.how = how;
                }
                item.spent = spent;
                item.seen = now;
            }
            None => {
                if p.items.len() >= MOST_ITEMS
                    && let Some(oldest) = (0..p.items.len()).min_by_key(|&i| p.items[i].seen)
                {
                    p.items.remove(oldest);
                }
                p.items.push(Known { key: k, stack: stack.clone(), count, how, spent, seen: now });
            }
        }
    }

    // A tick's sighting of a player: what each shown slot holds (the main hand with its count when the server sent
    // one), and whether they are using an item. `thrown`: items they threw or shot this tick.
    pub(super) fn observe(&mut self, name: &str, now: u64, forget: u64, shown: &[Option<ItemStack>; SHOWN], main_count: Option<u32>, using: bool) {
        let Some(p) = self.player(name, now, forget) else { return };
        p.seen = now;
        p.items.retain(|i| now.saturating_sub(i.seen) < forget);
        // The main hand's last one, used (eaten, drunk, thrown): a consumable's stack is gone, a thrown trident may be.
        let main_key = shown[0].as_ref().map(key);
        let threw = p.threw.take();
        if let Some(last) = p.last[0].clone()
            && main_key.as_deref() != Some(last.as_str())
            && p.last_count == Some(1)
            && (p.using || threw.as_deref() == last.split('|').next())
        {
            if p.items.iter().any(|i| i.key == last && consumable(&i.stack.item)) {
                p.items.retain(|i| i.key != last);
            } else if let Some(i) = p.items.iter_mut().find(|i| i.key == last) {
                i.spent = true;
            }
        }
        for (slot, stack) in shown.iter().enumerate() {
            let Some(stack) = stack else { continue };
            let (how, count) = match slot {
                0 => (How::Held, main_count),
                OFF_HAND => (How::Held, None),
                _ => (How::Worn, Some(stack.count)),
            };
            Self::note(p, stack, count, how, false, now, slot == OFF_HAND);
        }
        p.last = std::array::from_fn(|i| shown[i].as_ref().map(key));
        p.last_count = main_count;
        p.using = using;
    }

    // They threw or shot `item`: they had one. Held as it went, the hand's count tells the rest; else what is known of
    // it may be gone now (and was not known whole if it was never seen).
    pub(super) fn used(&mut self, name: &str, now: u64, forget: u64, item: &str) {
        let Some(p) = self.player(name, now, forget) else { return };
        let held = |slot: usize| p.last[slot].as_deref().is_some_and(|k| k.split('|').next() == Some(item));
        if held(0) || held(OFF_HAND) {
            p.threw = Some(item.to_owned());
            return;
        }
        match p.items.iter_mut().find(|i| &*i.stack.item == item) {
            Some(i) => {
                i.spent = true;
                i.count = None;
                i.seen = now;
            }
            None => Self::note(p, &ItemStack::new(item, 1), None, How::Used, true, now, false),
        }
    }

    // They picked up `stack` (`amount` of it).
    pub(super) fn picked(&mut self, name: &str, now: u64, forget: u64, stack: &ItemStack, amount: u32) {
        let Some(p) = self.player(name, now, forget) else { return };
        let k = key(stack);
        let before = p.items.iter().find(|i| i.key == k).and_then(|i| i.count).unwrap_or(0);
        Self::note(p, stack, Some(before + amount.max(1)), How::Picked, false, now, false);
    }

    // A totem of theirs went off: that one is gone, whether they have another the off hand will tell.
    pub(super) fn popped(&mut self, name: &str, now: u64, forget: u64) {
        let Some(p) = self.player(name, now, forget) else { return };
        if let Some(i) = p.items.iter_mut().find(|i| i.stack.item.ends_with("totem_of_undying")) {
            i.spent = true;
            i.seen = now;
        } else {
            Self::note(p, &ItemStack::new("minecraft:totem_of_undying", 1), None, How::Used, true, now, false);
        }
    }

    // What a shown slot held broke.
    pub(super) fn broke(&mut self, name: &str, slot: usize) {
        if let Some(p) = self.players.get_mut(name)
            && let Some(k) = p.last.get(slot).cloned().flatten()
        {
            p.items.retain(|i| i.key != k);
        }
    }

    // They died: what they carried is not theirs any more.
    pub(super) fn died(&mut self, name: &str) {
        if let Some(p) = self.players.get_mut(name) {
            p.items.clear();
            p.last = Default::default();
            p.last_count = None;
        }
    }

    // The Carried row for a player now (what they show now left out), the likeliest and most telling first, and how
    // many inventory slots nothing is known of (the main hand's stack is in one).
    pub(super) fn carried(&self, name: &str, now: u64, forget: u64, shown: &[Option<ItemStack>; SHOWN]) -> (Vec<Carried>, u32) {
        let Some(p) = self.players.get(name) else {
            return (Vec::new(), INVENTORY - u32::from(shown[0].is_some()));
        };
        let showing: HashSet<String> = shown.iter().flatten().map(key).collect();
        // An off hand piece known by id only stands for the one of that item.
        let off_id = shown[OFF_HAND].as_ref().map(|s| s.item.clone());
        let mut out: Vec<(&Known, u8)> = p
            .items
            .iter()
            .filter(|i| now.saturating_sub(i.seen) < forget && !showing.contains(&i.key))
            .filter(|i| off_id.as_ref() != Some(&i.stack.item))
            .map(|i| (i, rank(&i.stack.item)))
            .collect();
        out.sort_by(|(a, ra), (b, rb)| (a.spent || a.how == How::Used).cmp(&(b.spent || b.how == How::Used)).then(ra.cmp(rb)).then(b.seen.cmp(&a.seen)));
        let held = u32::from(shown[0].is_some());
        let unknown = INVENTORY.saturating_sub(held + out.len() as u32);
        let row = out
            .into_iter()
            .map(|(i, _)| Carried { stack: i.stack.clone(), count: i.count, likely: !i.spent && i.how != How::Used })
            .collect();
        (row, unknown)
    }

    pub(super) fn clear(&mut self) {
        self.players.clear();
    }
}

// How telling an item is in a fight, most first: totems, golden apples, pearls, crystals and anchors, potions,
// weapons, armour, the rest.
fn rank(item: &str) -> u8 {
    let id = short(item);
    match id {
        "totem_of_undying" => 0,
        "enchanted_golden_apple" => 1,
        "golden_apple" => 2,
        "ender_pearl" | "wind_charge" => 3,
        "end_crystal" | "respawn_anchor" | "glowstone" | "obsidian" => 4,
        _ if id.ends_with("potion") => 5,
        _ if id.ends_with("_sword") || id.ends_with("_axe") || id.ends_with("_spear") || matches!(id, "mace" | "trident" | "bow" | "crossbow") => 6,
        _ if id.ends_with("_helmet") || id.ends_with("_chestplate") || id.ends_with("_leggings") || id.ends_with("_boots") || id == "elytra" => 7,
        _ => 8,
    }
}

// ---- in the game

#[derive(Default)]
struct Gs {
    book: Book,
    // Mobs giving themselves away, and the pieces that did; the ones already told in chat.
    mobs: Vec<(u32, Vec<ItemStack>)>,
    said: HashSet<u32>,
    // The item entities about, by id: a pickup's item is gone from the world by the time its packet is read.
    items: HashMap<u32, ItemStack>,
    world: (u64, &'static str),
}

static GS: Mutex<Option<Gs>> = Mutex::new(None);
// Player gear is on: the packets are read for it, and Forget after in ticks.
static WATCH: AtomicBool = AtomicBool::new(false);
static FORGET: AtomicU64 = AtomicU64::new(6000);

fn gs<R>(f: impl FnOnce(&mut Gs) -> R) -> R {
    f(GS.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Gs::default))
}

fn forget(m: &Module) -> u64 {
    (m.n("Forget after (s)") * 20.0) as u64
}

fn is_player(mob: &horizon_client::mobs::Mob) -> bool {
    &*mob.kind.id == "minecraft:player"
}

fn own(game: &Game<'_>, id: u32) -> bool {
    game.remote.as_ref().is_some_and(|r| r.entity_id == id as i32)
}

// What a player shows: main hand (and its count when the server sent it with its stack), off hand, head to feet.
fn shown(mob: &horizon_client::mobs::Mob) -> ([Option<ItemStack>; SHOWN], Option<u32>) {
    let e = &mob.extra;
    let by_id = |id: &Option<std::sync::Arc<str>>| id.as_ref().map(|id| ItemStack::new(id, 1));
    let main_stack = e.main_hand_stack().cloned();
    let count = main_stack.as_ref().map(|s| s.count);
    let main = main_stack.or_else(|| by_id(&e.main_hand));
    let worn = |a: usize, id: &Option<std::sync::Arc<str>>| e.armor[a].clone().filter(|s| Some(&s.item) == id.as_ref()).or_else(|| by_id(id));
    ([main, by_id(&e.off_hand), worn(0, &e.head), worn(1, &e.chest), worn(2, &e.legs), worn(3, &e.feet)], count)
}

pub(super) fn tick(game: &mut Game<'_>, mods: &[Module]) {
    let m = mods.iter().find(|m| m.name == NAME && m.on);
    // A new world or dimension starts over.
    let world = (world_hash(game).unwrap_or(0), game.dim.id());
    if gs(|g| g.world != world) {
        gs(|g| *g = Gs { world, ..Gs::default() });
    }
    let Some(m) = m else {
        WATCH.store(false, Ordering::Relaxed);
        gs(|g| {
            g.mobs.clear();
            g.said.clear();
            g.items.clear();
        });
        return;
    };
    mob_gear(game, m);
    let watch = m.b("Player gear");
    WATCH.store(watch, Ordering::Relaxed);
    FORGET.store(forget(m), Ordering::Relaxed);
    if !watch {
        gs(|g| {
            g.book.clear();
            g.items.clear();
        });
        return;
    }
    let (now, forget, range) = (game.ticks, forget(m), m.n("Player range"));
    let me = game.player.as_ref().map(|p| [p.position.x, p.position.y, p.position.z]);
    let near = |at: [f64; 3]| me.is_some_and(|me| dist(me, at) <= range + 16.0);
    let seen: Vec<(String, [Option<ItemStack>; SHOWN], Option<u32>, bool)> = game
        .mobs
        .iter()
        .filter(|x| is_player(x) && x.alive() && !x.removed && !own(game, x.id) && near([x.position.x, x.position.y, x.position.z]))
        .filter_map(|x| {
            let name = game.remote_player_name(x.id)?.to_owned();
            let (shown, count) = shown(x);
            Some((name, shown, count, x.extra.using_item > 0))
        })
        .collect();
    // The item entities about, kept for pickups.
    let items: Vec<(u32, &ItemStack)> =
        game.dropped.iter().filter(|d| near([d.position.x, d.position.y, d.position.z])).map(|d| (d.id, &d.stack)).collect();
    gs(|g| {
        for (name, shown, count, using) in &seen {
            g.book.observe(name, now, forget, shown, *count, *using);
        }
        g.items.retain(|id, _| items.iter().any(|(i, _)| i == id));
        for (id, stack) in items {
            g.items.entry(id).or_insert_with(|| stack.clone());
        }
    });
}

// The thrown and shot things that give an item away, by entity type.
fn thrown_item(kind: &str) -> Option<&'static str> {
    Some(match short(kind) {
        "ender_pearl" => "minecraft:ender_pearl",
        "snowball" => "minecraft:snowball",
        "egg" => "minecraft:egg",
        "splash_potion" => "minecraft:splash_potion",
        "lingering_potion" => "minecraft:lingering_potion",
        "experience_bottle" => "minecraft:experience_bottle",
        "wind_charge" => "minecraft:wind_charge",
        "trident" => "minecraft:trident",
        "arrow" => "minecraft:arrow",
        "spectral_arrow" => "minecraft:spectral_arrow",
        _ => return None,
    })
}

// The packets since the last tick, for Player gear: who threw or shot what, picked what up, popped a totem, broke a
// piece or died.
pub(super) fn packet(game: &Game<'_>, packet: &C) {
    if !WATCH.load(Ordering::Relaxed) {
        return;
    }
    let (now, forget) = (game.ticks, FORGET.load(Ordering::Relaxed));
    let name = |id: i32| u32::try_from(id).ok().and_then(|id| game.remote_player_name(id)).map(str::to_owned);
    match packet {
        C::AddEntity(p) => {
            let kind = game.remote.as_ref().and_then(|r| r.builtin.get("minecraft:entity_type")).and_then(|t| t.name(p.kind));
            if let (Some(item), Some(owner)) = (kind.and_then(thrown_item), name(p.data)) {
                gs(|g| g.book.used(&owner, now, forget, item));
            }
        }
        C::TakeItemEntity(p) => {
            if let Some(who) = name(p.player)
                && let Ok(id) = u32::try_from(p.item)
                && let Some(stack) = gs(|g| g.items.get(&id).cloned())
            {
                gs(|g| g.book.picked(&who, now, forget, &stack, u32::try_from(p.amount).unwrap_or(1)));
            }
        }
        C::EntityEvent(p) => {
            let Some(who) = name(p.id) else { return };
            match p.event {
                35 => gs(|g| g.book.popped(&who, now, forget)),
                3 => gs(|g| g.book.died(&who)),
                // LivingEntity.entityEventForEquipmentBreak: main hand, off hand, head, chest, legs, feet.
                47..=52 => gs(|g| g.book.broke(&who, (p.event - 47) as usize)),
                _ => {}
            }
        }
        _ => {}
    }
}

// ---- Mob gear

// What on a mob gives it away: the listed items it wears or holds, a piece with a listed enchantment, or a named
// piece. The text for chat and the pieces.
fn mob_find(m: &Module, mob: &horizon_client::mobs::Mob) -> Option<(String, Vec<ItemStack>)> {
    let list = m.t("Items");
    let listed_item = |id: &str| {
        let id = short(id);
        list.split(',').map(str::trim).filter(|x| !x.is_empty()).any(|x| {
            x.strip_prefix('*').map_or(x == id, |end| id.ends_with(end)) || x.strip_suffix('*').is_some_and(|start| !start.is_empty() && id.starts_with(start))
        })
    };
    let (shown, _) = shown(mob);
    let mut pieces: Vec<ItemStack> = Vec::new();
    let mut said: Option<String> = None;
    for stack in shown.iter().flatten() {
        let label = short(&stack.item).replace('_', " ");
        let why = if listed_item(&stack.item) {
            Some(label)
        } else if let Some((name, _)) = stack.enchantments().iter().find(|(n, _)| listed(m.t("Enchantments"), n)) {
            Some(format!("{label} with {}", short(name).replace('_', " ")))
        } else if m.b("Named items") && let Some(name) = stack.custom_name() {
            Some(format!("{label} named {name}"))
        } else {
            None
        };
        if let Some(why) = why {
            said.get_or_insert(why);
            pieces.push(stack.clone());
        }
    }
    said.map(|s| (s, pieces))
}

fn mob_gear(game: &mut Game<'_>, m: &Module) {
    if !m.b("Mob gear") {
        gs(|g| {
            g.mobs.clear();
            g.said.clear();
        });
        return;
    }
    if game.ticks % 10 != 0 {
        return;
    }
    let found: Vec<(u32, String, Vec<ItemStack>, [f64; 3], String)> = game
        .mobs
        .iter()
        .filter(|x| x.alive() && !x.removed && !is_player(x))
        .filter_map(|x| mob_find(m, x).map(|(said, pieces)| (x.id, said, pieces, [x.position.x, x.position.y, x.position.z], short(&x.kind.id).replace('_', " "))))
        .collect();
    let fresh: Vec<(String, [f64; 3], String)> = gs(|g| {
        g.mobs = found.iter().map(|f| (f.0, f.2.clone())).collect();
        found.into_iter().filter(|f| g.said.insert(f.0)).map(|f| (f.1, f.3, f.4)).collect()
    });
    if m.b("Chat") {
        for (gear, p, kind) in fresh {
            report(game, &format!("A {kind} with {gear} at {:.0} {:.0} {:.0}", p[0], p[1], p[2]));
        }
    }
}

// ---- drawing

// A row of icons centred on `x`, its bottom at `bottom`; returns its top. Dimmed icons are drawn under a shade with a
// "?" (may be gone); counts over 1 in the corner, wear as a bar under damageable pieces.
fn row(game: &Game<'_>, out: &mut impl Canvas, icons: &[(&ItemStack, Option<u32>, bool)], tail: Option<&str>, x: f32, bottom: f32, size: f32) -> f32 {
    let gap = 1.0;
    let tail_w = tail.map_or(0.0, |t| game.native_text_width(t) * 0.6 + 2.0);
    let width = icons.len() as f32 * (size + gap) - gap + tail_w;
    let (left, top) = (x - width / 2.0, bottom - size - 2.0);
    out.fill([left - 2.0, top - 1.0, width + 4.0, size + 3.0], 0x7000_0000);
    for (i, (stack, count, sure)) in icons.iter().enumerate() {
        let at = [left + i as f32 * (size + gap), top];
        out.item(stack, at, size);
        if let Some(max) = game.res.items().get(&stack.item).map(|i| i.max_damage).filter(|m| *m > 0)
            && stack.damage > 0
        {
            let left_frac = 1.0 - (stack.damage as f32 / max as f32).min(1.0);
            let rgb = super::sunset_hud_bars::wear_rgb(left_frac);
            out.fill([at[0] + 1.0, at[1] + size, (size - 2.0) * left_frac, 1.0], 0xFF00_0000 | rgb);
        }
        if !sure {
            out.fill([at[0], at[1], size, size], 0x9000_0000);
            out.scaled("?", [at[0] + size - 4.0, at[1]], 0xFFFF55, 0.6);
        }
        if let Some(n) = count.filter(|n| *n > 1) {
            let t = n.to_string();
            let w = game.native_text_width(&t) * 0.6;
            out.scaled(&t, [at[0] + size - w, at[1] + size - 5.0], if *sure { 0xFFFFFF } else { 0xAAAAAA }, 0.6);
        }
    }
    if let Some(t) = tail {
        out.scaled(t, [left + width - tail_w + 2.0, top + size / 2.0 - 2.5], 0xAAAAAA, 0.6);
    }
    top - 1.0
}

// Boxes and pieces of Mob gear; the rows of Player gear above each player's name, or above Nametags' tag (`tags`: the
// players Nametags drew this frame, with the middle and top of their tag).
pub(super) fn draw(game: &Game<'_>, cam: &Camera, mods: &[Module], out: &mut impl Canvas, lw: f32, tags: &[(u32, [f32; 2])]) {
    let Some(m) = mods.iter().find(|m| m.name == NAME && m.on) else { return };
    let size = m.n("Icon size") as f32;
    let alpha = game.clock.camera_fraction();
    let lerp = |a: f64, b: f64| a + alpha * (b - a);
    let top_of = |mob: &horizon_client::mobs::Mob| {
        let b = mob.bounds();
        let (lo, hi) = (b.min_position(), b.max_position());
        let off = [lerp(mob.previous.x, mob.position.x) - mob.position.x, lerp(mob.previous.y, mob.position.y) - mob.position.y,
            lerp(mob.previous.z, mob.position.z) - mob.position.z];
        ([lo.x + off[0], lo.y + off[1], lo.z + off[2]], [hi.x + off[0], hi.y + off[1], hi.z + off[2]])
    };
    let mob_items = m.b("Mob items");
    gs(|g| {
        if m.b("Mob gear") {
            let look = Look::of(m);
            for (id, pieces) in &g.mobs {
                let Some(mob) = game.mobs.iter().find(|x| x.id == *id) else { continue };
                let (lo, hi) = top_of(mob);
                draw_box(cam, out, &look, lo, hi, m.c("Color"), lw);
                let above = [(lo[0] + hi[0]) / 2.0, hi[1] + 0.3, (lo[2] + hi[2]) / 2.0];
                if mob_items
                    && cam.sees(above, 1.0)
                    && let Some([x, y]) = cam.project(above)
                {
                    let icons: Vec<(&ItemStack, Option<u32>, bool)> = pieces.iter().map(|s| (s, None, true)).collect();
                    row(game, out, &icons, None, x, y, size);
                }
            }
        }
        if !m.b("Player gear") {
            return;
        }
        let (now, forget, range) = (game.ticks, forget(m), m.n("Player range"));
        let (carried_on, unknown_on) = (m.b("Carried"), m.b("Unknown slots"));
        for mob in game.mobs.iter().filter(|x| is_player(x) && x.alive() && !x.removed && !own(game, x.id)) {
            let (lo, hi) = top_of(mob);
            let mid = [(lo[0] + hi[0]) / 2.0, (lo[1] + hi[1]) / 2.0, (lo[2] + hi[2]) / 2.0];
            if dist(mid, cam.pos()) > range {
                continue;
            }
            let Some(name) = game.remote_player_name(mob.id) else { continue };
            // Above Nametags' tag, else above the game's own name over the head.
            let anchor = match tags.iter().find(|(id, _)| *id == mob.id) {
                Some((_, at)) => Some(*at),
                None => {
                    let above = [mid[0], hi[1] + 0.75, mid[2]];
                    cam.sees(above, 1.0).then(|| cam.project(above)).flatten()
                }
            };
            let Some([x, mut bottom]) = anchor else { continue };
            let (now_row, _) = shown(mob);
            if carried_on {
                let (carried, unknown) = g.book.carried(name, now, forget, &now_row);
                let tail = (unknown_on && unknown > 0).then(|| format!("+{unknown}?"));
                if !carried.is_empty() || tail.is_some() {
                    let icons: Vec<(&ItemStack, Option<u32>, bool)> = carried.iter().map(|c| (&c.stack, c.count, c.likely)).collect();
                    bottom = row(game, out, &icons, tail.as_deref(), x, bottom, (size * 0.8).round());
                }
            }
            let main_count = mob.extra.main_hand_stack().map(|s| s.count);
            let order = [2, 3, 4, 5, 0, 1];
            let icons: Vec<(&ItemStack, Option<u32>, bool)> = order
                .iter()
                .filter_map(|&i| now_row[i].as_ref().map(|s| (s, if i == 0 { main_count } else { None }, true)))
                .collect();
            if !icons.is_empty() {
                row(game, out, &icons, None, x, bottom, size);
            }
        }
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    const F: u64 = 6000;

    fn st(id: &str, count: u32) -> Option<ItemStack> {
        Some(ItemStack::new(&format!("minecraft:{id}"), count))
    }

    fn hands(main: Option<ItemStack>, off: Option<ItemStack>, chest: Option<ItemStack>) -> [Option<ItemStack>; SHOWN] {
        [main, off, None, chest, None, None]
    }

    fn names(row: &[Carried]) -> Vec<(String, bool)> {
        row.iter().map(|c| (short(&c.stack.item).to_owned(), c.likely)).collect()
    }

    #[test]
    fn what_was_seen_is_carried_and_only_the_present_is_known() {
        let mut b = Book::default();
        let sword = hands(st("diamond_sword", 1), st("totem_of_undying", 1), st("netherite_chestplate", 1));
        b.observe("Rival", 100, F, &sword, Some(1), false);
        let pearls = hands(st("ender_pearl", 16), st("totem_of_undying", 1), st("elytra", 1));
        b.observe("Rival", 101, F, &pearls, Some(16), false);
        let (row, unknown) = b.carried("Rival", 102, F, &pearls);
        // The sword and the chestplate no longer show: carried, likely; the totem shows, so it is not in the row.
        assert_eq!(names(&row), [("diamond_sword".into(), true), ("netherite_chestplate".into(), true)]);
        assert_eq!(unknown, 36 - 1 - 2);
        // Back to the sword: the pearls are carried, 16 last seen.
        b.observe("Rival", 103, F, &sword, Some(1), false);
        let (row, _) = b.carried("Rival", 103, F, &sword);
        let pearl = row.iter().find(|c| c.stack.item.ends_with("ender_pearl")).unwrap();
        assert_eq!((pearl.count, pearl.likely), (Some(16), true));
        // Unknown players have nothing known but the slot in their hand.
        assert_eq!(b.carried("Nobody", 103, F, &sword), (Vec::new(), 35));
        // Forgotten after Forget after.
        assert!(b.carried("Rival", 103 + F, F, &sword).0.is_empty());
    }

    #[test]
    fn use_and_loss_make_items_uncertain_or_gone() {
        let mut b = Book::default();
        let sword = hands(st("diamond_sword", 1), None, None);
        b.observe("Rival", 1, F, &sword, Some(1), false);
        // A pearl thrown from the hand: the hand's count tells the rest. The last one thrown is gone.
        b.observe("Rival", 1, F, &hands(st("ender_pearl", 1), None, None), Some(1), false);
        b.used("Rival", 1, F, "minecraft:ender_pearl");
        b.observe("Rival", 1, F, &sword, Some(1), false);
        assert!(b.carried("Rival", 1, F, &sword).0.is_empty());
        // A pearl thrown, never seen held (a silent swap): they had one, which may be gone.
        b.used("Rival", 2, F, "minecraft:ender_pearl");
        let (row, _) = b.carried("Rival", 2, F, &sword);
        assert_eq!(names(&row), [("ender_pearl".into(), false)]);
        // A golden apple eaten to the last: gone.
        b.observe("Rival", 3, F, &hands(st("golden_apple", 1), None, None), Some(1), true);
        b.observe("Rival", 4, F, &sword, Some(1), false);
        assert!(!names(&b.carried("Rival", 4, F, &sword).0).iter().any(|(n, _)| n == "golden_apple"));
        // Switched away from a stack of them: carried.
        b.observe("Rival", 5, F, &hands(st("golden_apple", 5), None, None), Some(5), true);
        b.observe("Rival", 6, F, &sword, Some(1), false);
        assert!(names(&b.carried("Rival", 6, F, &sword).0).contains(&("golden_apple".into(), true)));
        // A totem popped with none shown after: may be gone. A piece that broke: gone.
        b.observe("Rival", 7, F, &hands(st("diamond_sword", 1), st("totem_of_undying", 1), st("diamond_chestplate", 1)), Some(1), false);
        b.popped("Rival", 8, F);
        b.observe("Rival", 8, F, &sword, Some(1), false);
        assert!(names(&b.carried("Rival", 8, F, &sword).0).contains(&("totem_of_undying".into(), false)));
        b.observe("Rival", 9, F, &hands(st("diamond_sword", 1), None, st("diamond_chestplate", 1)), Some(1), false);
        b.broke("Rival", 3);
        b.observe("Rival", 10, F, &sword, Some(1), false);
        assert!(!names(&b.carried("Rival", 10, F, &sword).0).iter().any(|(n, _)| n == "diamond_chestplate"));
        // A pickup is known with its count; death forgets everything.
        b.picked("Rival", 11, F, &ItemStack::new("minecraft:obsidian", 1), 12);
        let (row, _) = b.carried("Rival", 11, F, &sword);
        assert_eq!(row.iter().find(|c| c.stack.item.ends_with("obsidian")).and_then(|c| c.count), Some(12));
        b.died("Rival");
        assert!(b.carried("Rival", 12, F, &sword).0.is_empty());
    }

    #[test]
    fn enchanted_pieces_are_told_apart_and_the_book_stays_bounded() {
        let mut plain = ItemStack::new("minecraft:diamond_sword", 1);
        let mut sharp = plain.clone();
        sharp.enchant("minecraft:sharpness", 5);
        assert_ne!(key(&plain), key(&sharp));
        plain.damage = 100;
        assert_eq!(key(&plain), key(&ItemStack::new("minecraft:diamond_sword", 1)), "wear is not identity");
        let mut b = Book::default();
        for i in 0..60 {
            b.observe("Rival", i, F, &hands(st(&format!("item_{i}"), 1), None, None), Some(1), false);
        }
        assert!(b.players["Rival"].items.len() <= MOST_ITEMS);
        for i in 0..300 {
            b.observe(&format!("p{i}"), 50, F, &Default::default(), None, false);
        }
        assert!(b.players.len() <= MOST_PLAYERS);
        // The unknown count never goes below none.
        let (_, unknown) = b.carried("Rival", 60, F, &hands(st("stick", 1), None, None));
        assert!(unknown <= 36);
    }
}

// GUI Move's GrimAC mode holds only the inventory packets. The native menu still handles every local click.
use super::remote::sunset_gui_move_remote::{self as inventory, Snapshot};
use super::sunset;
use super::{Game, Screen};
use horizon_client::net::sunset_packets as net;
use horizon_protocol::packets::play::{self, Clientbound as C, Serverbound as S};
use std::cell::{Cell, RefCell};
use std::sync::{Arc, Mutex};

type Session = Arc<Mutex<Option<Arc<horizon_protocol::connection::Counters>>>>;
const STOP_AT: usize = 128;
const MOST: usize = 1024;

#[derive(Default)]
struct Transaction {
    session: Option<Session>,
    dimension: Option<super::Dim>,
    entity: Option<i32>,
    packets: Vec<S>,
    base: Option<Snapshot>,
    closing: bool,
    quiet_move: Option<u64>,
    overflowed: bool,
    yielded: bool,
    stop_started: Option<u64>,
    wait_reported: bool,
}

thread_local! {
    static TRANSACTION: RefCell<Transaction> = RefCell::new(Transaction::default());
    static REPLAY: Cell<bool> = const { Cell::new(false) };
}

fn state<R>(run: impl FnOnce(&mut Transaction) -> R) -> R {
    TRANSACTION.with(|value| run(&mut value.borrow_mut()))
}

pub(super) fn replaying() -> bool {
    REPLAY.with(Cell::get)
}

// A click Sunset's inventory modules send themselves while you stand still (Inventory Manager, Auto Armor): it goes
// past GrimAC mode's queue as a plain click. Queued, it would wait for the inventory to close, and the module with it.
pub(super) fn direct<R>(f: impl FnOnce() -> R) -> R {
    let before = REPLAY.with(|flag| flag.replace(true));
    let result = f();
    REPLAY.with(|flag| flag.set(before));
    result
}

fn enabled(game: &Game<'_>) -> bool {
    game.native_window()
        && game.native_on(sunset::ID)
        && sunset::with(|s| {
            s.module("GUI Move")
                .is_some_and(|m| m.on && m.p("Mode") == "GrimAC")
        })
}

fn own(game: &Game<'_>) -> bool {
    game.screen == Screen::Inventory && game.remote_menu().0 == 0 && !game.creative
}

pub(super) fn inventory_busy() -> bool {
    state(|s| !s.packets.is_empty() || s.closing)
}

pub(super) fn stopping() -> bool {
    state(|s| s.closing && !s.yielded)
}

fn same_session(game: &Game<'_>, s: &Transaction) -> bool {
    game.remote.as_ref().is_some_and(|r| {
        s.session
            .as_ref()
            .is_some_and(|old| Arc::ptr_eq(old, &r.session.counters))
    }) && s.dimension == Some(game.dim)
        && s.entity == game.remote.as_ref().map(|r| r.entity_id)
}

fn attach(game: &Game<'_>, s: &mut Transaction) {
    s.session = game.remote.as_ref().map(|r| r.session.counters.clone());
    s.dimension = Some(game.dim);
    s.entity = game.remote.as_ref().map(|r| r.entity_id);
}

// Every input path calls this before predicting. An arriving slot update is rebased first, so a second click
// cannot accidentally pick up a stack from the server's old copy of the inventory.
pub(super) fn before_click(game: &mut Game<'_>) -> bool {
    if replaying() {
        return true;
    }
    // Your click (or another module's, outside `direct`): what the cursor holds is no longer Inventory Manager's.
    super::sunset_player::inventory_clicked(game.ticks);
    if game.remote_menu().0 != 0 && inventory_busy() {
        cancel(game, "a server container replaced the inventory");
    }
    updates(game);
    if state(|s| s.closing) {
        return false;
    }
    if enabled(game) && own(game) && game.remote.is_some() {
        state(|s| {
            if s.base.is_none() {
                attach(game, s);
                s.base = Some(Snapshot::capture(game));
                net::gui_move_active(true);
            }
        });
    }
    true
}

fn begin_close(s: &mut Transaction, container: i32) {
    if !s
        .packets
        .iter()
        .any(|packet| matches!(packet, S::ContainerClose(p) if p.container == container))
    {
        s.packets
            .push(S::ContainerClose(play::ContainerClose { container }));
    }
    s.closing = true;
}

pub(super) fn outgoing(game: &Game<'_>, packet: &S) -> bool {
    if replaying() {
        return false;
    }
    match packet {
        S::ContainerClick(p) if p.container == 0 && enabled(game) && own(game) => state(|s| {
            // The native prediction hook must have captured authority before the local mutation. Never claim
            // recovery support for a raw plugin packet that did not use the menu engine.
            if s.base.is_none() {
                return false;
            }
            if s.packets.len() >= MOST {
                s.overflowed = true;
                return true;
            }
            // A native drag/quick-move batch was predicted before its first packet. If it crosses STOP_AT,
            // keep the remaining packets of that already-admitted batch ahead of the synthesized close.
            let before_close = s
                .packets
                .iter()
                .position(|p| matches!(p, S::ContainerClose(_)))
                .unwrap_or(s.packets.len());
            s.packets.insert(before_close, packet.clone());
            net::gui_move_active(s.base.is_some());
            if s.packets.len() >= STOP_AT {
                s.closing = true;
            }
            true
        }),
        S::ContainerClose(p) if p.container == 0 && (enabled(game) || inventory_busy()) => {
            state(|s| {
                if s.session.is_none() {
                    attach(game, s);
                }
                begin_close(s, p.container);
                true
            })
        }
        _ => false,
    }
}

// Called only after all transformations and every packet delay. Engine `last_input` and `was_sprinting` are
// scheduled state, which can be ahead of the server while Fake Lag or a plugin holds the packet.
pub(super) fn forwarded(game: &Game<'_>, packet: &S) {
    state(|s| {
        if !same_session(game, s) {
            return;
        }
        match packet {
            S::PlayerInput(p) if p.flags & 0x7f != 0 => s.quiet_move = None,
            S::PlayerCommand(p) if p.action == 1 => s.quiet_move = None,
            S::MovePlayerPos(_)
            | S::MovePlayerPosRot(_)
            | S::MovePlayerRot(_)
            | S::MovePlayerStatus(_) => {
                if super::sunset_combat_wire::sent_input(game) & 0x7f == 0
                    && !super::sunset_combat_wire::sent_sprinting(game)
                {
                    s.quiet_move.get_or_insert(game.ticks);
                } else {
                    s.quiet_move = None;
                }
            }
            _ => {}
        }
    });
}

fn updates(game: &mut Game<'_>) {
    if !net::gui_move_pending() {
        return;
    }
    // The new server menu must receive its own updates first. Its state hook cancels the old transaction before
    // the native handler writes those slots; an own-inventory click is never interpreted as a chest click.
    if game.remote_menu().0 != 0 {
        return;
    }
    let updates = net::gui_move_take();
    let mut failed = false;
    state(|s| {
        if !same_session(game, s) {
            return;
        }
        let Some(base) = s.base.as_mut() else {
            return;
        };
        if s.packets.is_empty() {
            inventory::restore_authority(game, base, &updates);
            *base = Snapshot::capture(game);
        } else if !inventory::rebase(game, base, &mut s.packets, &updates) {
            // An unsupported semantic operation is explicitly cancelled on the authoritative snapshot.
            // The close still synchronizes the menu; old hashes are never sent as a recovery strategy.
            s.packets
                .retain(|packet| matches!(packet, S::ContainerClose(_)));
            s.closing = true;
            failed = true;
        }
    });
    if failed {
        sunset::say(
            game,
            "GUI Move: the server changed the inventory; pending clicks could not be replayed and were cancelled.",
        );
    }
}

fn send_queued(game: &Game<'_>) {
    let packets = state(|s| std::mem::take(&mut s.packets));
    REPLAY.with(|flag| flag.set(true));
    for packet in packets {
        game.send(packet);
    }
    REPLAY.with(|flag| flag.set(false));
    state(|s| {
        s.base = None;
        s.closing = false;
        s.quiet_move = None;
        s.yielded = false;
        s.stop_started = None;
        s.wait_reported = false;
    });
    net::gui_move_active(false);
}

// Panic cancels predictions instead of scheduling another inventory action.
pub(super) fn shutdown(game: &mut Game<'_>) {
    if state(|s| same_session(game, s)) && game.remote_menu().0 == 0 {
        cancel(game, "Sunset stopped");
    } else {
        net::gui_move_active(false);
        let _ = net::gui_move_take();
    }
    state(|s| *s = Transaction::default());
}

pub(super) fn packets(game: &mut Game<'_>, incoming: &[C]) {
    if incoming.iter().any(|p| matches!(p, C::PlayerPosition(_))) {
        state(|s| {
            if !s.packets.is_empty() {
                if own(game) {
                    s.closing = true;
                } else {
                    begin_close(s, 0);
                }
            }
        });
    }
    updates(game);
}

pub(super) fn incoming_before(game: &mut Game<'_>, packet: &C) {
    if !matches!(
        packet,
        C::OpenScreen(_)
            | C::MountScreenOpen(_)
            | C::ContainerClose(_)
            | C::Respawn(_)
            | C::Login(_)
            | C::Disconnect(_)
    ) {
        return;
    }
    if inventory_busy() {
        cancel(game, "the server replaced or closed the inventory context");
    } else if state(|s| s.base.is_some()) {
        updates(game);
        state(|s| s.base = None);
        net::gui_move_active(false);
    }
}

pub(super) fn pre_tick(game: &mut Game<'_>) -> bool {
    let stale = state(|s| s.session.is_some() && !same_session(game, s));
    if stale {
        let pending = inventory_busy();
        let same_connection = state(|s| {
            game.remote.as_ref().is_some_and(|r| {
                s.session
                    .as_ref()
                    .is_some_and(|old| Arc::ptr_eq(old, &r.session.counters))
            })
        });
        if same_connection {
            cancel(game, "the dimension or player life changed");
        }
        state(|s| *s = Transaction::default());
        net::gui_move_active(false);
        let _ = net::gui_move_take();
        if pending && !same_connection {
            sunset::say(
                game,
                "GUI Move: the connection ended; old inventory clicks were cancelled.",
            );
        }
        return false;
    }
    if inventory_busy() && game.remote_menu().0 != 0 {
        cancel(game, "a server container replaced the inventory");
        return false;
    }
    if inventory_busy()
        && game
            .player
            .as_ref()
            .is_some_and(|p| p.health.health() <= 0.0)
    {
        cancel(game, "the player died");
        return false;
    }
    updates(game);
    if state(|s| s.overflowed) {
        cancel(game, "the pending inventory batch exceeded its limit");
        return false;
    }
    let active = enabled(game);
    state(|s| {
        if !s.packets.is_empty() && (!active || !own(game)) {
            if own(game) {
                s.closing = true;
            } else {
                begin_close(s, 0);
            }
        }
        if s.packets.is_empty() && !s.closing {
            s.base = None;
            net::gui_move_active(false);
        }
    });
    let closing = state(|s| s.closing);
    if !closing {
        return false;
    }
    if state(|s| s.yielded) {
        let released = [
            winit::keyboard::KeyCode::KeyW,
            winit::keyboard::KeyCode::KeyA,
            winit::keyboard::KeyCode::KeyS,
            winit::keyboard::KeyCode::KeyD,
            winit::keyboard::KeyCode::Space,
            winit::keyboard::KeyCode::ShiftLeft,
            winit::keyboard::KeyCode::ControlLeft,
        ]
        .iter()
        .all(|key| !game.physical_keys.contains(key));
        let settled = game.riding.is_none()
            && game.player.as_ref().is_some_and(|p| {
                p.ground.on_ground
                    && !p.fluids.was_touching_water
                    && p.velocity.x.hypot(p.velocity.z) <= 0.003
            });
        if !released || !settled {
            return false;
        }
        state(|s| {
            s.yielded = false;
            s.stop_started = Some(game.ticks);
            s.quiet_move = None;
        });
    }
    state(|s| {
        s.stop_started.get_or_insert(game.ticks);
    });
    inventory::retry_idle(game);
    if let Some(player) = game.player.as_mut() {
        let _ = player.set_sprinting(false);
    }
    let ready = state(|s| {
        super::sunset_gui_move_policy::ready(
            game.ticks,
            s.quiet_move,
            super::sunset_combat_wire::sent_input(game),
            super::sunset_combat_wire::sent_sprinting(game),
            game.player
                .as_ref()
                .map_or(f64::INFINITY, |p| p.velocity.x.hypot(p.velocity.z)),
        )
    });
    // Fake Lag can still hold an old non-empty input behind the last observed idle one. Do not let a click's
    // action flush that input immediately before the click: Fake Lag yields to a closing GUI Move at its tick, and
    // readiness is judged on what actually went on the wire.
    if ready && game.riding.is_none() && !super::sunset_lag::pending() && !net::gui_move_pending() {
        send_queued(game);
    } else if state(|s| {
        s.stop_started
            .is_some_and(|start| game.ticks.saturating_sub(start) >= 40)
    }) {
        let report = state(|s| {
            s.yielded = true;
            let report = !s.wait_reported;
            s.wait_reported = true;
            report
        });
        if report {
            sunset::say(
                game,
                "GUI Move: waiting to stop; pending clicks retained. Release movement keys on dry ground to retry.",
            );
        }
        return false;
    }
    true
}

pub(super) fn frame(game: &mut Game<'_>) {
    if game.remote.is_none() {
        let _ = pre_tick(game);
    } else {
        updates(game);
    }
}

fn cancel(game: &mut Game<'_>, reason: &str) {
    let base = state(|s| {
        s.packets.clear();
        s.closing = false;
        s.quiet_move = None;
        s.overflowed = false;
        s.yielded = false;
        s.stop_started = None;
        s.wait_reported = false;
        s.base.take()
    });
    let updates = net::gui_move_take();
    if let Some(base) = base {
        inventory::restore_authority(game, &base, &updates);
    }
    net::gui_move_active(false);
    sunset::say(
        game,
        &format!(
            "GUI Move: {reason}; pending clicks were cancelled and server inventory restored."
        ),
    );
}

// Called before the native handler applies a new server menu's first slot/content packet.
pub(super) fn menu_state(game: &mut Game<'_>, container: i32) {
    if container != 0 && inventory_busy() {
        cancel(game, "a server container replaced the inventory");
    }
}

pub(super) fn suppress_shift(game: &Game<'_>) -> bool {
    if !game.native_window()
        || !game.native_on(sunset::ID)
        || sunset::gui_open()
        || game.recipe_search_focused()
    {
        return false;
    }
    let allowed = sunset::with(|s| {
        s.module("GUI Move").is_some_and(|m| {
            m.on && game.screen == Screen::Inventory
                && !matches!(game.remote_menu().1.as_str(), "anvil" | "minecraft:anvil")
                && (m.p("Mode") != "GrimAC" || game.remote_menu().0 == 0)
        })
    });
    allowed
        && [
            winit::keyboard::KeyCode::KeyW,
            winit::keyboard::KeyCode::KeyA,
            winit::keyboard::KeyCode::KeyS,
            winit::keyboard::KeyCode::KeyD,
        ]
        .iter()
        .any(|key| game.physical_keys.contains(key))
}

// GUI Move's stop is complete only after a quiet movement really left the client.
pub(super) fn ready(
    now: u64,
    quiet_move: Option<u64>,
    flags: u8,
    sprinting: bool,
    speed: f64,
) -> bool {
    quiet_move.is_some_and(|tick| tick < now)
        && flags & 0x7f == 0
        && !sprinting
        && speed.is_finite()
        && speed <= 0.003
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn waits_for_an_earlier_forwarded_idle_move_and_momentum() {
        assert!(!ready(10, None, 0, false, 0.0));
        assert!(!ready(10, Some(10), 0, false, 0.0));
        assert!(!ready(10, Some(9), 64, false, 0.0));
        assert!(!ready(10, Some(9), 0, true, 0.0));
        assert!(!ready(10, Some(9), 0, false, 0.1));
        assert!(ready(10, Some(9), 0, false, 0.0));
    }
}

// RF Click (R and F as the mouse buttons) and Kill Aura's and Trigger Bot's Shield (a shield kept up, lowered for each
// of your hits).
use super::sunset::{Category, Module, gui_open, with};
use super::sunset_util as util;
use super::{Game, Screen};
use super::sunset_autoblock::{Action, Legacy};
use horizon_protocol::packets::play::{self, Serverbound as S};
use std::sync::Mutex;
use winit::event::{ElementState, MouseButton, WindowEvent};
use winit::keyboard::PhysicalKey;

const RF: &str = "RF Click";

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new(RF, Category::Player, "R and F act as mouse buttons.")
            .text("Left key", "R")
            .text("Right key", "F"),
    ]
}

#[derive(Default)]
struct Hands {
    // RF Click: the key names for the left and right button (None: off), whether you are typing as of the last frame,
    // and which of the two is down as a button.
    keys: [Option<String>; 2],
    typing: bool,
    down: [bool; 2],
    physical: [bool; 2],
    // Shield: it holds use, and the tick it last lowered the shield for a hit.
    raised: bool,
    modern_owner: Option<&'static str>,
    lowered: Option<u64>,
    legacy: Legacy,
}

thread_local! { static OWNED_BLOCK_PACKET: std::cell::Cell<bool> = const { std::cell::Cell::new(false) }; }

pub(super) fn owned_block_packet() -> bool { OWNED_BLOCK_PACKET.with(std::cell::Cell::get) }

fn send_owned(game: &mut Game<'_>, packet: S) {
    if matches!(&packet, S::PlayerAction(a) if a.action == 6) {
        horizon_client::motion::sunset_motion::set_block_use_scale(None);
    }
    struct Scope(bool);
    impl Drop for Scope { fn drop(&mut self) { OWNED_BLOCK_PACKET.with(|f| f.set(self.0)); } }
    let _scope = Scope(OWNED_BLOCK_PACKET.with(|f| f.replace(true)));
    game.send(packet);
}

fn release_packet() -> S {
    // The current protocol's native release-use action, as used by Horizon's shield handling.
    S::PlayerAction(play::PlayerAction { action: 6, pos: [0; 3], direction: 0, sequence: 0 })
}

pub(super) fn scene_changed(game: &mut Game<'_>, same_scene: bool) {
    horizon_client::motion::sunset_motion::set_block_use_scale(None);
    if same_scene { stop_autoblock(game); }
    let raised = hands(|h| { h.legacy.stop(); h.lowered = None; h.modern_owner = None; std::mem::take(&mut h.raised) });
    if raised && !game.physical_buttons.contains(&MouseButton::Right) {
        // A new scene cannot receive the old scene's release packet; only let go of our synthetic button.
        super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, false);
    }
}

pub(super) fn stop_autoblock(game: &mut Game<'_>) {
    stop_owned_block(game, false);
}

pub(super) fn stop_kill_aura_block(game: &mut Game<'_>) {
    stop_owned_block(game, true);
}

fn stop_owned_block(game: &mut Game<'_>, kill_aura_only: bool) {
    horizon_client::motion::sunset_motion::set_block_use_scale(None);
    let (legacy, raised) = hands(|h| {
        let take_modern = !kill_aura_only || h.modern_owner == Some("Kill Aura");
        let raised = take_modern && std::mem::take(&mut h.raised);
        if take_modern { h.modern_owner = None; }
        (h.legacy.stop(), raised)
    });
    if legacy && super::sunset_combat_control::same_scene(game) { send_owned(game, release_packet()); }
    if raised && !game.physical_buttons.contains(&MouseButton::Right) {
        if game.using.is_some_and(|(slot, _)| slot == util::OFFHAND) {
            send_owned(game, release_packet());
            game.using = None;
        }
        super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, false);
    }
}

pub(super) fn autoblock_status() -> &'static str {
    hands(|h| if h.legacy.active() { "Legacy use requested (unconfirmed)" }
        else if h.raised { "Modern shield requested" } else { "idle" })
}

pub(super) fn legacy_using() -> bool { hands(|h| h.legacy.active()) }

// Called only for packets that passed the normal filters. A real attack must release our legacy use immediately
// before the attack packet, even if it came from Criticals, WTap, a native click or a different combat module.
// The returned cleanup packet is delivered by the shared send hook; no game call occurs under the Hands lock.
pub(super) fn before_outgoing(game: &Game<'_>, packet: &S) -> Option<S> {
    // A 1.8-order hit's swing goes before its attack: the release goes before the swing then.
    let strike_swing = matches!(packet, S::Punch(_)) && STRIKE_SWING.with(std::cell::Cell::get);
    if owned_block_packet()
        || !(strike_swing || matches!(packet, S::Attack(_) | S::SetCarriedItem(_) | S::UseItem(_) | S::PlayerAction(_)))
    {
        return None;
    }
    if !hands(|h| h.legacy.active()) { return None; }
    if !super::sunset_combat_control::same_scene(game) {
        hands(|h| { h.legacy.stop(); });
        return None;
    }
    let attack = strike_swing || matches!(packet, S::Attack(_)) || matches!(packet, S::PlayerAction(a) if a.action == 8);
    if attack {
        let delay = module("Kill Aura").map_or(1, |m| m.n("Legacy reblock delay") as u64);
        let released = hands(|h| h.legacy.attack(game.ticks, delay));
        if released { horizon_client::motion::sunset_motion::set_block_use_scale(None); }
        return released.then(release_packet);
    }
    if matches!(packet, S::SetCarriedItem(_) | S::UseItem(_)) || matches!(packet, S::PlayerAction(a) if a.action == 6) {
        // A native/foreign use or slot packet owns the replacement state; do not later release it as ours.
        hands(|h| h.legacy.interrupted(game.ticks));
        horizon_client::motion::sunset_motion::set_block_use_scale(None);
    }
    None
}

thread_local! {
    static STRIKE_SWING: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

// The swing of a hit sent the 1.8 way (swing, then attack): AutoBlock's release goes ahead of it, as of an attack.
pub(super) fn strike_swing(game: &mut Game<'_>) {
    STRIKE_SWING.with(|f| f.set(true));
    game.send(S::Punch(horizon_protocol::packets::Empty));
    STRIKE_SWING.with(|f| f.set(false));
}

static HANDS: Mutex<Option<Hands>> = Mutex::new(None);
static RF_EVENT: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

pub(super) fn rf_generated() -> bool { RF_EVENT.load(std::sync::atomic::Ordering::Relaxed) }

pub(super) fn release_rf(game: &mut Game<'_>) {
    let (down, physical) = hands(|h| (h.down, h.physical));
    for (i, button) in [MouseButton::Left, MouseButton::Right].into_iter().enumerate() {
        if down[i] && !physical[i] { game.physical_buttons.remove(&button); }
    }
}

pub(super) fn shutdown(game: &mut Game<'_>) {
    stop_autoblock(game);
    let down = hands(|h| {
        let down = [h.down[0], h.down[1] || h.raised];
        *h = Hands { physical: h.physical, ..Hands::default() };
        down
    });
    for (owned, button) in down.into_iter().zip([MouseButton::Left, MouseButton::Right]) {
        if owned && !game.physical_buttons.contains(&button) { let _ = super::remote::sunset_combat_remote::mouse(game, button, false); }
    }
}

fn hands<R>(f: impl FnOnce(&mut Hands) -> R) -> R {
    f(HANDS.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Hands::default))
}

fn module(name: &str) -> Option<Module> {
    with(|s| s.module(name).filter(|m| m.on).cloned())
}

// A text box or anything else that takes keys has them.
fn typing(game: &Game<'_>) -> bool {
    matches!(game.screen, Screen::Chat | Screen::CommandBlock | Screen::Options | Screen::WorldOptions)
        || game.sign_edit.is_some()
        || game.book.is_some()
        || game.title.is_some()
        || (game.screen == Screen::Creative && game.creative_screen.tab().search)
        || game.recipe_search_focused()
        || game.mod_browser_typing()
        || game.station_typing()
        || game.dialog_open()
        || gui_open()
}

// Every frame: RF Click's keys and whether you are typing.
pub(super) fn frame(game: &Game<'_>) {
    let keys = match module(RF).filter(|_| game.native_on(super::sunset::ID)) {
        Some(m) => [super::sunset::key_from_text(m.t("Left key")), super::sunset::key_from_text(m.t("Right key"))],
        None => [None, None],
    };
    let typing = typing(game);
    hands(|h| {
        h.keys = keys;
        h.typing = typing;
    });
}

// Focus lost: the window sends no releases for what was down, and the game lets go of its buttons by itself.
pub(super) fn rf_focus_lost() {
    hands(|h| h.down = [false; 2]);
}

// The window's key events, before anything sees them: RF Click's keys become mouse button presses and releases (a key
// repeat becomes nothing). A key let go is always the button let go, even if typing started meanwhile.
pub(super) fn rf_event(event: &mut WindowEvent) {
    RF_EVENT.store(false, std::sync::atomic::Ordering::Relaxed);
    if let WindowEvent::MouseInput { state, button, .. } = event {
        let i = match button { MouseButton::Left => Some(0), MouseButton::Right => Some(1), _ => None };
        if let Some(i) = i { hands(|h| h.physical[i] = *state == ElementState::Pressed); }
    }
    if !super::sunset::running() { return; }
    let WindowEvent::KeyboardInput { device_id, event: key, .. } = event else {
        return;
    };
    let PhysicalKey::Code(code) = key.physical_key else {
        return;
    };
    let Some(name) = horizon_client::keybinds::key_name(code) else {
        return;
    };
    let (state, repeat, device_id) = (key.state, key.repeat, *device_id);
    let button = hands(|h| {
        let i = h.keys.iter().position(|k| k.as_deref() == Some(name)).or_else(|| {
            // Turned off while held: its release still lets go.
            (state == ElementState::Released).then(|| h.down.iter().position(|&d| d)).flatten()
        })?;
        match state {
            ElementState::Pressed if h.down[i] => Some(i),
            ElementState::Pressed if h.typing || repeat => None,
            ElementState::Pressed => {
                h.down[i] = true;
                Some(i)
            }
            ElementState::Released if h.down[i] => {
                h.down[i] = false;
                Some(i)
            }
            ElementState::Released => None,
        }
    });
    let Some(i) = button else {
        return;
    };
    RF_EVENT.store(true, std::sync::atomic::Ordering::Relaxed);
    *event = if repeat {
        WindowEvent::HoveredFileCancelled
    } else {
        WindowEvent::MouseInput { device_id, state, button: if i == 0 { MouseButton::Left } else { MouseButton::Right } }
    };
}

// Shield has the shield up (Kill Aura and Trigger Bot hit through it: it comes down for the hit).
pub(super) fn shielding(game: &Game<'_>) -> bool {
    hands(|h| h.raised) && game.using.is_some_and(|(slot, _)| slot == util::OFFHAND)
}

fn offhand_shield(game: &Game<'_>) -> bool {
    game.offhand.as_ref().and_then(|s| game.res.items().get(&s.item)).is_some_and(|i| i.blocks_attacks.is_some())
}

fn wanted(game: &Game<'_>, m: &Module) -> bool {
    let held = game.held().map(|s| util::short(&s.item));
    let weapon = held.is_some_and(|h| h.ends_with("_sword") || h.ends_with("_axe") || h == "mace");
    // Anything else in hand with a use of its own (food, blocks, bows) would be used instead.
    let free = held.is_none() || weapon;
    let own = game.remote.as_ref().map(|r| r.entity_id as u32);
    let near = || {
        let Some(eye) = game.eye_position() else {
            return false;
        };
        game.mobs.iter().any(|mob| {
            mob.alive()
                && !mob.removed
                && Some(mob.id) != own
                && (mob.kind.id == "minecraft:player" || mob.hostile() || mob.kind.category == "monster")
                && util::dist(eye, [mob.position.x, mob.position.y + 1.0, mob.position.z]) <= m.n("Shield range")
        })
    };
    game.native_playing()
        && !game.spectator()
        && game.player.as_ref().is_some_and(|p| p.health.health() > 0.0)
        && super::sunset_combat_control::available(m.name)
        && game.screen == Screen::Playing
        && !gui_open()
        && offhand_shield(game)
        && free
        && (weapon || !m.b("Shield only with a weapon"))
        && (!m.b("Shield only near a target") || near())
}

// Before the tick's hits (Kill Aura's and Trigger Bot's queued ones, your click): the shield comes down, so the hit
// goes in the same tick.
pub(super) fn before_hits(game: &mut Game<'_>, hits: bool) {
    legacy_pre_tick(game, hits || game.attack_clicks > 0);
    if !shielding(game) || !(hits || game.attack_clicks > 0) {
        return;
    }
    send_owned(game, release_packet());
    game.using = None;
    let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, false);
    hands(|h| {
        h.raised = false;
        h.modern_owner = None;
        h.lowered = Some(game.ticks);
    });
}

fn legacy_pre_tick(game: &mut Game<'_>, hits: bool) {
    if !super::sunset_combat_control::same_scene(game) {
        hands(|h| { h.legacy.stop(); });
        return;
    }
    let m = module("Kill Aura").filter(|m| m.p("AutoBlock") == "Legacy" && game.native_on(super::sunset::ID));
    let desired = m.as_ref().filter(|m| {
        game.native_playing() && game.screen == Screen::Playing && !gui_open() && game.remote.is_some()
            && !game.spectator() && game.player.as_ref().is_some_and(|p| p.health.health() > 0.0)
            && game.using.is_none() && !game.right && !game.physical_buttons.contains(&MouseButton::Right)
            && game.held().is_some_and(|s| s.item.ends_with("_sword"))
            && super::sunset_combat_control::available("Kill Aura")
            && !with(|s| s.is_on("Blink")) && !super::sunset_lag::pending()
            && super::sunset_aura_timing::version(m.p("Combat version"), game.main_hand_attack_speed()).0
                == super::sunset_aura_timing::Version::Legacy
            && super::sunset_aura::target_id().is_some_and(|id| game.mobs.iter().any(|mob| mob.id == id && mob.alive() && !mob.removed))
    }).map(|_| game.selected);
    let delay = m.as_ref().map_or(1, |m| m.n("Legacy reblock delay") as u64);
    if hits && hands(|h| h.legacy.attack(game.ticks, delay)) { send_owned(game, release_packet()); }
    let can_start = !hits && !super::sunset::strike_waiting() && super::remote::sunset_combat_remote::carried_synced(game);
    match hands(|h| h.legacy.update(game.ticks, desired, can_start)) {
        Action::None => {}
        Action::Release => send_owned(game, release_packet()),
        Action::Block => {
            let sequence = util::sequence(game);
            let look = super::sunset::last_look().unwrap_or((game.yaw, game.pitch));
            let yaw = super::sunset::wire_yaw(game, look.0);
            send_owned(game, S::UseItem(play::UseItem { hand: 0, sequence, yaw, pitch: look.1 }));
        }
    }
    let scale = legacy_using().then(|| {
        // GrimAC's modern item-use method has not been established for translated sword use; keep normal slowdown.
        let no_slow = with(|s| s.module("No Slow").filter(|m| m.on && m.p("Mode") != "GrimAC")
            .map(|m| [m.n("Ground %"), m.n("Air %")]));
        super::sunset_movement::legacy_use_factor(no_slow, game.player.as_ref().is_some_and(|p| p.ground.on_ground))
    });
    horizon_client::motion::sunset_motion::set_block_use_scale(scale);
}

pub(super) fn tick(game: &mut Game<'_>) {
    // Kill Aura's Shield, else Trigger Bot's: the first of them on with it.
    let aura = module("Kill Aura");
    let legacy_selected = aura.as_ref().is_some_and(|m| m.p("AutoBlock") == "Legacy");
    let m = aura.filter(|m| m.p("AutoBlock") == "Modern")
        .or_else(|| (!legacy_selected).then(|| module("Trigger Bot").filter(|m| m.b("Shield"))).flatten())
        .filter(|_| game.native_on(super::sunset::ID));
    let want = m.as_ref().is_some_and(|m| wanted(game, m));
    let raised = hands(|h| h.raised);
    if !want {
        if raised {
            if game.using.is_some_and(|(slot, _)| slot == util::OFFHAND) && !game.physical_buttons.contains(&MouseButton::Right) {
                send_owned(game, release_packet());
                game.using = None;
            }
            hands(|h| { h.raised = false; h.modern_owner = None; });
            if !game.physical_buttons.contains(&MouseButton::Right) {
                let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, false);
            }
        }
        return;
    }
    let delay = m.as_ref().map_or(0, |m| m.n("Shield re-raise delay") as u64);
    if raised { hands(|h| h.modern_owner = m.as_ref().map(|m| m.name)); }
    let rested = hands(|h| h.lowered.is_none_or(|t| game.ticks >= t.saturating_add(delay)));
    if !raised && rested && game.using.is_none() && !super::sunset::strike_waiting() {
        let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, true);
        hands(|h| { h.raised = true; h.modern_owner = m.as_ref().map(|m| m.name); });
    }
}

// HUD's Armor HUD (with Compact style), Compass, Shield status, Item durability (on every damageable item's icon, and remaining/max in its tooltip), the
// settings that change the game's own bars (Mount HUD, Food preview, Saturation, Exhaustion; drawn by hunger_flags.rs),
// and the layout editor: with the chat (or the menu) open, every framed element moves by dragging and goes back to its
// Default place with a right click — Coordinates, FPS, Speed, Facing and Totems (each on its own), the Compass, the
// Armor HUD, Shield status, the watermark, the module list, the Target HUD, the server's scoreboard, other modules'
// (Scaffold's block counter, the Murderer list, Auto Spear's damage indicator, Radar) and Horizon's own HUD widgets.
use super::Game;
use super::sunset::{Module, Shape};
use horizon_client::extras::Corner;
use horizon_client::extras_hud::Corners;
use horizon_client::hud::HudBatch;
use horizon_client::hud_layout::sunset_hunger::{BARS, Bars};
use horizon_client::items::ItemStack;
use horizon_client::pvp_hud::{self, WidgetId};
use std::cell::Cell;
use std::ops::ControlFlow;
use std::sync::Mutex;
use std::sync::atomic::{AtomicBool, AtomicU8, Ordering::Relaxed};

// Item durability: 0 off, 1 the number left, 2 the percent left; and the tooltip line.
static DURABILITY: AtomicU8 = AtomicU8::new(0);
static TOOLTIP: AtomicBool = AtomicBool::new(false);
// The elements that can be dragged: where each was drawn last frame (x, y, width, height) and the screen it was on.
static PLACED: Mutex<Vec<Placed>> = Mutex::new(Vec::new());
// The left button was down last frame, while the chat was open; and the right one.
static CHAT_PRESSED: AtomicBool = AtomicBool::new(false);
static CHAT_RIGHT: AtomicBool = AtomicBool::new(false);
// One of Horizon's widgets was moved and Horizon's options are not saved yet (they are when the drag ends).
static WIDGET_MOVED: AtomicBool = AtomicBool::new(false);

type Placed = (&'static str, [f32; 4], [f32; 2]);
// Shield status: the tick the shield's cooldown was first seen, and how much of it was left then.
static SHIELD_SINCE: Mutex<Option<(f32, f32)>> = Mutex::new(None);

thread_local! {
    // An icon drawn without Item durability's number (Sunset's own icons, and the icon under the number).
    static PLAIN: Cell<bool> = const { Cell::new(false) };
}

// A slot box of the hotbar's sprite: one slot and its frame.
const SLOT: f32 = 20.0;

// Each tick: the settings the game's own drawing reads.
pub(super) fn tick(game: &Game<'_>, mods: &[Module], shown: bool) {
    let hud = mods.iter().find(|m| m.name == "HUD" && m.on).filter(|_| shown);
    let on = |name: &str| hud.is_some_and(|m| m.b(name));
    let durability = if !on("Item durability") {
        0
    } else if hud.is_some_and(|m| m.p("Durability format") == "Percent") {
        2
    } else {
        1
    };
    DURABILITY.store(durability, Relaxed);
    TOOLTIP.store(on("Item durability") && on("Durability tooltip"), Relaxed);
    let mut bars = Bars::default();
    if let Some(p) = game.player.as_ref() {
        let food = &p.health.food;
        bars.mount = on("Mount HUD");
        bars.mount_xp = bars.mount && game.riding.is_some() && !game.mount_jumping() && !game.waypoints.has_waypoints();
        // The air bubbles take the row over the food while they show.
        let bubbles = p.air < 300 || p.is_eye_in_fluid(horizon_client::motion::WATER);
        bars.raise = if bubbles { 20 } else { 10 };
        bars.saturation = on("Saturation");
        bars.exhaustion = on("Exhaustion").then_some(food.exhaustion);
        bars.preview = [game.held(), game.offhand.as_ref()]
            .into_iter()
            .flatten()
            .find_map(|s| game.res.items().get(&s.item)?.food)
            .filter(|_| on("Food preview"))
            .map(|(nutrition, saturation)| {
                let after = (food.food + nutrition as i32).min(20);
                (after, (food.saturation + saturation).min(after as f32))
            });
    }
    *BARS.lock().unwrap_or_else(|e| e.into_inner()) = bars;
}

// What is left of `max`, from 1 (all of it) to 0.
fn left_fraction(damage: u32, max: u32) -> f32 {
    (max.saturating_sub(damage) as f32 / max.max(1) as f32).clamp(0.0, 1.0)
}

// The game's durability bar colour: green when whole, through yellow, to red as it wears.
pub(super) fn wear_rgb(fraction: f32) -> u32 {
    horizon_client::hud_layout::hsv_to_argb(fraction / 3.0, 1.0, 1.0, 0) & 0x00FF_FFFF
}

// Percent left rounds as follows: 1 for the last point, never 0 while it holds.
fn percent(damage: u32, max: u32) -> u32 {
    let left = max.saturating_sub(damage);
    if left == 0 { 0 } else { ((left * 100).div_ceil(max)).max(1) }
}

fn max_damage(game: &Game<'_>, stack: &ItemStack) -> Option<u32> {
    game.res.items().get(&stack.item).map(|i| i.max_damage).filter(|m| *m > 0)
}

// An icon drawn by Sunset itself: no Item durability number on it.
pub(super) fn plain<R>(f: impl FnOnce() -> R) -> R {
    PLAIN.with(|p| p.set(true));
    let r = f();
    PLAIN.with(|p| p.set(false));
    r
}

// Item durability: any damageable item's icon (hotbar, inventories, the stack on the pointer) gets what it has left,
// small, in its top left corner, in the colour of its bar.
pub(super) fn item_model(game: &Game<'_>, batch: &mut HudBatch, stack: &ItemStack, x: f32, y: f32) -> ControlFlow<()> {
    let mode = DURABILITY.load(Relaxed);
    if mode == 0 || PLAIN.with(Cell::get) {
        return ControlFlow::Continue(());
    }
    let Some(max) = max_damage(game, stack) else {
        return ControlFlow::Continue(());
    };
    plain(|| game.draw_item_model(batch, stack, x, y));
    let text = if mode == 2 { format!("{}%", percent(stack.damage, max)) } else { max.saturating_sub(stack.damage).to_string() };
    let start = batch.vertices.len();
    game.native_text(batch, &text, [x, y], wear_rgb(left_fraction(stack.damage, max)), true);
    batch.scale_since(start, x, y, 0.5, 0.5);
    ControlFlow::Break(())
}

thread_local! {
    // The tooltip being drawn again with the durability line.
    static TOOLTIP_AGAIN: Cell<bool> = const { Cell::new(false) };
}

// Item durability's tooltip line, under the name: remaining / max (the game's own line shows instead with advanced
// tooltips on a worn item). The tooltip is drawn again with the line, and the first one left out.
pub(super) fn tooltip(
    game: &mut Game<'_>,
    batch: &mut HudBatch,
    stack: &ItemStack,
    creative: bool,
    [x, y]: [f32; 2],
    after_name: &[(horizon_client::text::Text, u32)],
) -> ControlFlow<()> {
    if TOOLTIP_AGAIN.with(Cell::get) || !TOOLTIP.load(Relaxed) || stack.damage > 0 && game.settings.file.bool("advancedItemTooltips") {
        return ControlFlow::Continue(());
    }
    let Some(max) = max_damage(game, stack) else {
        return ControlFlow::Continue(());
    };
    let [_, r, g, b] = wear_rgb(left_fraction(stack.damage, max)).to_be_bytes();
    let text = format!("Durability: {} / {max}", max.saturating_sub(stack.damage));
    let mut lines = after_name.to_vec();
    lines.push((horizon_client::text::Text::literal(text), horizon_client::hud::rgba(r, g, b, 255)));
    TOOLTIP_AGAIN.with(|c| c.set(true));
    game.draw_stack_tooltip_with(batch, stack, creative, x, y, lines);
    TOOLTIP_AGAIN.with(|c| c.set(false));
    ControlFlow::Break(())
}

fn placed<R>(f: impl FnOnce(&mut Vec<Placed>) -> R) -> R {
    f(&mut PLACED.lock().unwrap_or_else(|e| e.into_inner()))
}

// A new frame of the HUD: what it draws is placed again.
pub(super) fn clear_placed() {
    placed(Vec::clear);
}

// `name` was drawn at `rect` on a screen `w` by `h`.
pub(super) fn place(name: &'static str, rect: [f32; 4], w: f32, h: f32) {
    placed(|p| {
        p.retain(|e| e.0 != name);
        p.push((name, rect, [w, h]));
    });
}

// An element's position as fractions of the screen, from where its top left corner is dragged to.
pub(super) fn drag_to(name: &str, x: f32, y: f32) -> Option<(f64, f64)> {
    let (_, [_, _, w, h], [sw, sh]) = placed(|p| p.iter().find(|e| e.0 == name).copied())?;
    Some(fractions([x, y], [w, h], [sw, sh]))
}

fn fractions(at: [f32; 2], size: [f32; 2], screen: [f32; 2]) -> (f64, f64) {
    let fx = at[0].clamp(0.0, (screen[0] - size[0]).max(0.0)) / screen[0].max(1.0);
    let fy = at[1].clamp(0.0, (screen[1] - size[1]).max(0.0)) / screen[1].max(1.0);
    (f64::from(fx), f64::from(fy))
}

// A press on an element (the chat or the menu open): which, and where in it the pointer took it.
pub(super) fn grab(at: (f32, f32)) -> Option<(&'static str, f32, f32)> {
    placed(|p| {
        p.iter()
            .rev()
            .find(|(_, [x, y, w, h], _)| at.0 >= *x && at.0 < x + w && at.1 >= *y && at.1 < y + h)
            .map(|(name, [x, y, _, _], _)| (*name, at.0 - x, at.1 - y))
    })
}

// What the chat's layout editor does this frame with a drag.
pub(super) enum ChatDrag {
    // A press took an element, where in it.
    Start(&'static str, f32, f32),
    // The button came up.
    End,
    // A right click on an element: back to its Default place.
    Reset(&'static str),
}

// The layout editor with the chat open: a frame round each element, a press on one takes it, its release ends the drag;
// a right click on one sends it back.
pub(super) fn chat_layout(game: &Game<'_>, dragging: Option<&'static str>, out: &mut Vec<Shape>) -> Option<ChatDrag> {
    let down = game.physical_buttons.contains(&winit::event::MouseButton::Left);
    let was = CHAT_PRESSED.swap(down, Relaxed);
    let right = game.physical_buttons.contains(&winit::event::MouseButton::Right);
    let right_was = CHAT_RIGHT.swap(right, Relaxed);
    for (name, [x, y, w, h], _) in placed(|p| p.clone()) {
        let colour = if dragging == Some(name) { 0xC0FF_FFFF } else { 0x60FF_FFFF };
        out.push(Shape::Fill([x - 1.0, y - 1.0, w + 2.0, 1.0], colour));
        out.push(Shape::Fill([x - 1.0, y + h, w + 2.0, 1.0], colour));
        out.push(Shape::Fill([x - 1.0, y, 1.0, h], colour));
        out.push(Shape::Fill([x + w, y, 1.0, h], colour));
    }
    match dragging {
        Some(_) if !down => Some(ChatDrag::End),
        None if down && !was => grab(game.cursor).map(|(name, dx, dy)| ChatDrag::Start(name, dx, dy)),
        None if right && !right_was => grab(game.cursor).map(|(name, _, _)| ChatDrag::Reset(name)),
        _ => None,
    }
}

// The chat closed: the next press there starts afresh.
pub(super) fn chat_closed() {
    CHAT_PRESSED.store(false, Relaxed);
    CHAT_RIGHT.store(false, Relaxed);
}

// Horizon's own HUD widgets (its PvP & HUD page: FPS, CPS, ping and the rest), framed and dragged with Sunset's: each by
// a name of its own here. Their places are Horizon's (its layout, in its options), as its own HUD editor sets them.
const WIDGETS: [(WidgetId, &str); 13] = [
    (WidgetId::Armour, "Horizon armor"),
    (WidgetId::Effects, "Horizon effects"),
    (WidgetId::Held, "Horizon held item"),
    (WidgetId::Ping, "Horizon ping"),
    (WidgetId::Coords, "Horizon coordinates"),
    (WidgetId::Server, "Horizon server"),
    (WidgetId::Combo, "Horizon combo"),
    (WidgetId::Fps, "Horizon FPS"),
    (WidgetId::Cps, "Horizon CPS"),
    (WidgetId::Keys, "Horizon keystrokes"),
    (WidgetId::Clock, "Horizon clock"),
    (WidgetId::Reach, "Horizon reach"),
    (WidgetId::Speed, "Horizon speed"),
];

// The Horizon widget an element's name is, if it is one.
pub(super) fn widget(name: &str) -> Option<WidgetId> {
    WIDGETS.iter().find(|w| w.1 == name).map(|w| w.0)
}

// The widgets Horizon drew this frame (before the mods' HUD), as elements the editor can take.
pub(super) fn place_widgets(game: &Game<'_>, w: f32, h: f32) {
    for &(id, rect) in &game.pvp.boxes {
        if let Some(&(_, name)) = WIDGETS.iter().find(|x| x.0 == id) {
            place(name, rect, w, h);
        }
    }
}

// A widget dragged with its top left corner to (x, y): its place in Horizon's layout, kept on screen.
pub(super) fn move_widget(game: &mut Game<'_>, id: WidgetId, x: f32, y: f32) {
    let Some(&(_, [_, _, bw, bh])) = game.pvp.boxes.iter().find(|b| b.0 == id) else {
        return;
    };
    let at = pvp_hud::to_fractions((x, y), (bw, bh), game.gui_size());
    let place = game.settings.extras.pvp.layout.get_mut(id);
    if place.at != Some(at) {
        place.at = Some(at);
        WIDGET_MOVED.store(true, Relaxed);
    }
}

// A right click on a widget: back to its corner, at the size it has.
pub(super) fn reset_widget(game: &mut Game<'_>, id: WidgetId) {
    game.settings.extras.pvp.layout.get_mut(id).at = None;
    WIDGET_MOVED.store(true, Relaxed);
}

// No widget is being dragged: Horizon's options are saved if one moved (as its own editor does on the release).
pub(super) fn settle_widgets(game: &Game<'_>) {
    if WIDGET_MOVED.swap(false, Relaxed) {
        game.settings.save(&Game::options_path());
    }
}

// Move a shape by (dx, dy): every coordinate it carries, so a whole element drawn into a run of shapes slides together
// (its clip rectangle and all).
pub(super) fn shift(shape: &mut Shape, dx: f32, dy: f32) {
    match shape {
        Shape::Fill(r, _) | Shape::Round(r, _, _) | Shape::Corners(r, _, _, _) | Shape::Sprite(_, r, _)
        | Shape::Squircle(r, _, _) | Shape::ClipEnd(r) => {
            r[0] += dx;
            r[1] += dy;
        }
        Shape::Quad(corners, _) => {
            for c in corners {
                c[0] += dx;
                c[1] += dy;
            }
        }
        Shape::Text(_, p, _) | Shape::Head(_, p, _) | Shape::Item(_, p, _) | Shape::Scaled(_, p, _, _)
        | Shape::Face(_, p, _) => {
            p[0] += dx;
            p[1] += dy;
        }
        Shape::ClipStart => {}
    }
}

// The rectangle a run of shapes covers: what it filled, its icons and its text (a line 9 high, as the font draws it).
// None if it drew nothing with a place.
pub(super) fn bounds(game: &Game<'_>, shapes: &[Shape]) -> Option<[f32; 4]> {
    let (mut x0, mut y0, mut x1, mut y1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
    for s in shapes {
        let r = match s {
            Shape::Fill(r, _) | Shape::Round(r, _, _) | Shape::Corners(r, _, _, _) | Shape::Sprite(_, r, _)
            | Shape::Squircle(r, _, _) => *r,
            Shape::Quad(c, _) => {
                for p in c {
                    x0 = x0.min(p[0]);
                    y0 = y0.min(p[1]);
                    x1 = x1.max(p[0]);
                    y1 = y1.max(p[1]);
                }
                continue;
            }
            Shape::Text(t, p, _) | Shape::Head(t, p, _) => [p[0], p[1], game.native_text_width(t), 9.0],
            Shape::Scaled(t, p, _, k) => [p[0], p[1], game.native_text_width(t) * k, 9.0 * k],
            Shape::Item(_, p, size) | Shape::Face(_, p, size) => [p[0], p[1], *size, *size],
            Shape::ClipStart | Shape::ClipEnd(_) => continue,
        };
        x0 = x0.min(r[0]);
        y0 = y0.min(r[1]);
        x1 = x1.max(r[0] + r[2]);
        y1 = y1.max(r[1] + r[3]);
    }
    (x0 <= x1).then(|| [x0, y0, x1 - x0, y1 - y0])
}

// The bands the game's status effect icons take at the top right, when it draws them (`Hud.extractEffects`: 24 pixel
// icons 25 apart from the right edge, the beneficial row at y 1 and the harmful one at 26): each as wide as its icons
// and 25 high, as Horizon's top right corner reserves them. None while Horizon's effects widget takes their place, nor
// in an inventory that lists its own effects (wide enough for that, as `EffectsInInventory.canSeeEffects`).
fn effect_bands(game: &Game<'_>, w: f32) -> [Option<[f32; 4]>; 2] {
    use super::Screen;
    let own_list = match game.screen {
        Screen::Inventory => game.container.is_none() && game.craft_size == 2 && (w - 176.0) / 2.0 - 2.0 >= 32.0,
        Screen::Creative => (w - horizon_client::creative::Creative::WIDTH as f32) / 2.0 - 2.0 >= 32.0,
        _ => false,
    };
    if own_list || game.settings.extras.pvp.hud.effects {
        return [None, None];
    }
    let (mut beneficial, mut harmful) = (0.0, 0.0);
    for e in &game.potions.effects.list {
        let icon = horizon_client_render::hud_overlays::EffectIcon::from(e);
        if !icon.show_icon {
            continue;
        }
        if icon.beneficial {
            beneficial += 25.0;
        } else {
            harmful += 25.0;
        }
    }
    let band = |width: f32, top: f32| (width > 0.0).then_some([w - width, top, width, 25.0]);
    [band(beneficial, 0.0), band(harmful, 25.0)]
}

// The module list's top left for a box at `rect`: where it is, or just under the effect icons it would cover (2 below
// their band, as Horizon's corner puts what follows them), wherever it was placed or dragged to.
pub(super) fn below_effects(game: &Game<'_>, [x, y, bw, bh]: [f32; 4], w: f32, h: f32) -> (f32, f32) {
    let mut y = y;
    for [ex, ey, ew, eh] in effect_bands(game, w).into_iter().flatten() {
        if x < ex + ew && x + bw > ex && y < ey + eh && y + bh > ey {
            y = ey + eh + 2.0;
        }
    }
    (x, y.min((h - bh).max(0.0)))
}

// An independent element (not stacked in a corner) just drawn into `shapes[from..]` by module `m`: registered so the
// editor can grab it, and, when its `name position` is Custom, slid to where it was dragged. Its box is what it drew.
pub(super) fn editable(game: &Game<'_>, shapes: &mut Vec<Shape>, from: usize, m: &Module, name: &'static str, w: f32, h: f32) {
    let Some([bx, by, bw, bh]) = bounds(game, &shapes[from..]) else {
        return;
    };
    let (x, y) = if m.p(&format!("{name} position")) == "Custom" {
        (
            (m.n(&format!("{name} x")) as f32 * w).clamp(0.0, (w - bw).max(0.0)),
            (m.n(&format!("{name} y")) as f32 * h).clamp(0.0, (h - bh).max(0.0)),
        )
    } else {
        (bx, by)
    };
    let (dx, dy) = (x - bx, y - by);
    if dx != 0.0 || dy != 0.0 {
        for s in &mut shapes[from..] {
            shift(s, dx, dy);
        }
    }
    place(name, [x, y, bw, bh], w, h);
}

// Compass: 140 degrees of headings round the one you face, a tick every 5 degrees, a label
// every 15 (N, NE, E... at the eighths), and your heading over the middle.
fn compass(game: &Game<'_>, hud: &Module, w: f32, h: f32, out: &mut Vec<Shape>) {
    const WIDTH: f32 = 180.0;
    const HEIGHT: f32 = 26.0;
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let (x0, y0) = if hud.p("Compass position") == "Custom" {
        (
            (hud.n("Compass x") as f32 * w).clamp(0.0, (w - WIDTH).max(0.0)),
            (hud.n("Compass y") as f32 * h).clamp(0.0, (h - HEIGHT).max(0.0)),
        )
    } else {
        ((w - WIDTH) / 2.0, 2.0)
    };
    place("Compass", [x0, y0, WIDTH, HEIGHT], w, h);
    out.push(Shape::Fill([x0, y0 + 9.0, WIDTH, HEIGHT - 9.0], 0x5000_0000));
    let heading = heading(p.yaw);
    let middle = y0 + 9.0 + (HEIGHT - 9.0) / 2.0;
    for (offset, degree) in ticks(heading) {
        let x = x0 + offset * WIDTH;
        let major = degree % 45 == 0;
        let (top, bottom) = if major { (middle - 7.0, middle - 1.0) } else { (middle - 5.0, middle - 3.0) };
        out.push(Shape::Fill([x, top, 1.0, bottom - top], if major { 0xD0FF_FFFF } else { 0x90FF_FFFF }));
        if degree % 15 == 0 {
            let text = if major { ["N", "NE", "E", "SE", "S", "SW", "W", "NW"][(degree / 45) as usize].to_owned() } else { degree.to_string() };
            let (scale, colour) = if major { (0.8, 0xFFFFFF) } else { (0.6, 0xAAAAAA) };
            let tx = x - game.native_text_width(&text) * scale / 2.0;
            out.push(Shape::Scaled(text, [tx, middle + 1.0], colour, scale));
        }
    }
    let mid = x0 + WIDTH / 2.0;
    out.push(Shape::Fill([mid - 0.5, y0 + 9.0, 1.0, HEIGHT - 9.0], 0xFFE5_2E33));
    let text = (heading as i32).rem_euclid(360).to_string();
    let tx = mid - game.native_text_width(&text) * 0.4;
    out.push(Shape::Scaled(text, [tx, y0], 0xE6E6E6, 0.8));
}

// Your heading from north (0) round through east (90), as a compass reads it: the game's yaw is 0 facing south.
fn heading(yaw: f32) -> f32 {
    (yaw + 180.0).rem_euclid(360.0)
}

// The compass's ticks for `heading`: each 5 degrees within 70 either side, as how far across the strip it is (0 to 1)
// and its heading (0 to 355).
fn ticks(heading: f32) -> Vec<(f32, i32)> {
    let from = heading - 70.0;
    let first = (from / 5.0).ceil() as i32 * 5;
    (0..)
        .map(|i| first + i * 5)
        .take_while(|&d| d as f32 <= heading + 70.0)
        .map(|d| ((d as f32 - from) / 140.0, d.rem_euclid(360)))
        .collect()
}

// One piece the Armor HUD shows: its item, damage and maximum (0: none), or an empty slot.
type Piece = Option<(std::sync::Arc<str>, u32, u32)>;

pub(super) fn draw(game: &Game<'_>, hud: &Module, w: f32, h: f32, corners: &mut Corners, out: &mut Vec<Shape>) {
    if hud.b("Compass") {
        compass(game, hud, w, h, out);
    }
    if hud.b("Shield status") {
        let from = out.len();
        shield(game, w, h, out);
        editable(game, out, from, hud, "Shield status", w, h);
    } else {
        *SHIELD_SINCE.lock().unwrap_or_else(|e| e.into_inner()) = None;
    }
    if !hud.b("Armor HUD") || game.player.is_none() || game.spectator() {
        return;
    }
    let piece = |s: Option<&ItemStack>| -> Piece {
        s.map(|s| (std::sync::Arc::clone(&s.item), s.damage, max_damage(game, s).unwrap_or(0)))
    };
    let mut pieces: Vec<Piece> = game.armor.iter().map(|s| piece(s.as_ref())).collect();
    if hud.b("Armor HUD hands") {
        pieces.push(piece(game.held()));
        pieces.push(piece(game.offhand.as_ref()));
    }
    if hud.b("Armor HUD hide empty") {
        pieces.retain(Option::is_some);
    }
    if pieces.iter().all(Option::is_none) {
        return;
    }
    let vertical = hud.p("Armor HUD layout") == "Vertical";
    let compact = hud.p("Armor HUD style") == "Compact";
    let shows = hud.p("Armor HUD durability");
    let (bar, words) = (shows == "Bar" || shows == "Bar and percent", shows != "Bar");
    let label = |p: &Piece| -> Option<String> {
        let (_, damage, max) = p.as_ref().filter(|p| words && p.2 > 0)?;
        Some(if shows == "Number" { max.saturating_sub(*damage).to_string() } else { format!("{}%", percent(*damage, *max)) })
    };
    // Each piece's size: a slot box, or (Compact) the icon and its words beside it.
    let sizes: Vec<[f32; 2]> = pieces
        .iter()
        .map(|p| if compact { [16.0 + label(p).map_or(0.0, |t| 3.0 + game.native_text_width(&t)), 16.0] } else { [SLOT + 2.0, SLOT + 2.0] })
        .collect();
    let gap = if compact { 4.0 } else { 0.0 };
    // Boxes in a row share their frames, as on the hotbar.
    let step = |s: [f32; 2]| if vertical { s[1] + gap } else if compact { s[0] + gap } else { SLOT };
    let along: f32 = sizes.iter().map(|s| step(*s)).sum::<f32>() - gap + if vertical || compact { 0.0 } else { 2.0 };
    let across = sizes.iter().map(|s| if vertical { s[0] } else { s[1] }).fold(0.0, f32::max);
    let (bw, bh) = if vertical { (across, along) } else { (along, across) };
    let (x0, y0) = match hud.p("Armor HUD position") {
        "Top left" => corners.place(Corner::TopLeft, bw, bh),
        "Top right" => corners.place(Corner::TopRight, bw, bh),
        "Bottom left" => corners.place(Corner::BottomLeft, bw, bh),
        "Bottom right" => corners.place(Corner::BottomRight, bw, bh),
        "Custom" => (
            (hud.n("Armor HUD x") as f32 * w).clamp(0.0, (w - bw).max(0.0)),
            (hud.n("Armor HUD y") as f32 * h).clamp(0.0, (h - bh).max(0.0)),
        ),
        // Beside the hotbar, on the side the off hand slot isn't.
        _ if game.settings.main_hand_left => (w / 2.0 - 91.0 - 6.0 - bw, h - bh),
        _ => (w / 2.0 + 91.0 + 6.0, h - bh),
    };
    place("Armor HUD", [x0, y0, bw, bh], w, h);
    if !compact && !vertical {
        frame(out, x0, y0, pieces.len());
    }
    let mut at = 0.0;
    for (p, size) in pieces.iter().zip(&sizes) {
        let (x, y) = if vertical { (x0, y0 + at) } else { (x0 + at, y0) };
        at += step(*size);
        if !compact && vertical {
            frame(out, x, y, 1);
        }
        let (ix, iy) = if compact { (x, y) } else { (x + 3.0, y + 3.0) };
        let Some((item, damage, max)) = p else {
            continue;
        };
        out.push(Shape::Item(std::sync::Arc::clone(item), [ix, iy], 16.0));
        if *max == 0 {
            continue;
        }
        let fraction = left_fraction(*damage, *max);
        let rgb = wear_rgb(fraction);
        if bar {
            out.push(Shape::Fill([ix + 2.0, iy + 13.0, 13.0, 2.0], 0xFF00_0000));
            out.push(Shape::Fill([ix + 2.0, iy + 13.0, (13.0 * fraction).round(), 1.0], 0xFF00_0000 | rgb));
        }
        let Some(text) = label(p) else {
            continue;
        };
        if compact {
            out.push(Shape::Text(text, [ix + 19.0, iy + 4.0], rgb));
        } else {
            // In the box: over the icon's foot, or (with the bar) its head.
            let tw = game.native_text_width(&text) * 0.75;
            let ty = if bar { iy } else { iy + 16.0 - 6.75 };
            out.push(Shape::Scaled(text, [ix + 16.0 - tw, ty], rgb, 0.75));
        }
    }
}

// Slot boxes from the hotbar's own sprite: its left end and `slots` slots, then its right edge.
fn frame(out: &mut Vec<Shape>, x: f32, y: f32, slots: usize) {
    let width = 1.0 + SLOT * slots as f32;
    out.push(Shape::Sprite("gui/sprites/hud/hotbar", [x, y, width, 22.0], [0.0, 0.0, width / 182.0, 1.0]));
    out.push(Shape::Sprite("gui/sprites/hud/hotbar", [x + width, y, 1.0, 22.0], [181.0 / 182.0, 0.0, 1.0, 1.0]));
}

// Shield status: while an axe has your shield down, its icon, the seconds left and a bar, left of the crosshair (the
// Target HUD has its right).
fn shield(game: &Game<'_>, w: f32, h: f32, out: &mut Vec<Shape>) {
    let shield = [game.offhand.as_ref(), game.held()].into_iter().flatten().find(|s| s.item.ends_with("shield"));
    let group = shield.map_or_else(
        || std::sync::Arc::from("minecraft:shield"),
        |s| horizon_client::cooldowns::group(s, game.res.items().get(&s.item).and_then(|i| i.use_cooldown.as_ref())),
    );
    let partial = game.clock.fraction() as f32;
    let left = game.cooldowns.percent(&group, partial);
    let mut since = SHIELD_SINCE.lock().unwrap_or_else(|e| e.into_inner());
    if left <= 0.0 {
        *since = None;
        return;
    }
    let now = game.ticks as f32 + partial;
    let (start, first) = *since.get_or_insert((now, left));
    // The whole cooldown, from how fast it runs down: an axe's five seconds until that can be told.
    let (elapsed, run) = (now - start, first - left);
    let total = if elapsed >= 2.0 && run > 0.005 { elapsed / run } else { 100.0 };
    let text = format!("{:.1}s", left * total / 20.0);
    let width = 24.0 + game.native_text_width(&text);
    let (x, y) = (w / 2.0 - 12.0 - width, h / 2.0 + 12.0);
    out.push(Shape::Fill([x, y, width, 24.0], 0x9000_0000));
    out.push(Shape::Item(std::sync::Arc::from("minecraft:shield"), [x + 2.0, y + 2.0], 16.0));
    out.push(Shape::Text(text, [x + 20.0, y + 6.0], 0xFF5555));
    out.push(Shape::Fill([x + 2.0, y + 20.0, width - 4.0, 2.0], 0xFF30_3030));
    out.push(Shape::Fill([x + 2.0, y + 20.0, (width - 4.0) * left, 2.0], 0xFFFF_5555));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_compass_reads_north_at_the_games_yaw_180() {
        assert_eq!([heading(180.0), heading(-90.0), heading(0.0), heading(90.0), heading(-180.0)], [0.0, 90.0, 180.0, 270.0, 0.0]);
    }

    #[test]
    fn compass_ticks_cover_140_degrees_every_5() {
        let t = ticks(0.0);
        assert_eq!(t.len(), 29);
        assert_eq!(t.first().copied(), Some((0.0, 290)));
        assert_eq!(t[14], (0.5, 0));
        assert_eq!(t.last().copied(), Some((1.0, 70)));
        // Off the 5s: the first tick is past the strip's left edge, never before it.
        let t = ticks(12.5);
        assert!(t.iter().all(|&(at, d)| (0.0..=1.0).contains(&at) && d % 5 == 0));
        assert_eq!(t.first().map(|v| v.1), Some(305));
    }

    #[test]
    fn a_dragged_element_stays_on_the_screen() {
        assert_eq!(fractions([64.0, 32.0], [32.0, 16.0], [128.0, 64.0]), (0.5, 0.5));
        assert_eq!(fractions([-30.0, 90.0], [32.0, 16.0], [128.0, 64.0]), (0.0, 0.75));
        assert_eq!(fractions([120.0, 0.0], [32.0, 16.0], [128.0, 64.0]), (0.75, 0.0));
    }
}

// The HUD's module list (array list) and the colours and text case the rest of the HUD shares.
//
// Each module on is a row, widest first (or by name), with its details after its name (its info, else its Mode):
// in gray (Gray), in brackets, after a dash, or not at all. Rows slide in from the screen's edge as a module turns on
// and out as it turns off, and glide to their new place when the order changes. A row's colour is the HUD's Theme
// color (Static), flows between it and Second color down the list (Fade), pulses between them all at once (Breathe),
// or runs through the rainbow (Rainbow), at Color speed. Behind a row: a background at List background's opacity, and
// a bar on its outer or inner edge in the row's colour. Modules shown leaves out Render modules or those without a
// bind; the menu's own modules (Client, HUD, ClickGUI) never show.
//
// Behaviour after Rise 6's Interface module (array list colour modes, suffix, lowercase, remove spaces, background and
// sidebar, slide animations); written anew for Sunset.

use super::Game;
use super::sunset::{Category, Module, Shape, accent};
use std::sync::Mutex;
use std::time::Instant;

// The colours a HUD colour setting offers: the menu's accent, a darker accent, and the palette's.
pub(super) const COLOURS: &[&str] = &[
    "Accent", "Darker", "White", "Gold", "Red", "Orange", "Yellow", "Lime", "Green", "Cyan", "Blue", "Purple", "Pink", "Gray",
    "Sunset Orange",
];

// Second color's: the same, a darker accent first (a fade of the accent into its own shade).
pub(super) const SECOND_COLOURS: &[&str] = &[
    "Darker", "Accent", "White", "Gold", "Red", "Orange", "Yellow", "Lime", "Green", "Cyan", "Blue", "Purple", "Pink", "Gray",
    "Sunset Orange",
];

fn colour(name: &str) -> u32 {
    match name {
        "Accent" => accent() & 0x00FF_FFFF,
        "Darker" => scale(accent(), 0.55),
        other => super::sunset_visual::palette(other) & 0x00FF_FFFF,
    }
}

fn scale(rgb: u32, k: f32) -> u32 {
    let ch = |s: u32| (((rgb >> s & 0xFF) as f32 * k).round() as u32).min(255) << s;
    ch(16) | ch(8) | ch(0)
}

fn blend(a: u32, b: u32, t: f32) -> u32 {
    let ch = |s: u32| {
        let (x, y) = ((a >> s & 0xFF) as f32, (b >> s & 0xFF) as f32);
        ((x + (y - x) * t).round() as u32).min(255) << s
    };
    ch(16) | ch(8) | ch(0)
}

// A hue (degrees) at Rise's rainbow saturation (0.6) and full brightness.
fn rainbow(hue: f32) -> u32 {
    let h = hue.rem_euclid(360.0) / 60.0;
    let (s, v) = (0.6f32, 1.0f32);
    let c = v * s;
    let x = c * (1.0 - (h % 2.0 - 1.0).abs());
    let (r, g, b) = match h as u32 {
        0 => (c, x, 0.0),
        1 => (x, c, 0.0),
        2 => (0.0, c, x),
        3 => (0.0, x, c),
        4 => (x, 0.0, c),
        _ => (c, 0.0, x),
    };
    let m = v - c;
    let to = |f: f32| (((f + m) * 255.0).round() as u32).min(255);
    to(r) << 16 | to(g) << 8 | to(b)
}

static START: Mutex<Option<Instant>> = Mutex::new(None);

fn seconds() -> f32 {
    START.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Instant::now).elapsed().as_secs_f32()
}

// The HUD's colour at height `y` (pixels down the screen) now, by its Color mode.
pub(super) fn colour_at(hud: &Module, mode: &str, y: f32) -> u32 {
    let (first, second) = (colour(hud.p("Theme color")), colour(hud.p("Second color")));
    let t = seconds() * hud.n("Color speed") as f32;
    match mode {
        "Fade" => blend(first, second, (t * 1.667 + y * 0.06).sin() * 0.5 + 0.5),
        "Breathe" => blend(first, second, (t * 1.667).sin() * 0.5 + 0.5),
        "Rainbow" => rainbow(t * 100.0 + y * 2.5),
        _ => first,
    }
}

// Text as the HUD's Text case has it.
pub(super) fn cased(hud: &Module, text: &str) -> String {
    match hud.p("Text case") {
        "lowercase" => text.to_lowercase(),
        "UPPERCASE" => text.to_uppercase(),
        _ => text.to_owned(),
    }
}

// The HUD's shapes from `from` on in its Text case (what was drawn after the text was measured: left-aligned).
pub(super) fn case_shapes(hud: &Module, shapes: &mut [Shape]) {
    if hud.p("Text case") == "Normal" {
        return;
    }
    for s in shapes {
        if let Shape::Text(t, ..) | Shape::Head(t, ..) | Shape::Scaled(t, ..) = s {
            *t = cased(hud, t);
        }
    }
}

// A module's details for the list: its own info, else its Mode.
fn detail(m: &Module) -> Option<String> {
    m.info().or_else(|| m.setting("Mode").map(|_| m.p("Mode").to_owned()))
}

// Whether a module on shows in the list.
fn shown(hud: &Module, m: &Module) -> bool {
    if !m.on || matches!(m.name, "HUD" | "ClickGUI") || m.category == Category::Client {
        return false;
    }
    match hud.p("Modules shown") {
        "Exclude render" => m.category != Category::Render,
        "Only bound" => m.key.is_some(),
        _ => true,
    }
}

// A row: its module, the text drawn (name, details) and their widths, how far in it is (0 out, 1 in) and its height.
struct Row {
    module: &'static str,
    name: String,
    detail: String,
    name_w: f32,
    detail_w: f32,
    shown: bool,
    t: f32,
    y: f32,
}

impl Row {
    fn width(&self) -> f32 {
        self.name_w + if self.detail.is_empty() { 0.0 } else { 4.0 + self.detail_w }
    }
}

struct List {
    rows: Vec<Row>,
    last: Option<Instant>,
    font: u32,
}

static LIST: Mutex<List> = Mutex::new(List { rows: Vec::new(), last: None, font: u32::MAX });

// The text of a module's row: its name and details as Text case, Remove spaces and Module details have them.
fn row_text(hud: &Module, m: &Module) -> (String, String) {
    let tidy = |s: &str| {
        let s = cased(hud, s);
        if hud.b("Remove spaces") { s.replace(' ', "") } else { s }
    };
    let detail = match (hud.p("Module details"), detail(m)) {
        ("Off", _) | (_, None) => String::new(),
        ("Brackets", Some(d)) => format!("[{}]", tidy(&d)),
        ("Dash", Some(d)) => format!("- {}", tidy(&d)),
        (_, Some(d)) => tidy(&d),
    };
    (tidy(m.name), detail)
}

// Draws the list at the corner's place (`at`, the top of its side's edge: x is the screen's edge for Right), and the
// room it takes now (its widest row and its height). `place` asks the corner for that room first.
pub(super) fn draw(game: &Game<'_>, hud: &Module, mods: &[Module], right: bool, place: &mut dyn FnMut(f32, f32) -> (f32, f32), out: &mut Vec<Shape>) {
    let mut list = LIST.lock().unwrap_or_else(|e| e.into_inner());
    let now = Instant::now();
    let dt = list.last.map_or(0.0, |l| now.duration_since(l).as_secs_f32()).min(0.1);
    list.last = Some(now);
    let font = u32::from(horizon_client::font::sunset_font::STYLE.load(std::sync::atomic::Ordering::Relaxed));
    let remeasure = std::mem::replace(&mut list.font, font) != font;
    let spacing = hud.n("List spacing") as f32;
    let animate = hud.b("List animations");
    // The rows wanted now, with their text: new ones start out at the edge, changed text is measured again.
    for row in &mut list.rows {
        row.shown = false;
    }
    for m in mods.iter().filter(|m| shown(hud, m)) {
        let (name, detail) = row_text(hud, m);
        let i = match list.rows.iter().position(|r| r.module == m.name) {
            Some(i) => i,
            None => {
                list.rows.push(Row { module: m.name, name: String::new(), detail: String::new(), name_w: 0.0, detail_w: 0.0, shown: true, t: 0.0, y: -1.0 });
                list.rows.len() - 1
            }
        };
        let row = &mut list.rows[i];
        row.shown = true;
        if remeasure || row.name != name {
            row.name_w = game.native_text_width(&name);
            row.name = name;
        }
        if remeasure || row.detail != detail {
            row.detail_w = if detail.is_empty() { 0.0 } else { game.native_text_width(&detail) };
            row.detail = detail;
        }
    }
    // Order: widest first, or by name; the rows going out keep their place while they leave.
    let by_name = hud.p("List sort") == "Name";
    list.rows.sort_by(|a, b| {
        b.shown.cmp(&a.shown).then_with(|| if by_name { a.name.cmp(&b.name) } else { b.width().total_cmp(&a.width()) })
    });
    let count = list.rows.iter().filter(|r| r.shown).count();
    let speed = if animate { dt * 6.0 } else { 1.0 };
    for (n, row) in list.rows.iter_mut().enumerate() {
        let target = if row.shown { n as f32 * spacing } else { row.y.max(0.0) };
        row.t = if row.shown { (row.t + speed).min(1.0) } else { (row.t - speed).max(0.0) };
        row.y = if row.y < 0.0 || !animate { target } else { row.y + (target - row.y) * (dt * 12.0).min(1.0) };
    }
    list.rows.retain(|r| r.shown || r.t > 0.0);
    let widest = list.rows.iter().filter(|r| r.t > 0.0).map(Row::width).fold(0.0, f32::max);
    if list.rows.is_empty() {
        return;
    }
    let bar = hud.p("List bar");
    let pad = 2.0;
    let room = widest + 2.0 * pad + if bar == "Off" { 0.0 } else { 2.0 };
    let (x, y) = place(room, count as f32 * spacing + 2.0);
    let mode = hud.p("List color mode");
    let background = hud.n("List background") as f32;
    for row in &list.rows {
        let ease = row.t * row.t * (3.0 - 2.0 * row.t);
        let w = row.width() + 2.0 * pad;
        let ry = y + row.y;
        let colour = colour_at(hud, mode, ry);
        // The bar on the row's right edge or its left (Outer: the screen's side).
        let bar_right = bar != "Off" && (right == (bar == "Outer"));
        let bar_left = bar != "Off" && !bar_right;
        // In from (and out to) the screen's edge, fading as it goes.
        let slide = (1.0 - ease) * (w + 4.0);
        let rx = if right {
            x + room - w - if bar_right { 2.0 } else { 0.0 } + slide
        } else {
            x + if bar_left { 2.0 } else { 0.0 } - slide
        };
        let alpha = ((ease * 255.0) as u32).clamp(1, 255);
        if background > 0.0 {
            let a = ((background * 255.0 * ease) as u32).min(255);
            out.push(Shape::Fill([rx, ry, w, spacing], a << 24));
        }
        if bar_right {
            out.push(Shape::Fill([rx + w, ry, 1.5, spacing], alpha << 24 | colour));
        } else if bar_left {
            out.push(Shape::Fill([rx - 1.5, ry, 1.5, spacing], alpha << 24 | colour));
        }
        let ty = ry + (spacing - 8.0) / 2.0;
        out.push(Shape::Text(row.name.clone(), [rx + pad, ty], alpha << 24 | colour));
        if !row.detail.is_empty() {
            let tint = if hud.p("Module details") == "Gray" { 0xAAAAAA } else { colour };
            out.push(Shape::Text(row.detail.clone(), [rx + pad + row.name_w + 4.0, ty], alpha << 24 | tint));
        }
    }
}

