        let inventory = inv(&[(0, n(item("stone"), 64)), (9, n(item("stone"), 64)), (10, n(item("stone"), 64)),
            (11, n(item("bread"), 8)), (12, n(item("arrow"), 64))]);
        let mut keep = vec![false; 36];
        keep[0] = true;
        assert_eq!(quota_excess(&inventory, &keep, [80, 4, 0, 16]), [10, 12]);
        // A protected stack already meets the quota: ordinary copies can go, but that stack cannot.
        assert_eq!(quota_excess(&inventory, &keep, [32, 4, 0, 16]), [10, 9, 12]);
    }

    #[test]
    fn merging_does_not_empty_another_hotbar_slot() {
        let inventory = inv(&[(0, n(item("stone"), 10)), (8, n(item("stone"), 20))]);
        assert_eq!(merge_step(&inventory, &vec![false; 36]), None,
            "merging hotbar stacks fights the layout and the player's own arrangement");
        let mut inventory = inventory;
        inventory[9] = Some(n(item("stone"), 5));
        assert_eq!(merge_step(&inventory, &vec![false; 36]), Some((9, 0)));
    }

    #[test]
    fn part_stacks_merge_only_with_their_like() {
        let mut inv1 = inv(&[(2, n(item("stone"), 40)), (9, n(item("stone"), 30)), (10, Item { meta: 7, ..n(item("stone"), 10) }),
            (11, n(item("ender_pearl"), 16))]);
        let locked = vec![false; 36];
        assert_eq!(merge_step(&inv1, &locked), Some((9, 2)), "the later stack into the hotbar's");
        // After it (64 and 6): the 6 has no plain stone to join; the stack with components stays apart.
        inv1[2] = Some(n(item("stone"), 64));
        inv1[9] = Some(n(item("stone"), 6));
        assert_eq!(merge_step(&inv1, &locked), None);
    }

    #[test]
    fn sorting_reaches_its_order_and_stays_there_over_many_ticks() {
        let mut inv1 = inv(&[(9, item("bread")), (11, item("diamond_sword")), (12, n(item("stone"), 3)), (14, n(item("stone"), 9)),
            (15, item("iron_pickaxe"))]);
        let locked = vec![false; 36];
        let mut steps = 0;
        for _ in 0..150 {
            if let Some((a, b)) = sort_step(&inv1, 9..36, &locked) {
                inv1.swap(a, b);
                steps += 1;
            }
        }
        assert!(steps <= 5, "{steps} swaps over 150 ticks: no loop");
        assert_eq!(names(&inv1, 9..15), ["diamond_sword", "iron_pickaxe", "stone", "stone", "bread", "-"]);
    }

    #[test]
    fn planning_a_full_inventory_is_cheap() {
        let kinds = ["diamond_sword", "iron_sword", "diamond_pickaxe", "iron_pickaxe", "diamond_chestplate", "iron_chestplate", "bread", "stone"];
        let full: Vec<Option<Item>> = (0..36).map(|i| Some(n(with(item(kinds[i % kinds.len()]), "unbreaking", (i % 3) as u32), 1 + i as u32))).collect();
        let worn: [Option<Item>; 4] = Default::default();
        let w = slots(["Sword", "Pickaxe", "Blocks", "Food", "Sword", "Blocks", "Food", "Pickaxe", "Blocks"]);
        let locked = vec![false; 36];
        let runs = 500;
        let started = std::time::Instant::now();
        for _ in 0..runs {
            std::hint::black_box(plan_hotbar(&full, &w, &locked, false));
            std::hint::black_box(excess(&full, &worn, &locked, false, Retention::BestPlusBackup));
            std::hint::black_box(merge_step(&full, &locked));
            std::hint::black_box(sort_step(&full, 9..36, &locked));
        }
        let each = started.elapsed() / runs;
        println!("inventory plan (hotbar search, retention, merge, sort; 36 full slots): {} us a plan", each.as_micros());
        assert!(each < std::time::Duration::from_millis(5), "{each:?}");
    }

    // Vanilla's hotbar-key click (SWAP): the clicked slot and the hotbar slot exchange what they hold, with nothing on
    // the cursor. Every way two slots and the hotbar slot between them can be filled ends with the two exchanged and
    // the hotbar slot as it was; a refused middle click puts everything back.
    #[test]
    fn exchanges_go_by_hotbar_swaps_and_lose_nothing() {
        let run = |inv: &mut Vec<Option<&str>>, clicks: &[(usize, usize)], refuse: Option<usize>| {
            for (k, &(slot, key)) in clicks.iter().enumerate() {
                if Some(k) != refuse {
                    inv.swap(slot, key);
                }
            }
        };
        for (a, b, via) in [(12, 30, 4), (12, 3, 4), (2, 30, 4)] {
            for fill in 0..8u8 {
                let mut inv: Vec<Option<&str>> = vec![None; 36];
                inv[a] = (fill & 1 != 0).then_some("sword");
                inv[b] = (fill & 2 != 0).then_some("stone");
                inv[via] = (fill & 4 != 0).then_some("pearl");
                let before = inv.clone();
                let clicks = exchange_swaps(a, b, via, |i| inv[i].is_none());
                let mut done = inv.clone();
                run(&mut done, &clicks, None);
                assert_eq!((done[a], done[b], done[via]), (before[b], before[a], before[via]), "{a} {b} {via} {fill}: {clicks:?}");
                if clicks.len() == 3 {
                    let mut refused = inv.clone();
                    run(&mut refused, &clicks, Some(1));
                    assert_eq!(refused, before, "a refused middle click puts everything back");
                }
                let count = |v: &Vec<Option<&str>>| v.iter().flatten().count();
                for refuse in 0..clicks.len() {
                    let mut partial = inv.clone();
                    run(&mut partial, &clicks, Some(refuse));
                    assert_eq!(count(&partial), count(&before), "nothing is lost to a refused click");
                }
            }
        }
        // The hotbar slot is never the one held; free and unlocked ones first.
        let mut empty = [false; 9];
        empty[5] = true;
        assert_eq!(pivot(empty, [false; 9], 0), Some(5));
        assert_eq!(pivot([false; 9], [false; 9], 0), Some(1));
        let mut locked = [true; 9];
        locked[7] = false;
        assert_eq!(pivot(empty, locked, 0), Some(7));
        assert_eq!(pivot([true; 9], [true; 9], 3), Some(0));
    }

    #[test]
    fn a_stack_left_on_the_cursor_goes_back_where_it_fits() {
        let pearls = n(item("ender_pearl"), 10);
        let mut slots = inv(&[(12, n(item("ender_pearl"), 16)), (20, n(item("ender_pearl"), 4))]);
        // Where it came from, when that still takes it.
        assert_eq!(place_target(&slots, &pearls, Some(30), &[false; 36], 0, &[]), Some(30));
        // Filled meanwhile (an item picked up): a stack with room, then an empty slot, the held one last.
        slots[30] = Some(item("stone"));
        assert_eq!(place_target(&slots, &pearls, Some(30), &[false; 36], 0, &[]), Some(20));
        assert_eq!(place_target(&slots, &pearls, Some(30), &[false; 36], 0, &[20]), Some(9), "not where it was refused");
        let full: Vec<Option<Item>> = (0..36).map(|i| (i != 4).then(|| item("stone"))).collect();
        assert_eq!(place_target(&full, &pearls, None, &[false; 36], 4, &[]), Some(4));
        let mut locked = [false; 36];
        locked[4] = true;
        assert_eq!(place_target(&full, &pearls, None, &locked, 0, &[]), None, "no room: left to the player");
    }
}

// The inventory modules' rules that need no world (Rust's PR #16): which slots a swap touches on the wire, when the
// server has confirmed a swap, a key's press edge.

// The offhand's slot number in Sunset's hotbar/inventory numbering (util::OFFHAND).
pub(super) const OFFHAND: usize = 504;

// The player inventory menu's slot for an inventory slot.
pub(super) fn player_wire(slot: usize) -> Option<usize> {
    match slot {
        0..=8 => Some(36 + slot),
        9..=35 => Some(slot),
        OFFHAND => Some(45),
        _ => None,
    }
}

// The inventory slot a SetPlayerInventory packet's slot is.
pub(super) fn player_internal(slot: i32) -> Option<usize> {
    match slot {
        0..=35 => Some(slot as usize),
        40 => Some(OFFHAND),
        _ => None,
    }
}

// A swap of two slots sent to the server: done once the server says each holds what the other held.
#[derive(Clone, Debug)]
pub(super) struct Swap<T> {
    slots: [usize; 2],
    expected: [Option<T>; 2],
    sent: u64,
    seen: u8,
    rejected: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Status {
    Waiting,
    Confirmed,
    Rejected,
    Expired,
}

impl<T: Clone + PartialEq> Swap<T> {
    pub(super) fn new(slots: [usize; 2], before: [Option<T>; 2], sent: u64) -> Option<Self> {
        if slots[0] == slots[1] || before[0].is_none() || before[0] == before[1] {
            return None;
        }
        Some(Self { slots, expected: [before[1].clone(), before[0].clone()], sent, seen: 0, rejected: false })
    }
    // What the server says `slot` holds.
    pub(super) fn observe(&mut self, slot: usize, server_stack: &Option<T>) {
        for i in 0..2 {
            if self.slots[i] == slot {
                if server_stack == &self.expected[i] {
                    self.seen |= 1 << i;
                } else {
                    self.rejected = true;
                }
            }
        }
    }
    pub(super) fn reject(&mut self) {
        self.rejected = true;
    }
    pub(super) fn status(&self, now: u64, timeout: u64) -> Status {
        if self.rejected {
            Status::Rejected
        } else if now < self.sent || now.saturating_sub(self.sent) >= timeout {
            Status::Expired
        } else if self.seen == 3 {
            Status::Confirmed
        } else {
            Status::Waiting
        }
    }
}

// A swap the server refused: not sent again while the slots hold the same.
#[derive(Clone, Debug)]
pub(super) struct Failure<T> {
    pub slots: [usize; 2],
    pub before: [Option<T>; 2],
}

impl<T: PartialEq> Failure<T> {
    pub(super) fn blocks(&self, slots: [usize; 2], before: &[Option<T>; 2]) -> bool {
        self.slots == slots && &self.before == before
    }
}

// A delay setting in ticks, at most `maximum`.
pub(super) fn delay(value: f64, maximum: u64) -> u64 {
    if value.is_finite() && value >= 0.0 { (value as u64).min(maximum) } else { maximum }
}

// How long to wait for the server to confirm a swap: three times the ping plus 250 ms, from 0.75 to 5 s, in ticks.
pub(super) fn confirmation_ticks(latency_ms: Option<i32>) -> u64 {
    let millis = (u64::from(latency_ms.unwrap_or(0).max(0) as u32).saturating_mul(3).saturating_add(250)).clamp(750, 5000);
    millis.div_ceil(50)
}

// A menu's state id that is not older than the last one (it counts up and wraps at 32768).
pub(super) fn revision_current(previous: i32, incoming: i32) -> bool {
    if (0..32768).contains(&previous) && (0..32768).contains(&incoming) {
        (incoming - previous).rem_euclid(32768) < 16384
    } else {
        incoming >= previous
    }
}

// Inventory Manager's Slots mode: a fixed hotbar layout and a lean inventory, one action at a time, a random Delay
// apart. Written after how the classic 1.8 PvP inventory managers behave, not from any client's code:
// - the cursor emptied first; then your best armour worn, helmet to boots; then the best sword, a second sword, the
//   best pickaxe, axe, shovel, bow and a fishing rod each moved to its hotbar slot (0: none); the biggest block
//   stacks, the best potions and the most filling food to their slot ranges;
// - then what is over a limit thrown (blocks, arrows, buckets, snowballs and eggs, ender pearls), then anything not
//   worth keeping, then the worse duplicates (every sword past the one or two kept, every other tool, bow, rod and
//   armour piece but the best);
// - nothing for 10 ticks after you attack, place a block or have a container open, nor while Scaffold is on; off the
//   inventory screen only with GUI Move on and no click held (Only in inventory: on the screen only), and the
//   inventory counts as opened a tick before the first action and closed after two passes with nothing to do;
// - an item with a custom name (a server's menu item) is neither moved nor thrown unless Use / Drop custom items say.
// Slots in this file are numbered as the classic player inventory is: 0 to 8 the hotbar, 9 to 35 the rest, 36 to 39
// the boots, leggings, chestplate and helmet worn. Of two equal armour pieces the worn one stays.

use super::Game;
use super::sunset::Module;
use std::sync::Mutex;

pub(super) const SLOTS: usize = 40;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Tool {
    Pickaxe,
    Axe,
    Shovel,
}

// What the manager knows of a stack.
#[derive(Clone, Debug, Default, PartialEq)]
pub(super) struct Stack {
    pub name: String,
    pub count: u32,
    pub custom: bool,
    pub useful: bool,
    // Any block item (the block limit and slots).
    pub block: bool,
    // Armour: its type (0 helmet, 1 chestplate, 2 leggings, 3 boots) and score.
    pub armor: Option<(usize, i32)>,
    pub sword: Option<f32>,
    pub tool: Option<(Tool, f32)>,
    pub bow: Option<f32>,
    pub rod: bool,
    // A potion with effects: splash, and its effect's rank.
    pub potion: Option<(bool, i32)>,
    // Food: its saturation modifier.
    pub food: Option<f32>,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub(super) struct Cfg {
    // Hotbar slots, 1 to 9 (0: none).
    pub sword: usize,
    pub second_sword: usize,
    pub pickaxe: usize,
    pub axe: usize,
    pub shovel: usize,
    pub bow: usize,
    pub rod: usize,
    pub blocks: (usize, usize),
    pub potions: (usize, usize),
    pub food: (usize, usize),
    pub limits: Limits,
    pub drop_custom: bool,
    pub use_custom: bool,
    pub splash_first: bool,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub(super) struct Limits {
    pub blocks: u32,
    pub arrows: u32,
    pub buckets: u32,
    pub throwables: u32,
    pub pearls: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Action {
    // The cursor's stack put in an empty slot, or thrown (None).
    Cursor(Option<usize>),
    // An armour piece worn (its slot, the armour type).
    Wear(usize, usize),
    // A stack swapped to a hotbar slot (0 to 8).
    Hotbar(usize, usize),
    Drop(usize),
    // A stack cut down to `keep`, the rest thrown.
    DropPart(usize, u32),
}

// The slots of armour type `t` worn: 39 the helmet down to 36 the boots.
fn worn(t: usize) -> usize {
    39 - t
}

// The inventory sorted into what is kept where and what is spare.
#[derive(Debug, Default)]
struct Scan {
    useless: Vec<usize>,
    blocks: Vec<usize>,
    potions: Vec<usize>,
    food: Vec<usize>,
    armor: [Option<usize>; 4],
    spare_armor: [Vec<usize>; 4],
    sword: Option<usize>,
    second_sword: Option<usize>,
    spare_swords: Vec<usize>,
    tools: [Option<usize>; 3],
    spare_tools: [Vec<usize>; 3],
    bow: Option<usize>,
    spare_bows: Vec<usize>,
    rod: Option<usize>,
    spare_rods: Vec<usize>,
}

// The best of `list` by `score` (the first of equals), the rest spare.
fn best(list: &[usize], spare: &mut Vec<usize>, score: impl Fn(usize) -> f32) -> Option<usize> {
    let (&first, rest) = list.split_first()?;
    let (mut top, mut value) = (first, score(first));
    for &i in rest {
        let v = score(i);
        if v > value {
            spare.push(top);
            (top, value) = (i, v);
        } else {
            spare.push(i);
        }
    }
    Some(top)
}

fn scan(inv: &[Option<Stack>; SLOTS], cfg: &Cfg) -> Scan {
    let mut s = Scan::default();
    let (mut armor, mut swords, mut tools, mut bows, mut rods): ([Vec<usize>; 4], Vec<usize>, [Vec<usize>; 3], Vec<usize>, Vec<usize>) =
        Default::default();
    for (i, stack) in inv.iter().enumerate() {
        let Some(st) = stack else { continue };
        if !st.useful {
            s.useless.push(i);
            continue;
        }
        if st.block {
            s.blocks.push(i);
        }
        if st.potion.is_some() {
            s.potions.push(i);
        }
        if st.food.is_some() {
            s.food.push(i);
        }
        if let Some((t, _)) = st.armor {
            armor[t].push(i);
        } else if st.sword.is_some() {
            swords.push(i);
        } else if let Some((tool, _)) = st.tool {
            tools[tool as usize].push(i);
        } else if st.bow.is_some() {
            bows.push(i);
        } else if st.rod {
            rods.push(i);
        }
    }
    let get = |i: usize| inv[i].as_ref().expect("scanned");
    // The piece worn first, so an equal one is the spare (not the worn one, which would be thrown and worn again).
    for (t, list) in armor.iter_mut().enumerate() {
        if let Some(at) = list.iter().position(|&i| i == worn(t)) {
            let w = list.remove(at);
            list.insert(0, w);
        }
    }
    for t in 0..4 {
        s.armor[t] = best(&armor[t], &mut s.spare_armor[t], |i| get(i).armor.map_or(0.0, |a| a.1 as f32));
    }
    // Swords by damage, best first (a stable sort keeps equals in slot order).
    swords.sort_by(|&a, &b| get(b).sword.unwrap_or(0.0).total_cmp(&get(a).sword.unwrap_or(0.0)));
    if let Some((&first, rest)) = swords.split_first() {
        s.sword = Some(first);
        let two = cfg.sword != 0 && cfg.second_sword != 0 && cfg.second_sword != cfg.sword;
        let rest = if two && !rest.is_empty() {
            s.second_sword = Some(rest[0]);
            &rest[1..]
        } else {
            rest
        };
        s.spare_swords.extend_from_slice(rest);
    }
    for t in 0..3 {
        s.tools[t] = best(&tools[t], &mut s.spare_tools[t], |i| get(i).tool.map_or(0.0, |x| x.1));
    }
    s.bow = best(&bows, &mut s.spare_bows, |i| get(i).bow.unwrap_or(0.0));
    if let Some((&first, rest)) = rods.split_first() {
        s.rod = Some(first);
        s.spare_rods.extend_from_slice(rest);
    }
    s
}

// A stack already in hotbar slot `target` (0 to 8).
fn at(slot: usize, target: usize) -> bool {
    slot <= 8 && slot == target
}

// Where a kept item goes: its hotbar slot (setting 1 to 9), unless it is there or none is set.
fn wants(slot: Option<usize>, setting: usize) -> Option<(usize, usize)> {
    let slot = slot?;
    (setting != 0 && !at(slot, setting - 1)).then_some((slot, setting - 1))
}

// A sword kept in the hotbar slot `setting` names.
fn sword_there(s: &Scan, cfg: &Cfg, setting: usize) -> bool {
    setting != 0 && ((s.sword.is_some() && cfg.sword == setting) || (s.second_sword.is_some() && cfg.second_sword == setting))
}

// The hotbar moves of the kept tools, in order.
fn tool_moves(s: &Scan, cfg: &Cfg) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    out.extend(wants(s.sword, cfg.sword));
    out.extend(wants(s.second_sword, cfg.second_sword));
    for (tool, setting) in [(s.tools[0], cfg.pickaxe), (s.tools[1], cfg.axe), (s.tools[2], cfg.shovel), (s.bow, cfg.bow)] {
        if !sword_there(s, cfg, setting) {
            out.extend(wants(tool, setting));
        }
    }
    if !sword_there(s, cfg, cfg.rod) && cfg.rod != 0 && (cfg.bow == 0 || cfg.rod != cfg.bow || s.bow.is_none()) {
        out.extend(wants(s.rod, cfg.rod));
    }
    out
}

// The moves filling a slot range (first, last; 1 to 9) from `list`, already in order.
fn range_moves(list: &[usize], (first, last): (usize, usize)) -> Vec<(usize, usize)> {
    if first == 0 || first > last {
        return Vec::new();
    }
    list.iter()
        .take(last - first + 1)
        .enumerate()
        .map(|(l, &slot)| (slot, first - 1 + l))
        .filter(|&(slot, target)| !at(slot, target))
        .collect()
}

fn ordered_blocks(inv: &[Option<Stack>; SLOTS], s: &Scan) -> Vec<usize> {
    let mut list = s.blocks.clone();
    list.sort_by_key(|&i| std::cmp::Reverse(inv[i].as_ref().map_or(0, |x| x.count)));
    list
}

fn ordered_potions(inv: &[Option<Stack>; SLOTS], s: &Scan, cfg: &Cfg) -> Vec<usize> {
    let mut list = s.potions.clone();
    let potion = |i: usize| inv[i].as_ref().and_then(|x| x.potion).unwrap_or((false, -1));
    list.sort_by(|&a, &b| {
        let ((sa, ra), (sb, rb)) = (potion(a), potion(b));
        if cfg.splash_first && sa != sb {
            return sb.cmp(&sa);
        }
        rb.cmp(&ra)
    });
    list
}

fn ordered_food(inv: &[Option<Stack>; SLOTS], s: &Scan) -> Vec<usize> {
    let mut list = s.food.clone();
    let food = |i: usize| inv[i].as_ref().and_then(|x| x.food).unwrap_or(0.0);
    list.sort_by(|&a, &b| food(b).total_cmp(&food(a)));
    list
}

// The stacks of each limited kind, in slot order, and the limit.
fn limited(inv: &[Option<Stack>; SLOTS], cfg: &Cfg) -> [(Vec<usize>, u32); 5] {
    let of = |is: &dyn Fn(&Stack) -> bool| -> Vec<usize> {
        inv.iter().enumerate().filter(|(_, x)| x.as_ref().is_some_and(is)).map(|(i, _)| i).collect()
    };
    let l = cfg.limits;
    [
        (of(&|x| x.block), l.blocks),
        (of(&|x| x.name == "arrow"), l.arrows),
        (of(&|x| matches!(x.name.as_str(), "bucket" | "water_bucket" | "lava_bucket" | "milk_bucket")), l.buckets),
        (of(&|x| matches!(x.name.as_str(), "snowball" | "egg")), l.throwables),
        (of(&|x| x.name == "ender_pearl"), l.pearls),
    ]
}

fn total(inv: &[Option<Stack>; SLOTS], list: &[usize]) -> u32 {
    list.iter().filter_map(|&i| inv[i].as_ref()).map(|x| x.count).sum()
}

// Worn armour to change: the best piece of type `t`, when it is not the one worn and beats it.
fn better_armor(inv: &[Option<Stack>; SLOTS], s: &Scan, t: usize) -> Option<usize> {
    let best = s.armor[t]?;
    let score = inv[best].as_ref()?.armor?.1;
    let worn_score = inv[worn(t)].as_ref().and_then(|x| x.armor).map_or(i32::MIN, |a| a.1);
    (best != worn(t) && score > worn_score).then_some(best)
}

fn spares(s: &Scan) -> impl Iterator<Item = usize> + '_ {
    s.spare_swords
        .iter()
        .chain(s.spare_tools.iter().flatten())
        .chain(&s.spare_bows)
        .chain(&s.spare_rods)
        .chain(s.spare_armor.iter().flatten())
        .copied()
}

// Whether the inventory has anything to do (the inventory is opened for it).
pub(super) fn needs_work(inv: &[Option<Stack>; SLOTS], cursor: bool, cfg: &Cfg) -> bool {
    let s = scan(inv, cfg);
    cursor
        || (0..4).any(|t| better_armor(inv, &s, t).is_some())
        || !tool_moves(&s, cfg).is_empty()
        || !range_moves(&ordered_blocks(inv, &s), cfg.blocks).is_empty()
        || !range_moves(&ordered_potions(inv, &s, cfg), cfg.potions).is_empty()
        || !range_moves(&ordered_food(inv, &s), cfg.food).is_empty()
        || limited(inv, cfg).iter().any(|(list, limit)| total(inv, list) > *limit)
        || !s.useless.is_empty()
        || spares(&s).next().is_some()
}

// This pass's action: the first of the manager's order that may go. `may(slot, drop)`: whether the stack in `slot`
// may be clicked (moved or, with `drop`, thrown); `empty`: the first empty inventory slot (not armour).
pub(super) fn next_action(inv: &[Option<Stack>; SLOTS], cursor: bool, cfg: &Cfg, may: impl Fn(usize, bool) -> bool) -> Option<Action> {
    if cursor {
        return Some(Action::Cursor((0..36).find(|&i| inv[i].is_none())));
    }
    let s = scan(inv, cfg);
    for t in 0..4 {
        if let Some(from) = better_armor(inv, &s, t) {
            return Some(Action::Wear(from, t));
        }
    }
    let custom_ok = |slot: usize, drop: bool| {
        inv[slot].as_ref().is_none_or(|x| !x.custom || if drop { cfg.drop_custom } else { cfg.use_custom }) && may(slot, drop)
    };
    for (from, to) in tool_moves(&s, cfg) {
        if custom_ok(from, false) {
            return Some(Action::Hotbar(from, to));
        }
    }
    for moves in [
        range_moves(&ordered_blocks(inv, &s), cfg.blocks),
        range_moves(&ordered_potions(inv, &s, cfg), cfg.potions),
        range_moves(&ordered_food(inv, &s), cfg.food),
    ] {
        if let Some(&(from, to)) = moves.iter().find(|(from, _)| custom_ok(*from, false)) {
            return Some(Action::Hotbar(from, to));
        }
    }
    for (list, limit) in limited(inv, cfg) {
        let count = total(inv, &list);
        if count <= limit {
            continue;
        }
        let excess = count - limit;
        // From the last stack back.
        if let Some(&i) = list.iter().rev().find(|&&i| custom_ok(i, true)) {
            let size = inv[i].as_ref().map_or(0, |x| x.count);
            return Some(if excess >= size { Action::Drop(i) } else { Action::DropPart(i, size - excess) });
        }
    }
    if let Some(i) = s.useless.first().copied().filter(|&i| custom_ok(i, true)) {
        return Some(Action::Drop(i));
    }
    spares(&s).find(|&i| custom_ok(i, true)).map(Action::Drop)
}

// ---- the game side

// The manager's own state: its pause after an action, the counts since an attack, a block placed and a container,
// and whether the inventory counts as open.
struct State {
    next_click: std::time::Duration,
    since_click: std::time::Instant,
    attack: u32,
    place: u32,
    container: u32,
    alive: u32,
    entity: Option<i32>,
    open: bool,
    open_delay: u32,
    idle: u32,
    rng: u64,
}

static STATE: Mutex<Option<State>> = Mutex::new(None);

fn st<R>(f: impl FnOnce(&mut State) -> R) -> R {
    let mut g = STATE.lock().unwrap_or_else(|e| e.into_inner());
    f(g.get_or_insert_with(|| State {
        next_click: std::time::Duration::ZERO,
        since_click: std::time::Instant::now(),
        attack: 100,
        place: 100,
        container: 100,
        alive: 0,
        entity: None,
        open: false,
        open_delay: 0,
        idle: 0,
        rng: 0x2545_f491_4f6c_dd1d,
    }))
}

// An attack or a block placed (not a water bucket's) went out: the manager waits 10 ticks.
pub(super) fn sent(packet: &horizon_protocol::packets::play::Serverbound) {
    use horizon_protocol::packets::play::Serverbound as S;
    match packet {
        S::Attack(_) => st(|s| s.attack = 0),
        S::UseItemOn(_) => st(|s| s.place = 0),
        _ => {}
    }
}

fn close(s: &mut State) {
    s.open = false;
    s.open_delay = 0;
    s.idle = 0;
}

// The classic slot number's place in Sunset's numbering (armour 500 and on, helmet first).
fn internal(slot: usize) -> usize {
    if slot < 36 { slot } else { 500 + (39 - slot) }
}

fn stack_at<'a>(game: &'a Game<'_>, slot: usize) -> Option<&'a horizon_client::items::ItemStack> {
    if slot < 36 { game.inventory.get(slot).and_then(Option::as_ref) } else { game.armor.get(39 - slot).and_then(Option::as_ref) }
}

// The 1.8 potion ranks (instant health 1 ... water breathing 12) of a modern potion's effect, -1 for none ranked.
fn potion_rank(potion: &str) -> i32 {
    let p = super::sunset_util::short(potion).trim_start_matches("long_").trim_start_matches("strong_");
    match p {
        "healing" => 1,
        "regeneration" => 2,
        "turtle_master" => 3,
        "strength" => 7,
        "swiftness" => 8,
        "fire_resistance" => 9,
        "invisibility" => 10,
        "water_breathing" => 12,
        _ => -1,
    }
}

const FALLS: [&str; 6] = ["sand", "gravel", "concrete_powder", "anvil", "dragon_egg", "pointed_dripstone"];
// Full blocks that hold something (a block entity) or bounce: not building blocks.
const NOT_BUILDING: [&str; 14] = [
    "furnace", "blast_furnace", "smoker", "barrel", "dispenser", "dropper", "jukebox", "beacon", "spawner", "note_block",
    "slime_block", "honey_block", "crafter", "trial_spawner",
];
// Items a classic manager keeps besides weapons, tools, armour, food, potions and building blocks.
const KEPT: [&str; 10] = ["fishing_rod", "water_bucket", "bucket", "arrow", "bow", "snowball", "egg", "ender_pearl", "clay_ball", "fire_charge"];

fn describe(game: &Game<'_>, m: &Module, stack: &horizon_client::items::ItemStack) -> Stack {
    let item = super::sunset_player::plan_item(game, stack);
    let name = item.name.clone();
    let level = |e: &str| item.enchants.iter().find(|(x, _)| super::sunset_util::short(x) == e).map_or(0, |x| x.1);
    let info = game.res.items().get(&stack.item);
    let block = info.as_ref().and_then(|i| i.block).is_some();
    let building = item.block
        && !FALLS.iter().any(|f| name.ends_with(f))
        && !NOT_BUILDING.contains(&name.as_str())
        && !name.contains("shulker_box");
    let armor_type = if name.ends_with("_helmet") {
        Some(0)
    } else if name.ends_with("_chestplate") {
        Some(1)
    } else if name.ends_with("_leggings") {
        Some(2)
    } else if name.ends_with("_boots") {
        Some(3)
    } else {
        None
    };
    let tier = |n: &str| match n.split('_').next().unwrap_or("") {
        "netherite" => 6,
        "diamond" => 5,
        "iron" => 4,
        "chainmail" => 3,
        "golden" => 2,
        "leather" => 1,
        _ => 0,
    };
    let armor = armor_type.map(|t| {
        let points = item.armor.round() as i32;
        let other = level("projectile_protection") + level("fire_protection") + level("blast_protection");
        (t, points * 100 + tier(&name) * 10 + level("protection") as i32 * 6 + other as i32 * 2)
    });
    let efficiency = level("efficiency") as f32;
    let tool_score = item.mining + if efficiency > 0.0 { efficiency * efficiency + 1.0 } else { 0.0 };
    let tool = if name.ends_with("_pickaxe") {
        Some((Tool::Pickaxe, tool_score))
    } else if name.ends_with("_axe") {
        Some((Tool::Axe, tool_score))
    } else if name.ends_with("_shovel") {
        Some((Tool::Shovel, tool_score))
    } else {
        None
    };
    let sword = name.ends_with("_sword").then(|| item.attack + level("sharpness") as f32 * 1.25 + level("fire_aspect") as f32 * 2.5);
    let potion = matches!(name.as_str(), "potion" | "splash_potion" | "lingering_potion")
        .then(|| stack.potion())
        .flatten()
        .filter(|p| !matches!(super::sunset_util::short(p), "water" | "awkward" | "mundane" | "thick"))
        .map(|p| (name != "potion", potion_rank(p)));
    let food = info.as_ref().and_then(|i| i.food).map(|(nutrition, saturation)| {
        if nutrition > 0 { saturation as f32 / (nutrition as f32 * 2.0) } else { 0.0 }
    });
    let kept = super::sunset_util::listed(m.t("Protected items"), &name);
    let useful = building
        || name == "tnt"
        || name.ends_with("glass")
        || sword.is_some()
        || tool.is_some()
        || armor.is_some()
        || food.is_some()
        || matches!(name.as_str(), "potion" | "splash_potion" | "lingering_potion")
        || KEPT.contains(&name.as_str())
        || kept;
    Stack {
        name,
        count: stack.count,
        custom: item.named,
        useful,
        block,
        armor,
        sword,
        tool,
        bow: (item.name == "bow").then(|| level("power") as f32),
        rod: item.name == "fishing_rod",
        potion,
        food,
    }
}

fn cfg(m: &Module) -> Cfg {
    let n = |name: &str| m.n(name).max(0.0) as usize;
    let range = |from: &str, to: &str| (n(from), n(to));
    Cfg {
        sword: n("Sword slot"),
        second_sword: n("Second sword slot"),
        pickaxe: n("Pickaxe slot"),
        axe: n("Axe slot"),
        shovel: n("Shovel slot"),
        bow: n("Bow slot"),
        rod: n("Rod slot"),
        blocks: range("Block slots from", "Block slots to"),
        potions: range("Potion slots from", "Potion slots to"),
        food: range("Food slots from", "Food slots to"),
        limits: Limits {
            blocks: m.n("Block limit") as u32,
            arrows: m.n("Arrow limit") as u32,
            buckets: m.n("Bucket limit") as u32,
            throwables: m.n("Snowball and egg limit") as u32,
            pearls: m.n("Ender pearl limit") as u32,
        },
        drop_custom: m.b("Drop custom items"),
        use_custom: m.b("Use custom items"),
        splash_first: m.b("Prioritize splash potions"),
    }
}

fn unit(rng: &mut u64) -> f64 {
    *rng ^= *rng << 13;
    *rng ^= *rng >> 7;
    *rng ^= *rng << 17;
    (*rng >> 11) as f64 / (1u64 << 53) as f64
}

// One pass, each tick before the game's (so its clicks go before the tick's move packet). `m`: Inventory Manager, on,
// in Slots mode.
pub(super) fn pre_tick(game: &mut Game<'_>, m: Option<&Module>) {
    let Some(m) = m else {
        st(close);
        return;
    };
    let entity = game.remote.as_ref().map(|r| r.entity_id);
    let menu = game.remote_menu();
    let player_menu = menu.0 == 0 && menu.1 == "inventory";
    let in_inventory = game.screen == super::Screen::Inventory && player_menu;
    let foreign = !player_menu || !matches!(game.screen, super::Screen::Inventory | super::Screen::Playing);
    let ready = st(|s| {
        if s.entity != entity {
            (s.entity, s.alive) = (entity, 0);
            close(s);
        }
        s.alive = s.alive.saturating_add(1);
        s.attack = s.attack.saturating_add(1);
        s.place = s.place.saturating_add(1);
        s.container = if foreign { 0 } else { s.container.saturating_add(1) };
        s.alive > 40
    });
    if !ready || game.player.is_none() || game.remote.is_none() {
        return;
    }
    let scaffold = super::sunset::with(|s| s.is_on("Scaffold"));
    let gui_move = super::sunset::with(|s| s.is_on("GUI Move"));
    // Only in inventory: on the inventory screen only, the pause counting from when it opened.
    if m.b("Only in inventory") && !in_inventory {
        st(|s| {
            s.since_click = std::time::Instant::now();
            close(s);
        });
        return;
    }
    let paused = st(|s| s.since_click.elapsed() < s.next_click || s.container < 10 || s.attack < 10 || s.place < 10);
    if paused || scaffold || foreign || (!gui_move && !in_inventory) || super::sunset_gui_move::inventory_busy() {
        st(close);
        return;
    }
    let locked = super::sunset_loadouts::locked_slots();
    let inv: [Option<Stack>; SLOTS] = std::array::from_fn(|i| stack_at(game, i).map(|s| describe(game, m, s)));
    let cursor = game.carried.is_some();
    let c = cfg(m);
    let work = needs_work(&inv, cursor, &c);
    // The inventory counts as opened a tick before the first action (at once on its screen).
    let can_open = gui_move
        && game.screen == super::Screen::Playing
        && !scaffold
        && !game.left
        && !game.right
        && !game.physical_buttons.contains(&winit::event::MouseButton::Left)
        && !game.physical_buttons.contains(&winit::event::MouseButton::Right);
    let go = st(|s| {
        if !s.open {
            if !work {
                return false;
            }
            s.idle = 0;
            if in_inventory {
                (s.open, s.open_delay) = (true, 0);
            } else if can_open {
                (s.open, s.open_delay) = (true, 1);
            } else {
                return false;
            }
        } else if !work {
            close(s);
            return false;
        }
        if s.open_delay > 0 {
            s.open_delay -= 1;
            return false;
        }
        true
    });
    if !go || super::sunset_combat_control::owner().is_some() {
        return;
    }
    let may = |slot: usize, _drop: bool| {
        let i = internal(slot);
        !(i < 36 && locked[i]) && !super::sunset_loadouts::locked(i)
    };
    let action = next_action(&inv, cursor, &c, may);
    let moved = action.is_some_and(|a| act(game, a, &locked));
    let (lo, hi) = (m.n("Delay min (ms)"), m.n("Delay max (ms)"));
    st(|s| {
        if moved {
            let roll = unit(&mut s.rng);
            s.next_click = std::time::Duration::from_millis((lo.min(hi) + (hi - lo).abs() * roll).round() as u64);
            s.since_click = std::time::Instant::now();
            s.idle = 0;
        } else {
            // Two passes with nothing done: the inventory counts as closed.
            s.idle += 1;
            if s.idle >= 2 {
                close(s);
            }
        }
    });
}

// The clicks of an action. True when they went.
fn act(game: &mut Game<'_>, action: Action, locked: &[bool; 36]) -> bool {
    use horizon_client::menu::Input::{Pickup, Swap, Throw};
    let ops: Vec<(Option<usize>, i32, horizon_client::menu::Input)> = match action {
        Action::Cursor(Some(slot)) => vec![(Some(internal(slot)), 0, Pickup)],
        Action::Cursor(None) => vec![(None, 0, Pickup)],
        Action::Wear(from, t) => {
            super::sunset_gui_move::direct(|| super::sunset::wear(game, internal(from), t));
            return true;
        }
        Action::Hotbar(from, to) => {
            if locked[to] {
                return false;
            }
            vec![(Some(internal(from)), to as i32, Swap)]
        }
        Action::Drop(slot) => vec![(Some(internal(slot)), 1, Throw)],
        Action::DropPart(slot, keep) => {
            let mut ops = vec![(Some(internal(slot)), 0, Pickup)];
            ops.extend((0..keep).map(|_| (Some(internal(slot)), 1, Pickup)));
            ops.push((None, 0, Pickup));
            ops
        }
    };
    super::sunset_gui_move::direct(|| game.remote_menu_ops(&ops))
}

#[cfg(test)]
mod tests {
    use super::*;

    const CFG: Cfg = Cfg {
        sword: 1,
        second_sword: 2,
        pickaxe: 2,
        axe: 3,
        shovel: 4,
        bow: 7,
        rod: 8,
        blocks: (5, 5),
        potions: (6, 6),
        food: (9, 9),
        limits: Limits { blocks: 512, arrows: 128, buckets: 1, throwables: 16, pearls: 16 },
        drop_custom: false,
        use_custom: false,
        splash_first: false,
    };

    fn empty() -> [Option<Stack>; SLOTS] {
        std::array::from_fn(|_| None)
    }

    fn sword(damage: f32) -> Option<Stack> {
        Some(Stack { name: "iron_sword".into(), count: 1, useful: true, sword: Some(damage), ..Stack::default() })
    }

    fn blocks(count: u32) -> Option<Stack> {
        Some(Stack { name: "oak_planks".into(), count, useful: true, block: true, ..Stack::default() })
    }

    fn helmet(score: i32) -> Option<Stack> {
        Some(Stack { name: "iron_helmet".into(), count: 1, useful: true, armor: Some((0, score)), ..Stack::default() })
    }

    #[test]
    fn the_order_is_cursor_armour_tools_then_ranges_then_drops() {
        let mut inv = empty();
        assert_eq!(next_action(&inv, true, &CFG, |_, _| true), Some(Action::Cursor(Some(0))));
        inv[20] = helmet(500);
        inv[12] = sword(7.0);
        inv[30] = blocks(64);
        // A better helmet first, then the sword to slot 1, then blocks to slot 5.
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), Some(Action::Wear(20, 0)));
        inv[39] = inv[20].take();
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), Some(Action::Hotbar(12, 0)));
        inv[0] = inv[12].take();
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), Some(Action::Hotbar(30, 4)));
        inv[4] = inv[30].take();
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), None);
        assert!(!needs_work(&inv, false, &CFG));
    }

    #[test]
    fn two_swords_take_both_slots_and_the_rest_are_thrown() {
        let mut inv = empty();
        inv[0] = sword(6.0);
        inv[1] = sword(7.0);
        inv[9] = sword(5.0);
        // The best (slot 1) to slot 1 first: swords sorted by damage.
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), Some(Action::Hotbar(1, 0)));
        inv.swap(0, 1);
        // The second best is in slot 2 (index 1) already; the worst goes.
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), Some(Action::Drop(9)));
    }

    #[test]
    fn limits_throw_from_the_last_stack_and_cut_one_down() {
        let mut inv = empty();
        let cfg = Cfg { limits: Limits { blocks: 100, ..CFG.limits }, blocks: (0, 0), ..CFG };
        inv[9] = blocks(64);
        inv[10] = blocks(64);
        // 128 over 100: the last stack keeps 36.
        assert_eq!(next_action(&inv, false, &cfg, |_, _| true), Some(Action::DropPart(10, 36)));
        inv[11] = blocks(64);
        // 192 over 100: the last stack (64 <= 92) goes whole.
        assert_eq!(next_action(&inv, false, &cfg, |_, _| true), Some(Action::Drop(11)));
    }

    #[test]
    fn junk_goes_and_custom_items_are_left_alone() {
        let mut inv = empty();
        inv[15] = Some(Stack { name: "rotten_flesh".into(), count: 3, ..Stack::default() });
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), Some(Action::Drop(15)));
        inv[15].as_mut().unwrap().custom = true;
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), None, "a menu item stays");
        let cfg = Cfg { drop_custom: true, ..CFG };
        assert_eq!(next_action(&inv, false, &cfg, |_, _| true), Some(Action::Drop(15)));
    }

    #[test]
    fn a_worn_piece_as_good_as_the_spare_stays_on_and_the_spare_goes() {
        let mut inv = empty();
        inv[39] = helmet(500);
        inv[20] = helmet(500);
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), Some(Action::Drop(20)));
        inv[20] = helmet(600);
        assert_eq!(next_action(&inv, false, &CFG, |_, _| true), Some(Action::Wear(20, 0)));
    }
}

// Velocity's Knockback delay: what the network module holds by for the next pushes on you
// (horizon_client::net::sunset_packets::hold). Its own state and its own switch: Fake Lag's Knockback mode only hears of
// a push once the game takes it, after this has let it go.
use super::Game;
use super::sunset::Module;
use horizon_client::net::sunset_packets as net;

pub(super) fn tick(game: &Game<'_>, mods: &[Module]) {
    let live = game.remote.is_some()
        && game.screen == super::Screen::Playing
        && !super::sunset::gui_open()
        && !game.spectator()
        && game.player.as_ref().is_some_and(|p| p.health.health() > 0.0);
    let kb = mods.iter().find(|m| m.name == "Velocity" && m.on).filter(|m| {
        m.b("Knockback delay") && live && (!m.b("Delay only near enemies") || super::sunset_lag::enemy(game, 6.0, false))
            && !(m.b("Delay not in water") && game.player.as_ref().is_some_and(|p| p.fluids.was_touching_water))
    });
    match (kb, game.remote.as_ref()) {
        (Some(m), Some(r)) => {
            let ground = game.player.as_ref().is_some_and(|p| p.ground.on_ground);
            let (a, b) = if ground {
                (m.n("Ground delay min (ms)"), m.n("Ground delay max (ms)"))
            } else {
                (m.n("Air delay min (ms)"), m.n("Air delay max (ms)"))
            };
            net::delay(r.entity_id, m.n("Delay chance (%)"), [a.min(b) as u64, a.max(b) as u64]);
        }
        _ => net::delay_off(),
    }
}

pub(super) fn shutdown() {
    net::delay_off();
}

// Fake Lag (from Rust's PR #16, rebuilt): what you send waits on a line (sunset_lag_line) and goes in the order it was
// sent, whole client ticks at a time, so the server sees a slower connection rather than a broken client: no move is
// merged, dropped or moved past its ClientTickEnd, and the Pongs answering the server's pings stay where the client
// wrote them. The modes only decide when the line holds and for how long:
// - Delay: always, each packet Delay (ms) late.
// - Pulse: chokes of Shortest to Longest choke (ms), each let go at once at its end, with Pulse gap (ms) (a tick at
//   least) between them.
// - Dynamic: Delay's line while an enemy is near (Trigger: one you face and walk towards, or the nearest closing in),
//   kept a few ticks after it stops, so the edge of the range does not flip it every tick.
// - Knockback: one choke after each push the game takes (after Velocity's Knockback delay, if that holds it).
// An action (a hit, a use, a click, chat), with Release on action, sends what is held first and goes at once; so does
// an accepted teleport. A teleport, a respawn or a new dimension lets everything held go before the game answers it,
// and the answering tick goes undelayed. A disconnect, a transfer or a proxy's reconfiguration throws what is held
// away: it was written for a connection that is gone. Turning the module off, or a mode whose condition ends, lets the
// line drain on its schedule; Blink, a combat macro or GUI Move taking the stream empties it at once.
// Backtrack and Knockback Delay hold what comes in: sunset_backtrack and sunset_knockback_delay.
use super::sunset::{self, Camera, Canvas, Category, Module};
use super::sunset_lag_line::{self as line, Decision, Discard, Flush, Hysteresis, Kind, Line, Phase, Plan, Pulse};
use super::{Game, Screen};
use horizon_client::net::sunset_packets::{Link, Linked};
use horizon_protocol::packets::play::Serverbound as S;
use std::borrow::Cow;
use std::cell::Cell;
use std::collections::VecDeque;
use std::fmt::Write as _;
use std::sync::Mutex;
use std::time::{Duration, Instant, SystemTime};

pub(super) const LAG: &str = "Fake Lag";
// Dynamic lets go after its condition failed this many ticks running.
const EXIT_TICKS: u32 = 3;
// Sunset's tick tells the line how to hold; one that stops coming (Sunset off) holds nothing after this.
const TOLD: Duration = Duration::from_millis(250);

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new(LAG, Category::Combat, "Delays what you send, in order.")
            .pick("Mode", &["Delay", "Pulse", "Dynamic", "Knockback"])
            .num("Delay (ms)", 100.0, 10.0, 1000.0, 10.0)
            .pick("Trigger", &["Facing", "Closing"])
            .num("Range", 6.0, 3.0, 12.0, 0.5)
            .num("Shortest choke (ms)", 100.0, 0.0, 1000.0, 10.0)
            .num("Longest choke (ms)", 150.0, 0.0, 1000.0, 10.0)
            .num("Pulse gap (ms)", 0.0, 0.0, 1000.0, 10.0)
            .bool("Release on action", true)
            .bool("Show server position", true),
    ]
}

// Which settings show for a mode (the ClickGUI).
pub(super) fn setting_visible(m: &Module, name: &str) -> bool {
    let mode = m.p("Mode");
    match name {
        "Delay (ms)" => matches!(mode, "Delay" | "Dynamic"),
        "Trigger" | "Range" => mode == "Dynamic",
        "Shortest choke (ms)" | "Longest choke (ms)" => matches!(mode, "Pulse" | "Knockback"),
        "Pulse gap (ms)" => matches!(mode, "Pulse" | "Knockback"),
        _ => true,
    }
}

// ---------------------------------------------------------------- state

#[derive(Default)]
struct Dynamic {
    gate: Hysteresis,
    // Closing: how far the nearest enemy was last tick.
    enemy_was: Option<f64>,
}

struct Note {
    at: SystemTime,
    tick: u64,
    what: Cow<'static, str>,
    packets: usize,
}

#[derive(Default)]
struct Lag {
    line: Line<S>,
    // The connection what is held was written for.
    link: Option<Link>,
    // The life what is held belongs to: entity id and dimension.
    life: Option<(i32, super::Dim)>,
    // As Sunset's tick last said: actions release, and when it said so.
    actions: bool,
    told: Option<Instant>,
    mode: &'static str,
    pulse: Pulse,
    dynamic: Dynamic,
    // The game took a push on you since the last tick.
    knocked: bool,
    // Where the server has you: the last position that went on the wire.
    sent_at: Option<[f64; 3]>,
    roll: u64,
    notes: VecDeque<Note>,
}

static LAG_STATE: Mutex<Option<Lag>> = Mutex::new(None);

thread_local! {
    // Inside Fake Lag's own delivery: a packet a module sends from there goes behind what is still to go.
    static DELIVERING: Cell<u32> = const { Cell::new(0) };
}

fn lag<R>(f: impl FnOnce(&mut Lag) -> R) -> R {
    f(LAG_STATE.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Lag::default))
}

fn note(l: &mut Lag, what: impl Into<Cow<'static, str>>, packets: usize) {
    if l.notes.len() == 16 {
        l.notes.pop_front();
    }
    l.notes.push_back(Note { at: SystemTime::now(), tick: horizon_protocol::connection::sunset_wire::ticks(), what: what.into(), packets });
}

// ---------------------------------------------------------------- packets

// Packets that do something: with Release on action, what is held goes before them, and they go at once.
fn action(packet: &S) -> bool {
    matches!(
        packet,
        S::Attack(_) | S::Interact(_) | S::UseItemOn(_) | S::UseItem(_) | S::PlayerAction(_) | S::Punch(_)
            | S::ContainerClick(_) | S::ContainerButtonClick(_) | S::ContainerClose(_) | S::Chat(_)
            | S::ChatCommand(_) | S::ChatCommandSigned(_) | S::SignUpdate(_) | S::EditBook(_) | S::PlaceRecipe(_)
            | S::SelectTrade(_) | S::SetCreativeModeSlot(_) | S::PickItemFromBlock(_) | S::PickItemFromEntity(_)
            | S::Unknown(..)
    )
}

fn kind(packet: &S, actions: bool) -> Kind {
    match packet {
        S::ClientTickEnd(_) => Kind::TickEnd,
        // Answers to the server's re-anchoring: never behind what was written before it.
        S::AcceptTeleportation(_) | S::ConfigurationAcknowledged(_) => Kind::Trigger,
        _ if actions && action(packet) => Kind::Trigger,
        _ => Kind::Other,
    }
}

fn position(packet: &S) -> Option<[f64; 3]> {
    match packet {
        S::MovePlayerPos(p) => Some([p.x, p.y, p.z]),
        S::MovePlayerPosRot(p) => Some([p.x, p.y, p.z]),
        _ => None,
    }
}

// What is held is the connection's it was written for; another connection's (or a reconfigured one's) is thrown away.
fn bind(l: &mut Lag, session: Option<&horizon_client::net::Session>) {
    let linked = l.link.as_ref().map_or(Linked::Other, |old| old.to(session));
    if linked == Linked::Same {
        return;
    }
    if !l.line.is_empty() {
        let why = if linked == Linked::Reconfigured { Discard::Reconfigured } else { Discard::Session };
        let n = l.line.discard(why);
        l.pulse.reset();
        l.dynamic = Dynamic::default();
        note(l, format!("discarded: {}", why.name()), n);
    }
    l.link = session.map(Link::of);
}

// A packet going out now, after the send hook or from the line: Sunset hears of it, then the wire takes it.
fn deliver(game: &Game<'_>, packet: S) {
    DELIVERING.with(|d| d.set(d.get() + 1));
    super::sunset_combat_wire::delivered(game, &packet);
    if let Some(r) = &game.remote {
        r.session.send(packet);
    }
    DELIVERING.with(|d| d.set(d.get() - 1));
}

// What may go now goes, in order; a packet a module sends meanwhile is queued behind and may go in the same pass.
fn release(game: &Game<'_>, now: Instant) {
    for _ in 0..2 * line::MOST {
        let n = lag(|l| l.line.releasable(now));
        if n == 0 {
            return;
        }
        for _ in 0..n {
            let Some(p) = lag(|l| l.line.pop(now)) else { break };
            deliver(game, p);
        }
    }
}

// Panic, while its cleanup waits for a plugin callback: a packet the game sends goes behind what was held, never before
// it (the send hook calls this before letting it through).
pub(super) fn drain(game: &Game<'_>) {
    if DELIVERING.with(Cell::get) == 0 && lag(|l| l.line.len()) > 0 {
        flush(game, Flush::Stopped);
    }
}

// Everything held goes now, in order.
fn flush(game: &Game<'_>, why: Flush) -> usize {
    let now = Instant::now();
    let n = lag(|l| {
        let n = l.line.len();
        if n > 0 {
            l.line.note_flush(why);
        }
        n
    });
    for _ in 0..n + line::MOST {
        let Some(p) = lag(|l| l.line.pop(now)) else { break };
        deliver(game, p);
    }
    n
}

// The send hook, on the packet that would go out (after Sunset's other changes to it): true if Fake Lag took it (held
// it, or sent it itself behind what it held).
pub(super) fn held(game: &Game<'_>, packet: &S) -> bool {
    let now = Instant::now();
    if DELIVERING.with(Cell::get) > 0 {
        lag(|l| {
            let k = kind(packet, l.actions);
            l.line.push(packet.clone(), k, now, now);
        });
        return true;
    }
    let session = game.remote.as_ref().map(|r| &r.session);
    // The ordinary path: one lock, nothing held, the packet goes.
    let idle = lag(|l| {
        bind(l, session);
        // Sunset's tick stopped coming: hold nothing more, let what is held drain.
        if l.line.phase() == Phase::Holding && l.told.is_none_or(|t| now - t >= TOLD) {
            l.line.stop();
        }
        l.line.phase() == Phase::Idle
    });
    if idle {
        return false;
    }
    release(game, now);
    let decision = lag(|l| {
        let k = kind(packet, l.actions);
        let d = l.line.decide(k, now);
        match d {
            Decision::Pass => l.line.passed(k),
            Decision::Hold(due) => l.line.push(packet.clone(), k, now, due),
            Decision::Flush(_) => l.line.push(packet.clone(), k, now, now),
        }
        d
    });
    match decision {
        Decision::Pass => false,
        Decision::Hold(_) => {
            release(game, now);
            true
        }
        Decision::Flush(why) => {
            if why == Flush::Overflow {
                lag(|l| {
                    let n = l.line.len();
                    note(l, "overflow: sent everything held", n);
                });
            }
            flush(game, why);
            true
        }
    }
}

// Every packet that went on the wire (sunset_combat_wire::delivered): where the server now has you.
pub(super) fn sent(_game: &Game<'_>, packet: &S) {
    if let Some(at) = position(packet) {
        lag(|l| l.sent_at = Some(at));
    }
}

pub(super) fn pending() -> bool {
    lag(|l| !l.line.is_empty())
}

// The server pushed you (a velocity packet the game took): Knockback's choke starts.
pub(super) fn knocked() {
    lag(|l| l.knocked = true);
}

// A position packet from the server (remote_teleport's head, before the game answers it): what is held goes first
// (the server ignores moves until the client accepts), and the answer goes undelayed.
pub(super) fn correction(game: &Game<'_>) {
    let session = game.remote.as_ref().map(|r| &r.session);
    let busy = lag(|l| {
        bind(l, session);
        l.line.phase() != Phase::Idle
    });
    if !busy {
        return;
    }
    let n = flush(game, Flush::Reanchor);
    lag(|l| {
        l.line.reset();
        l.pulse.reset();
        note(l, "teleport: sent everything held", n);
    });
}

// Panic: everything held goes now, in order, and nothing more is held. (Thrown away, the Pongs among it would leave
// the server waiting on answers it never gets, and the ticks it already counted on would be missing.)
pub(super) fn shutdown(game: &mut Game<'_>) {
    let session = game.remote.as_ref().map(|r| &r.session);
    lag(|l| bind(l, session));
    let n = flush(game, Flush::Stopped);
    lag(|l| {
        if n > 0 {
            note(l, "Sunset stopped: sent everything held", n);
        }
        l.line.clear_keeping_stats();
        l.told = None;
        l.pulse.reset();
        l.dynamic = Dynamic::default();
        l.knocked = false;
    });
    super::remote::sunset_gui_move_remote::retry_idle(game);
}

fn rolled(lo: f64, hi: f64) -> Duration {
    let r = lag(|l| {
        l.roll = (l.roll ^ 0x9E37_79B9_7F4A_7C15) | 1;
        l.roll ^= l.roll << 13;
        l.roll ^= l.roll >> 7;
        l.roll ^= l.roll << 17;
        (l.roll >> 11) as f64 / (1u64 << 53) as f64
    });
    let (lo, hi) = (lo.min(hi).max(0.0), lo.max(hi).max(0.0));
    Duration::from_millis((lo + r * (hi - lo)) as u64)
}

fn live(game: &Game<'_>) -> bool {
    game.remote.is_some()
        && game.screen == Screen::Playing
        && !sunset::gui_open()
        && !game.spectator()
        && game.player.as_ref().is_some_and(|p| p.health.health() > 0.0)
}

// Another module owns the outgoing stream this tick: Fake Lag hands it over empty.
fn yielding(mods: &[Module]) -> Option<&'static str> {
    if mods.iter().any(|m| m.name == "Blink" && m.on) {
        return Some("Blink");
    }
    if let Some(owner) = super::sunset_combat_control::owner() {
        return Some(owner);
    }
    super::sunset_gui_move::stopping().then_some("GUI Move")
}

// A player who is not a friend within range; with `facing`, only one you look at (30 degrees) and walk towards.
pub(super) fn enemy(game: &Game<'_>, range: f64, facing: bool) -> bool {
    let (Some(p), Some(eye), Some(me)) = (game.player.as_ref(), game.eye_position(), game.remote.as_ref().map(|r| r.entity_id as u32)) else {
        return false;
    };
    let friends = sunset::with(|s| s.friends.clone());
    let (yaw, pitch) = (f64::from(game.yaw).to_radians(), f64::from(game.pitch).to_radians());
    let look = [-yaw.sin() * pitch.cos(), -pitch.sin(), yaw.cos() * pitch.cos()];
    game.mobs.iter().any(|m| {
        if m.removed || !m.alive() || m.kind.id != "minecraft:player" || m.id == me {
            return false;
        }
        if game.remote_player_name(m.id).is_none_or(|n| friends.iter().any(|f| f.eq_ignore_ascii_case(n))) {
            return false;
        }
        let d = [m.position.x - p.position.x, m.position.y - p.position.y, m.position.z - p.position.z];
        if (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt() > range {
            return false;
        }
        if !facing {
            return true;
        }
        let b = m.bounds();
        let (lo, hi) = (b.min_position(), b.max_position());
        let to = [(lo.x + hi.x) / 2.0 - eye[0], (lo.y + hi.y) / 2.0 - eye[1], (lo.z + hi.z) / 2.0 - eye[2]];
        let len = (to[0] * to[0] + to[1] * to[1] + to[2] * to[2]).sqrt().max(1e-9);
        let dot = (0..3).map(|i| look[i] * to[i] / len).sum::<f64>();
        dot >= 30f64.to_radians().cos() && (p.velocity.x * to[0] + p.velocity.z * to[2]) / len > 0.02
    })
}

fn nearest_enemy(game: &Game<'_>) -> Option<f64> {
    let me = super::sunset_util::player_pos(game)?;
    game.mobs
        .iter()
        .filter(|m| super::sunset_util::player_enemy(game, m))
        .map(|m| super::sunset_util::dist(me, [m.position.x, m.position.y, m.position.z]))
        .min_by(f64::total_cmp)
}

// When this tick's mode wants the line to hold, and how.
fn plan(game: &Game<'_>, m: &Module, now: Instant) -> Option<Plan> {
    let delay = Plan::Latency(Duration::from_millis(m.n("Delay (ms)").clamp(10.0, 1000.0) as u64));
    let gap = Duration::from_millis(m.n("Pulse gap (ms)").max(0.0) as u64);
    let choke = || rolled(m.n("Shortest choke (ms)"), m.n("Longest choke (ms)"));
    match m.p("Mode") {
        "Pulse" => {
            let mut pulse = lag(|l| l.pulse);
            let plan = pulse.step(now, true, choke, gap);
            lag(|l| l.pulse = pulse);
            plan
        }
        "Knockback" => {
            let (mut pulse, knocked) = lag(|l| (l.pulse, std::mem::take(&mut l.knocked)));
            let plan = pulse.step(now, knocked, choke, gap);
            lag(|l| l.pulse = pulse);
            plan
        }
        "Dynamic" => {
            let range = m.n("Range");
            let near = if m.p("Trigger") == "Closing" {
                let d = nearest_enemy(game).filter(|d| *d <= range);
                let was = lag(|l| std::mem::replace(&mut l.dynamic.enemy_was, d));
                d.is_some_and(|d| was.is_none_or(|w| d <= w + 0.01))
            } else {
                enemy(game, range, true)
            };
            lag(|l| l.dynamic.gate.step(near, EXIT_TICKS)).then_some(delay)
        }
        _ => Some(delay),
    }
}

pub(super) fn tick(game: &mut Game<'_>, mods: &[Module]) {
    let now = Instant::now();
    let session = game.remote.as_ref().map(|r| &r.session);
    lag(|l| bind(l, session));
    // A new life or world in the same session: what is held goes first (the server takes no move until the client has
    // accepted where it now is), and the new life starts with nothing held.
    let life = game.remote.as_ref().map(|r| (r.entity_id, game.dim));
    let reanchor = lag(|l| {
        let changed = l.life.is_some() && life.is_some() && l.life != life;
        l.life = life;
        changed && l.line.phase() != Phase::Idle
    });
    if reanchor {
        let n = flush(game, Flush::Reanchor);
        lag(|l| {
            l.line.reset();
            l.pulse.reset();
            note(l, "new life or dimension: sent everything held", n);
        });
    }
    let m = mods.iter().find(|m| m.name == LAG && m.on);
    if let Some(who) = yielding(mods) {
        if pending() {
            let n = flush(game, Flush::Yield);
            lag(|l| note(l, format!("{who} took the outgoing stream: sent everything held"), n));
        }
        lag(|l| {
            l.line.stop();
            l.pulse.reset();
            l.dynamic = Dynamic::default();
            l.knocked = false;
        });
    } else if let Some(m) = m.filter(|_| live(game)) {
        let plan = plan(game, m, now);
        lag(|l| match plan {
            Some(plan) => l.line.hold(plan),
            None => l.line.stop(),
        });
    } else {
        lag(|l| {
            l.line.stop();
            l.pulse.reset();
            l.dynamic = Dynamic::default();
            l.knocked = false;
        });
    }
    lag(|l| {
        l.told = Some(now);
        l.actions = m.is_none_or(|m| m.b("Release on action"));
        l.mode = m.map_or("", |m| m.p("Mode"));
    });
    release(game, now);
}

// Show server position: where the server has you while Fake Lag holds what you send.
pub(super) fn draw(game: &Game<'_>, cam: &Camera, mods: &[Module], out: &mut impl Canvas, lw: f32) {
    if !mods.iter().any(|m| m.name == LAG && m.on && m.b("Show server position")) {
        return;
    }
    let (Some(at), Some(p)) = (lag(|l| l.sent_at.filter(|_| !l.line.is_empty())), game.player.as_ref()) else {
        return;
    };
    let half = f64::from(p.dimensions.width) / 2.0;
    let lo = [at[0] - half, at[1], at[2] - half];
    let hi = [at[0] + half, at[1] + f64::from(p.dimensions.height), at[2] + half];
    super::sunset_visual::draw_box(cam, out, &super::sunset_visual::Look::BOXED, lo, hi, 0xFFFF_5555, lw);
}

// ---------------------------------------------------------------- Debug Report

pub(super) fn report(out: &mut String) {
    let now = Instant::now();
    lag(|l| {
        let s = &l.line.stats;
        let _ = writeln!(out, "\n## Fake Lag (outgoing)");
        let plan = match l.line.plan() {
            Some(Plan::Latency(d)) => format!("each packet {} ms late", d.as_millis()),
            Some(Plan::Until(at)) => format!("choke ends in {} ms", at.saturating_duration_since(now).as_millis()),
            None => "not holding".into(),
        };
        let mode = if l.mode.is_empty() { "module off" } else { l.mode };
        let pulse = if l.pulse.choking() { "; a choke running" } else { "" };
        let _ = writeln!(out, "- State: {} ({mode}; {plan}{pulse}); release on action {}", l.line.phase().name(), if l.actions { "on" } else { "off" });
        let link = l.link.as_ref().map_or("none".to_owned(), |k| format!("session #{} epoch {}", k.serial, k.epoch));
        let _ = writeln!(out, "- Held now: {} packets, oldest {} ms; bound to {link}", l.line.len(), l.line.oldest(now).as_millis());
        let _ = writeln!(out, "- Since start: {} held, {} released; deepest {} packets, longest wait {} ms", s.captured, s.released, s.max_depth, s.max_wait_ms);
        let flushes: Vec<String> =
            line::FLUSHES.iter().zip(s.flushes).filter(|(_, n)| *n > 0).map(|(f, n)| format!("{} {n}", f.name())).collect();
        let _ = writeln!(out, "- Sent at once (times, by reason): {}", if flushes.is_empty() { "none".into() } else { flushes.join(", ") });
        let discards: Vec<String> =
            line::DISCARDS.iter().zip(s.discarded).filter(|(_, n)| *n > 0).map(|(d, n)| format!("{} {n}", d.name())).collect();
        let _ = writeln!(out, "- Thrown away (packets, by reason): {}", if discards.is_empty() { "none".into() } else { discards.join(", ") });
        if s.reordered > 0 {
            let _ = writeln!(out, "- **Reordered by Fake Lag: {} (a bug: it must keep the order)**", s.reordered);
        }
        if !l.notes.is_empty() {
            let _ = writeln!(out, "\n| Time | Tick | Event | Packets |\n|---|---|---|---|");
            for n in l.notes.iter().rev() {
                let at = chrono::DateTime::<chrono::Local>::from(n.at).format("%H:%M:%S%.3f");
                let _ = writeln!(out, "| {at} | {} | {} | {} |", n.tick, n.what, n.packets);
            }
        }
    });
}

// ---------------------------------------------------------------- old settings

// Fake Lag before its line (and Backtrack inside it): Always is Delay, Timed is Pulse, Ranged is Dynamic closing in
// (with its Range choke as the delay), Off was Backtrack alone (Fake Lag off, its key Backtrack's). Backtrack's
// settings are the Backtrack module's, on if Fake Lag was with it, and on the same key.
pub(super) fn migrated(text: Cow<'_, str>) -> Cow<'_, str> {
    let line_of = |l: &str| l.split_once('=').and_then(|(k, v)| k.strip_prefix("fakelag.").map(|f| (f.to_owned(), v.trim().to_owned())));
    let old_mode = |v: &str| matches!(v, "Always" | "Timed" | "Ranged" | "Off");
    let backtrack_field = |f: &str| f.starts_with("backtrack") || matches!(f, "shortestlatencyms" | "longestlatencyms");
    // Range choke was saved as `rangechoke` and, in builds between, `rangechokems`.
    let choke_field = |f: &str| matches!(f, "rangechoke" | "rangechokems");
    let old = text.lines().filter_map(line_of).any(|(f, v)| (f == "mode" && old_mode(&v)) || choke_field(&f) || backtrack_field(&f));
    if !old {
        return text;
    }
    let fields: Vec<(String, String)> = text.lines().filter_map(line_of).collect();
    let get = |f: &str| fields.iter().rev().find(|(k, _)| k == f).map(|(_, v)| v.as_str());
    let mode = get("mode").unwrap_or("Dynamic");
    let backtrack = get("backtrack") == Some("true");
    let mut out: Vec<String> = text
        .lines()
        .filter(|l| line_of(*l).is_none_or(|(f, _)| f != "mode" && !choke_field(&f) && !backtrack_field(&f)))
        .map(str::to_owned)
        .collect();
    let (new_mode, off) = match mode {
        "Always" => ("Delay", false),
        "Timed" => ("Pulse", false),
        "Ranged" => ("Dynamic", false),
        "Off" => ("Delay", true),
        other => (other, false),
    };
    out.push(format!("fakelag.mode={new_mode}"));
    if mode == "Ranged" {
        out.push("fakelag.trigger=Closing".into());
        if let Some(choke) = get("rangechoke").or_else(|| get("rangechokems")) {
            out.push(format!("fakelag.delayms={choke}"));
        }
    }
    if off {
        out.push("fakelag.on=false".into());
    }
    if backtrack && !text.lines().any(|l| l.starts_with("backtrack.")) {
        // A profile that leaves Fake Lag's switch alone leaves Backtrack's too.
        if let Some(on) = get("on") {
            out.push(format!("backtrack.on={on}"));
        }
        if let Some(key) = get("key").filter(|k| *k != "none") {
            out.push(format!("backtrack.key={key}"));
            if let Some(bind) = get("bindmode") {
                out.push(format!("backtrack.bindmode={bind}"));
            }
            if off {
                out.push("fakelag.key=none".into());
            }
        }
        for (old, new) in [
            ("backtrackminrange", "minrange"),
            ("backtrackmaxrange", "maxrange"),
            ("shortestlatencyms", "shortestlatencyms"),
            ("longestlatencyms", "longestlatencyms"),
            ("backtrackweapononly", "weapononly"),
            ("showserverposition", "showserverposition"),
        ] {
            if let Some(v) = get(old) {
                out.push(format!("backtrack.{new}={v}"));
            }
        }
    }
    Cow::Owned(out.join("\n"))
}

#[cfg(test)]
