// ---- Chest Stealer and Inventory Manager

// How many slots a server's container menu has, for the ones that are just a grid of items.
fn container_size(menu: &str) -> Option<usize> {
    let name = menu.strip_prefix("minecraft:").unwrap_or(menu);
    match name {
        "shulker_box" | "generic_9x3" => Some(27),
        "hopper" => Some(5),
        "generic_3x3" => Some(9),
        _ => name.strip_prefix("generic_9x")?.parse::<usize>().ok().map(|rows| rows * 9),
    }
}

fn auto_steal(game: &mut Game<'_>, m: &Module) {
    use horizon_client::menu::Input::QuickMove;
    if game.screen != Screen::Inventory {
        // Closed: the next chest starts afresh.
        ps(|p| p.steal_done = i32::MIN);
        return;
    }
    // Carts from shulkers (a cart PvP restock): only TNT minecarts, only out of shulker boxes.
    let carts = m.p("Take") == "Carts from shulkers";
    let shulker = match game.container {
        Some(key) => super::sunset_util::facts(game, [key.0, key.1, key.2]).name.ends_with("shulker_box"),
        None => game.remote_menu().1.strip_prefix("minecraft:") == Some("shulker_box"),
    };
    if carts && !shulker {
        return;
    }
    // A chest of your own world, or the menu a server opened.
    let (id, size) = match game.container {
        Some(key) if matches!(game.container_kind(), Some(super::BlockEntity::Chest(_))) => {
            (key.0 ^ key.1.rotate_left(10) ^ key.2.rotate_left(20) | 1, game.container_size())
        }
        Some(_) => return,
        None => {
            let (id, menu) = game.remote_menu();
            match container_size(&menu) {
                Some(n) => (id, n),
                None => return,
            }
        }
    };
    // With a Steal key, only while it is held.
    let key = m.t("Steal key") != "None";
    if ps(|p| p.steal_done == id) || (key && !super::sunset_util::setting_key_down(game, m, "Steal key")) || ps(|p| {
        p.steal_wait = p.steal_wait.saturating_sub(1);
        p.steal_wait > 0
    }) {
        return;
    }
    let items: Vec<usize> =
        (0..size).filter(|&i| game.slot_mut(300 + i).as_ref().is_some_and(|s| !carts || &*s.item == "minecraft:tnt_minecart")).collect();
    // Done when there is nothing to take, or when taking stopped changing it (your inventory is full). Close when
    // done shuts the container then.
    let stuck = ps(|p| {
        p.steal_same = if p.steal_id == id && p.steal_last == items.len() { p.steal_same + 1 } else { 0 };
        (p.steal_id, p.steal_last) = (id, items.len());
        p.steal_same >= 6
    });
    if items.is_empty() || stuck {
        ps(|p| p.steal_done = id);
        if m.b("Close when done") {
            super::sunset_combat_inventory::close_inventory(game);
        }
        return;
    }
    let ops: Vec<_> = items.iter().take(m.n("Items per tick") as usize).map(|&i| (Some(300 + i), 0, QuickMove)).collect();
    game.menu_ops(&ops);
    ps(|p| p.steal_wait = m.n("Delay (ticks)") as u32);
}

// Inventory Manager's presets: name, then the blocks, food, arrows and pearls kept, and the junk.
const PRESETS: [(&str, f64, f64, f64, f64, &str); 4] = [
    ("PvP", 128.0, 64.0, 64.0, 16.0, "dirt,gravel,sand,rotten_flesh,spider_eye,poisonous_potato,wheat_seeds,bone,string,feather,flint,stick,egg"),
    ("Building", 1728.0, 32.0, 0.0, 16.0, "rotten_flesh,spider_eye,poisonous_potato,wheat_seeds,bone,string,feather,flint,egg"),
    ("Mining", 64.0, 64.0, 0.0, 0.0, "dirt,gravel,cobblestone,cobbled_deepslate,netherrack,andesite,diorite,granite,tuff,rotten_flesh,spider_eye,poisonous_potato,wheat_seeds"),
    ("Survival", 256.0, 128.0, 128.0, 16.0, "rotten_flesh,spider_eye,poisonous_potato"),
];

// A stack as Inventory Manager's planner sees it, from the game's item data.
pub(super) fn plan_item(game: &Game<'_>, stack: &horizon_client::items::ItemStack) -> plan::Item {
    let info = game.res.items().get(&stack.item);
    let modifier = |attribute: &str| {
        info.as_ref().map_or(0.0, |i| i.modifiers.iter().filter(|m| m.0 == attribute).map(|m| m.2 as f32).sum::<f32>())
    };
    let mining = info.as_ref().map_or(1.0, |i| i.tool.iter().filter_map(|r| r.speed).fold(i.tool_default_speed.max(1.0), f32::max));
    plan::Item {
        name: short(&stack.item).to_owned(),
        count: stack.count,
        attack: info.as_ref().map_or(0.0, |i| i.attack_damage),
        speed: 4.0 + info.as_ref().map_or(0.0, |i| i.attack_speed),
        armor: modifier("minecraft:armor"),
        toughness: modifier("minecraft:armor_toughness"),
        mining,
        damage: stack.damage,
        max_damage: info.as_ref().map_or(0, |i| i.max_damage),
        enchants: stack.enchantments().iter().map(|(e, l)| (e.to_string(), *l)).collect(),
        named: stack.custom_name().is_some(),
        block: info.as_ref().and_then(|i| i.block).is_some_and(|b| game.res.facts().get(b).full_collision),
        food: info.as_ref().and_then(|i| i.food).map_or(0.0, |(nutrition, saturation)| nutrition as f32 + saturation),
        max_stack: info.as_ref().map_or(64, |i| i.max_stack),
        meta: component_fingerprint(stack),
    }
}

// Network Wire bookkeeping includes the original stack count; bundle selection is runtime-only. Neither belongs
// in component equality. Use Horizon's saved component representation, with canonical compound ordering.
fn component_fingerprint(stack: &horizon_client::items::ItemStack) -> u64 {
    use std::hash::{Hash, Hasher};
    horizon_client::item_data::encode_components(stack).map_or(0, |tag| {
        let mut h = std::collections::hash_map::DefaultHasher::new();
        horizon_client::item_data::canon_tag(&tag).hash(&mut h);
        h.finish() | 1
    })
}

#[cfg(test)]
mod inventory_data_tests {
    use super::component_fingerprint;
    use horizon_client::{item_data::Wire, items::ItemStack};
    use std::sync::Arc;

    #[test]
    fn network_bookkeeping_does_not_split_compatible_stacks() {
        let mut a = ItemStack::new("minecraft:stone", 10);
        let original_a = a.clone();
        a.data_mut().wire = Wire::new(original_a, Arc::from([1u8]));
        let mut b = ItemStack::new("minecraft:stone", 20);
        let original_b = b.clone();
        b.data_mut().wire = Wire::new(original_b, Arc::from([2u8]));
        assert!(a.same_item_same_components(&b));
        assert_eq!(component_fingerprint(&a), component_fingerprint(&b));
        b.enchant("minecraft:sharpness", 2);
        assert_ne!(component_fingerprint(&a), component_fingerprint(&b));
        let before = component_fingerprint(&b);
        b.enchant("minecraft:sharpness", 3);
        assert_ne!(before, component_fingerprint(&b), "changes inside existing extra data invalidate plans too");
    }
}

// Explicit junk plus conservative whole-stack quotas. The planner already built the item snapshot and retention.
fn junk_slots(m: &Module, items: &[Option<plan::Item>], keep: &[bool]) -> Vec<usize> {
    let mut remaining = items.to_vec();
    let mut out = Vec::new();
    for (i, item) in items.iter().enumerate() {
        if item.as_ref().is_some_and(|s| listed(m.t("Junk"), &s.name)) && !keep[i] {
            out.push(i);
            remaining[i] = None;
        }
    }
    out.extend(plan::quota_excess(&remaining, keep, ["Blocks", "Food", "Arrows", "Pearls"].map(|key| m.n(key) as u32)));
    out
}

// Inventory Manager: one step at a time, Delay apart: first the hotbar layout, then a junk stack or a worse
// duplicate dropped, then a swap toward the sorted inventory. Each step is planned from the inventory as it is now
// (inventory_plan.rs), so a refused click or a change from elsewhere is planned around. Nothing moves while GUI Move
// holds clicks, another module has the hand (combat_control), or in a slot Loadouts locks; armour you wear is Auto
// Armor's and the offhand Offhand's.
fn inventory_manager(game: &mut Game<'_>, m: &Module) {
    use horizon_client::menu::Input::{Pickup, Swap, Throw};
    if super::sunset_gui_move::inventory_busy() { return; }
    // A preset just picked fills in its limits and junk (not on the first look, so a change you made stays).
    let preset = m.p("Preset");
    let before = ps(|p| std::mem::replace(&mut p.clean_preset, preset.to_owned()));
    if !before.is_empty() && before != preset
        && let Some(&(_, blocks, food, arrows, pearls, junk)) = PRESETS.iter().find(|p| p.0 == preset)
    {
        for (field, value) in [("blocks", blocks.to_string()), ("food", food.to_string()), ("arrows", arrows.to_string()),
            ("pearls", pearls.to_string()), ("junk", junk.to_owned())]
        {
            super::sunset::set_setting(game, &format!("inventorymanager.{field}"), &value);
        }
        return;
    }
    let menu = game.remote_menu();
    let in_screen = game.screen == Screen::Inventory && menu.0 == 0 && menu.1 == "inventory";
    // Off the screen: only with no other menu open (the player inventory's clicks need no screen on the server).
    let closed = !m.b("Only in inventory") && game.screen == Screen::Playing && menu.0 == 0 && menu.1 == "inventory";
    if !(in_screen || closed) {
        // Invalidate decisions without shortening the settle deadline of an outstanding click.
        exec(|e| e.context(u64::MAX));
        return;
    }
    let now = game.ticks;
    // You first: a button down on the screen (a click of yours that came and went between ticks is told by
    // `inventory_clicked`), or an item in use.
    let clicking = game.physical_buttons.contains(&MouseButton::Left) || game.physical_buttons.contains(&MouseButton::Right);
    if clicking || (closed && (game.left || game.right)) {
        exec(|e| e.user(now));
        return;
    }
    if game.using.is_some() {
        exec(|e| e.hold(now + 1));
        return;
    }
    let mut locked = super::sunset_loadouts::locked_slots();
    let loot = in_screen && super::sunset_refill::looting(m);
    let fingerprint = inventory_fingerprint(game);
    let context = inventory_context(game, m, &locked, loot);
    exec(|e| e.context(context));
    // An item on the cursor: the player's is left alone (nothing else moves until it is put down); the manager's own,
    // left by a refused click of a Merge, goes back before anything else.
    if game.carried.is_some() {
        match exec(|e| e.owns_cursor()) {
            Some(origin) => put_back(game, origin, &locked, fingerprint),
            None => exec(|e| e.user(now)),
        }
        return;
    }
    exec(|e| e.cursor_empty(now));
    if exec(|e| e.gate(now, fingerprint)) == Gate::Wait || super::sunset_combat_control::owner().is_some() {
        return;
    }
    // A correction can refuse one operation without blocking all other work. Protect its slots until contents or
    // settings change, so a refused hotbar placement cannot turn into a destructive cleanup of that same item.
    let unavailable = exec(|e| {
        let mut slots: Vec<usize> = e.blocked(fingerprint).into_iter().flat_map(|s| s.slots().into_iter().flatten()).collect();
        slots.extend(e.reserved(now));
        slots
    });
    for i in unavailable {
        if let Some(l) = locked.get_mut(i) {
            *l = true;
        }
    }
    let started = std::time::Instant::now();
    let step = if loot {
        super::sunset_refill::loot_step(game, m, &locked).map(Step::Throw)
    } else {
        plan_step(game, m, preset, &locked)
    };
    let took = started.elapsed();
    let Some(step) = exec(|e| e.planned(fingerprint, step, took)) else {
        return;
    };
    // A Merge holds the stack on the cursor between its clicks: it goes only once everything sent before it has been
    // confirmed, so it never starts on a cursor the server has not emptied.
    if step.cursor() && !exec(|e| e.exclusive(now)) {
        return;
    }
    // Its clicks go straight out (past GUI Move's GrimAC queue, which would hold them until the inventory closes), so
    // only while you stand still: a click while moving is what anticheats look for. Moving, it waits.
    if !super::remote::sunset_combat_remote::quiet(game) {
        return;
    }
    // Two slots change places through a hotbar slot by hotbar-key swaps, never by picking items up: a refused click
    // then leaves every item in a slot rather than on the cursor, and a bundle never takes in the other stack.
    let via = match step {
        Step::Exchange(a, b) if a >= 9 && b >= 9 => {
            let empty: [bool; 9] = std::array::from_fn(|h| game.inventory.get(h).is_none_or(|s| s.is_none()));
            let held: [bool; 9] = std::array::from_fn(|h| locked[h]);
            let Some(via) = plan::pivot(empty, held, game.selected) else { return };
            Some(via)
        }
        _ => None,
    };
    let clicks: Vec<(Option<usize>, i32, horizon_client::menu::Input)> = match step {
        Step::Swap { from, to } => vec![(Some(from), to as i32, Swap)],
        Step::Throw(i) => vec![(Some(i), 1, Throw)],
        Step::Exchange(a, b) => plan::exchange_swaps(a, b, via.unwrap_or(0), |i| game.inventory.get(i).is_none_or(|s| s.is_none()))
            .into_iter()
            .map(|(slot, key)| (Some(slot), key as i32, Swap))
            .collect(),
        Step::Merge { from, into } => vec![(Some(from), 0, Pickup), (Some(into), 0, Pickup), (Some(from), 0, Pickup)],
        Step::Place(_) => return,
    };
    if !super::sunset_gui_move::direct(|| game.remote_menu_ops(&clicks)) { return; }
    // rand() takes the PS lock itself: rolled here, outside any ps() or exec() closure.
    let delay = m.n("Delay (ticks)") as u64 + rand(m.n("Delay variation") as usize + 1) as u64;
    let latency = super::remote::sunset_combat_remote::latency(game);
    if step.cursor() {
        // Nothing follows it until the server's answer is in: a round trip, at least Delay.
        exec(|e| e.sent(step, fingerprint, now, super::sunset_inventory_exec::settle_ticks(latency, delay)));
    } else {
        exec(|e| e.sent_predicted(step, via, fingerprint, now, delay, latency));
    }
}

// The stack the manager left on the cursor goes into a slot that takes it (`place_target`): where it came from, a
// stack of the same item, an empty slot. One click, settled for a round trip before anything else; a slot refused once
// is not tried again on the same inventory. With no slot left it is the player's, and they are told.
fn put_back(game: &mut Game<'_>, origin: Option<usize>, locked: &[bool; 36], fingerprint: u64) {
    let now = game.ticks;
    if !exec(|e| e.settle(now, fingerprint) && e.exclusive(now)) {
        return;
    }
    // The Merge that left it there is not tried again on its inventory.
    exec(|e| e.stranded());
    if !super::remote::sunset_combat_remote::quiet(game) {
        return;
    }
    let Some(carried) = game.carried.as_ref().map(|s| plan_item(game, s)) else { return };
    let items: Vec<Option<plan::Item>> = (0..36).map(|i| game.inventory.get(i).and_then(|s| s.as_ref()).map(|s| plan_item(game, s))).collect();
    let refused: Vec<usize> = exec(|e| e.blocked(fingerprint)).into_iter().filter_map(|s| match s { Step::Place(i) => Some(i), _ => None }).collect();
    let Some(target) = plan::place_target(&items, &carried, origin, locked, game.selected, &refused) else {
        exec(|e| e.disown_cursor());
        report(game, "Inventory Manager: an item it moved is left on the cursor, and no slot takes it.");
        return;
    };
    if !super::sunset_gui_move::direct(|| game.remote_menu_ops(&[(Some(target), 0, horizon_client::menu::Input::Pickup)])) {
        return;
    }
    let settle = super::sunset_inventory_exec::settle_ticks(super::remote::sunset_combat_remote::latency(game), 1);
    exec(|e| e.sent(Step::Place(target), fingerprint, now, settle));
}

// A click on the inventory that is not the manager's (yours, through the game's screen, or another module's): what
// the cursor holds is no longer the manager's to put back, and it waits a moment.
pub(super) fn inventory_clicked(now: u64) {
    exec(|e| e.user(now));
}

// Whether the manager's action cadence or another owner's explicit hold still blocks clicks at `now`.
pub(super) fn inventory_stepping(now: u64) -> bool {
    exec(|e| e.busy(now))
}

// Auto Armor clicked: its separate delay/settle policy holds Inventory Manager until `until`.
pub(super) fn inventory_hold(until: u64) {
    exec(|e| e.hold(until));
}

pub(super) fn inventory_reset() {
    exec(|e| e.reset());
}

// Inventory Manager's executor state (inventory_exec.rs). Its closures only read and write it: no game call, no other
// lock is taken inside.
static EXEC: Mutex<Option<super::sunset_inventory_exec::Exec>> = Mutex::new(None);

fn exec<R>(f: impl FnOnce(&mut super::sunset_inventory_exec::Exec) -> R) -> R {
    f(EXEC.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Default::default))
}

// Include component values: two different enchanted/custom stacks may both have `extra`. State-id-only updates
// are not changed contents, and must not restart retries of a refused operation.
fn inventory_fingerprint(game: &Game<'_>) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = std::collections::hash_map::DefaultHasher::new();
    for stack in game.inventory.iter().take(36).chain(game.armor.iter()) {
        match stack {
            Some(s) => {
                (&*s.item, s.count, s.damage).hash(&mut h);
                component_fingerprint(s).hash(&mut h);
            }
            None => 0u8.hash(&mut h),
        }
    }
    h.finish()
}

fn inventory_context(game: &Game<'_>, m: &Module, locked: &[bool; 36], loot: bool) -> u64 {
    use std::hash::{Hash, Hasher};
    use super::sunset::Value;
    let mut h = std::collections::hash_map::DefaultHasher::new();
    for setting in &m.settings {
        setting.name.hash(&mut h);
        match &setting.value {
            Value::Bool(b) => b.hash(&mut h),
            Value::Num { v, .. } => v.to_bits().hash(&mut h),
            Value::Pick { i, .. } => i.hash(&mut h),
            Value::Text(t) => t.hash(&mut h),
        }
    }
    locked.hash(&mut h);
    loot.hash(&mut h);
    (game.screen == Screen::Inventory).hash(&mut h);
    super::sunset::with(|s| s.module("Kill Aura").map(|k| k.p("Combat version"))).hash(&mut h);
    // Auto combat mode can change via server attributes without changing any stack.
    let legacy = super::sunset_aura_timing::version("Auto", game.main_hand_attack_speed()).0 == super::sunset_aura_timing::Version::Legacy;
    legacy.hash(&mut h);
    h.finish()
}

// The next step for the inventory as it is: the hotbar plan first; then, with what must stay worked out first (the
// hotbar's picks, protected and Loadouts' slots, the best of each kind and its backups, specialised, named and
// unknown items), junk, items past their limits and excess duplicates; then merging and sorting.
fn plan_step(game: &Game<'_>, m: &Module, preset: &str, locked: &[bool; 36]) -> Option<Step> {
    let items: Vec<Option<plan::Item>> = (0..36).map(|i| game.inventory.get(i).and_then(|s| s.as_ref()).map(|s| plan_item(game, s))).collect();
    let kill_aura = super::sunset::with(|s| s.module("Kill Aura").map(|k| k.p("Combat version")).unwrap_or("Auto"));
    let legacy = super::sunset_aura_timing::version(kill_aura, game.main_hand_attack_speed()).0 == super::sunset_aura_timing::Version::Legacy;
    let slot_words: [&str; 9] = std::array::from_fn(|i| m.p(["Slot 1", "Slot 2", "Slot 3", "Slot 4", "Slot 5", "Slot 6", "Slot 7", "Slot 8", "Slot 9"][i]));
    let wants = plan::wants(slot_words, m.t("Hotbar layout"));
    let hotbar = plan::plan_hotbar(&items, &wants, locked, legacy);
    if let Some((h, from)) = (0..9).find_map(|h| hotbar[h].filter(|&from| from != h).map(|from| (h, from))) {
        return Some(Step::Swap { from, to: h });
    }
    // Retention first: what nothing may drop.
    let mut keep: Vec<bool> = (0..36)
        .map(|i| locked[i] || items[i].as_ref().is_none_or(|s| plan::never_drop(s) || listed(m.t("Protected items"), &s.name)))
        .collect();
    for i in hotbar.iter().flatten() {
        keep[*i] = true;
    }
    let mut drop: Vec<usize> = if preset == "Custom" {
        (0..36).filter(|&i| items[i].as_ref().is_some_and(|s| passes(m, "Items", &s.name))).collect()
    } else {
        junk_slots(m, &items, &keep)
    };
    if m.b("Duplicates") {
        let worn: [Option<plan::Item>; 4] = std::array::from_fn(|a| game.armor.get(a).and_then(|s| s.as_ref()).map(|s| plan_item(game, s)));
        drop.extend(plan::excess(&items, &worn, &keep, legacy, plan::Retention::named(m.p("Retention"))));
    }
    if let Some(i) = drop.into_iter().filter(|&i| !keep[i]).min() {
        return Some(Step::Throw(i));
    }
    if m.b("Merge stacks")
        && let Some((from, into)) = plan::merge_step(&items, locked)
    {
        return Some(Step::Merge { from, into });
    }
    if m.b("Sort inventory") {
        return plan::sort_step(&items, 9..36, locked).map(|(a, b)| Step::Exchange(a, b));
    }
    None
}

// The Debug Report's Inventory Manager line: how often it planned, skipped an unchanged inventory, stepped, and how
// long its planning took.
pub(super) fn inventory_report(out: &mut String) {
    use std::fmt::Write;
    let s = exec(|e| e.stats);
    let mean = if s.plans == 0 { 0 } else { (s.plan_total / s.plans as u32).as_micros() };
    let _ = writeln!(out, "- Inventory Manager: {} plans (mean {mean} us, most {} us), {} unchanged ticks skipped, {} steps, {} refused",
        s.plans, s.plan_most.as_micros(), s.skipped, s.steps, s.refused);
}

// ---- Anti AFK (Sunset's AntiAFK)

// Wander, Anti AFK: once none of your move keys has been held for a
// random Start delay, every few seconds at random (Frequency) a small visible turn at a random speed (at most Max yaw
// and Max pitch change) and a short walk, a tenth to a fifth of a second, toward a point within a block. Keep close
// walks back and turns back once it has drifted from where it started. Times in ticks.
#[derive(Default)]
struct Wander {
    idle_since: Option<u64>,
    delay: u64,
    next_walk: u64,
    next_turn: u64,
    walked_at: u64,
    turned_at: u64,
    // Where you were and how you looked when it began.
    origin: Option<([f64; 2], f32, f32)>,
    // The point it walks to, from when, for how long.
    walk: Option<([f64; 2], u64, u64)>,
    // The look it turns to and its speed, degrees a tick.
    turn: Option<(f32, f32, f32)>,
}

fn unit() -> f64 {
    rand(1_000_000) as f64 / 1e6
}

fn wrap180(a: f32) -> f32 {
    (a + 180.0).rem_euclid(360.0) - 180.0
}

// The move keys from `at` toward `to` with this yaw (Sunset's keys_towards).
fn keys_towards(at: [f64; 2], yaw: f32, to: [f64; 2]) -> Vec<KeyCode> {
    let (dx, dz) = (to[0] - at[0], to[1] - at[1]);
    if dx.hypot(dz) < 0.1 {
        return Vec::new();
    }
    let rad = f64::from(yaw).to_radians();
    let forward = -rad.sin() * dx + rad.cos() * dz;
    let left = rad.cos() * dx + rad.sin() * dz;
    let edge = 0.3 * dx.hypot(dz);
    [(forward > edge, KeyCode::KeyW), (forward < -edge, KeyCode::KeyS), (left > edge, KeyCode::KeyA), (left < -edge, KeyCode::KeyD)]
        .into_iter()
        .filter_map(|(held, k)| held.then_some(k))
        .collect()
}

// One tick of Wander: the keys to hold, and the view turned a step.
fn wander(game: &mut Game<'_>, m: &Module) -> Vec<KeyCode> {
    let Some(p) = game.player.as_ref() else {
        return Vec::new();
    };
    let at = [p.position.x, p.position.z];
    let now = game.ticks;
    let yours = [KeyCode::KeyW, KeyCode::KeyA, KeyCode::KeyS, KeyCode::KeyD].iter().any(|k| game.physical_keys.contains(k));
    let mut w = ps(|p| std::mem::take(&mut p.afk_wander));
    if yours || w.idle_since.is_none() {
        let (lo, hi) = (m.n("Shortest start delay (s)"), m.n("Longest start delay (s)"));
        let delay = ((lo + unit() * (hi - lo).max(0.0)) * 20.0) as u64;
        w = Wander { idle_since: Some(now), delay, next_walk: delay, next_turn: delay, walked_at: now, turned_at: now, ..Wander::default() };
        ps(|p| p.afk_wander = w);
        return Vec::new();
    }
    let mut keys = Vec::new();
    if now.saturating_sub(w.idle_since.unwrap_or(now)) >= w.delay {
        // Up to a second plus the Frequency's interval between one and the next.
        let interval = 20 + (20.0 / m.n("Frequency").max(0.1)) as usize;
        let (yaw, pitch) = (game.yaw, game.pitch);
        if m.b("Turn") && in_world(game) && now.saturating_sub(w.turned_at) >= w.next_turn {
            w.origin.get_or_insert((at, yaw, pitch));
            w.next_turn = rand(interval) as u64;
            w.turned_at = now;
            let (most_yaw, most_pitch) = (m.n("Max yaw change"), m.n("Max pitch change"));
            let drifted = match (m.b("Keep close"), w.origin) {
                (true, Some((_, y, p))) => f64::from(wrap180(yaw - y).hypot(wrap180(pitch - p))) >= most_yaw.hypot(most_pitch),
                _ => false,
            };
            let mut dy = unit() * most_yaw;
            let mut dp = unit() * most_pitch;
            if unit() > 0.6 {
                dy = -dy;
            }
            if unit() > 0.5 {
                dp = -dp;
            }
            let to = match w.origin {
                Some((_, y, p)) if drifted => (y, p),
                _ => (yaw + dy as f32, (pitch + dp as f32).clamp(-90.0, 90.0)),
            };
            w.turn = Some((to.0, to.1, (unit() * 10.0).max(1.0) as f32));
        }
        if let Some((ty, tp, speed)) = w.turn {
            let (dy, dp) = (wrap180(ty - yaw), tp - pitch);
            game.yaw += dy.clamp(-speed, speed);
            game.pitch = (game.pitch + dp.clamp(-speed, speed)).clamp(-90.0, 90.0);
            if dy.abs() <= speed && dp.abs() <= speed {
                w.turn = None;
            }
        }
        match w.walk {
            None if now.saturating_sub(w.walked_at) >= w.next_walk => {
                w.origin.get_or_insert((at, yaw, pitch));
                w.next_walk = rand(interval) as u64;
                let mut to = [at[0] + unit() * 2.0 - 1.0, at[1] + unit() * 2.0 - 1.0];
                if let (true, Some((origin, _, _))) = (m.b("Keep close"), w.origin)
                    && (origin[0] - at[0]).hypot(origin[1] - at[1]) >= 0.75
                {
                    to = origin;
                }
                w.walk = Some((to, now, 2 + rand(3) as u64));
                w.walked_at = now;
            }
            Some((_, since, ticks)) if now.saturating_sub(since) >= ticks => w.walk = None,
            _ => {}
        }
        if let Some((to, _, _)) = w.walk {
            keys = keys_towards(at, game.yaw, to);
        }
    }
    ps(|p| p.afk_wander = w);
    keys
}

// The keys it holds this tick: Wander's walk; or, in Meteor mode, a jump now and then, sneaking, and strafing left
// and right.
pub(super) fn afk_keys(game: &mut Game<'_>, m: &Module) -> Vec<KeyCode> {
    if m.p("Mode") == "Wander" {
        return wander(game, m);
    }
    let mut keys = Vec::new();
    if m.b("Jump") {
        // rand takes the same lock as ps: roll first, or the game freezes.
        let roll = rand(99) == 0;
        let jump = ps(|p| {
            p.afk_jump = !p.afk_jump && roll;
            p.afk_jump
        });
        if jump {
            keys.push(KeyCode::Space);
        }
    }
    if m.b("Sneak") {
        let sneak = ps(|p| {
            let held = p.afk_sneak < m.n("Sneak time") as u32;
            p.afk_sneak += 1;
            held
        });
        if sneak {
            keys.push(KeyCode::ShiftLeft);
        } else if rand(99) == 0 {
            ps(|p| p.afk_sneak = 0);
        }
    }
    if m.b("Strafe") {
        let key = ps(|p| {
            p.afk_strafe -= 1;
            if p.afk_strafe <= 0 {
                p.afk_key = Some(if p.afk_right { KeyCode::KeyD } else { KeyCode::KeyA });
                p.afk_right = !p.afk_right;
                p.afk_strafe = 20;
            }
            p.afk_key
        });
        keys.extend(key);
    }
    keys
}

fn anti_afk(game: &mut Game<'_>, m: &Module) {
    if !in_world(game) {
        return;
    }
    let meteor = m.p("Mode") == "Meteor";
    if meteor && m.b("Swing") && rand(99) == 0 {
        game.swing_arm();
        game.send(S::Punch(Empty));
    }
    if meteor && m.b("Spin") {
        let yaw = ps(|p| {
            let y = p.afk_yaw.unwrap_or(game.yaw) + m.n("Speed") as f32;
            p.afk_yaw = Some(y);
            y
        });
        if m.p("Spin mode") == "Client" {
            game.yaw = yaw;
        } else {
            super::sunset::turn("Anti AFK", yaw, m.n("Pitch") as f32);
        }
    }
    if m.b("Send messages") {
        let messages: Vec<&str> = m.t("Messages").split('|').map(str::trim).filter(|s| !s.is_empty()).collect();
        if messages.is_empty() {
            return;
        }
        let due = ps(|p| {
            p.afk_message -= 1;
            p.afk_message <= 0
        });
        if due {
            let i = if m.b("Random") {
                rand(messages.len())
            } else {
                ps(|p| {
                    p.afk_index = (p.afk_index + 1) % messages.len();
                    p.afk_index
                })
            };
            game.send_chat(messages[i]);
            ps(|p| p.afk_message = m.n("Delay (seconds)") as i32 * 20);
        }
    }
}

// ---- Spam

fn spam(game: &mut Game<'_>, m: &Module) {
    if game.remote.is_none() {
        toggle_off(game, "Spam");
        return;
    }
    if ps(|p| {
        if p.spam_timer > 0 {
            p.spam_timer -= 1;
            true
        } else {
            false
        }
    }) {
        return;
    }
    let messages: Vec<&str> = m.t("Messages").split('|').map(str::trim).filter(|s| !s.is_empty()).collect();
    if messages.is_empty() {
        return;
    }
    let i = if m.b("Randomise") {
        rand(messages.len())
    } else {
        ps(|p| {
            let i = p.spam_index % messages.len();
            p.spam_index = i + 1;
            i
        })
    };
    let mut text = messages[i].to_owned();
    if m.b("Bypass") {
        const LETTERS: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
        text.push(' ');
        for _ in 0..m.n("Bypass length") as usize {
            text.push(LETTERS[rand(LETTERS.len())] as char);
        }
    }
    text.truncate(256);
    game.send_chat(&text);
    ps(|p| p.spam_timer = m.n("Delay (ticks)") as u32);
    // Once: one message (or /command) as it turns on, then off (a kit or warp on a key).
    if m.b("Once") {
        toggle_off(game, "Spam");
    }
}

// ---- No Fall (Sunset's NoFall): Air place and Place, and Clutch's place under Packet and No ground. Those two change
// the move packets (runtime_packets.rs's outgoing). This runs after the tick, once its move packet has gone, when the player uses
// the item.

// Place's choices: the item, and whether it is a bucket (used, and picked back up) or a block (placed).
const FALL_ITEMS: [(&str, &str, bool); 5] = [
    ("Bucket", "water_bucket", true),
    ("Powder snow", "powder_snow_bucket", true),
    ("Hay bale", "hay_block", false),
    ("Cobweb", "cobweb", false),
    ("Slime block", "slime_block", false),
];

fn no_fall(game: &mut Game<'_>, m: &Module) {
    let Some(p) = game.player.as_ref() else {
        return;
    };
    if game.creative || p.flying || (m.b("Pause on mace") && game.held().is_some_and(|s| short(&s.item) == "mace")) {
        return;
    }
    match m.p("Mode") {
        "Air place" => fall_air_place(game, m),
        "Place" => fall_place(game, m),
        _ if m.b("Clutch") => fall_place(game, m),
        _ => {}
    }
}

// Air place: a block under you once the fall would hurt (Before damage) or kill (Before death).
fn fall_air_place(game: &mut Game<'_>, m: &Module) {
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let fallen = p.fall_distance;
    let health = f64::from(p.health.health() + p.health.absorption());
    let due = if m.p("Air place mode") == "Before damage" { fallen > 2.0 } else { fallen > health.max(2.0) };
    if !due {
        return;
    }
    let Some(slot) = (0..9).find(|&i| super::sunset::item_info(game, i).is_some_and(|info| info.block.is_some())) else {
        return;
    };
    if m.b("Anchor") {
        center_player(game);
    }
    if let Some(at) = block_pos(game) {
        place_block(game, [at[0], at[1] - 1, at[2]], slot, m.b("Rotate"), true);
    }
}

// Place: water (or what Placed item says) where the fall will land, a moment before it does; once you have stood
// still for two ticks, the water or powder snow goes back in the bucket.
fn fall_place(game: &mut Game<'_>, m: &Module) {
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let (vy, fallen, still) = (p.velocity.y, p.fall_distance, p.fall_distance == 0.0 && p.ground.on_ground);
    if let Some((at, item, timer, stood, seen)) = ps(|s| s.fall_placed) {
        let stood = if still { (stood + 1).min(2) } else { 0 };
        let there = facts(game, at);
        let present = if item == "water_bucket" { there.fluid_level == 8 && there.name.ends_with("water") } else { there.name.ends_with("powder_snow") };
        // Gone once it was there (it was picked up, or flowed away), or never there in a second.
        let mut done = (seen && !present) || timer > 20;
        if stood >= 2 && present {
            if let (Some(slot), Some(eye)) = (find_hotbar(game, |n| n == "bucket"), game.eye_position()) {
                let (yaw, pitch) = look_at(eye, center_of(at));
                use_held(game, slot, yaw, pitch);
            }
            done = true;
        }
        ps(|s| s.fall_placed = (!done).then_some((at, item, timer + 1, stood, seen || present)));
        return;
    }
    if vy >= 0.0 || (fallen <= 3.0 && vy > -0.6) || p.fluids.was_touching_water {
        return;
    }
    let chosen = m.p("Placed item");
    // Water boils away in the Nether: powder snow instead.
    let chosen = if chosen == "Bucket" && game.dim.id() == "minecraft:the_nether" { "Powder snow" } else { chosen };
    let Some(&(_, item, bucket)) = FALL_ITEMS.iter().find(|i| i.0 == chosen) else {
        return;
    };
    let Some(slot) = find_hotbar(game, |n| n == item) else {
        return;
    };
    if m.b("Anchor") {
        center_player(game);
    }
    let (Some((ground, point)), Some(eye)) = (landing(game), game.eye_position()) else {
        return;
    };
    // The use reaches as far as a click does (4.5 blocks); further up, it waits for a later tick.
    if dist(eye, point) > 4.5 {
        return;
    }
    let above = [ground[0], ground[1] + 1, ground[2]];
    if bucket {
        let (yaw, pitch) = look_at(eye, point);
        use_held(game, slot, yaw, pitch);
        ps(|s| s.fall_placed = Some((above, item, 0, 0, false)));
    } else {
        place_block(game, above, slot, m.b("Rotate"), true);
    }
}

// Uses the item in a hotbar slot looking at (yaw, pitch), as a right click into the air does, then holds what you
// held before.
fn use_held(game: &mut Game<'_>, slot: usize, yaw: f32, pitch: f32) {
    let before = game.selected;
    hold(game, slot);
    let seq = sequence(game);
    game.send(S::UseItem(play::UseItem { hand: 0, sequence: seq, yaw, pitch }));
    game.swing_arm();
    hold(game, before);
}

// Where the fall lands within the next 8 ticks (Sunset's findLandingSurface, straight down): the block it lands on and
// the point on its top below you; nothing if it lands in water or later.
fn landing(game: &Game<'_>) -> Option<([i32; 3], [f64; 3])> {
    let p = game.player.as_ref()?;
    let (x, z) = (p.position.x, p.position.z);
    let (bx, bz) = (x.floor() as i32, z.floor() as i32);
    let feet = p.position.y.floor() as i32;
    let below = (0..64).map(|d| feet - 1 - d).find(|&y| !is_air(game, [bx, y, bz]))?;
    let ground = [bx, below, bz];
    if facts(game, ground).fluid_level > 0 || !facts(game, ground).full_collision {
        return None;
    }
    let top = f64::from(below + 1);
    let (mut y, mut vy) = (p.position.y, p.velocity.y);
    for _ in 0..8 {
        y += vy;
        vy = (vy - 0.08) * 0.98;
        if y <= top {
            return Some((ground, [x, top, z]));
        }
    }
    None
}

// ---- Speed Mine (Sunset's SpeedMine), before the tick, where the game goes on breaking the block

pub(super) fn speed_mine(game: &mut Game<'_>, m: Option<&Module>) {
    use super::remote::sunset_remote as remote;
    // Haste mode's own Haste, taken off when it is no longer wanted.
    let haste = m.filter(|m| m.p("Mode") == "Haste").map(|m| m.n("Haste amplifier") as i32 - 1);
    let ours = game.potions.effects.get("haste").is_some_and(|e| !e.visible);
    match haste {
        Some(amplifier) if game.potions.effects.get("haste").is_none_or(|e| e.amplifier < amplifier) => {
            let mut effect = horizon_client::effects::EffectInstance::new("haste", -1, amplifier);
            effect.visible = false;
            game.potions.effects.add(effect);
        }
        None if ours => {
            game.potions.effects.list.retain(|e| e.id != "haste" || e.visible);
        }
        _ => {}
    }
    let (Some(m), Some((pos, done))) = (m, remote::breaking(game)) else {
        return;
    };
    let name = &game.res.facts().get(game.world.block(pos[0], pos[1], pos[2])).name;
    if listed(m.t("Blocks"), name) != (m.p("Blocks filter") == "Whitelist") {
        return;
    }
    let step = game.destroy_progress(pos);
    match m.p("Mode") {
        // The server takes the stop once its count reaches 0.7 (counting the tick the break began in): be done then.
        "Damage" if (done > 0.0 && done + step >= 0.7) || (done == 0.0 && step > 0.5 && m.b("Instamine")) => {
            remote::set_breaking(game, 1.0);
        }
        // Modifier times the game's own step (the game adds one step itself).
        "Normal" if done > 0.0 => remote::set_breaking(game, done + step * (m.n("Modifier") as f32 - 1.0)),
        _ => {}
    }
}

// ---- No Break Reset, before the tick, where the game would see the new item and start the break again

pub(super) fn no_break_reset(game: &mut Game<'_>, m: Option<&Module>) {
    use super::remote::sunset_remote as remote;
    let (Some(m), Some((pos, _))) = (m, remote::breaking(game)) else {
        return;
    };
    let step = game.destroy_progress(pos);
    if remote::breaking_item_changed(game) && (!m.b("Only to better tools") || step >= ps(|p| p.break_step)) {
        remote::keep_breaking(game);
    }
    ps(|p| p.break_step = step);
}

// Where enemy players will be when a hit lands (their movement, stepped through Horizon's collisions), and which of
// them can be hurt yet: the server's hurt time after each hit, as observed.
use super::sunset_explosive_damage::{self as damage, Blast};
use super::sunset_explosive_policy::Budget;
use super::sunset_hurt_policy as hurt;
use super::sunset_lead_policy as lead;
use super::sunset_prediction_native::{NativeKernel, StrictChunks};
use super::sunset_util::{self as util, Target};
use super::{Dim, Game};
use horizon_client::collisions::{EntityCollisions, PowderSnowSubject, SceneCollisions};
use horizon_core::geometry::Vec3;
use horizon_protocol::{
    entity_data::Value,
    packets::play::{Clientbound as C, Serverbound as S},
};
use horizon_world::{
    collision_context::{CollisionContext, CollisionEntity, CollisionItem},
    entity_obstruction::EntityIdentity,
};
use std::sync::{Arc, Mutex};
type Session = Arc<Mutex<Option<Arc<horizon_protocol::connection::Counters>>>>;
struct Scene {
    session: Session,
    dim: Dim,
    id: i32,
}
#[derive(Clone, Copy)]
struct Pending {
    source: hurt::ShotSource,
    victim: u32,
    raw: f32,
    tick: u64,
    lead: u32,
}
struct Hands {
    id: u32,
    stacks: [Option<horizon_client::items::ItemStack>; 2],
    using: Option<(usize, u64)>,
}
struct State {
    scene: Option<Scene>,
    generation: u64,
    tick: u64,
    steps: u32,
    tracks: lead::Tracks,
    cache: Vec<(u32, u32, Target)>,
    absorption: Vec<(u32, f32)>,
    clock: hurt::Clock,
    receipts: hurt::ReceiptTiming,
    pending: Vec<Pending>,
    hands: Vec<Hands>,
}
impl Default for State {
    fn default() -> Self {
        Self {
            scene: None,
            generation: 0,
            tick: 0,
            steps: 512,
            tracks: lead::Tracks::default(),
            cache: Vec::new(),
            absorption: Vec::new(),
            clock: hurt::Clock::new(),
            receipts: hurt::ReceiptTiming::new(),
            pending: Vec::new(),
            hands: Vec::new(),
        }
    }
}
static STATE: Mutex<Option<State>> = Mutex::new(None);
fn state<R>(f: impl FnOnce(&mut State) -> R) -> R {
    let mut guard = STATE.lock().unwrap_or_else(|e| e.into_inner());
    f(guard.get_or_insert_with(State::default))
}
fn same(game: &Game<'_>, scene: &Scene) -> bool {
    scene.dim == game.dim
        && game
            .remote
            .as_ref()
            .is_some_and(|r| r.entity_id == scene.id && Arc::ptr_eq(&r.session.counters, &scene.session))
}
pub(super) fn reset() {
    state(|s| {
        let generation = s.generation.wrapping_add(1);
        *s = State { generation, ..State::default() };
    });
}
pub(super) fn tick(game: &Game<'_>) {
    state(|s| {
        let changed = s.scene.as_ref().is_none_or(|scene| !same(game, scene));
        if changed {
            let generation = s.generation.wrapping_add(1);
            *s = State {
                generation,
                scene: game.remote.as_ref().map(|r| Scene {
                    session: r.session.counters.clone(),
                    dim: game.dim,
                    id: r.entity_id,
                }),
                ..State::default()
            };
        }
        if changed || s.tick != game.ticks {
            s.tick = game.ticks;
            s.steps = 512;
            s.cache.clear();
            s.clock
                .tick(s.generation, game.ticks, |id| game.mobs.iter().any(|m| m.id == id && m.alive() && !m.removed));
        }
        s.pending.retain(|p| p.tick == game.ticks);
    });
}
pub(super) fn reset_receipts() {
    state(|s| s.receipts.reset());
}
pub(super) fn rtt(game: &Game<'_>) -> u32 {
    state(|s| s.receipts.rtt_ticks(super::remote::sunset_combat_remote::latency(game).unwrap_or(0)))
}
pub(super) fn effective_health(game: &Game<'_>, target: &Target) -> Option<f64> {
    let extra = state(|s| {
        s.scene
            .as_ref()
            .filter(|scene| same(game, scene))
            .and_then(|_| s.absorption.iter().find(|p| p.0 == target.id).map(|p| p.1))
    })?;
    let hp = f64::from(target.health + extra);
    (hp.is_finite() && hp > 0.0).then_some(hp)
}
// Some(None) means no use was observed. None means an active hand's complete
// equipment has not arrived; that cannot establish a shield damage reduction.
pub(super) fn blocking_hand(id: u32, tick: u64) -> Option<Option<(horizon_client::items::ItemStack, u64)>> {
    state(|s| {
        let hand = s.hands.iter().find(|h| h.id == id)?;
        let Some((slot, since)) = hand.using else {
            return Some(None);
        };
        Some(Some((hand.stacks[slot].clone()?, tick.checked_sub(since)?)))
    })
}
fn vec(value: [f64; 3]) -> Vec3 {
    Vec3::new(value[0], value[1], value[2])
}
fn context<'a>(game: &'a Game<'_>, target: &Target) -> Option<CollisionContext<'a>> {
    let mob = game.mobs.iter().find(|m| m.id == target.id && !m.removed)?;
    let held =
        mob.extra.main_hand.as_deref().map(|item| CollisionItem { item, count: 1 }).unwrap_or(CollisionItem::EMPTY);
    Some(CollisionContext::for_entity(
        CollisionEntity {
            identity: EntityIdentity(u64::from(target.id)),
            kind: if &*mob.kind.id == "minecraft:player" { horizon_world::collision_context::EntityContextKind::Player } else { horizon_world::collision_context::EntityContextKind::Living },
            y: mob.position.y,
            descending: mob.extra.crouching,
            main_hand: Some(held),
        },
        false,
    ))
}
fn subject(game: &Game<'_>, id: u32) -> Option<PowderSnowSubject> {
    let mob = game.mobs.iter().find(|m| m.id == id)?;
    Some(PowderSnowSubject {
        fall_distance: mob.fall_distance,
        leather_boots: mob.extra.feet.as_deref() == Some("minecraft:leather_boots"),
        ..Default::default()
    })
}
pub(super) fn target(game: &Game<'_>, target: &Target, ahead: u32) -> Option<Target> {
    if let Some(cached) = state(|s| s.cache.iter().find(|p| p.0 == target.id && p.1 == ahead).map(|p| p.2.clone())) {
        return Some(cached);
    }
    let observed = super::remote::sunset_prediction_remote::motion(game, target.id)?;
    let motion = state(|s| s.tracks.observe(target.id, game.ticks, observed.server, observed.update_interval).ok())?;
    let snapshot = lead::Snapshot {
        rendered_feet: observed.rendered,
        server_feet: observed.server,
        rendered_box: observed.bounds,
        motion,
        floating: observed.floating,
    };
    let blocks = SceneCollisions { world: &game.world, binding: game.collision, subject: subject(game, target.id) };
    let mut world = StrictChunks(EntityCollisions::with_border(
        blocks,
        game.border.geometry(),
        [observed.rendered.x, observed.rendered.z],
    ));
    let mut kernel = NativeKernel {
        world: &mut world,
        identity: EntityIdentity(u64::from(target.id)),
        context: context(game, target)?,
        cell_budget_per_step: 512,
    };
    let projected = state(|s| lead::project(snapshot, ahead, &mut s.steps, &mut kernel).ok())?;
    let mut out = target.clone();
    out.pos = projected.feet.components();
    out.lo = projected.bounds.min_position().components();
    out.hi = projected.bounds.max_position().components();
    state(|s| {
        if s.cache.len() < 96 {
            s.cache.push((out.id, ahead, out.clone()));
        }
    });
    Some(out)
}
pub(super) fn local_offset(game: &Game<'_>, ahead: u32) -> Option<[f64; 3]> {
    let local = super::remote::sunset_prediction_remote::local_motion(game)?;
    let player = game.player.as_ref()?;
    let held = game
        .inventory
        .get(game.selected)
        .and_then(Option::as_ref)
        .map(|s| CollisionItem { item: &s.item, count: s.count as i32 })
        .unwrap_or(CollisionItem::EMPTY);
    let blocks =
        SceneCollisions { world: &game.world, binding: game.collision, subject: Some(player.powder_snow_subject()) };
    let mut world = StrictChunks(EntityCollisions::with_border(
        blocks,
        game.border.geometry(),
        [player.position.x, player.position.z],
    ));
    let mut kernel = NativeKernel {
        world: &mut world,
        identity: EntityIdentity(0),
        context: CollisionContext::for_entity(
            CollisionEntity {
                identity: EntityIdentity(0),
                kind: horizon_world::collision_context::EntityContextKind::Player,
                y: player.position.y,
                descending: player.shift_key_down,
                main_hand: Some(held),
            },
            false,
        ),
        cell_budget_per_step: 512,
    };
    let snapshot = lead::Snapshot {
        rendered_feet: local.feet,
        server_feet: local.feet,
        rendered_box: local.bounds,
        motion: lead::Motion { velocity: local.previous.vector_to(local.feet), extra_ticks: 0 },
        floating: local.floating,
    };
    state(|s| lead::project(snapshot, ahead, &mut s.steps, &mut kernel).ok()).map(|p| p.offset.components())
}
pub(super) fn face_facts(game: &Game<'_>, target: &Target) -> super::sunset_faceplace_policy::FaceFacts {
    use super::{sunset_durability_patch::Prototype, sunset_faceplace_native as native};
    let armor = game.mobs.iter().find(|m| m.id == target.id).map_or([None; 4], |mob| {
        std::array::from_fn(|i| {
            let stack = mob.extra.armor[i].as_ref()?;
            let info = game.items().get(&stack.item)?;
            let name = stack.item.strip_prefix("minecraft:")?;
            if !["helmet", "chestplate", "leggings", "boots"].iter().any(|suffix| name.ends_with(suffix))
                && name != "elytra"
            {
                return None;
            }
            native::armor(
                stack,
                Prototype {
                    maximum: (info.max_damage > 0).then_some(info.max_damage),
                    damage_present: true,
                    unbreakable: false,
                },
            )
        })
    });
    super::sunset_faceplace_policy::FaceFacts {
        effective_health: effective_health(game, target),
        armor,
        neighbor_resistance: native::horizontal_resistance(&game.world, game.res.facts(), vec(target.pos)),
    }
}
pub(super) fn estimate(
    game: &Game<'_>,
    victim: &Target,
    blast: Blast,
    ahead: u32,
    lead: u32,
    budget: &mut Budget,
) -> Option<(f64, f32)> {
    let sample = damage::target_hurt_raw_at(game, victim, blast, budget)?;
    let assessed = state(|s| s.clock.assess(victim.id, sample.raw_before_armor(), ahead, lead));
    Some((damage::reduce_target_hurt_raw(game, victim, sample, assessed.raw_for_reduction)?, sample.raw_before_armor()))
}
// Both temporal assessments reuse one native exposure/shield/difficulty sample.
pub(super) fn estimate_pair(
    game: &Game<'_>,
    victim: &Target,
    blast: Blast,
    ahead: u32,
    opening: u32,
    lead: u32,
    budget: &mut Budget,
) -> Option<([f64; 3], f32)> {
    let sample = damage::target_hurt_raw_at(game, victim, blast, budget)?;
    let raw = sample.raw_before_armor();
    let assessments =
        state(|s| [s.clock.assess(victim.id, raw, ahead, lead), s.clock.assess(victim.id, raw, opening, lead)]);
    Some((
        [
            damage::reduce_target_hurt_raw(game, victim, sample, assessments[0].raw_for_reduction)?,
            damage::reduce_target_hurt_raw(game, victim, sample, assessments[1].raw_for_reduction)?,
            damage::reduce_target_hurt_raw(game, victim, sample, raw)?,
        ],
        raw,
    ))
}
pub(super) fn held_totem(id: u32) -> bool {
    state(|s| {
        s.hands.iter().find(|h| h.id == id).is_some_and(|h| {
            h.stacks.iter().flatten().any(|stack| stack.count > 0 && util::short(&stack.item) == "totem_of_undying")
        })
    })
}
pub(super) fn opens_in(victim: u32, lead: u32) -> u32 {
    state(|s| s.clock.opens_in(victim, lead))
}
pub(super) fn arm_blast(
    game: &Game<'_>,
    source: hurt::ShotSource,
    blast: Blast,
    targets: &[Target],
    selected: u32,
    horizon: u32,
    budget: &mut Budget,
) -> bool {
    let mut selected_ready = false;
    let mut samples = Vec::with_capacity(4);
    for victim in targets.iter().take(4) {
        let Some(projected) = target(game, victim, horizon) else {
            continue;
        };
        let Some((_, raw)) = estimate(game, &projected, blast, 0, rtt(game), budget) else {
            continue;
        };
        samples.push((victim.id, raw));
        selected_ready |= victim.id == selected;
    }
    if !selected_ready {
        return false;
    }
    for (id, raw) in samples {
        arm(game, source, id, raw, rtt(game));
    }
    true
}
pub(super) fn arm(game: &Game<'_>, source: hurt::ShotSource, victim: u32, raw: f32, lead: u32) {
    state(|s| {
        if s.pending.len() < 8 {
            s.pending.push(Pending { source, victim, raw, tick: game.ticks, lead });
        }
    });
}
pub(super) fn forwarded(game: &Game<'_>, packet: &S) {
    state(|s| {
        let mut i = 0;
        while i < s.pending.len() {
            let pending = s.pending[i];
            let matches = match (pending.source, packet) {
                (hurt::ShotSource::Crystal(id), S::Attack(p)) => p.id == id as i32,
                (hurt::ShotSource::Anchor(center), S::UseItemOn(p)) => p.pos.map(|n| f64::from(n) + 0.5) == center,
                _ => false,
            };
            if matches && pending.tick == game.ticks {
                s.clock.sent(pending.victim, pending.raw, pending.source, pending.lead);
                s.pending.swap_remove(i);
            } else {
                i += 1;
            }
        }
        if let S::UseItemOn(p) = packet
            && matches!(&*util::facts(game, p.pos).name, "minecraft:obsidian" | "minecraft:bedrock")
            && game
                .stack_in(if p.hand == 1 { util::OFFHAND } else { game.selected })
                .is_some_and(|stack| &*stack.item == "minecraft:end_crystal")
        {
            s.receipts.placed(p.pos, game.ticks);
        }
    });
}
pub(super) fn packet(game: &Game<'_>, packet: &C) {
    if matches!(packet, C::Login(_) | C::Respawn(_) | C::Disconnect(_)) {
        reset();
        return;
    }
    tick(game);
    // Incoming packets are observed before native application. Drop all cached
    // copied actor facts so a deferred deed samples the updated native state.
    // Keep the shared collision budget: invalidation must not replenish it.
    state(|s| s.cache.clear());
    if let Some(notice) = super::remote::sunset_hurt_remote::damage_notice(game, packet, |id| {
        game.mobs.iter().find(|m| m.id == id).is_some_and(|m| util::player_enemy(game, m))
    }) && let Some(id) = game.remote.as_ref().and_then(|r| u32::try_from(r.entity_id).ok())
    {
        state(|s| s.clock.damaged(id, notice));
    }
    if let Some(ids) = super::remote::sunset_hurt_remote::removed_ids(packet) {
        state(|s| {
            s.clock.removed(&ids);
            for id in &ids {
                s.tracks.forget(*id);
            }
            s.absorption.retain(|p| !ids.contains(&p.0));
            s.cache.retain(|p| !ids.contains(&p.0));
            s.hands.retain(|p| !ids.contains(&p.id));
        });
    }
    if let Some((id, equipment)) = super::remote::sunset_prediction_remote::equipment(game, packet) {
        state(|s| {
            if let Some(hand) = s.hands.iter_mut().find(|h| h.id == id) {
                for (slot, stack) in equipment {
                    if hand.stacks[slot] != stack {
                        hand.stacks[slot] = stack;
                        if hand.using.is_some_and(|(active, _)| active == slot) {
                            hand.using = Some((slot, game.ticks));
                        }
                    }
                }
            }
        });
    }
    if let Some(base) = super::remote::sunset_hurt_remote::spawned_base(game, packet) {
        state(|s| {
            s.receipts.spawned(base, game.ticks);
        });
    }
    match packet {
        C::AddEntity(p) if p.id >= 0 && super::remote::sunset_prediction_remote::is_player(game, p.kind) => {
            state(|s| {
                let id = p.id as u32;
                s.tracks.forget(id);
                s.absorption.retain(|p| p.0 != id);
                if s.absorption.len() < 512 {
                    s.absorption.push((id, 0.0));
                }
                s.hands.retain(|h| h.id != id);
                if s.hands.len() < 512 {
                    s.hands.push(Hands { id, stacks: [None, None], using: None });
                }
            })
        }
        C::SetEntityData(p) if p.id >= 0 => state(|s| {
            if let Some(extra) = s.absorption.iter_mut().find(|pair| pair.0 == p.id as u32) {
                for (index, _, value) in &p.values {
                    if let (17, Value::Float(amount)) = (index, value) {
                        extra.1 = if amount.is_finite() && *amount >= 0.0 { *amount } else { f32::NAN };
                    }
                }
            }
            if let Some(hand) = s.hands.iter_mut().find(|h| h.id == p.id as u32) {
                for (index, _, value) in &p.values {
                    if let (8, Value::Byte(flags)) = (index, value) {
                        let slot = usize::from(flags & 2 != 0);
                        if flags & 1 == 0 {
                            hand.using = None;
                        } else if !hand.using.is_some_and(|(active, _)| active == slot) {
                            hand.using = Some((slot, game.ticks));
                        }
                    }
                }
            }
        }),
        _ => {}
    }
}

// The collision checks prediction.rs steps a player's movement through.
use super::sunset_lead_policy::{CollisionKernel, Error};
use horizon_core::{
    geometry::{Aabb, Vec3, VoxelShape},
    position::{BlockPos, ChunkPos},
};
use horizon_world::{
    block_collision_scan::{BlockCollisionWorld, CollisionBlock},
    collision_context::CollisionContext,
    entity_obstruction::EntityIdentity,
    world_movement::{EntityMovementWorld, MovementRequest, resolve_world_movement},
};
use std::io;

/// Native scans normally skip unavailable chunks. Forecasts must fail instead.
/// The wrapped SceneCollisions retains native contextual block shapes.
pub struct StrictChunks<W>(pub W);
impl<W: BlockCollisionWorld<Error = io::Error>> BlockCollisionWorld for StrictChunks<W> {
    type Error = io::Error;
    type Chunk = W::Chunk;
    fn collision_chunk(&mut self, p: ChunkPos) -> io::Result<Option<W::Chunk>> {
        self.0
            .collision_chunk(p)?
            .map(Some)
            .ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "forecast collision chunk unavailable"))
    }
    fn collision_block(&mut self, c: W::Chunk, p: BlockPos) -> io::Result<CollisionBlock> {
        self.0.collision_block(c, p)
    }
    fn is_suffocating(&mut self, c: W::Chunk, b: CollisionBlock, p: BlockPos) -> io::Result<bool> {
        self.0.is_suffocating(c, b, p)
    }
    fn may_reach_out(&mut self, c: W::Chunk, y: i32) -> io::Result<bool> {
        self.0.may_reach_out(c, y)
    }
    fn context_shape(&mut self, b: CollisionBlock, p: BlockPos, c: &CollisionContext<'_>) -> io::Result<VoxelShape> {
        self.0.context_shape(b, p, c)
    }
}
impl<W: EntityMovementWorld<Error = io::Error>> EntityMovementWorld for StrictChunks<W> {
    type Error = io::Error;
    // Reference static forecast supplies no extra entity collision shapes.
    fn entity_collisions(&mut self, _: EntityIdentity, _: Aabb) -> io::Result<Vec<VoxelShape>> {
        Ok(Vec::new())
    }
    fn movement_border(&mut self, id: EntityIdentity, b: Aabb) -> io::Result<Option<VoxelShape>> {
        self.0.movement_border(id, b)
    }
}
pub struct NativeKernel<'a, W> {
    pub world: &'a mut StrictChunks<W>,
    pub identity: EntityIdentity,
    /// Capture from the real entity, including descending/mainhand. Do not substitute
    /// a placement context or change held-item facts to the planned attack hand.
    pub context: CollisionContext<'a>,
    pub cell_budget_per_step: usize,
}
impl<W> CollisionKernel for NativeKernel<'_, W>
where
    W: BlockCollisionWorld<Error = io::Error> + EntityMovementWorld<Error = io::Error>,
{
    fn clip(&mut self, bounds: Aabb, attempted: Vec3) -> Result<Vec3, Error> {
        resolve_world_movement(
            self.world,
            MovementRequest {
                entity: self.identity,
                context: self.context,
                bounds,
                movement: attempted,
                max_step: 0.0,
                on_ground: false,
                candidate_budget: self.cell_budget_per_step.min(1024),
            },
        )
        .map_err(|_| Error::Collision)
    }
}

// The list the Profiles module's row opens: the saved profiles, or (its Presets tab) the pre-made ones. A click, or
// the arrows and Enter, loads a saved one; a preset first shows what taking it turns on and off, with Apply and Back.
// Save (under the saved ones) writes the settings as they are now to the profile in use. Left and Right change tabs. The files are read when it opens and when one loads, never while drawing.
use super::{Game, sunset::{Shape, accent, panel_radius}};
use super::sunset_presets::PRESETS;

const ROW: f32 = 18.0;
// The list's title above it and the room under it.
const TOP: f32 = 25.0;
const BOTTOM: f32 = 22.0;
// A preview's lines, and its buttons' row.
const LINE: f32 = 11.0;
const BUTTONS: f32 = 30.0;

#[derive(Clone, Copy, Debug, PartialEq)]
pub(super) enum Tab {
    Saved,
    Presets,
}

// What a click or a key in the menu asks for.
pub(super) enum Choice {
    Load(String),
    Save(String),
    Preview(usize),
    Apply(usize),
}

// A preset's preview: its lines (text, colour), fitted to the menu's width when it was made.
#[derive(Clone, Debug)]
pub(super) struct Preview {
    pub(super) preset: usize,
    pub(super) lines: Vec<(String, u32)>,
}

#[derive(Clone, Debug)]
pub(super) struct Menu {
    pub(super) names: Vec<String>,
    pub(super) error: Option<String>,
    pub(super) tab: Tab,
    pub(super) preview: Option<Preview>,
    // The saved profile in use, which Save writes to.
    in_use: Option<String>,
    focus: usize,
    start: usize,
}

pub(super) fn width(w: f32) -> f32 {
    (w - 16.0).min(300.0)
}

fn frame(w: f32, h: f32, count: usize) -> [f32; 4] {
    let ww = width(w);
    let hh = (count.clamp(1, 10) as f32 * ROW + TOP + BOTTOM).min(h - 16.0);
    [(w - ww) / 2.0, (h - hh) / 2.0, ww, hh]
}

fn preview_frame(w: f32, h: f32, lines: usize) -> [f32; 4] {
    let ww = width(w);
    let hh = (lines as f32 * LINE + TOP + BUTTONS + 6.0).min(h - 16.0);
    [(w - ww) / 2.0, (h - hh) / 2.0, ww, hh]
}

// How many preview lines fit.
fn preview_rows(r: [f32; 4]) -> usize {
    ((r[3] - TOP - BUTTONS - 6.0) / LINE).max(1.0) as usize
}

// The preview's Apply and Back buttons.
fn buttons(r: [f32; 4]) -> ([f32; 4], [f32; 4]) {
    let (bw, bh) = (60.0, 16.0);
    let y = r[1] + r[3] - bh - 8.0;
    ([r[0] + r[2] - 2.0 * bw - 14.0, y, bw, bh], [r[0] + r[2] - bw - 8.0, y, bw, bh])
}

// The Save button, at the foot of the Saved tab.
fn save_button(r: [f32; 4]) -> [f32; 4] {
    [r[0] + r[2] - 98.0, r[1] + r[3] - 19.0, 90.0, 15.0]
}

// The two tabs in the title row.
fn tabs(r: [f32; 4]) -> [([f32; 4], Tab, &'static str); 2] {
    let y = r[1] + 4.0;
    [([r[0] + r[2] - 140.0, y, 50.0, 15.0], Tab::Saved, "Saved"), ([r[0] + r[2] - 86.0, y, 56.0, 15.0], Tab::Presets, "Presets")]
}

// How many rows fit.
fn rows(r: [f32; 4]) -> usize {
    ((r[3] - TOP - BOTTOM) / ROW).max(1.0) as usize
}

fn inside(r: [f32; 4], at: (f32, f32)) -> bool {
    at.0 >= r[0] && at.0 < r[0] + r[2] && at.1 >= r[1] && at.1 < r[1] + r[3]
}

impl Menu {
    // On the saved profiles, or the presets when none is saved.
    pub(super) fn new(names: Vec<String>, selected: Option<&str>, w: f32, h: f32) -> Self {
        let tab = if names.is_empty() { Tab::Presets } else { Tab::Saved };
        let focus = selected.and_then(|n| names.iter().position(|p| p == n)).unwrap_or(0);
        let in_use = selected.filter(|n| names.iter().any(|p| p == n)).map(str::to_owned);
        let mut menu = Self { names, error: None, tab, preview: None, in_use, focus, start: 0 };
        menu.reveal(w, h);
        menu
    }

    fn count(&self) -> usize {
        match self.tab {
            Tab::Saved => self.names.len(),
            Tab::Presets => PRESETS.len(),
        }
    }

    fn rect(&self, w: f32, h: f32) -> [f32; 4] {
        match &self.preview {
            Some(p) => preview_frame(w, h, p.lines.len()),
            None => frame(w, h, self.count()),
        }
    }

    fn reveal(&mut self, w: f32, h: f32) {
        let count = rows(frame(w, h, self.count()));
        self.start = self.start.min(self.focus).max((self.focus + 1).saturating_sub(count));
    }

    fn switch(&mut self, tab: Tab, w: f32, h: f32) {
        if self.tab != tab {
            self.tab = tab;
            self.focus = 0;
            self.start = 0;
            self.error = None;
            self.reveal(w, h);
        }
    }

    // The row `i` of the tab shown: a profile to load or a preset to preview.
    fn choice(&self, i: usize) -> Option<Choice> {
        match self.tab {
            Tab::Saved => self.names.get(i).cloned().map(Choice::Load),
            Tab::Presets => (i < PRESETS.len()).then_some(Choice::Preview(i)),
        }
    }

    pub(super) fn scroll(&mut self, steps: i32, w: f32, h: f32) {
        if self.preview.is_some() {
            return;
        }
        let max = self.count().saturating_sub(rows(frame(w, h, self.count())));
        self.start = (self.start as i32 + steps).clamp(0, max as i32) as usize;
    }

    // Esc: out of a preview (true), else the menu closes.
    pub(super) fn back(&mut self) -> bool {
        self.error = None;
        self.preview.take().is_some()
    }

    // Up and Down move the mark, Left and Right change tabs, Enter loads or previews (and in a preview, applies).
    pub(super) fn key(&mut self, key: &str, w: f32, h: f32) -> Option<Choice> {
        let enter = matches!(key, "key.keyboard.enter" | "key.keyboard.numpad.enter");
        if let Some(p) = &self.preview {
            return enter.then_some(Choice::Apply(p.preset));
        }
        match key {
            "key.keyboard.up" => self.focus = self.focus.saturating_sub(1),
            "key.keyboard.down" => self.focus = (self.focus + 1).min(self.count().saturating_sub(1)),
            "key.keyboard.left" => self.switch(Tab::Saved, w, h),
            "key.keyboard.right" => self.switch(Tab::Presets, w, h),
            _ if enter => return self.choice(self.focus),
            _ => return None,
        }
        self.reveal(w, h);
        None
    }

    // What a click asks for, if anything (a tab or Back is done here).
    pub(super) fn click(&mut self, at: (f32, f32), w: f32, h: f32) -> Option<Choice> {
        let r = self.rect(w, h);
        if let Some(p) = &self.preview {
            let (apply, back) = buttons(r);
            if inside(apply, at) {
                return Some(Choice::Apply(p.preset));
            }
            if inside(back, at) {
                self.back();
            }
            return None;
        }
        if let Some((_, tab, _)) = tabs(r).into_iter().find(|(t, _, _)| inside(*t, at)) {
            self.switch(tab, w, h);
            return None;
        }
        if self.tab == Tab::Saved && let Some(name) = &self.in_use && inside(save_button(r), at) {
            return Some(Choice::Save(name.clone()));
        }
        let list = [r[0] + 4.0, r[1] + TOP, r[2] - 8.0, rows(r) as f32 * ROW];
        inside(list, at).then(|| self.choice(self.start + ((at.1 - list[1]) / ROW) as usize)).flatten()
    }

    // A click outside the menu or on its x closes it.
    pub(super) fn closes(&self, at: (f32, f32), w: f32, h: f32) -> bool {
        let r = self.rect(w, h);
        !inside(r, at) || inside([r[0] + r[2] - 25.0, r[1], 25.0, 22.0], at)
    }
}

fn fit(game: &Game<'_>, text: &str, width: f32) -> String {
    super::sunset::fit_to(game, text, width)
}

// The preview's lines at the menu's width: the preset's about (its title is the head), then `lines` (what it turns on
// and off, and the settings count).
pub(super) fn preview_lines(game: &Game<'_>, w: f32, preset: usize, lines: &[String]) -> Vec<(String, u32)> {
    let room = width(w) - 16.0;
    let about = super::sunset::wrap(game, PRESETS[preset].about, room);
    let mut out: Vec<(String, u32)> = about.into_iter().map(|l| (l, 0x909090)).collect();
    for line in lines {
        let colour = if line.starts_with("Turns on") {
            accent()
        } else if line.starts_with("Turns off") {
            0xFF9090
        } else {
            0xFFFFFF
        };
        out.extend(super::sunset::wrap(game, line, room).into_iter().map(|l| (l, colour)));
    }
    out
}

pub(super) fn draw(game: &Game<'_>, w: f32, h: f32, at: (f32, f32), selected: Option<&str>, menu: Option<&Menu>, out: &mut Vec<Shape>) {
    let Some(menu) = menu else {
        return;
    };
    let r = menu.rect(w, h);
    out.push(Shape::Fill([0.0, 0.0, w, h], 0x8000_0000));
    out.push(Shape::Round(r, panel_radius(), 0xFF12_1214));
    out.push(Shape::Text("x".into(), [r[0] + r[2] - 15.0, r[1] + 7.0], 0xFFFFFF));
    if let Some(p) = &menu.preview {
        out.push(Shape::Head(fit(game, PRESETS[p.preset].title, r[2] - 40.0), [r[0] + 8.0, r[1] + 7.0], 0xFFFFFF));
        let fits = preview_rows(r);
        for (n, (line, colour)) in p.lines.iter().take(fits).enumerate() {
            let text = if n + 1 == fits && p.lines.len() > fits { format!("{line} ...") } else { line.clone() };
            out.push(Shape::Text(fit(game, &text, r[2] - 16.0), [r[0] + 8.0, r[1] + TOP + n as f32 * LINE], *colour));
        }
        let (apply, back) = buttons(r);
        for (b, label, colour) in [(apply, "Apply", 0xFF00_0000 | accent()), (back, "Back", 0xFF3A_3A3A)] {
            out.push(Shape::Round(b, panel_radius(), colour));
            let tw = game.native_text_width(label);
            out.push(Shape::Text(label.to_owned(), [b[0] + (b[2] - tw) / 2.0, b[1] + super::sunset::text_y(b[3])], 0xFFFFFF));
        }
        if let Some(error) = &menu.error {
            out.push(Shape::Text(fit(game, error, r[2] - 150.0), [r[0] + 8.0, r[1] + r[3] - 20.0], 0xFF9090));
        }
        return;
    }
    out.push(Shape::Head("Profiles".into(), [r[0] + 8.0, r[1] + 7.0], 0xFFFFFF));
    for (t, tab, label) in tabs(r) {
        if menu.tab == tab {
            out.push(Shape::Round(t, panel_radius(), 0xFF28_282C));
        }
        let tw = game.native_text_width(label);
        out.push(Shape::Text(label.to_owned(), [t[0] + (t[2] - tw) / 2.0, t[1] + 3.0], if menu.tab == tab { accent() } else { 0x909090 }));
    }
    if menu.tab == Tab::Saved && menu.names.is_empty() {
        out.push(Shape::Text("None saved yet: .profile save <name>".into(), [r[0] + 8.0, r[1] + TOP + 5.0], 0xFFFFFF));
    }
    for i in (menu.start..menu.count()).take(rows(r)) {
        let row = [r[0] + 4.0, r[1] + TOP + (i - menu.start) as f32 * ROW, r[2] - 8.0, ROW];
        if inside(row, at) || i == menu.focus {
            out.push(Shape::Round(row, panel_radius(), 0xFF28_282C));
        }
        let at_text = [row[0] + 5.0, row[1] + 5.0];
        match menu.tab {
            Tab::Saved => {
                let name = &menu.names[i];
                let colour = if selected == Some(name.as_str()) { accent() } else { 0xFFFFFF };
                out.push(Shape::Text(fit(game, name, row[2] - 10.0), at_text, colour));
            }
            Tab::Presets => {
                let preset = &PRESETS[i];
                let colour = if selected == Some(preset.id) { accent() } else { 0xFFFFFF };
                let title = fit(game, preset.title, row[2] - 10.0);
                let tw = game.native_text_width(&title);
                out.push(Shape::Text(title, at_text, colour));
                let room = row[2] - 18.0 - tw;
                if room > 30.0 {
                    out.push(Shape::Text(fit(game, preset.about, room), [at_text[0] + tw + 8.0, at_text[1]], 0x808080));
                }
            }
        }
    }
    let saving = menu.tab == Tab::Saved && menu.in_use.is_some();
    if let Some(name) = menu.in_use.as_deref().filter(|_| saving) {
        let b = save_button(r);
        out.push(Shape::Round(b, panel_radius(), if inside(b, at) { 0xFF00_0000 | accent() } else { 0xFF3A_3A3A }));
        let label = fit(game, &format!("Save {name}"), b[2] - 8.0);
        let tw = game.native_text_width(&label);
        out.push(Shape::Text(label, [b[0] + (b[2] - tw) / 2.0, b[1] + 3.0], 0xFFFFFF));
    }
    if let Some(error) = &menu.error {
        let room = if saving { r[2] - 112.0 } else { r[2] - 16.0 };
        out.push(Shape::Text(fit(game, error, room), [r[0] + 8.0, r[1] + r[3] - 16.0], 0xFF9090));
    }
}

// Profiles as files: `<mod data>/profiles/<name>.profile`, with the checks from Rust's pull request #2 (names that
// are safe file names on every system, size limits, no links or junctions in the way, writes that leave the old file
// whole when they fail), a backup of the settings before every load, and export and import folders beside them. Only
// the mod's own data folder is ever written; no command names a path.

use std::fs::{self, File, OpenOptions};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

pub(super) const HEADER: &str = "sunset-profile=1";
// The settings as they were before the last load.
pub(super) const BACKUP: &str = "before-load";
const MAX_BYTES: usize = 1024 * 1024;
const MAX_PROFILES: usize = 128;

// Selection belongs to the config, never to a portable profile. Hashing is only
// change detection, not a trust check; the full module snapshot is canonical.
#[derive(Clone, Debug, Default, PartialEq)]
pub(super) struct Selection {
    current: Option<(String, u64)>,
    before: Option<(String, u64)>,
    modified: bool,
}

pub(super) fn fingerprint(text: &str) -> u64 {
    text.bytes().fold(0xcbf29ce484222325, |hash, byte| (hash ^ u64::from(byte)).wrapping_mul(0x100000001b3))
}

impl Selection {
    pub(super) fn refresh(&mut self, snapshot: &str) {
        self.modified = self.current.as_ref().is_some_and(|(_, hash)| *hash != fingerprint(snapshot));
    }
    pub(super) fn selected(&self) -> Option<&str> {
        self.current.as_ref().map(|(name, _)| name.as_str())
    }
    pub(super) fn label(&self) -> String {
        match self.selected() {
            Some(name) => format!("{name}{}", if self.modified { " (modified)" } else { "" }),
            None => "Custom".into(),
        }
    }
    pub(super) fn choose(&mut self, name: &str, snapshot: &str) {
        self.current = Some((name.to_owned(), fingerprint(snapshot)));
        self.modified = false;
    }
    pub(super) fn loaded(&mut self, name: &str, snapshot: &str) {
        let previous = self.current.clone();
        if name == BACKUP {
            self.current = self.before.take();
        } else {
            self.choose(name, snapshot);
        }
        self.before = previous;
        self.refresh(snapshot);
    }
    pub(super) fn deleted(&mut self, name: &str) {
        if self.selected() == Some(name) {
            self.current = None;
            self.modified = false;
        }
        if self.before.as_ref().is_some_and(|(n, _)| n == name) { self.before = None; }
    }
    pub(super) fn stored(&self) -> String {
        let encode = |value: &Option<(String, u64)>| value.as_ref().map_or(String::new(), |(n, h)| format!("{n}|{h:016x}"));
        format!("{};{}", encode(&self.current), encode(&self.before))
    }
    pub(super) fn restore(&mut self, text: &str) {
        let decode = |value: &str| -> Option<(String, u64)> {
            let (n, hash) = value.split_once('|')?;
            (name(n).ok()?.as_str() == n && n != BACKUP && hash.len() == 16)
                .then(|| u64::from_str_radix(hash, 16).ok().map(|h| (n.to_owned(), h))).flatten()
        };
        let (current, before) = text.split_once(';').unwrap_or(("", ""));
        self.current = decode(current);
        self.before = decode(before);
        self.modified = false;
    }
}

#[cfg(test)]
mod selection_tests {
    use super::*;
    #[test]
    fn edits_and_restores_are_tracked() {
        let mut s = Selection::default();
        s.choose("bedwars", "hud.on=true");
        s.refresh("hud.on=false");
        assert_eq!(s.label(), "bedwars (modified)");
        s.refresh("hud.on=true");
        assert_eq!(s.label(), "bedwars");
    }
    #[test]
    fn saved_selection_survives_restart_with_dirty_state() {
        let mut s = Selection::default();
        s.choose("smp", "baseline");
        let mut restored = Selection::default();
        restored.restore(&s.stored());
        restored.refresh("changed");
        assert_eq!(restored.label(), "smp (modified)");
    }
    #[test]
    fn undo_preserves_previous_name_and_dirty_baseline() {
        let mut s = Selection::default();
        s.choose("smp", "baseline");
        s.loaded("bedwars", "new");
        let mut restored = Selection::default();
        restored.restore(&s.stored());
        restored.loaded(BACKUP, "changed");
        assert_eq!(restored.label(), "smp (modified)");
        restored.loaded(BACKUP, "new");
        assert_eq!(restored.label(), "bedwars");
    }
    #[test]
    fn deleting_selected_profile_and_invalid_metadata_show_custom() {
        let mut s = Selection::default();
        s.choose("bedwars", "baseline");
        s.deleted("bedwars");
        assert_eq!(s.label(), "Custom");
        for text in ["../secret|0000000000000000;", "before-load|0000000000000000;", "bedwars|bad;", "broken"] {
            s.restore(text);
            assert_eq!(s.label(), "Custom");
        }
    }
}

// A profile's name as its file is called: 1 to 32 letters, digits, - or _, starting with a letter or digit, and not
// a name Windows keeps for itself.
pub(super) fn name(input: &str) -> Result<String, String> {
    let n = input.trim().to_ascii_lowercase().replace(' ', "-");
    let ok = !n.is_empty()
        && n.len() <= 32
        && n.as_bytes()[0].is_ascii_alphanumeric()
        && n.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_');
    if !ok {
        return Err("a name is 1 to 32 letters, digits, - or _, starting with a letter or digit".into());
    }
    let device = |p: &str| n.len() == 4 && n.starts_with(p) && n.as_bytes()[3].is_ascii_digit();
    if matches!(n.as_str(), "con" | "prn" | "aux" | "nul") || device("com") || device("lpt") {
        return Err(format!("{n} is a name Windows keeps for itself"));
    }
    Ok(n)
}

// A link or a Windows junction (a reparse point).
fn linked(m: &fs::Metadata) -> bool {
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;
        m.file_attributes() & 0x400 != 0
    }
    #[cfg(not(windows))]
    {
        m.file_type().is_symlink()
    }
}

fn plain(path: &Path, directory: bool) -> Result<(), String> {
    let m = fs::symlink_metadata(path).map_err(|e| format!("can't look at {}: {e}", path.display()))?;
    if linked(&m) || m.is_dir() != directory {
        return Err(format!("{} must be a plain {} (no links)", path.display(), if directory { "folder" } else { "file" }));
    }
    Ok(())
}

fn folder(path: PathBuf) -> Result<PathBuf, String> {
    match fs::create_dir_all(&path) {
        Ok(()) => plain(&path, true).map(|()| path),
        Err(e) => Err(format!("can't make {}: {e}", path.display())),
    }
}

pub(super) struct Store {
    profiles: PathBuf,
    exports: PathBuf,
    imports: PathBuf,
}

impl Store {
    // The mod's data folder, from the game.
    pub(super) fn new(data: PathBuf) -> Result<Self, String> {
        let data = folder(data)?;
        Ok(Self { profiles: folder(data.join("profiles"))?, exports: folder(data.join("exports"))?, imports: folder(data.join("imports"))? })
    }

    pub(super) fn path(&self, name: &str) -> PathBuf {
        self.profiles.join(format!("{name}.profile"))
    }

    pub(super) fn exists(&self, name: &str) -> bool {
        self.path(name).is_file()
    }

    pub(super) fn read(&self, name: &str) -> Result<String, String> {
        read(&self.path(name))
    }

    // The saved profiles, less the backup.
    pub(super) fn list(&self) -> Result<Vec<String>, String> {
        let mut names = Vec::new();
        for entry in fs::read_dir(&self.profiles).map_err(|e| format!("can't list the profiles: {e}"))?.flatten() {
            let file = entry.file_name();
            if let Some(n) = file.to_str().and_then(|f| f.strip_suffix(".profile"))
                && name(n).as_deref() == Ok(n)
                && n != BACKUP
            {
                names.push(n.to_owned());
            }
        }
        names.sort();
        Ok(names)
    }

    pub(super) fn write(&self, name: &str, text: &str) -> Result<(), String> {
        if name != BACKUP && !self.exists(name) && self.list()?.len() >= MAX_PROFILES {
            return Err(format!("{MAX_PROFILES} profiles are the most; delete one first"));
        }
        write(&self.path(name), text)
    }

    pub(super) fn delete(&self, name: &str) -> Result<(), String> {
        let path = self.path(name);
        plain(&path, false)?;
        fs::remove_file(&path).map_err(|e| format!("can't delete {name}: {e}"))
    }

    // A copy in the exports folder, to share: where it went.
    pub(super) fn export(&self, name: &str) -> Result<PathBuf, String> {
        let to = self.exports.join(format!("{name}.profile"));
        write(&to, &self.read(name)?)?;
        Ok(to)
    }

    // A profile file someone put in the imports folder.
    pub(super) fn import(&self, name: &str) -> Result<String, String> {
        read(&self.imports.join(format!("{name}.profile")))
    }

    // Another kind of file (a loadout) to share: written to the exports folder as `file`, where it went.
    pub(super) fn share(&self, file: &str, text: &str) -> Result<PathBuf, String> {
        let to = self.exports.join(file);
        write(&to, text)?;
        Ok(to)
    }

    // Such a file someone put in the imports folder.
    pub(super) fn shared(&self, file: &str) -> Result<String, String> {
        read(&self.imports.join(file))
    }

    pub(super) fn imports(&self) -> &Path {
        &self.imports
    }
}

fn read(path: &Path) -> Result<String, String> {
    plain(path, false)?;
    let mut bytes = Vec::new();
    File::open(path)
        .and_then(|f| f.take(MAX_BYTES as u64 + 1).read_to_end(&mut bytes))
        .map_err(|e| format!("can't read {}: {e}", path.display()))?;
    if bytes.len() > MAX_BYTES {
        return Err("a profile is 1 MiB at most".into());
    }
    String::from_utf8(bytes).map_err(|_| "a profile is UTF-8 text".into())
}

// The config: the game's own setting writer truncates the file and then writes it, so a crash or a full disk in
// between left an empty config (every setting gone). Sunset writes it as it writes profiles instead.
pub(super) fn write_config(data: &Path, key: &str, text: &str) -> Result<(), String> {
    let data = folder(data.to_path_buf())?;
    write_limited(&data.join(key), text, 16 * MAX_BYTES)
}

// A config that holds settings: anything else (empty, cut short before its first module) is not one to load.
pub(super) fn whole_config(text: &str) -> bool {
    text.lines().any(|l| l.contains(".on="))
}

// Files a write left behind when the game was closed in the middle of it (`config.tmp1234`, `pvp.tmp1234`).
pub(super) fn sweep(data: &Path) {
    for dir in [data.to_path_buf(), data.join("profiles")] {
        for entry in fs::read_dir(&dir).into_iter().flatten().flatten() {
            let name = entry.file_name();
            let Some(name) = name.to_str() else { continue };
            let stray = name.rsplit_once(".tmp").is_some_and(|(_, pid)| !pid.is_empty() && pid.bytes().all(|b| b.is_ascii_digit()));
            if stray && entry.file_type().is_ok_and(|t| t.is_file()) {
                let _ = fs::remove_file(entry.path());
            }
        }
    }
}

// Written beside the old file and renamed over it, so a failed write leaves the old one whole.
fn write(path: &Path, text: &str) -> Result<(), String> {
    write_limited(path, text, MAX_BYTES)
}

fn write_limited(path: &Path, text: &str, limit: usize) -> Result<(), String> {
    if text.len() > limit {
        return Err(format!("{} is {} KiB at most", path.display(), limit / 1024));
    }
    if fs::symlink_metadata(path).is_ok() {
        plain(path, false)?;
    }
    let tmp = path.with_extension(format!("tmp{}", std::process::id()));
    let done = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&tmp)
        .and_then(|mut f| f.write_all(text.as_bytes()).and_then(|()| f.sync_all()))
        .and_then(|()| fs::rename(&tmp, path));
    if done.is_err() {
        let _ = fs::remove_file(&tmp);
    }
    done.map_err(|e| format!("can't write {}: {e}", path.display()))
}

#[cfg(test)]
mod store_tests {
    use super::*;

    // The config is written whole or not at all, a cut-short one is told apart, and a crashed write's leftovers go.
    #[test]
    fn config_writes_replace_whole_and_leftovers_are_swept() {
        let dir = std::env::temp_dir().join(format!("sunset-store-test-{}", std::process::id()));
        let _ = fs::remove_dir_all(&dir);
        write_config(&dir, "config", "sprint.on=true\n").unwrap();
        write_config(&dir, "config", "sprint.on=false\nhud.on=true\n").unwrap();
        assert_eq!(fs::read_to_string(dir.join("config")).unwrap(), "sprint.on=false\nhud.on=true\n");
        fs::write(dir.join("config.tmp4242"), "half").unwrap();
        fs::create_dir_all(dir.join("profiles")).unwrap();
        fs::write(dir.join("profiles").join("pvp.tmp99"), "half").unwrap();
        fs::write(dir.join("profiles").join("pvp.profile"), "kept").unwrap();
        sweep(&dir);
        assert!(!dir.join("config.tmp4242").exists() && !dir.join("profiles").join("pvp.tmp99").exists());
        assert!(dir.join("profiles").join("pvp.profile").exists() && dir.join("config").exists());
        assert!(whole_config("sprint.on=true") && !whole_config("") && !whole_config("friends=a"));
        let _ = fs::remove_dir_all(&dir);
    }
}

// PvP Bot. Sword mode is from Rust's PR #16 (its settings and what it does; written small here): fights the nearest
// enemy player with your sword by itself. It turns you towards them at a human pace, walks and sprints in, keeps its
// distance (Patient) or presses on (Aggressive), strafes, jumps for critical hits and on being hit (Jump reset), and
// eats a golden apple when low. Hits go through the strikes queue like Kill Aura's. Your own movement keys take over.
// Crystal mode follows the behaviour of #16's crystal controller, with Sunset's own modules as its hands: it walks
// into crystal range, holes up (into a hole nearby, else Surround where it stands), and while it fights keeps Crystal
// Aura, Anchor Aura, Offhand and Auto Gap on, Self Trap when low, and pearls away when low with no totem left. What it learns of each rival (Rust's PR #20 store) changes how it fights them again.
use super::sunset::{self, Category, Module, hold, own_id, with};
use super::sunset_util as util;
use super::{Game, Screen};
use std::collections::{HashMap, HashSet};
use std::sync::Mutex;
use winit::event::MouseButton;
use winit::keyboard::KeyCode;

pub(super) const NAME: &str = "PvP Bot";
const KEYS: [KeyCode; 6] = [KeyCode::KeyW, KeyCode::KeyS, KeyCode::KeyA, KeyCode::KeyD, KeyCode::ControlLeft, KeyCode::Space];
// The vanilla reach to a player's box, with a little kept back.
const REACH: f64 = 2.9;
// The modules Crystal mode drives.
const HANDS: [&str; 6] = ["Crystal Aura", "Anchor Aura", "Offhand", "Auto Gap", "Surround", "Self Trap"];

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new(NAME, Category::Combat, "Fights the nearest player: with a sword, or with crystals and anchors.")
            .pick("Mode", &["Sword", "Crystal"])
            .pick("Style", &["Patient", "Aggressive"])
            .num("Fight range", 16.0, 6.0, 32.0, 1.0)
            .num("Turn speed", 1.0, 0.5, 1.5, 0.05)
            .bool("Strafe", true)
            .bool("Jump crits", true)
            .bool("Jump reset", true)
            .num("Gapple below HP", 10.0, 0.0, 20.0, 1.0)
            .num("Crystal range", 4.5, 3.0, 6.0, 0.5)
            .bool("Use anchors", true)
            .bool("Hole up", true)
            .num("Self trap below HP", 12.0, 0.0, 36.0, 1.0)
            .num("Pearl below HP", 8.0, 0.0, 20.0, 1.0)
            .bool("Learn rivals", true),
    ]
}

pub(super) fn visible(m: &Module, name: &str) -> bool {
    let crystal = m.p("Mode") == "Crystal";
    match name {
        "Style" | "Strafe" | "Jump crits" | "Jump reset" | "Gapple below HP" => !crystal,
        "Crystal range" | "Use anchors" | "Hole up" | "Self trap below HP" | "Pearl below HP" | "Learn rivals" => crystal,
        _ => true,
    }
}

#[derive(Default)]
struct Bot {
    // The keys the bot holds down (never one you hold yourself).
    pressed: HashSet<KeyCode>,
    // Strafing right (else left), and the tick it turns the other way.
    right: bool,
    flip_at: u64,
    // Eating: the slot to go back to.
    eating: Option<usize>,
    health: f32,
    // Ticks the hit has been ready for, on the ground, waiting for a jump to fall.
    ready_for: u32,
    // Crystal mode: the modules it turned on (each off before), and the tick each last went on.
    leased: Vec<&'static str>,
    leased_at: HashMap<&'static str, u64>,
    fight: Option<Fight>,
    pearl_at: u64,
}

// The fight with one rival: what it started at, for their history.
struct Fight {
    id: u32,
    uuid: Option<u128>,
    // Totems popped (theirs, yours) as it began, and the most seen since.
    start: (u32, u32),
    seen: (u32, u32),
    ticks: u32,
    hole_ticks: u32,
}

// What the bot learnt of a rival over its fights: their totems it popped, yours they popped, and how much of the time
// they sat in a hole.
#[derive(Clone, Copy, Default, Debug, PartialEq)]
pub(super) struct Rival {
    pub fights: u32,
    pub pops: u32,
    pub taken: u32,
    pub ticks: u32,
    pub hole_ticks: u32,
}

impl Rival {
    fn text(&self) -> String {
        serde_json::json!({"version": 1, "fights": self.fights, "pops": self.pops, "taken": self.taken,
            "ticks": self.ticks, "hole_ticks": self.hole_ticks})
        .to_string()
    }
    fn parse(text: &str) -> Option<Self> {
        let v: serde_json::Value = serde_json::from_str(text).ok()?;
        if v["version"].as_u64() != Some(1) {
            return None;
        }
        let n = |k: &str| v[k].as_u64().and_then(|n| u32::try_from(n).ok());
        Some(Self { fights: n("fights")?, pops: n("pops")?, taken: n("taken")?, ticks: n("ticks")?, hole_ticks: n("hole_ticks")? })
    }
    // Has popped more of your totems than you of theirs: the pearl goes earlier.
    fn beats_you(&self) -> bool {
        self.taken > self.pops
    }
}

// Rivals by UUID: None while the store is read (off the game thread).
static RIVALS: Mutex<Option<HashMap<u128, Option<Rival>>>> = Mutex::new(None);

fn rivals<R>(f: impl FnOnce(&mut HashMap<u128, Option<Rival>>) -> R) -> R {
    f(RIVALS.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(HashMap::new))
}

static BOT: Mutex<Option<Bot>> = Mutex::new(None);

fn bot<R>(f: impl FnOnce(&mut Bot) -> R) -> R {
    f(BOT.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Bot::default))
}

// Lets go of the keys the bot holds, stops eating, turns off the modules Crystal mode turned on and ends the fight
// (its rival history saved).
pub(super) fn release(game: &mut Game<'_>) {
    let (pressed, eating) = bot(|b| (std::mem::take(&mut b.pressed), b.eating.take()));
    for key in pressed {
        if !game.physical_keys.contains(&key) {
            game.keys.remove(&key);
        }
    }
    if let Some(back) = eating {
        let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, false);
        hold(game, back);
    }
    for name in HANDS {
        lease(game, name, false);
    }
    end_fight(game);
}

fn busy() -> bool {
    bot(|b| !b.pressed.is_empty() || b.eating.is_some() || !b.leased.is_empty() || b.fight.is_some())
}

// Set while the bot itself turns a module on, so its toggle isn't taken for yours.
static LEASING: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

// A module Crystal mode drives, on or off: turned on only when it is off (then saved as off), turned off only when
// the bot turned it on. One that turned itself off again is turned back on after 20 ticks at the soonest.
fn lease(game: &mut Game<'_>, name: &'static str, on: bool) {
    use std::sync::atomic::Ordering;
    let is_on = with(|s| s.module(name).is_some_and(|m| m.on));
    let now = game.ticks;
    if on && !is_on {
        let Some(i) = with(|s| s.find(name)) else {
            return;
        };
        let soon = bot(|b| b.leased_at.get(name).is_some_and(|&at| now >= at && now < at + 20));
        if soon {
            return;
        }
        bot(|b| {
            if !b.leased.contains(&name) {
                b.leased.push(name);
            }
            b.leased_at.insert(name, now);
        });
        LEASING.store(true, Ordering::Relaxed);
        sunset::toggle(game, i, false);
        LEASING.store(false, Ordering::Relaxed);
    } else if !on && bot(|b| b.leased.contains(&name)) {
        bot(|b| b.leased.retain(|n| *n != name));
        util::toggle_off(game, name);
    }
}

// A module turned on or off by hand (or by itself): no longer the bot's to turn off.
pub(super) fn toggled(name: &str) {
    if !LEASING.load(std::sync::atomic::Ordering::Relaxed) {
        bot(|b| b.leased.retain(|n| *n != name));
    }
}

// The on state to save: a module on only because the bot turned it on is saved as off.
pub(super) fn saved_on(name: &str, on: bool) -> bool {
    on && !bot(|b| b.leased.contains(&name))
}

fn press(game: &mut Game<'_>, want: &[KeyCode]) {
    let before = bot(|b| std::mem::take(&mut b.pressed));
    let mut pressed = HashSet::new();
    for key in KEYS {
        if want.contains(&key) {
            game.keys.insert(key);
            pressed.insert(key);
        } else if before.contains(&key) && !game.physical_keys.contains(&key) {
            game.keys.remove(&key);
        }
    }
    bot(|b| b.pressed = pressed);
}

// Turns the view towards (yaw, pitch) by at most `step` degrees a tick.
fn turn(game: &mut Game<'_>, yaw: f32, pitch: f32, step: f32) {
    let dy = (yaw - game.yaw + 540.0).rem_euclid(360.0) - 180.0;
    game.yaw += dy.clamp(-step, step);
    game.pitch += (pitch - game.pitch).clamp(-step, step);
}

// Ground a step ahead along `dir`: a drop of more than 2 blocks, lava or fire there is no place to walk.
fn safe_ahead(game: &Game<'_>, dir: [f64; 2]) -> bool {
    let Some(p) = game.player.as_ref() else {
        return false;
    };
    let (x, z) = ((p.position.x + dir[0]).floor() as i32, (p.position.z + dir[1]).floor() as i32);
    let y = p.position.y.floor() as i32;
    let burns = |y: i32| {
        let name = &game.res.facts().get(game.world.block(x, y, z)).name;
        name.ends_with(":lava") || name.ends_with(":fire")
    };
    if burns(y) || burns(y - 1) {
        return false;
    }
    (1..=3).any(|d| !game.res.facts().is_air(game.world.block(x, y - d, z)))
}

pub(super) fn tick(game: &mut Game<'_>, mods: &[Module]) {
    let Some(m) = mods.iter().find(|m| m.name == NAME && m.on) else {
        if busy() {
            release(game);
        }
        return;
    };
    let alive = game.remote.is_some() && !game.spectator() && game.player.as_ref().is_some_and(|p| p.health.health() > 0.0);
    let playing = game.screen == Screen::Playing && !sunset::gui_open();
    let live = alive && playing;
    // Your own movement keys: the bot lets go and waits.
    let yours = KEYS.iter().any(|k| game.physical_keys.contains(k));
    let me = own_id(game);
    let range = m.n("Fight range");
    let target = game
        .mobs
        .iter()
        .filter(|mob| Some(mob.id) != me && util::player_enemy(game, mob))
        .map(util::mob_target)
        .filter(|t| game.player.as_ref().is_some_and(|p| util::dist([p.position.x, p.position.y, p.position.z], t.pos) <= range))
        .min_by(|a, b| {
            let at = game.player.as_ref().map_or([0.0; 3], |p| [p.position.x, p.position.y, p.position.z]);
            util::dist(at, a.pos).total_cmp(&util::dist(at, b.pos))
        });
    let crystal = m.p("Mode") == "Crystal";
    // Crystal mode keeps its modules on through a screen (Offhand opens the inventory for a totem), only standing.
    if crystal && let (Some(t), Some(eye), true) = (target.as_ref(), game.eye_position(), alive) {
        crystal_tick(game, m, t, eye, yours, !playing);
        return;
    }
    if crystal || bot(|b| !b.leased.is_empty() || b.fight.is_some()) {
        release(game);
        if crystal {
            return;
        }
    }
    let (Some(t), Some(eye), true, false) = (target, game.eye_position(), live, yours) else {
        release(game);
        return;
    };
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let (health, ground, falling, in_water) = (
        p.health.health() + p.health.absorption(),
        p.ground.on_ground,
        !p.ground.on_ground && p.velocity.y < 0.0,
        p.fluids.was_touching_water,
    );
    let hurt = bot(|b| std::mem::replace(&mut b.health, health)) > health + 0.01;
    // A golden apple when low; the fight waits while it eats.
    let low = f64::from(health) < m.n("Gapple below HP");
    let eating = bot(|b| b.eating);
    match (eating, low) {
        (Some(_), true) => {
            press(game, &[KeyCode::KeyS]);
            if game.using.is_none() {
                let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, true);
            }
            return;
        }
        (Some(_), false) => release(game),
        (None, true) => {
            if let Some(slot) = util::find_held(game, |n| n.ends_with("golden_apple")) {
                let back = game.selected;
                press(game, &[KeyCode::KeyS]);
                hold(game, slot);
                let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, true);
                bot(|b| b.eating = Some(back));
                return;
            }
        }
        (None, false) => {}
    }
    if let Some(sword) = util::find_held(game, |n| n.ends_with("_sword"))
        && !game.held().is_some_and(|s| s.item.ends_with("_sword") || s.item.ends_with("_axe"))
    {
        hold(game, sword);
    }
    // Aim at the nearest point of their box to your eyes' height, turned to at Turn speed (40 degrees a tick at 1).
    let aim = [(t.lo[0] + t.hi[0]) / 2.0, eye[1].clamp(t.lo[1] + 0.2, t.hi[1] - 0.2), (t.lo[2] + t.hi[2]) / 2.0];
    let (yaw, pitch) = sunset::look_at(eye, aim);
    turn(game, yaw, pitch, 40.0 * m.n("Turn speed") as f32);
    let near = [(t.lo[0] - eye[0]).max(eye[0] - t.hi[0]).max(0.0), (t.lo[1] - eye[1]).max(eye[1] - t.hi[1]).max(0.0), (t.lo[2] - eye[2]).max(eye[2] - t.hi[2]).max(0.0)];
    let reach = (near[0] * near[0] + near[1] * near[1] + near[2] * near[2]).sqrt();
    let off = ((yaw - game.yaw + 540.0).rem_euclid(360.0) - 180.0).abs();
    let ready = game.hand_strength.scale(0.5, game.main_hand_attack_speed()) >= 1.0;
    // The hit: cooldown full, in reach and in view; with Jump crits, on the way down from a jump (or after 10 ticks
    // ready on the ground, so it never stalls).
    let ready_for = bot(|b| {
        b.ready_for = if ready && reach <= REACH && ground { b.ready_for + 1 } else { 0 };
        b.ready_for
    });
    let crit_ok = !m.b("Jump crits") || falling || in_water || ready_for > 10;
    if ready && reach <= REACH && off < 30.0 && crit_ok && !sunset::strike_waiting() {
        sunset::strike(game, t.id);
    }
    // Moving: in (sprinting) while out of reach; Patient backs off to 2.2 blocks while the cooldown fills, Aggressive
    // stays on them. Strafing turns the other way every 20 to 40 ticks.
    let mut want = Vec::new();
    let dir = [-(game.yaw.to_radians() as f64).sin(), (game.yaw.to_radians() as f64).cos()];
    let gap = util::dist([eye[0], 0.0, eye[2]], [t.pos[0], 0.0, t.pos[2]]);
    if gap > 3.0 || (m.p("Style") == "Aggressive" && gap > 1.5) {
        if safe_ahead(game, dir) {
            want.extend([KeyCode::KeyW, KeyCode::ControlLeft]);
        }
    } else if m.p("Style") == "Patient" && !ready && gap < 2.2 && safe_ahead(game, [-dir[0], -dir[1]]) {
        want.push(KeyCode::KeyS);
    }
    if m.b("Strafe") && gap < 6.0 {
        let now = game.ticks;
        let right = bot(|b| {
            if now >= b.flip_at {
                b.right = !b.right;
                b.flip_at = now + 20 + (now * 7919 % 21);
            }
            b.right
        });
        let side = if right { [-dir[1], dir[0]] } else { [dir[1], -dir[0]] };
        if safe_ahead(game, side) {
            want.push(if right { KeyCode::KeyD } else { KeyCode::KeyA });
        }
    }
    // A jump: for the critical hit as the cooldown comes round in reach, or as a hit lands (Jump reset).
    let soon = game.hand_strength.scale(0.5, game.main_hand_attack_speed()) >= 0.85;
    if ground && !in_water && ((m.b("Jump crits") && soon && reach <= REACH + 0.5) || (m.b("Jump reset") && hurt)) {
        want.push(KeyCode::Space);
    }
    press(game, &want);
}

fn totems(game: &Game<'_>) -> usize {
    game.inventory.iter().chain(std::iter::once(&game.offhand)).flatten().filter(|s| s.item.ends_with(":totem_of_undying")).count()
}

fn air(game: &Game<'_>, p: [i32; 3]) -> bool {
    game.res.facts().is_air(game.world.block(p[0], p[1], p[2]))
}

// The nearest hole within 3 blocks (at your feet or one down) with room to stand in it.
fn hole_near(game: &Game<'_>, feet: [i32; 3]) -> Option<[i32; 3]> {
    let mut cells = Vec::new();
    for dx in -3..=3 {
        for dz in -3..=3 {
            for dy in -1..=0 {
                cells.push([feet[0] + dx, feet[1] + dy, feet[2] + dz]);
            }
        }
    }
    cells
        .into_iter()
        .filter(|&c| air(game, c) && air(game, [c[0], c[1] + 1, c[2]]) && super::sunset_parity::in_hole(game, c))
        .min_by_key(|c| (c[0] - feet[0]).pow(2) + (c[1] - feet[1]).pow(2) + (c[2] - feet[2]).pow(2))
}

// A look to pearl away along, turned from straight back (`toward` + 180) a little at a time: one whose pearl lands
// where you stand clear (no block in your body, ground within 3 blocks, no lava) at least 6 blocks farther from them.
fn pearl_look(game: &Game<'_>, eye: [f64; 3], toward: f32, t: &util::Target) -> Option<(f32, f32)> {
    let now = util::dist([eye[0], 0.0, eye[2]], [t.pos[0], 0.0, t.pos[2]]);
    let clear = |x: f64, y: i32, z: f64| {
        [(-0.3, -0.3), (-0.3, 0.3), (0.3, -0.3), (0.3, 0.3)]
            .iter()
            .all(|(dx, dz)| air(game, [(x + dx).floor() as i32, y, (z + dz).floor() as i32]))
    };
    for turn in [0.0f32, 25.0, -25.0, 50.0, -50.0, 80.0, -80.0] {
        for pitch in [-30.0f32, -15.0, -45.0, 0.0] {
            let (yr, pr) = ((toward + 180.0 + turn).to_radians() as f64, pitch.to_radians() as f64);
            let vel = [-yr.sin() * pr.cos() * 1.5, -pr.sin() * 1.5, yr.cos() * pr.cos() * 1.5];
            let Some(flight) = super::sunset_throws::pearl_flight(game, [eye[0], eye[1] - 0.1, eye[2]], vel, 100, false) else {
                continue;
            };
            let land = flight.land;
            let feet = (land[1] + 0.01).floor() as i32;
            let cell = [land[0].floor() as i32, feet, land[2].floor() as i32];
            let ground = (1..=3).any(|d| !air(game, [cell[0], feet - d, cell[2]]));
            let lava = (0..=3).any(|d| game.res.facts().get(game.world.block(cell[0], feet - d, cell[2])).name.ends_with(":lava"));
            let far = util::dist([land[0], 0.0, land[2]], [t.pos[0], 0.0, t.pos[2]]) >= now + 6.0;
            if far && ground && !lava && clear(land[0], feet, land[2]) && clear(land[0], feet + 1, land[2]) {
                return Some((toward + 180.0 + turn, pitch));
            }
        }
    }
    None
}

fn target_feet(t: &util::Target) -> [i32; 3] {
    [t.pos[0].floor() as i32, (t.lo[1] + 0.1).floor() as i32, t.pos[2].floor() as i32]
}

// A fight with `id` from now: the one before ends; their history is read in the background the first time.
fn begin_fight(game: &mut Game<'_>, id: u32, learn: bool) {
    if bot(|b| b.fight.as_ref().is_some_and(|f| f.id == id)) {
        return;
    }
    end_fight(game);
    let uuid = super::remote::sunset_combat_remote::player_uuid(game, id);
    let own = own_id(game).map_or(0, super::sunset_effects::pops);
    let start = (super::sunset_effects::pops(id), own);
    let fight = Fight { id, uuid, start, seen: start, ticks: 0, hole_ticks: 0 };
    bot(|b| b.fight = Some(fight));
    let Some(uuid) = uuid.filter(|_| learn) else {
        return;
    };
    if rivals(|r| r.get(&uuid).is_some_and(Option::is_some)) {
        return;
    }
    rivals(|r| {
        r.insert(uuid, None);
    });
    let data = game.native_data_dir(sunset::ID);
    let generation = horizon_protocol::connection::sunset_lifecycle::RUNTIME.token();
    std::thread::spawn(move || {
        if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.current(generation) { return; }
        let read = super::sunset_rival_store::read(&data, uuid).ok().and_then(|text| Rival::parse(&text)).unwrap_or_default();
        if !horizon_protocol::connection::sunset_lifecycle::RUNTIME.current(generation) { return; }
        rivals(|r| {
            r.insert(uuid, Some(read));
        });
    });
}

// The fight ends: with Learn rivals, their history gets what it saw and is saved in the background.
fn end_fight(game: &mut Game<'_>) {
    let Some(f) = bot(|b| b.fight.take()) else {
        return;
    };
    if !sunset::running() { return; }
    let learn = with(|s| s.module(NAME).is_some_and(|m| m.b("Learn rivals")));
    let Some(uuid) = f.uuid.filter(|_| learn && f.ticks > 0) else {
        return;
    };
    let pops = super::sunset_effects::pops(f.id).max(f.seen.0);
    let own = own_id(game).map_or(0, super::sunset_effects::pops).max(f.seen.1);
    let Some(next) = rivals(|r| {
        let rival = r.get_mut(&uuid)?.as_mut()?;
        rival.fights += 1;
        rival.ticks += f.ticks;
        rival.hole_ticks += f.hole_ticks;
        rival.pops += pops.saturating_sub(f.start.0);
        rival.taken += own.saturating_sub(f.start.1);
        Some(*rival)
    }) else {
        return;
    };
    let data = game.native_data_dir(sunset::ID);
    std::thread::spawn(move || {
        if sunset::running() { let _ = super::sunset_rival_store::save(&data, &[(uuid, next.text())]); }
    });
}

// What the bot knows of a rival (None: never fought, or still being read).
pub(super) fn rival(uuid: u128) -> Option<Rival> {
    rivals(|r| r.get(&uuid).copied().flatten())
}

fn crystal_tick(game: &mut Game<'_>, m: &Module, t: &util::Target, eye: [f64; 3], yours: bool, paused: bool) {
    let learn = m.b("Learn rivals");
    begin_fight(game, t.id, learn);
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let health = f64::from(p.health.health() + p.health.absorption());
    let ground = p.ground.on_ground;
    let Some(feet) = util::block_pos(game) else {
        return;
    };
    let their_feet = target_feet(t);
    let their_hole = super::sunset_parity::in_hole(game, their_feet);
    let history = bot(|b| b.fight.as_ref().and_then(|f| f.uuid)).filter(|_| learn).and_then(rival);
    // Each tick: the totems popped so far (they go when the rival leaves), time in a hole.
    let (pops, own) = (super::sunset_effects::pops(t.id), own_id(game).map_or(0, super::sunset_effects::pops));
    bot(|b| {
        if let Some(f) = b.fight.as_mut() {
            f.ticks += 1;
            f.hole_ticks += u32::from(their_hole);
            f.seen = (f.seen.0.max(pops), f.seen.1.max(own));
        }
    });
    if paused {
        press(game, &[]);
        return;
    }
    let gap = util::dist([eye[0], 0.0, eye[2]], [t.pos[0], 0.0, t.pos[2]]);
    let (yaw, pitch) = sunset::look_at(eye, [t.pos[0], (t.lo[1] + t.hi[1]) / 2.0, t.pos[2]]);
    // Low with no totem left: one pearl away from them (thrown once the server has its look; another 10 s on at the
    // soonest), then keep back and eat.
    let below = m.n("Pearl below HP") + if history.is_some_and(|r| r.beats_you()) { 4.0 } else { 0.0 };
    let escaping = m.n("Pearl below HP") > 0.0 && health < below && totems(game) == 0;
    let now = game.ticks;
    if escaping {
        let pearl = util::find_held(game, |n| n == "ender_pearl").is_some() && !game.cooldowns.is_on_cooldown("minecraft:ender_pearl");
        let waited = bot(|b| b.pearl_at == 0 || now >= b.pearl_at + 200 || now < b.pearl_at);
        if pearl
            && waited
            && let Some(look) = pearl_look(game, eye, yaw, t)
        {
            lease(game, "Crystal Aura", false);
            lease(game, "Anchor Aura", false);
            (game.yaw, game.pitch) = look;
            if super::sunset_combat_control::owner().is_none() && super::sunset_throws::escape_pearl(game, look) {
                bot(|b| b.pearl_at = now);
            }
            press(game, &[]);
            return;
        }
    }
    // The pearl's look holds for 5 ticks while it is thrown.
    let throwing = bot(|b| b.pearl_at > 0 && now >= b.pearl_at && now < b.pearl_at + 5);
    lease(game, "Crystal Aura", !escaping);
    lease(game, "Anchor Aura", !escaping && m.b("Use anchors"));
    lease(game, "Offhand", true);
    lease(game, "Auto Gap", true);
    let in_hole = super::sunset_parity::in_hole(game, feet);
    let range = m.n("Crystal range");
    // Where to go: back from them while escaping, in while out of crystal range, into a hole nearby once in it.
    let hole = if m.b("Hole up") && !in_hole && gap <= range + 1.5 && !escaping { hole_near(game, feet) } else { None };
    let mut want = Vec::new();
    let mut facing = (yaw, pitch);
    let mut standing = false;
    if let Some(h) = hole.filter(|_| ground) {
        facing = (sunset::look_at(eye, [f64::from(h[0]) + 0.5, eye[1], f64::from(h[2]) + 0.5]).0, game.pitch);
        let dir = [-(facing.0.to_radians() as f64).sin(), (facing.0.to_radians() as f64).cos()];
        let close = (game.yaw - facing.0 + 540.0).rem_euclid(360.0) - 180.0;
        if close.abs() < 20.0 && safe_ahead(game, dir) {
            want.push(KeyCode::KeyW);
        }
    } else if escaping {
        if safe_ahead(game, [(yaw.to_radians() as f64).sin(), -(yaw.to_radians() as f64).cos()]) {
            want.push(KeyCode::KeyS);
        }
    } else if gap > range {
        let dir = [-(game.yaw.to_radians() as f64).sin(), (game.yaw.to_radians() as f64).cos()];
        if safe_ahead(game, dir) {
            want.extend([KeyCode::KeyW, KeyCode::ControlLeft]);
        }
    } else {
        standing = ground;
    }
    // Standing to fight: Surround where it stands (or the hole's open sides), Self Trap when low.
    lease(game, "Surround", m.b("Hole up") && standing && !yours);
    lease(game, "Self Trap", standing && !yours && health < m.n("Self trap below HP"));
    if yours {
        press(game, &[]);
        return;
    }
    if !throwing {
        turn(game, facing.0, facing.1, 40.0 * m.n("Turn speed") as f32);
    }
    press(game, &want);
}

// Native-resolution player radar.

use super::Game;
use super::sunset::{Category, Module, accent, own_id};
use super::sunset_radar_math::{
    circle_point, circle_segments, fitted_size, offset, pixel_width, project,
};
use horizon_client::extras::Corner;
use horizon_client::extras_hud::Corners;
use horizon_client::hud::HudBatch;

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new(
            "Radar",
            Category::Render,
            "Shows nearby players.",
        )
        .pick("Mode", &["Round", "Potato"])
        .num("Range", 64.0, 8.0, 256.0, 1.0)
        .num("Size", 100.0, 80.0, 320.0, 1.0)
        .bool("Rotate", true)
        .colour("Players color", "White")
        // Its place: the bottom left corner, or where the chat or the menu dragged it.
        .pick("Radar position", &["Default", "Custom"])
        .num("Radar x", 0.0, 0.0, 1.0, 0.001)
        .num("Radar y", 1.0, 0.0, 1.0, 0.001),
    ]
}

fn rgba(argb: u32) -> u32 {
    let [a, r, g, b] = argb.to_be_bytes();
    horizon_client::hud::rgba(r, g, b, a)
}

// Solid-atlas vector quads enter the existing HUD batch directly. The only
// edge fade is one physical pixel of coverage, not a blur or low-res texture.
fn band(
    game: &Game<'_>,
    batch: &mut HudBatch,
    center: [f32; 2],
    inner: f32,
    outer: f32,
    segments: usize,
    color: u32,
    feather: bool,
) {
    for i in 0..segments {
        let corners = [
            circle_point(center, inner, i, segments),
            circle_point(center, outer, i, segments),
            circle_point(center, outer, i + 1, segments),
            circle_point(center, inner, i + 1, segments),
        ];
        let start = batch.vertices.len();
        batch.fill_quad(&game.gui.atlas, corners, rgba(color));
        if feather {
            // fill_quad's two triangles use corners 0,1,2,0,2,3.
            for (vertex, corner) in batch.vertices[start..].iter_mut().zip([0, 1, 2, 0, 2, 3]) {
                if corner == 1 || corner == 2 {
                    vertex.color &= 0x00FF_FFFF;
                }
            }
        }
    }
}

fn disc(game: &Game<'_>, batch: &mut HudBatch, center: [f32; 2], radius: f32, color: u32) {
    let pixel = pixel_width(batch.scale);
    let inner = (radius - pixel * 0.5).max(0.0);
    let segments = circle_segments(radius, batch.scale);
    // Two adjacent fan triangles share one quad; no temporary vertex vector.
    for i in (0..segments).step_by(2) {
        batch.fill_quad(
            &game.gui.atlas,
            [
                center,
                circle_point(center, inner, i, segments),
                circle_point(center, inner, i + 1, segments),
                circle_point(center, inner, i + 2, segments),
            ],
            rgba(color),
        );
    }
    band(
        game,
        batch,
        center,
        inner,
        radius + pixel * 0.5,
        segments,
        color,
        true,
    );
}

// Where the radar goes this frame (x, y, its size), worked out before the HUD's layout editor looks so it can be taken:
// in the bottom left corner, or where it was dragged (Custom). None: not drawn this frame.
pub(super) fn place(game: &Game<'_>, w: f32, h: f32, corners: &mut Corners, modules: &[Module]) -> Option<[f32; 3]> {
    let module = modules.iter().find(|m| m.name == "Radar" && m.on)?;
    game.player.as_ref()?;
    let custom = module.p("Radar position") == "Custom";
    if game.title.is_some() || (!custom && !game.native_corner_shown(Corner::BottomLeft)) {
        return None;
    }
    let size = fitted_size(module.n("Size") as f32, w, h)?;
    let (x, y) = if custom {
        (
            (module.n("Radar x") as f32 * w).clamp(0.0, (w - size).max(0.0)),
            (module.n("Radar y") as f32 * h).clamp(0.0, (h - size - 12.0).max(0.0)),
        )
    } else {
        let (x, y) = corners.place(Corner::BottomLeft, size, size + 12.0);
        // A preceding native panel can consume the corner. Avoid drawing offscreen.
        if x < 0.0 || y < 2.0 || x + size > w {
            return None;
        }
        (x, y)
    };
    super::sunset_hud_bars::place("Radar", [x, y, size, size + 12.0], w, h);
    Some([x, y, size])
}

// The radar at the place `place` gave it.
pub(super) fn draw(game: &Game<'_>, batch: &mut HudBatch, [x, y, size]: [f32; 3], modules: &[Module]) {
    let Some(module) = modules.iter().find(|m| m.name == "Radar" && m.on) else {
        return;
    };
    let Some(player) = game.player.as_ref() else {
        return;
    };
    let center = [x + size / 2.0, y + size / 2.0];
    let radius = size / 2.0 - 1.0;
    let reach = radius - 17.0;
    let pixel = pixel_width(batch.scale);
    let rotate = module.b("Rotate");
    let yaw = f64::from(game.yaw);
    let range = module.n("Range");
    let alpha = game.clock.camera_fraction();
    let lerp = |previous: f64, current: f64| previous + alpha * (current - previous);
    let local = [
        lerp(game.previous_position.x, player.position.x),
        lerp(game.previous_position.z, player.position.z),
    ];
    let own = own_id(game);
    let color = module.c("Players color");
    // The players on it: where on the radar, from its middle.
    let dots = game
        .mobs
        .iter()
        .filter(|other| {
            other.kind.id == "minecraft:player"
                && Some(other.id) != own
                && other.alive()
                && !other.removed
                && !other.is_invisible()
                && !super::remote::sunset_radar_players::spectator(game, other.id)
        })
        .filter_map(|other| {
            let dx = lerp(other.previous.x, other.position.x) - local[0];
            let dz = lerp(other.previous.z, other.position.z) - local[1];
            project(dx, dz, yaw, rotate, range, reach - 3.0)
        });
    if module.p("Mode") == "Potato" {
        game.native_fill(batch, [x, y, size, size], 0xD016_1B24);
        for [ox, oy] in dots {
            game.native_fill(batch, [center[0] + ox - 2.0, center[1] + oy - 2.0, 4.0, 4.0], color);
        }
        game.native_fill(batch, [center[0] - 2.0, center[1] - 2.0, 4.0, 4.0], 0xFF00_0000 | accent());
        return;
    }
    // Keep the background fringe under the solid rim, so only one layer
    // contributes coverage at the outer device-pixel edge.
    disc(game, batch, center, radius - pixel, 0xD016_1B24);
    band(
        game,
        batch,
        center,
        radius - pixel * 1.5,
        radius - pixel * 0.5,
        circle_segments(radius, batch.scale),
        0xFF58_6371,
        false,
    );
    band(
        game,
        batch,
        center,
        radius - pixel * 0.5,
        radius + pixel * 0.5,
        circle_segments(radius, batch.scale),
        0xFF58_6371,
        true,
    );
    game.native_fill(
        batch,
        [center[0] - reach, center[1], reach * 2.0, pixel],
        0xFF35_3E49,
    );
    game.native_fill(
        batch,
        [center[0], center[1] - reach, pixel, reach * 2.0],
        0xFF35_3E49,
    );

    for (label, dx, dz) in [
        ("N", 0.0, -1.0),
        ("E", 1.0, 0.0),
        ("S", 0.0, 1.0),
        ("W", -1.0, 0.0),
    ] {
        let [ox, oy] = offset(dx, dz, yaw, rotate);
        let at = [
            center[0] + ox as f32 * (radius - 8.0) - game.native_text_width(label) / 2.0,
            center[1] + oy as f32 * (radius - 8.0) - 4.0,
        ];
        game.native_text(
            batch,
            label,
            at,
            if label == "N" { accent() } else { 0xC6CFD9 },
            true,
        );
    }

    let mut count = 0;
    for [ox, oy] in dots {
        let dot = [center[0] + ox, center[1] + oy];
        disc(game, batch, dot, 3.2, 0xFF09_0D13);
        disc(game, batch, dot, 2.3, color);
        count += 1;
    }
    disc(game, batch, center, 3.0, 0xFF00_0000 | accent());
    let [fx, fy] = if rotate {
        [0.0, -1.0]
    } else {
        let (sin, cos) = yaw.to_radians().sin_cos();
        [-sin as f32, cos as f32]
    };
    // Short heading marker distinguishes the local center from other players.
    for i in 4..8 {
        game.native_fill(
            batch,
            [
                center[0] + fx * i as f32 - 0.6,
                center[1] + fy * i as f32 - 0.6,
                1.2,
                1.2,
            ],
            0xFF00_0000 | accent(),
        );
    }
    let caption = format!("Radar  {range:.0}m  {count} players");
    game.native_text(batch, &caption, [x, y + size + 2.0], 0xC6CFD9, true);
}

// Radar geometry for Horizon.

use std::sync::OnceLock;

const CIRCLE_POINTS: usize = 256;
static CIRCLE: OnceLock<[[f32; 2]; CIRCLE_POINTS]> = OnceLock::new();

// Physical pixels, not GUI pixels: edges stay one device pixel wide even
// with a fractional desktop scale or a large Minecraft GUI scale.
pub(super) fn pixel_width(scale: f32) -> f32 {
    if scale.is_finite() && scale > 0.0 {
        scale.recip()
    } else {
        1.0
    }
}

pub(super) fn circle_segments(radius: f32, scale: f32) -> usize {
    let physical_radius = f64::from(radius.max(0.0) / pixel_width(scale));
    // Bound the maximum chord error to a quarter of a device pixel for
    // supported window sizes, while keeping small markers inexpensive.
    [16, 32, 64, 128, 256]
        .into_iter()
        .find(|&segments| {
            physical_radius * (1.0 - (std::f64::consts::PI / segments as f64).cos()) <= 0.25
        })
        .unwrap_or(CIRCLE_POINTS)
}

pub(super) fn circle_point(center: [f32; 2], radius: f32, i: usize, segments: usize) -> [f32; 2] {
    let points = CIRCLE.get_or_init(|| {
        std::array::from_fn(|j| {
            let angle = std::f64::consts::TAU * j as f64 / CIRCLE_POINTS as f64;
            [angle.cos() as f32, angle.sin() as f32]
        })
    });
    let [x, y] = points[(i % segments) * (CIRCLE_POINTS / segments)];
    [center[0] + radius * x, center[1] + radius * y]
}

// North-up uses +X right, +Z down. Rotating puts the player's forward
// direction up (Minecraft yaw zero faces +Z).
pub(super) fn offset(dx: f64, dz: f64, yaw: f64, rotate: bool) -> [f64; 2] {
    if !rotate {
        return [dx, dz];
    }
    let (sin, cos) = yaw.to_radians().sin_cos();
    [-dx * cos - dz * sin, dx * sin - dz * cos]
}

pub(super) fn project(
    dx: f64,
    dz: f64,
    yaw: f64,
    rotate: bool,
    range: f64,
    radius: f32,
) -> Option<[f32; 2]> {
    if ![dx, dz, yaw, range, f64::from(radius)]
        .iter()
        .all(|n| n.is_finite())
        || range <= 0.0
        || radius <= 0.0
        || dx.hypot(dz) > range
    {
        return None;
    }
    let [x, y] = offset(dx, dz, yaw, rotate);
    Some([(x / range) as f32 * radius, (y / range) as f32 * radius])
}

pub(super) fn fitted_size(requested: f32, width: f32, height: f32) -> Option<f32> {
    // Four pixels of screen margin, twelve for the range label. Do not
    // rewrite the saved setting when temporarily fitting a small viewport.
    let size = requested.min(width - 4.0).min(height - 16.0).floor();
    (size.is_finite() && size >= 64.0).then_some(size)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn near(actual: [f32; 2], expected: [f32; 2]) {
        assert!(
            (actual[0] - expected[0]).abs() < 0.001,
            "{actual:?} != {expected:?}"
        );
        assert!(
            (actual[1] - expected[1]).abs() < 0.001,
            "{actual:?} != {expected:?}"
        );
    }

    #[test]
    fn north_up_and_heading_up_match_minecraft_cardinal_yaws() {
        near(project(0., -24., 0., false, 48., 60.).unwrap(), [0., -30.]);
        near(project(24., 0., 90., false, 48., 60.).unwrap(), [30., 0.]);
        // Forward at yaw 0, 90, 180 and -90 must always appear above center.
        for (dx, dz, yaw) in [
            (0., 24., 0.),
            (-24., 0., 90.),
            (0., -24., 180.),
            (24., 0., -90.),
        ] {
            near(project(dx, dz, yaw, true, 48., 60.).unwrap(), [0., -30.]);
        }
        near(project(24., 0., 0., true, 48., 60.).unwrap(), [-30., 0.]);
    }

    #[test]
    fn range_is_horizontal_inclusive_and_rejects_invalid_coordinates() {
        near(project(48., 0., 0., false, 48., 60.).unwrap(), [60., 0.]);
        assert!(project(48.001, 0., 0., false, 48., 60.).is_none());
        assert!(project(40., 40., 0., true, 48., 60.).is_none());
        assert!(project(f64::NAN, 0., 0., false, 48., 60.).is_none());
        assert!(project(0., 0., f64::INFINITY, true, 48., 60.).is_none());
        assert!(project(0., 0., 0., false, 0., 60.).is_none());
    }

    #[test]
    fn requested_size_fits_small_viewports_without_mutating_settings() {
        assert_eq!(fitted_size(150., 427., 240.), Some(150.));
        assert_eq!(fitted_size(320., 320., 180.), Some(164.));
        assert_eq!(fitted_size(150., 70., 100.), Some(66.));
        assert_eq!(fitted_size(150., 60., 100.), None);
    }

    #[test]
    fn edge_width_is_one_physical_pixel_at_fractional_and_integer_gui_scales() {
        for scale in [0.75, 1.0, 1.25, 1.5, 2.0, 3.0, 4.0, 8.0] {
            assert!((pixel_width(scale) * scale - 1.0).abs() < 0.00001);
        }
        assert_eq!(pixel_width(f32::NAN), 1.0);
        assert_eq!(pixel_width(0.0), 1.0);
    }

    #[test]
    fn circle_tessellation_tracks_device_resolution_with_bounded_chord_error() {
        for radius in [2.3, 3.0, 49.0, 74.0, 159.0] {
            for scale in [1.0, 1.25, 2.0, 3.0, 4.0, 8.0] {
                let segments = circle_segments(radius, scale);
                let error = f64::from(radius * scale)
                    * (1.0 - (std::f64::consts::PI / segments as f64).cos());
                assert!(error <= 0.25001, "{radius} at scale {scale}: {error}");
                assert!(segments <= 256 && segments >= 16 && segments.is_power_of_two());
            }
        }
        assert!(circle_segments(74.0, 3.0) > circle_segments(74.0, 1.0));
    }

    #[test]
    fn cached_circle_vertices_are_closed_and_not_quantized_to_gui_scanlines() {
        near(circle_point([0., 0.], 10., 0, 64), [10., 0.]);
        near(circle_point([0., 0.], 10., 16, 64), [0., 10.]);
        near(circle_point([0., 0.], 10., 64, 64), [10., 0.]);
        let [x, y] = circle_point([0., 0.], 10., 1, 64);
        assert!((x.hypot(y) - 10.0).abs() < 0.00001);
        assert!((y - y.round()).abs() > 0.01);
    }
}

// Inventory routines on modules that had a silent version already: Auto Replenish's Inventory open and Key modes and
// its Potion refill, and Inventory Manager's Loot key. Each is one click step at a time with the module's delay
// between, from the player's own inventory menu (no container open), never from a slot Loadouts locks.
use super::sunset::{Module, key_from_text, menu_click};
use super::sunset_util::short;
use super::{Game, Screen};
use horizon_client::menu::Input::{Pickup, QuickMove};
use std::sync::Mutex;

#[derive(Default)]
struct Refill {
    // Keys held now, as the game names them.
    down: Vec<String>,
    replenish_wait: u32,
    potion_wait: u32,
}

static REFILL: Mutex<Option<Refill>> = Mutex::new(None);

pub(super) fn shutdown() { *REFILL.lock().unwrap_or_else(|e| e.into_inner()) = None; }

fn st<R>(f: impl FnOnce(&mut Refill) -> R) -> R {
    f(REFILL.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Refill::default))
}

pub(super) fn key(key: &str, pressed: bool) {
    st(|s| {
        s.down.retain(|k| k != key);
        if pressed {
            s.down.push(key.to_owned());
        }
    });
}

// Whether the key a setting names is held.
fn held(m: &Module, setting: &str) -> bool {
    key_from_text(m.t(setting)).is_some_and(|k| st(|s| s.down.contains(&k)))
}

// The player's inventory screen is open (not a container's).
fn inventory_screen(game: &Game<'_>) -> bool {
    game.screen == Screen::Inventory && game.remote_menu().1 == "inventory" && game.remote.is_some() && game.player.is_some()
}

// A step's wait: counts down a tick, true while some is left.
fn waiting(wait: impl FnOnce(&mut Refill) -> &mut u32) -> bool {
    st(|s| {
        let w = wait(s);
        *w = w.saturating_sub(1);
        *w > 0
    })
}

fn splash(game: &Game<'_>, slot: usize, healing_only: bool) -> bool {
    game.inventory.get(slot).and_then(|s| s.as_ref()).is_some_and(|s| {
        short(&s.item) == "splash_potion" && (!healing_only || s.potion().is_some_and(|p| short(p).ends_with("healing")))
    })
}

// Auto Replenish's modes beside Silent. Inventory open: with your inventory screen open, a hotbar stack at or under
// Threshold (one that stacks and isn't full) is topped up from the main inventory: pick that stack up, put it on the
// hotbar one (it fills to full), put what is left back. Key: the same while Refill key is held, the screen open or
// not. Potion refill: with the screen open, a splash potion (only healing ones, with Healing only) shift-clicked from
// the main inventory into an empty hotbar slot.
pub(super) fn replenish(game: &mut Game<'_>, m: &Module) {
    let screen = inventory_screen(game);
    if m.b("Potion refill") && screen && !waiting(|s| &mut s.potion_wait) {
        let locked = super::sunset_loadouts::locked_slots();
        let room = (0..9).any(|h| !locked[h] && game.inventory.get(h).is_some_and(Option::is_none));
        let healing = m.b("Healing only");
        if let Some(src) = (9..36).find(|&i| !locked[i] && splash(game, i, healing)).filter(|_| room) {
            if menu_click(game, &[(src, QuickMove)]) {
                st(|s| s.potion_wait = m.n("Potion delay (ticks)") as u32 + 1);
            }
            return;
        }
    }
    let ready = match m.p("Mode") {
        "Inventory open" => screen,
        "Key" => held(m, "Refill key") && (screen || super::sunset::inventory_idle(game)),
        _ => false,
    };
    if !ready || waiting(|s| &mut s.replenish_wait) {
        return;
    }
    let locked = super::sunset_loadouts::locked_slots();
    for h in (0..9).filter(|&h| !locked[h]) {
        let Some(st_h) = game.inventory.get(h).and_then(|s| s.as_ref()) else {
            continue;
        };
        let max = game.res.items().get(&st_h.item).map_or(64, |i| i.max_stack);
        if max <= 1 || st_h.count >= max || f64::from(st_h.count) > m.n("Threshold") {
            continue;
        }
        let item = st_h.item.clone();
        let source = (9..36).find(|&i| !locked[i] && game.inventory.get(i).and_then(|s| s.as_ref()).is_some_and(|s| s.item == item));
        if let Some(src) = source {
            if menu_click(game, &[(src, Pickup), (h, Pickup), (src, Pickup)]) {
                st(|s| s.replenish_wait = m.n("Delay (ticks)") as u32);
            }
            return;
        }
    }
}

pub(super) fn looting(m: &Module) -> bool {
    held(m, "Loot key")
}

// Inventory Manager executes Loot through its shared cursor/input/settle gates, not a second independent timer.
// Holding the key replaces normal cleanup, even when there is nothing left to drop.
pub(super) fn loot_step(game: &Game<'_>, m: &Module, locked: &[bool; 36]) -> Option<usize> {
    let slots = |item: &str| -> Vec<usize> {
        (0..36).filter(|&i| game.inventory.get(i).and_then(|s| s.as_ref()).is_some_and(|s| short(&s.item) == item)).collect()
    };
    let extra = |found: Vec<usize>, keep: f64| (found.len() as f64 > keep).then(|| found.into_iter().find(|&i| !locked[i])).flatten();
    extra(slots("totem_of_undying"), m.n("Keep totems")).or_else(|| extra(slots("ender_pearl"), m.n("Keep pearl stacks")))
}

