// Every module off and their pending work dropped (Panic, and the plugin API's stop_everything).
pub(super) fn panic_off_state(s: &mut State) -> Option<(f32, f32)> {
    for m in &mut s.modules {
        m.on = false;
    }
    s.strafe = Strafe::default();
    s.bhop.reset();
    s.ncp.reset();
    s.watchdog.reset();
    s.legacy_recovery = Default::default();
    s.knockback_ticks = 0;
    s.velocity = None;
    s.blast = [0.0; 3];
    s.scaffold_stack = None;
    s.inputs.suspend();
    s.binding = None;
    s.tool_wait = None;
    s.mc_use = None;
    s.mc_back = None;
    s.crit_target = None;
    s.crit_look = None;
    s.trigger_sticky = None;
    s.trigger_missed = None;
    s.eat_paused_aura = false;
    s.scaffold_placed.clear();
    s.blocks = Sweep::new();
    s.holes = Sweep::new();
    s.unsneaked = false;
    s.blink_ticks = 0;
    s.fly_delay = 0;
    s.fly_off = 0;
    s.nuke = None;
    s.nuke_skip.clear();
    s.nuke_interacted.clear();
    s.nuke_box = None;
    s.nuke_broken.clear();
    take_scaffold_rotation(&mut s.scaffold_rotation)
}

// Every module off (Panic, and the plugin API's stop_everything).
pub(super) fn mapped_input(
    bindings: &horizon_client::keybinds::KeyBinds,
    keys: &std::collections::HashSet<KeyCode>,
    buttons: &std::collections::HashSet<MouseButton>,
    toggles: [Option<bool>; 4],
) -> (std::collections::HashSet<KeyCode>, std::collections::HashSet<MouseButton>) {
    let mut held = (std::collections::HashSet::new(), std::collections::HashSet::new());
    for action in keys.iter().flat_map(|k| bindings.translate_all(*k))
        .chain(buttons.iter().flat_map(|b| bindings.translate_mouse_all(*b))) {
        match action { Ok(k) => { held.0.insert(k); } Err(b) => { held.1.insert(b); } }
    }
    for (slot, key) in [KeyCode::ShiftLeft, KeyCode::ControlLeft].into_iter().enumerate() {
        if let Some(down) = toggles[slot] {
            if down { held.0.insert(key); } else { held.0.remove(&key); }
        }
    }
    for (i, button) in [MouseButton::Left, MouseButton::Right].into_iter().enumerate() {
        if let Some(down) = toggles[i + 2] {
            if down { held.1.insert(button); } else { held.1.remove(&button); }
        }
    }
    held
}

pub(super) fn native_held_input(game: &Game<'_>) -> (std::collections::HashSet<KeyCode>, std::collections::HashSet<MouseButton>) {
    let options = [game.settings.toggle_crouch, game.settings.toggle_sprint, game.settings.toggle_attack, game.settings.toggle_use];
    let toggles = std::array::from_fn(|i| (options[i] || game.toggles.is_down(i)).then(|| game.toggles.is_down(i)));
    let mut held = mapped_input(&game.settings.keys, &game.physical_keys, &game.physical_buttons, toggles);
    for (mapping, key) in [("key.forward", KeyCode::KeyW), ("key.back", KeyCode::KeyS), ("key.left", KeyCode::KeyA),
        ("key.right", KeyCode::KeyD), ("key.jump", KeyCode::Space), ("key.sneak", KeyCode::ShiftLeft), ("key.sprint", KeyCode::ControlLeft)] {
        if game.pad.holds_action(mapping) { held.0.insert(key); }
    }
    for (mapping, button) in [("key.attack", MouseButton::Left), ("key.use", MouseButton::Right)] {
        if game.pad.holds_action(mapping) { held.1.insert(button); }
    }
    held
}

pub(super) fn all_off(game: &mut Game<'_>) {
    watchdog_stop(game, true);
    super::sunset_hands::release_rf(game);
    super::remote::sunset_combat_remote::restore_buttons(game);
    let native_input = native_held_input(game);
    let sprint_owned = with(|s| std::mem::take(&mut s.sprint_owned));
    // Turn modules off before any release method can send or consult settings.
    let restore = with(panic_off_state);
    GUI_TOP.lock().unwrap_or_else(|e| e.into_inner()).0.clear();
    SHAPES.lock().unwrap_or_else(|e| e.into_inner()).clear();
    with(sync_flags);
    let injected = with(|s| std::mem::take(&mut s.injected));
    for k in injected {
        if !native_input.0.contains(&k) { game.keys.remove(&k); }
    }
    super::sunset_server_scan::disabled();
    horizon_client::net::sunset_client_brand::next(None);
    super::agent::sunset_goto::cancel(game, "stopped by Panic");
    super::sunset_gui_move::shutdown(game);
    combat_cleanup(game);
    legit_sneak(game, false);
    super::sunset_scaffold_bridge::stop(game);
    super::sunset_scaffold_normal::stop(game);
    super::sunset_scaffold_telly::stop(game);
    super::sunset_lag::shutdown(game);
    super::sunset_backtrack::shutdown();
    super::sunset_knockback_delay::shutdown();
    super::sunset_packet_mine::toggled(game, "Packet Mine", false);
    super::sunset_duel::shutdown(game);
    super::sunset_swap_keys::shutdown(game);
    super::sunset_takeoff::shutdown(game);
    super::sunset_drain::shutdown(game);
    super::sunset_hands::shutdown(game);
    if with(|s| s.eating) { eat_stop(game); }
    super::sunset_snap_tap::post_tick(game);
    auto_tool_off(game);
    with(|s| { s.tool_back = None; s.tool_pulled = None; s.eating = false; s.eat_slot = None; });
    turns(|t| { t.queue.clear(); t.carried = false; t.restore = false; });
    BLINK_HELD.store(false, Ordering::Relaxed);
    super::sunset_flight::stop(game);
    super::sunset_flight::damage_reset();
    FLY_DOWN.store(false, Ordering::Relaxed);
    FLY_LAST_Y.store(u64::MAX, Ordering::Relaxed);
    set_last_look(None);
    super::sunset_sky::real(game);
    super::sunset_sky::forget();
    super::sunset_atmosphere::sync(game);
    super::sunset_render::shutdown(game);
    super::sunset_parity::shutdown(game);
    super::sunset_player::shutdown(game);
    super::sunset_extras::shutdown(game);
    super::sunset_refill::shutdown();
    super::sunset_world_parity::tick(game, &[]);
    super::sunset_vanish::tick(game, None);
    super::sunset_base_finder::tick(game, None);
    super::sunset_hunting::tick(game, &[]);
    super::sunset_light_scan::tick(game, &[]);
    super::sunset_sound_detector::tick(game, None);
    super::sunset_gear::tick(game, &[]);
    super::sunset_new_chunks::tick(game, &[]);
    super::sunset_ore_sim::tick(game, &[]);
    super::sunset_hud_bars::tick(game, &[], false);
    super::sunset_hud_bars::chat_closed();
    super::sunset_streamer_mode::frame(game);
    if let Some((yaw, pitch)) = restore {
        game.yaw = yaw;
        game.pitch = pitch;
    }
    horizon_client::motion::sunset_motion::set_across(None);
    horizon_client::motion::sunset_motion::set_up(None);
    horizon_client::motion::sunset_motion::set_strafe_dir(None);
    bhop_body(game, None);
    horizon_client::motion::sunset_motion::set_safe_walk(false);
    horizon_client::input::sunset_flags::NO_SLOW.store(false, Ordering::Relaxed);
    horizon_client::motion::sunset_motion::reset();
    let (flying, stepping, jumping) = with(|s| {
        let old = (s.flying, s.stepping, s.high_jumping);
        s.flying = false; s.stepping = false; s.high_jumping = false;
        old
    });
    let spectator = game.spectator();
    if let Some(p) = game.player.as_mut() {
        if flying {
            p.flying = (game.creative && p.flying) || spectator;
            p.may_fly = game.creative || spectator;
            p.flying_speed = 0.05;
        }
        if stepping { let _ = p.set_modifier("minecraft:step_height", "sunset:step", 0.0, "add_value", false); }
        if jumping { let _ = p.set_modifier("minecraft:jump_strength", "sunset:high_jump", 0.0, "add_multiplied_total", false); }
        if sprint_owned && !native_input.0.contains(&KeyCode::ControlLeft) { let _ = p.set_sprinting(false); }
    }
    save(game);
    if gui_open() {
        close_gui(game);
    }
    super::remote::sunset_combat_remote::cancel_input(game);
    // Release methods may temporarily take a real key/button up. Restore the
    // physical state without synthesizing new clicks or replaying queued input.
    if game.native_playing() {
        for key in [KeyCode::KeyW, KeyCode::KeyA, KeyCode::KeyS, KeyCode::KeyD, KeyCode::Space, KeyCode::ShiftLeft, KeyCode::ControlLeft] {
            if native_input.0.contains(&key) { game.keys.insert(key); } else { game.keys.remove(&key); }
        }
        game.left = native_input.1.contains(&MouseButton::Left);
        game.right = native_input.1.contains(&MouseButton::Right);
    }
}

// Panic (the module, its key, .panic, or a plugin turning it on): Sunset stops until the game restarts.
pub(super) fn panic_off(game: &mut Game<'_>) {
    shutdown(game, "Panic");
}

// .profile save|load|delete|list <name>: the modules' settings kept under a name.
// Profiles (`.profile`): files in the mod's data folder (sunset_profiles), with a backup of the settings before every
// load. Profiles from before 0.9 (kept in the mod's settings) move into files the first time.
fn profile_command(game: &mut Game<'_>, args: &[&str]) {
    let result = profile_action(game, args);
    say(game, &result.unwrap_or_else(|e| format!("Profile: {e}.")));
}

pub(super) fn profile_action(game: &mut Game<'_>, args: &[&str]) -> Result<String, String> {
    use super::sunset_profiles::{self as profiles, BACKUP, HEADER};
        let store = profiles::Store::new(game.native_data_dir(ID))?;
        let old: Vec<String> = game.native_setting(ID, "profiles").unwrap_or_default().split(',').filter(|n| !n.is_empty()).map(str::to_owned).collect();
        for n in &old {
            let key = format!("profile-{}", norm(n));
            if let (Ok(file), Some(text)) = (profiles::name(n), game.native_setting(ID, &key))
                && !store.exists(&file)
            {
                store.write(&file, &format!("{HEADER}\n{text}\n"))?;
            }
            game.native_set_setting(ID, &key, "");
        }
        if !old.is_empty() {
            game.native_set_setting(ID, "profiles", "");
        }
        let sub = args.first().map(|a| a.to_ascii_lowercase()).unwrap_or_default();
        if sub == "list" {
            let all = store.list()?;
            let in_use = with(|s| s.selection.label());
            return Ok(if all.is_empty() {
                "No profiles yet. .profile save <name> keeps the current settings.".to_owned()
            } else {
                format!("Profiles: {}. In use: {in_use}", all.join(", "))
            });
        }
        let Some(name) = args.get(1..).filter(|rest| !rest.is_empty()).map(|rest| profiles::name(&rest.join(" "))).transpose()? else {
            return Err("use .profile save|load|delete|export|import <name>, or .profile list".into());
        };
        if name == BACKUP && sub != "load" {
            return Err(format!("{BACKUP} is the settings before the last load; .profile load {BACKUP} puts them back"));
        }
        match sub.as_str() {
            "save" => {
                let text = with(|s| s.profile_text());
                store.write(&name, &format!("{HEADER}\n{text}\n"))?;
                with(|s| s.select(&name));
                save(game);
                Ok(format!("Saved profile {name}."))
            }
            "load" => {
                let text = store.read(&name)?;
                let checked = with(|s| s.check_profile(&text))?;
                let before = with(|s| s.profile_text());
                store.write(BACKUP, &format!("{HEADER}\n{before}\n"))?;
                apply_profile(game, &checked.body, &name);
                Ok(format!("Loaded profile {name}. .profile load {BACKUP} puts the settings back as they were.{}", checked.skipped_note()))
            }
            "delete" => {
                store.delete(&name)?;
                with(|s| s.selection.deleted(&name));
                save(game);
                Ok(format!("Deleted profile {name}."))
            }
            "export" => Ok(format!("Profile {name} is in {}", store.export(&name)?.display())),
            "import" => {
                let text = store.import(&name).map_err(|e| format!("{e} (put {name}.profile in {})", store.imports().display()))?;
                let checked = with(|s| s.check_profile(&text))?;
                store.write(&name, &text)?;
                Ok(format!("Imported profile {name}; .profile load {name} uses it.{}", checked.skipped_note()))
            }
            _ => Err("use .profile save|load|delete|export|import <name>, or .profile list".into()),
        }
}

// .preset [name] [apply]: the pre-made profiles. A name alone says what taking it turns on and off; apply takes it.
fn preset_command(game: &mut Game<'_>, args: &[&str]) {
    use super::sunset_presets::{self as presets, PRESETS};
    let apply = args.len() > 1 && args.last().is_some_and(|a| a.eq_ignore_ascii_case("apply"));
    let name = args[..args.len() - usize::from(apply)].join(" ");
    if name.is_empty() {
        let list: Vec<&str> = PRESETS.iter().map(|p| p.id).collect();
        return say(game, &format!("Presets: {}. .preset <name> says what it turns on and off.", list.join(", ")));
    }
    let Some(i) = presets::find(&name) else {
        return say(game, &format!("Preset: there is none called {name}."));
    };
    if apply {
        let message = take_preset(game, i).unwrap_or_else(|e| format!("Preset: {e}."));
        return say(game, &message);
    }
    match with(|s| s.preview(&PRESETS[i])) {
        Ok(preview) => {
            for line in preview_lines(&PRESETS[i], &preview) {
                say(game, &line);
            }
            say(game, &format!(".preset {} apply takes it.", PRESETS[i].id));
        }
        Err(e) => say(game, &format!("Preset: {e}.")),
    }
}

// A preview as lines: the preset, then what it turns on and off and how many settings it changes.
pub(super) fn preview_lines(preset: &super::sunset_presets::Preset, preview: &Preview) -> Vec<String> {
    let names = |list: &[&str]| if list.is_empty() { "nothing".to_owned() } else { list.join(", ") };
    let mut lines = vec![
        format!("{} - {}", preset.title, preset.about),
        format!("Turns on: {}", names(&preview.on)),
        format!("Turns off: {}", names(&preview.off)),
    ];
    if preview.settings > 0 {
        lines.push(format!("Changes {} setting{}", preview.settings, if preview.settings == 1 { "" } else { "s" }));
    }
    lines
}

// Takes preset `i`, after a backup of the settings as they are (.profile load before-load brings them back).
pub(super) fn take_preset(game: &mut Game<'_>, i: usize) -> Result<String, String> {
    use super::sunset_profiles::{self as profiles, BACKUP, HEADER};
    let preset = &super::sunset_presets::PRESETS[i];
    let store = profiles::Store::new(game.native_data_dir(ID))?;
    let text = with(|s| s.preset_text(preset))?;
    let before = with(|s| s.profile_text());
    store.write(BACKUP, &format!("{HEADER}\n{before}\n"))?;
    apply_profile(game, &text, preset.id);
    Ok(format!("Took preset {}. .profile load {BACKUP} puts the settings back as they were.", preset.title))
}

// A profile's (or preset's) checked lines taken as `name`: what turning each module on or off does by hand happens for
// those it switches (Scaffold gives back your look, Kill Aura stops blocking and swaps back, Speed lets go of its
// motion...), Hold binds of modules it changed end, and the settings are saved.
fn apply_profile(game: &mut Game<'_>, body: &str, name: &str) {
    let before: Vec<bool> = with(|s| s.modules.iter().map(|m| m.on).collect());
    let switched = with(|s| {
        s.load_profile(body);
        release_changed_binds(s);
        let snapshot = s.profile_text();
        s.selection.loaded(name, &snapshot);
        s.modules.iter().zip(&before).filter(|(m, was)| m.on != **was).map(|(m, _)| (m.name, m.on)).collect::<Vec<_>>()
    });
    for (module, on) in switched {
        switched_effects(game, module, on);
    }
    save(game);
}

pub(super) fn apply_movement_preset(state: &mut State, style: &str) -> bool {
    let changes: &[(&str, &str, &str)] = match norm(style).as_str() {
        "subtle" => &[
            ("Speed", "Mode", "Smooth"), ("Speed", "Vanilla speed", "3"),
            ("Speed", "Only on ground", "true"), ("Speed", "Acceleration", "0.025"),
            ("Speed", "Deceleration", "0.04"), ("Speed", "Strafe strength", "0.5"),
            ("Velocity", "Mode", "Scale"), ("Velocity", "Knockback horizontal", "1"),
            ("Velocity", "Knockback vertical", "1"), ("Velocity", "Explosions horizontal", "1"),
            ("Velocity", "Explosions vertical", "1"),
            ("Scaffold", "Delay (ticks)", "2"), ("Scaffold", "Rotate", "true"),
            ("No Slow", "Mode", "Scale"), ("No Slow", "Ground %", "20"), ("No Slow", "Air %", "20"),
        ],
        "balanced" => &[
            ("Speed", "Mode", "Strafe"), ("Speed", "Strafe speed", "1.3"),
            ("Speed", "Speed limit", "true"),
            ("Velocity", "Mode", "Scale"), ("Velocity", "Knockback horizontal", "0.7"),
            ("Velocity", "Knockback vertical", "0.85"),
            ("Scaffold", "Delay (ticks)", "1"), ("Scaffold", "Rotate", "true"),
            ("No Slow", "Mode", "Scale"), ("No Slow", "Ground %", "70"), ("No Slow", "Air %", "70"),
        ],
        "aggressive" => &[
            ("Speed", "Mode", "Custom"), ("Speed", "Vanilla speed", "10"),
            ("Speed", "Only on ground", "false"), ("Speed", "Ground multiplier", "1.2"),
            ("Speed", "Air multiplier", "1.1"), ("Speed", "Acceleration", "0.15"),
            ("Speed", "Deceleration", "0.1"), ("Speed", "Strafe strength", "1"),
            ("Velocity", "Mode", "Scale"), ("Velocity", "Knockback horizontal", "0"),
            ("Velocity", "Knockback vertical", "0"),
            ("Scaffold", "Delay (ticks)", "0"), ("Scaffold", "Rotation speed", "180"),
            ("No Slow", "Mode", "Scale"), ("No Slow", "Ground %", "100"), ("No Slow", "Air %", "100"),
        ],
        _ => return false,
    };
    for &(module, setting, value) in changes {
        if let Some(s) = state.modules.iter_mut().find(|m| m.name == module)
            .and_then(|m| m.settings.iter_mut().find(|s| s.name == setting)) {
            s.parse(value);
        }
    }
    true
}

pub(super) fn run(game: &mut Game<'_>, args: &[&str]) {
    let cmd = args[0].to_ascii_lowercase();
    let module_arg = |game: &mut Game<'_>, name: Option<&&str>| -> Option<usize> {
        let Some(name) = name else {
            say(game, "Name a module.");
            return None;
        };
        let found = with(|s| s.find(name));
        if found.is_none() {
            say(game, &format!("No module called {name}. Try .modules"));
        }
        found
    };
    match cmd.as_str() {
        "auradebug" => say(game, &super::sunset_aura::diagnostics()),
        "antibotdebug" => {
            let id = args.get(1).and_then(|id| id.parse::<u32>().ok());
            for line in super::sunset_antibot::diagnostics(game, id) { say(game, &line); }
        }
        "scan" => super::sunset_server_scan::command(game, &args[1..]),
        "goto" => {
            let text = super::agent::sunset_goto::command(game, &args[1..]).unwrap_or_else(|e| e);
            say(game, &text);
        }
        "help" | "commands" => {
            say(game, "Commands:");
            for (c, d) in HELP {
                say(game, &format!("{c} - {d}"));
            }
            for (c, d) in super::sunset_api::help() {
                say(game, &format!("{c} - {d}"));
            }
        }
        "menu" | "gui" => {
            // `.menu esp` opens it with that search typed.
            let search: String = args[1..].join(" ").chars().take(20).collect();
            with(|s| s.gui.search = search);
            open_gui(game);
        }
        "pages" => open_menu(game),
        "toggle" | "t" => {
            if let Some(i) = module_arg(game, args.get(1)) {
                toggle(game, i, true);
            }
        }
        "modules" | "list" => {
            let lines: Vec<String> = with(|s| {
                CATEGORIES
                    .iter()
                    .map(|&c| {
                        let names: Vec<String> = s
                            .modules
                            .iter()
                            .filter(|m| m.category == c)
                            .map(|m| if m.on { format!("{}*", m.name) } else { m.name.to_owned() })
                            .collect();
                        format!("{}: {}", c.label(), names.join(", "))
                    })
                    .collect()
            });
            for l in lines {
                say(game, &l);
            }
            say(game, "* is on.");
        }
        "settings" | "get" => {
            if let Some(i) = module_arg(game, args.get(1)) {
                let lines: Vec<String> = with(|s| s.modules[i].settings.iter().map(Setting::shown).collect());
                if lines.is_empty() {
                    say(game, "It has no settings.");
                }
                for l in lines {
                    say(game, &l);
                }
            }
        }
        "set" => {
            let Some(i) = module_arg(game, args.get(1)) else {
                return;
            };
            if args.len() < 4 {
                say(game, "Use .set <module> <setting> <value>");
                return;
            }
            // The setting's name is the first words that name one (exactly, else
            // by its start); the rest is the value, spaces and all.
            let (found, value) = with(|s| {
                let m = &s.modules[i];
                for exact in [true, false] {
                    for k in (1..args.len() - 2).rev() {
                        let name = norm(&args[2..2 + k].join(""));
                        let at = m.settings.iter().position(|st| {
                            if exact { norm(st.name) == name } else { norm(st.name).starts_with(&name) }
                        });
                        if let Some(at) = at {
                            return (Some(at), args[2 + k..].join(" "));
                        }
                    }
                }
                (None, String::new())
            });
            let value = value.as_str();
            let result = found.and_then(|at| {
                with(|s| {
                    let m = &mut s.modules[i];
                    let setting = &mut m.settings[at];
                    let alias = m.name == "Kill Aura" && setting.name == "Shield";
                    let parsed = setting.parse(value);
                    let shown = setting.shown();
                    if parsed && alias {
                        let mode = if m.b("Shield") { "Modern" } else { "Off" };
                        if let Some(s) = m.settings.iter_mut().find(|s| s.name == "AutoBlock") { s.parse(mode); }
                    }
                    Some((parsed, shown))
                })
            });
            match result {
                None => say(game, "No such setting. Try .settings <module>"),
                Some((false, shown)) => say(game, &format!("Could not read {value}. Now {shown}")),
                Some((true, shown)) => {
                    save(game);
                    say(game, &shown);
                }
            }
        }
        "movementpreset" => {
            if let Some(style) = args.get(1) && with(|s| apply_movement_preset(s, style)) {
                save(game);
                say(game, &format!("{style} movement preset applied. Use .settings <module> to inspect values."));
            } else {
                say(game, "Use .movementpreset subtle, balanced or aggressive");
            }
        }
        "bind" => {
            let Some(i) = module_arg(game, args.get(1)) else {
                return;
            };
            let Some(k) = args.get(2) else {
                say(game, "Use .bind <module> <key or mouse1 to mouse5>, or none");
                return;
            };
            let key = if k.eq_ignore_ascii_case("none") {
                None
            } else {
                match key_from_text(k) {
                    Some(key) => Some(key),
                    None => {
                        say(game, &format!("Unknown key {k}."));
                        return;
                    }
                }
            };
            let name = with(|s| {
                set_bind(s, i, key.clone());
                s.modules[i].name
            });
            save(game);
            say(game, &format!("{name} bound to {}", key_label(key.as_deref())));
        }
        "binds" => {
            let lines: Vec<String> = with(|s| {
                s.modules
                    .iter()
                    .filter_map(|m| {
                        let hold = if m.p("Bind mode") == "Hold" { " (hold)" } else { "" };
                        m.key.as_deref().map(|k| format!("{}: {}{hold}", m.name, key_label(Some(k))))
                    })
                    .collect()
            });
            if lines.is_empty() {
                say(game, "No key binds yet.");
            }
            for l in lines {
                say(game, &l);
            }
        }
        "panic" => panic_off(game),
        "debug" => match args.get(1).map(|n| n.parse::<usize>()) {
            Some(Err(_)) => say(game, "Usage: .debug [chat lines]"),
            lines => super::sunset_debug::copy(game, lines.and_then(Result::ok)),
        },
        "profile" | "profiles" | "config" | "cfg" => profile_command(game, &args[1..]),
        "preset" | "presets" => preset_command(game, &args[1..]),
        "reset" => {
            if let Some(i) = module_arg(game, args.get(1)) {
                let name = with(|s| {
                    s.inputs.take_where(|h| h.module == i);
                    let fresh = fresh_module(s, i);
                    s.modules[i] = fresh;
                    s.modules[i].name
                });
                if name == "Server Scan" { super::sunset_server_scan::disabled(); }
                save(game);
                say(game, &format!("{name} reset."));
            }
        }
        "friend" | "friends" | "f" => {
            let sub = args.get(1).map(|s| s.to_ascii_lowercase());
            match (sub.as_deref(), args.get(2)) {
                (Some("add"), Some(name)) => {
                    with(|s| {
                        if !s.friends.iter().any(|f| f.eq_ignore_ascii_case(name)) {
                            s.flip_friend(name);
                        }
                    });
                    save(game);
                    say(game, &format!("{name} is a friend."));
                }
                (Some("remove" | "del" | "rm"), Some(name)) => {
                    with(|s| {
                        if s.friends.iter().any(|f| f.eq_ignore_ascii_case(name)) {
                            s.flip_friend(name);
                        }
                    });
                    save(game);
                    say(game, &format!("{name} is no longer a friend."));
                }
                _ => {
                    let list = with(|s| s.friends.join(", "));
                    say(game, &format!("Friends: {}", if list.is_empty() { "none" } else { &list }));
                }
            }
        }
        "loadout" | "loadouts" => super::sunset_loadouts::command(game, args),
        "waypoint" | "waypoints" | "wp" => {
            let sub = args.get(1).map(|a| a.to_ascii_lowercase());
            match (sub.as_deref(), args.get(2)) {
                (Some("add" | "set"), Some(name)) => {
                    let Some(p) = game.native_player() else {
                        say(game, "Join a world first.");
                        return;
                    };
                    let w = Waypoint {
                        name: (*name).replace(['|', '='], ""),
                        pos: [p.x.floor() + 0.5, p.y.floor() + 1.0, p.z.floor() + 0.5],
                        dim: p.dimension.to_owned(),
                    };
                    with(|s| {
                        s.waypoints.retain(|o| !o.name.eq_ignore_ascii_case(&w.name) || o.dim != w.dim);
                        s.waypoints.push(w.clone());
                        if let Some(i) = s.find("Waypoints") {
                            s.modules[i].on = true;
                        }
                    });
                    save(game);
                    say(game, &format!("Saved {} at {} {} {}", w.name, w.pos[0].floor(), w.pos[1].floor(), w.pos[2].floor()));
                }
                (Some("remove" | "del" | "rm"), Some(name)) => {
                    with(|s| s.waypoints.retain(|o| !o.name.eq_ignore_ascii_case(name)));
                    save(game);
                    say(game, &format!("Removed {name}."));
                }
                _ => {
                    let lines: Vec<String> = with(|s| {
                        s.waypoints
                            .iter()
                            .map(|w| format!("{}: {} {} {} ({})", w.name, w.pos[0].floor(), w.pos[1].floor(), w.pos[2].floor(), w.dim.trim_start_matches("minecraft:")))
                            .collect()
                    });
                    if lines.is_empty() {
                        say(game, "No waypoints. Use .waypoint add <name>");
                    }
                    for l in lines {
                        say(game, &l);
                    }
                }
            }
        }
        "vclip" | "hclip" => {
            let Some(d) = args.get(1).and_then(|a| a.parse::<f64>().ok()) else {
                say(game, &format!("Use .{cmd} <blocks>"));
                return;
            };
            let yaw = f64::from(game.yaw).to_radians();
            if let Some(p) = game.player.as_mut() {
                if cmd == "vclip" {
                    p.position.y += d;
                } else {
                    p.position.x += -yaw.sin() * d;
                    p.position.z += yaw.cos() * d;
                }
                p.velocity = horizon_core::geometry::Vec3::ZERO;
            }
        }
        "plugins" => super::sunset_api::list(game),
        _ => {
            if !super::sunset_api::command(game, &cmd, &args[1..]) {
                say(game, &format!("Unknown command .{cmd}. Try .help"));
            }
        }
    }
}

// Runtime part (see runtime.rs): reading and merging the config and profiles, presets' previews.

use super::sunset::*;

// What a preset turns on and off, and the number of settings it changes.
#[derive(Clone, Debug, Default)]
pub(super) struct Preview {
    pub(super) on: Vec<&'static str>,
    pub(super) off: Vec<&'static str>,
    pub(super) settings: usize,
}

// Offhand's settings from before Sunset's Auto Totem (0.9): set_field turns Health, Refill and Swap delay into the new
// ones, and the rest are gone.
pub(super) const OFFHAND_RETIRED: [&str; 10] =
    ["health", "elytra", "fall", "explosion", "refill", "reactiondelay", "swapdelay", "closedelay", "switchbackdelay", "doublehand"];

// Settings that are gone: Client Sort's old orders, lists and pace (0.9), PvP Bot's City (with Auto City, after
// 1.1.0). Their lines go.
const DROPPED: [(&str, &str); 9] = [
    ("clientsort", "order"), ("clientsort", "shiftorder"), ("clientsort", "ctrlorder"), ("clientsort", "altorder"),
    ("clientsort", "hotbar"), ("clientsort", "startitems"), ("clientsort", "enditems"), ("clientsort", "clickspertick"),
    ("pvpbot", "city"),
];

// Offhand took in Auto Totem, Auto Inventory Totem and Hover Totem, Fast Use took in FastXP, Velocity took in
// Knockback Delay, Kill Aura and Trigger Bot took in Auto Shield and Auto Weapon took in Shield Breaker, Mace and
// Spear Swap (0.9): a config or profile from before has their
// lines turned into the new module's. FastXP's are Throwables; Fast Use is on if either was (only for throwables, with
// an empty list, when Fast Use itself was off).
// Offhand is on if any of its three was, with the first key bound; the old Offhand's Item when it was on, else a totem
// always (Auto Totem Strict) or only when needed (None), else the new default; Refill is Auto Inventory Totem's Mode.
// Modules renamed since go by their new names first, and a config from before Extra Modules lists the extras it uses.
// Extra Modules is Modules (its switches the same; Pearl Catch shows unless switched off since).
// A profile as this version reads it: the lines it loads, and those it left out (what each was).
#[derive(Debug, Default)]
pub(super) struct Checked {
    pub(super) body: String,
    pub(super) skipped: Vec<String>,
}

impl Checked {
    // What was left out, for the message after a load or an import ("" when nothing was).
    pub(super) fn skipped_note(&self) -> String {
        match self.skipped.as_slice() {
            [] => String::new(),
            [one] => format!(" Left out a line this version doesn't know: {one}."),
            [first, rest @ ..] => format!(" Left out {} lines this version doesn't know, the first {first}.", rest.len() + 1),
        }
    }
}

// What a profile never carries: your friends (ClickGUI's Friends list: a profile from before you met someone would
// take them off it) and Panic's switch (a profile with it on would shut Sunset down as it loads).
pub(super) fn not_in_profiles(key: &str) -> bool {
    matches!(key.trim(), "clickgui.friends" | "panic.on")
}

pub(super) fn merged_modules(text: &str) -> std::borrow::Cow<'_, str> {
    let renamed = renamed_modules(text);
    let owned = match merge_lines(&renamed) {
        std::borrow::Cow::Owned(out) => Some(out),
        std::borrow::Cow::Borrowed(_) => None,
    };
    super::sunset_lag::migrated(listed_extras(owned.map_or(renamed, std::borrow::Cow::Owned)))
}

// Modules with new names (0.9): Auto Steal is Chest Stealer, No Mining Trace is Mine Through Mobs; Inventory Cleaner is
// Inventory Manager, Mob Gear ESP is Gear ESP (1.0).
pub(super) const RENAMED: [(&str, &str); 6] = [("autosteal", "cheststealer"), ("nominingtrace", "minethroughmobs"), ("swordpvpbot", "pvpbot"),
    ("extramodules", "modules"), ("inventorycleaner", "inventorymanager"), ("mobgearesp", "gearesp")];

// Auto Armor joined Inventory Manager (1.0): its on/off is the Auto Armor setting, its key Auto Armor key, its Delay
// and Mode Armor delay and Armor mode; the rest keep their names.
fn auto_armor_line(l: &str) -> Option<String> {
    let (field, value) = l.strip_prefix("autoarmor.")?.split_once('=')?;
    let field = match field {
        "on" => "autoarmor",
        "key" => "autoarmorkey",
        "delayticks" => "armordelayticks",
        "mode" => "armormode",
        other => other,
    };
    let value = if field == "autoarmorkey" && value == "none" { "None" } else { value };
    Some(format!("inventorymanager.{field}={value}"))
}

// The Modules list's line for a module that was renamed (`modules.inventorycleaner=` is now
// `modules.inventorymanager=`), or None for one that is gone (Auto Armor: it is Inventory Manager's now, and that has
// its own line). Other lines: Some(unchanged).
fn modules_list_line(l: &str) -> Option<String> {
    let Some((field, value)) = l.strip_prefix("modules.").and_then(|r| r.split_once('=')) else {
        return Some(l.to_owned());
    };
    if field == "autoarmor" {
        return None;
    }
    match RENAMED.iter().find(|(from, _)| *from == field) {
        Some((_, to)) => Some(format!("modules.{to}={value}")),
        None => Some(l.to_owned()),
    }
}

fn renamed_modules(text: &str) -> std::borrow::Cow<'_, str> {
    let old = |l: &str| RENAMED.iter().find(|(from, _)| l.split_once('.').is_some_and(|(id, _)| id == *from));
    let listed_old = |l: &str| modules_list_line(l).as_deref() != Some(l);
    if !text.lines().any(|l| old(l).is_some() || l.starts_with("autoarmor.") || listed_old(l)) {
        return std::borrow::Cow::Borrowed(text);
    }
    let lines: Vec<String> = text
        .lines()
        .filter(|l| l.trim() != "extramodules.pearlcatch=false")
        .filter_map(modules_list_line)
        .map(|l| match old(&l) {
            Some((from, to)) => format!("{to}{}", &l[from.len()..]),
            None => auto_armor_line(&l).unwrap_or_else(|| l.clone()),
        })
        .collect();
    std::borrow::Cow::Owned(lines.join("\n"))
}

// A config or profile with no Modules lines (from before Extra Modules) has the hidden modules it turns on or binds
// listed.
fn listed_extras(text: std::borrow::Cow<'_, str>) -> std::borrow::Cow<'_, str> {
    if text.lines().any(|l| l.starts_with("modules.")) {
        return text;
    }
    let used: Vec<String> = super::sunset_extra_modules::HIDDEN
        .iter()
        .map(|name| norm(name))
        .filter(|extra| {
            let last = |field: &str| {
                text.lines().rev().find_map(|l| l.strip_prefix(&format!("{extra}.{field}=")).map(str::trim))
            };
            last("on") == Some("true") || last("key").is_some_and(|k| k != "none")
        })
        .collect();
    if used.is_empty() {
        return text;
    }
    let mut out = text.into_owned();
    for extra in used {
        out.push_str(&format!("\nmodules.{extra}=true"));
    }
    std::borrow::Cow::Owned(out)
}

fn merge_lines(text: &str) -> std::borrow::Cow<'_, str> {
    let lines: Vec<(&str, &str, &str)> = text
        .lines()
        .filter_map(|l| {
            let (k, v) = l.split_once('=')?;
            let (id, field) = k.split_once('.')?;
            Some((id, field, v.trim()))
        })
        .collect();
    let get = |id: &str, field: &str| lines.iter().rev().find(|l| l.0 == id && l.1 == field).map(|l| l.2);
    let had = |id: &str| lines.iter().any(|l| l.0 == id);
    let on = |id: &str| get(id, "on") == Some("true");
    // The old Offhand had Min health where the new one has Health.
    let old_offhand = get("offhand", "minhealth").is_some();
    let gone = [
        "autototem", "autoinventorytotem", "hovertotem", "fastxp", "knockbackdelay", "autoshield", "shieldbreaker", "mace",
        "spearswap", "crystalmacro", "anchormacro", "antianvil", "selfanvil", "autoanvil", "anchor", "reversestep",
        // Potion Saver (gone in 0.9) only held the timer you see; the server's ran down all the same.
        "potionsaver",
        // Bow Spam and Anti Bed are gone; Rotation and No Rotate are Rotations' Lock and No rotate.
        "bowspam", "antibed", "rotation", "norotate",
        // Removed after 1.1.0.
        "burrow", "holefiller", "autocity", "keythrow", "arrowdodge", "holdtoeat", "targetesp",
    ];
    // A gone module's entry in the Modules list goes with it.
    let dropped = lines.iter().any(|&(id, field, _)| DROPPED.contains(&(id, field)) || (id == "modules" && gone.contains(&field)));
    // A config from before Auto Spear: Auto Weapon's spear lines go to it.
    let spear_moved = !had("autospear") && (get("autoweapon", "spear").is_some() || get("autoweapon", "mode") == Some("Spear"));
    if !old_offhand && !dropped && !spear_moved && !gone.iter().any(|id| had(id)) {
        return std::borrow::Cow::Borrowed(text);
    }
    let mut out: Vec<String> = text
        .lines()
        .filter(|l| {
            let key = l.split_once('=').map_or("", |(k, _)| k);
            let (id, field) = key.split_once('.').unwrap_or((key, ""));
            !gone.contains(&id)
                && !(old_offhand && id == "offhand")
                && !DROPPED.contains(&(id, field))
                && !(id == "modules" && gone.contains(&field))
        })
        .map(str::to_owned)
        .collect();
    // Knockback Delay is Velocity's Knockback delay: on alone, Velocity comes on with its own pushes left alone.
    if had("knockbackdelay") && get("velocity", "knockbackdelay").is_none() {
        let delay = on("knockbackdelay");
        out.push(format!("velocity.knockbackdelay={delay}"));
        if delay && !on("velocity") {
            out.push("velocity.on=true".into());
            for field in ["knockback", "explosions", "liquids", "entitypush", "sinking"] {
                out.push(format!("velocity.{field}=false"));
            }
        }
        if get("velocity", "key").is_none_or(|k| k == "none")
            && let Some(key) = get("knockbackdelay", "key")
        {
            out.push(format!("velocity.key={key}"));
        }
        for (old, new) in [
            ("chance", "delaychance"), ("airdelayminms", "airdelayminms"), ("airdelaymaxms", "airdelaymaxms"),
            ("grounddelayminms", "grounddelayminms"), ("grounddelaymaxms", "grounddelaymaxms"),
            ("notinwater", "delaynotinwater"), ("onlynearenemies", "delayonlynearenemies"),
        ] {
            if let Some(value) = get("knockbackdelay", old) {
                out.push(format!("velocity.{new}={value}"));
            }
        }
    }
    // Auto Shield is Kill Aura's and Trigger Bot's Shield: on in both if it was on, with its settings.
    if had("autoshield") {
        for id in ["killaura", "triggerbot"].into_iter().filter(|id| get(id, "shield").is_none()) {
            out.push(format!("{id}.shield={}", on("autoshield")));
            for field in ["onlywithaweapon", "onlynearatarget", "range", "reraisedelay"] {
                if let Some(v) = get("autoshield", field) {
                    out.push(format!("{id}.shield{field}={v}"));
                }
            }
        }
    }
    // Shield Breaker is Auto Weapon's Axe on shields (Best weapon the old Auto Weapon): Auto Weapon on if either was,
    // then with only their sections on, and the first key bound; Holding and slot back from Shield Breaker when it was
    // on. The old Mace's lines are dropped: its section left Auto Weapon for Auto Mace. Spear Swap is Auto Spear.
    if had("spearswap") && !had("autospear") {
        out.push(format!("autospear.on={}", on("spearswap")));
        for (old_field, field) in [
            ("key", "key"), ("lungekey", "lungekey"), ("reachpoke", "reachpoke"), ("spearreach", "spearreach"), ("holding", "holding"),
            ("switchback", "swapback"), ("backafter", "backafter"), ("shortestdelay", "shortestdelay"), ("longestdelay", "longestdelay"),
        ] {
            if let Some(v) = get("spearswap", old_field) {
                out.push(format!("autospear.{field}={v}"));
            }
        }
    }
    // Auto Weapon's Spear section (or Mode Spear) is Auto Spear: on with Auto Weapon if it ran, with its settings and
    // Auto Weapon's Holding and slot back.
    if spear_moved {
        let spear = on("autoweapon") && (get("autoweapon", "spear") == Some("true") || get("autoweapon", "mode") == Some("Spear"));
        out.push(format!("autospear.on={spear}"));
        for field in [
            "lungekey", "lungeonhit", "reachpoke", "spearreach", "damageindicator", "holding", "swapback", "backafter", "shortestdelay",
            "longestdelay",
        ] {
            if let Some(v) = get("autoweapon", field) {
                out.push(format!("autospear.{field}={v}"));
            }
        }
    }
    if had("shieldbreaker") {
        let old = ["autoweapon", "shieldbreaker"];
        let weapon = get("autoweapon", "bestweapon").is_none() && on("autoweapon");
        out.push(format!("autoweapon.on={}", old.iter().any(|id| on(id))));
        if let Some(key) = old.iter().filter_map(|id| get(id, "key")).find(|k| *k != "none") {
            out.push(format!("autoweapon.key={key}"));
        }
        if old.iter().any(|id| on(id)) {
            for (id, section) in [("autoweapon", "bestweapon"), ("shieldbreaker", "axeonshields")] {
                out.push(format!("autoweapon.{section}={}", if id == "autoweapon" { weapon } else { on(id) }));
            }
        }
        for (id, old_field, field) in [
            ("shieldbreaker", "mode", "shieldmode"), ("shieldbreaker", "shieldheld", "shieldheld"),
        ] {
            if let Some(v) = get(id, old_field) {
                out.push(format!("autoweapon.{field}={v}"));
            }
        }
        if let Some(first) = ["shieldbreaker"].into_iter().find(|id| on(id)) {
            for (old_field, field) in [("holding", "holding"), ("switchback", "swapback"), ("backafter", "backafter"), ("shortestdelay", "shortestdelay"), ("longestdelay", "longestdelay")] {
                if let Some(v) = get(first, old_field) {
                    out.push(format!("autoweapon.{field}={v}"));
                }
            }
        } else if weapon {
            // Auto Weapon alone switched from anything and stayed.
            out.push("autoweapon.holding=sword,axe,spear,mace,trident,empty,other".into());
            out.push("autoweapon.swapback=false".into());
        }
    }
    if had("fastxp") {
        let (fast, xp) = (on("fastuse"), on("fastxp"));
        out.push(format!("fastuse.on={}", fast || xp));
        if let Some(key) = ["fastuse", "fastxp"].iter().filter_map(|id| get(id, "key")).find(|k| *k != "none") {
            out.push(format!("fastuse.key={key}"));
        }
        if xp && !fast {
            out.push("fastuse.mode=Some".into());
            out.push("fastuse.listmode=Whitelist".into());
            out.push("fastuse.items=".into());
            out.push("fastuse.blocks=false".into());
        }
        out.push(format!("fastuse.throwables={xp}"));
        // FastXP's Delay 0 threw every 2 ticks; Throw delay counts the ticks from one throw to the next.
        if let Some(delay) = get("fastxp", "delay").and_then(|d| d.parse::<f64>().ok()) {
            out.push(format!("fastuse.throwdelay={}", delay + 2.0));
        }
        for field in ["experiencebottles", "enderpearls", "windcharges", "snowballsandeggs", "splashpotions", "offhand"] {
            if let Some(v) = get("fastxp", field) {
                out.push(format!("fastuse.{field}={v}"));
            }
        }
    }
    // Crystal Aura and Anchor Aura took in Crystal Macro and Anchor Macro as their Macro sections, Step took in Reverse
    // Step, and Anvil took in Anti Anvil, Self Anvil and Auto Anvil as sections; Anchor (Movement) is gone, its lines
    // with it. `id` took in `parts` (each old module with its section; Crystal Aura is its own Aura): it is on if any
    // was, with only those sections on. With none on, the sections keep their defaults, unless the one key bound was
    // another module's: that module's section alone then. The first key bound goes over; each `shared` setting is the
    // first module's that was on (else the first with one), and `fields` (old module, old setting, new setting) are
    // copied.
    {
        let mut merge = |id: &str, parts: &[(&str, &str)], shared: &[&str], fields: &[(&str, &str, &str)]| {
            if !parts.iter().any(|(old, _)| *old != id && had(old)) {
                return;
            }
            let any_on = parts.iter().any(|(old, _)| on(old));
            out.push(format!("{id}.on={any_on}"));
            let keyed: Vec<&str> =
                parts.iter().map(|(old, _)| *old).filter(|old| get(old, "key").is_some_and(|k| k != "none")).collect();
            if let Some(key) = keyed.first().and_then(|old| get(old, "key")) {
                out.push(format!("{id}.key={key}"));
            }
            let sections: Option<Vec<&str>> = if any_on {
                Some(parts.iter().map(|(old, _)| *old).filter(|old| on(old)).collect())
            } else if let [only] = keyed.as_slice()
                && *only != id
            {
                Some(vec![*only])
            } else {
                None
            };
            if let Some(sections) = sections {
                for (old, section) in parts {
                    out.push(format!("{id}.{section}={}", sections.contains(old)));
                }
            }
            for field in shared {
                let from = parts.iter().map(|(old, _)| *old).find(|old| on(old) && get(old, field).is_some())
                    .or_else(|| parts.iter().map(|(old, _)| *old).find(|old| get(old, field).is_some()));
                if let Some(v) = from.and_then(|old| get(old, field)) {
                    out.push(format!("{id}.{field}={v}"));
                }
            }
            for (old, old_field, field) in fields {
                if let Some(v) = get(old, old_field) {
                    out.push(format!("{id}.{field}={v}"));
                }
            }
        };
        merge(
            "crystalaura",
            &[("crystalaura", "aura"), ("crystalmacro", "macro")],
            &["placedelay", "breakdelay", "maxselfdamage", "autoobsidian", "switchback", "humanpace", "protectloot"],
            &[("crystalmacro", "obsidiandelay", "obsidiandelay")],
        );
        merge(
            "anchoraura",
            &[("anchoraura", "aura"), ("anchormacro", "macro")],
            &["protectloot"],
            &[
                ("anchormacro", "mode", "mode"), ("anchormacro", "delay", "delay"), ("anchormacro", "safeanchor", "safeanchor"),
                ("anchormacro", "ifunguarded", "ifunguarded"), ("anchormacro", "switchback", "switchback"),
            ],
        );
        merge(
            "rotations",
            &[("rotation", "lock"), ("norotate", "norotate")],
            &[],
            &[
                ("rotation", "yawlock", "yawlock"), ("rotation", "yawangle", "yawangle"),
                ("rotation", "pitchlock", "pitchlock"), ("rotation", "pitchangle", "pitchangle"),
            ],
        );
        // Step took in Reverse Step as its Reverse step section (0.9).
        merge("step", &[("step", "stepup"), ("reversestep", "reversestep")], &[], &[("reversestep", "speed", "fallspeed")]);
        merge(
            "anvil",
            &[("antianvil", "antianvil"), ("selfanvil", "selfanvil"), ("autoanvil", "autoanvil")],
            &["rotate"],
            &[
                ("autoanvil", "targetrange", "targetrange"), ("autoanvil", "height", "height"), ("autoanvil", "delay", "delay"),
                ("autoanvil", "placeatfeet", "placeatfeet"), ("autoanvil", "multiplace", "multiplace"),
            ],
        );
    }
    if !old_offhand && !gone[..3].iter().any(|id| had(id)) {
        return std::borrow::Cow::Owned(out.join("\n"));
    }
    let mut set = |field: &str, value: Option<&str>| {
        if let Some(v) = value {
            out.push(format!("offhand.{field}={v}"));
        }
    };
    let (offhand, totem, inv, hover) = (on("offhand"), on("autototem"), on("autoinventorytotem"), on("hovertotem"));
    set("on", Some(if offhand || totem || inv || hover { "true" } else { "false" }));
    set("key", ["offhand", "autototem", "autoinventorytotem", "hovertotem"].iter().filter_map(|id| get(id, "key")).find(|k| *k != "none"));
    let item = if offhand {
        get("offhand", "item")
    } else if totem && get("autototem", "mode") == Some("Strict") {
        Some("Totem")
    } else if totem || inv || hover {
        Some("None")
    } else {
        None
    };
    set("item", item);
    let (when, delay) = if offhand || !had("autototem") {
        ("offhand", get("offhand", "itemswitchdelay"))
    } else {
        ("autototem", get("autototem", "delayticks"))
    };
    set("health", get(when, if when == "offhand" { "minhealth" } else { "health" }));
    set("fall", get(when, if when == "offhand" { "falling" } else { "fall" }));
    set("elytra", get(when, "elytra"));
    set("explosion", get(when, "explosion"));
    set("delayticks", delay);
    for field in ["hotbar", "rightgapple", "swordgapple", "alwaysgaponsword", "alwayspotonsword", "swordpot"] {
        set(field, get("offhand", field));
    }
    set("refill", Some(if inv { get("autoinventorytotem", "mode").unwrap_or("Inventory") } else { "Off" }));
    let slots = if hover && !inv { "hovertotem" } else { "autoinventorytotem" };
    set("hotbarrefill", get(slots, "hotbarrefill"));
    set("hotbarslot", get(slots, "hotbarslot"));
    for field in ["reactiondelay", "swapdelay", "closedelay", "switchbackdelay", "doublehand"] {
        set(field, get("autoinventorytotem", field));
    }
    set("hover", Some(if hover { "true" } else { "false" }));
    std::borrow::Cow::Owned(out.join("\n"))
}

// Runtime part (see runtime.rs): the camera, shapes and painting them.

use super::Game;
use horizon_client::hud::HudBatch;
use horizon_client::text::Text;
use std::sync::Mutex;
use std::sync::atomic::Ordering;

// ---------------------------------------------------------------- HUD

pub(super) struct Camera {
    pub(super) pos: [f64; 3],
    fwd: [f64; 3],
    pub(super) up: [f64; 3],
    pub(super) right: [f64; 3],
    focal: f64,
    aspect: f64,
    pub(super) w: f64,
    pub(super) h: f64,
    // The sine and cosine of half the view's width and of half its height: the sides of what it sees.
    cone: [f64; 4],
}

impl Camera {
    // Where the view is from.
    pub(super) fn pos(&self) -> [f64; 3] {
        self.pos
    }

    pub(super) fn of(game: &Game<'_>, w: f32, h: f32) -> Option<Self> {
        let (last_pos, last_yaw, last_pitch, fov) = game.locator_camera?;
        let p = game.player.as_ref()?;
        let alpha = game.clock.camera_fraction();
        let (pos, yaw, pitch) = if game.camera_type.first_person() {
            let lerp = |a: f64, b: f64| a + alpha * (b - a);
            let eye = f64::from(game.previous_eye) + alpha * f64::from(game.eye - game.previous_eye);
            (
                [
                    lerp(game.previous_position.x, p.position.x),
                    lerp(game.previous_position.y, p.position.y) + eye,
                    lerp(game.previous_position.z, p.position.z),
                ],
                game.yaw,
                game.pitch,
            )
        } else {
            (last_pos, last_yaw, last_pitch)
        };
        let (sy, cy) = f64::from(yaw.to_radians()).sin_cos();
        let (sp, cp) = f64::from(pitch.to_radians()).sin_cos();
        let focal = 1.0 / f64::from((fov / 2.0).to_radians()).tan();
        let aspect = f64::from(w) / f64::from(h);
        let (sh, ch) = (aspect / focal).atan().sin_cos();
        let (sv, cv) = (1.0 / focal).atan().sin_cos();
        Some(Self {
            pos,
            fwd: [-sy * cp, -sp, cy * cp],
            up: [-sy * sp, cp, cy * sp],
            right: [-cy, 0.0, -sy],
            focal,
            aspect,
            w: f64::from(w),
            h: f64::from(h),
            cone: [sh, ch, sv, cv],
        })
    }
    // Whether anything of a ball round `at` can be on screen: the test before any other work on a thing.
    pub(super) fn sees(&self, at: [f64; 3], radius: f64) -> bool {
        let o = [at[0] - self.pos[0], at[1] - self.pos[1], at[2] - self.pos[2]];
        let dot = |a: [f64; 3]| a[0] * o[0] + a[1] * o[1] + a[2] * o[2];
        let depth = dot(self.fwd);
        let [sh, ch, sv, cv] = self.cone;
        depth > -radius && depth * sh - dot(self.right).abs() * ch > -radius && depth * sv - dot(self.up).abs() * cv > -radius
    }
    // Whether a point on screen is within `margin` of it.
    pub(super) fn on_screen(&self, p: [f32; 2], margin: f32) -> bool {
        p[0] > -margin && p[1] > -margin && p[0] < self.w as f32 + margin && p[1] < self.h as f32 + margin
    }
    pub(super) fn project(&self, at: [f64; 3]) -> Option<[f32; 2]> {
        let o = [at[0] - self.pos[0], at[1] - self.pos[1], at[2] - self.pos[2]];
        let dot = |a: [f64; 3]| a[0] * o[0] + a[1] * o[1] + a[2] * o[2];
        let depth = dot(self.fwd);
        if depth < 0.05 {
            return None;
        }
        let x = dot(self.right) * self.focal / (depth * self.aspect);
        let y = dot(self.up) * self.focal / depth;
        Some([((1.0 + x) / 2.0 * self.w) as f32, ((1.0 - y) / 2.0 * self.h) as f32])
    }
    // Screen pixels a block across makes at `at` (None behind the camera): how big to draw a thing of a set size.
    pub(super) fn pixels_per_block(&self, at: [f64; 3]) -> Option<f32> {
        let o = [at[0] - self.pos[0], at[1] - self.pos[1], at[2] - self.pos[2]];
        let depth = o[0] * self.fwd[0] + o[1] * self.fwd[1] + o[2] * self.fwd[2];
        (depth >= 0.05).then(|| (self.focal / depth * self.h / 2.0) as f32)
    }
    // Where the view is from.
    pub(super) fn eye(&self) -> [f64; 3] {
        self.pos
    }
    // A box's eight corners on screen (None behind the camera): corner i is at hi on x, y and z where bits 1, 2 and
    // 4 of i are set.
    pub(super) fn points(&self, lo: [f64; 3], hi: [f64; 3]) -> [Option<[f32; 2]>; 8] {
        std::array::from_fn(|i| {
            self.project([
                if i & 1 == 0 { lo[0] } else { hi[0] },
                if i & 2 == 0 { lo[1] } else { hi[1] },
                if i & 4 == 0 { lo[2] } else { hi[2] },
            ])
        })
    }
    // The eight, when all of the box is in front.
    pub(super) fn corners(&self, lo: [f64; 3], hi: [f64; 3]) -> Option<[[f32; 2]; 8]> {
        let pts = self.points(lo, hi);
        pts.iter().all(Option::is_some).then(|| pts.map(Option::unwrap_or_default))
    }
    // The screen rectangle round those corners, unless it is far off screen.
    pub(super) fn bounds(&self, pts: &[[f32; 2]; 8]) -> Option<[f32; 4]> {
        let r = pts.iter().fold([f32::MAX, f32::MAX, f32::MIN, f32::MIN], |r, &[x, y]| [r[0].min(x), r[1].min(y), r[2].max(x), r[3].max(y)]);
        let margin = 4.0 * self.w as f32;
        (r[2] > -margin && r[0] < margin && r[3] > -margin && r[1] < margin).then_some(r)
    }
}

pub(super) enum Shape {
    Fill([f32; 4], u32),
    // A rectangle with rounded corners, and their radius.
    Round([f32; 4], f32, u32),
    // A rectangle with only some corners rounded: top left, top right, bottom right, bottom left.
    Corners([f32; 4], f32, [bool; 4], u32),
    // A slanted shape (a line): its four corners in order round it.
    Quad([[f32; 2]; 4], u32),
    Text(String, [f32; 2], u32),
    // A line of text in the font's bolder weight: a panel's header.
    Head(String, [f32; 2], u32),
    // An item's icon as the game draws it in its own menus (by id), and its size.
    Item(std::sync::Arc<str>, [f32; 2], f32),
    // A GUI sprite (by its atlas name) stretched over a rectangle, from the part of it given as fractions u0, v0, u1, v1.
    Sprite(&'static str, [f32; 4], [f32; 4]),
    // A line of text at a size (1: the usual).
    Scaled(String, [f32; 2], u32, f32),
    // A player's face from a skin texture (and its hat layer), and its size.
    Face(String, [f32; 2], f32),
    // A panel with squircle corners, and their radius.
    Squircle([f32; 4], f32, u32),
    // What is drawn from ClipStart on is cut to the rectangle ClipEnd gives: x0, y0, x1, y1.
    ClipStart,
    ClipEnd([f32; 4]),
}

// Where shapes go: a list drawn after the frame's other work (the menu, plugins), or straight into the frame's
// batch (what the world overlays draw, so a frame of them makes no list and no copies of their text).
pub(super) trait Canvas {
    fn fill(&mut self, r: [f32; 4], argb: u32);
    fn quad(&mut self, corners: [[f32; 2]; 4], argb: u32);
    fn text(&mut self, text: &str, at: [f32; 2], rgb: u32);
    // An item's icon as the game's menus draw it (enchantment glint included), `size` pixels square.
    fn item(&mut self, _stack: &horizon_client::items::ItemStack, _at: [f32; 2], _size: f32) {}
    // A line of text at a size (1: the usual).
    fn scaled(&mut self, text: &str, at: [f32; 2], rgb: u32, _size: f32) {
        self.text(text, at, rgb);
    }
}

impl Canvas for Vec<Shape> {
    fn fill(&mut self, r: [f32; 4], argb: u32) {
        self.push(Shape::Fill(r, argb));
    }
    fn quad(&mut self, corners: [[f32; 2]; 4], argb: u32) {
        self.push(Shape::Quad(corners, argb));
    }
    fn text(&mut self, text: &str, at: [f32; 2], rgb: u32) {
        self.push(Shape::Text(text.to_owned(), at, rgb));
    }
    fn item(&mut self, stack: &horizon_client::items::ItemStack, at: [f32; 2], size: f32) {
        self.push(Shape::Item(stack.item.clone(), at, size));
    }
    fn scaled(&mut self, text: &str, at: [f32; 2], rgb: u32, size: f32) {
        self.push(Shape::Scaled(text.to_owned(), at, rgb, size));
    }
}

pub(super) struct Painter<'a, 'g> {
    pub(super) game: &'a Game<'g>,
    pub(super) batch: &'a mut HudBatch,
}

impl Canvas for Painter<'_, '_> {
    fn fill(&mut self, r: [f32; 4], argb: u32) {
        self.game.native_fill(self.batch, r, argb);
    }
    fn quad(&mut self, corners: [[f32; 2]; 4], argb: u32) {
        let [a, r, g, b] = argb.to_be_bytes();
        self.batch.fill_quad(&self.game.gui.atlas, corners, horizon_client::hud::rgba(r, g, b, a));
    }
    fn text(&mut self, text: &str, at: [f32; 2], rgb: u32) {
        self.game.native_text(self.batch, text, at, rgb, true);
    }
    fn item(&mut self, stack: &horizon_client::items::ItemStack, [x, y]: [f32; 2], size: f32) {
        let start = self.batch.vertices.len();
        super::sunset_hud_bars::plain(|| self.game.draw_item_model(self.batch, stack, x, y));
        self.batch.scale_since(start, x, y, size / 16.0, size / 16.0);
    }
    fn scaled(&mut self, text: &str, [x, y]: [f32; 2], rgb: u32, size: f32) {
        let start = self.batch.vertices.len();
        self.game.native_text(self.batch, text, [x, y], rgb, true);
        self.batch.scale_since(start, x, y, size, size);
    }
}

pub(super) fn outline(out: &mut impl Canvas, r: [f32; 4], argb: u32, lw: f32, fill: bool) {
    let [x0, y0, x1, y1] = r;
    if fill {
        out.fill([x0, y0, x1 - x0, y1 - y0], (argb & 0x00FF_FFFF) | 0x2800_0000);
    }
    out.fill([x0, y0, x1 - x0, lw], argb);
    out.fill([x0, y1 - lw, x1 - x0, lw], argb);
    out.fill([x0, y0, lw, y1 - y0], argb);
    out.fill([x1 - lw, y0, lw, y1 - y0], argb);
}

pub(super) fn health_colour(fraction: f32) -> u32 {
    if fraction > 0.66 {
        0x55FF55
    } else if fraction > 0.33 {
        0xFFFF55
    } else {
        0xFF5555
    }
}

// The frame's list of shapes, kept from frame to frame so it is not grown again each time.
pub(super) static SHAPES: Mutex<Vec<Shape>> = Mutex::new(Vec::new());

// A rounded rectangle: straight sides as plain fills, each corner a fan with one physical pixel of edge fade (`px`).
fn round_fill(game: &Game<'_>, batch: &mut HudBatch, [x, y, w, h]: [f32; 4], radius: f32, which: [bool; 4], argb: u32, px: f32) {
    let r = radius.min(w / 2.0).min(h / 2.0);
    if r < px {
        game.native_fill(batch, [x, y, w, h], argb);
        return;
    }
    game.native_fill(batch, [x + r, y, w - 2.0 * r, h], argb);
    if h > 2.0 * r {
        game.native_fill(batch, [x, y + r, r, h - 2.0 * r], argb);
        game.native_fill(batch, [x + w - r, y + r, r, h - 2.0 * r], argb);
    }
    let [a, red, g, b] = argb.to_be_bytes();
    let colour = horizon_client::hud::rgba(red, g, b, a);
    let (inner, outer) = ((r - px * 0.5).max(0.0), r + px * 0.5);
    let segments = (((r / px).sqrt() * 2.0).ceil() as usize).clamp(3, 16);
    let at = |c: [f32; 2], radius: f32, angle: f32| [c[0] + radius * angle.cos(), c[1] + radius * angle.sin()];
    let quarter = std::f32::consts::FRAC_PI_2;
    let corners = [([x + r, y + r], 2.0), ([x + w - r, y + r], 3.0), ([x + w - r, y + h - r], 0.0), ([x + r, y + h - r], 1.0)];
    for ((c, turn), round) in corners.into_iter().zip(which) {
        if !round {
            // A square corner: the square the arc would have cut.
            game.native_fill(batch, [c[0] - r * f32::from(u8::from(c[0] < x + w / 2.0)), c[1] - r * f32::from(u8::from(c[1] < y + h / 2.0)), r, r], argb);
            continue;
        }
        for i in 0..segments {
            let a0 = (turn + i as f32 / segments as f32) * quarter;
            let a1 = (turn + (i + 1) as f32 / segments as f32) * quarter;
            let (p0, p1) = (at(c, inner, a0), at(c, inner, a1));
            batch.fill_quad(&game.gui.atlas, [c, p0, p1, p1], colour);
            let start = batch.vertices.len();
            batch.fill_quad(&game.gui.atlas, [p0, at(c, outer, a0), at(c, outer, a1), p1], colour);
            // fill_quad's two triangles use corners 0,1,2,0,2,3.
            for (vertex, corner) in batch.vertices[start..].iter_mut().zip([0, 1, 2, 0, 2, 3]) {
                if corner == 1 || corner == 2 {
                    vertex.color &= 0x00FF_FFFF;
                }
            }
        }
    }
}

// Draws a list of shapes (and empties it, keeping its room).
// Text whose colour has an alpha byte (other than 0 and FF: opaque) is drawn that see-through: the module list's
// rows fading in and out. `shadow`: text with its drop shadow (the HUD's Text shadow; the menu always has it).
pub(super) fn paint(game: &Game<'_>, batch: &mut HudBatch, shapes: &mut Vec<Shape>, px: f32, shadow: bool) {
    let mut clip = 0;
    for s in shapes.drain(..) {
        match s {
            Shape::Squircle(r, radius, argb) => super::sunset_dashboard::squircle(game, batch, r, radius, argb, px),
            Shape::ClipStart => clip = batch.vertices.len(),
            Shape::ClipEnd([x0, y0, x1, y1]) => batch.clip_since(clip, x0, y0, x1, y1),
            Shape::Fill(r, argb) => game.native_fill(batch, r, argb),
            Shape::Round(r, radius, argb) => round_fill(game, batch, r, radius, [true; 4], argb, px),
            Shape::Corners(r, radius, which, argb) => round_fill(game, batch, r, radius, which, argb, px),
            Shape::Quad(corners, argb) => {
                let [a, r, g, b] = argb.to_be_bytes();
                batch.fill_quad(&game.gui.atlas, corners, horizon_client::hud::rgba(r, g, b, a));
            }
            Shape::Text(t, at, argb) => match argb >> 24 {
                0 | 0xFF => game.native_text(batch, &t, at, argb & 0x00FF_FFFF, shadow),
                a => {
                    let [_, r, g, b] = argb.to_be_bytes();
                    let colour = horizon_client::hud::rgba(r, g, b, a as u8);
                    batch.text_styled(&game.gui.atlas, &Text::literal(&*t), at[0], at[1], colour, shadow);
                }
            },
            Shape::Head(t, at, rgb) => {
                horizon_client::font::sunset_font::BOLD.store(true, Ordering::Relaxed);
                game.native_text(batch, &t, at, rgb, shadow);
                horizon_client::font::sunset_font::BOLD.store(false, Ordering::Relaxed);
            }
            Shape::Item(item, [x, y], size) => {
                let start = batch.vertices.len();
                let stack = horizon_client::items::ItemStack { item, count: 1, damage: 0, extra: None };
                super::sunset_hud_bars::plain(|| game.draw_item_model(batch, &stack, x, y));
                batch.scale_since(start, x, y, size / 16.0, size / 16.0);
            }
            Shape::Sprite(name, [x, y, w, h], [a, b, c, d]) => {
                if let Some(r) = game.gui.atlas.sprites.get(name).copied() {
                    let (du, dv) = (r.u1 - r.u0, r.v1 - r.v0);
                    let part = horizon_client::hud::Rect { u0: r.u0 + du * a, v0: r.v0 + dv * b, u1: r.u0 + du * c, v1: r.v0 + dv * d, ..r };
                    batch.rect_uv(x, y, w, h, part, u32::MAX);
                }
            }
            Shape::Scaled(t, [x, y], rgb, size) => {
                let start = batch.vertices.len();
                game.native_text(batch, &t, [x, y], rgb, shadow);
                batch.scale_since(start, x, y, size, size);
            }
            Shape::Face(skin, [x, y], size) => {
                // The face is 8 by 8 at (8, 8) of the 64 by 64 skin, its hat beside it at (40, 8).
                let Some(r) = game.gui.atlas.sprites.get(skin.as_str()).copied() else {
                    continue;
                };
                let (du, dv) = (r.u1 - r.u0, r.v1 - r.v0);
                for u in [8.0, 40.0] {
                    let part = horizon_client::hud::Rect {
                        u0: r.u0 + du * u / 64.0,
                        v0: r.v0 + dv * 8.0 / 64.0,
                        u1: r.u0 + du * (u + 8.0) / 64.0,
                        v1: r.v0 + dv * 16.0 / 64.0,
                        ..r
                    };
                    batch.rect_uv(x, y, size, size, part, horizon_client::hud::rgba(255, 255, 255, 255));
                }
            }
        }
    }
}

// Runtime part (see runtime.rs): the click GUI: its state, layout and hit testing.

use super::{Game, Screen};
use super::sunset_text_edit::{Draft, EditKey};
use std::sync::atomic::Ordering;
use super::sunset::*;

// ---------------------------------------------------------------- click GUI
//
// Sunset's style: every category as a panel at once, over the world. Left
// click turns a module on or off, right click opens its settings under it;
// headers drag the panels (right click folds one). Numbers are sliders. The
// game keeps running (single player does not pause), the pointer is free and
// the window's keys and clicks come here while it is open.

#[derive(Clone, Copy, Debug, PartialEq)]
pub(super) struct Panel {
    // Negative until the first frame places it.
    pub(super) x: f32,
    pub(super) y: f32,
    pub(super) collapsed: bool,
    pub(super) scroll: f32,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub(super) enum Drag {
    Panel(usize, f32, f32),
    // The row and scale at the press: a setting that resizes the GUI must not move the slider under the pointer.
    Slider(usize, usize, [f32; 4], f32),
    // The settings window by its title, where in it the pointer took it.
    Window(f32, f32),
    // A HUD element (Coordinates, Compass, Armor HUD), where in it the pointer took it (in the HUD's own units).
    Hud(&'static str, f32, f32),
}

#[derive(Clone, Debug)]
pub(super) struct Gui {
    pub(super) profile_menu: Option<super::sunset_profile_menu::Menu>,
    pub(super) open: bool,
    // Esc or the menu key closes it at the next frame, so the same key
    // press can't also reach the game (Esc would open the pause menu).
    pub(super) closing: bool,
    pub(super) panels: Vec<Panel>,
    pub(super) expanded: Vec<usize>,
    pub(super) drag: Option<Drag>,
    // The height of the GUI the panels last drew in.
    pub(super) view_h: f32,
    // Typed letters: only the modules whose names contain them show.
    pub(super) search: String,
    // Ctrl+A: the next letter replaces the whole search, Backspace clears it.
    pub(super) select_all: bool,
    // The text editor over the panels (a left click on a text setting), the GUI's width when it last drew, and
    // whether the key just pressed was the editor's already (from the window's own event, with its text).
    pub(super) editor: Option<Editor>,
    // A module's settings in their own window (ClickGUI Settings: Window).
    pub(super) window: Option<Win>,
    pub(super) view_w: f32,
    pub(super) typed: bool,
    // Ctrl or Cmd held, as the window last said.
    shortcut: bool,
}

// A text setting being edited: the setting changes only when Apply is clicked (or Enter pressed).
#[derive(Clone, Debug)]
pub(super) struct Editor {
    pub(super) module: usize,
    pub(super) setting: usize,
    // A value from .set or the config that the editor can't hold (too long, more than one line) is shown, not cut.
    pub(super) draft: Result<Draft, &'static str>,
    // A number typed in its own slider row, instead of the text editor's box over the panels.
    pub(super) inline: bool,
    // A list of blocks, items or entities: picked from the registries, the draft being the search.
    pub(super) list: Option<super::sunset_picker::Picker>,
}

pub(super) fn editor_rect(w: f32, h: f32) -> [f32; 4] {
    let width = (w - 8.0).clamp(1.0, 320.0);
    [(w - width) / 2.0, ((h - 76.0) / 2.0).max(0.0), width, 76.0]
}

// Apply and Cancel.
pub(super) fn editor_buttons(r: [f32; 4]) -> ([f32; 4], [f32; 4]) {
    let width = ((r[2] - 18.0) / 2.0).clamp(1.0, 56.0);
    ([r[0] + 6.0, r[1] + 54.0, width, 15.0], [r[0] + 12.0 + width, r[1] + 54.0, width, 15.0])
}

// The editor's draft into its setting, and the editor closed.
// A number goes in rounded to its step and kept in its range; what is not a number keeps the field open, in red.
pub(super) fn apply_editor(s: &mut State) {
    let Some(mut edit) = s.gui.editor.take() else {
        return;
    };
    // A picker changed its list as it was clicked: Enter only closes it.
    let (Ok(draft), None) = (&mut edit.draft, &edit.list) else {
        return;
    };
    match s.modules.get_mut(edit.module).and_then(|m| m.settings.get_mut(edit.setting)).map(|st| &mut st.value) {
        Some(Value::Text(t)) => *t = draft.text().to_owned(),
        Some(Value::Num { v, min, max, step }) => match draft.text().trim().parse::<f64>() {
            Ok(n) if n.is_finite() => *v = round_to(n, *step).clamp(*min, *max),
            _ => {
                draft.error = Some("not a number");
                s.gui.editor = Some(edit);
            }
        },
        _ => {}
    }
}

pub(super) fn edit_key(name: &str) -> Option<EditKey> {
    Some(match name {
        "key.keyboard.left" => EditKey::Left,
        "key.keyboard.right" => EditKey::Right,
        "key.keyboard.home" => EditKey::Home,
        "key.keyboard.end" => EditKey::End,
        "key.keyboard.backspace" => EditKey::Backspace,
        "key.keyboard.delete" => EditKey::Delete,
        _ => return None,
    })
}

// The window's key events while the editor is open: the text the keyboard layout makes goes into the draft (a real
// keyboard's keys come here first, then to gui_key, which leaves them be).
pub(super) fn text_event(event: &winit::event::WindowEvent) {
    use winit::event::{ElementState, WindowEvent};
    use winit::keyboard::{Key, NamedKey};
    with(|s| {
        if let WindowEvent::ModifiersChanged(m) = event {
            s.gui.shortcut = m.state().control_key() && !m.state().alt_key() || m.state().super_key();
        }
        let WindowEvent::KeyboardInput { event, is_synthetic: false, .. } = event else {
            return;
        };
        if event.state != ElementState::Pressed || !s.gui.open || s.gui.editor.is_none() {
            return;
        }
        s.gui.typed = true;
        let key = match &event.logical_key {
            Key::Named(NamedKey::Escape) => {
                s.gui.editor = None;
                return;
            }
            Key::Named(NamedKey::Enter) => {
                apply_editor(s);
                return;
            }
            Key::Named(NamedKey::ArrowLeft) => Some(EditKey::Left),
            Key::Named(NamedKey::ArrowRight) => Some(EditKey::Right),
            Key::Named(NamedKey::Home) => Some(EditKey::Home),
            Key::Named(NamedKey::End) => Some(EditKey::End),
            Key::Named(NamedKey::Backspace) => Some(EditKey::Backspace),
            Key::Named(NamedKey::Delete) => Some(EditKey::Delete),
            Key::Character(c) if s.gui.shortcut && c.eq_ignore_ascii_case("a") => Some(EditKey::SelectAll),
            _ => None,
        };
        let shortcut = s.gui.shortcut;
        let Some(Editor { draft: Ok(draft), list, .. }) = s.gui.editor.as_mut() else {
            return;
        };
        match (key, event.text.as_deref()) {
            (Some(k), _) => draft.key(k),
            (None, Some(text)) if !shortcut && !text.chars().any(char::is_control) => draft.insert(text),
            _ => {}
        }
        // A new search starts at the top of the list.
        if let Some(picker) = list {
            picker.scroll = 0.0;
        }
    });
}

impl Default for Gui {
    fn default() -> Self {
        Self {
            profile_menu: None,
            open: false,
            closing: false,
            select_all: false,
            editor: None,
            window: None,
            view_w: 0.0,
            typed: false,
            shortcut: false,
            panels: (0..CATEGORIES.len())
                .map(|_| Panel { x: -1.0, y: 32.0, collapsed: false, scroll: 0.0 })
                .collect(),
            expanded: Vec::new(),
            drag: None,
            view_h: 240.0,
            search: String::new(),
        }
    }
}

// Row heights, Comfortable or Compact (ClickGUI's Spacing): a header, a row, and a slider, whose track is under its text.
fn spaced(comfortable: f32, compact: f32) -> f32 {
    if LOOK[10].load(Ordering::Relaxed) == 0 { comfortable } else { compact }
}
pub(super) fn head_h() -> f32 {
    spaced(16.0, 13.0)
}
pub(super) fn row_hh() -> f32 {
    spaced(14.0, 11.0)
}
fn slider_h() -> f32 {
    spaced(19.0, 15.0)
}
// To the right of what the rows draw (the scroll marker sits there).
pub(super) const RIGHT_PAD: f32 = 7.0;
// The panel's own space under its last row: the last row's text is as far from the bottom as the header's from the top.
pub(super) fn body_pad() -> f32 {
    (head_h() - row_hh()) / 2.0
}
// Text is this far down a row of its height.
pub(super) const fn text_y(h: f32) -> f32 {
    (h - 8.0) / 2.0
}
// A row of panels still narrow enough to read, in GUI pixels at scale 1: GUI scale stops where this fills the window.
pub(super) const MIN_ROW: f32 = 4.0 + 5.0 * 70.0 + 4.0 * 3.0;

#[derive(Clone, Copy, Debug, PartialEq)]
