    Header(usize),
    Module(usize),
    Bind(usize),
    Setting(usize, usize),
    // The settings window: anywhere on it, its title (to drag it) and its close button.
    WinBody,
    WinTitle,
    WinClose,
    // The Dashboard style's own parts.
    Dash(super::sunset_dashboard::Part),
}

