pub(super) fn row_h(s: &State, hit: Hit) -> f32 {
    match hit {
        Hit::Setting(i, j) if matches!(s.modules[i].settings[j].value, Value::Num { .. }) => slider_h(),
        _ => row_hh(),
    }
}

// The rows of one panel before scrolling: their offset from the top of its
// body, what they are, and how tall the whole body is.
pub(super) fn panel_body(s: &State, c: usize) -> (Vec<(f32, Hit)>, f32) {
    let mut rows = Vec::new();
    let mut y = 0.0;
    let listed = s.listed();
    let in_panel = s.modules.iter().enumerate().filter(|(_, m)| m.category == CATEGORIES[c] && listed(m)).map(|(i, _)| i);
    // Searching: what it finds, best first, each with the settings it matched shown under it while it is closed.
    let found = (!s.gui.search.trim().is_empty()).then(|| super::sunset_search::results(&s.modules, &s.gui.search));
    let order: Vec<usize> = match &found {
        Some(found) => super::sunset_search::ranked(found, in_panel),
        None => in_panel.collect(),
    };
    for i in order {
        let m = &s.modules[i];
        rows.push((y, Hit::Module(i)));
        y += row_hh();
        if !s.gui.expanded.contains(&i)
            && let Some(hit) = found.as_ref().and_then(|f| f[i].as_ref())
        {
            for &j in hit.settings.iter().filter(|&&j| m.setting_visible(j)) {
                let hit = Hit::Setting(i, j);
                rows.push((y, hit));
                y += row_h(s, hit);
            }
        }
        if s.gui.expanded.contains(&i) {
            rows.push((y, Hit::Bind(i)));
            y += row_hh();
            for j in 0..m.settings.len() {
                if m.setting_visible(j) {
                    let hit = Hit::Setting(i, j);
                    rows.push((y, hit));
                    y += row_h(s, hit);
                }
            }
        }
    }
    (rows, y)
}

// How much of a panel's body shows: what is left of the screen under it.
pub(super) fn body_room(s: &State, c: usize) -> f32 {
    (s.gui.view_h - s.gui.panels[c].y - head_h() - 14.0).max(row_hh() * 3.0)
}

// Each row of every panel in view, top to bottom: its rectangle and what it is. One part way in view is drawn cut.
pub(super) fn panel_rows(s: &State) -> Vec<([f32; 4], Hit)> {
    if super::sunset_dashboard::on() {
        return super::sunset_dashboard::rows(s);
    }
    let mut out = Vec::new();
    for c in 0..CATEGORIES.len() {
        let p = s.gui.panels[c];
        let (rows, _) = panel_body(s, c);
        // A search leaves out the panels with nothing that matches.
        if rows.is_empty() && !s.gui.search.is_empty() {
            continue;
        }
        out.push(([p.x, p.y, panel_w(), head_h()], Hit::Header(c)));
        if p.collapsed {
            continue;
        }
        let room = body_room(s, c);
        for (off, hit) in rows {
            let top = off - super::sunset_smooth::shown(c, p.scroll);
            let rh = row_h(s, hit);
            if top + rh <= 0.0 || top >= room {
                continue;
            }
            out.push(([p.x, p.y + head_h() + top, panel_w(), rh], hit));
        }
    }
    out
}

// A row of a scrolling list, cut to the part of it in view.
pub(super) fn in_view([x, y, w, h]: [f32; 4], [top, bottom]: [f32; 2]) -> Option<[f32; 4]> {
    let (y0, y1) = (y.max(top), (y + h).min(bottom));
    (y1 > y0).then_some([x, y0, w, y1 - y0])
}

// The rows the pointer can hit: only what shows of each.
fn panel_hits(s: &State) -> Vec<([f32; 4], Hit)> {
    let mut body = super::sunset_dashboard::list_y(s).unwrap_or([f32::MIN, f32::MAX]);
    panel_rows(s)
        .into_iter()
        .filter_map(|(r, hit)| {
            if let Hit::Header(c) = hit {
                body = [r[1] + r[3], r[1] + r[3] + body_room(s, c)];
                return Some((r, hit));
            }
            in_view(r, body).map(|r| (r, hit))
        })
        .collect()
}

// What the pointer can hit: the panels' rows, then the settings window over them.
pub(super) fn gui_rows(s: &State) -> Vec<([f32; 4], Hit)> {
    let mut rows = super::sunset_dashboard::hits(s);
    rows.extend(panel_hits(s));
    rows.extend(window_hits(s));
    rows
}

#[derive(Clone, Copy, Debug)]
pub(super) struct Win {
    pub(super) module: usize,
    pub(super) x: f32,
    pub(super) y: f32,
    pub(super) scroll: f32,
    // As it last drew: its description's height, its rows' height and how much of them shows.
    pub(super) about_h: f32,
    pub(super) content: f32,
    pub(super) room: f32,
}

#[derive(Clone, Copy, Debug)]
pub(super) enum WinRow {
    Group(&'static str),
    Row(Hit),
}

pub(super) fn win_w(s: &State) -> f32 {
    (panel_w() * 1.6).max(150.0).min(s.gui.view_w - 8.0)
}

// The window's rows under its title and description, each group under its name: the settings (in the module's sections,
// or all under General), then the bind.
pub(super) fn win_body(s: &State, i: usize) -> (Vec<(f32, WinRow)>, f32) {
    let m = &s.modules[i];
    let (bind, settings): (Vec<usize>, Vec<usize>) =
        (0..m.settings.len()).filter(|&j| m.setting_visible(j)).partition(|&j| m.settings[j].name == "Bind mode");
    let mut groups: Vec<(&'static str, Vec<Hit>)> = Vec::new();
    for j in settings {
        let title = m.group_of(j).unwrap_or("General");
        match groups.last_mut() {
            Some((last, hits)) if *last == title => hits.push(Hit::Setting(i, j)),
            _ => groups.push((title, vec![Hit::Setting(i, j)])),
        }
    }
    groups.push(("Bind", std::iter::once(Hit::Bind(i)).chain(bind.into_iter().map(|j| Hit::Setting(i, j))).collect()));
    let mut rows = Vec::new();
    let mut y = 0.0;
    for (name, hits) in groups.into_iter().filter(|(_, hits)| !hits.is_empty()) {
        rows.push((y, WinRow::Group(name)));
        y += row_hh();
        for hit in hits {
            rows.push((y, WinRow::Row(hit)));
            y += row_h(s, hit);
        }
    }
    (rows, y)
}

pub(super) fn win_frame(s: &State, w: &Win) -> [f32; 4] {
    [w.x, w.y, win_w(s), head_h() + w.about_h + w.content.min(w.room) + body_pad()]
}

pub(super) fn win_close(frame: [f32; 4]) -> [f32; 4] {
    [frame[0] + frame[2] - head_h(), frame[1], head_h(), head_h()]
}

// The window's rows in view, and where.
pub(super) fn win_rows(s: &State) -> Vec<([f32; 4], WinRow)> {
    let Some(w) = s.gui.window else {
        return Vec::new();
    };
    let [x, y, ww, _] = win_frame(s, &w);
    let top = y + head_h() + w.about_h;
    win_body(s, w.module)
        .0
        .into_iter()
        .filter_map(|(off, row)| {
            let rh = match row {
                WinRow::Row(hit) => row_h(s, hit),
                WinRow::Group(_) => row_hh(),
            };
            let at = off - super::sunset_smooth::shown(super::sunset_smooth::WINDOW, w.scroll);
            (at + rh > 0.0 && at < w.room).then_some(([x, top + at, ww, rh], row))
        })
        .collect()
}

// What a click on the window hits: before anything under it.
fn window_hits(s: &State) -> Vec<([f32; 4], Hit)> {
    let Some(w) = s.gui.window else {
        return Vec::new();
    };
    let frame = win_frame(s, &w);
    let mut out = vec![(frame, Hit::WinBody), ([frame[0], frame[1], frame[2], head_h()], Hit::WinTitle), (win_close(frame), Hit::WinClose)];
    let top = frame[1] + head_h() + w.about_h;
    out.extend(win_rows(s).into_iter().filter_map(|(r, row)| match row {
        WinRow::Row(hit) => in_view(r, [top, top + w.room]).map(|r| (r, hit)),
        WinRow::Group(_) => None,
    }));
    out
}

// A number field's width, for its text.
pub(super) fn field_width(game: &Game<'_>, text: &str) -> f32 {
    (game.native_text_width(text) + 6.0).max(24.0)
}

// A description in lines that fit `width`.
pub(super) fn wrap(game: &Game<'_>, text: &str, width: f32) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    for word in text.split_whitespace() {
        match lines.last_mut() {
            Some(l) if game.native_text_width(&format!("{l} {word}")) <= width => {
                l.push(' ');
                l.push_str(word);
            }
            _ => lines.push(word.to_owned()),
        }
    }
    lines
}

// The pointer in the GUI's own coordinates, which GUI scale divides.
pub(super) fn gui_cursor(game: &Game<'_>) -> (f32, f32) {
    let scale = gui_scale();
    (game.cursor.0 / scale, game.cursor.1 / scale)
}

// A panel's scroll moved by some rows: it always starts on a row, and stops at the first that shows the panel's end.
pub(super) fn snap_scroll(rows: &[(f32, Hit)], content: f32, room: f32, scroll: f32, by: i32) -> f32 {
    let max = (content - room).max(0.0);
    let stops = rows.iter().position(|(off, _)| *off >= max - 0.01).map_or(rows.len(), |i| i + 1);
    let Some(last) = stops.checked_sub(1) else {
        return 0.0;
    };
    let at = rows[..stops].iter().position(|(off, _)| *off >= scroll - 0.01).unwrap_or(last);
    rows[(at as i32 + by).clamp(0, last as i32) as usize].0
}

// The wheel over a panel scrolls it: the top one, where panels overlap.
pub(super) fn gui_wheel(game: &Game<'_>, steps: f32) {
    let at = gui_cursor(game);
    with(|s| {
        // An open picker's list scrolls, wherever the pointer is.
        let (view_w, view_h) = (s.gui.view_w, s.gui.view_h);
        if let Some(menu) = &mut s.gui.profile_menu {
            menu.scroll((-steps * 3.0) as i32, view_w, view_h);
            return;
        }
        if let Some(Editor { module, setting, draft: Ok(draft), list: Some(picker), .. }) = &mut s.gui.editor {
            use super::sunset_picker as pick;
            let count = match &s.modules[*module].settings[*setting].value {
                Value::Text(t) => pick::rows(picker, t, draft.text()).len(),
                _ => 0,
            };
            let max = pick::max_scroll(count, pick::rect(view_w, view_h));
            picker.scroll = (picker.scroll - steps * pick::ROW * 3.0).clamp(0.0, max);
            return;
        }
        // Over the settings window: it scrolls.
        if let Some(w) = s.gui.window
            && inside(win_frame(s, &w), at)
        {
            let max = (w.content - w.room).max(0.0);
            s.gui.window = Some(Win { scroll: (w.scroll - steps * row_hh() * 2.0).clamp(0.0, max), ..w });
            return;
        }
        if super::sunset_dashboard::on() {
            super::sunset_dashboard::wheel(s, steps, at);
            return;
        }
        for c in (0..CATEGORIES.len()).rev() {
            let p = s.gui.panels[c];
            let (rows, content) = panel_body(s, c);
            if rows.is_empty() && !s.gui.search.is_empty() {
                continue;
            }
            let room = body_room(s, c);
            let shown = if p.collapsed { 0.0 } else { content.min(room) + body_pad() };
            if inside([p.x, p.y, panel_w(), head_h() + shown], at) {
                let by = -steps * 2.0;
                let by = if by > 0.0 { by.ceil() } else { by.floor() } as i32;
                s.gui.panels[c].scroll = snap_scroll(&rows, content, room, p.scroll, by);
                return;
            }
        }
    });
}

pub(super) fn inside(r: [f32; 4], (x, y): (f32, f32)) -> bool {
    x >= r[0] && x < r[0] + r[2] && y >= r[1] && y < r[1] + r[3]
}

pub(super) fn hit_at(s: &State, at: (f32, f32)) -> Option<([f32; 4], Hit)> {
    // The last drawn is the one on top, where panels overlap.
    gui_rows(s).into_iter().rfind(|(r, _)| inside(*r, at))
}

pub(super) fn open_gui(game: &mut Game<'_>) {
    if !running() { return; }
    release_binds();
    if !game.native_playing() {
        return;
    }
    ensure_loaded(game);
    // The menu is drawn with the HUD: opened while F1 hides it, the HUD comes back.
    game.ui.hide_gui = false;
    game.keys.clear();
    game.capture(false);
    with(|s| {
        s.gui.open = true;
        s.gui.closing = false;
        s.gui.drag = None;
        s.binding = None;
    });
    super::sunset_dashboard::opened();
}

pub(super) fn close_gui(game: &mut Game<'_>) {
    with(|s| {
        s.gui.profile_menu = None;
        s.gui.open = false;
        s.gui.closing = false;
        s.gui.drag = None;
        s.gui.editor = None;
        s.gui.window = None;
        s.binding = None;
    });
    save(game);
    if game.screen == Screen::Playing {
        game.capture(true);
    }
}

// The number's own line above a slider: clicks lower than this go to the slider, so the end of the track (and its knob,
// which reaches a little above it) slides instead of opening the number for typing.
pub(super) fn number_band(r: [f32; 4]) -> f32 {
    r[1] + row_hh() - 4.0
}

// Where a slider's track starts in its row, and how long it is.
pub(super) fn slider_track(r: [f32; 4]) -> (f32, f32) {
    let x0 = r[0] + indent() + 4.0;
    (x0, (r[0] + r[2] - RIGHT_PAD - x0).max(1.0))
}

// A slider's value from the pointer's place along its row.
pub(super) fn slide(s: &mut State, i: usize, j: usize, r: [f32; 4], x: f32) -> bool {
    let Some(setting) = s.modules[i].settings.get_mut(j) else {
        return false;
    };
    if let Value::Num { v, min, max, step } = &mut setting.value {
        let (x0, track) = slider_track(r);
        let t = ((x - x0) / track).clamp(0.0, 1.0);
        let n = round_to(*min + f64::from(t) * (*max - *min), *step).clamp(*min, *max);
        let changed = (n - *v).abs() > 1e-9;
        *v = n;
        return changed;
    }
    false
}

// Runtime part (see runtime.rs): drawing the click GUI: text measuring, pickers, panels and the profile menu.

use super::Game;
use super::sunset_text_edit::Draft;
use std::sync::Mutex;
use std::sync::atomic::Ordering;
use super::sunset::*;

// What the menu's text measured: its rows measure the same words every frame. Each entry is by the text and, for a cut,
// the room it was cut to. Kept until the font changes, or there are too many (numbers being dragged).
#[derive(Default)]
struct Measured {
    font: f32,
    widths: std::collections::HashMap<u64, f32>,
    cuts: std::collections::HashMap<(u64, u32), String>,
}

static MEASURED: Mutex<Option<Measured>> = Mutex::new(None);

fn measured<R>(f: impl FnOnce(&mut Measured) -> R) -> R {
    f(MEASURED.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Measured::default))
}

// Once a frame, while the menu draws.
fn check_measured(game: &Game<'_>) {
    let font = game.native_text_width("Mm");
    measured(|m| {
        if m.font != font || m.widths.len() + m.cuts.len() > 4096 {
            *m = Measured { font, ..Measured::default() };
        }
    });
}

fn text_key(text: &str) -> u64 {
    use std::hash::{Hash as _, Hasher as _};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    text.hash(&mut hasher);
    hasher.finish()
}

// A menu row's text width.
fn width_of(game: &Game<'_>, text: &str) -> f32 {
    let key = text_key(text);
    if let Some(width) = measured(|m| m.widths.get(&key).copied()) {
        return width;
    }
    let width = game.native_text_width(text);
    measured(|m| m.widths.insert(key, width));
    width
}

// The text, cut to `max` wide with "..." when it is wider.
pub(super) fn fit_to(game: &Game<'_>, text: &str, max: f32) -> String {
    let key = (text_key(text), max.to_bits());
    if let Some(cut) = measured(|m| m.cuts.get(&key).cloned()) {
        return cut;
    }
    let cut = if game.native_text_width(text) <= max {
        text.to_owned()
    } else {
        let mut t = text.to_owned();
        while !t.is_empty() && game.native_text_width(&format!("{t}...")) > max {
            t.pop();
        }
        format!("{t}...")
    };
    measured(|m| m.cuts.insert(key, cut.clone()));
    cut
}

// The list picker over the panels: its title, the search box, the rows (a lit mark on the chosen ones, which come
// first) and Done.
fn draw_picker(game: &Game<'_>, w: f32, h: f32, edit: &Editor, picker: &super::sunset_picker::Picker, modules: &[Module], at: (f32, f32), out: &mut Vec<Shape>) {
    use super::sunset_picker as pick;
    let fit = |text: &str, max: f32| fit_to(game, text, max);
    let solid = |rgb: u32| 0xFF00_0000 | rgb;
    let r = pick::rect(w, h);
    let [x, y, rw, _] = r;
    let room = (rw - 16.0).max(0.0);
    let control = control_radius();
    out.push(Shape::Fill([0.0, 0.0, w, h], 0x9000_0000));
    out.push(Shape::Round(r, panel_radius(), 0xF814_1414));
    let m = &modules[edit.module];
    out.push(Shape::Head(fit(&format!("{} / {}", m.name, m.settings[edit.setting].name), room), [x + 8.0, y + 6.0], accent()));
    let search = edit.draft.as_ref().map_or("", Draft::text);
    out.push(Shape::Round([x + 6.0, y + 22.0, rw - 12.0, 16.0], panel_radius(), 0xFF08_0808));
    let (shown, colour) = if search.is_empty() { ("Type to search", 0x909090) } else { (search, 0xFFFFFF) };
    out.push(Shape::Text(fit(shown, room - 4.0), [x + 10.0, y + 22.0 + text_y(16.0)], colour));
    let text = match &m.settings[edit.setting].value {
        Value::Text(t) => t.as_str(),
        _ => "",
    };
    let rows = pick::rows(picker, text, search);
    let area = pick::list_area(r);
    let mut icons = Vec::new();
    let scroll = super::sunset_smooth::shown(super::sunset_smooth::PICKER, picker.scroll).min(pick::max_scroll(rows.len(), r));
    let first = (scroll / pick::ROW) as usize;
    out.push(Shape::ClipStart);
    for (n, (name, have)) in rows.iter().enumerate().skip(first) {
        let ry = area[1] + n as f32 * pick::ROW - scroll;
        if ry >= area[1] + area[3] {
            break;
        }
        let row = [area[0], ry, area[2], pick::ROW];
        if inside(row, at) {
            out.push(Shape::Round(row, control, 0x40FF_FFFF));
        }
        out.push(Shape::Round([area[0] + 3.0, ry + 3.0, 6.0, 6.0], 3.0, if *have { solid(accent()) } else { 0xFF3A_3A3A }));
        // The block's, item's or mob's icon (only the rows on screen are drawn), then its name.
        let icon = pick::icon(game, picker, name, [area[0] + 13.0, ry + 1.0], pick::ROW - 2.0);
        let left = if icon.is_some() { 26.0 } else { 14.0 };
        // An icon can't be cut, so it waits outside the cut part until its row is all in view.
        icons.extend(icon.filter(|_| ry >= area[1] && ry + pick::ROW <= area[1] + area[3]));
        let label = if picker.kind == pick::ListKind::Players { (*name).to_owned() } else { pick::readable(name) };
        out.push(Shape::Text(fit(&label, area[2] - left - 4.0), [area[0] + left, ry + text_y(pick::ROW)], 0xFFFFFF));
    }
    out.push(Shape::ClipEnd([area[0], area[1], area[0] + area[2], area[1] + area[3]]));
    out.extend(icons);
    let chosen = rows.iter().filter(|(_, have)| *have).count();
    let note = format!("{chosen} chosen, {} more. Click to add or take away; Esc closes.", rows.len() - chosen);
    let done = pick::done_button(r);
    out.push(Shape::Text(fit(&note, done[0] - x - 12.0), [x + 8.0, done[1] + text_y(done[3])], 0x909090));
    out.push(Shape::Round(done, panel_radius(), solid(accent())));
    let tw = game.native_text_width("Done");
    out.push(Shape::Text("Done".to_owned(), [done[0] + (done[2] - tw) / 2.0, done[1] + text_y(done[3])], 0xFFFFFF));
}

pub(super) fn draw_gui(game: &Game<'_>, modules: &[Module], w: f32, h: f32, px: f32, out: &mut Vec<Shape>) {
    check_measured(game);
    follow_drag(game, w, h);
    with(|s| {
        use super::sunset_smooth as smooth;
        super::sunset_dashboard::prepare(s);
        let mut targets = [None; smooth::SLOTS];
        for (target, p) in targets.iter_mut().zip(&s.gui.panels) {
            *target = Some(p.scroll);
        }
        targets[smooth::WINDOW] = s.gui.window.map(|w| w.scroll);
        targets[smooth::DASHBOARD] = Some(super::sunset_dashboard::list_scroll());
        targets[smooth::PANE] = Some(super::sunset_dashboard::pane_scroll());
        targets[smooth::PICKER] = s.gui.editor.as_ref().and_then(|e| e.list.as_ref()).map(|p| p.scroll);
        smooth::frame(targets);
    });
    // The panels are as wide as asked, or as wide as lets all of them sit in a row.
    let fits = ((w - 4.0 - 3.0 * (CATEGORIES.len() as f32 - 1.0)) / CATEGORIES.len() as f32).floor();
    let width = f32::from_bits(LOOK[1].load(Ordering::Relaxed)).min(fits).max(50.0);
    let before = LOOK[4].swap(width.to_bits(), Ordering::Relaxed);
    let was = f32::from_bits(before);
    with(|s| {
        s.gui.view_h = h;
        s.gui.view_w = w;
        if before != 0 && was != width {
            // Another width: the panels spread or close up and a layout of your own keeps its shape.
            let k = (width + 3.0) / (was + 3.0);
            for p in s.gui.panels.iter_mut().filter(|p| p.x >= 0.0) {
                p.x = (2.0 + (p.x - 2.0) * k).max(0.0);
            }
        }
        // Panels with no place yet go left to right, in a second row when the
        // window is narrow.
        let mut x = 2.0;
        let mut y = 32.0;
        for p in s.gui.panels.iter_mut().filter(|p| p.x < 0.0) {
            if x + panel_w() > w {
                x = 2.0;
                y += head_h() + 3.0;
            }
            (p.x, p.y) = (x, y);
            x += panel_w() + 3.0;
        }
        for p in &mut s.gui.panels {
            p.x = p.x.clamp(0.0, (w - panel_w()).max(0.0));
            p.y = p.y.clamp(0.0, (h - head_h()).max(0.0));
        }
        // The Dashboard has no panels to keep in order.
        if super::sunset_dashboard::on() {
            return;
        }
        // A scroll past the end (a shorter body, a taller window) comes back.
        for c in 0..CATEGORIES.len() {
            let (rows, content) = panel_body(s, c);
            let room = body_room(s, c);
            s.gui.panels[c].scroll = snap_scroll(&rows, content, room, s.gui.panels[c].scroll, 0);
        }
    });
    // The settings window: its description in lines, sized to what it holds and kept on the screen where it is, 4
    // short of the bottom: a taller one scrolls (three rows at least, moved up if need be). The description takes
    // three lines at most, the last cut short (its module's tooltip has it all).
    let about = with(|s| s.gui.window.map(|w| (s.modules[w.module].about, win_w(s)))).map_or_else(Vec::new, |(text, ww)| {
        let mut lines = wrap(game, text, ww - 2.0 * indent());
        if lines.len() > 3 {
            let rest = lines.split_off(2).join(" ");
            lines.push(fit_to(game, &rest, ww - 2.0 * indent()));
        }
        lines
    });
    let window = with(|s| {
        let mut win = s.gui.window?;
        win.about_h = if about.is_empty() { 0.0 } else { about.len() as f32 * 10.0 + 4.0 };
        win.content = win_body(s, win.module).1;
        win.room = (h - 4.0 - win.y.max(0.0) - head_h() - win.about_h - body_pad()).max(row_hh() * 3.0);
        win.scroll = win.scroll.clamp(0.0, (win.content - win.room).max(0.0));
        let [_, _, ww, wh] = win_frame(s, &win);
        win.x = win.x.clamp(0.0, (w - ww).max(0.0));
        win.y = win.y.clamp(0.0, (h - wh).max(0.0));
        s.gui.window = Some(win);
        Some((win, win_frame(s, &win), win_rows(s), about))
    });
    let at = gui_cursor(game);
    let (rows, binding, hover, editing) =
        with(|s| (panel_rows(s), s.binding, hit_at(s, at).map(|(_, h)| h), s.gui.editor.clone()));
    // Modules whose settings are open (inline or in the window): a mark by the name.
    let open: Vec<usize> = with(|s| s.gui.expanded.iter().copied().chain(s.gui.window.map(|w| w.module)).collect());
    // Each panel's height of rows, room, scroll and whether it is folded.
    let bodies: Vec<(f32, f32, f32, bool)> = with(|s| {
        (0..CATEGORIES.len())
            .filter(|_| !super::sunset_dashboard::on())
            .map(|c| (panel_body(s, c).1, body_room(s, c), super::sunset_smooth::shown(c, s.gui.panels[c].scroll), s.gui.panels[c].collapsed))
            .collect()
    });
    let fit = |text: &str, max: f32| fit_to(game, text, max);
    let solid = |rgb: u32| 0xFF00_0000 | rgb;
    let control = control_radius();
    let dash = super::sunset_dashboard::on();
    // The label on the left of a row, cut short of what sits to its right: whether it had to be.
    let label = |out: &mut Vec<Shape>, text: &str, r: [f32; 4], x: f32, right: f32, colour: u32| -> bool {
        let room = r[0] + r[2] - RIGHT_PAD - right - x - 3.0;
        let shown = fit(text, room);
        let cut = shown != text;
        out.push(Shape::Text(shown, [x, r[1] + text_y(row_hh())], colour));
        cut
    };
    // A value in its rounded box at the right of a row; how wide it is.
    let value_box = |out: &mut Vec<Shape>, text: &str, r: [f32; 4], colour: u32| -> f32 {
        let text = fit(text, r[2] * 0.5);
        let tw = width_of(game, &text);
        let bw = tw + 8.0;
        let bx = r[0] + r[2] - RIGHT_PAD - bw;
        out.push(Shape::Round([bx, r[1] + 2.0, bw, row_hh() - 4.0], control, 0xFF1E_1E1E));
        out.push(Shape::Text(text, [bx + 4.0, r[1] + text_y(row_hh())], colour));
        bw
    };
    // A number being typed in its slider row: the field's width (the draft and its caret are drawn in it).
    let typing = |i: usize, j: usize| editing.as_ref().filter(|e| e.inline && e.module == i && e.setting == j).and_then(|e| e.draft.as_ref().ok());
    // One row of a panel or of the settings window: what it shows, and its name when it had to be cut short.
    let draw_row = |out: &mut Vec<Shape>, r: [f32; 4], hit: Hit, hovered: bool| -> Option<&'static str> {
        let [x, y, rw, rh] = r;
        let setting_x = x + indent() + 4.0;
        match hit {
            Hit::Module(i) => {
                let m = &modules[i];
                // A bound key shows at the row's end.
                let tag = m.key.as_deref().map(|k| fit(&key_label(Some(k)), 30.0)).unwrap_or_default();
                let tag_w = if tag.is_empty() { 0.0 } else { width_of(game, &tag) };
                // The name clears the mark of open settings at any Text indent.
                let name_x = x + indent().max(6.0);
                if open.contains(&i) && !dash {
                    out.push(Shape::Round([name_x - 5.0, y + 3.0, 2.0, rh - 6.0], 1.0, 0xFFE4_E4E4));
                }
                if !tag.is_empty() {
                    out.push(Shape::Text(tag, [x + rw - RIGHT_PAD - tag_w, y + text_y(rh)], 0x707070));
                }
                (label(out, m.name, r, name_x, tag_w, if m.on { accent() } else { 0xE4E4E4 }) && hovered).then_some(m.name)
            }
            Hit::Bind(i) => {
                let waiting = binding == Some(i);
                let key = if waiting { "Press a key or button".to_owned() } else { key_label(modules[i].key.as_deref()) };
                let bw = value_box(out, &key, r, if waiting { accent() } else { 0xC8C8C8 });
                label(out, "Bind", r, setting_x, bw, 0xB4B4B4);
                None
            }
            Hit::Setting(i, j) => {
                let st = &modules[i].settings[j];
                let right = match st.value {
                    Value::Bool(b) => {
                        let (tw, th) = (14.0, 8.0);
                        let (tx, ty) = (x + rw - RIGHT_PAD - tw, y + (rh - th) / 2.0);
                        // Off is the same pill in grey; on follows the accent colour.
                        out.push(Shape::Round([tx, ty, tw, th], control, if b { solid(accent()) } else { 0xFF5A_5A5A }));
                        let knob = th - 2.0;
                        let kx = if b { tx + tw - knob - 1.0 } else { tx + 1.0 };
                        out.push(Shape::Round([kx, ty + 1.0, knob, knob], (control - 1.0).max(0.0), 0xFF10_1010));
                        tw
                    }
                    Value::Num { v, min, max, .. } => {
                        let vw = match typing(i, j) {
                            Some(draft) => {
                                let fw = field_width(game, draft.text());
                                let fx = x + rw - RIGHT_PAD - fw + 3.0;
                                let colour = match (draft.error, draft.selected()) {
                                    (Some(_), _) => 0xFF60_2020,
                                    (None, true) => 0xFF30_60B0,
                                    (None, false) => 0xFF08_0808,
                                };
                                out.push(Shape::Round([fx - 3.0, y + 1.0, fw, row_hh() - 2.0], control, colour));
                                out.push(Shape::Text(draft.text().to_owned(), [fx, y + text_y(row_hh())], 0xFFFFFF));
                                let caret = game.native_text_width(&draft.text()[..draft.caret()]);
                                out.push(Shape::Fill([fx + caret, y + 3.0, 1.0, row_hh() - 6.0], solid(accent())));
                                fw
                            }
                            None => {
                                let value = st.value_text();
                                let vw = width_of(game, &value);
                                out.push(Shape::Text(value, [x + rw - RIGHT_PAD - vw, y + text_y(row_hh())], 0xE4E4E4));
                                vw
                            }
                        };
                        let (tx, track) = slider_track(r);
                        let t = if max > min { ((v - min) / (max - min)) as f32 } else { 0.0 };
                        let ty = y + row_hh();
                        out.push(Shape::Round([tx, ty, track, 2.0], 1.0, 0xFF2A_2A2A));
                        out.push(Shape::Round([tx, ty, track * t, 2.0], 1.0, solid(accent())));
                        out.push(Shape::Round([tx + track * t - 2.5, ty - 1.5, 5.0, 5.0], control.min(2.5), 0xFFE4_E4E4));
                        vw
                    }
                    Value::Pick { .. } => value_box(out, &st.value_text(), r, 0xE4E4E4),
                    Value::Text(_) => {
                        // The text itself: the name keeps its width, the text gets what is left (a quarter at least).
                        let room = x + rw - RIGHT_PAD - setting_x - width_of(game, st.name) - 6.0;
                        let value = fit(&st.value_text(), room.max(rw * 0.25));
                        let vw = width_of(game, &value);
                        out.push(Shape::Text(value, [x + rw - RIGHT_PAD - vw, y + text_y(row_hh())], 0xE4E4E4));
                        vw
                    }
                };
                (label(out, st.name, r, setting_x, right, 0xB4B4B4) && hovered).then_some(st.name)
            }
            _ => None,
        }
    };
    // The pointer's row lit edge to edge, between the lines; at the bottom of a panel, down to its rounded corners.
    let lit = |out: &mut Vec<Shape>, [x, y, rw, rh]: [f32; 4], line: bool, last: bool| {
        let top = if line { px } else { 0.0 };
        let r = [x, y + top, rw, rh - top + if last { body_pad() } else { 0.0 }];
        out.push(Shape::Corners(r, panel_radius(), [false, false, last, last], 0x14FF_FFFF));
    };
    if dash {
        with(|s| super::sunset_dashboard::back(s, game, hover, px, out));
    }
    let mut whole: Option<&str> = None;
    let mut first_row = false;
    // The list the rows scroll in, top and bottom: a row part way out of it is cut.
    let mut body = with(|s| super::sunset_dashboard::list_y(s)).unwrap_or([f32::MIN, f32::MAX]);
    for (k, (r, hit)) in rows.iter().enumerate() {
        let [x, y, rw, rh] = *r;
        let hovered = hover == Some(*hit);
        let cut = !matches!(hit, Hit::Header(_)) && (y < body[0] || y + rh > body[1]);
        if cut {
            out.push(Shape::ClipStart);
        }
        let line = if let Hit::Header(_) = hit {
            first_row = true;
            false
        } else if std::mem::take(&mut first_row) {
            // The header's line is under it already.
            false
        } else if dash && (y <= body[0] + 0.01 || !super::sunset_dashboard::line_above(*hit)) {
            // The Dashboard draws lines only between the settings of a section.
            false
        } else {
            out.push(Shape::Fill([x, y, rw, px], 0x12FF_FFFF));
            true
        };
        if let Hit::Header(c) = *hit {
            let (content, room, scroll, folded) = bodies[c];
            body = [y + rh, y + rh + room];
            let body = if folded || content <= 0.0 { 0.0 } else { content.min(room) + body_pad() };
            out.push(Shape::Round([x, y, rw, rh + body], panel_radius(), bg(0xC00E_0E0E)));
            if body > 0.0 {
                out.push(Shape::Fill([x, y + rh - px, rw, px], 0x24FF_FFFF));
            }
            let name = CATEGORIES[c].label();
            let on = modules.iter().filter(|m| m.category == CATEGORIES[c] && m.on).count();
            let count = format!("{on}");
            let cw = game.native_text_width(&count);
            out.push(Shape::Head(fit(name, rw - indent() - RIGHT_PAD - cw - 3.0), [x + indent(), y + text_y(rh)], 0xFFFFFF));
            out.push(Shape::Text(count, [x + rw - RIGHT_PAD - cw, y + text_y(rh)], 0x808080));
            // The scroll marker: how much of the panel shows, and where.
            if !folded && content > room {
                let thumb = (room * room / content).max(10.0);
                let t = (scroll / (content - room)).min(1.0);
                out.push(Shape::Round([x + rw - 4.0, y + rh + 1.0 + (room - 2.0 - thumb) * t, 2.0, thumb], 1.0, 0x70FF_FFFF));
            }
            continue;
        }
        if dash {
            // A Dashboard row fades as the pointer comes and goes.
            let glow = super::sunset_dashboard::glow(*hit);
            if glow > 0 {
                out.push(Shape::Fill(*r, glow << 24 | 0x00FF_FFFF));
            }
        } else if hovered {
            let last = rows.get(k + 1).is_none_or(|(_, next)| matches!(next, Hit::Header(_)));
            lit(out, *r, line, last);
        }
        let text = if dash && matches!(hit, Hit::Module(_)) { super::sunset_dashboard::module_text(*r) } else { *r };
        if let Some(name) = draw_row(out, text, *hit, hovered) {
            whole = Some(name);
        }
        if cut {
            out.push(Shape::ClipEnd([x, body[0], x + rw, body[1]]));
        }
    }
    // The settings window, over the panels: its title, close button, description, groups and rows.
    if let Some((win, frame, list, about)) = &window {
        let [x, y, ww, wh] = *frame;
        out.push(Shape::Round(*frame, panel_radius(), 0xF812_1212));
        let hh = head_h();
        out.push(Shape::Head(fit(modules[win.module].name, ww - indent() - hh - 4.0), [x + indent(), y + text_y(hh)], accent()));
        // The close button: a cross, lit under the pointer.
        let close = win_close(*frame);
        if hover == Some(Hit::WinClose) {
            out.push(Shape::Corners(close, panel_radius(), [false, true, false, false], 0x24FF_FFFF));
        }
        let (cx, cy, d) = (close[0] + close[2] / 2.0, close[1] + close[3] / 2.0, 3.0);
        for (a, b) in [([cx - d, cy - d], [cx + d, cy + d]), ([cx - d, cy + d], [cx + d, cy - d])] {
            line(out, a, b, 0xFFE4_E4E4, 1.5);
        }
        out.push(Shape::Fill([x, y + hh - px, ww, px], 0x24FF_FFFF));
        for (n, l) in about.iter().enumerate() {
            out.push(Shape::Text(l.clone(), [x + indent(), y + hh + 3.0 + n as f32 * 10.0], 0xA8A8A8));
        }
        let mut line = false;
        let view = [y + hh + win.about_h, y + hh + win.about_h + win.room];
        for (n, (r, row)) in list.iter().enumerate() {
            let cut = r[1] < view[0] || r[1] + r[3] > view[1];
            if cut {
                out.push(Shape::ClipStart);
            }
            match row {
                WinRow::Group(name) => {
                    out.push(Shape::Text((*name).to_owned(), [r[0] + indent(), r[1] + text_y(r[3])], accent()));
                    line = false;
                }
                WinRow::Row(hit) => {
                    if line {
                        out.push(Shape::Fill([r[0], r[1], r[2], px], 0x12FF_FFFF));
                    }
                    let hovered = hover == Some(*hit);
                    if hovered {
                        lit(out, *r, line, n + 1 == list.len() && r[1] + r[3] + body_pad() >= y + wh - 0.5);
                    }
                    if let Some(name) = draw_row(out, *r, *hit, hovered) {
                        whole = Some(name);
                    }
                    line = true;
                }
            }
            if cut {
                out.push(Shape::ClipEnd([r[0], view[0], r[0] + r[2], view[1]]));
            }
        }
        // Its scroll marker.
        let (content, room) = (win.content, win.room);
        if content > room {
            let thumb = (room * room / content).max(10.0);
            let t = (super::sunset_smooth::shown(super::sunset_smooth::WINDOW, win.scroll) / (content - room)).min(1.0);
            out.push(Shape::Round([x + ww - 4.0, y + hh + win.about_h + 1.0 + (room - 2.0 - thumb) * t, 2.0, thumb], 1.0, 0x70FF_FFFF));
        }
    }
    // The hovered module's description, under the pointer.
    if let Some(Hit::Module(i)) = hover
        && with(|s| s.gui.drag.is_none())
        && super::sunset_dashboard::wants_tip(i)
    {
        let text = modules[i].about;
        let about = match whole {
            Some(name) => format!("{name}: {text}"),
            None => text.to_owned(),
        };
        // Wrapped to half the screen and kept on it.
        let lines = wrap(game, &about, (w * 0.5).max(120.0).min(w - 16.0));
        let tw = lines.iter().map(|l| game.native_text_width(l)).fold(0.0, f32::max);
        let th = lines.len() as f32 * 10.0 + 4.0;
        let bx = (at.0 + 8.0).min(w - tw - 8.0).max(0.0);
        let by = (at.1 + 10.0).min(h - th).max(0.0);
        out.push(Shape::Round([bx, by, tw + 8.0, th], panel_radius(), 0xF80A_0A0A));
        for (n, line) in lines.into_iter().enumerate() {
            out.push(Shape::Text(line, [bx + 4.0, by + 3.0 + n as f32 * 10.0], 0xE4E4E4));
        }
    }
    // A setting's name cut short, whole under the pointer.
    if let (Some(Hit::Setting(..)), Some(name)) = (hover, whole) {
        let tw = game.native_text_width(name);
        let bx = (at.0 + 8.0).min(w - tw - 8.0).max(0.0);
        let by = (at.1 + 10.0).min(h - 14.0);
        out.push(Shape::Round([bx, by, tw + 8.0, 14.0], panel_radius(), 0xF80A_0A0A));
        out.push(Shape::Text(name.to_owned(), [bx + 4.0, by + text_y(14.0)], 0xE4E4E4));
    }
    // The list picker, over everything.
    if let Some((edit, picker)) = editing.as_ref().and_then(|e| e.list.as_ref().map(|p| (e, p))) {
        draw_picker(game, w, h, edit, picker, &modules, at, out);
        return;
    }
    // The text editor, over everything.
    if let Some(edit) = editing.filter(|e| !e.inline) {
        let r = editor_rect(w, h);
        let [x, y, rw, _] = r;
        let room = (rw - 16.0).max(0.0);
        out.push(Shape::Fill([0.0, 0.0, w, h], 0x9000_0000));
        out.push(Shape::Round(r, panel_radius(), 0xF814_1414));
        let m = &modules[edit.module];
        out.push(Shape::Head(fit(&format!("{} / {}", m.name, m.settings[edit.setting].name), room), [x + 8.0, y + 6.0], accent()));
        let selected = edit.draft.as_ref().is_ok_and(Draft::selected);
        out.push(Shape::Round([x + 6.0, y + 22.0, rw - 12.0, 16.0], panel_radius(), if selected { 0xFF30_60B0 } else { 0xFF08_0808 }));
        let note = match &edit.draft {
            Ok(draft) => {
                // The end of the text near the caret shows, with the caret at its place.
                let before = &draft.text()[..draft.caret()];
                let mut from = 0;
                while game.native_text_width(&before[from..]) > room - 4.0 {
                    from += before[from..].chars().next().map_or(1, char::len_utf8);
                }
                let shown = fit(&draft.text()[from..], room);
                let caret = game.native_text_width(&before[from..]);
                out.push(Shape::Text(shown, [x + 10.0, y + 22.0 + text_y(16.0)], 0xFFFFFF));
                out.push(Shape::Fill([x + 10.0 + caret, y + 25.0, 1.0, 10.0], solid(accent())));
                draft.error.unwrap_or("Enter or Apply keeps it, Esc or Cancel leaves it as it was")
            }
            Err(e) => e,
        };
        out.push(Shape::Text(fit(note, room), [x + 8.0, y + 41.0], if matches!(&edit.draft, Ok(d) if d.error.is_none()) { 0x909090 } else { 0xFF7070 }));
        let (apply, cancel) = editor_buttons(r);
        for (b, label, colour) in [(apply, "Apply", solid(accent())), (cancel, "Cancel", 0xFF3A_3A3A)] {
            out.push(Shape::Round(b, panel_radius(), colour));
            let tw = game.native_text_width(label);
            out.push(Shape::Text(label.to_owned(), [b[0] + (b[2] - tw) / 2.0, b[1] + text_y(b[3])], 0xFFFFFF));
        }
    }
    // The saved profiles, when the Profiles module's row was clicked.
    with(|s| super::sunset_profile_menu::draw(game, w, h, at, s.selection.selected(), s.gui.profile_menu.as_ref(), out));
    // The Dashboard has its own search box.
    if dash {
        return;
    }
    // The search box, and over it a reminder of the clicks.
    let search = with(|s| s.gui.search.clone());
    let (text, colour) = if search.is_empty() {
        ("Type to search".to_owned(), 0x909090)
    } else {
        (format!("Search: {search}_"), accent())
    };
    let selected = with(|s| s.gui.select_all) && !search.is_empty();
    let lw_ = game.native_text_width(&text);
    out.push(Shape::Round([(w - lw_) / 2.0 - 6.0, 14.0, lw_ + 12.0, 14.0], panel_radius(), if selected { 0xFF30_60B0 } else { bg(0xC00E_0E0E) }));
    out.push(Shape::Text(text, [(w - lw_) / 2.0, 14.0 + text_y(14.0)], if selected { 0xFFFFFF } else { colour }));
    let hint = "Right click: settings   Enter: toggle search result   Esc: close";
    let hw = game.native_text_width(hint);
    out.push(Shape::Text(hint.to_owned(), [(w - hw) / 2.0, 3.0], 0xA0A0A0));
}

// A profile picked in the Profile list: loaded and the list closed, or the error shown in it.
// A saved profile loaded, a preset's preview shown, or the preset taken, from the Profiles row's menu.
pub(super) fn profile_menu_choice(game: &mut Game<'_>, choice: super::sunset_profile_menu::Choice) {
    use super::sunset_profile_menu::{self as menu, Choice};
    let preset = match choice {
        Choice::Load(name) => return load_profile_from_menu(game, &name),
        Choice::Save(name) => {
            let result = profile_action(game, &["save", &name]);
            return menu_result(game, result);
        }
        Choice::Apply(i) => {
            let result = take_preset(game, i);
            return menu_result(game, result);
        }
        Choice::Preview(i) => i,
    };
    let preview = with(|s| s.preview(&super::sunset_presets::PRESETS[preset]));
    let w = with(|s| s.gui.view_w);
    let preview = preview.map(|p| menu::preview_lines(game, w, preset, &preview_lines(&super::sunset_presets::PRESETS[preset], &p)[1..]));
    with(|s| {
        if let Some(m) = &mut s.gui.profile_menu {
            match preview {
                Ok(lines) => m.preview = Some(menu::Preview { preset, lines }),
                Err(e) => m.error = Some(e),
            }
        }
    });
}

fn load_profile_from_menu(game: &mut Game<'_>, name: &str) {
    let result = profile_action(game, &["load", name]);
    menu_result(game, result);
}

// A load from the Profiles menu: done, the menu closes and the chat says so; else the menu shows why not.
fn menu_result(game: &mut Game<'_>, result: Result<String, String>) {
    match result {
        Ok(message) => {
            with(|s| {
                s.gui.profile_menu = None;
                s.binding = None;
                s.gui.drag = None;
            });
            say(game, &message);
        }
        Err(message) => with(|s| {
            if let Some(menu) = &mut s.gui.profile_menu {
                menu.error = Some(message);
            }
        }),
    }
}

// Runtime part (see runtime.rs): the click GUI's keys, clicks, wheel and the HUD layout editor.

use super::{Game, Screen};
use super::sunset_text_edit::{Draft, EditKey};
use super::sunset::*;

pub(super) fn gui_open() -> bool {
    with(|s| s.gui.open)
}

// A key while the GUI is open: a bind being chosen, or Esc and the menu key
// closing it. Every key stops here.
pub(super) fn gui_key(game: &mut Game<'_>, name: &str) {
    if with(|s| s.gui.profile_menu.is_some()) {
        let choice = with(|s| {
            if name == "key.keyboard.escape" {
                // Out of a preview first, then the menu closes.
                if !s.gui.profile_menu.as_mut().is_some_and(super::sunset_profile_menu::Menu::back) {
                    s.gui.profile_menu = None;
                }
                return None;
            }
            let (w, h) = (s.gui.view_w, s.gui.view_h);
            s.gui.profile_menu.as_mut().and_then(|m| m.key(name, w, h))
        });
        if let Some(choice) = choice {
            profile_menu_choice(game, choice);
        }
        return;
    }
    // The editor takes every key: from the window's event already (text_event), or else here (a key without text of
    // its own, as horizon-ctl's are, types its letter).
    if with(|s| s.gui.editor.is_some() || std::mem::take(&mut s.gui.typed)) {
        let control = game.modifiers.control_key();
        with(|s| {
            if std::mem::take(&mut s.gui.typed) {
                return;
            }
            if name == "key.keyboard.escape" {
                s.gui.editor = None;
                return;
            }
            if name.ends_with("enter") {
                apply_editor(s);
                return;
            }
            let Some(Editor { draft: Ok(draft), list, .. }) = s.gui.editor.as_mut() else {
                return;
            };
            if control && name == "key.keyboard.a" {
                draft.key(EditKey::SelectAll);
            } else if let Some(k) = edit_key(name) {
                draft.key(k);
            } else if let Some(c) = key_char(name).filter(|_| !control) {
                draft.insert(&c.to_string());
            }
            if let Some(picker) = list {
                picker.scroll = 0.0;
            }
        });
        return;
    }
    if let Some(i) = with(|s| s.binding) {
        let chosen = match name {
            "key.keyboard.escape" => {
                with(|s| s.binding = None);
                return;
            }
            "key.keyboard.backspace" | "key.keyboard.delete" => None,
            k => Some(k.to_owned()),
        };
        with(|s| {
            set_bind(s, i, chosen);
            s.binding = None;
        });
        save(game);
        return;
    }
    if name == "key.keyboard.escape" && with(|s| s.gui.window.take().is_some()) {
        // Esc closes the settings window before the menu.
        return;
    }
    if name == "key.keyboard.escape" {
        // The first Esc clears a search; the next closes the GUI.
        with(|s| s.gui.select_all = false);
        if with(|s| std::mem::take(&mut s.gui.search)).is_empty() {
            with(|s| s.gui.closing = true);
        }
        return;
    }
    if is_menu_key(game, name) {
        with(|s| s.gui.closing = true);
        return;
    }
    let control = game.modifiers.control_key();
    if name.ends_with("enter") {
        // Enter in the search turns on (or off) the module it found.
        if let Some(i) = with(|s| first_match(s)) {
            toggle(game, i, chat_lines("Toggle messages"));
        }
    } else if control && name == "key.keyboard.a" {
        with(|s| s.gui.select_all = !s.gui.search.is_empty());
    } else if name == "key.keyboard.backspace" || name == "key.keyboard.delete" {
        with(|s| {
            if control || s.gui.select_all {
                s.gui.search.clear();
            } else {
                s.gui.search.pop();
            }
            s.gui.select_all = false;
        });
    } else if let Some(c) = key_char(name)
        && !control
    {
        with(|s| {
            if std::mem::take(&mut s.gui.select_all) {
                s.gui.search.clear();
            }
            if s.gui.search.chars().count() < 32 {
                s.gui.search.push(c);
            }
        });
    }
}

// The module a search points at: the one it scores best (search.rs).
fn first_match(s: &State) -> Option<usize> {
    if s.gui.search.trim().is_empty() {
        return None;
    }
    let listed = s.listed();
    let found = super::sunset_search::results(&s.modules, &s.gui.search);
    super::sunset_search::ranked(&found, (0..s.modules.len()).filter(|&i| listed(&s.modules[i]))).first().copied()
}

// A letter, digit or space typed in the click GUI's search.
pub(super) fn key_char(name: &str) -> Option<char> {
    let k = name.strip_prefix("key.keyboard.")?;
    if k == "space" {
        return Some(' ');
    }
    let mut chars = k.chars();
    let c = chars.next()?;
    (chars.next().is_none() && c.is_ascii_alphanumeric()).then_some(c)
}

// A mouse button pressed while the GUI is open (its release is read from
// the held buttons each frame).
pub(super) fn gui_press(game: &mut Game<'_>, button: winit::event::MouseButton) {
    use winit::event::MouseButton;
    let at = gui_cursor(game);
    if with(|s| s.gui.profile_menu.is_some()) {
        if button == MouseButton::Left {
            let choice = with(|s| {
                let (w, h) = (s.gui.view_w, s.gui.view_h);
                let menu = s.gui.profile_menu.as_mut()?;
                if menu.closes(at, w, h) {
                    s.gui.profile_menu = None;
                    return None;
                }
                menu.click(at, w, h)
            });
            if let Some(choice) = choice {
                profile_menu_choice(game, choice);
            }
        }
        return;
    }
    // The Profiles module's row, either button: the list of saved profiles instead of a toggle or settings.
    if with(|s| {
        s.gui.editor.is_none()
            && s.binding.is_none()
            && hit_at(s, at).is_some_and(|(_, hit)| matches!(hit, Hit::Module(i) if s.modules[i].name == "Profiles"))
    }) {
        let result = super::sunset_profiles::Store::new(game.native_data_dir(ID)).and_then(|store| store.list());
        with(|s| {
            let names = result.as_ref().cloned().unwrap_or_default();
            let mut menu = super::sunset_profile_menu::Menu::new(names, s.selection.selected(), s.gui.view_w, s.gui.view_h);
            menu.error = result.err();
            s.gui.profile_menu = Some(menu);
            s.gui.drag = None;
        });
        return;
    }
    // A bind being chosen takes any button but the left one (which clicks as ever).
    let captured = with(|s| {
        let i = s.binding.filter(|_| button != MouseButton::Left && s.gui.editor.is_none())?;
        set_bind(s, i, Some(horizon_client::keybinds::mouse_name(button)));
        s.binding = None;
        Some(())
    });
    if captured.is_some() {
        save(game);
        return;
    }
    let right = match button {
        MouseButton::Left => false,
        MouseButton::Right => true,
        _ => return,
    };
    let mut toggled = None;
    let mut changed = false;
    let mut reset = None;
    with(|s| {
        // The editor is in front of everything: its buttons, nothing else; a picker's rows too.
        if let Some(Editor { module, setting, draft: Ok(draft), list: Some(picker), .. }) = &s.gui.editor {
            use super::sunset_picker as pick;
            let r = pick::rect(s.gui.view_w, s.gui.view_h);
            let area = pick::list_area(r);
            if !right && inside(pick::done_button(r), at) {
                s.gui.editor = None;
            } else if !right && inside(area, at) {
                let (i, j) = (*module, *setting);
                let row = ((at.1 - area[1] + super::sunset_smooth::shown(super::sunset_smooth::PICKER, picker.scroll)) / pick::ROW) as usize;
                if let Value::Text(t) = &s.modules[i].settings[j].value
                    && let Some((name, _)) = pick::rows(picker, t, draft.text()).get(row)
                {
                    let list = pick::clicked(picker, t, name);
                    s.modules[i].settings[j].value = Value::Text(list);
                    changed = true;
                }
            }
            return;
        }
        if s.gui.editor.is_some() {
            let (apply, cancel) = editor_buttons(editor_rect(s.gui.view_w, s.gui.view_h));
            if !right && inside(apply, at) {
                apply_editor(s);
                changed = true;
            } else if !right && inside(cancel, at) {
                s.gui.editor = None;
            }
            return;
        }
        let found = hit_at(s, at);
        // A number being typed: a click in its field leaves it be; anywhere else, it is left as it was.
        if let Some(Editor { module, setting, draft: Ok(draft), inline: true, .. }) = &s.gui.editor {
            let in_field = found.is_some_and(|(r, hit)| {
                hit == Hit::Setting(*module, *setting) && at.0 >= r[0] + r[2] - RIGHT_PAD - field_width(game, draft.text()) && at.1 < number_band(r)
            });
            if in_field {
                return;
            }
            s.gui.editor = None;
        }
        let Some((r, hit)) = found else {
            // Off the menu: a HUD element can be taken and moved, or (the right button) sent back to its place.
            if let Some((name, dx, dy)) = super::sunset_hud_bars::grab(game.cursor) {
                if right {
                    reset = Some(name);
                } else {
                    s.gui.drag = Some(Drag::Hud(name, dx, dy));
                }
            }
            return;
        };
        // Modules is its switches: either button opens them.
        let right = right || matches!(hit, Hit::Module(i) if s.modules[i].name == super::sunset_extra_modules::NAME);
        match (hit, right) {
            (Hit::WinTitle, false) => {
                if let Some(w) = s.gui.window {
                    s.gui.drag = Some(Drag::Window(at.0 - w.x, at.1 - w.y));
                }
            }
            (Hit::WinClose, false) => s.gui.window = None,
            (Hit::WinBody | Hit::WinTitle | Hit::WinClose, _) => {}
            (Hit::Dash(super::sunset_dashboard::Part::Toggle), false) => toggled = super::sunset_dashboard::chosen(),
            (Hit::Dash(part), right) => super::sunset_dashboard::press(s, part, right),
            (Hit::Header(c), false) => {
                let p = s.gui.panels[c];
                s.gui.drag = Some(Drag::Panel(c, at.0 - p.x, at.1 - p.y));
            }
            (Hit::Header(c), true) => {
                s.gui.panels[c].collapsed = !s.gui.panels[c].collapsed;
                changed = true;
            }
            (Hit::Module(i), false) => toggled = Some(i),
            (Hit::Module(i), true) if super::sunset_dashboard::on() => {
                super::sunset_dashboard::choose(i);
                s.binding = None;
            }
            (Hit::Module(i), true) if s.module("ClickGUI").is_some_and(|m| m.p("Settings") == "Inline") => {
                if let Some(k) = s.gui.expanded.iter().position(|&e| e == i) {
                    s.gui.expanded.remove(k);
                } else {
                    s.gui.expanded.push(i);
                }
            }
            // Its own window, in the middle at first (the same module again closes it).
            (Hit::Module(i), true) => {
                s.gui.window = match s.gui.window {
                    Some(w) if w.module == i => None,
                    _ => Some(Win { module: i, x: (s.gui.view_w - win_w(s)) / 2.0, y: 40.0, scroll: 0.0, about_h: 0.0, content: 0.0, room: 0.0 }),
                };
                s.binding = None;
            }
            (Hit::Bind(i), false) => s.binding = if s.binding == Some(i) { None } else { Some(i) },
            (Hit::Bind(i), true) => {
                s.modules[i].key = None;
                s.binding = None;
                changed = true;
            }
            (Hit::Setting(i, j), right) => {
                let number = match s.modules[i].settings[j].value {
                    Value::Num { v, .. } => Some(v),
                    _ => None,
                };
                // A click on the number: it is typed instead (all of it selected, so typing replaces it).
                if let (Some(v), false) = (number, right)
                    && at.0 >= r[0] + r[2] - RIGHT_PAD - game.native_text_width(&num(v)) - 3.0
                    && at.1 < number_band(r)
                {
                    let mut draft = Draft::new(&num(v));
                    if let Ok(d) = &mut draft {
                        d.key(EditKey::SelectAll);
                    }
                    s.gui.editor = Some(Editor { module: i, setting: j, draft, inline: true, list: None });
                    s.gui.drag = None;
                    s.binding = None;
                } else if number.is_some() && !right {
                    s.gui.drag = Some(Drag::Slider(i, j, r, gui_scale()));
                    changed = slide(s, i, j, r, at.0);
                } else if number.is_some() {
                    // Right click on a slider: back to its default.
                    let fresh = fresh_module(s, i).settings.swap_remove(j);
                    s.modules[i].settings[j] = fresh;
                    changed = true;
                } else if let (Value::Text(t), false) = (&s.modules[i].settings[j].value, right) {
                    // A list of blocks, items or entities opens the picker (the draft is its search), other text the
                    // editor.
                    let m = &s.modules[i];
                    let list = super::sunset_picker::list_kind(m.name, m.settings[j].name).map(|k| {
                        if m.name == "Xray" && m.p("List") == "Simple" {
                            super::sunset_picker::short_list(super::sunset_picker::VALUABLES)
                        } else {
                            super::sunset_picker::open(game, k)
                        }
                    });
                    let draft = if list.is_some() { Draft::new("") } else { Draft::new(t) };
                    s.gui.editor = Some(Editor { module: i, setting: j, draft, inline: false, list });
                    s.gui.drag = None;
                    s.binding = None;
                } else {
                    s.modules[i].settings[j].click(right);
                    changed = true;
                }
            }
        }
    });
    if let Some(i) = toggled {
        toggle(game, i, false);
    } else if changed {
        save(game);
    }
    if let Some(name) = reset {
        reset_place(game, name);
    }
}

// The module that keeps an element's place: the one with its `name position` setting (HUD's own, Scaffold's block
// counter, ESP's Murderer list, Auto Spear's damage indicator, Radar).
fn place_owner<'a>(modules: &'a mut [Module], name: &str) -> Option<&'a mut Module> {
    let key = format!("{name} position");
    modules.iter_mut().find(|m| m.settings.iter().any(|st| st.name == key))
}

// A HUD element dragged by the pointer, taken `dx`, `dy` into it: its position Custom, at where its corner is now.
// Horizon's widgets are moved in Horizon's layout instead (drag_widgets).
fn move_hud(s: &mut State, game: &Game<'_>, name: &str, dx: f32, dy: f32) {
    if super::sunset_hud_bars::widget(name).is_some() {
        return;
    }
    let Some((fx, fy)) = super::sunset_hud_bars::drag_to(name, game.cursor.0 - dx, game.cursor.1 - dy) else {
        return;
    };
    let Some(m) = place_owner(&mut s.modules, name) else {
        return;
    };
    for st in &mut m.settings {
        match st.name.strip_prefix(name).map(str::trim) {
            Some("position") => {
                if let Value::Pick { i, of } = &mut st.value {
                    *i = of.iter().position(|o| *o == "Custom").unwrap_or(*i);
                }
            }
            Some("x") => {
                if let Value::Num { v, .. } = &mut st.value {
                    *v = fx;
                }
            }
            Some("y") => {
                if let Value::Num { v, .. } = &mut st.value {
                    *v = fy;
                }
            }
            _ => {}
        }
    }
}

// A right click on a HUD element: back to its Default place (its position as the module's defaults have it), or a
// Horizon widget back to its corner.
pub(super) fn reset_place(game: &mut Game<'_>, name: &str) {
    if let Some(id) = super::sunset_hud_bars::widget(name) {
        super::sunset_hud_bars::reset_widget(game, id);
        super::sunset_hud_bars::settle_widgets(game);
        return;
    }
    let key = format!("{name} position");
    let fresh = defaults();
    let reset = with(|s| {
        let m = place_owner(&mut s.modules, name)?;
        let default = fresh.iter().find(|f| f.name == m.name)?.settings.iter().find(|st| st.name == key)?.value.clone();
        let st = m.settings.iter_mut().find(|st| st.name == key)?;
        (st.value != default).then(|| st.value = default)
    });
    if reset.is_some() {
        save(game);
    }
}

// Each frame: a Horizon widget being dragged follows the pointer in Horizon's layout; once none is, Horizon's options
// are saved if one moved.
pub(super) fn drag_widgets(game: &mut Game<'_>) {
    let dragging = with(|s| match s.gui.drag {
        Some(Drag::Hud(name, dx, dy)) => super::sunset_hud_bars::widget(name).map(|id| (id, dx, dy)),
        _ => None,
    });
    match dragging {
        Some((id, dx, dy)) => {
            let (x, y) = (game.cursor.0 - dx, game.cursor.1 - dy);
            super::sunset_hud_bars::move_widget(game, id, x, y);
        }
        None => super::sunset_hud_bars::settle_widgets(game),
    }
}

// HUD's layout editor with the chat open: every element is framed, a press on one drags it until the button comes up
// (saved then), and a right click sends it back to its place. The chat closed, a drag still going ends there.
pub(super) fn chat_layout(game: &mut Game<'_>, out: &mut Vec<Shape>) {
    use super::sunset_hud_bars::ChatDrag;
    let dragging = with(|s| match s.gui.drag {
        Some(Drag::Hud(name, dx, dy)) => Some((name, dx, dy)),
        _ => None,
    });
    if game.screen != Screen::Chat || with(|s| s.gui.open) {
        super::sunset_hud_bars::chat_closed();
        if dragging.is_some() && !with(|s| s.gui.open) {
            with(|s| s.gui.drag = None);
            save(game);
        }
        return;
    }
    match super::sunset_hud_bars::chat_layout(game, dragging.map(|d| d.0), out) {
        Some(ChatDrag::Start(name, dx, dy)) => with(|s| s.gui.drag = Some(Drag::Hud(name, dx, dy))),
        Some(ChatDrag::End) => {
            with(|s| s.gui.drag = None);
            save(game);
        }
        Some(ChatDrag::Reset(name)) => reset_place(game, name),
        None => {
            if let Some((name, dx, dy)) = dragging {
                with(|s| move_hud(s, game, name, dx, dy));
            }
        }
    }
}

// A drag follows the pointer each frame.
pub(super) fn follow_drag(game: &Game<'_>, w: f32, h: f32) {
    let at = gui_cursor(game);
    with(|s| match s.gui.drag {
        Some(Drag::Panel(c, dx, dy)) => {
            let p = &mut s.gui.panels[c];
            p.x = (at.0 - dx).clamp(0.0, (w - panel_w()).max(0.0));
            p.y = (at.1 - dy).clamp(0.0, (h - head_h()).max(0.0));
        }
        Some(Drag::Slider(i, j, r, scale)) => {
            // The look follows as it is dragged, but for what moves the panels: that waits for the release (save).
            let layout = s.modules[i].name == "ClickGUI" && matches!(s.modules[i].settings[j].name, "Panel width" | "GUI scale" | "Text indent");
            if slide(s, i, j, r, game.cursor.0 / scale) && !layout {
                sync_flags(s);
            }
        }
        Some(Drag::Window(dx, dy)) => {
            if let Some(win) = &mut s.gui.window {
                (win.x, win.y) = (at.0 - dx, at.1 - dy);
            }
        }
        Some(Drag::Hud(name, dx, dy)) => move_hud(s, game, name, dx, dy),
        None => {}
    });
    // The left button came up: the drag ends where the pointer is.
    if !game.physical_buttons.contains(&winit::event::MouseButton::Left)
        && with(|s| s.gui.drag.take().is_some())
    {
        save(game);
    }
}

// Runtime part (see runtime.rs): small shared helpers: chat lines, numbers, keys, players, aiming.

use super::{Game, Screen};
use super::sunset_bind_state::canonical;
use horizon_client::text::Text;
use winit::keyboard::KeyCode;
use super::sunset::*;

// ---------------------------------------------------------------- helpers

pub(super) fn on_off(b: bool) -> &'static str {
    if b { "ON" } else { "OFF" }
}

pub(super) fn num(v: f64) -> String {
    let s = format!("{v:.2}");
    let s = s.trim_end_matches('0').trim_end_matches('.');
    if s == "-0" { "0".into() } else { s.into() }
}

pub(super) fn round_to(v: f64, step: f64) -> f64 {
    if step <= 0.0 {
        return v;
    }
    (v / step).round() * step
}

// Lowercase letters and digits only: how commands and the config name things.
pub(super) fn norm(s: &str) -> String {
    s.chars()
        .filter(char::is_ascii_alphanumeric)
        .map(|c| c.to_ascii_lowercase())
        .collect()
}

// A key or mouse button typed in a command (`r`, `rshift`, `f6`, `mouse4`, `key.keyboard.r`) as the game names it.
pub(super) fn key_from_text(t: &str) -> Option<String> {
    canonical(t)
}

pub(super) fn key_label(key: Option<&str>) -> String {
    match key {
        None => "None".into(),
        Some(k) => {
            if let Some(button) = k.strip_prefix("key.mouse.") {
                return format!("Mouse {}", match button {
                    "left" => "Left",
                    "right" => "Right",
                    "middle" => "Middle",
                    "4" => "Back",
                    "5" => "Forward",
                    other => other,
                });
            }
            let short = k.strip_prefix("key.keyboard.").or_else(|| k.strip_prefix("key.mouse.")).unwrap_or(k);
            let mut out = String::new();
            for (i, part) in short.split('.').enumerate() {
                if i > 0 {
                    out.push(' ');
                }
                let mut c = part.chars();
                if let Some(f) = c.next() {
                    out.extend(f.to_uppercase());
                    out.push_str(c.as_str());
                }
            }
            out
        }
    }
}

// ClickGUI's switch for a kind of chat line ("Toggle messages", "Module messages").
pub(super) fn chat_lines(kind: &str) -> bool {
    with(|s| s.module("ClickGUI").is_none_or(|m| m.b(kind)))
}

// A line in chat: Sunset's tag, then the message.
pub(super) fn say(game: &mut Game<'_>, msg: &str) {
    if !running() {
        return;
    }
    let line = Text::literal("[Sunset] ")
        .with_color(accent())
        .append(Text::literal(msg).with_color(horizon_client::text::WHITE));
    let focused = game.screen == Screen::Chat;
    let atlas = &game.gui.atlas;
    game.ui.chat.add(
        atlas,
        line,
        None,
        horizon_client::chat::ChatSource::Client,
        game.ticks,
        focused,
    );
}

pub(super) fn own_id(game: &Game<'_>) -> Option<u32> {
    game.remote.as_ref().map(|r| r.entity_id as u32)
}

// The move keys held now: forward minus back, left minus right.
pub(super) fn move_input(game: &Game<'_>) -> (f64, f64) {
    if !game.native_playing() {
        return (0.0, 0.0);
    }
    let held = |k: KeyCode| f64::from(u8::from(game.keys.contains(&k)));
    (
        held(KeyCode::KeyW) - held(KeyCode::KeyS),
        held(KeyCode::KeyA) - held(KeyCode::KeyD),
    )
}

// The direction the move keys point, flat, length 1 (or zero).
pub(super) fn move_direction(game: &Game<'_>) -> Option<[f64; 2]> {
    let (f, s) = move_input(game);
    if f == 0.0 && s == 0.0 {
        return None;
    }
    let yaw = f64::from(game.yaw).to_radians();
    // Yaw 0 faces south (+z); left of it is east (+x).
    let x = -yaw.sin() * f + yaw.cos() * s;
    let z = yaw.cos() * f + yaw.sin() * s;
    let len = (x * x + z * z).sqrt();
    Some([x / len, z / len])
}

#[derive(Clone, Copy, PartialEq)]
pub(super) enum Kind {
    Player,
    Hostile,
    Passive,
}

pub(super) fn kind_of(mob: &horizon_client::mobs::Mob) -> Kind {
    if mob.kind.id == "minecraft:player" {
        Kind::Player
    } else if mob.hostile() || mob.kind.category == "monster" {
        Kind::Hostile
    } else {
        Kind::Passive
    }
}

// A mob of a kind switched on, or of a type in the module's Entities list.
pub(super) fn wanted(m: &Module, kind: Kind, id: &str) -> bool {
    let of_kind = match kind {
        Kind::Player => m.b("Players"),
        Kind::Hostile => m.b("Hostiles"),
        Kind::Passive => m.b("Passive"),
    };
    super::sunset_util::kind_wanted(of_kind, m.t("Entities"), m.p("List mode") == "Blacklist", id)
}

pub(super) fn is_friend(friends: &[String], names: &[(u32, String)], id: u32) -> bool {
    names
        .iter()
        .find(|(i, _)| *i == id)
        .is_some_and(|(_, n)| friends.iter().any(|f| f.eq_ignore_ascii_case(n)))
}

pub(super) fn look_at(eye: [f64; 3], at: [f64; 3]) -> (f32, f32) {
    let (dx, dy, dz) = (at[0] - eye[0], at[1] - eye[1], at[2] - eye[2]);
    let yaw = (-dx).atan2(dz).to_degrees();
    let pitch = -dy.atan2((dx * dx + dz * dz).sqrt()).to_degrees();
    (yaw as f32, pitch as f32)
}

// Runtime part (see runtime.rs): the HUD each frame and the GUI on top of it.

use super::{Game, Screen};
use horizon_client::extras::Corner;
use horizon_client::extras_hud::Corners;
use horizon_client::hud::HudBatch;
use std::sync::Mutex;
use std::sync::atomic::Ordering;
use super::sunset::*;

pub(super) fn hud(game: &mut Game<'_>, batch: &mut HudBatch, corners: &mut Corners) {
    if !running() || !game.native_window() || !game.native_on(ID) {
        return;
    }
    ensure_loaded(game);
    super::sunset_crosshair::draw(game, batch);
    let mods = snapshot();
    let get = |n: &str| mods.iter().find(|m| m.name == n && m.on);
    let (w, h) = (batch.width, batch.height);
    // GUI scale, as far as a row of the narrowest panels still fits the window.
    let scale = f32::from_bits(LOOK[6].load(Ordering::Relaxed)).min((w / MIN_ROW).max(1.0));
    LOOK[7].store(scale.to_bits(), Ordering::Relaxed);
    let lw = (1.5 / batch.scale).max(0.5);
    let mut shapes = std::mem::take(&mut *SHAPES.lock().unwrap_or_else(|e| e.into_inner()));

    if let Some(cam) = Camera::of(game, w, h)
        && game.player.is_some()
    {
        // World labels use the open GUI's text scale too: one glyph size a frame, so Sunset's font is not rebuilt
        // twice a frame and the labels' glyphs are not taken from an atlas rebuilt under them.
        let real = batch.scale;
        if game.screen == Screen::Playing && with(|s| s.gui.open && !s.gui.closing) {
            batch.scale = real * scale;
        }
        world_overlays(game, &cam, &mods, lw, &mut Painter { game, batch: &mut *batch });
        super::sunset_api::world(game, &cam, &mut Painter { game, batch: &mut *batch }, lw);
        batch.scale = real;
    }

    // What the layout editor can take is placed again each frame: Horizon's own widgets (drawn before this) first, and
    // one of them being dragged follows the pointer.
    super::sunset_hud_bars::clear_placed();
    drag_widgets(game);
    super::sunset_hud_bars::place_widgets(game, w, h);
    super::sunset_loadouts::draw(game, w, h, &mut shapes);
    // The spear's damage indicator and the Murderer list, where they are drawn or where they were dragged.
    let from = shapes.len();
    super::sunset_melee::draw_spear(game, w, h, &mut shapes);
    if let Some(spear) = get("Auto Spear") {
        super::sunset_hud_bars::editable(game, &mut shapes, from, spear, "Damage indicator", w, h);
    }
    if let Some(esp) = get("ESP") {
        let from = shapes.len();
        super::sunset_murder::draw(game, esp, w, &mut shapes);
        super::sunset_hud_bars::editable(game, &mut shapes, from, esp, "Murderer list", w, h);
    }
    // Where the HUD module's own shapes start: its Text case is for them, not for the menu, the chat or plugins.
    let hud_from = shapes.len();
    if let Some(hud) = get("HUD") {
        if hud.b("Target HUD") && get("Kill Aura").is_some() {
            // Target HUD sits by the crosshair; drawn there, then slid to its dragged place if moved.
            let from = shapes.len();
            super::sunset_aura::draw_target(game, w, h, hud.p("Target HUD mode") == "Potato", &mut shapes);
            super::sunset_hud_bars::editable(game, &mut shapes, from, hud, "Target HUD", w, h);
        }
        let cased = |text: &str| super::sunset_hud_list::cased(hud, text);
        if hud.b("Watermark") && (hud.p("Watermark position") == "Custom" || game.native_corner_shown(Corner::TopLeft)) {
            let own = hud.t("Watermark text").trim();
            let line = cased(&if own.is_empty() { format!("{NAME} {VERSION}") } else { own.to_owned() });
            let profile = hud.b("Watermark profile").then(|| cased(&with(|s| format!("Profile: {}", s.selection.label()))));
            let bw = game.native_text_width(&line).max(profile.as_ref().map_or(0.0, |t| game.native_text_width(t))) + 4.0;
            let bh = if profile.is_some() { 24.0 } else { 12.0 };
            let (x, y) = if hud.p("Watermark position") == "Custom" {
                (
                    (hud.n("Watermark x") as f32 * w).clamp(0.0, (w - bw).max(0.0)),
                    (hud.n("Watermark y") as f32 * h).clamp(0.0, (h - bh).max(0.0)),
                )
            } else {
                corners.place(Corner::TopLeft, bw, bh)
            };
            let colour = super::sunset_hud_list::colour_at(hud, hud.p("Watermark color mode"), y);
            shapes.push(Shape::Text(line, [x + 2.0, y + 2.0], colour));
            if let Some(text) = profile {
                shapes.push(Shape::Text(text, [x + 2.0, y + 14.0], 0xE4E4E4));
            }
            super::sunset_hud_bars::place("Watermark", [x, y, bw, bh], w, h);
        }
        let left = hud.p("Module list side") == "Left";
        let corner = if left { Corner::TopLeft } else { Corner::TopRight };
        let moved = hud.p("Module list position") == "Custom";
        if hud.b("Module list") && (moved || game.native_corner_shown(corner)) {
            let mut place = |width: f32, height: f32| {
                let (x, y) = if moved {
                    (
                        (hud.n("Module list x") as f32 * w).clamp(0.0, (w - width).max(0.0)),
                        (hud.n("Module list y") as f32 * h).clamp(0.0, (h - height).max(0.0)),
                    )
                } else {
                    corners.place(corner, width, height)
                };
                // Never over the status effect icons at the top right: just under them, Default or dragged (the game's
                // corner leaves them room only while playing, not with the chat open).
                let (x, y) = super::sunset_hud_bars::below_effects(game, [x, y, width, height], w, h);
                super::sunset_hud_bars::place("Module list", [x, y, width, height], w, h);
                (x, y)
            };
            super::sunset_hud_list::draw(game, hud, &mods, !left, &mut place, &mut shapes);
        }
        // The server's scoreboard sidebar (drawn by the game itself): framed here so the chat editor can grab it, and
        // moved by the offset the render crate applies to its draws, to where it was dragged.
        if let Some((nx, ny, nw, nh)) = horizon_client_render::hud_overlays::sunset_scoreboard_pos::natural() {
            let (nxf, nyf, nwf, nhf) = (nx as f32, ny as f32, nw as f32, nh as f32);
            let custom = hud.p("Scoreboard position") == "Custom";
            let (x, y) = if custom {
                (
                    (hud.n("Scoreboard x") as f32 * w).clamp(0.0, (w - nwf).max(0.0)),
                    (hud.n("Scoreboard y") as f32 * h).clamp(0.0, (h - nhf).max(0.0)),
                )
            } else {
                (nxf, nyf)
            };
            super::sunset_hud_bars::place("Scoreboard", [x, y, nwf, nhf], w, h);
            horizon_client_render::hud_overlays::sunset_scoreboard_pos::set_offset(custom, (x - nxf) as i32, (y - nyf) as i32);
        }
        let coordinates = game.native_player().filter(|_| hud.b("Coordinates")).map(|p| {
            let (x, y, z) = (p.x.floor(), p.y.floor(), p.z.floor());
            let other = match p.dimension {
                "minecraft:overworld" => format!(" (Nether {} {})", (p.x / 8.0).floor(), (p.z / 8.0).floor()),
                "minecraft:the_nether" => format!(" (Overworld {} {})", (p.x * 8.0).floor(), (p.z * 8.0).floor()),
                _ => String::new(),
            };
            format!("XYZ {x} {y} {z}{other}")
        });
        let custom = hud.p("Coordinates position") == "Custom";
        // Coordinates moved off the corner: on their own where they were dragged to.
        if custom && let Some(text) = &coordinates {
            let (tw, th) = (game.native_text_width(text) + 4.0, 12.0);
            let x = (hud.n("Coordinates x") as f32 * w).clamp(0.0, (w - tw).max(0.0));
            let y = (hud.n("Coordinates y") as f32 * h).clamp(0.0, (h - th).max(0.0));
            super::sunset_hud_bars::place("Coordinates", [x, y, tw, th], w, h);
            shapes.push(Shape::Text(text.clone(), [x + 2.0, y + 2.0], 0xFFFFFF));
        }
        // The Info line's parts (FPS, Speed, Facing, Totems), by name: each in the corner's line (Default) or on its own
        // where it was dragged to (Custom), and each can be taken on its own.
        let mut info: Vec<(&'static str, String)> = Vec::new();
        if let Some(p) = game.native_player() {
            if hud.b("FPS") {
                info.push(("FPS", format!("{} FPS", game.native_frame_rate().0)));
            }
            if hud.b("Speed")
                && let Some(pl) = game.player.as_ref()
            {
                let (dx, dz) = (pl.position.x - game.previous_position.x, pl.position.z - game.previous_position.z);
                info.push(("Speed", format!("{:.1} b/s", (dx * dx + dz * dz).sqrt() * 20.0)));
            }
            if hud.b("Facing") {
                const NAMES: [&str; 8] = ["South +Z", "South-West", "West -X", "North-West", "North -Z", "North-East", "East +X", "South-East"];
                let yaw = f64::from(p.yaw).rem_euclid(360.0);
                info.push(("Facing", NAMES[((yaw + 22.5) / 45.0).floor() as usize % 8].to_owned()));
            }
            if hud.b("Totems") {
                let count = |s: &Option<horizon_client::items::ItemStack>| {
                    s.as_ref().filter(|s| s.item.ends_with("totem_of_undying")).map_or(0, |s| s.count)
                };
                let total: u32 = game.inventory.iter().map(count).sum::<u32>() + count(&game.offhand);
                info.push(("Totems", format!("{total} totems")));
            }
        }
        let (moved, in_line): (Vec<_>, Vec<_>) = info
            .into_iter()
            .map(|(name, text)| (name, cased(&text)))
            .partition(|(name, _)| hud.p(&format!("{name} position")) == "Custom");
        for (name, text) in moved {
            let (tw, th) = (game.native_text_width(&text) + 4.0, 12.0);
            let x = (hud.n(&format!("{name} x")) as f32 * w).clamp(0.0, (w - tw).max(0.0));
            let y = (hud.n(&format!("{name} y")) as f32 * h).clamp(0.0, (h - th).max(0.0));
            super::sunset_hud_bars::place(name, [x, y, tw, th], w, h);
            shapes.push(Shape::Text(text, [x + 2.0, y + 2.0], 0xFFFFFF));
        }
        if game.native_corner_shown(Corner::TopLeft) {
            let mut lines: Vec<String> = Vec::new();
            let in_corner = coordinates.filter(|_| !custom).map(|c| cased(&c));
            if let Some(text) = &in_corner {
                lines.push(text.clone());
            }
            const GAP: &str = "  ";
            if !in_line.is_empty() {
                lines.push(in_line.iter().map(|(_, t)| t.as_str()).collect::<Vec<_>>().join(GAP));
            }
            let width = lines.iter().map(|l| game.native_text_width(l)).fold(0.0, f32::max);
            if !lines.is_empty() {
                let (bx, by) = corners.place(Corner::TopLeft, width + 4.0, lines.len() as f32 * 10.0 + 2.0);
                if let Some(text) = &in_corner {
                    super::sunset_hud_bars::place("Coordinates", [bx, by, game.native_text_width(text) + 4.0, 12.0], w, h);
                }
                // The Info line is the last: each part of it framed where it sits in the line.
                let row = by + 1.0 + (lines.len() - 1) as f32 * 10.0;
                let mut x = bx + 1.0;
                for (name, text) in &in_line {
                    let tw = game.native_text_width(text) + 2.0;
                    super::sunset_hud_bars::place(name, [x, row, tw, 11.0], w, h);
                    x += tw - 2.0 + game.native_text_width(GAP);
                }
                for (i, line) in lines.into_iter().enumerate() {
                    shapes.push(Shape::Text(line, [bx + 2.0, by + 2.0 + i as f32 * 10.0], 0xFFFFFF));
                }
            }
        }
        // After the corners' text, so a corner keeps that at its edge.
        if game.native_playing() {
            super::sunset_hud_bars::draw(game, hud, w, h, corners, &mut shapes);
        }
        super::sunset_hud_list::case_shapes(hud, &mut shapes[hud_from..]);
    }
    let shadow = get("HUD").is_none_or(|hud| hud.b("Text shadow"));

    // Scaffold's block counter: a number and a word above the hotbar, clear of the hearts, armour and item name (or where
    // it was dragged).
    if let Some(m) = get("Scaffold").filter(|m| m.b("Block counter"))
        && game.native_playing()
        && game.player.is_some()
        && !game.spectator()
    {
        let blocks = scaffold_blocks(game, m);
        let text = format!("{blocks} {}", if blocks == 1 { "block" } else { "blocks" });
        let colour = if blocks < 16 { 0xFF5555 } else { 0xFFFFFF };
        let from = shapes.len();
        shapes.push(Shape::Text(text.clone(), [(w - game.native_text_width(&text)) / 2.0, h - 71.0], colour));
        super::sunset_hud_bars::editable(game, &mut shapes, from, m, "Block counter", w, h);
    }
    // Radar's place (after the HUD's corners, as it is drawn last), so the layout editor can take it too.
    let radar = if with(|s| s.gui.open) { None } else { super::sunset_radar::place(game, w, h, corners, &mods) };
    chat_layout(game, &mut shapes);

    if with(|s| s.gui.open && s.gui.closing) {
        close_gui(game);
    }
    let mut gui_shapes = Vec::new();
    // A player picker follows the players online, with their faces.
    let mut picker = with(|s| s.gui.editor.as_mut().and_then(|e| e.list.take()));
    super::sunset_picker::see_players(game, &mut picker);
    with(|s| {
        if let Some(e) = s.gui.editor.as_mut() {
            e.list = picker;
        }
    });
    if with(|s| s.gui.open) {
        if game.screen == Screen::Playing && game.player.is_some() {
            // The world dims behind the panels by Background dim (percent), the one fill behind them.
            let dim = LOOK[3].load(Ordering::Relaxed).min(100) * 255 / 100;
            if dim > 0 {
                shapes.push(Shape::Fill([0.0, 0.0, w, h], dim << 24));
            }
            draw_gui(game, &mods, w / scale, h / scale, 1.0 / (batch.scale * scale), &mut gui_shapes);
        } else {
            with(|s| {
                s.gui.open = false;
                s.gui.drag = None;
                s.gui.editor = None;
                s.gui.window = None;
            });
        }
    }
    let game = &*game;
    // Sunset's font is drawn for the scale it is told, and rebuilds its glyphs when that changes: while the GUI is
    // open all of the frame's text uses the GUI's, so it is sharp at any GUI scale and they rebuild only once.
    let real = batch.scale;
    if !gui_shapes.is_empty() {
        batch.scale = real * scale;
    }
    super::sunset_api::hud(game, &mut shapes, [w, h], lw);
    paint(game, batch, &mut shapes, 1.0 / batch.scale, shadow);
    *SHAPES.lock().unwrap_or_else(|e| e.into_inner()) = shapes;
    // The GUI goes on top of the rest of the frame too: gui_top paints it last.
    *GUI_TOP.lock().unwrap_or_else(|e| e.into_inner()) = (gui_shapes, scale);
    batch.scale = real;
    if let Some(at) = radar.filter(|_| !with(|s| s.gui.open)) {
        super::sunset_radar::draw(game, batch, at, &mods);
    }
}

// The open GUI's shapes this frame and its scale, from hud for gui_top.
pub(super) static GUI_TOP: Mutex<(Vec<Shape>, f32)> = Mutex::new((Vec::new(), 1.0));

// After all of the frame's HUD (chat, titles, the tab list, toasts) and before its prompts (a server's pack, a dialog, a
// link), which stay on top and take the clicks, as ever: the GUI, scaled about the corner its coordinates start from.
pub(super) fn gui_top(game: &Game<'_>, batch: &mut HudBatch) {
    let (mut shapes, scale) = std::mem::replace(&mut *GUI_TOP.lock().unwrap_or_else(|e| e.into_inner()), (Vec::new(), 1.0));
    if shapes.is_empty() {
        return;
    }
    let real = batch.scale;
    batch.scale = real * scale;
    let start = batch.vertices.len();
    paint(game, batch, &mut shapes, 1.0 / batch.scale, true);
    // Opening, it rises into place as it fades in.
    if let Some((opacity, below)) = super::sunset_dashboard::open_motion() {
        for v in &mut batch.vertices[start..] {
            v.pos[1] += below;
            v.color = (v.color & 0x00FF_FFFF) | (((v.color >> 24) as f32 * opacity) as u32) << 24;
        }
    }
    batch.scale_since(start, 0.0, 0.0, scale, scale);
    batch.scale = real;
}

// Runtime part (see runtime.rs): armour, Chest Swap, Auto Replenish, Auto Tool and middle click.

use super::{Game, Screen};
use winit::keyboard::KeyCode;
use super::sunset::*;

// Puts the stack in inventory slot `i` on armor slot `a`: shift-click into an empty slot; else from the hotbar one
// hotbar-key swap with the armor slot, and from the main inventory three (into a hotbar slot, onto the armor slot, the
// worn piece back to `i`). Never by picking pieces up: a server that refuses one of the clicks would leave a piece on
// the cursor, and a refused middle swap puts both back.
// Ungated: Chest Swap and Take off check the input themselves, and a restore must go out.
pub(super) fn wear(game: &mut Game<'_>, i: usize, a: usize) {
    use horizon_client::menu::Input::{QuickMove, Swap};
    let armor = 500 + a;
    if super::sunset_loadouts::locked(i) || super::sunset_loadouts::locked(armor) {
        return;
    }
    let ops: Vec<(Option<usize>, i32, horizon_client::menu::Input)> = if game.armor[a].is_none() {
        vec![(Some(i), 0, QuickMove)]
    } else if i < 9 {
        vec![(Some(armor), i as i32, Swap)]
    } else {
        let empty: [bool; 9] = std::array::from_fn(|h| game.inventory.get(h).is_none_or(|s| s.is_none()));
        let locked: [bool; 9] = std::array::from_fn(super::sunset_loadouts::locked);
        let Some(h) = super::sunset_inventory_plan::pivot(empty, locked, game.selected) else {
            return;
        };
        vec![(Some(i), h as i32, Swap), (Some(armor), h as i32, Swap), (Some(i), h as i32, Swap)]
    };
    game.remote_menu_ops(&ops);
}

// An armour piece's material: `diamond` of diamond_helmet.
fn armor_material(item: &str) -> &str {
    let name = super::sunset_util::short(item);
    name.rsplit_once('_').map_or(name, |(material, _)| material)
}

// Switch key (Sunset's ArmorSwitch), on a press: the next set Switch sets lists after the one you wear, once all four
// of its pieces are on you or in your inventory; Auto Armor then wears that set instead of the best.
pub(super) fn armor_switch(game: &mut Game<'_>, key: &str) {
    auto_armor_key(game, key);
    let Some(m) = with(|s| s.module("Inventory Manager").filter(|m| m.b("Auto Armor")).cloned()) else {
        return;
    };
    if key_from_text(m.t("Switch key")).as_deref() != Some(key) || !game.native_playing() || !inventory_idle(game) {
        return;
    }
    let sets: Vec<&str> = m.t("Switch sets").split(',').map(str::trim).filter(|t| !t.is_empty()).collect();
    let worn = game.armor.iter().flatten().next().map(|s| armor_material(&s.item).to_owned());
    let at = worn.as_deref().and_then(|w| sets.iter().position(|s| *s == w));
    let next = at.map_or(0, |i| i + 1);
    let complete = |set: &str| {
        ["head", "chest", "legs", "feet"].iter().all(|slot| {
            game.armor.iter().chain(game.inventory.iter().take(36)).flatten().any(|st| {
                armor_material(&st.item) == set && game.res.items().get(&st.item).is_some_and(|i| i.equip_slot.as_deref() == Some(*slot))
            })
        })
    };
    match (0..sets.len()).map(|k| sets[(next + k) % sets.len()]).find(|set| Some(*set) != worn.as_deref() && complete(set)) {
        Some(set) => with(|s| s.armor_set = Some(set.to_owned())),
        None => say(game, "No other full armour set from Switch sets."),
    }
}

// Auto Armor key: turns Auto Armor on or off, as its module's key did before it joined Inventory Manager.
fn auto_armor_key(game: &mut Game<'_>, key: &str) {
    let bound = with(|s| s.module("Inventory Manager").map(|m| (key_from_text(m.t("Auto Armor key")), m.b("Auto Armor"))));
    let Some((Some(bound), on)) = bound else {
        return;
    };
    if bound != key || gui_open() || !game.native_playing() {
        return;
    }
    set_setting(game, "inventorymanager.autoarmor", if on { "false" } else { "true" });
    if chat_lines("Toggle messages") {
        say(game, if on { "Auto Armor off" } else { "Auto Armor on" });
    }
}

pub(super) fn auto_armor(game: &mut Game<'_>, m: &Module) {
    // Inventory Manager's Slots mode wears your armour itself (inventory_slots.rs).
    if m.on && m.p("Mode") == "Slots" {
        return;
    }
    // One inventory step at a time: Inventory Manager's last one settles first.
    if super::sunset_player::inventory_stepping(game.ticks) {
        return;
    }
    let set = with(|s| s.armor_set.clone());
    // Inventory open: only with your inventory screen up; Key: only while Armor key is held. A set from Switch key
    // goes on anyway.
    let allowed = set.is_some() || match m.p("Armor mode") {
        "Inventory open" => game.screen == Screen::Inventory,
        "Key" => super::sunset_util::setting_key_down(game, m, "Armor key"),
        _ => true,
    };
    // Nothing while the cursor holds an item (yours, or one Inventory Manager is putting back): a click would move it.
    if !allowed || !inventory_idle(game) || game.carried.is_some() {
        return;
    }
    // Avoid cursed: never a piece with Curse of Binding or Vanishing.
    let cursed = |st: &horizon_client::items::ItemStack| {
        m.b("Avoid cursed") && st.enchantments().iter().any(|(id, _)| id.ends_with("binding_curse") || id.ends_with("vanishing_curse"))
    };
    if with(|s| {
        s.armor_wait = s.armor_wait.saturating_sub(1);
        s.armor_wait > 0
    }) {
        return;
    }
    const SLOTS: [&str; 4] = ["head", "chest", "legs", "feet"];
    // Pieces are ranked by inventory_plan's armour evaluator (vanilla's damage reduction with Protection), the same one
    // Inventory Manager keeps armour by, so the two never disagree.
    let value = |game: &Game<'_>, s: &horizon_client::items::ItemStack| super::sunset_inventory_plan::armor_score(&super::sunset_player::plan_item(game, s));
    for (a, slot_name) in SLOTS.iter().enumerate() {
        // A worn elytra is Chest Swap's to change, not Auto Armor's.
        if a == 1 && game.armor[a].as_ref().is_some_and(|s| s.item.ends_with("elytra")) && set.is_none() {
            continue;
        }
        let worn = game.armor[a].as_ref().map_or(0.0, |s| value(game, s));
        let mut best: Option<(usize, f32)> = None;
        for i in 0..36 {
            let Some(st) = game.inventory.get(i).and_then(|s| s.as_ref()) else {
                continue;
            };
            if st.item.ends_with("elytra") || cursed(st) {
                continue;
            }
            let fits = game
                .res
                .items()
                .get(&st.item)
                .is_some_and(|inf| inf.equip_slot.as_deref() == Some(*slot_name));
            let score = value(game, st);
            let wanted = match set.as_deref() {
                Some(set) => armor_material(&st.item) == set && game.armor[a].as_ref().is_none_or(|w| armor_material(&w.item) != set),
                // Better by more than a hair: no swapping back and forth between near-equal pieces.
                None => score > worn + 0.005,
            };
            if fits && wanted && best.is_none_or(|(_, b)| score > b) {
                best = Some((i, score));
            }
        }
        if let Some((i, _)) = best {
            // A click while moving is what Grim's MultiActionsC flags: the piece waits until you stand still.
            if !super::remote::sunset_combat_remote::quiet(game) {
                return;
            }
            // Past GUI Move's GrimAC queue (it would hold the click until the inventory closes); you stand still here.
            super::sunset_gui_move::direct(|| wear(game, i, a));
            with(|s| s.armor_wait = m.n("Armor delay (ticks)") as u32);
            // Inventory Manager waits for the server's answer to this too.
            let settle = super::sunset_inventory_exec::settle_ticks(super::remote::sunset_combat_remote::latency(game), 0);
            super::sunset_player::inventory_hold(game.ticks + settle);
            return;
        }
    }
}

// Swaps the chestplate and the elytra once the server has received idle input.
// Grim checks the last PlayerInput and sprint state on each inventory click.
pub(super) fn chest_swap(game: &mut Game<'_>) -> bool {
    let moving_now = [KeyCode::KeyW, KeyCode::KeyA, KeyCode::KeyS, KeyCode::KeyD, KeyCode::Space, KeyCode::ShiftLeft]
        .into_iter()
        .any(|key| game.keys.contains(&key) || game.physical_keys.contains(&key));
    if !inventory_idle(game)
        || moving_now
        || super::sunset_combat_wire::sent_input(game) & 0x3f != 0
        || super::sunset_combat_wire::sent_sprinting(game)
        || game.player.as_ref().is_some_and(|p| p.sprinting || p.fall_flying)
    {
        return false;
    }
    let wearing_elytra = game.armor[1].as_ref().is_some_and(|s| s.item.ends_with("elytra"));
    let found = (0..36).find(|&i| {
        game.inventory.get(i).and_then(|s| s.as_ref()).is_some_and(|s| {
            if wearing_elytra {
                !s.item.ends_with("elytra")
                    && game.res.items().get(&s.item).is_some_and(|inf| inf.equip_slot.as_deref() == Some("chest"))
            } else {
                s.item.ends_with("elytra")
            }
        })
    });
    match found {
        Some(i) => wear(game, i, 1),
        None => say(game, if wearing_elytra { "No chestplate in your inventory." } else { "No elytra in your inventory." }),
    }
    true
}

pub(super) fn auto_replenish(game: &mut Game<'_>, m: &Module) {
    use horizon_client::menu::Input::QuickMove;
    if !inventory_idle(game) {
        return;
    }
    if with(|s| {
        s.replenish_wait = s.replenish_wait.saturating_sub(1);
        s.replenish_wait > 0
    }) {
        return;
    }
    let locked = super::sunset_loadouts::locked_slots();
    for h in (0..9).filter(|&h| !locked[h]) {
        let Some(st) = game.inventory.get(h).and_then(|s| s.as_ref()) else {
            continue;
        };
        let max = game.res.items().get(&st.item).map_or(64, |i| i.max_stack);
        if max <= 1 || st.count >= max || f64::from(st.count) > m.n("Threshold") {
            continue;
        }
        let item = st.item.clone();
        let source = (9..36).find(|&i| game.inventory.get(i).and_then(|s| s.as_ref()).is_some_and(|s| s.item == item));
        if let Some(src) = source {
            // Shift-click from the main inventory fills the hotbar stack first.
            if menu_click(game, &[(src, QuickMove)]) {
                with(|s| s.replenish_wait = m.n("Delay (ticks)") as u32);
            }
            return;
        }
    }
}

// Auto Tool (Sunset's): while you break a block, the hotbar tool with the best score for it (Sunset's getScore:
// a tool that is right for the block's drops, by its speed and enchantments), after Switch delay; Switch back when you
// let go; Anti break lets go of a tool about to break. Only below you: only for the block under you. From inventory:
// with no better tool in the hotbar, the best in the main inventory swapped into your hand (one swap click), and
// swapped back when you let go or look off the block.
// It runs at the start of a tick, before the game's dig packets and the move packet, as a hotbar key does: a slot
// change after the move packet is what Grim's Post check flags, and one after a hit in the same tick its PacketOrderE
// (`busy`: a hit or a slot change already went this tick; the change waits a tick). The swap clicks go only while the
// server knows you stand still (no movement keys, sneak or sprint sent: Grim's MultiActionsC), each with the
// inventory's close after it, as the game sends them.
pub(super) fn auto_tool(game: &mut Game<'_>, m: &Module, busy: bool) {
    use winit::event::MouseButton;
    let below = super::sunset_util::block_pos(game).map(|[x, y, z]| [x, y - 1, z]);
    let on_block = !m.b("Only below you") || game.pick().is_some_and(|hit| Some(hit.pos) == below);
    let down = game.native_playing() && (game.physical_buttons.contains(&MouseButton::Left) || game.left) && !gui_open() && on_block;
    if !down || game.selected != with(|s| s.tool_pulled.map_or(game.selected, |p| p.1)) {
        tool_unpull(game);
    }
    if !down {
        let back = with(|s| {
            s.tool_wait = None;
            if busy && m.b("Switch back") { None } else { s.tool_back.take() }
        });
        if let Some(back) = back.filter(|_| m.b("Switch back")) {
            hold(game, back);
        }
        return;
    }
    if let Some((slot, left)) = with(|s| s.tool_wait) {
        if left > 1 {
            with(|s| s.tool_wait = Some((slot, left - 1)));
        } else if !busy {
            hold(game, slot);
            with(|s| s.tool_wait = None);
        }
    }
    if game.creative || game.remote.is_none() || game.entity_targeted() {
        return;
    }
    let Some(hit) = game.pick() else {
        return;
    };
    let facts = game.res.facts().get(game.world.block(hit.pos[0], hit.pos[1], hit.pos[2]));
    let block = (facts.name.clone(), facts.requires_tool);
    let list = if m.p("List mode") == "Whitelist" { m.t("Whitelist") } else { m.t("Blacklist") };
    let allowed = |stack: Option<&horizon_client::items::ItemStack>| {
        let listed = stack.is_some_and(|s| super::sunset_util::listed(list, &s.item));
        listed == (m.p("List mode") == "Whitelist")
    };
    let stack = |i: usize| game.inventory.get(i).and_then(|s| s.as_ref());
    let best = (0..9)
        .filter(|&i| allowed(stack(i)))
        .map(|i| (i, tool_score(game, m, stack(i), &block)))
        .filter(|(_, score)| *score >= 0.0)
        .fold(None, |b: Option<(usize, f64)>, (i, v)| if b.is_none_or(|b| v > b.1) { Some((i, v)) } else { b });
    let current = stack(game.selected);
    let locked = super::sunset_loadouts::locked;
    let still = super::remote::sunset_combat_remote::quiet(game);
    let pull = (m.b("From inventory") && still && with(|s| s.tool_pulled.is_none()) && inventory_idle(game) && !locked(game.selected))
        .then(|| {
            let held = tool_score(game, m, current, &block).max(best.map_or(-1.0, |b| b.1));
            (9..36)
                .filter(|&i| !locked(i) && allowed(stack(i)))
                .map(|i| (i, tool_score(game, m, stack(i), &block)))
                .filter(|&(_, score)| score > held)
                .fold(None, |b: Option<(usize, f64)>, (i, v)| if b.is_none_or(|b| v > b.1) { Some((i, v)) } else { b })
        })
        .flatten();
    if let Some((from, _)) = pull {
        let to = game.selected;
        if game.remote_menu_ops(&[(Some(from), to as i32, horizon_client::menu::Input::Swap)]) {
            game.close_container();
            with(|s| s.tool_pulled = Some((from, to)));
        }
        return;
    }
    let switch = best
        .filter(|&(slot, score)| slot != game.selected && (score > tool_score(game, m, current, &block) || tool_spent(game, m, current)))
        .map(|(slot, _)| slot);
    if let Some(slot) = switch {
        let selected = game.selected;
        with(|s| {
            s.tool_back.get_or_insert(selected);
        });
        // Switch delay counts from when the tool is first wanted: the wait is set once, not again each tick.
        match m.n("Switch delay") as u32 {
            0 if !busy => hold(game, slot),
            0 => {}
            delay => with(|s| {
                if s.tool_wait.is_none_or(|(waiting, _)| waiting != slot) {
                    s.tool_wait = Some((slot, delay));
                }
            }),
        }
    }
    let held = game.inventory.get(game.selected).and_then(|s| s.as_ref());
    if tool_spent(game, m, held) {
        let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Left, false);
    }
}

// From inventory's tool goes back where it came from: one swap click and the inventory's close, once the server knows
// you stand still (else it waits).
fn tool_unpull(game: &mut Game<'_>) {
    let Some((from, to)) = with(|s| s.tool_pulled) else {
        return;
    };
    if !inventory_idle(game) || !super::remote::sunset_combat_remote::quiet(game) {
        return;
    }
    if game.remote_menu_ops(&[(Some(from), to as i32, horizon_client::menu::Input::Swap)]) {
        game.close_container();
    }
    with(|s| s.tool_pulled = None);
}

// Auto Tool turned off: a tool it pulled from the inventory still goes back, nothing else waits.
pub(super) fn auto_tool_off(game: &mut Game<'_>) {
    with(|s| {
        s.tool_wait = None;
        s.tool_back = None;
    });
    tool_unpull(game);
}

// Anti break: a tool worn down to its last Anti break percentage.
fn tool_spent(game: &Game<'_>, m: &Module, stack: Option<&horizon_client::items::ItemStack>) -> bool {
    let Some(s) = stack else {
        return false;
    };
    let max = game.res.items().get(&s.item).map_or(0, |i| i.max_damage);
    m.b("Anti break") && max > 0 && f64::from(max - s.damage.min(max)) < f64::from(max) * m.n("Anti break percentage") / 100.0
}

// Sunset's AutoTool.getScore, on the game's own destroy speed: any item (a sword or shears on a cobweb, a sword on
// bamboo, a pickaxe on stone) scores by how fast it breaks the block (its name, and whether it needs the right tool to
// drop: a wrong tool then breaks it at a third of its speed), the right tool first on a tie; -1 for one no faster
// than the bare hand.
fn tool_score(game: &Game<'_>, m: &Module, stack: Option<&horizon_client::items::ItemStack>, (block, requires_tool): &(std::sync::Arc<str>, bool)) -> f64 {
    let Some(s) = stack.filter(|s| !tool_spent(game, m, Some(s))) else {
        return -1.0;
    };
    let items = game.res.items();
    let short = super::sunset_util::short(block);
    let correct = items.correct_for_drops(stack, block);
    let speed = f64::from(items.mining_speed(stack, block)) * if *requires_tool && !correct { 0.3 } else { 1.0 };
    if speed <= 1.0 && !correct {
        return -1.0;
    }
    let level = |e: &str| f64::from(s.enchantment_level(e));
    if m.b("Silk touch for ender chest") && short == "ender_chest" && level("minecraft:silk_touch") == 0.0 {
        return -1.0;
    }
    let fortunable = (short.ends_with("_ore") && short != "ancient_debris") || matches!(short, "wheat" | "carrots" | "potatoes" | "beetroots" | "torchflower_crop");
    if m.b("Fortune for ores and crops") && fortunable && level("minecraft:fortune") == 0.0 {
        return -1.0;
    }
    let preferred = match m.p("Prefer") {
        "Fortune" => level("minecraft:fortune"),
        "Silk touch" => level("minecraft:silk_touch"),
        _ => 0.0,
    };
    speed * 1000.0 + f64::from(u8::from(correct)) * 100.0 + level("minecraft:unbreaking") + level("minecraft:efficiency") + level("minecraft:mending") + preferred
}

// Middle click: throws or uses the chosen item from the hotbar, and switches
// back a few ticks later.
pub(super) fn middle_click(game: &mut Game<'_>) {
    let Some(m) = with(|s| s.module("Middle Click Extra").filter(|m| m.on).cloned()) else {
        return;
    };
    if m.p("Item") == "Friend" {
        let player = game.mob_hit().map(|(i, ..)| &game.mobs[i]).filter(|mob| kind_of(mob) == Kind::Player).map(|mob| mob.id);
        if let Some(name) = player.and_then(|id| game.remote_player_name(id)).map(str::to_owned) {
            let now = with(|s| s.flip_friend(&name));
            save(game);
            super::sunset_util::report(game, &format!("{name} {}", if now { "is a friend." } else { "is no longer a friend." }));
        }
        return;
    }
    let want = match m.p("Item") {
        "Pearl" => "ender_pearl",
        "Rocket" => "firework_rocket",
        _ => "experience_bottle",
    };
    let slot = (0..9).find(|&i| game.inventory.get(i).and_then(|s| s.as_ref()).is_some_and(|s| s.item.ends_with(want)));
    if let Some(slot) = slot {
        with(|s| s.mc_use = Some((slot, want)));
    }
}

// Middle Click Extra's use and its slot back, at the start of a tick as a hotbar key and a right click are: the slot,
// then the use, before the tick's move packet (a slot change or use after it is what Grim's Post check flags); the slot
// goes back three ticks later, never in the tick of the use (Grim's PacketOrderE). `busy`: a hit or a slot change went
// already this tick; both wait.
pub(super) fn middle_click_tick(game: &mut Game<'_>, busy: bool) -> bool {
    use winit::event::MouseButton;
    if busy {
        return false;
    }
    if let Some((slot, want)) = with(|s| s.mc_use.take()) {
        if !game.inventory.get(slot).and_then(|s| s.as_ref()).is_some_and(|s| s.item.ends_with(want)) {
            return false;
        }
        let before = game.selected;
        hold(game, slot);
        let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, true);
        let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, false);
        with(|s| {
            if s.mc_back.is_none() {
                s.mc_back = Some((before, 3));
            }
        });
        return true;
    }
    match with(|s| s.mc_back) {
        Some((back, wait)) if wait <= 1 => {
            with(|s| s.mc_back = None);
            let moved = game.selected != back;
            hold(game, back);
            moved
        }
        Some((back, wait)) => {
            with(|s| s.mc_back = Some((back, wait - 1)));
            false
        }
        None => false,
    }
}

// Runtime part (see runtime.rs): the menu on the Mods page, toggling modules, keys and binds.

use super::Game;
use super::sunset_bind_state::Held;
use std::sync::atomic::Ordering;
use winit::keyboard::KeyCode;
use super::sunset::*;

// ---------------------------------------------------------------- the menu

// Sunset's row in Options > Mods; none after Panic, when the list is made again (`unlist` took the one it had).
pub(super) fn listed(mods: &mut Vec<super::native_hooks::NativeMod>) {
    if !running() { return; }
    super::sunset_session::sweep();
    mods.push(super::native_hooks::NativeMod {
        id: ID.into(),
        title: format!("{NAME} {VERSION}"),
        description: DESCRIPTION.into(),
        keys: vec![
            [MENU_KEY.into(), "Open Sunset menu".into(), MENU_DEFAULT.into()],
            [MENU2_KEY.into(), "Open Sunset menu (2nd key)".into(), MENU2_DEFAULT.into()],
        ],
    });
}

pub(super) fn mod_index(game: &Game<'_>) -> Option<usize> {
    game.settings.mods.installed.iter().position(|m| m.id == ID)
}

pub(super) fn refresh(game: &mut Game<'_>) {
    if let Some(i) = mod_index(game) {
        game.native_settings_refresh(i);
    }
}

// Either of the two keys that open the click GUI.
pub(super) fn is_menu_key(game: &Game<'_>, key: &str) -> bool {
    key == game.native_mod_key(ID, MENU_KEY, MENU_DEFAULT) || key == game.native_mod_key(ID, MENU2_KEY, MENU2_DEFAULT)
}

pub(super) fn open_menu(game: &mut Game<'_>) {
    if !running() { return; }
    release_binds();
    let Some(i) = mod_index(game) else {
        say(game, "Turn Sunset on in Options > Mods first.");
        return;
    };
    with(|s| {
        s.page = Page::Main;
        s.binding = None;
    });
    game.open_options_at(false, horizon_client::options_ui::Page::NativeMod(i));
    game.native_settings_refresh(i);
}

pub(super) fn buttons(game: &Game<'_>, out: &mut Vec<String>) {
    if !running() { return; }
    ensure_loaded(game);
    with(|s| match s.page {
        Page::Main => {
            let listed = s.listed();
            for c in CATEGORIES {
                let all: Vec<&Module> = s.modules.iter().filter(|m| m.category == c && listed(m)).collect();
                let on = all.iter().filter(|m| m.on).count();
                out.push(format!("{} ({on} of {} on)", c.label(), all.len()));
            }
            out.push(format!("Friends: {}", if s.friends.is_empty() { "none".into() } else { s.friends.join(", ") }));
            out.push("Type .help in chat for commands".into());
        }
        Page::Category(c) => {
            out.push("< Back".into());
            let listed = s.listed();
            for m in s.modules.iter().filter(|m| m.category == c && listed(m)) {
                out.push(format!("{}: {}", m.name, on_off(m.on)));
            }
        }
        Page::Module(i) => {
            let m = &s.modules[i];
            out.push(format!("< Back to {}", m.category.label()));
            out.push(format!("{}: {}", m.name, on_off(m.on)));
            if s.binding == Some(i) {
                out.push("Keybind: > press a key (Backspace: none) <".into());
            } else {
                out.push(format!("Keybind: {}", key_label(m.key.as_deref())));
            }
            for setting in &m.settings {
                out.push(setting.shown());
            }
            let mut about = m.about.to_owned();
            if m.settings.iter().any(|s| matches!(s.value, Value::Num { .. })) {
                about.push_str(" Shift-click lowers a number.");
            }
            out.push(about);
        }
    });
}

pub(super) fn click(game: &mut Game<'_>, button: usize) {
    if !running() { return; }
    ensure_loaded(game);
    let shift = game.modifiers.shift_key();
    let mut toggled = None;
    let changed = with(|s| match s.page {
        Page::Main => {
            if let Some(&c) = CATEGORIES.get(button) {
                s.page = Page::Category(c);
            }
            false
        }
        Page::Category(c) => {
            if button == 0 {
                s.page = Page::Main;
                return false;
            }
            let listed = s.listed();
            let idx: Vec<usize> = (0..s.modules.len()).filter(|&i| s.modules[i].category == c && listed(&s.modules[i])).collect();
            if let Some(&i) = idx.get(button - 1) {
                s.page = Page::Module(i);
            }
            false
        }
        Page::Module(i) => match button {
            0 => {
                s.binding = None;
                s.page = Page::Category(s.modules[i].category);
                false
            }
            1 => {
                toggled = Some(i);
                false
            }
            2 => {
                s.binding = if s.binding == Some(i) { None } else { Some(i) };
                false
            }
            b => match s.modules[i].settings.get_mut(b - 3) {
                Some(setting) => {
                    setting.click(shift);
                    true
                }
                None => false,
            },
        },
    });
    if let Some(i) = toggled {
        toggle(game, i, false);
    } else if changed {
        save(game);
    }
}

pub(super) fn toggle(game: &mut Game<'_>, i: usize, announce: bool) {
    if !running() { return; }
    if with(|s| s.modules[i].name == "Panic" && !s.modules[i].on) {
        panic_off(game);
        return;
    }
    let (name, on) = with(|s| {
        // Turned on or off by hand: a Hold bind no longer has it.
        s.inputs.take_where(|held| held.module == i);
        let m = &mut s.modules[i];
        m.on = !m.on;
        (m.name, m.on)
    });
    switched_effects(game, name, on);
    save(game);
    if announce && name != super::sunset_debug::NAME {
        say(game, &format!("{name} {}", if on { "on" } else { "off" }));
    }
}

// What a module going on or off does besides its switch: by hand (toggle) or as a profile or preset loads.
pub(super) fn switched_effects(game: &mut Game<'_>, name: &'static str, on: bool) {
    if name == "Panic" {
        return;
    }
    super::sunset_combat_macros::toggled(game, name, on);
    super::sunset_combat_inventory::toggled(game, name);
    super::sunset_pvp_bot::toggled(name);
    super::sunset_packet_mine::toggled(game, name, on);
    if name == "Friend Guard" {
        super::sunset_melee::reset_friend_feedback();
    }
    if !on {
        match name {
            "Scaffold" => {
                with(|s| s.scaffold_stack = None);
                restore_scaffold_rotation(game);
                legit_sneak(game, false);
                super::sunset_scaffold_bridge::stop(game);
                super::sunset_scaffold_telly::stop(game);
            }
            "Speed" => {
                watchdog_stop(game, true);
                with(|s| { s.strafe = Strafe::default(); s.bhop.reset(); s.ncp.reset(); s.knockback_ticks = 0; });
                with(|s| s.legacy_recovery = Default::default());
                horizon_client::motion::sunset_motion::set_across(None);
                horizon_client::motion::sunset_motion::set_up(None);
            },
            "Velocity" => with(|s| { s.velocity = None; s.blast = [0.0; 3]; }),
            "Crystal Aura" => super::sunset_crystal_aura::disabled(game),
            "Cart" => super::sunset_cart::reset(game),
            "Kill Aura" => {
                super::sunset_hands::stop_kill_aura_block(game);
                let swap_back = with(|s| s.module("Kill Aura").is_some_and(|m| m.b("Swap back")));
                super::sunset_aura::disabled(game, swap_back);
            }
            "Anchor Aura" => super::sunset_anchor_aura::disabled(game),
            "No Slow" => {
                horizon_client::input::sunset_flags::NO_SLOW.store(false, Ordering::Relaxed);
                horizon_client::motion::sunset_motion::set_no_slow_skip(false);
                horizon_client::motion::sunset_motion::set_no_slow_grim(false);
            },
            "Server Scan" => super::sunset_server_scan::disabled(),
            _ => {},
        }
    }
}

pub(super) fn take_scaffold_rotation(saved: &mut Option<(f32, f32)>) -> Option<(f32, f32)> {
    saved.take()
}

pub(super) fn restore_scaffold_rotation(game: &mut Game<'_>) {
    if let Some((yaw, pitch)) = with(|s| take_scaffold_rotation(&mut s.scaffold_rotation)) {
        game.yaw = yaw;
        game.pitch = pitch;
    }
}

// ---------------------------------------------------------------- keys

// Modules Hold binds had on, back as they were (left off if something turned them off meanwhile).
fn restore_holds(s: &mut State, held: Vec<Held>) {
    if held.is_empty() {
        return;
    }
    for h in held {
        if let Some(m) = s.modules.get_mut(h.module)
            && m.on
        {
            m.on = h.previous;
        }
    }
    sync_flags(s);
}

// Holds whose module went off, or whose bind or Bind mode changed, end.
pub(super) fn release_changed_binds(s: &mut State) {
    let modules = &s.modules;
    let held = s.inputs.take_where(|h| {
        modules
            .get(h.module)
            .is_none_or(|m| !m.on || m.key.as_deref() != Some(h.key.as_str()) || m.p("Bind mode") != "Hold")
    });
    restore_holds(s, held);
}

// A screen, the menu or another window has the input: every hold ends.
pub(super) fn release_binds() {
    with(|s| {
        let held = s.inputs.suspend();
        restore_holds(s, held);
    });
}

pub(super) fn set_bind(s: &mut State, module: usize, key: Option<String>) {
    let held = s.inputs.take_where(|h| h.module == module);
    restore_holds(s, held);
    s.modules[module].key = key;
}

// Each tick, whatever the screen: keys let go of where no release came (from what is physically down), and no holds
// while the menu or a screen has the input (another window taking it is the window's Focused event, in bind_event).
pub(super) fn sync_binds(game: &Game<'_>) {
    if !game.native_window() {
        return;
    }
    with(|s| {
        let held = s.inputs.missing(|name| {
            game.physical_keys.iter().any(|k| horizon_client::keybinds::key_name(*k) == Some(name))
                || game.physical_buttons.iter().any(|b| horizon_client::keybinds::mouse_name(*b) == name)
        });
        restore_holds(s, held);
        release_changed_binds(s);
        if !game.native_on(ID) || game.player.is_none() || !game.native_playing() || s.gui.open {
            let held = s.inputs.suspend();
            restore_holds(s, held);
        }
    });
}

// The window's presses and releases before any screen has them: a release a screen swallows still ends its hold, a
// key pressed in the menu or by the window coming back into focus is no bind press, and lost focus ends every hold.
pub(super) fn bind_event(event: &winit::event::WindowEvent) {
    use winit::event::{ElementState, WindowEvent};
    use winit::keyboard::{Key, NamedKey, PhysicalKey};
    if matches!(event, WindowEvent::Focused(false) | WindowEvent::CloseRequested | WindowEvent::Destroyed) {
        release_binds();
    }
    let (name, pressed, synthetic) = match event {
        WindowEvent::KeyboardInput { event, is_synthetic, .. } => {
            // Escape and Caps Lock by their meaning, as Horizon's keymap takes them.
            let code = match &event.logical_key {
                Key::Named(NamedKey::Escape) => KeyCode::Escape,
                Key::Named(NamedKey::CapsLock) => KeyCode::CapsLock,
                _ => match event.physical_key {
                    PhysicalKey::Code(code) => code,
                    PhysicalKey::Unidentified(_) => return,
                },
            };
            let Some(name) = horizon_client::keybinds::key_name(code) else {
                return;
            };
            (name.to_owned(), event.state == ElementState::Pressed, *is_synthetic)
        }
        WindowEvent::MouseInput { state, button, .. } => (horizon_client::keybinds::mouse_name(*button), *state == ElementState::Pressed, false),
        _ => return,
    };
    with(|s| {
        if !pressed {
            let held = s.inputs.release(&name);
            restore_holds(s, held);
            return;
        }
        if s.gui.open || synthetic {
            s.inputs.block(&name);
            let held = s.inputs.suspend();
            restore_holds(s, held);
        }
        if synthetic {
            s.inputs.synthetic(&name);
        }
    });
}

pub(super) fn key(game: &mut Game<'_>, key: &str, pressed: bool) {
    finish_shutdown(game);
    if !running() { return; }
    if !game.native_window() {
        return;
    }
    ensure_loaded(game);
    if pressed && game.native_on(ID) && game.native_playing() && !gui_open()
        && with(|s| !s.inputs.is_synthetic(key) && s.module("Panic").is_some_and(|m| m.key.as_deref() == Some(key)))
        && with(|s| s.inputs.press(key))
    {
        panic_off(game);
        return;
    }
    if game.native_on(ID) {
        super::sunset_api::key(game, key, pressed);
    }
    if !running() { return; }
    if pressed {
        super::agent::sunset_goto::key(game, key);
    }
    super::sunset_melee::key(game, key, pressed);
    super::sunset_swap_keys::key(game, key, pressed);
    super::sunset_combat::web_key(game, key, pressed);
    super::sunset_duel::key(game, key, pressed);
    super::sunset_cart::key(game, key, pressed);
    super::sunset_throws::key(game, key, pressed);
    if pressed {
        armor_switch(game, key);
    }
    super::sunset_refill::key(key, pressed);
    super::sunset_takeoff::key(key, pressed);
    if !pressed {
        with(|s| {
            let held = s.inputs.release(key);
            restore_holds(s, held);
        });
        return;
    }
    if !game.native_on(ID) {
        release_binds();
        return;
    }
    if with(|s| s.inputs.is_synthetic(key)) {
        return;
    }
    ensure_loaded(game);
    if gui_open() {
        gui_key(game, key);
        return;
    }
    if let Some(i) = with(|s| s.binding) {
        let chosen = match key {
            "key.keyboard.escape" => {
                with(|s| s.binding = None);
                refresh(game);
                return;
            }
            "key.keyboard.backspace" | "key.keyboard.delete" => None,
            k => Some(k.to_owned()),
        };
        with(|s| {
            set_bind(s, i, chosen);
            s.binding = None;
        });
        save(game);
        refresh(game);
        return;
    }
    if !game.native_playing() || game.player.is_none() {
        with(|s| s.inputs.block(key));
        release_binds();
        return;
    }
    // The chat key opens a text screen: a bind on the same key is not pressed by it.
    if !is_menu_key(game, key) && (key == game.settings.keys.get("key.chat") || key == game.settings.keys.get("key.command")) {
        with(|s| s.inputs.block(key));
        release_binds();
        return;
    }
    // A fresh press only: not one a screen or the menu had when it went down.
    if !with(|s| s.inputs.press(key)) {
        return;
    }
    if is_menu_key(game, key) {
        open_gui(game);
        return;
    }
    if key == "key.mouse.middle" && with(|s| s.is_on("Middle Click Extra")) {
        middle_click(game);
    }
    if key == "key.mouse.right" {
        super::sunset_player::right_click(game);
    }
    let bound: Vec<usize> = with(|s| {
        (0..s.modules.len())
            .filter(|&i| s.modules[i].key.as_deref() == Some(key))
            .collect()
    });
    for i in bound {
        if !running() { break; }
        if with(|s| s.modules[i].p("Bind mode") == "Hold") {
            // On while the key is down, then as it was.
            with(|s| {
                let previous = s.modules[i].on;
                s.inputs.hold(i, key, previous);
                s.modules[i].on = true;
                sync_flags(s);
            });
        } else {
            toggle(game, i, chat_lines("Toggle messages"));
        }
    }
    // Air Jump: the jump key in mid-air jumps again.
    if key == "key.keyboard.space" && with(|s| s.is_on("Air Jump")) {
        if let Some(p) = game.player.as_mut()
            && !p.ground.on_ground
            && !p.flying
        {
            p.velocity.y = 0.42;
            p.fall_distance = 0.0;
        }
        remember_velocity(game);
    }
}

// Runtime part (see runtime.rs): modules, their categories and settings, and what each setting shows.

use super::sunset::*;

// ---------------------------------------------------------------- modules

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Category {
    Combat,
    Movement,
    Player,
    Render,
    World,
    // Not cheats: the client's own (profiles, sorting, which extra modules the menu lists).
    Client,
}

pub(super) const CATEGORIES: [Category; 6] = [
    Category::Combat,
    Category::Movement,
    Category::Player,
    Category::Render,
    Category::World,
    Category::Client,
];

impl Category {
    pub(super) fn label(self) -> &'static str {
        match self {
            Category::Combat => "Combat",
            Category::Movement => "Movement",
            Category::Player => "Player",
            Category::Render => "Render",
            Category::World => "World",
            Category::Client => "Client",
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub(super) enum Value {
    Bool(bool),
    Num { v: f64, min: f64, max: f64, step: f64 },
    Pick { i: usize, of: &'static [&'static str] },
    // A comma separated list (blocks, items, entities): set with `.set`.
    Text(String),
}

#[derive(Clone, Debug, PartialEq)]
pub(super) struct Setting {
    pub(crate) name: &'static str,
    pub(crate) value: Value,
}

impl Setting {
    pub(super) fn shown(&self) -> String {
        format!("{}: {}", self.name, self.value_text())
    }
    pub(super) fn value_text(&self) -> String {
        match &self.value {
            Value::Bool(b) => on_off(*b).to_owned(),
            Value::Num { v, .. } if self.all_loaded(*v) => "All".to_owned(),
            Value::Num { v, .. } => num(*v),
            Value::Pick { i, of } => of[*i].to_owned(),
            Value::Text(t) if t.is_empty() => "(empty)".to_owned(),
            Value::Text(t) => t.chars().map(|c| if c.is_control() { '?' } else { c }).collect(),
        }
    }
    // ESP's, Tracers' and Nametags' Range at 0: everything the server sent, however far.
    fn all_loaded(&self, v: f64) -> bool {
        self.name == "Range" && v == 0.0 && matches!(self.value, Value::Num { min, max, .. } if min == 0.0 && max == ALL_RANGE_MAX)
    }
    // As the config and profiles keep it: numbers to six places (HUD positions step by 0.001, frictions by 0.005;
    // two places moved them a little at every save), text on one line.
    pub(super) fn stored(&self) -> String {
        match &self.value {
            Value::Bool(b) => b.to_string(),
            Value::Num { v, .. } => exact(*v),
            Value::Pick { i, of } => of[*i].to_owned(),
            Value::Text(t) => one_line(t),
        }
    }
    // A click: a switch flips, a number goes up a step (down with Shift) and
    // wraps at its ends, a choice moves to the next.
    pub(super) fn click(&mut self, down: bool) {
        match &mut self.value {
            Value::Bool(b) => *b = !*b,
            Value::Num { v, min, max, step } => {
                let mut n = if down { *v - *step } else { *v + *step };
                if n > *max + 1e-9 {
                    n = *min;
                } else if n < *min - 1e-9 {
                    n = *max;
                }
                *v = round_to(n, *step);
            }
            Value::Text(_) => {}
            Value::Pick { i, of } => {
                *i = if down {
                    (*i + of.len() - 1) % of.len()
                } else {
                    (*i + 1) % of.len()
                };
            }
        }
    }
    // From text (`.set`, the config): whether it was understood.
    pub(super) fn parse(&mut self, text: &str) -> bool {
        let t = text.trim();
        match &mut self.value {
            Value::Bool(b) => match t.to_ascii_lowercase().as_str() {
                "true" | "on" | "yes" | "1" => *b = true,
                "false" | "off" | "no" | "0" => *b = false,
                "toggle" => *b = !*b,
                _ => return false,
            },
            Value::Num { v, min, max, .. } => match t.parse::<f64>() {
                Ok(n) if n.is_finite() => *v = n.clamp(*min, *max),
                _ => return false,
            },
            Value::Pick { i, of } => match of.iter().position(|o| norm(o) == norm(t)) {
                Some(p) => *i = p,
                None => return false,
            },
            Value::Text(v) => *v = one_line(t),
        }
        true
    }
}

// A number as the config keeps it: up to six places, no trailing zeros.
pub(super) fn exact(v: f64) -> String {
    let s = format!("{v:.6}");
    let s = s.trim_end_matches('0').trim_end_matches('.');
    if s == "-0" { "0".into() } else { s.into() }
}

// Text with its line breaks and other control characters made spaces: a value is one line of the config.
fn one_line(t: &str) -> String {
    if t.chars().any(char::is_control) { t.chars().map(|c| if c.is_control() { ' ' } else { c }).collect() } else { t.to_owned() }
}

#[derive(Clone, Debug, PartialEq)]
pub(super) struct Module {
    pub(crate) name: &'static str,
    pub(crate) category: Category,
    pub(crate) about: &'static str,
    pub(crate) on: bool,
    pub(crate) key: Option<String>,
    pub(crate) settings: Vec<Setting>,
    // Its settings' sections, for the menu: where each starts (a setting's index) and its title. None for most modules.
    pub(crate) groups: Vec<(usize, &'static str)>,
}

impl Module {
    pub(super) fn new(name: &'static str, category: Category, about: &'static str) -> Self {
        Self {
            name,
            category,
            about,
            on: false,
            key: None,
            settings: Vec::new(),
            groups: Vec::new(),
        }
    }
    // The settings after this, up to the next group, are a section of the menu under `title`. Only the menu reads it:
    // saved settings go by name.
    pub(super) fn group(mut self, title: &'static str) -> Self {
        self.groups.push((self.settings.len(), title));
        self
    }
    // The section a setting is in, if the module has sections.
    pub(super) fn group_of(&self, j: usize) -> Option<&'static str> {
        self.groups.iter().rev().find(|(start, _)| *start <= j).map(|(_, title)| *title)
    }
    pub(super) fn on(mut self) -> Self {
        self.on = true;
        self
    }
    // Kill Aura's and Trigger Bot's Shield: the offhand shield kept up, lowered for each hit (sunset_hands).
    pub(super) fn shield(self) -> Self {
        self.bool("Shield", false)
            .bool("Shield only with a weapon", true)
            .bool("Shield only near a target", true)
            .num("Shield range", 6.0, 2.0, 16.0, 0.5)
            .num("Shield re-raise delay", 0.0, 0.0, 10.0, 1.0)
    }
    pub(super) fn bool(mut self, name: &'static str, v: bool) -> Self {
        self.settings.push(Setting {
            name,
            value: Value::Bool(v),
        });
        self
    }
    pub(super) fn num(mut self, name: &'static str, v: f64, min: f64, max: f64, step: f64) -> Self {
        self.settings.push(Setting {
            name,
            value: Value::Num { v, min, max, step },
        });
        self
    }
    pub(super) fn text(mut self, name: &'static str, default: &str) -> Self {
        self.settings.push(Setting {
            name,
            value: Value::Text(default.to_owned()),
        });
        self
    }
    pub(super) fn pick(mut self, name: &'static str, of: &'static [&'static str]) -> Self {
        self.settings.push(Setting {
            name,
            value: Value::Pick { i: 0, of },
        });
        self
    }
    // Auto Weapon: whether its Mode runs this section.
    pub(super) fn weapon(&self, section: &str) -> bool {
        super::sunset_melee::weapon_on(self, section)
    }
    pub(super) fn setting(&self, name: &str) -> Option<&Setting> {
        self.settings.iter().find(|s| s.name == name)
    }
    pub(super) fn b(&self, name: &str) -> bool {
        matches!(self.setting(name), Some(Setting { value: Value::Bool(true), .. }))
    }
    pub(super) fn n(&self, name: &str) -> f64 {
        match self.setting(name) {
            Some(Setting { value: Value::Num { v, .. }, .. }) => *v,
            _ => 0.0,
        }
    }
    // A list setting's text.
    pub(super) fn t(&self, name: &str) -> &str {
        match self.setting(name) {
            Some(Setting { value: Value::Text(t), .. }) => t,
            _ => "",
        }
    }
    pub(super) fn p(&self, name: &str) -> &'static str {
        match self.setting(name) {
            Some(Setting { value: Value::Pick { i, of }, .. }) => of[*i],
            _ => "",
        }
    }
    // What the module list shows beside the name (as Sunset's info string).
    pub(super) fn info(&self) -> Option<String> {
        match self.name {
            "Flight" => Some(self.p("Mode").to_owned()),
            "Kill Aura" => Some(num(self.n("Range"))),
            "Fast Place" => Some(num(self.n("Speed"))),
            "Speed" | "Criticals" | "Fake Lag" => Some(self.p("Mode").to_owned()),
            "Client Spoofer" => Some(self.p("Client").to_owned()),
            "Offhand" if self.b("Show totem count") => Some(super::sunset_combat_inventory::totem_count().to_string()),
            _ => None,
        }
    }

    pub(super) fn setting_visible(&self, j: usize) -> bool {
        let name = self.settings[j].name;
        let advanced = self.b("Advanced");
        match self.name {
            // Kill Aura's and Trigger Bot's Shield: its settings with it on.
            "Kill Aura" if name == "Shield" => false, // Retained compatibility alias, superseded by AutoBlock.
            "Kill Aura" if name.starts_with("Shield ") => self.p("AutoBlock") == "Modern",
            "Kill Aura" if name == "Legacy reblock delay" => self.p("AutoBlock") == "Legacy",
            "Trigger Bot" if name.starts_with("Shield ") => self.b("Shield"),
            // Streamer Mode: what shows in place of a name, with that name hidden.
            "Streamer Mode" => match name {
                "Your name" => self.b("Hide your name"),
                "Others as" | "Others' name" => self.b("Hide others"),
                _ => true,
            },
            // Client Spoofer: a profile's own settings with it picked (all of them with Per server set).
            "Client Spoofer" => {
                let picked = |profile: &str| self.p("Client") == profile || !self.t("Per server").trim().is_empty();
                match name {
                    "Custom brand" => picked("Custom"),
                    "Lunar version" | "Lunar Fabric tag" => picked("Lunar Client"),
                    "LabyMod version" => picked("LabyMod"),
                    _ => true,
                }
            }
            "Ghost Hand" => name != "Cut through" || !self.b("Hits"),
            "HUD" => match name {
                "Second color" => self.p("List color mode") != "Static" || self.p("Watermark color mode") != "Static",
                "Color speed" => [self.p("List color mode"), self.p("Watermark color mode")].iter().any(|m| *m != "Static"),
                "Watermark text" | "Watermark profile" | "Watermark color mode" | "Watermark position" => self.b("Watermark"),
                "Watermark x" | "Watermark y" => self.b("Watermark") && self.p("Watermark position") == "Custom",
                "Module list side" | "Modules shown" | "Module details" | "Remove spaces" | "List sort" | "List color mode"
                | "List background" | "List bar" | "List spacing" | "List animations" | "Module list position" => self.b("Module list"),
                "Module list x" | "Module list y" => self.b("Module list") && self.p("Module list position") == "Custom",
                "Target HUD position" => self.b("Target HUD"),
                "Target HUD x" | "Target HUD y" => self.b("Target HUD") && self.p("Target HUD position") == "Custom",
                "Scoreboard x" | "Scoreboard y" => self.p("Scoreboard position") == "Custom",
                "Coordinates position" => self.b("Coordinates"),
                "Coordinates x" | "Coordinates y" => self.b("Coordinates") && self.p("Coordinates position") == "Custom",
                "Compass position" => self.b("Compass"),
                "Compass x" | "Compass y" => self.b("Compass") && self.p("Compass position") == "Custom",
                "Armor HUD x" | "Armor HUD y" => self.b("Armor HUD") && self.p("Armor HUD position") == "Custom",
                // The Info line's parts and Shield status, each placed on its own once dragged.
                "FPS position" | "Speed position" | "Facing position" | "Totems position" | "Shield status position" => {
                    self.b(name.trim_end_matches(" position"))
                }
                "FPS x" | "FPS y" => self.b("FPS") && self.p("FPS position") == "Custom",
                "Speed x" | "Speed y" => self.b("Speed") && self.p("Speed position") == "Custom",
                "Facing x" | "Facing y" => self.b("Facing") && self.p("Facing position") == "Custom",
                "Totems x" | "Totems y" => self.b("Totems") && self.p("Totems position") == "Custom",
                "Shield status x" | "Shield status y" => self.b("Shield status") && self.p("Shield status position") == "Custom",
                _ if name.starts_with("Armor HUD ") => self.b("Armor HUD"),
                "Durability format" | "Durability tooltip" => self.b("Item durability"),
                "Target HUD mode" => self.b("Target HUD"),
                _ => true,
            },
            "Client Sort" => name != "Fill CPS" || self.b("Shift fill"),
            "Loadouts" => match name {
                "Hotbar mode" | "Hotbar rules" | "Hotbar delay (ms)" => self.b("Auto hotbar"),
                _ => true,
            },
            "No Slow" => match name {
                "Release items" => self.b("No item release"),
                _ => true,
            },
            "Auto Clicker" => match name {
                "Delay (ticks)" => self.p("Mode") == "Delay",
                "Min CPS" | "Max CPS" => self.b("Left") && self.p("Mode") == "CPS" || self.b("Right") && !self.b("Right own CPS") && self.p("Mode") == "CPS",
                "CPS pattern" => self.p("Mode") == "CPS" || self.b("Right") && self.b("Right own CPS"),
                "Respect miss cooldown" => self.b("Left"),
                "Right items" | "Right sneak only" | "Right start delay (ms)" | "Right own CPS" => self.b("Right"),
                "Right min CPS" | "Right max CPS" => self.b("Right") && self.b("Right own CPS"),
                _ => true,
            },
            "Trigger Bot" => match name {
                "Shortest cooldown (%)" | "Longest cooldown (%)" => self.b("Wait for cooldown"),
                "Sticky range" => self.b("Sticky target"),
                _ => true,
            },
            "Auto Gap" => match name {
                "Pot mode" | "Pot pitch" => self.b("Auto pot"),
                "Pot health" => self.b("Auto pot") && self.p("Pot mode") == "Auto",
                "Soup health" | "Soup delay (ms)" | "Drop bowls" => self.b("Soup"),
                _ => true,
            },
            "Auto Replenish" => match name {
                "Refill key" => self.p("Mode") == "Key",
                "Healing only" | "Potion delay (ticks)" => self.b("Potion refill"),
                _ => true,
            },
            "Flight" => {
                let mode = self.p("Mode");
                let old = matches!(mode, "Abilities" | "Velocity");
                match name {
                    "Speed" | "Anti kick mode" => old,
                    "Delay" | "Off time" => old && self.p("Anti kick mode") != "None",
                    "Vertical speed match" | "No sneak" => mode == "Velocity",
                    "Burst speed" | "Burst friction" | "Burst repeat" => mode == "NCP Burst",
                    "Bounce period (ticks)" | "Bounce boost" => mode == "NCP Bounce",
                    "Damage time (ticks)" | "Knockback" | "Damage boost" | "After damage" => self.p("Damage fly") != "Off",
                    "Self damage health" | "Self damage method" => self.p("Damage fly") == "Self damage",
                    _ => true,
                }
            }
            "Inventory Manager" => {
                let slots = self.p("Mode") == "Slots";
                match name {
                    "Armor key" => self.p("Armor mode") == "Key",
                    "Switch sets" => key_from_text(self.t("Switch key")).is_some(),
                    "Mode" | "Only in inventory" | "Protected items" | "Auto Armor" | "Auto Armor key"
                    | "Armor delay (ticks)" | "Armor mode" | "Avoid cursed" | "Switch key" => true,
                    "Delay min (ms)" | "Delay max (ms)" | "Drop custom items" | "Use custom items" | "Prioritize splash potions"
                    | "Block limit" | "Arrow limit" | "Bucket limit" | "Snowball and egg limit" | "Ender pearl limit"
                    | "Sword slot" | "Second sword slot" | "Pickaxe slot" | "Axe slot" | "Shovel slot" | "Block slots from"
                    | "Block slots to" | "Potion slots from" | "Potion slots to" | "Bow slot" | "Rod slot" | "Food slots from"
                    | "Food slots to" => slots,
                    _ if slots => false,
                    "Keep totems" | "Keep pearl stacks" => self.t("Loot key") != "None",
                    "List mode" | "Items" => self.p("Preset") == "Custom",
                    "Blocks" | "Food" | "Arrows" | "Pearls" | "Junk" => self.p("Preset") != "Custom",
                    _ => true,
                }
            }
            // Crystal Aura and Anchor Aura: each section's settings with it on, the shared ones with either.
            "Crystal Aura" => match name {
                "Aura" | "Macro" => true,
                "Hold key" => self.b("Aura") && self.b("Require hold"),
                "Render color" => self.b("Aura") && self.b("Render"),
                "Require hold" | "Min damage" | "Face place" | "Force face place" | "Turn speed" | "View angle" | "Render" => self.b("Aura"),
                "Obsidian delay" => self.b("Macro") && self.b("Auto obsidian"),
                "Perfect timing" => self.b("Macro"),
                _ => self.b("Aura") || self.b("Macro"),
            },
            "Anchor Aura" => match name {
                "Aura" | "Macro" | "Pearl catch" => true,
                "Scan range" | "Catch min damage" | "Catch max self damage" | "Anti suicide" | "Damage tick" | "Safe cover"
                | "Silent aim FOV" | "Catch swap back" | "Shortest place delay (ms)" | "Longest place delay (ms)"
                | "Shortest charge delay (ms)" | "Longest charge delay (ms)" | "Shortest detonate delay (ms)"
                | "Longest detonate delay (ms)" => self.b("Pearl catch"),
                "Safe block" => self.b("Pearl catch") && self.b("Safe cover"),
                "Render color" => self.b("Aura") && self.b("Render"),
                "Min damage" | "Max self damage" | "Render" | "Turn speed" => self.b("Aura"),
                "Mode" | "Delay" | "Safe anchor" | "Switch back" => self.b("Macro"),
                "Wait for hurt time" => self.b("Macro") && self.p("Mode") == "Double",
                "If unguarded" => self.b("Macro") && self.b("Safe anchor"),
                _ => self.b("Aura") || self.b("Macro"),
            },
            "Anvil" => match name {
                "Target range" | "Height" | "Delay" | "Place at feet" | "Multi place" => self.b("Auto Anvil"),
                "Rotate" => self.b("Anti Anvil") || self.b("Self Anvil") || self.b("Auto Anvil"),
                _ => true,
            },
            "Hand View" => {
                let legacy = self.p("Animations") == "1.8";
                match name {
                    "Swing animation" | "Block animation" => !legacy,
                    "1.8 swing" => legacy,
                    "1.8 block" => legacy || self.p("Block animation") == "1.8 style",
                    _ => true,
                }
            }
            "Speed" => match name {
                "Vanilla speed" => !matches!(self.p("Mode"), "Strafe" | "Bhop" | "NCP" | "NCP Hop" | "Watchdog"),
                "NCP reduced jump" => self.p("Mode") == "NCP",
                "NCP hop jump" | "NCP hop ground speed" | "NCP hop slope" | "NCP hop custom boost" | "NCP hop low hop"
                | "NCP hop Y-port" => self.p("Mode") == "NCP Hop",
                "NCP hop boost speed" | "NCP hop hurt ticks" => self.p("Mode") == "NCP Hop" && self.b("NCP hop custom boost"),
                "Watchdog knockback boost" => self.p("Mode") == "Watchdog",
                "Strafe speed" | "Speed limit" => self.p("Mode") == "Strafe",
                "Hop speed" | "Hop gain (%)" | "Hop height" | "Hop slope" | "Air friction (%)" | "Air control" | "Fast fall"
                | "Hop when" | "Stop on release" => self.p("Mode") == "Bhop",
                "Damage boost" => matches!(self.p("Mode"), "Bhop" | "NCP Hop"),
                "Hop max speed" => self.p("Mode") == "Bhop" && self.n("Hop gain (%)") > 0.0,
                "Only on ground" => !matches!(self.p("Mode"), "Bhop" | "NCP" | "NCP Hop" | "Watchdog"),
                "Ground multiplier" => advanced && self.p("Mode") == "Custom",
                "Air multiplier" => advanced && matches!(self.p("Mode"), "Smooth" | "Low Hop" | "Custom") && !self.b("Only on ground"),
                "Acceleration" | "Deceleration" | "Strafe strength" => advanced && matches!(self.p("Mode"), "Smooth" | "Custom"),
                "Jump height" => advanced && self.p("Mode") == "Low Hop",
                "Max speed" | "Sprint multiplier" => advanced && matches!(self.p("Mode"), "Smooth" | "Low Hop" | "Custom"),
                "Knockback pause" | "Stop at wall" => advanced,
                _ => true,
            },
            "Velocity" => match name {
                "Delay chance (%)" | "Air delay min (ms)" | "Air delay max (ms)" | "Ground delay min (ms)"
                | "Ground delay max (ms)" | "Delay not in water" | "Delay only near enemies" => self.b("Knockback delay"),
                "Use air values" => advanced,
                "Air knockback horizontal" | "Air knockback vertical" => advanced && self.b("Use air values"),
                "Blend %" => self.p("Mode") == "Blend",
                _ => true,
            },
            "Kill Aura" => {
                let always = self.p("Rotate") == "Always";
                match name {
                    "Rotation mode" | "Rotation view" => always,
                    "Yaw speed" | "Pitch speed" => always && matches!(self.p("Rotation mode"), "Custom" | "Adaptive"),
                    "Smoothing" => always && self.p("Rotation mode") == "Custom",
                    "Aim speed" => always && self.p("Rotation mode") == "Silent aura",
                    "Rotation range" => self.p("Rotate") != "None",
                    "Aim point" | "Prediction" => always && self.p("Rotation mode") != "Silent aura",
                    "Aim height (%)" => always && self.p("Rotation mode") != "Silent aura" && self.p("Aim point") == "Custom",
                    "Prediction strength" => always && self.p("Rotation mode") != "Silent aura" && self.p("Prediction") != "Off",
                    "Max targets" => self.p("Attack mode") == "Multi",
                    "Target lock" => self.p("Attack mode") == "Single",
                    "Target switch delay" => self.p("Attack mode") != "Multi",
                    // Modern's timing and Legacy's clicks; Auto may run either, so it shows both.
                    "Attack timing" => self.p("Combat version") != "Legacy (1.8)",
                    "Cooldown" => self.p("Combat version") != "Legacy (1.8)" && self.p("Attack timing") != "Custom delay",
                    "Hit delay" => self.p("Combat version") != "Legacy (1.8)" && self.p("Attack timing") == "Custom delay",
                    "Min CPS" | "Max CPS" | "CPS pattern" => self.p("Combat version") != "Modern (1.9+)",
                    "Strafe radius" | "Strafe when" | "Avoid edges" => self.b("Target strafe"),
                    "Selected weapon types" => self.p("Attack when holding") == "Weapons",
                    "Swap back" => self.b("Auto switch"),
                    "Anti bot sensitivity" => self.b("Anti bot"),
                    _ => true,
                }
            }
            "Entity Control" => match name {
                "Horizontal speed" | "Only on ground" | "In water" => self.b("Speed"),
                "Vertical speed" | "Fall speed" | "Anti fly kick" => self.b("Fly"),
                "Delay" => self.b("Fly") && self.b("Anti fly kick"),
                _ => true,
            },
            "Pearl Catch" => match name {
                "Wind charge delay (ms)" => matches!(self.p("Key mode"), "Up" | "Diagonal macro"),
                "Moving delay (ms)" => self.p("Key mode") == "Up",
                "Pearl angle" | "Wind charge angle" => self.p("Key mode") == "Fast",
                "Offhand pearl angle" | "Offhand wind charge angle" => self.p("Key mode") == "Offhand",
                "Max yaw delta" => self.p("Key mode") == "Diagonal",
                _ => true,
            },
            "Wind Jump" => match name {
                "Hit reach" | "Max yaw" | "In air only" | "Humanized aim" => self.b("Hit charges"),
                _ => true,
            },
            "Fast Use" => match name {
                "Throw mode" | "Experience bottles" | "Ender pearls" | "Wind charges" | "Snowballs and eggs" | "Splash potions"
                | "Off hand" => self.b("Throwables"),
                "Throw delay" => self.b("Throwables") && self.p("Throw mode") == "Delay",
                "Burst" => self.b("Throwables") && self.p("Throw mode") == "Burst",
                _ => true,
            },
            "Offhand" => {
                let totem = self.p("Item") == "Totem" || self.b("Totem on low health");
                let (open, silent) = (self.b("Open inventory"), self.b("Silent open"));
                match name {
                    "Totem health" | "Wait while shielding" => self.b("Totem on low health"),
                    "Sword gapple" => self.b("Right gapple"),
                    "Open inventory" | "Inventory only" | "Random slot" | "Shortest totem delay (ms)" | "Longest totem delay (ms)"
                    | "Extra randomization" | "Show totem count" => totem,
                    "Silent open" => totem && open,
                    "Shortest silent move delay (ms)" | "Longest silent move delay (ms)" => totem && open && silent,
                    "Close inventory" => totem && open && !silent,
                    "Hotbar refill" => self.b("Hover"),
                    "Double hand on" | "Double hand sensitivity" | "Reswap delay (ticks)" => self.b("Double hand"),
                    "Hotbar slot" => self.b("Hover") && self.b("Hotbar refill"),
                    _ => true,
                }
            }
            "Hitboxes" if name == "Weapons" => self.b("Only on weapon"),
            "Auto Web" => match name {
                "Max webs per fall" => self.b("Only when falling"),
                "Ticks to predict" => self.b("Predict movement") && !self.b("Only when falling"),
                _ => true,
            },
            "Shield" => match name {
                "Target distance" | "FOV" | "Movement threshold" | "Sword cooldown correction (%)" | "Disable tracker" => self.b("Auto block"),
                "Swap to sword" => self.b("Auto block") && self.b("Disable tracker"),
                "Block hit min chance (%)" | "Block hit max chance (%)" | "Block hit ticks" => self.p("Block hit") == "Manual",
                "Max hurt time (ms)" | "Include ping" | "Hold after" => self.p("Block hit") == "Predict",
                "Require mouse down" => self.p("Block hit") != "Off",
                _ => true,
            },
            "Fake Lag" => super::sunset_lag::setting_visible(self, name),
            "Sprint" if name.ends_with("restore delay") => self.b("Keep sprint"),
            "Aim Assist" => match name {
                "Silent players only" | "Silent weapon only" | "Silent max yaw" | "Silent max pitch" => self.b("Silent aim"),
                "Aim points" => self.b("Silent aim") || self.b("Hit flick"),
                "Flick players only" | "Flick needs sprint" | "Flick min angle" | "Flick max angle" | "Flick direction" => self.b("Hit flick"),
                _ => true,
            },
            "Liquid Filler" => match name {
                "Drain aim" | "Only by cobwebs" | "Drain swap" | "Swap back" | "Fallback to cobweb" => self.p("Mode") == "Drain",
                "Silent aim FOV" => self.p("Mode") == "Drain" && self.p("Drain aim") == "Silent aim",
                "Shape" | "Place range" | "Walls range" | "Max blocks per tick" | "Sort" | "List mode" | "Whitelist" | "Blacklist" => {
                    self.p("Mode") == "Fill"
                }
                _ => true,
            },
            "No Interact" => match name {
                "Hit fix weapons only" | "Hit fix hurt time" | "Hit fix on ground" => self.b("Hit fix"),
                "Hit select chance (%)" => self.p("Hit select") != "Off",
                "Hit select favours" => self.p("Hit select") == "Sprint reset",
                "Humanize (%)" | "In combat only" => self.b("No miss delay"),
                "Combat range" => self.b("No miss delay") && self.b("In combat only"),
                "Double glowstone" | "Open ender chest" | "Place glowstone" | "Ground firework" => self.b("Anti action"),
                "Cobweb only" | "Use offhand" => self.b("Ghost place"),
                "Hide armor stands" | "Hide minecarts" | "Hide item frames" | "Hide boats" | "Hide end crystals" | "Trap range"
                | "Drop spawns" | "Remove loaded" | "Anti sign" => self.b("Anti trap"),
                _ => true,
            },
            "Chest Swap" => match name {
                "Mode" => true,
                "Fly time (ms)" => self.p("Mode") == "Take off" && self.b("Auto disable"),
                "Shortest space cooldown (ms)" | "Longest space cooldown (ms)" => self.p("Mode") == "Take off" && self.b("Firework on space"),
                _ => self.p("Mode") == "Take off",
            },
            "Safe Walk" => match name {
                "Min pitch" | "Only holding blocks" => self.p("Mode") == "Sneak",
                _ => true,
            },
            "Rotations" => match name {
                "Yaw lock" | "Pitch lock" => self.b("Lock"),
                "Yaw angle" => self.b("Lock") && self.p("Yaw lock") == "Simple",
                "Pitch angle" => self.b("Lock") && self.p("Pitch lock") == "Simple",
                _ => true,
            },
            "Step" => match name {
                "Height" | "Active when" | "Safe step" => self.b("Step up"),
                "Step health" => self.b("Step up") && self.b("Safe step"),
                "Fall speed" => self.b("Reverse step"),
                _ => true,
            },
            "Base Finder" => super::sunset_base_finder::visible(self, name),
            super::sunset_light_scan::GEODE | super::sunset_light_scan::LIGHT => super::sunset_light_scan::visible(self, name),
            super::sunset_sound_detector::NAME => super::sunset_sound_detector::visible(self, name),
            "Anti Vanish" => super::sunset_vanish::visible(self, name),
            "Effects" => super::sunset_effects::visible(self, name),
            super::sunset_pvp_bot::NAME => super::sunset_pvp_bot::visible(self, name),
            "Atmosphere" => super::sunset_atmosphere::visible(self, name),
            "ESP" => match name {
                "2D style" | "Health bar" | "2D names" | "2D distance" | "Glow" => self.p("Mode") == "2D box",
                "Health side" | "Health text" => self.p("Mode") == "2D box" && self.b("Health bar"),
                "Shield mode" | "Shield color" | "Broken shield color" => self.b("Shield colors"),
                "Murderer items" | "Murderer color" | "Murderer list" | "Callout" => self.b("Murderer finder"),
                "Murderer list position" => self.b("Murderer finder") && self.b("Murderer list"),
                "Murderer list x" | "Murderer list y" => {
                    self.b("Murderer finder") && self.b("Murderer list") && self.p("Murderer list position") == "Custom"
                }
                "Callout delay (ms)" | "Callout messages" => self.b("Murderer finder") && self.b("Callout"),
                _ => true,
            },
            "Nametags" => match name {
                "Health colors" => self.b("Health"),
                _ => true,
            },
            "Cart" => super::sunset_cart::visible(self, name),
            super::sunset_gear::NAME => super::sunset_gear::visible(self, name),
            "Auto Mace" => super::sunset_auto_mace::visible(self, name),
            "ClickGUI" => match name {
                "Inventory blur" => self.b("Menu dim"),
                _ => true,
            },
            "Auto Weapon" => match name {
                "Best weapon" | "Axe on shields" => self.p("Mode") == "Custom",
                "Prefer axes" => self.p("Mode") == "Custom" && self.b("Best weapon"),
                "Totem hit" => self.weapon("Best weapon"),
                "Shield mode" | "Shield held" => self.weapon("Axe on shields"),
                "Back after" => self.b("Swap back"),
                "Shortest delay" | "Longest delay" => self.b("Swap back") && self.p("Back after") == "A delay",
                _ => true,
            },
            "Radar" => !matches!(name, "Radar x" | "Radar y") || self.p("Radar position") == "Custom",
            "Auto Spear" => match name {
                "Reach chance (%)" | "Reach weapons" | "Works with Trigger Bot" => self.b("Extended reach"),
                "Damage indicator position" => self.b("Damage indicator"),
                "Damage indicator x" | "Damage indicator y" => self.b("Damage indicator") && self.p("Damage indicator position") == "Custom",
                "Back after" => self.b("Swap back"),
                "Shortest delay" | "Longest delay" => self.b("Swap back") && self.p("Back after") == "A delay",
                _ => true,
            },
            "GUI Move" => match name {
                "Rotate speed" => self.b("Arrows"),
                _ => true,
            },
            // W Tap's S Tap: its own settings in that mode.
            "W Tap" => match name {
                "Adaptive" => self.p("Mode") == "S Tap",
                "Spacing" => self.p("Mode") == "S Tap" && self.b("Adaptive"),
                _ => true,
            },
            "Scaffold" => match name {
                "Block counter position" => self.b("Block counter"),
                "Block counter x" | "Block counter y" => self.b("Block counter") && self.p("Block counter position") == "Custom",
                "Telly rotations" | "Start speed min" | "Start speed max" | "Normal speed min" | "Normal speed max"
                | "Keep Y" | "Tower" | "Telly sprint" | "Ground motion (%)" | "Air motion (%)" | "Speed motion (%)"
                | "Multi place" | "Swing" | "Reject wait (ticks)" => self.p("Mode") == "Telly",
                "Keep Y on press" => self.p("Mode") == "Telly" && self.p("Keep Y") == "Telly",
                "Shortest sneak delay (ms)" | "Longest sneak delay (ms)" => self.p("Mode") == "Legit",
                "Activation blocks" => self.p("Mode") == "Godbridge",
                "Auto switch" => self.p("Mode") != "Legit",
                "Swap back" => matches!(self.p("Mode"), "Normal" | "Telly") && self.b("Auto switch"),
                "Delay (ticks)" => matches!(self.p("Mode"), "Normal" | "Telly"),
                "Rotations" | "Look" | "Rotation speed" | "Min rotation speed" | "Ray cast" => self.p("Mode") == "Normal" && self.b("Rotate"),
                "Telly ticks" => self.p("Mode") == "Normal" && self.b("Rotate") && self.p("Rotations") == "Telly",
                "Movement correction" => self.p("Mode") == "Normal" && self.b("Rotate") && self.p("Look") == "Silent",
                "Late click" => self.p("Mode") == "Normal" && self.b("Rotate") && self.p("Ray cast") == "Strict",
                "Air place" => self.p("Mode") == "Normal" && (!self.b("Rotate") || self.p("Ray cast") == "Off"),
                "Render" => matches!(self.p("Mode"), "Normal" | "Telly"),
                "Fast tower" | "Only on click" | "Rotate" | "Sprint" | "Same Y" | "Expand" | "Ledge sneak"
                | "Advanced" => self.p("Mode") == "Normal",
                "Tower speed" | "While moving" => self.p("Mode") == "Normal" && self.b("Fast tower"),
                "Shape mode" | "Fill opacity" | "Color" => matches!(self.p("Mode"), "Normal" | "Telly") && self.b("Render"),
                "Safe walk" | "Max placement distance" | "Closest block range" | "Max per second" => {
                    self.p("Mode") == "Normal" && advanced
                }
                _ => true,
            },
            "Server Scan" => match name {
                "Query" | "Command suggestions" => self.p("Mode") == "Extended",
                _ => true,
            },
            _ => true,
        }
    }
}

// Base Finder's block list before its tiers (0.8.1), told apart from a list of your own.
pub(super) const OLD_BASE_BLOCKS: &str = "chest,trapped_chest,barrel,ender_chest,shulker_box,*_shulker_box,crafting_table,furnace,blast_furnace,smoker,*_bed,*_sign,anvil,enchanting_table,brewing_stand,hopper,dropper,dispenser,beacon,respawn_anchor,lodestone,*_concrete,nether_portal";

// Runtime part (see runtime.rs): velocity, Flight, strafe, Bhop and Speed, and pushes.

use super::Game;
use horizon_protocol::packets::play::{self, Serverbound as S};
use std::sync::atomic::Ordering;
use winit::keyboard::KeyCode;
use super::sunset::*;

pub(super) fn remember_velocity(game: &Game<'_>) {
    let v = game.player.as_ref().map(|p| [p.velocity.x, p.velocity.y, p.velocity.z]);
    with(|s| s.velocity = v);
}

// A correction replaces the player's position: Speed's strafe and Scaffold's waits start again. (Velocity's baseline
// stays: Horizon's server can bring a hit's knockback with a position packet, which Velocity has to see.)
pub(super) fn server_correction(game: &mut Game<'_>) {
    super::sunset_lag::correction(game);
    if !game.native_on(ID) { return; }
    // Flight: a setback is the server refusing where Flight took you; pushing on from there is what loops.
    if let Some((pause, disable)) = with(|s| s.module("Flight").filter(|m| m.on).map(|m| (m.n("Setback pause (ticks)") as u32, m.b("Disable on setback")))) {
        if disable {
            toggle_named(game, "Flight", false);
            say(game, "Flight off: the server set you back.");
        } else {
            with(|s| s.fly_setback = pause);
            super::sunset_flight::correction(pause);
        }
    }
    super::sunset_render::no_slow_reset();
    super::sunset_parity::correction(game);
    let disable_speed = with(|s| {
        s.knockback_ticks = 0;
        s.strafe = Strafe::default();
        s.bhop.reset();
        s.ncp.recover();
        s.ncp_hop.teleported();
        s.watchdog.reset(); // A server correction owns its new velocity; never restore old launch momentum here.
        s.scaffold_stack = None;
        s.module("Speed").is_some_and(|m| m.on && matches!(m.p("Mode"), "NCP" | "Watchdog"))
            && s.legacy_recovery.correction(game.ticks)
    });
    if disable_speed {
        toggle_named(game, "Speed", false);
        say(game, "Speed off: repeated server corrections in an experimental legacy mode.");
    }
    super::sunset_scaffold_normal::correction();
    super::sunset_scaffold_telly::correction();
    horizon_client::motion::sunset_motion::set_across(None);
    horizon_client::motion::sunset_motion::set_up(None);
    horizon_client::motion::sunset_motion::set_strafe_dir(None);
}

fn velocity_share(m: &Module, name: &str) -> f64 {
    let blend = if m.p("Mode") == "Blend" { m.n("Blend %") } else { 100.0 };
    super::sunset_movement::velocity_factor(m.n(name) * 100.0, blend)
}

pub(super) fn knockback_shares(m: &Module, ground: bool) -> [f64; 2] {
    let (h, v) = if !ground && m.b("Use air values") {
        ("Air knockback horizontal", "Air knockback vertical")
    } else {
        ("Knockback horizontal", "Knockback vertical")
    };
    [velocity_share(m, h), velocity_share(m, v)]
}

// Flight (Sunset's) before the tick: hovering after a fall of three blocks, nudge the yaw a degree either way so the
// look the server sees moves (put back after the tick); in Velocity mode set the speed the air gives you, and with
// No sneak let go of sneaking (its key still takes you down).
pub(super) fn flight_pre(game: &mut Game<'_>, m: Option<&Module>) {
    use horizon_client::motion::sunset_motion as motion;
    let Some(m) = m else {
        super::sunset_flight::stop(game);
        motion::set_flying_speed(None);
        let (delay, off) = (20, 1);
        with(|s| {
            (s.fly_delay, s.fly_off) = (delay, off);
            if std::mem::take(&mut s.unsneaked) && game.physical_keys.contains(&KeyCode::ShiftLeft) {
                game.keys.insert(KeyCode::ShiftLeft);
            }
        });
        FLY_DOWN.store(false, Ordering::Relaxed);
        FLY_LAST_Y.store(u64::MAX, Ordering::Relaxed);
        return;
    };
    if super::sunset_flight::experimental(m.p("Mode")) {
        motion::set_flying_speed(None);
        // Old NCP sets the move across itself (over Speed's), at the 1.8 strafe's allowed distance.
        if m.p("Mode") == "Old NCP" {
            motion::set_across(super::sunset_flight::old_ncp_across(game));
        }
        return;
    }
    super::sunset_flight::stop(game);
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let yaw = game.yaw;
    let still = p.velocity.x.hypot(p.velocity.y).hypot(p.velocity.z) < 0.003;
    let (fallen, sprinting) = (p.fall_distance, p.sprinting);
    let nudge = with(|s| {
        let nudge = (fallen >= 3.0 && yaw == s.fly_last_yaw && still).then(|| if s.fly_flip { 1.0 } else { -1.0 });
        if nudge.is_some() {
            s.fly_flip = !s.fly_flip;
        }
        s.fly_last_yaw = yaw;
        nudge
    });
    if let Some(d) = nudge {
        game.yaw = yaw + d;
    }
    let velocity = m.p("Mode") == "Velocity";
    let speed = m.n("Speed") as f32;
    motion::set_flying_speed(velocity.then(|| speed * if sprinting { 15.0 } else { 10.0 }));
    if velocity && m.b("No sneak") && game.keys.remove(&KeyCode::ShiftLeft) {
        with(|s| s.unsneaked = true);
    }
}

// Flight after the tick: Sunset's anti kick (Packet: every `Delay` ticks the next move packets sink a little for
// `Off time` ticks, Normal: the flying stops for those ticks), the yaw put back, then the mode: Abilities flies as
// creative does at Speed; Velocity holds you still but for the jump and sneak keys, and Speed sets the air's pull.
// A tick of Flight's setback pause: true while it holds still, counting down.
pub(super) fn fly_paused(left: &mut u32) -> bool {
    let paused = *left > 0;
    *left = left.saturating_sub(1);
    paused
}

pub(super) fn flight_post(game: &mut Game<'_>, m: Option<&Module>, jump: bool, sneak: bool, screen_dir: Option<[f64; 2]>) {
    let Some(m) = m else {
        return;
    };
    if super::sunset_flight::experimental(m.p("Mode")) {
        super::sunset_flight::tick(game, m);
        // Old NCP: a move packet every tick, as a 1.8 client sends one, so each carries its height offset. The game
        // sends none on a tick you neither moved nor turned; this one goes then (never a second in a tick).
        if m.p("Mode") == "Old NCP"
            && !MOVED_THIS_TICK.load(Ordering::Relaxed)
            && game.remote.is_some()
            && let Some(p) = game.player.as_ref()
        {
            let (x, y, z) = (p.position.x, p.position.y, p.position.z);
            let flags = u8::from(p.ground.on_ground) | (u8::from(p.collision.horizontal) << 1);
            game.send(S::MovePlayerPos(play::MovePlayerPos { x, y, z, flags }));
        }
        return;
    }
    let (velocity, kick) = (m.p("Mode") == "Velocity", m.p("Anti kick mode"));
    let (delay, off_time) = (m.n("Delay") as i32, m.n("Off time") as i32);
    let (rest, remind, last_yaw) = with(|s| {
        let (mut rest, mut remind) = (false, false);
        if s.fly_delay > 0 {
            s.fly_delay -= 1;
        }
        if s.fly_off <= 0 && s.fly_delay <= 0 {
            (s.fly_delay, s.fly_off) = (delay, off_time);
            remind = kick == "Packet";
        } else if s.fly_delay <= 0 {
            rest = kick == "Normal" && !velocity;
            remind = kick == "Packet" && s.fly_off == off_time;
            s.fly_off -= 1;
        }
        FLY_DOWN.store(kick == "Packet" && s.fly_delay <= 0, Ordering::Relaxed);
        (rest, remind, s.fly_last_yaw)
    });
    if remind {
        horizon_client::player_sync::sunset_sync::remind();
    }
    let (creative, spectator) = (game.creative, game.spectator());
    let paused = with(|s| fly_paused(&mut s.fly_setback));
    let Some(p) = game.player.as_mut() else {
        return;
    };
    if paused {
        // Held still where the server put you: no push, and vanilla's flying speed.
        if velocity {
            p.velocity = horizon_core::geometry::Vec3::new(0.0, 0.0, 0.0);
        } else {
            p.flying_speed = 0.05;
        }
        return;
    }
    if rest {
        p.flying = false;
        p.flying_speed = 0.05;
        p.may_fly = creative || spectator;
        return;
    }
    game.yaw = last_yaw;
    let speed = m.n("Speed");
    if velocity {
        p.flying = false;
        let up = speed * if m.b("Vertical speed match") { 10.0 } else { 5.0 };
        let down = sneak || game.physical_keys.contains(&KeyCode::ShiftLeft);
        p.velocity = horizon_core::geometry::Vec3::new(0.0, f64::from(u8::from(jump)) * up - f64::from(u8::from(down)) * up, 0.0);
        // Damage fly: the hit's knockback carried on across the ground.
        if let Some([x, z]) = super::sunset_flight::carry() {
            (p.velocity.x, p.velocity.z) = (x, z);
        }
        // GUI Move: behind a menu the game takes no move keys, so the pull they would give is set by hand.
        if let Some([x, z]) = screen_dir {
            let pull = speed * if p.sprinting { 15.0 } else { 10.0 };
            (p.velocity.x, p.velocity.z) = (x * pull, z * pull);
        }
        if m.b("No sneak") {
            p.ground.on_ground = false;
        }
    } else if !spectator {
        p.flying_speed = speed as f32;
        p.flying = true;
        p.may_fly = true;
    }
}

// Speed's Strafe mode between moves: Sunset's stage, the last tick's distance, the speed, and the speed limit's clock.
#[derive(Default)]
pub(super) struct Strafe {
    pub(super) stage: u8,
    pub(super) distance: f64,
    pub(super) speed: f64,
    since: Option<std::time::Instant>,
}

// Speed's Bhop mode between ticks: the speed it carries (blocks a tick), the ticks in the air since its jump (None: on
// the ground), the ticks on the ground since the last landing, hops in a row (Hop gain) and whether the last one was
// a hop, a knockback's speed for Damage boost, whether the last tick was still rising (Fast fall's top), and whether
// Hop height's jump modifier is on the player.
#[derive(Default)]
pub(super) struct Bhop {
    pub(super) speed: f64,
    air: Option<u32>,
    pub(super) ground: u32,
    pub(super) chain: u32,
    hopped: bool,
    kick: f64,
    rising: bool,
    jump_set: bool,
}

impl Bhop {
    // Back to standing (Speed off, a correction, Panic); Hop height's modifier is taken off by bhop_body.
    pub(super) fn reset(&mut self) {
        *self = Bhop { jump_set: self.jump_set, ..Bhop::default() };
    }
}

// Speed's Bhop: hops on the game's own jump each landing (Hop height's), and takes the move across the ground:
// Hop speed on the jump's tick (Hop gain more for each hop in a row, up to Hop max speed), Hop slope of the speed over
// the sprint-jump speed lost the next tick, then Air friction each tick in the air, never under the sprint-jump speed
// (Speed's effect counted). It goes the way the move keys point, turned by Air control from the way you were going;
// a wall or a stop starts it again. Damage boost takes a knockback's speed when it is more. With no move key held,
// Stop on release stands you still.
pub(super) fn bhop(game: &Game<'_>, m: &Module, base: f64, scale: f64) -> Option<([f64; 2], Option<f64>)> {
    let p = game.player.as_ref()?;
    let Some(wish) = move_direction(game) else {
        with(|s| s.bhop.reset());
        return m.b("Stop on release").then_some(([0.0; 2], None));
    };
    let ground = p.ground.on_ground;
    // The jump goes this tick: on the ground with jump held (pressed by Bhop, or by you with Hop when Jump held).
    let jumping = ground && game.keys.contains(&KeyCode::Space);
    let (hop, gain, max) = (m.n("Hop speed") / 20.0, m.n("Hop gain (%)") / 100.0, m.n("Hop max speed") / 20.0);
    let (slope, friction) = (m.n("Hop slope").clamp(0.0, 1.0), (m.n("Air friction (%)") / 100.0).clamp(0.0, 1.0));
    let boost = m.b("Damage boost");
    let wall = p.collision.horizontal;
    let speed = with(|s| {
        let b = &mut s.bhop;
        if wall {
            b.speed = base;
            b.chain = 0;
        }
        if jumping {
            b.chain = if b.hopped && b.ground <= 2 { b.chain + 1 } else { 0 };
            let top = if gain > 0.0 { max.max(hop) } else { hop };
            b.speed = (hop * (1.0 + gain * f64::from(b.chain))).min(top).max(base);
            b.air = Some(0);
            b.ground = 0;
            b.hopped = true;
        } else if ground {
            b.ground = b.ground.saturating_add(1);
            if b.ground > 2 {
                b.chain = 0;
                b.hopped = false;
            }
            b.air = None;
            b.speed = base;
        } else {
            let n = b.air.map_or(1, |a| a.saturating_add(1));
            b.air = Some(n);
            if n == 1 {
                b.speed -= slope * (b.speed - base);
            } else {
                b.speed -= b.speed * friction;
            }
            b.speed = b.speed.max(base);
        }
        if boost && b.kick > 0.0 {
            b.speed = b.speed.max(b.kick.min(max.max(hop)));
        }
        b.kick = 0.0;
        b.speed
    });
    // Air control: on the ground the keys' way at once; in the air turned that share from the way you were going.
    let was = [p.position.x - game.previous_position.x, p.position.z - game.previous_position.z];
    let was_len = was[0].hypot(was[1]);
    let control = m.n("Air control").clamp(0.0, 1.0);
    let dir = if ground || control >= 1.0 || was_len < 1e-4 {
        wish
    } else {
        let mix = [was[0] / was_len * (1.0 - control) + wish[0] * control, was[1] / was_len * (1.0 - control) + wish[1] * control];
        let len = mix[0].hypot(mix[1]);
        if len < 1e-6 { wish } else { [mix[0] / len, mix[1] / len] }
    };
    Some(([dir[0] * speed * scale, dir[1] * speed * scale], None))
}

// Bhop on the player itself, before the tick moves it: Hop height's jump (the game's jump strength scaled, so the
// jump is the game's own), no jump delay on the ground (a held jump hops again on landing), and Fast fall's pull down
// at the top of a hop. `m`: Speed in Bhop mode, on.
pub(super) fn bhop_body(game: &mut Game<'_>, m: Option<&Module>) {
    let moving = move_input(game) != (0.0, 0.0);
    let was = with(|s| s.bhop.jump_set);
    let Some(p) = game.player.as_mut() else {
        return;
    };
    let Some(m) = m else {
        if was {
            let _ = p.set_modifier("minecraft:jump_strength", "sunset:bhop", 0.0, "add_multiplied_total", false);
            with(|s| s.bhop.jump_set = false);
        }
        return;
    };
    let _ = p.set_modifier("minecraft:jump_strength", "sunset:bhop", m.n("Hop height") / 0.42 - 1.0, "add_multiplied_total", true);
    if p.ground.on_ground {
        p.no_jump_delay = 0;
    }
    let fast_fall = m.n("Fast fall");
    let rising = with(|s| std::mem::replace(&mut s.bhop.rising, p.velocity.y > 0.0));
    if fast_fall > 0.0 && moving && rising && !p.ground.on_ground && p.velocity.y <= 0.0 && !p.fall_flying && !p.flying {
        p.velocity.y -= fast_fall;
        with(|s| s.bhop.rising = false);
    }
    with(|s| s.bhop.jump_set = true);
}

// Bhop presses the game's jump this tick: on the ground with a move key held (Hop when Moving), where Speed moves you.
pub(super) fn bhop_hops(game: &Game<'_>, m: &Module) -> bool {
    let Some(p) = game.player.as_ref() else {
        return false;
    };
    let feet = [p.position.x.floor() as i32, p.position.y.floor() as i32, p.position.z.floor() as i32];
    m.p("Hop when") == "Moving"
        && move_input(game) != (0.0, 0.0)
        && p.ground.on_ground
        && !p.flying
        && !p.fall_flying
        && game.riding.is_none()
        && (m.b("When sneaking") || !game.keys.contains(&KeyCode::ShiftLeft))
        && (m.b("In liquids") || !(p.fluids.was_touching_water || p.is_in_lava()))
        && !game.block_in_tag("minecraft:climbable", &game.block_name(feet))
}

// NCP's distinct controller; actual attributes include Speed/Slowness and server modifications. Remove only the
// native sprint multiplier before applying the historical walk/sprint baseline (do not count potion levels twice).
fn legacy_speed_move(game: &mut Game<'_>, m: &Module, item_scale: f64) -> Option<([f64; 2], Option<f64>)> {
    if !game.native_playing() || gui_open() || super::sunset_gui_move::inventory_busy()
        || with(|s| s.is_on("Scaffold"))
        || CRIT_STAGE.load(Ordering::Relaxed) != 0
    {
        watchdog_stop(game, false);
        with(|s| s.ncp.recover());
        return None;
    }
    let direction = move_direction(game);
    let speed_level = game.potions.effects.amplifier("speed").map(|a| a.max(0) as u32);
    let p = game.player.as_mut()?;
    let native_speed = p.attribute("minecraft:movement_speed").ok()?;
    let base = if p.sprinting { 0.2873 * native_speed / 0.13 } else { 0.216 * native_speed / 0.1 };
    let frame = super::sunset_legacy_speed::Frame {
        tick: game.ticks,
        position: [p.position.x, p.position.z],
        grounded: p.ground.on_ground,
        blocked: p.collision.horizontal || (p.collision.vertical && !p.ground.on_ground),
        direction,
        base,
        jump_scale: if m.b("NCP reduced jump") { 0.4 / 0.42 } else { 1.0 },
        speed_effect: speed_level.is_some(),
    };
    let velocity = [p.velocity.x, p.velocity.z];
    if m.p("Mode") == "Watchdog" && (frame.direction.is_none() || frame.blocked) {
        watchdog_stop(game, false);
        return None;
    }
    let step = with(|s| {
        if m.p("Mode") == "NCP" { s.ncp.step(frame) }
        else { s.watchdog.step(frame, velocity, speed_level, m.b("Watchdog knockback boost")) }
    });
    if step.is_none() && m.p("Mode") == "Watchdog" && with(|s| s.watchdog.recovering()) {
        watchdog_stop(game, false);
    }
    let step = step?;
    // Item-use settings scale owned acceleration, not a server impulse already filtered by Velocity.
    let scale = if m.p("Mode") == "Watchdog" && step.jump_scale.is_none() { 1.0 } else { item_scale };
    Some(([step.across[0] * scale, step.across[1] * scale], step.jump_scale))
}

// The move keys and the place you are in as a 1.8 client has them, for the 1.8 strafe (legacy_speed::strafe_move):
// Speed's NCP Hop and Flight's Old NCP. An item in use slows the keys to 20% (No Slow's share instead), as 1.8 does.
pub(super) fn legacy_strafe_frame(
    game: &mut Game<'_>,
) -> Option<(super::sunset_legacy_speed::Input, super::sunset_legacy_speed::Allowance)> {
    use super::sunset_legacy_speed::{Allowance, Input};
    let held = |k: KeyCode| f64::from(u8::from(game.keys.contains(&k)));
    let (forward, left) = (held(KeyCode::KeyW) - held(KeyCode::KeyS), held(KeyCode::KeyA) - held(KeyCode::KeyD));
    let sneaking = game.keys.contains(&KeyCode::ShiftLeft);
    let no_slow = with(|s| s.module("No Slow").filter(|m| m.on).map(|m| [m.n("Ground %"), m.n("Air %")]));
    let using = game.using.is_some() || super::sunset_hands::legacy_using();
    let level = |id: &str| game.potions.effects.amplifier(id).map(|a| (a + 1).max(0) as u32);
    let (speed, slowness) = (level("speed"), level("slowness").is_some());
    let p = game.player.as_ref()?;
    let ground = p.ground.on_ground;
    let feet = [p.position.x.floor() as i32, p.position.y.floor() as i32, p.position.z.floor() as i32];
    let liquid = p.fluids.was_touching_water || p.is_in_lava();
    let web = [feet, [feet[0], feet[1] + 1, feet[2]]]
        .iter()
        .any(|&b| super::sunset_util::short(&super::sunset_util::facts(game, b).name) == "cobweb");
    let use_factor = if using { super::sunset_movement::item_use_factor(true, Some(no_slow.unwrap_or([20.0; 2])), ground) } else { 1.0 };
    let efficiency = game.player.as_mut()?.attribute("minecraft:water_movement_efficiency").unwrap_or(0.0);
    let depth_strider = (efficiency * 3.0).round().clamp(0.0, 3.0) as u32;
    Some((
        Input::of(forward, left, sneaking, use_factor, game.yaw),
        Allowance { web, liquid, depth_strider, sneaking, speed, slowness },
    ))
}

// Speed's NCP Hop (legacy_speed::NcpHop): this tick's move across, the hop's vertical speed written on the player
// before the tick moves it (the jump, Low hop's and Y-port's pull down).
pub(super) fn ncp_hop(game: &mut Game<'_>, m: &Module) -> Option<([f64; 2], Option<f64>)> {
    use super::sunset_legacy_speed::{HopCfg, HopFrame, allowed_distance, strafe_move};
    let (input, allowance) = legacy_strafe_frame(game)?;
    let jump_boost = game.potions.effects.amplifier("jump_boost").map_or(0, |a| (a + 1).max(0) as u32);
    let p = game.player.as_ref()?;
    let ground = p.ground.on_ground;
    let air = with(|s| {
        s.hop_air = if ground { 0 } else { s.hop_air.saturating_add(1) };
        s.hop_air
    });
    let hurt = p.health.hurt.hurt_time;
    let frame = HopFrame {
        air,
        moving: input.moving(),
        blocked: p.collision.horizontal,
        allowed: allowed_distance(allowance, input),
        vy: p.velocity.y,
        hurt: (hurt > 0).then(|| (10 - hurt).max(0) as u32),
    };
    let cfg = HopCfg {
        jump: m.n("NCP hop jump"),
        ground_speed: m.n("NCP hop ground speed"),
        slope: m.n("NCP hop slope"),
        custom_boost: m.b("NCP hop custom boost").then(|| (m.n("NCP hop boost speed"), m.n("NCP hop hurt ticks") as u32)),
        low_hop: m.b("NCP hop low hop"),
        y_port: m.b("NCP hop Y-port"),
        jump_boost,
    };
    // What the last move left (a 1.8 tick's friction on it), kept at a random 0 to 1/2000.
    let keep = super::sunset_rotation::Rng::new(game.ticks.wrapping_mul(0x9E37_79B9_7F4A_7C15) ^ 0x4E43_5048).next() / 2000.0;
    let friction = if ground { 0.6 * 0.91 } else { 0.91 };
    let (out, residual) = with(|s| (s.ncp_hop.step(frame, cfg), [s.hop_last[0] * friction, s.hop_last[1] * friction]));
    if let (Some(vy), Some(p)) = (out.vy, game.player.as_mut()) {
        p.velocity.y = vy;
    }
    let across = strafe_move(out.speed, input, residual, keep);
    with(|s| s.hop_last = across);
    Some((across, None))
}

// Restore only surplus momentum created by Watchdog's own launch. Genuine server impulses relinquish this ownership.
pub(super) fn watchdog_stop(game: &mut Game<'_>, reset: bool) {
    let owned = with(|s| if reset { s.watchdog.reset() } else { s.watchdog.suspend() });
    if !owned { return; }
    let Some(p) = game.player.as_mut() else { return };
    let Ok(attribute) = p.attribute("minecraft:movement_speed") else { return };
    let base = if p.sprinting { 0.2873 * attribute / 0.13 } else { 0.216 * attribute / 0.1 };
    let magnitude = p.velocity.x.hypot(p.velocity.z);
    if base.is_finite() && base >= 0.0 && magnitude.is_finite() && magnitude > base {
        p.velocity.x *= base / magnitude;
        p.velocity.z *= base / magnitude;
    }
}

// Speed (Sunset's): this tick's own move across the ground, blocks a tick (and Strafe's hop up), or None to leave
// it to the game. Vanilla moves the setting's blocks a second the way the move keys point, and stands still without
// them; Strafe hops, faster at each jump, slowing in the air.
pub(super) fn speed(game: &mut Game<'_>, m: &Module) -> Option<([f64; 2], Option<f64>)> {
    if m.p("Mode") != "Watchdog" { watchdog_stop(game, true); }
    let p = game.player.as_ref()?;
    let held = |k: KeyCode| game.keys.contains(&k);
    let feet = [p.position.x.floor() as i32, p.position.y.floor() as i32, p.position.z.floor() as i32];
    let mode = m.p("Mode");
    if mode != "NCP" { with(|s| s.ncp.reset()); }
    if mode != "NCP Hop" { with(|s| { s.ncp_hop.reset(); s.hop_air = 0; }); }
    if matches!(mode, "NCP" | "Watchdog") && with(|s| s.legacy_recovery.waiting(game.ticks)) {
        watchdog_stop(game, false);
        with(|s| s.ncp.recover());
        return None;
    }
    if !matches!(mode, "NCP" | "Watchdog") { with(|s| s.legacy_recovery = Default::default()); }
    let vanilla = mode == "Vanilla";
    let (flight, no_slow, pause) = with(|s| {
        let pause = s.knockback_ticks;
        s.knockback_ticks = pause.saturating_sub(1);
        let no_slow = s.module("No Slow").filter(|m| m.on).map(|m| [m.n("Ground %"), m.n("Air %")]);
        (s.is_on("Flight") && (super::sunset_flight::damage_open() || super::sunset_flight::self_falling()), no_slow, pause)
    });
    let using = game.using.is_some() || super::sunset_hands::legacy_using();
    let slow_factor = super::sunset_movement::item_use_factor(
        using, no_slow, p.ground.on_ground,
    );
    if !super::sunset_movement::speed_can_write(
        flight || p.flying, p.fall_flying, using, no_slow.is_some(),
        pause, p.collision.horizontal, m.b("Stop at wall"),
    ) {
        if matches!(mode, "NCP" | "Watchdog") { watchdog_stop(game, false); with(|s| s.ncp.recover()); }
        return None;
    }
    let scale_across = |v: [f64; 2]| [v[0] * slow_factor, v[1] * slow_factor];
    let effect = |id: &str| game.potions.effects.amplifier(id).map_or(0.0, |a| f64::from(a + 1));
    // Sunset's stopSpeed.
    if p.fall_flying
        || game.block_in_tag("minecraft:climbable", &game.block_name(feet))
        || game.riding.is_some()
        || (!m.b("When sneaking") && held(KeyCode::ShiftLeft))
        || (vanilla && m.b("Only on ground") && !p.ground.on_ground)
        || (!m.b("In liquids") && (p.fluids.was_touching_water || p.is_in_lava()))
    {
        if matches!(mode, "NCP" | "Watchdog") { watchdog_stop(game, false); with(|s| s.ncp.recover()); }
        return None;
    }
    if matches!(mode, "NCP" | "Watchdog") {
        return legacy_speed_move(game, m, slow_factor);
    }
    if mode == "NCP Hop" {
        return ncp_hop(game, m);
    }
    if mode == "Bhop" {
        let base = 0.2873 * (1.0 + 0.2 * effect("speed")) / (1.0 + 0.2 * effect("slowness"));
        return bhop(game, m, base, slow_factor);
    }
    if matches!(mode, "Smooth" | "Low Hop" | "Custom") {
        if m.b("Only on ground") && !p.ground.on_ground { return None; }
        let ground = p.ground.on_ground;
        let multiplier = if ground {
            if mode == "Custom" { m.n("Ground multiplier") } else { 1.0 }
        } else { m.n("Air multiplier") };
        let sprint = if p.sprinting { m.n("Sprint multiplier") } else { 1.0 };
        let target = m.n("Vanilla speed") / 20.0 * multiplier * sprint;
        let dir = move_direction(game);
        let up = if mode == "Low Hop" && ground && dir.is_some()
            && !held(KeyCode::Space) && !held(KeyCode::ShiftLeft)
        { Some(m.n("Jump height")) } else { None };
        let across = if mode == "Low Hop" {
            dir.map_or([0.0; 2], |d| {
                let speed = target.min(m.n("Max speed"));
                [d[0] * speed, d[1] * speed]
            })
        } else {
            super::sunset_movement::steer(
                [p.velocity.x, p.velocity.z], dir, target, m.n("Acceleration"),
                m.n("Deceleration"), m.n("Strafe strength"), m.n("Max speed"),
            )
        };
        return Some((scale_across(across), up));
    }
    let yaw = f64::from(game.yaw).to_radians();
    if vanilla {
        // Horizontal velocity from the keys, with the Speed effect's boost.
        let (forward, right) = ([-yaw.sin(), yaw.cos()], [-yaw.cos(), -yaw.sin()]);
        let f = f64::from(i8::from(held(KeyCode::KeyW)) - i8::from(held(KeyCode::KeyS)));
        let r = f64::from(i8::from(held(KeyCode::KeyD)) - i8::from(held(KeyCode::KeyA)));
        let diagonal = if (held(KeyCode::KeyW) || held(KeyCode::KeyS)) && (held(KeyCode::KeyA) || held(KeyCode::KeyD)) { std::f64::consts::FRAC_1_SQRT_2 } else { 1.0 };
        let k = m.n("Vanilla speed") / 20.0 * diagonal * (1.0 + effect("speed") * 0.205);
        return Some((scale_across([(forward[0] * f + right[0] * r) * k, (forward[1] * f + right[1] * r) * k]), None));
    }
    let base = 0.2873 * (1.0 + 0.2 * effect("speed")) / (1.0 + 0.2 * effect("slowness"));
    let forward = f64::from(i8::from(held(KeyCode::KeyW)) - i8::from(held(KeyCode::KeyS)));
    let side = f64::from(i8::from(held(KeyCode::KeyA)) - i8::from(held(KeyCode::KeyD)));
    let moving = forward != 0.0 || side != 0.0;
    let distance = (p.position.x - game.previous_position.x).hypot(p.position.z - game.previous_position.z);
    let (ground, landing) = (p.ground.on_ground, p.ground.on_ground || p.collision.vertical);
    let (strafe_speed, limit) = (m.n("Strafe speed"), m.b("Speed limit"));
    let (speed, up) = with(|s| {
        let st = &mut s.strafe;
        st.distance = distance;
        let mut up = None;
        match st.stage {
            0 => {
                if moving {
                    st.stage = 1;
                    st.speed = 1.18 * base - 0.01;
                }
            }
            1 => {
                if moving && ground {
                    up = Some(0.40123128 + effect("jump_boost") * 0.1);
                    st.speed *= strafe_speed;
                    st.stage = 2;
                }
            }
            2 => {
                st.speed = st.distance - 0.76 * (st.distance - base);
                st.stage = 3;
            }
            _ => {
                if landing {
                    st.stage = 0;
                }
                st.speed = st.distance - st.distance / 159.0;
            }
        }
        st.speed = st.speed.max(base);
        if limit {
            let now = std::time::Instant::now();
            let since = *st.since.get_or_insert(now);
            if now.duration_since(since).as_millis() > 2500 {
                st.since = Some(now);
            }
            let held_for = now.duration_since(st.since.unwrap_or(now)).as_millis();
            st.speed = st.speed.min(if held_for > 1250 { 0.44 } else { 0.43 });
        }
        (st.speed, up)
    });
    // Strafe.transformStrafe: the speed the way the move keys point.
    if !moving {
        return Some((scale_across([0.0; 2]), up));
    }
    let mut turn = 90.0 * side.signum();
    if forward != 0.0 {
        turn *= forward.signum() * 0.5;
    }
    let mut dir = f64::from(game.yaw) - turn;
    if forward < 0.0 {
        dir -= 180.0;
    }
    let dir = dir.to_radians();
    Some((scale_across([-dir.sin() * speed, dir.cos() * speed]), up))
}

// An explosion packet's push on the player, as it arrives (before the game adds it).
pub(super) fn explosion_push(game: &mut Game<'_>, push: Option<[f64; 3]>) {
    if let Some(push) = push {
        with(|s| { s.watchdog.reset(); }); // Preserve the explosion; it is not a damage-steering event.
        super::sunset_render::no_slow_knocked();
        let shares = with(|s| {
            s.knockback_ticks = s.module("Speed").filter(|m| m.on).map_or(0, |m| m.n("Knockback pause") as u32);
            s.module("Velocity").filter(|m| m.on && m.b("Explosions"))
                .map(|m| [velocity_share(m, "Explosions horizontal"), velocity_share(m, "Explosions vertical")])
        });
        horizon_client::motion::sunset_motion::set_across(None);
        horizon_client::motion::sunset_motion::set_up(None);
        if let (Some([h, v]), Some(p)) = (shares, game.player.as_mut()) {
            // Horizon adds the original push after this hook; this leaves the chosen share.
            p.velocity.x += push[0] * (h - 1.0);
            p.velocity.y += push[1] * (v - 1.0);
            p.velocity.z += push[2] * (h - 1.0);
            let after = [p.velocity.x + push[0], p.velocity.y + push[1], p.velocity.z + push[2]];
            with(|s| { s.velocity = Some(after); s.blast = [0.0; 3]; });
        } else {
            with(|s| (0..3).for_each(|i| s.blast[i] += push[i]));
        }
    }
}

// Velocity (Sunset's), before the tick moves the player: of what changed the velocity since the last tick, the
// explosions' pushes keep their share and the rest, the server's knockback, its own; flowing liquids push by their
// share (the flow hook), and of the entities pushing you only the push amount is left.
pub(super) fn velocity(game: &mut Game<'_>, m: Option<&Module>) {
    use horizon_client::motion::sunset_motion as motion;
    let (last, blast) = with(|s| (s.velocity.take(), std::mem::take(&mut s.blast)));
    if let (Some(last), Some(p)) = (last, game.player.as_ref()) {
        let impulse = [p.velocity.x - last[0] - blast[0], p.velocity.y - last[1] - blast[1], p.velocity.z - last[2] - blast[2]];
        if game.remote.is_some() && impulse[0].hypot(impulse[2]).hypot(impulse[1]) > 0.08 {
            // Bhop's Damage boost takes the knockback's speed across the ground.
            let kick = impulse[0].hypot(impulse[2]);
            with(|s| {
                let (pause, bhop, hop) = s.module("Speed").filter(|m| m.on).map_or((0, false, false), |m| {
                    (m.n("Knockback pause") as u32, m.p("Mode") == "Bhop", m.p("Mode") == "NCP Hop" && m.b("Damage boost"))
                });
                s.knockback_ticks = if hop { 0 } else { pause };
                if bhop {
                    s.bhop.kick = s.bhop.kick.max(kick);
                }
                if hop {
                    s.ncp_hop.knocked(kick);
                }
            });
        }
    }
    let share = |on: &str, h: &str, v: &str| m.filter(|m| m.b(on)).map_or([1.0; 2], |m| [velocity_share(m, h), velocity_share(m, v)]);
    let liquids = m.filter(|m| m.b("Liquids")).map(|m| [velocity_share(m, "Liquids horizontal"), velocity_share(m, "Liquids vertical")]);
    motion::set_liquid_flow(liquids);
    let Some(m) = m else {
        return;
    };
    let pushed = if m.b("Entity push") { entity_push(game) } else { [0.0; 2] };
    let ground = game.player.as_ref().is_some_and(|p| p.ground.on_ground);
    // Knockback chance: each knockback is cut with that chance, else taken whole.
    let roll = super::sunset_rotation::Rng::new(game.ticks.wrapping_mul(0x9E37_79B9_7F4A_7C15) ^ 0x7E10).next() * 100.0;
    let knock =
        if m.b("Knockback") && roll < m.n("Knockback chance (%)") { knockback_shares(m, ground) } else { [1.0; 2] };
    with(|s| s.watchdog.filtered_knockback(game.ticks, knock[0]));
    let blasts = share("Explosions", "Explosions horizontal", "Explosions vertical");
    let Some(p) = game.player.as_mut() else {
        return;
    };
    let mut v = [p.velocity.x, p.velocity.y, p.velocity.z];
    if let Some(last) = last {
        for i in 0..3 {
            let (k, b) = if i == 1 { (knock[1], blasts[1]) } else { (knock[0], blasts[0]) };
            v[i] = last[i] + (v[i] - last[i] - blast[i]) * k + blast[i] * b;
        }
    }
    // The game adds the pushes later in the tick: take back what the push amount does not keep.
    let keep = velocity_share(m, "Entity push amount");
    v[0] -= pushed[0] * (1.0 - keep);
    v[2] -= pushed[1] * (1.0 - keep);
    (p.velocity.x, p.velocity.y, p.velocity.z) = (v[0], v[1], v[2]);
}

// The entities' push on the player this tick, x and z (the game's `LivingEntity.pushEntities` with
// `Entity.push(Entity)`): every living one but bats whose box overlaps yours, pushable by your team.
fn entity_push(game: &Game<'_>) -> [f64; 2] {
    let Some(p) = game.player.as_ref() else {
        return [0.0; 2];
    };
    let (bounds, own) = (p.bounds(), own_id(game));
    let team = game.score.board.players_team(&game.options.player_name());
    let mut push = [0.0; 2];
    for m in &game.mobs {
        if Some(m.id) == own
            || !m.alive()
            || m.species() == horizon_client::mobs::Species::Bat
            || game.riding.is_some_and(|v| v == m.id || m.extra.mount == Some(v))
            || !m.bounds().intersects(bounds)
            || !horizon_client::scoreboard::pushable_by(game.mob_team(m.id), team, true)
        {
            continue;
        }
        let (mut xa, mut za) = (m.position.x - p.position.x, m.position.z - p.position.z);
        let dd = xa.abs().max(za.abs());
        if dd < f64::from(0.01_f32) {
            continue;
        }
        let dd = dd.sqrt();
        let pow = (1.0 / dd).min(1.0) * f64::from(0.05_f32);
        xa = xa / dd * pow;
        za = za / dd * pow;
        push[0] -= xa;
        push[1] -= za;
    }
    push
}

// Runtime part (see runtime.rs): world and entity overlays, trajectories and storage.

use super::Game;
use super::sunset_visual::{Draw, Kinds, Look, distance_colour, draw_box, faded, potato};
use std::fmt::Write as _;
use super::sunset::*;

pub(super) fn world_overlays(game: &Game<'_>, cam: &Camera, mods: &[Module], lw: f32, out: &mut impl Canvas) {
    super::sunset_explosive_aura::draw(game, cam, mods, out, lw);
    super::sunset_lag::draw(game, cam, mods, out, lw);
    super::sunset_backtrack::draw(cam, mods, out, lw);
    super::sunset_block_overlay::overlay(game, cam, mods, out, lw);
    super::sunset_util::draw_shown(cam, out, lw);
    super::sunset_effects::draw(game, cam, mods, out);
    super::sunset_render::overlay(game, cam, mods, out, lw);
    super::sunset_new_chunks::draw(cam, mods, out);
    super::sunset_ore_sim::draw(game, cam, mods, out, lw);
    super::sunset_hunting::draw(cam, mods, out, lw);
    super::sunset_light_scan::draw(cam, mods, out, lw);
    super::sunset_sound_detector::draw(game, cam, mods, out, lw);
    let get = |n: &str| mods.iter().find(|m| m.name == n && m.on);
    if let Some(m) = get("Nuker") {
        let (look, argb) = (Look::of(m), m.c("Broken color"));
        with(|s| {
            if let Some([lo, hi]) = s.nuke_box.filter(|_| m.b("Bounding box") && m.p("Mode") != "Smash") {
                draw_box(cam, out, &look, lo, hi, m.c("Box color"), lw);
            }
            for &(pos, left) in &s.nuke_broken {
                let lo = [f64::from(pos[0]), f64::from(pos[1]), f64::from(pos[2])];
                let a = ((argb >> 24) * u32::from(left) / 8) << 24;
                draw_box(cam, out, &look, lo, [lo[0] + 1.0, lo[1] + 1.0, lo[2] + 1.0], a | (argb & 0x00FF_FFFF), lw);
            }
        });
    }
    if let Some(m) = get("Scaffold").filter(|m| m.b("Render")) {
        let (look, argb) = (Look::of(m), m.c("Color"));
        with(|s| {
            for &(pos, left) in &s.scaffold_placed {
                let lo = [f64::from(pos[0]), f64::from(pos[1]), f64::from(pos[2])];
                let a = ((argb >> 24) * u32::from(left) / 8) << 24;
                draw_box(cam, out, &look, lo, [lo[0] + 1.0, lo[1] + 1.0, lo[2] + 1.0], a | (argb & 0x00FF_FFFF), lw);
            }
        });
    }
    let alpha = game.clock.camera_fraction();
    let lerp = |a: f64, b: f64| a + alpha * (b - a);
    let dist = |at: [f64; 3]| {
        let d = [at[0] - cam.pos[0], at[1] - cam.pos[1], at[2] - cam.pos[2]];
        (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt()
    };
    let (esp, tracers, tags) = (get("ESP"), get("Tracers"), get("Nametags"));
    // The players Nametags tags this frame, and where: Gear ESP's rows go above them.
    let mut tagged: Vec<(u32, [f32; 2])> = Vec::new();
    if esp.is_some() || tracers.is_some() || tags.is_some() {
        entity_overlays(game, cam, [esp, tracers, tags], lw, out, &mut tagged);
    }
    super::sunset_gear::draw(game, cam, mods, out, lw, &tagged);
    // Text drawn from one buffer, written over for each label.
    let mut text = String::new();

    if let Some(m) = esp.filter(|m| m.b("Items")) {
        let (look, colour, range, fade) = (Look::of(m), m.c("Items color"), range_of(m), m.n("Fade distance"));
        let (names, lines, filter, list) = (m.b("Item names"), m.b("Item tracers"), m.p("Item filter"), m.t("Item list"));
        let middle = [cam.w as f32 / 2.0, cam.h as f32 / 2.0];
        for item in &game.dropped {
            if filter != "All" && super::sunset_util::listed(list, &item.stack.item) != (filter == "Whitelist") {
                continue;
            }
            let at = [
                lerp(item.previous.x, item.position.x),
                lerp(item.previous.y, item.position.y),
                lerp(item.previous.z, item.position.z),
            ];
            let d = dist(at);
            if d > range {
                continue;
            }
            let lo = [at[0] - 0.125, at[1], at[2] - 0.125];
            let hi = [at[0] + 0.125, at[1] + 0.25, at[2] + 0.125];
            let colour = faded(colour, d, fade);
            draw_box(cam, out, &look, lo, hi, colour, lw);
            let Some([x, y]) = (names || lines).then(|| cam.project([at[0], at[1] + 0.25, at[2]])).flatten() else {
                continue;
            };
            if lines {
                line(out, middle, [x, y], colour, lw);
            }
            // Its name as the game shows it (a custom name, else the translated one) and the stack's count.
            if names {
                text.clear();
                text.push_str(&horizon_client::item_tooltip::name_line(&item.stack, &|key| game.pack.names.display_get(key)));
                if item.stack.count > 1 {
                    let _ = write!(text, " x{}", item.stack.count);
                }
                let tw = game.native_text_width(&text);
                out.fill([x - tw / 2.0 - 2.0, y - 14.0, tw + 4.0, 12.0], 0x7800_0000);
                out.text(&text, [x - tw / 2.0, y - 12.0], colour & 0x00FF_FFFF);
            }
        }
    }

    if let Some(m) = get("Storage ESP") {
        let (look, range, fade, max) = (Look::of(m), m.n("Range"), m.n("Fade distance"), m.n("Max") as usize);
        let want = [m.b("Ender chests"), m.b("Chests"), m.b("Barrels"), m.b("Shulkers"), m.b("Other")];
        let facts = game.res.facts();
        let mut drawn = 0;
        for &(x, y, z) in game.world.block_entities.keys() {
            let at = [f64::from(x) + 0.5, f64::from(y) + 0.5, f64::from(z) + 0.5];
            let d = dist(at);
            // Out of range or off screen: nothing more is looked up.
            if d > range || !cam.sees(at, 0.87) {
                continue;
            }
            let name = &facts.get(game.world.block(x, y, z)).name;
            let Some(col) = storage_colour(name) else {
                continue;
            };
            let short = name.strip_prefix("minecraft:").unwrap_or(name);
            let group = if short == "ender_chest" {
                0
            } else if short.ends_with("chest") {
                1
            } else if short == "barrel" {
                2
            } else if short.ends_with("shulker_box") {
                3
            } else {
                4
            };
            if !want[group] {
                continue;
            }
            let inset = if name.ends_with("chest") { 0.0625 } else { 0.0 };
            let (lo, hi) = match chest_pair(game, [x, y, z]) {
                Some(Some(pair)) => pair,
                Some(None) => continue,
                None => (
                    [f64::from(x) + inset, f64::from(y), f64::from(z) + inset],
                    [f64::from(x + 1) - inset, f64::from(y + 1) - inset * 2.0, f64::from(z + 1) - inset],
                ),
            };
            if draw_box(cam, out, &look, lo, hi, faded(col, d, fade), lw) {
                drawn += 1;
                if drawn >= max {
                    break;
                }
            }
        }
    }

    if let Some(m) = get("Breadcrumbs") {
        let (dots, colour) = (m.p("Mode") == "Potato", 0xFF00_0000 | accent());
        let now = game.player.as_ref().map(|p| [p.position.x, p.position.y + 0.1, p.position.z]);
        with(|s| {
            let mut last: Option<[f32; 2]> = None;
            // To where you are now at the end.
            for point in s.crumbs.iter().chain(now.as_ref()) {
                if dots {
                    potato(cam, out, *point, colour, lw);
                    continue;
                }
                let next = cam.project(*point);
                if let (Some(a), Some(b)) = (last, next) {
                    line(out, a, b, colour, lw);
                }
                last = next;
            }
        });
    }

    if let Some(m) = get("Block ESP") {
        let (look, range, max) = (Look::of(m), m.n("Range") * 1.5, m.n("Max") as usize);
        with(|s| {
            let mut drawn = 0;
            for &(pos, col) in &s.blocks.found {
                let lo = [f64::from(pos[0]), f64::from(pos[1]), f64::from(pos[2])];
                if dist([lo[0] + 0.5, lo[1] + 0.5, lo[2] + 0.5]) > range {
                    continue;
                }
                if draw_box(cam, out, &look, lo, [lo[0] + 1.0, lo[1] + 1.0, lo[2] + 1.0], col, lw) {
                    drawn += 1;
                    if drawn >= max {
                        break;
                    }
                }
            }
        });
    }

    if let Some(m) = get("Logout Spots") {
        let look = Look::of(m);
        let here = game.native_player().map(|p| p.dimension);
        with(|s| {
            for sp in s.spots.iter().filter(|sp| Some(sp.dim.as_str()) == here) {
                let lo = [sp.pos[0] - 0.3, sp.pos[1], sp.pos[2] - 0.3];
                let hi = [sp.pos[0] + 0.3, sp.pos[1] + 1.8, sp.pos[2] + 0.3];
                if !draw_box(cam, out, &look, lo, hi, 0xFFFF_5050, lw) || look.draw == Draw::Potato {
                    continue;
                }
                if let Some([x, y]) = cam.project([sp.pos[0], sp.pos[1] + 2.2, sp.pos[2]]) {
                    text.clear();
                    let _ = write!(text, "{} logged out {}m ago", sp.name, game.ticks.saturating_sub(sp.at) / 1200);
                    let tw = game.native_text_width(&text);
                    out.fill([x - tw / 2.0 - 2.0, y - 2.0, tw + 4.0, 12.0], 0x7800_0000);
                    out.text(&text, [x - tw / 2.0, y], 0xFF5555);
                }
            }
        });
    }

    if let Some(m) = get("Spawner Alerts").filter(|m| m.b("Labels")) {
        super::sunset_world::spawner_labels(game, cam, m.n("Range"), out);
    }

    if let Some(m) = get("Trajectories") {
        trajectory(game, cam, m, out, lw);
    }

    if let Some(m) = get("Hole ESP") {
        let (look, height, max) = (Look::of(m), m.n("Height").max(0.02), m.n("Max") as usize);
        let colours = [m.c("Bedrock color"), m.c("Obsidian color"), m.c("Mixed color")];
        with(|s| {
            let mut drawn = 0;
            for &(pos, kind) in &s.holes.found {
                let lo = [f64::from(pos[0]), f64::from(pos[1]), f64::from(pos[2])];
                if draw_box(cam, out, &look, lo, [lo[0] + 1.0, lo[1] + height, lo[2] + 1.0], colours[usize::from(kind)], lw) {
                    drawn += 1;
                    if drawn >= max {
                        break;
                    }
                }
            }
        });
    }

    if let Some(m) = get("Waypoints") {
        let (range, dots, colour) = (m.n("Range"), m.p("Mode") == "Potato", 0xFF00_0000 | accent());
        let here = game.native_player().map(|p| p.dimension);
        with(|s| {
            for w in s.waypoints.iter().filter(|w| Some(w.dim.as_str()) == here) {
                let d = dist(w.pos);
                if d > range {
                    continue;
                }
                if dots {
                    potato(cam, out, w.pos, colour, lw);
                    continue;
                }
                let Some([x, y]) = cam.project(w.pos).filter(|p| cam.on_screen(*p, 200.0)) else {
                    continue;
                };
                text.clear();
                let _ = write!(text, "{} {}m", w.name, d.round());
                let tw = game.native_text_width(&text);
                out.fill([x - tw / 2.0 - 2.0, y - 2.0, tw + 4.0, 12.0], 0x7800_0000);
                out.text(&text, [x - tw / 2.0, y], accent());
                out.fill([x - 1.0, y + 11.0, 2.0, 4.0], colour);
            }
        });
    }
}

// ESP's, Tracers' and Nametags' Range: 0 (shown "All") draws everything loaded, else a limit up to this.
pub(super) const ALL_RANGE_MAX: f64 = 512.0;

// A Range setting as a distance: 0 is no limit.
fn range_of(m: &Module) -> f64 {
    match m.n("Range") {
        r if r <= 0.0 => f64::INFINITY,
        r => r,
    }
}

// The settings ESP, Tracers and Nametags draw with, read once a frame.
struct EntityLook {
    pub(super) kinds: Kinds,
    pub(super) look: Look,
    pub(super) range: f64,
    pub(super) max: usize,
    fade: f64,
    potato: bool,
}

impl EntityLook {
    pub(super) fn of(m: &Module) -> Self {
        let look = Look::of(m);
        Self {
            kinds: Kinds::of(m),
            potato: look.draw == Draw::Potato,
            look,
            range: range_of(m),
            max: m.n("Max") as usize,
            fade: m.n("Fade distance"),
        }
    }
}

// ESP, Tracers and Nametags in one pass over the mobs: those in range of any of them, nearest first when a Max
// leaves some out.
fn entity_overlays(game: &Game<'_>, cam: &Camera, mods: [Option<&Module>; 3], lw: f32, out: &mut impl Canvas, tagged: &mut Vec<(u32, [f32; 2])>) {
    let [esp, tracers, tags] = mods.map(|m| m.map(EntityLook::of));
    let two = mods[0].map(super::sunset_esp2d::TwoD::of);
    // ESP's Murderer finder: its suspects in the Murderer color.
    let murderer = mods[0].filter(|m| m.b("Murderer finder")).map(|m| m.c("Murderer color"));
    let tags_module = mods[2];
    let banded = tags_module.is_some_and(|m| m.p("Health colors") == "Bands");
    let (tracer_target, tracer_bottom, tracer_by_distance) =
        mods[1].map_or(("Body", false, false), |m| (m.p("Target"), m.p("Start") == "Bottom", m.b("Distance colors")));
    let (tag_players, tag_mobs, tag_friends) =
        tags_module.map_or((false, false, false), |m| (m.b("Players"), m.b("Mobs"), !m.b("Ignore friends")));
    let tag_extra = tags_module.map_or(("", false), |m| (m.t("Entities"), m.p("List mode") == "Blacklist"));
    let (show_health, show_distance, tag_back, tag_colour) =
        tags_module.map_or((false, false, false, 0), |m| (m.b("Health"), m.b("Distance"), m.b("Background"), m.c("Name color") & 0x00FF_FFFF));
    let show_pops = tags_module.is_some_and(|m| m.b("Totem pops"));
    let looks = [&esp, &tracers, &tags];
    let range = looks.iter().filter_map(|l| l.as_ref().map(|l| l.range)).fold(0.0, f64::max);
    let alpha = game.clock.camera_fraction();
    let lerp = |a: f64, b: f64| a + alpha * (b - a);
    let own = own_id(game);
    // The mobs in range: distance, index, and the box where the frame draws them.
    let mut near: Vec<(f64, usize, [f64; 3], [f64; 3])> = Vec::with_capacity(game.mobs.len());
    for (i, mob) in game.mobs.iter().enumerate() {
        if !mob.alive() || mob.removed || Some(mob.id) == own {
            continue;
        }
        let b = mob.bounds();
        let (lo, hi) = (b.min_position(), b.max_position());
        let off = [
            lerp(mob.previous.x, mob.position.x) - mob.position.x,
            lerp(mob.previous.y, mob.position.y) - mob.position.y,
            lerp(mob.previous.z, mob.position.z) - mob.position.z,
        ];
        let lo = [lo.x + off[0], lo.y + off[1], lo.z + off[2]];
        let hi = [hi.x + off[0], hi.y + off[1], hi.z + off[2]];
        let mid = [(lo[0] + hi[0]) / 2.0, (lo[1] + hi[1]) / 2.0, (lo[2] + hi[2]) / 2.0];
        let d = super::sunset_util::dist(mid, cam.pos);
        if d <= range {
            near.push((d, i, lo, hi));
        }
    }
    if looks.iter().any(|l| l.as_ref().is_some_and(|l| l.max < near.len())) {
        near.sort_unstable_by(|a, b| a.0.total_cmp(&b.0));
    }
    // Friends only matter to the full modes.
    let friendly = esp.as_ref().is_some_and(|l| !l.potato) || tracers.as_ref().is_some_and(|l| !l.potato) || tags.is_some();
    let names = if friendly { game.remote_player_names() } else { Vec::new() };
    let friends = if friendly { with(|s| s.friends.clone()) } else { Vec::new() };
    let centre = [cam.w as f32 / 2.0, cam.h as f32 / 2.0];
    let from = if tracer_bottom { [centre[0], cam.h as f32] } else { centre };
    let mut drawn = [0usize; 3];
    let (mut name, mut hp, mut tail) = (String::new(), String::new(), String::new());
    for &(d, i, lo, hi) in &near {
        let mob = &game.mobs[i];
        let kind = kind_of(mob);
        let mid = [(lo[0] + hi[0]) / 2.0, (lo[1] + hi[1]) / 2.0, (lo[2] + hi[2]) / 2.0];
        let friend = || kind == Kind::Player && is_friend(&friends, &names, mob.id);
        if let Some(l) = &esp
            && drawn[0] < l.max
            && d <= l.range
            && l.kinds.wants(kind, &mob.kind.id)
        {
            let col = if l.potato { l.kinds.colour(kind, false) } else { faded(l.kinds.colour(kind, friend()), d, l.fade) };
            let shield = two.as_ref().filter(|_| !l.potato).and_then(|t| super::sunset_esp2d::shield_colour(game, t, mob));
            let col = shield.map_or(col, |c| faded(c, d, l.fade));
            let col = match &murderer {
                Some(c) if kind == Kind::Player && super::sunset_murder::suspect(mob.id) => faded(*c, d, l.fade),
                _ => col,
            };
            let shown = match two.as_ref().filter(|t| l.look.draw == Draw::Box2d && t.extras()) {
                Some(t) => super::sunset_esp2d::draw(game, cam, out, t, mob, lo, hi, d, col, lw),
                None => draw_box(cam, out, &l.look, lo, hi, col, lw),
            };
            if shown {
                drawn[0] += 1;
            }
        }
        if let Some(l) = &tracers
            && drawn[1] < l.max
            && d <= l.range
            && l.kinds.wants(kind, &mob.kind.id)
        {
            // Potato: the line alone, to the middle, in the kind's colour.
            let (aim, col) = if l.potato {
                (mid, l.kinds.colour(kind, false))
            } else {
                let aim = match tracer_target {
                    "Head" => [mid[0], hi[1] - 0.1, mid[2]],
                    "Feet" => [mid[0], lo[1], mid[2]],
                    _ => mid,
                };
                (aim, if tracer_by_distance { distance_colour(d) } else { l.kinds.colour(kind, friend()) })
            };
            if let Some(to) = cam.project(aim) {
                line(out, from, to, col, lw);
                drawn[1] += 1;
            }
        }
        if let Some(l) = &tags
            && drawn[2] < l.max
            && d <= l.range
            && super::sunset_util::kind_wanted(if kind == Kind::Player { tag_players } else { tag_mobs }, tag_extra.0, tag_extra.1, &mob.kind.id)
        {
            let top = [mid[0], hi[1] + 0.6, mid[2]];
            if !cam.sees(top, 1.0) {
                continue;
            }
            let friend = friend();
            if friend && !tag_friends {
                continue;
            }
            let Some([x, y]) = cam.project(top) else {
                continue;
            };
            drawn[2] += 1;
            super::sunset_util::name_into(game, mob, &mut name);
            let name_colour = if friend { 0x55FFFF } else { tag_colour };
            let nw = game.native_text_width(&name);
            if kind == Kind::Player {
                tagged.push((mob.id, [x, y - 2.0]));
            }
            // Potato: the name alone.
            if l.potato {
                out.text(&name, [x - nw / 2.0, y], name_colour);
                continue;
            }
            hp.clear();
            tail.clear();
            // Whole numbers written as integers: float formatting was a good part of a frame of 200 tags.
            // Bands: the health rounded up, red to 5, gold to 10, yellow to 15, green to 20, dark green over.
            if show_health && banded {
                let _ = write!(hp, "{}", mob.health.max(0.0).ceil() as i32);
            } else if show_health {
                let tenths = (mob.health * 10.0).round() as i32;
                let _ = write!(hp, "{}", tenths / 10);
                if tenths % 10 != 0 {
                    let _ = write!(hp, ".{}", (tenths % 10).abs());
                }
            }
            let popped = if show_pops { super::sunset_effects::pops(mob.id) } else { 0 };
            if popped > 0 {
                let _ = write!(tail, " -{popped}");
            }
            if show_distance {
                let _ = write!(tail, " {}m", d.round() as i64);
            }
            let (hw, tw) = (game.native_text_width(&hp), game.native_text_width(&tail));
            let gap = if hp.is_empty() { 0.0 } else { 4.0 };
            let total = nw + gap + hw + tw;
            let x0 = x - total / 2.0;
            if tag_back {
                out.fill([x0 - 2.0, y - 2.0, total + 4.0, 12.0], 0x7800_0000);
            }
            out.text(&name, [x0, y], name_colour);
            if !hp.is_empty() {
                let colour = if banded {
                    match mob.health.ceil() {
                        h if h <= 5.0 => 0xFF5555,
                        h if h <= 10.0 => 0xFFAA00,
                        h if h <= 15.0 => 0xFFFF55,
                        h if h <= 20.0 => 0x55FF55,
                        _ => 0x00AA00,
                    }
                } else {
                    health_colour(mob.health / mob.kind.max_health.max(1.0))
                };
                out.text(&hp, [x0 + nw + gap, y], colour);
            }
            if !tail.is_empty() {
                out.text(&tail, [x0 + nw + gap + hw, y], 0xAAAAAA);
            }
        }
    }
}

// Where what the player holds would land: a bow being drawn, a loaded crossbow (each of a multishot's three arrows),
// or a throwable, as Show lets through; with Pearls in flight, every pearl in the air too, and with Landing time how
// long each has left. Potato: only a square where it lands.
pub(super) fn trajectory(game: &Game<'_>, cam: &Camera, m: &Module, out: &mut impl Canvas, lw: f32) {
    let potato_only = m.p("Mode") == "Potato";
    let colour = 0xFF00_0000 | accent();
    if m.b("Pearls in flight") {
        let ids: Vec<u32> = game
            .creatures
            .projectiles
            .iter()
            .filter(|p| p.kind == horizon_client::projectiles::ProjectileKind::EnderPearl && !p.stuck)
            .map(|p| p.id)
            .collect();
        for id in ids {
            let Some(f) = super::sunset_throws::pearl_landing(game, id, 400, true) else {
                continue;
            };
            draw_path(cam, out, &f.path, potato_only, colour, lw);
            if m.b("Landing time")
                && let Some([x, y]) = cam.project(f.land).filter(|p| cam.on_screen(*p, 50.0))
            {
                let tag = format!("{:.1}s", f64::from(f.ticks) / 20.0);
                let tw = game.native_text_width(&tag);
                out.fill([x - tw / 2.0 - 2.0, y - 14.0, tw + 4.0, 12.0], 0x7800_0000);
                out.text(&tag, [x - tw / 2.0, y - 12.0], colour);
            }
        }
    }
    let Some(stack) = game.held() else {
        return;
    };
    let name = stack.item.strip_prefix("minecraft:").unwrap_or(&stack.item);
    let show = m.p("Show");
    let wanted = match name {
        "bow" => matches!(show, "All" | "Bows" | "Bow"),
        "crossbow" => matches!(show, "All" | "Bows" | "Crossbow"),
        "ender_pearl" => matches!(show, "All" | "Pearl"),
        _ => show == "All",
    };
    if !wanted {
        return;
    }
    let charged = || stack.data().map_or(0, |d| d.charged.len());
    let (speed, gravity, drag, spread): (f64, f64, f64, &[f32]) = match name {
        "bow" => match game.using {
            Some((_, ticks)) => {
                let t = f64::from(ticks) / 20.0;
                (((t * t + t * 2.0) / 3.0).min(1.0) * 3.0, 0.05, 0.99, &[0.0])
            }
            None => return,
        },
        "crossbow" if charged() > 0 => {
            let rocket = stack.data().is_some_and(|d| d.charged.iter().any(|a| a.item.ends_with("firework_rocket")));
            let fan: &[f32] = if charged() > 1 { &[-10.0, 0.0, 10.0] } else { &[0.0] };
            if rocket { (1.6, 0.0, 1.0, fan) } else { (3.15, 0.05, 0.99, fan) }
        }
        "trident" => (2.5, 0.05, 0.99, &[0.0]),
        "ender_pearl" | "snowball" | "egg" => (1.5, 0.03, 0.99, &[0.0]),
        "wind_charge" => (1.5, 0.0, 1.0, &[0.0]),
        "splash_potion" | "lingering_potion" => (0.5, 0.05, 0.99, &[0.0]),
        "experience_bottle" => (0.7, 0.07, 0.99, &[0.0]),
        _ => return,
    };
    let Some(eye) = game.eye_position() else {
        return;
    };
    for turn in spread {
        let (yaw, pitch) = (f64::from(game.yaw + turn).to_radians(), f64::from(game.pitch).to_radians());
        let dir = [-yaw.sin() * pitch.cos(), -pitch.sin(), yaw.cos() * pitch.cos()];
        let mut pos = [eye[0], eye[1] - 0.1, eye[2]];
        let mut vel = [dir[0] * speed, dir[1] * speed, dir[2] * speed];
        let mut path = vec![pos];
        for _ in 0..200 {
            for i in 0..3 {
                pos[i] += vel[i];
                vel[i] *= drag;
            }
            vel[1] -= gravity;
            path.push(pos);
            if solid_at(game, pos[0].floor() as i32, pos[1].floor() as i32, pos[2].floor() as i32) || pos[1] < -80.0 {
                break;
            }
        }
        draw_path(cam, out, &path, potato_only, colour, lw);
    }
}

// A flight drawn as a line ending in a small box where it lands, or (Potato) a square there alone.
fn draw_path(cam: &Camera, out: &mut impl Canvas, path: &[[f64; 3]], potato_only: bool, colour: u32, lw: f32) {
    let Some(&end) = path.last() else {
        return;
    };
    if potato_only {
        potato(cam, out, end, colour, lw);
        return;
    }
    for pair in path.windows(2) {
        if let (Some(a), Some(b)) = (cam.project(pair[0]), cam.project(pair[1])) {
            line(out, a, b, colour, lw);
        }
    }
    draw_box(cam, out, &Look::BOXED, [end[0] - 0.25, end[1] - 0.25, end[2] - 0.25], [end[0] + 0.25, end[1] + 0.25, end[2] + 0.25], colour, lw);
}

// A double chest (or trapped or copper one) is one box: each half's outline reaches the side its other half is on.
// The half to the west or north draws the pair's box (Some(Some(box))), the other half nothing (Some(None)); a single
// chest or any other block: None.
fn chest_pair(game: &Game<'_>, p: [i32; 3]) -> Option<Option<([f64; 3], [f64; 3])>> {
    use super::sunset_util::facts;
    let here = facts(game, p);
    if !here.name.ends_with("chest") {
        return None;
    }
    let b = *here.outline.first()?;
    let side = if b[0] <= 0.0 { [-1, 0] } else if b[3] >= 1.0 { [1, 0] } else if b[2] <= 0.0 { [0, -1] } else if b[5] >= 1.0 { [0, 1] } else { return None };
    let at = [p[0] + side[0], p[1], p[2] + side[1]];
    let there = facts(game, at);
    let o = *there.outline.first()?;
    // The other half reaches back.
    let back = match side {
        [-1, 0] => o[3] >= 1.0,
        [1, 0] => o[0] <= 0.0,
        [0, -1] => o[5] >= 1.0,
        _ => o[2] <= 0.0,
    };
    if there.name != here.name || !back {
        return None;
    }
    if side[0] < 0 || side[1] < 0 {
        return Some(None);
    }
    let corner = |q: [i32; 3], f: [f64; 3]| [f64::from(q[0]) + f[0], f64::from(q[1]) + f[1], f64::from(q[2]) + f[2]];
    Some(Some((corner(p, [b[0], b[1], b[2]]), corner(at, [o[3], o[4], o[5]]))))
}

pub(super) fn storage_colour(name: &str) -> Option<u32> {
    let n = name.strip_prefix("minecraft:").unwrap_or(name);
    Some(if n == "ender_chest" {
        0xFFB0_50FF
    } else if n == "chest" || n == "trapped_chest" || n.ends_with("copper_chest") {
        0xFFFF_A040
    } else if n.ends_with("shulker_box") {
        0xFFFF_70C0
    } else if n == "barrel" {
        0xFFC0_8040
    } else if matches!(n, "hopper" | "dropper" | "dispenser" | "furnace" | "blast_furnace" | "smoker" | "crafter") {
        0xFFB0_B0B0
    } else {
        return None;
    })
}

// A line, as one slanted quad.
pub(super) fn line(out: &mut impl Canvas, from: [f32; 2], to: [f32; 2], argb: u32, lw: f32) {
    let (dx, dy) = (to[0] - from[0], to[1] - from[1]);
    let len = (dx * dx + dy * dy).sqrt();
    if !len.is_finite() || len < 1.0 {
        return;
    }
    let half = lw.max(1.0) / 2.0;
    let (nx, ny) = (-dy / len * half, dx / len * half);
    out.quad(
        [[from[0] + nx, from[1] + ny], [to[0] + nx, to[1] + ny], [to[0] - nx, to[1] - ny], [from[0] - nx, from[1] - ny]],
        argb,
    );
}

// Runtime part (see runtime.rs): outgoing packets: moves, the look and fall the server sees, turns and Blink.

use super::Game;
use horizon_protocol::packets::play::{self, Serverbound as S};
use std::sync::Mutex;
use std::sync::atomic::Ordering;
use super::sunset::*;

// ---------------------------------------------------------------- packets

// What the send hook does with an outgoing packet.
pub(super) enum Out {
    Pass,
    Drop,
    Replace(S),
}

// A move packet taken apart: where (if it says), the look (if it says), and its flags (bit 0 on the ground, bit 1
// against a wall).
#[derive(Clone, Copy, PartialEq)]
struct Move {
    pub(super) at: Option<[f64; 3]>,
    pub(super) look: Option<(f32, f32)>,
    pub(super) flags: u8,
}

impl Move {
    pub(super) fn of(packet: &S) -> Option<Self> {
        Some(match packet {
            S::MovePlayerPos(m) => Self { at: Some([m.x, m.y, m.z]), look: None, flags: m.flags },
            S::MovePlayerPosRot(m) => Self { at: Some([m.x, m.y, m.z]), look: Some((m.yaw, m.pitch)), flags: m.flags },
            S::MovePlayerRot(m) => Self { at: None, look: Some((m.yaw, m.pitch)), flags: m.flags },
            S::MovePlayerStatus(m) => Self { at: None, look: None, flags: m.flags },
            _ => return None,
        })
    }
    fn packet(self) -> S {
        let flags = self.flags;
        match (self.at, self.look) {
            (Some([x, y, z]), Some((yaw, pitch))) => S::MovePlayerPosRot(play::MovePlayerPosRot { x, y, z, yaw, pitch, flags }),
            (Some([x, y, z]), None) => S::MovePlayerPos(play::MovePlayerPos { x, y, z, flags }),
            (None, Some((yaw, pitch))) => S::MovePlayerRot(play::MovePlayerRot { yaw, pitch, flags }),
            (None, None) => S::MovePlayerStatus(play::MovePlayerStatus { flags }),
        }
    }
}

// No Slow's No item release (Sunset's NoItemRelease): letting go of the use button never tells the server, with a
// menu open or what Release items lists in hand (`swords`, `food`, `potions` or item names), so it goes on using it.
fn kept_using(game: &Game<'_>) -> bool {
    let Some(m) = with(|s| s.module("No Slow").filter(|m| m.on && m.b("No item release")).cloned()) else {
        return false;
    };
    if gui_open() || !matches!(game.screen, super::Screen::Playing) {
        return true;
    }
    let list = m.t("Release items");
    game.held().is_some_and(|h| {
        let tagged = |tag: &str| game.res.items().item_tags.get(tag).is_some_and(|t| t.contains(&*h.item));
        super::sunset_util::listed(list, &h.item)
            || (super::sunset_util::listed(list, "swords") && tagged("minecraft:swords"))
            || (super::sunset_util::listed(list, "food") && game.res.items().get(&h.item).is_some_and(|i| i.food.is_some()))
            || (super::sunset_util::listed(list, "potions") && h.item.ends_with("potion"))
    })
}

// Outgoing packets: Blink holds moves, Anti Hunger hides sprinting and the ground, No Fall claims the ground as you
// fall (or, in No ground, never), Criticals hops, Flight's anti kick sinks, no move claims the ground with a fall that
// is not yours to pay (settle_fall), and the look modules asked for (turn_then) rides along. Each is a change to the
// tick's own move packet, never another one.
pub(super) fn outgoing(game: &Game<'_>, packet: &S) -> Out {
    if !running() { return Out::Pass; }
    if let Some(changed) = super::sunset_world_parity::outgoing(game, packet) {
        return Out::Replace(changed);
    }
    if let S::PlayerAction(a) = packet
        && a.action == 6
        && !super::sunset_hands::owned_block_packet()
        && kept_using(game)
    {
        return Out::Drop;
    }
    if ANTI_SPRINT.load(Ordering::Relaxed) && !super::sunset_gui_move::stopping()
        && let S::PlayerCommand(c) = packet
        && (c.action == 1 || c.action == 2)
    {
        return Out::Drop;
    }
    // A teleport: the server goes on counting from where it put you, though the moves after it are held (Blink) or
    // the next one is far away.
    if let S::AcceptTeleportation(t) = packet {
        fall(|f| f.last = Some(t.y));
        // The server set your look: what it has now is not the last one sent.
        set_last_look(None);
    }
    let Some(sent) = Move::of(packet) else {
        return Out::Pass;
    };
    if BLINK.load(Ordering::Relaxed) && !super::sunset_gui_move::stopping() {
        BLINK_HELD.store(true, Ordering::Relaxed);
        return Out::Drop;
    }
    if super::sunset_gui_move::stopping() {
        // This native movement supersedes Blink's held endpoint; never add a second move to drain it.
        BLINK_HELD.store(false, Ordering::Relaxed);
    }
    MOVED_THIS_TICK.store(true, Ordering::Relaxed);
    let Some(p) = game.player.as_ref() else {
        return Out::Pass;
    };
    let mut m = sent;
    let here = [p.position.x, p.position.y, p.position.z];
    // What a module tells the server of the ground, if it changes it; and whether No Fall is on to spare you the fall.
    let ground;
    let mut spared = false;
    // Criticals: this tick's move is the hop (stage 1: up, 2: half way down, 3: back down, then the hit's tick where
    // it ended), all off the ground. A jump this tick (your key, Auto Jump) would carry it up with you: the hit waits
    // for the jump's fall instead.
    if (1..CRIT_HIT).contains(&CRIT_STAGE.load(Ordering::Relaxed)) && !p.ground.on_ground && p.velocity.y > 0.0 {
        CRIT_STAGE.store(CRIT_FALL, Ordering::Relaxed);
    }
    let stage = CRIT_STAGE.load(Ordering::Relaxed);
    let hopping = (stage > 0 && stage < CRIT_HIT) || stage == CRIT_LAND;
    if hopping {
        let [x, y, z] = m.at.unwrap_or(here);
        let hop = f64::from_bits(CRIT_HOP.load(Ordering::Relaxed));
        let lift = if stage == CRIT_LAND { 0.0 } else { hop * f64::from(3 - stage) / 2.0 };
        m.at = Some([x, y + lift, z]);
        m.flags = 0;
        ground = Some(false);
        CRIT_STAGE.store(if stage == CRIT_LAND { 0 } else { stage + 1 }, Ordering::Relaxed);
    } else {
        // Flight's Packet anti kick: the move carries the position, sunk 0.0313 below the last height sent while it
        // is due and you are in the air (Sunset's antiKickPacket).
        if FLY_PACKET.load(Ordering::Relaxed) && super::sunset_flight::damage_open() {
            fly_down(game, &mut m, here);
        }
        if let Some(dy) = super::sunset_flight::offset() {
            let mut at = m.at.unwrap_or(here);
            at[1] += dy;
            m.at = Some(at);
        }
        // The server adds each move's drop to the fall, and a move that says you are on the ground costs what has
        // added up beyond three blocks. No Fall's Packet mode claims the ground on every move down, so the count
        // never passes one move's drop (Sunset's waits for 0.5 blocks a tick, which leaves a fall the server counted
        // before to hurt), and one move drops 3.92 at most, which costs nothing. No ground never claims it. Flying that
        // way claims it all the time. settle_fall has the last word.
        // Anti Hunger hides the ground, but not while you break a block: off the ground the server mines five times
        // slower and refuses the break, so the block comes back (Sunset's skips it then too). Nor once the server
        // has counted a fall, or this move adds one: hidden, every jump and step down would add up to one fall that
        // the first move you are on the ground for makes you pay.
        let falling = !p.ground.on_ground && !p.flying && !p.fall_flying;
        let no_fall = NO_FALL.load(Ordering::Relaxed);
        let paused = game.creative || (NO_FALL_MACE.load(Ordering::Relaxed) && game.held().is_some_and(|s| s.item.ends_with(":mace")));
        spared = no_fall != 0 && !paused;
        let flight_ground = FLIGHT_GROUND.load(Ordering::Relaxed) && super::sunset_flight::damage_open();
        ground = if flight_ground || (GLIDE_GROUND.load(Ordering::Relaxed) && !p.flying) {
            Some(true)
        } else if no_fall == 1 && !paused && falling && p.velocity.y < 0.0 {
            Some(true)
        } else if no_fall == 2 && !paused {
            Some(false)
        } else if ANTI_GROUND.load(Ordering::Relaxed)
            && (p.fall_distance <= 0.0 || p.flying)
            && super::remote::sunset_remote::breaking(game).is_none()
            && fall_counted(&m) == 0.0
        {
            Some(false)
        } else {
            None
        };
        if let Some(g) = ground {
            m.flags = (m.flags & !1) | u8::from(g);
        }
    }
    // Flight's Damage fly dealing itself fall damage: this tick's height of its fall, off the ground, or its landing.
    // That fall is yours to pay (settle_fall lets it land).
    let own_fall = super::sunset_flight::fall_move();
    if let Some((y, lands)) = own_fall {
        let mut at = m.at.unwrap_or(here);
        at[1] = y;
        m.at = Some(at);
        m.flags = (m.flags & !1) | u8::from(lands);
    }
    let told = settle_fall(game, &m, sent.flags & 1 != 0, ground == Some(true) || spared, own_fall.is_some());
    m.flags = (m.flags & !1) | u8::from(told);
    if ground.is_some() || own_fall.is_some() {
        horizon_client::player_sync::sunset_sync::told_ground(told);
    }
    // The look a module asked for, else the player's own back after one (not during the Criticals hop, whose hit
    // follows it).
    let own = (game.yaw, game.pitch);
    let last = last_look();
    let look = turns(|t| {
        if let Some(head) = t.queue.first().filter(|_| !t.carried) {
            t.carried = true;
            let look = wire_look(last, own, head.look);
            t.restore = look != own;
            Some(look)
        } else if t.restore && !hopping {
            t.restore = false;
            Some(own)
        } else {
            None
        }
    });
    if let Some(look) = look {
        m.look = Some(look);
    }
    // A look the server already has is left out (as Sunset's look through the game's own sender never repeats one):
    // the same look twice in a row is what Grim's AimDuplicateLook catches.
    if m.look.is_some() && m.look == last_look() {
        m.look = None;
    }
    if m.look.is_some() {
        set_last_look(m.look);
    }
    if m == sent { Out::Pass } else { Out::Replace(m.packet()) }
}

// The last look a move packet carried to the server (None after a teleport, which sets it).
static LAST_LOOK: Mutex<Option<(f32, f32)>> = Mutex::new(None);

pub(super) fn last_look() -> Option<(f32, f32)> {
    *LAST_LOOK.lock().unwrap_or_else(|e| e.into_inner())
}

pub(super) fn set_last_look(look: Option<(f32, f32)>) {
    *LAST_LOOK.lock().unwrap_or_else(|e| e.into_inner()) = look;
}

// The yaw a look asked for goes out as the game's own does: unbounded and continuous, never folded into ±180 (a fold
// is a 360-degree turn to the server, Grim's AimModulo360). It is taken nearest your own yaw (your own exactly when
// that is what was asked), then nearest the last one sent.
fn wire_look(last: Option<(f32, f32)>, own: (f32, f32), asked: (f32, f32)) -> (f32, f32) {
    let wrap = |d: f32| (d + 180.0).rem_euclid(360.0) - 180.0;
    let mut yaw = if asked.0 == own.0 { own.0 } else { own.0 + wrap(asked.0 - own.0) };
    if let Some((sent, _)) = last
        && (yaw - sent).abs() > 180.0
    {
        yaw = sent + wrap(yaw - sent);
    }
    (yaw, asked.1.clamp(-90.0, 90.0))
}

// The yaw the next move packet will carry for a look asked now with `yaw`: what a use packet sent with it says.
pub(super) fn wire_yaw(game: &Game<'_>, yaw: f32) -> f32 {
    wire_look(last_look(), (game.yaw, game.pitch), (yaw, 0.0)).0
}

// ---- the fall the server counts
//
// A server adds up the drop of each move told off the ground, and a move told on it costs what that comes to beyond
// three blocks (a point of health for each whole block past that) and starts it again; water, a ladder or creative
// flight start it again too (Entity.checkFallDamage, LivingEntity.handleOnClimbable). Sunset keeps the same count
// of the moves it lets go, so that no move claims the ground with a fall the server would make you pay for that was
// not yours to pay: one it hid the ground you landed on through (No Fall's No ground, the Criticals hop), or one
// Flight, Glide or No Fall would claim the ground on. That fall is kept: every move goes off the ground until
// something starts the count again, or you die.

pub(super) struct Fall {
    // The server's count, in blocks.
    pub(super) counted: f64,
    // The height the last move told, or the last teleport put you at; None at first.
    pub(super) last: Option<f64>,
    // Part of the count is not yours to pay.
    pub(super) kept: bool,
}

static FALL: Mutex<Fall> = Mutex::new(Fall { counted: 0.0, last: None, kept: false });

// The most the server lets you land with for nothing: four blocks costs a point (LivingEntity.calculateFallPower adds
// 1.0E-6 to the fall). A move at full falling speed drops 3.92.
const FREE_FALL: f64 = 3.99;

pub(super) fn fall<R>(f: impl FnOnce(&mut Fall) -> R) -> R {
    f(&mut FALL.lock().unwrap_or_else(|e| e.into_inner()))
}

// What the server will have counted after this move, if it goes off the ground.
fn fall_counted(m: &Move) -> f64 {
    fall(|f| f.counted + drop_of(f, m))
}

fn drop_of(f: &Fall, m: &Move) -> f64 {
    match (f.last, m.at) {
        (Some(last), Some([_, y, _])) => (last - y).max(0.0),
        _ => 0.0,
    }
}

// The count after a move that tells the server `told` of the ground (`real` is what the game would tell it, and
// `claimed` a module claiming it, or No Fall on): the ground the move should tell. Gliding, a move that drops less
// than half a block brings the count down to one (LivingEntity.travelFallFlying), but a steep dive adds up: No Fall
// can't claim the ground in the glide (the server would end it), so the landing is kept.
fn settle_fall(game: &Game<'_>, m: &Move, real: bool, claimed: bool, owned: bool) -> bool {
    let (Some(p), Some(_)) = (game.player.as_ref(), game.remote.as_ref()) else {
        return m.flags & 1 != 0;
    };
    let cleared = fall_cleared(game);
    fall(|f| {
        let drop = drop_of(f, m);
        let counted = if p.fall_flying && drop < 0.5 { (f.counted + drop).min(1.0) } else { f.counted + drop };
        if let Some([_, y, _]) = m.at {
            f.last = Some(y);
        }
        let mut told = m.flags & 1 != 0;
        if cleared {
            (f.counted, f.kept) = (0.0, false);
            return told;
        }
        if told && counted >= FREE_FALL && (f.kept || claimed) && !owned {
            told = false;
            f.kept = true;
        } else if !told && real && counted > 0.0 && !owned {
            f.kept = true;
        }
        if told {
            (f.counted, f.kept) = (0.0, false);
        } else {
            f.counted = counted;
        }
        told
    })
}

// Water, a ladder or creative flight: the server starts the count again each tick there, moves or no moves.
pub(super) fn fall_cleared(game: &Game<'_>) -> bool {
    let Some(p) = game.player.as_ref() else {
        return false;
    };
    let feet = [p.position.x.floor() as i32, p.position.y.floor() as i32, p.position.z.floor() as i32];
    p.fluids.was_touching_water
        || (game.creative && p.flying)
        || game.spectator()
        || game.block_in_tag("minecraft:climbable", &game.block_name(feet))
}

// Nothing of a fall is counted (Damage fly's self damage adds exactly its own).
pub(super) fn fall_clean() -> bool {
    fall(|f| f.counted == 0.0 && !f.kept)
}

// Death: the next body has fallen nowhere.
pub(super) fn fall_died() {
    fall(|f| *f = Fall { counted: 0.0, last: None, kept: false });
}

// Flight's Packet anti kick on the move: while it is due and you are in the air, the height sinks 0.0313 below the
// last one sent (a move without a position gets the player's).
fn fly_down(game: &Game<'_>, m: &mut Move, here: [f64; 3]) {
    let mut at = m.at.unwrap_or(here);
    let bits = FLY_LAST_Y.load(Ordering::Relaxed);
    let last = f64::from_bits(bits);
    let sinking = at[1] >= last || last - at[1] < 0.03130;
    if FLY_DOWN.load(Ordering::Relaxed) && bits != u64::MAX && sinking && in_the_air(game) {
        at[1] = last - 0.03130;
        m.at = Some(at);
    } else {
        FLY_LAST_Y.store(at[1].to_bits(), Ordering::Relaxed);
    }
}

// ---- the look the server sees
//
// Rotate in Kill Aura, Nuker, Scaffold and the rest: a module asks for a look and hands over what to do once the server
// has it. The look rides on the tick's own move packet, or in a tick without one on the single one Sunset sends at
// its end, and what was asked runs after that packet has gone (Sunset's Rotations). Servers kick for a second move
// packet in a tick, and some check the look of a click.

struct Deed {
    pub(super) guard: Option<AttackGuard>,
    pub(super) critical: CriticalCompletion,
    pub(super) run: Box<dyn for<'a, 'b> FnOnce(&'a mut Game<'b>) + Send>,
}
pub(super) struct CriticalCompletion(pub(super) bool);
impl Drop for CriticalCompletion {
    fn drop(&mut self) { if self.0 { crit_done(); } }
}

pub(super) struct Ask {
    who: &'static str,
    pub(super) look: (f32, f32),
    deeds: Vec<Deed>,
    // Asked this tick: another ask of the same module joins it instead of replacing it.
    pub(super) fresh: bool,
}

pub(super) struct Turns {
    // Oldest first, one a module; one look goes out a tick.
    pub(super) queue: Vec<Ask>,
    // This tick's move packet carried the first ask's look.
    pub(super) carried: bool,
    // A look went out that is not the player's own: the next move packet puts the player's back.
    pub(super) restore: bool,
}

static TURNS: Mutex<Turns> = Mutex::new(Turns { queue: Vec::new(), carried: false, restore: false });

pub(super) fn turns<R>(f: impl FnOnce(&mut Turns) -> R) -> R {
    f(&mut TURNS.lock().unwrap_or_else(|e| e.into_inner()))
}

// The packets that came since the last tick, to what Crystal Aura and Anchor Aura keep track of.
pub(super) fn combat_packets(game: &Game<'_>, packets: &[horizon_protocol::packets::play::Clientbound]) {
    use horizon_protocol::packets::play::Clientbound as C;
    for packet in packets {
        super::sunset_loot_guard::packet(game, packet);
        super::sunset_prediction::packet(game, packet);
        super::sunset_crystal_aura::packet(game, packet);
        if matches!(packet, C::Login(_) | C::Respawn(_) | C::PlayerPosition(_)) {
            super::sunset_combat_wire::reset_look();
        }
        if matches!(packet, C::Login(_) | C::Respawn(_)) {
            super::sunset_flight::reset();
        }
        match packet {
            C::DamageEvent(p) if game.remote.as_ref().is_some_and(|r| r.entity_id == p.id) => super::sunset_flight::hurt(),
            C::SetHealth(p) => super::sunset_flight::health(p.health),
            _ => {}
        }
        super::sunset_combat_inventory::packet(game, packet);
        super::sunset_gear::packet(game, packet);
        super::sunset_throws::packet(game, packet);
        super::sunset_effects::packet(game, packet);
        super::recipe_book::sunset_recipes::packet(packet);
        if let C::SetEntityMotion(p) = packet {
            super::sunset_melee::note_velocity(game, p.id, p.velocity);
            if game.remote.as_ref().is_some_and(|r| r.entity_id == p.id) {
                if with(|s| s.module("Speed").is_some_and(|m| m.on && m.p("Mode") == "Watchdog")) {
                    with(|s| s.watchdog.knocked(game.ticks, p.velocity));
                }
                super::sunset_flight::knocked(p.velocity);
                super::sunset_lag::knocked();
                super::sunset_render::no_slow_knocked();
            }
        }
    }
}

// Crystal Aura, Anchor Aura and the combat macros let go of what they hold: the hand they switched, a look waiting.
pub(super) fn combat_cleanup(game: &mut Game<'_>) {
    reset_targets(game);
    super::sunset_combat_control::prepare_cleanup(game);
    super::sunset_combat_macros::reset(game);
    super::sunset_pvp_bot::release(game);
    drop_strikes();
    super::sunset_melee::cancel(game);
    super::sunset_auto_mace::cancel();
    super::sunset_aura::disabled(game, false);
    super::sunset_combat_inventory::cancel(game);
    super::sunset_combat_control::reset();
    super::sunset_crystal_aura::disabled(game);
    super::sunset_anchor_aura::disabled(game);
    super::sunset_cart::reset(game);
    super::sunset_throws::reset(game);
    super::sunset_anchor_catch::reset(game);
}

// A scene change invalidates target caches as well as actions carrying old IDs.
pub(super) fn reset_targets(game: &mut Game<'_>) {
    super::sunset_autoclicker::reset();
    drop_strikes();
    super::sunset_aura::clear_targets(game);
    super::sunset_combat::reset_aim();
    super::sunset_click_fix::reset();
    for who in ["Attack", "Hit flick", "Kill Aura"] { cancel_turns(who); }
    CRIT_STAGE.store(0, Ordering::Relaxed);
    CRIT_SPRINT.store(0, Ordering::Relaxed);
    CRIT_JUMP.store(false, Ordering::Relaxed);
    with(|s| {
        s.crit_target = None;
        s.crit_look = None;
        s.trigger_sticky = None;
        s.trigger_missed = None;
    });
}

pub(super) fn revalidate_targets(game: &Game<'_>) {
    super::sunset_click_fix::revalidate(game);
    let pending = with(|s| s.crit_target);
    if pending.is_some_and(|guard| !guard.valid(game)) {
        with(|s| { s.crit_target = None; s.crit_look = None; });
        CRIT_STAGE.store(0, Ordering::Relaxed);
        CRIT_JUMP.store(false, Ordering::Relaxed);
        crit_done();
        cancel_turns("Attack");
    }
    // Validate outside the queue lock: eligibility consults the shared module
    // settings and the classifier, neither of which may call a held deed.
    let mut queue = turns(|t| std::mem::take(&mut t.queue));
    for ask in &mut queue {
        if ask.deeds.first().is_some_and(|deed| deed.guard.is_some_and(|guard| !guard.valid(game))) {
            ask.deeds.clear();
            continue;
        }
        ask.deeds.retain(|deed| deed.guard.is_none_or(|guard| guard.valid(game)));
    }
    let head_kept = queue.first().is_none_or(|ask| !ask.deeds.is_empty());
    queue.retain(|ask| !ask.deeds.is_empty());
    turns(|t| {
        t.queue = queue;
        if !head_kept { t.carried = false; }
    });
}

// turn_then only when no look waits: Crystal Aura, Anchor Aura and the macros switch the hand in `then`, so an ask
// refused changes nothing. Never while Blink holds the moves.
pub(super) fn try_turn_then(who: &'static str, yaw: f32, pitch: f32,
    then: impl for<'a, 'b> FnOnce(&'a mut Game<'b>) + Send + 'static) -> bool {
    if !running() { return false; }
    if !yaw.is_finite() || !pitch.is_finite() || BLINK.load(Ordering::Relaxed) {
        return false;
    }
    let look = (yaw, pitch.clamp(-90.0, 90.0));
    turns(|t| {
        if t.carried || !t.queue.is_empty() {
            return false;
        }
        t.queue.push(Ask { who, look, deeds: vec![Deed { guard: None, critical: CriticalCompletion(false), run: Box::new(then) }], fresh: true });
        true
    })
}

// A look is waiting to go out, or on its way.
pub(super) fn turn_pending() -> bool {
    turns(|t| t.carried || !t.queue.is_empty())
}

// What `who` asked to look at, and do, is dropped.
pub(super) fn cancel_turns(who: &str) {
    turns(|t| {
        if t.queue.first().is_some_and(|ask| ask.who == who) {
            t.carried = false;
        }
        t.queue.retain(|ask| ask.who != who);
    });
}

// Has the server see the player look at (yaw, pitch), then does `then`. `who` names the module: what it asks again in
// the same tick goes along under its first look, and an ask from an earlier tick still waiting is replaced.
pub(super) fn turn_then(who: &'static str, yaw: f32, pitch: f32, then: impl for<'a, 'b> FnOnce(&'a mut Game<'b>) + Send + 'static) {
    queue_turn(who, yaw, pitch, None, false, then);
}
pub(super) fn turn_then_checked(who: &'static str, yaw: f32, pitch: f32, guard: AttackGuard,
    then: impl for<'a, 'b> FnOnce(&'a mut Game<'b>) + Send + 'static) {
    queue_turn(who, yaw, pitch, Some(guard), false, then);
}
pub(super) fn queue_turn(who: &'static str, yaw: f32, pitch: f32, guard: Option<AttackGuard>, critical: bool,
    then: impl for<'a, 'b> FnOnce(&'a mut Game<'b>) + Send + 'static) {
    if !running() { return; }
    let critical = CriticalCompletion(critical);
    if !yaw.is_finite() || !pitch.is_finite() {
        return;
    }
    let look = (yaw, pitch.clamp(-90.0, 90.0));
    let deed = Deed { guard, critical, run: Box::new(then) };
    turns(|t| match t.queue.iter_mut().position(|a| a.who == who) {
        Some(i) if t.queue[i].fresh => t.queue[i].deeds.push(deed),
        Some(i) => {
            if i == 0 && t.carried {
                // Its look is on the way already: the new ask waits behind it.
                t.queue.push(Ask { who, look, deeds: vec![deed], fresh: true });
            } else {
                t.queue[i] = Ask { who, look, deeds: vec![deed], fresh: true };
            }
        }
        None => t.queue.push(Ask { who, look, deeds: vec![deed], fresh: true }),
    });
}

// A look alone (Anti AFK's spin).
pub(super) fn turn(who: &'static str, yaw: f32, pitch: f32) {
    turn_then(who, yaw, pitch, |_| {});
}

// Runs what waited for the look this tick's move packet carried.
pub(super) fn turned(game: &mut Game<'_>) {
    let ask = turns(|t| std::mem::take(&mut t.carried).then(|| t.queue.remove(0)));
    for mut deed in ask.map_or_else(Vec::new, |a| a.deeds) {
        if !running() { break; }
        if deed.guard.is_none_or(|guard| guard.valid(game)) {
            deed.critical.0 = false;
            (deed.run)(game);
        }
    }
}

// The end of the tick: with no move packet in it, one to carry the first look asked for (or the player's own back),
// and what waited for it.
pub(super) fn end_turns(game: &mut Game<'_>) {
    // The look that packet would carry is the one the server has already: nothing to send, and what waited for it goes.
    // Your own look back waits for the next tick, as it would after a packet (Quiver keeps the look up across its
    // let-go).
    let own = (game.yaw, game.pitch);
    let have = last_look();
    let quiet = !MOVED_THIS_TICK.load(Ordering::Relaxed) && !BLINK.load(Ordering::Relaxed);
    let already = quiet
        && have.is_some()
        && turns(|t| match t.queue.first().filter(|_| !t.carried).map(|head| wire_look(have, own, head.look)) {
            Some(look) if Some(look) == have => {
                t.carried = true;
                t.restore = look != own;
                true
            }
            None if t.restore && Some(own) == have => {
                t.restore = false;
                true
            }
            _ => false,
        });
    if already {
        turned(game);
    } else if quiet && turns(|t| !t.queue.is_empty() || t.restore) {
        let ground = game.player.as_ref().is_some_and(|p| p.ground.on_ground);
        // outgoing puts the look in.
        game.send(S::MovePlayerRot(play::MovePlayerRot { yaw: game.yaw, pitch: game.pitch, flags: u8::from(ground) }));
        turned(game);
    }
    turns(|t| {
        for a in &mut t.queue {
            a.fresh = false;
        }
    });
}

fn in_the_air(game: &Game<'_>) -> bool {
    let Some(p) = game.player.as_ref() else {
        return false;
    };
    let b = p.bounds();
    let (lo, hi) = (b.min_position(), b.max_position());
    let f = |v: f64| v.floor() as i32;
    for x in f(lo.x - 0.0625)..=f(hi.x + 0.0625) {
        for y in f(lo.y - 0.0625 - 0.55)..=f(hi.y + 0.0625) {
            for z in f(lo.z - 0.0625)..=f(hi.z + 0.0625) {
                if !super::sunset_util::is_air(game, [x, y, z]) {
                    return false;
                }
            }
        }
    }
    true
}

// Where the player is, as one position packet: what Blink held back is a
// single move to here, as the server takes one position packet a tick.
pub(super) fn flush_blink(game: &mut Game<'_>) {
    if !BLINK_HELD.swap(false, Ordering::Relaxed) || MOVED_THIS_TICK.load(Ordering::Relaxed) {
        return;
    }
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let flags = u8::from(p.ground.on_ground) | u8::from(p.collision.horizontal) << 1;
    let (x, y, z) = (p.position.x, p.position.y, p.position.z);
    game.send(S::MovePlayerPos(play::MovePlayerPos { x, y, z, flags }));
}

// Runtime part (see runtime.rs): blocks and items, Scaffold, Legit Sneak, Auto Eat, block scans and inventory clicks.

use super::Game;
use super::sunset_util::block_pos;
use horizon_protocol::packets::play::{self, Serverbound as S};
use std::sync::Mutex;
use winit::keyboard::KeyCode;
use super::sunset::*;

pub(super) fn solid_at(game: &Game<'_>, x: i32, y: i32, z: i32) -> bool {
    !game.res.facts().is_air(game.world.block(x, y, z))
}

// The block column just ahead of the player's feet, in the direction the
// move keys point: its x and z, and the y of the block under the feet.
// Parkour (Sunset's), before the tick moves you: on the ground, moving, jump not held and not sneaking. Last tick:
// jump when your box where this tick's move takes you (as far as the last tick's), Edge distance narrower each side
// and half a block down, would touch no block, so you leave from the last spot on it. Early: when a point 0.35 blocks
// ahead of you is over air.
pub(super) fn parkour_jump(game: &Game<'_>, m: &Module) -> bool {
    use horizon_core::geometry::Vec3;
    let Some(p) = game.player.as_ref() else {
        return false;
    };
    let (forward, side) = move_input(game);
    let held = |k: KeyCode| game.keys.contains(&k);
    if !p.ground.on_ground
        || held(KeyCode::Space)
        || (forward == 0.0 && side == 0.0)
        || (held(KeyCode::ShiftLeft) && !m.b("Ignore sneaking"))
        || (m.b("Only while sprinting") && !p.sprinting)
        || (m.b("Only when moving forward") && forward <= 0.0)
    {
        return false;
    }
    if m.p("Jump when") == "Early" {
        return ahead(game).is_some_and(|(x, y, z)| !solid_at(game, x, y, z));
    }
    let step = Vec3::new(p.position.x - game.previous_position.x, -0.5, p.position.z - game.previous_position.z);
    // Each side's edge distance rolled between Edge distance and Longest edge distance (the same when they match).
    let mut rng = super::sunset_rotation::Rng::new(game.ticks.wrapping_mul(0x9E37_79B9_7F4A_7C15) ^ 0x51ED);
    let (lo, hi) = (m.n("Edge distance"), m.n("Longest edge distance").max(m.n("Edge distance")));
    let mut edge = || lo + rng.next() * (hi - lo);
    let under = p.bounds().move_by(step).deflate(Vec3::new(edge(), 0.0, edge()));
    horizon_client::collisions::SceneCollisions { world: &game.world, binding: game.collision, subject: None }
        .unobstructed(under)
        .unwrap_or(false)
}

// Safe Walk's Sneak: a block item in either hand (with Only holding blocks), your look at least Min pitch down, and
// the block under you and the two below it all air or replaceable, so you are past the edge of what you stand on.
pub(super) fn edge_sneak(game: &Game<'_>, m: &Module) -> bool {
    let block = |s: Option<&horizon_client::items::ItemStack>| s.is_some_and(|s| game.res.items().get(&s.item).is_some_and(|i| i.block.is_some()));
    if (m.b("Only holding blocks") && !block(game.held()) && !block(game.offhand.as_ref())) || f64::from(game.pitch) < m.n("Min pitch") {
        return false;
    }
    super::sunset_util::block_pos(game).is_some_and(|[x, y, z]| (1..=3).all(|d| super::sunset_util::replaceable(game, [x, y - d, z])))
}

pub(super) fn ahead(game: &Game<'_>) -> Option<(i32, i32, i32)> {
    let p = game.player.as_ref()?;
    let d = move_direction(game)?;
    let (ax, az) = (p.position.x + d[0] * 0.35, p.position.z + d[1] * 0.35);
    Some((ax.floor() as i32, (p.position.y - 0.5).floor() as i32, az.floor() as i32))
}

// Switches the held slot now: the server is told before anything is sent
// that depends on it, once (the tick sees it was told and doesn't send it again).
pub(super) fn hold(game: &mut Game<'_>, slot: usize) {
    game.selected = slot;
    if super::remote::sunset_remote::tell_carried(game, slot) {
        game.send(S::SetCarriedItem(play::SetCarriedItem { slot: slot as i16 }));
    }
}

pub(super) fn item_info(game: &Game<'_>, slot: usize) -> Option<horizon_client::items::ItemInfo> {
    let stack = game.inventory.get(slot)?.as_ref()?;
    game.res.items().get(&stack.item).cloned()
}

pub(super) fn best_weapon(game: &Game<'_>, prefer_axes: bool) -> Option<usize> {
    let mut best: Option<(usize, f32)> = None;
    for slot in 0..9 {
        let Some(stack) = game.inventory.get(slot).and_then(|s| s.as_ref()) else {
            continue;
        };
        let Some(info) = game.res.items().get(&stack.item) else {
            continue;
        };
        if info.attack_damage <= 0.0 {
            continue;
        }
        let kind = if stack.item.ends_with("_axe") && prefer_axes {
            100.0
        } else if stack.item.ends_with("_sword") && !prefer_axes {
            100.0
        } else {
            0.0
        };
        let score = info.attack_damage + kind;
        if best.is_none_or(|(_, b)| score > b) {
            best = Some((slot, score));
        }
    }
    best.map(|(slot, _)| slot)
}

// Scaffold's blocks: a block item in the list (or not in it, as a blacklist) that is a full block and does not fall.
pub(super) fn scaffold_item(game: &Game<'_>, m: &Module, slot: usize) -> bool {
    let Some(state) = item_info(game, slot).and_then(|i| i.block) else {
        return false;
    };
    let f = game.res.facts().get(state);
    let name = super::sunset_util::short(&f.name);
    let listed = super::sunset_util::listed(m.t("Blocks"), name);
    let falls = ["sand", "gravel", "concrete_powder", "anvil"].iter().any(|e| name.ends_with(e)) || name == "dragon_egg";
    listed == (m.p("Blocks filter") == "Whitelist") && f.full_collision && !falls
}

// Scaffold's presets: settings of its modes made for one style, filled in when the Preset is picked (not on the first
// look, so a change you made afterwards stays). Speedbridge is Legit's edge sneaking at its quickest; Blatant is Normal
// with snap rotations, no ray cast, sprint kept, a reach ahead and fast tower while moving. Neither adds an algorithm.
pub(super) const SCAFFOLD_PRESETS: [(&str, &[(&str, &str)]); 2] = [
    ("Speedbridge", &[("Mode", "Legit"), ("Shortest sneak delay (ms)", "0"), ("Longest sneak delay (ms)", "50")]),
    ("Blatant", &[("Mode", "Normal"), ("Rotate", "true"), ("Rotations", "Snap"), ("Look", "Silent"), ("Ray cast", "Off"),
        ("Movement correction", "Silent"), ("Sprint", "Keep"), ("Expand", "2"), ("Same Y", "Off"), ("Ledge sneak", "false"),
        ("Fast tower", "true"), ("While moving", "true")]),
];
static SCAFFOLD_PRESET: Mutex<String> = Mutex::new(String::new());

pub(super) fn scaffold_preset(game: &Game<'_>, m: &Module) {
    let preset = m.p("Preset");
    let before = std::mem::replace(&mut *SCAFFOLD_PRESET.lock().unwrap_or_else(|e| e.into_inner()), preset.to_owned());
    if before.is_empty() || before == preset {
        return;
    }
    if let Some((_, fields)) = SCAFFOLD_PRESETS.iter().find(|p| p.0 == preset) {
        for (name, value) in fields.iter() {
            set_setting(game, &format!("scaffold.{}", norm(name)), value);
        }
    }
}

// Scaffold waits while Blink is on, and while Kill Aura has someone to hit if Disable with Kill Aura says so (Kill
// Aura on with no one about leaves Scaffold be; without the setting Kill Aura waits for Scaffold instead).
pub(super) fn scaffold_paused(m: &Module, kill_aura_engaged: bool, blink: bool) -> bool {
    blink || (kill_aura_engaged && m.b("Disable with Kill Aura"))
}

// The biggest stack in the hotbar (the one in hand if two are level), kept until it runs out: taking the biggest
// again each time would swap between two like stacks at every block. Auto switch off: only what is in hand.
pub(super) fn scaffold_slot(game: &Game<'_>, m: &Module) -> Option<usize> {
    if !m.b("Auto switch") {
        return Some(game.selected).filter(|&i| scaffold_item(game, m, i));
    }
    if let Some(kept) = with(|s| s.scaffold_stack).filter(|&i| scaffold_item(game, m, i)) {
        return Some(kept);
    }
    let count = |i: usize| game.inventory.get(i).and_then(|s| s.as_ref()).map_or(0, |s| s.count);
    let best = (0..9).filter(|&i| scaffold_item(game, m, i)).max_by_key(|&i| (count(i), i == game.selected, std::cmp::Reverse(i)));
    with(|s| s.scaffold_stack = best);
    best
}

// The blocks Scaffold can use: the hotbar's, or only the hand's with Auto switch off.
pub(super) fn scaffold_blocks(game: &Game<'_>, m: &Module) -> u32 {
    let count = |i: usize| game.inventory.get(i).and_then(|s| s.as_ref()).map_or(0, |s| s.count);
    if !m.b("Auto switch") {
        return if scaffold_item(game, m, game.selected) { count(game.selected) } else { 0 };
    }
    (0..9).filter(|&i| scaffold_item(game, m, i)).map(count).sum()
}

// A block Scaffold placed, drawn for 8 ticks as it fades (Render).
pub(super) fn scaffold_drawn(at: [i32; 3]) {
    with(|s| s.scaffold_placed.push((at, 8)));
}

// Normal's Look Visible is about to turn your view: the view before it is kept, to be put back when Scaffold goes off.
pub(super) fn scaffold_view(game: &Game<'_>) {
    let view = (game.yaw, game.pitch);
    with(|s| {
        s.scaffold_rotation.get_or_insert(view);
    });
}

// Scaffold's placed blocks fade (its Normal mode works before the tick, in sunset_scaffold_normal).
pub(super) fn scaffold_fade() {
    with(|s| {
        s.scaffold_placed.retain_mut(|(_, t)| {
            *t = t.saturating_sub(1);
            *t > 0
        });
    });
}

// Legit Scaffold's sneak: held (the game's movement then keeps you on the edge, and tells the server you sneak) or let
// go, if it was Scaffold's and you are not holding it yourself.
pub(super) fn legit_sneak(game: &mut Game<'_>, down: bool) {
    let ours = with(|s| s.scaffold_sneak);
    if down && !game.keys.contains(&KeyCode::ShiftLeft) {
        game.keys.insert(KeyCode::ShiftLeft);
        with(|s| s.scaffold_sneak = true);
    } else if !down && ours {
        if !game.physical_keys.contains(&KeyCode::ShiftLeft) {
            game.keys.remove(&KeyCode::ShiftLeft);
        }
        with(|s| s.scaffold_sneak = false);
    }
}

// Auto Eat (Sunset's): once health or hunger is at its threshold, holds use on the best food (the off hand's first,
// then the hotbar's, then the inventory's moved into the hotbar), with Kill Aura off meanwhile, until neither is.
// Each tick it eats from the food it chose: held again if something else took the hand (your keys, Auto Tool,
// Scaffold), and use is only pressed with food in that hand, so it never uses or places what took its place. A
// menu, death or Auto Gap stops it, and it starts afresh after.
pub(super) fn auto_eat(game: &mut Game<'_>, m: &Module) {
    use winit::event::MouseButton;
    let alive = game.player.as_ref().is_some_and(|p| p.health.health() > 0.0);
    if !game.native_playing() || !alive || super::sunset_player::gap_eating() {
        if with(|s| s.eating) {
            eat_stop(game);
        }
        return;
    }
    if with(|s| s.eating) {
        if !super::sunset_combat_control::claim("Auto Eat") || !eat_due(game, m) {
            eat_stop(game);
            return;
        }
        let slot = with(|s| s.eat_slot);
        let edible = match slot {
            Some(i) => edible(game, m, game.inventory.get(i).and_then(|s| s.as_ref())),
            None => edible(game, m, game.offhand.as_ref()),
        };
        if !edible && !food_slot(game, m).is_some_and(|next| eat_from(game, next)) {
            eat_stop(game);
            return;
        }
        // The hand went to something else: let go, take the food back (or, eating from the off hand, an empty
        // hand), and press again next tick.
        let want = match with(|s| s.eat_slot) {
            Some(i) => Some(i),
            None => (!hand_inert(game)).then(|| empty_hotbar(game)).flatten(),
        };
        if let Some(i) = want
            && game.selected != i
        {
            let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, false);
            hold(game, i);
            return;
        }
        if with(|s| s.eat_slot).is_none() && !hand_inert(game) {
            eat_stop(game);
            return;
        }
        if game.using.is_none() {
            let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, true);
        }
        return;
    }
    if !eat_due(game, m) {
        return;
    }
    let Some(slot) = food_slot(game, m) else {
        return;
    };
    let prev = game.selected;
    if !super::sunset_combat_control::claim("Auto Eat") {
        return;
    }
    if !eat_from(game, slot) {
        super::sunset_combat_control::release("Auto Eat");
        return;
    }
    let paused = m.b("Pause auras") && with(|s| s.is_on("Kill Aura"));
    if paused {
        toggle_named(game, "Kill Aura", false);
    }
    with(|s| {
        s.eating = true;
        s.eat_prev = prev;
        s.eat_paused_aura = paused;
    });
    let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, true);
}

// Health and hunger against the thresholds, as Threshold mode joins them.
fn eat_due(game: &Game<'_>, m: &Module) -> bool {
    let Some(p) = game.player.as_ref() else {
        return false;
    };
    let health = f64::from(p.health.health()) <= m.n("Health threshold");
    let bar = f64::from(p.health.food.food) <= m.n("Hunger threshold");
    let saturation = f64::from(p.health.food.saturation) <= m.n("Saturation threshold");
    let hunger = match m.p("Food mode") {
        "Saturation" => saturation,
        "Either" => bar || saturation,
        _ => bar,
    };
    match m.p("Threshold mode") {
        "Health" => health,
        "Hunger" => hunger,
        "Both" => health && hunger,
        _ => health || hunger,
    }
}

// Food that passes the list (off the Blacklist, or on the Whitelist) and that you can eat now (hungry, or food you can always eat).
fn edible(game: &Game<'_>, m: &Module, stack: Option<&horizon_client::items::ItemStack>) -> bool {
    let Some(stack) = stack else {
        return false;
    };
    let Some(info) = game.res.items().get(&stack.item) else {
        return false;
    };
    let hungry = game.player.as_ref().is_some_and(|p| p.health.food.food < 20);
    info.food.is_some() && super::sunset_util::passes(m, if m.p("List mode") == "Whitelist" { "Whitelist" } else { "Blacklist" }, &stack.item) && (hungry || info.can_always_eat)
}

// A right click with this in the main hand does nothing, so the off hand eats: an empty hand, a sword, pickaxe or
// mace. (A block would be placed, and axes, hoes, shovels, spears, pearls and the like have uses of their own.)
fn hand_inert(game: &Game<'_>) -> bool {
    game.held().is_none_or(|s| ["_sword", "_pickaxe", ":mace"].iter().any(|t| s.item.ends_with(t)))
}

fn empty_hotbar(game: &Game<'_>) -> Option<usize> {
    (0..9).find(|&h| game.inventory.get(h).is_some_and(Option::is_none))
}

// Where to eat from: None for the off hand (while the main hand does nothing, or an empty hotbar slot can take it),
// else the inventory slot (0 to 8 the hotbar) of the best food.
fn food_slot(game: &Game<'_>, m: &Module) -> Option<Option<usize>> {
    if edible(game, m, game.offhand.as_ref()) && (hand_inert(game) || empty_hotbar(game).is_some()) {
        return Some(None);
    }
    let value = |i: usize| -> Option<f32> {
        let stack = game.inventory.get(i)?.as_ref();
        let (nutrition, saturation) = game.res.items().get(&stack?.item)?.food?;
        edible(game, m, stack).then(|| match m.p("Food priority") {
            "Combined" => nutrition as f32 + saturation,
            "Hunger" => nutrition as f32,
            _ => saturation,
        })
    };
    let best = |range: std::ops::Range<usize>| {
        range.filter_map(|i| value(i).map(|v| (i, v))).fold(None, |b: Option<(usize, f32)>, (i, v)| if b.is_none_or(|b| v > b.1) { Some((i, v)) } else { b })
    };
    let found = best(0..9).or_else(|| if m.b("Search inventory") { best(9..36) } else { None });
    found.map(|(i, _)| Some(i))
}

// Holds the food: the off hand (with an empty main hand if what it holds would act first), a hotbar slot selected,
// or food from the inventory moved to an empty hotbar slot first. False when there is no room for it.
fn eat_from(game: &mut Game<'_>, slot: Option<usize>) -> bool {
    let at = match slot {
        None => {
            if !hand_inert(game) {
                let Some(empty) = empty_hotbar(game) else {
                    return false;
                };
                hold(game, empty);
            }
            with(|s| s.eat_slot = None);
            return true;
        }
        Some(i) if i < 9 => i,
        Some(i) => {
            let Some(empty) = empty_hotbar(game) else {
                return false;
            };
            if !menu_click(game, &[(i, horizon_client::menu::Input::Pickup), (empty, horizon_client::menu::Input::Pickup)]) {
                return false;
            }
            empty
        }
    };
    hold(game, at);
    with(|s| s.eat_slot = Some(at));
    true
}

pub(super) fn eat_stop(game: &mut Game<'_>) {
    super::sunset_combat_control::release("Auto Eat");
    use winit::event::MouseButton;
    let (prev, aura) = with(|s| {
        s.eating = false;
        (s.eat_prev, std::mem::take(&mut s.eat_paused_aura))
    });
    let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, false);
    hold(game, prev);
    if aura {
        toggle_named(game, "Kill Aura", true);
    }
}

// Debug Report: each module on but Debug Report, with its bind and the settings that differ from their defaults
// (name, value, default; a plugin's module lists all of them), and the profile in use.
pub(super) type ModuleState = (&'static str, Option<String>, Vec<(&'static str, String, String)>);

pub(super) fn debug_modules() -> (String, Vec<ModuleState>) {
    let defaults = defaults();
    with(|s| {
        let list = s
            .modules
            .iter()
            .filter(|m| m.on && m.name != super::sunset_debug::NAME)
            .map(|m| {
                let base = defaults.iter().find(|d| d.name == m.name);
                let changed = m
                    .settings
                    .iter()
                    .filter_map(|x| {
                        let default = base.and_then(|d| d.setting(x.name));
                        default
                            .is_none_or(|d| d.value != x.value)
                            .then(|| (x.name, x.value_text(), default.map_or_else(|| "-".to_owned(), Setting::value_text)))
                    })
                    .collect();
                (m.name, m.key.clone(), changed)
            })
            .collect();
        (s.selection.label(), list)
    })
}

pub(super) fn toggle_named(game: &mut Game<'_>, name: &str, on: bool) {
    if let Some(i) = with(|s| s.find(name)) {
        toggle(game, i, on);
    }
}

pub(super) fn block_colour(preset: &str, name: &str) -> Option<u32> {
    let n = name.strip_prefix("minecraft:").unwrap_or(name);
    let ore = |n: &str| -> Option<u32> {
        let core = n.strip_prefix("deepslate_").unwrap_or(n);
        Some(match core {
            "diamond_ore" => 0xFF55_FFFF,
            "emerald_ore" => 0xFF55_FF55,
            "gold_ore" | "nether_gold_ore" => 0xFFFF_D040,
            "iron_ore" => 0xFFD8_AF93,
            "coal_ore" => 0xFF90_9090,
            "redstone_ore" => 0xFFFF_3030,
            "lapis_ore" => 0xFF30_50FF,
            "copper_ore" => 0xFFE0_7040,
            "nether_quartz_ore" => 0xFFEE_EEEE,
            _ => return None,
        })
    };
    match preset {
        "Ores" => ore(n).or((n == "ancient_debris").then_some(0xFFB0_6040)),
        "Diamond" => matches!(n, "diamond_ore" | "deepslate_diamond_ore").then_some(0xFF55_FFFF),
        "Ancient Debris" => (n == "ancient_debris").then_some(0xFFB0_6040),
        "Spawners" => matches!(n, "spawner" | "trial_spawner").then_some(0xFF80_40FF),
        "Portals" => matches!(n, "nether_portal" | "end_portal" | "end_portal_frame" | "end_gateway").then_some(0xFFB0_50FF),
        _ => None,
    }
}

// Block ESP's search of the loaded blocks around the player, spread over ticks: again when the player has moved, the
// settings changed, or it has been a while.
pub(super) fn scan_blocks(game: &Game<'_>, m: &Module, ticks: u64) {
    let Some(at) = block_pos(game) else {
        return;
    };
    let preset = m.p("Blocks");
    let range = m.n("Range") as i32;
    let kind = ["Ores", "Diamond", "Ancient Debris", "Spawners", "Portals"].iter().position(|p| *p == preset).unwrap_or(0);
    let key = (kind as u64) << 32 | range as u64;
    let facts = game.res.facts();
    with(|s| {
        s.blocks.tick(ticks, at, range, key, 100, 6, |c, x, out| {
            let ys = (c[1] - range).max(-64)..=(c[1] + range).min(320);
            for z in c[2] - range..=c[2] + range {
                for y in ys.clone() {
                    let state = game.world.block(x, y, z);
                    if facts.is_air(state) {
                        continue;
                    }
                    if let Some(col) = block_colour(preset, &facts.get(state).name) {
                        out.push(([x, y, z], col));
                    }
                }
            }
            (2 * range as usize + 1) * ys.count()
        })
    });
}

// A click or several in the player's own inventory (the menu with no
// container open), by the menu's slot numbers: 0 to 8 the hotbar, 9 to 35
// the rest, 500 to 503 the armor.
// Clicks on inventory slots; none at all when one is a slot Loadouts locks.
// Clicks in the player's inventory, for modules that click on their own: only while the server knows you stand still
// (no movement keys, jump, sneak or sprint in the last input sent), as with any screen open: a click while moving is
// what Grim's MultiActionsC flags (and cancels). False when nothing was clicked; the caller tries again later.
pub(super) fn menu_click(game: &mut Game<'_>, ops: &[(usize, horizon_client::menu::Input)]) -> bool {
    if super::sunset_gui_move::inventory_busy() { return false; }
    if ops.iter().any(|&(slot, _)| super::sunset_loadouts::locked(slot)) || !super::remote::sunset_combat_remote::quiet(game) {
        return false;
    }
    let ops: Vec<(Option<usize>, i32, horizon_client::menu::Input)> =
        ops.iter().map(|&(slot, input)| (Some(slot), 0, input)).collect();
    game.remote_menu_ops(&ops)
}

pub(super) fn inventory_idle(game: &Game<'_>) -> bool {
    !super::sunset_gui_move::inventory_busy() && game.native_playing() && game.remote.is_some() && game.remote_menu().1 == "inventory"
}

