// Tells the launcher that a native mod is hidden for as long as this game process runs, without
// touching the installation: `<game folder>/horizon-session/hidden/<mod id>.<pid>.lock`, a file
// this process keeps open under an exclusive lock until it exits. The operating system drops the
// lock when the process ends, crash or kill included, so a file whose lock can be taken is stale
// whoever finds it, and is removed. The launcher's side is docs/hard-panic.md's patch.
use std::fs::{self, File};
use std::path::{Path, PathBuf};
use std::sync::Mutex;

pub(super) const DIR: &str = "horizon-session/hidden";

// The open, locked markers: kept until the process exits.
static HELD: Mutex<Vec<File>> = Mutex::new(Vec::new());

fn root() -> PathBuf {
    // The game folder (`Game::game_dir`): the launcher starts the game in the instance's folder.
    std::env::current_dir().unwrap_or_default()
}

// Hides `id` until this process exits. A marker that can't be made leaves the launcher's list as
// it is; the game's own Options > Mods doesn't depend on it.
pub(super) fn hide(id: &str) {
    if let Ok(file) = hold(&root(), id, std::process::id()) {
        HELD.lock().unwrap_or_else(|e| e.into_inner()).push(file);
    }
}

fn hold(root: &Path, id: &str, pid: u32) -> std::io::Result<File> {
    let dir = root.join(DIR);
    fs::create_dir_all(&dir)?;
    // Locked under another name first: a sweep never finds the marker unlocked.
    let new = dir.join(format!("{id}.{pid}.tmp"));
    let file = File::create(&new)?;
    file.try_lock().map_err(std::io::Error::other)?;
    fs::rename(&new, dir.join(format!("{id}.{pid}.lock")))?;
    Ok(file)
}

// Removes the markers of game processes that have ended (their lock is free), so a crashed
// session leaves nothing behind once the next game starts. Markers still held are left alone.
// Once a process, as Sunset starts.
pub(super) fn sweep() {
    static ONCE: std::sync::Once = std::sync::Once::new();
    ONCE.call_once(|| sweep_in(&root()));
}

fn sweep_in(root: &Path) {
    let dir = root.join(DIR);
    let Ok(entries) = fs::read_dir(&dir) else { return };
    for path in entries.flatten().map(|e| e.path()) {
        if path.extension().is_none_or(|e| e != "lock" && e != "tmp") {
            continue;
        }
        let stale = File::open(&path).is_ok_and(|f| f.try_lock_shared().is_ok());
        if stale {
            let _ = fs::remove_file(&path);
        }
    }
    // Only when empty: `hidden`, then `horizon-session`.
    if fs::remove_dir(&dir).is_ok() {
        let _ = fs::remove_dir(root.join(DIR).parent().unwrap_or(root));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_held_marker_survives_a_sweep_and_a_released_one_does_not() {
        let root = std::env::temp_dir().join(format!("sunset-session-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        let dir = root.join(DIR);
        let held = hold(&root, "sunset", 41).unwrap();
        let ended = hold(&root, "sunset", 42).unwrap();
        drop(ended);
        sweep_in(&root);
        assert!(dir.join("sunset.41.lock").exists());
        assert!(!dir.join("sunset.42.lock").exists());
        // Another handle (another process's view) can't share the lock while it is held.
        let other = File::open(dir.join("sunset.41.lock")).unwrap();
        assert!(matches!(other.try_lock_shared(), Err(fs::TryLockError::WouldBlock)));
        drop((other, held));
        sweep_in(&root);
        assert!(!root.join("horizon-session").exists());
        let _ = fs::remove_dir(&root);
    }
}

// Time Changer and Weather Changer. The server's packets arrive once a frame, between ticks, and write the time and the
// weather straight into the world: the world gets the real ones back before them, and what you asked for again before
// anything is drawn, so a frame never shows the server's and turning a module off gives back what the server last said.

use super::sunset_sky_math::{Cover, Levels, kept, lay, lift, shown_time, shown_weather};
use super::Game;
use std::sync::Mutex;

struct Sky {
    time: Option<Cover<i64>>,
    weather: Option<Cover<Levels>>,
}

static SKY: Mutex<Sky> = Mutex::new(Sky { time: None, weather: None });

fn sky<R>(f: impl FnOnce(&mut Sky) -> R) -> R {
    f(&mut SKY.lock().unwrap_or_else(|e| e.into_inner()))
}

fn levels(game: &Game<'_>) -> Levels {
    let w = &game.world.weather;
    Levels { raining: w.raining, thundering: w.thundering, rain: w.rain_level, thunder: w.thunder_level }
}

fn set_levels(game: &mut Game<'_>, l: Levels) {
    let w = &mut game.world.weather;
    w.raining = l.raining;
    w.thundering = l.thundering;
    w.rain_level = l.rain;
    w.thunder_level = l.thunder;
}

// Before the frame's packets.
pub(super) fn real(game: &mut Game<'_>) {
    if !game.native_window() {
        return;
    }
    let (time, weather) = (game.world.day_time, levels(game));
    let (time, weather) = sky(|s| (lift(&mut s.time, time), lift(&mut s.weather, weather)));
    game.world.day_time = time;
    set_levels(game, weather);
}

// After the packets, and again before drawing. Only over a server's world (single player's is one too): with the world
// in this `Game`, what is here is what gets saved.
pub(super) fn shown(game: &mut Game<'_>) {
    if !game.native_window() {
        return;
    }
    if game.title.is_some() || game.remote.is_none() {
        forget();
        return;
    }
    real(game);
    let on = game.native_on(super::sunset::ID);
    let (time, weather) = super::sunset::with(|s| {
        let get = |name| s.module(name).filter(|m| on && m.on);
        (get("Time Changer").map(|m| m.n("Time") as i64), get("Weather Changer").map(|m| shown_weather(m.p("Weather"))))
    });
    let (real_time, real_weather) = (game.world.day_time, levels(game));
    let (time, weather) = sky(|s| {
        (lay(&mut s.time, real_time, time.map(|t| shown_time(real_time, t))), lay(&mut s.weather, real_weather, weather))
    });
    game.world.day_time = time;
    set_levels(game, weather);
}

// The end of a tick: the clock counts on between the server's updates, the shown time does not.
pub(super) fn keep_shown(game: &mut Game<'_>) {
    game.world.day_time = sky(|s| kept(&s.time, game.world.day_time));
}

// Another world is coming: what was under the cover belongs to this one.
pub(super) fn forget() {
    sky(|s| *s = Sky { time: None, weather: None });
}

// What Time Changer and Weather Changer show laid over what the server said, so that what it said is never lost.

const DAY: i64 = 24000;

#[derive(Clone, Copy, PartialEq, Debug, Default)]
pub(super) struct Levels {
    pub(super) raining: bool,
    pub(super) thundering: bool,
    pub(super) rain: (f32, f32),
    pub(super) thunder: (f32, f32),
}

// The time of day asked for on the server's day: the moon's phase comes from the day.
pub(super) fn shown_time(real: i64, time: i64) -> i64 {
    real.div_euclid(DAY) * DAY + time.rem_euclid(DAY)
}

pub(super) fn shown_weather(weather: &str) -> Levels {
    let (rain, thunder) = match weather {
        "Rain" => (true, false),
        "Thunder" => (true, true),
        _ => (false, false),
    };
    let level = |on: bool| if on { (1.0, 1.0) } else { (0.0, 0.0) };
    Levels { raining: rain, thundering: thunder, rain: level(rain), thunder: level(thunder) }
}

#[derive(Clone, Copy)]
pub(super) struct Cover<T> {
    real: T,
    shown: T,
}

// Takes the cover off: what is underneath, unless something has written over what was shown (a new world, say), which
// is then the real thing.
pub(super) fn lift<T: Copy + PartialEq>(cover: &mut Option<Cover<T>>, now: T) -> T {
    match cover.take() {
        Some(c) if now == c.shown => c.real,
        _ => now,
    }
}

// What to show over `real`: `want`, kept under the cover, or `real` itself.
pub(super) fn lay<T: Copy>(cover: &mut Option<Cover<T>>, real: T, want: Option<T>) -> T {
    *cover = want.map(|shown| Cover { real, shown });
    want.unwrap_or(real)
}

// What is shown, whatever the tick has made of it (the clock keeps counting between the server's updates).
pub(super) fn kept<T: Copy>(cover: &Option<Cover<T>>, now: T) -> T {
    cover.map_or(now, |c| c.shown)
}

// The menu's lists glide to where the wheel put them: their scroll values stay the targets, and what is drawn follows.

use std::sync::Mutex;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::Instant;

// The panels come first, one for each category.
pub(super) const WINDOW: usize = 6;
pub(super) const DASHBOARD: usize = 7;
pub(super) const PICKER: usize = 8;
pub(super) const PANE: usize = 9;
pub(super) const SLOTS: usize = 10;

// ClickGUI's Animations: Off, and everything is at once where it is going.
static ENABLED: AtomicBool = AtomicBool::new(true);

pub(super) fn set_enabled(on: bool) {
    ENABLED.store(on, Ordering::Relaxed);
}

pub(super) fn enabled() -> bool {
    ENABLED.load(Ordering::Relaxed)
}

// How fast the rest of the way closes, per second: nine tenths of it in about 0.14 s.
const RATE: f32 = 16.0;
// This close, it is there.
const NEAR: f32 = 0.05;

struct Glide {
    shown: [Option<f32>; SLOTS],
    last: Option<Instant>,
}

static GLIDE: Mutex<Glide> = Mutex::new(Glide { shown: [None; SLOTS], last: None });

fn glide<R>(f: impl FnOnce(&mut Glide) -> R) -> R {
    f(&mut GLIDE.lock().unwrap_or_else(|e| e.into_inner()))
}

// One frame's step towards the target: the same glide at any frame rate.
fn step(shown: f32, target: f32, dt: f32) -> f32 {
    let next = shown + (target - shown) * (1.0 - (-dt * RATE).exp());
    if (target - next).abs() < NEAR { target } else { next }
}

// Once a frame, with each list's target (None for one not open: it starts at its target when it opens).
pub(super) fn frame(targets: [Option<f32>; SLOTS]) {
    glide(|g| {
        let now = Instant::now();
        let dt = if enabled() { g.last.map_or(0.0, |t| now.duration_since(t).as_secs_f32()) } else { f32::INFINITY };
        g.last = Some(now);
        for (shown, target) in g.shown.iter_mut().zip(targets) {
            *shown = target.map(|t| shown.map_or(t, |v| step(v, t, dt)));
        }
    });
}

// Where a list is drawn: `target` until the frame has seen it.
pub(super) fn shown(slot: usize, target: f32) -> f32 {
    glide(|g| g.shown[slot]).unwrap_or(target)
}

// The list shows new things (another page): no glide from the old place.
pub(super) fn jump(slot: usize) {
    glide(|g| g.shown[slot] = None);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn it_arrives_and_stays_without_passing_the_target() {
        let (mut v, mut last) = (0.0, 0.0);
        for _ in 0..120 {
            v = step(v, 100.0, 1.0 / 60.0);
            assert!(v >= last && v <= 100.0);
            last = v;
        }
        assert_eq!(v, 100.0);
    }

    #[test]
    fn the_frame_rate_does_not_change_the_speed() {
        let (mut fast, mut slow) = (0.0, 0.0);
        for _ in 0..24 {
            fast = step(fast, 100.0, 1.0 / 240.0);
        }
        for _ in 0..3 {
            slow = step(slow, 100.0, 1.0 / 30.0);
        }
        assert!((fast - slow).abs() < 0.001, "{fast} {slow}");
    }

    #[test]
    fn a_long_pause_lands_on_the_target() {
        assert_eq!(step(0.0, 100.0, 10.0), 100.0);
    }

    #[test]
    fn it_scrolls_back_up_too() {
        let v = step(100.0, 0.0, 1.0 / 60.0);
        assert!(v < 100.0 && v > 0.0);
    }
}

// Snap Tap (SOCD "last input wins", as Razer's Snap Tap and Wooting's Rappy Snappy): of two opposite move keys held at
// once, the one pressed last moves you, and letting go of it hands back to the other while that is still held. The
// key that loses is out of the game's held keys for the tick only, so the movement and the server's input packet
// agree; it goes back after the tick. Neutral: both cancel out, as without it.
use super::Game;
use super::sunset::{Category, Module};
use std::sync::Mutex;
use winit::keyboard::KeyCode;

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new("Snap Tap", Category::Movement, "Of two opposite move keys, the last pressed wins.")
            .pick("Mode", &["Last input", "Neutral"])
            .bool("Forward and back", true),
    ]
}

const KEYS: [KeyCode; 4] = [KeyCode::KeyW, KeyCode::KeyS, KeyCode::KeyA, KeyCode::KeyD];

#[derive(Default)]
struct Snap {
    // Which of W, S, A and D were held last tick, and when each was last pressed (a count of presses).
    held: [bool; 4],
    pressed: [u64; 4],
    presses: u64,
    // The keys taken out for this tick, each with the one that won over it.
    took: Vec<(KeyCode, KeyCode)>,
    // The keys that lost last tick, each with the one that won (Debug Report).
    last: Vec<(KeyCode, KeyCode)>,
}

static SNAP: Mutex<Option<Snap>> = Mutex::new(None);

fn snap<R>(f: impl FnOnce(&mut Snap) -> R) -> R {
    f(SNAP.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Snap::default))
}

// The key of each pair that loses to the one pressed after it, with Snap Tap on; held: in the game's keys or on the
// keyboard (behind a screen GUI Move walks you by the keyboard's). A pair pressed in the same tick stays neutral.
fn losers(held: [bool; 4], pressed: [u64; 4], forward_back: bool) -> Vec<(usize, usize)> {
    let pairs: &[(usize, usize)] = if forward_back { &[(0, 1), (2, 3)] } else { &[(2, 3)] };
    pairs
        .iter()
        .filter(|&&(a, b)| held[a] && held[b] && pressed[a] != pressed[b])
        .map(|&(a, b)| if pressed[a] < pressed[b] { (a, b) } else { (b, a) })
        .collect()
}

// Before the tick: the presses seen since the last one counted, then the losing keys taken out. Returns them, for GUI
// Move's keys behind a screen.
pub(super) fn pre_tick(game: &mut Game<'_>, m: Option<&Module>) -> Vec<KeyCode> {
    let held = KEYS.map(|k| game.keys.contains(&k) || game.physical_keys.contains(&k));
    let order = snap(|s| {
        // Keys first seen in the same tick share their count.
        let new = std::array::from_fn::<bool, 4, _>(|i| held[i] && !s.held[i]);
        if new.contains(&true) {
            s.presses += 1;
        }
        for i in (0..4).filter(|&i| new[i]) {
            s.pressed[i] = s.presses;
        }
        s.held = held;
        s.pressed
    });
    let Some(m) = m.filter(|m| m.p("Mode") == "Last input") else {
        snap(|s| s.last.clear());
        return Vec::new();
    };
    let lost: Vec<(KeyCode, KeyCode)> = losers(held, order, m.b("Forward and back")).into_iter().map(|(l, w)| (KEYS[l], KEYS[w])).collect();
    let took = lost.iter().filter(|(k, _)| game.keys.remove(k)).copied().collect();
    snap(|s| {
        s.took = took;
        s.last.clone_from(&lost);
    });
    lost.into_iter().map(|(k, _)| k).collect()
}

// The keys that lost last tick, each with the one that won over it.
pub(super) fn last() -> Vec<(KeyCode, KeyCode)> {
    snap(|s| s.last.clone())
}

// After the tick: a key taken out goes back while the one that won over it is still held (a tick that let go of every
// key, a death or a screen, keeps it out).
pub(super) fn post_tick(game: &mut Game<'_>) {
    for (key, winner) in snap(|s| std::mem::take(&mut s.took)) {
        if game.keys.contains(&winner) {
            game.keys.insert(key);
        }
    }
}

#[cfg(test)]
mod tests {
