// Streamer Mode (Client): your name and other players' names are replaced wherever the game draws text (chat, the tab
// list, the scoreboard, titles, boss bars, tooltips, name tags over heads, signs, every screen, Horizon's own menus and
// Sunset's HUD), as whole words in any case, also split over colours. Yours shows as Your name; others as Player 1,
// Player 2... (Numbered, the same number for a name while it is on) or all as Others' name. The names come from the
// server's player list (and the last word of a listed display name, a nickname), the players in the world, your
// profile and signed-in account, and Also hide. Nothing sent to the server changes: only what is drawn.

use super::Game;
use super::sunset::{Category, Module};
use std::collections::HashMap;
use std::sync::Mutex;
use std::time::{Duration, Instant};

pub(super) const NAME: &str = "Streamer Mode";

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new(NAME, Category::Client, "Hides your name and other players' names on screen.")
            .bool("Hide your name", true)
            .text("Your name", "You")
            .bool("Hide others", true)
            .pick("Others as", &["Numbered", "Fixed"])
            .text("Others' name", "Player")
            .text("Also hide", ""),
    ]
}

#[derive(Default)]
struct State {
    // The number each other name was given while the module is on: every name seen stays hidden (a player who left is
    // still named in chat), with the same number.
    numbers: HashMap<String, usize>,
    // The last list handed to the text hooks, when it was made, and the players it was made from.
    shown: Option<HashMap<String, String>>,
    at: Option<Instant>,
    players: u128,
}

static STATE: Mutex<Option<State>> = Mutex::new(None);

fn state<R>(f: impl FnOnce(&mut State) -> R) -> R {
    f(STATE.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(State::default))
}

// A name Minecraft allows: 1 to 16 letters, digits or _.
fn is_name(s: &str) -> bool {
    (1..=16).contains(&s.len()) && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
}

// The name as text shows it: a Bedrock player's prefix (Geyser's ".Steve") dropped, as it is no part of the word.
fn bare(s: &str) -> &str {
    s.trim_start_matches(|c: char| !(c.is_ascii_alphanumeric() || c == '_'))
}

// A replacement shown in place of a name: one line, at most 32 characters.
fn shown_as(s: &str, fallback: &str) -> String {
    let s: String = s.trim().chars().filter(|c| !c.is_control()).take(32).collect();
    if s.is_empty() { fallback.to_owned() } else { s }
}

// Every frame, also on the title screen: the names to hide, made again at once when a player joins, leaves or comes
// into the world (before the frame draws their name), and four times a second for settings and nicknames.
pub(super) fn frame(game: &Game<'_>) {
    let module = super::sunset::with(|s| s.module(NAME).filter(|m| m.on).cloned()).filter(|_| game.native_on(super::sunset::ID));
    let Some(m) = module else {
        if state(|s| s.shown.take().is_some()) {
            horizon_client_render::hud::sunset_streamer::set(None);
        }
        state(|s| s.numbers.clear());
        return;
    };
    let players = super::remote::sunset_remote::players_changed_key(game);
    let due = state(|s| {
        s.shown.is_none() || s.players != players || s.at.is_none_or(|t| t.elapsed() >= Duration::from_millis(250))
    });
    if !due {
        return;
    }
    let (own, others) = super::remote::sunset_remote::player_names(game);
    let account = horizon_client::auth::current().map(|a| a.name.clone());
    let extra: Vec<String> = m.t("Also hide").split(',').map(|s| s.trim().to_owned()).collect();
    let names = build(&m, own.into_iter().chain(account), others.into_iter().chain(extra));
    state(|s| {
        s.at = Some(Instant::now());
        s.players = players;
        if s.shown.as_ref() != Some(&names) {
            horizon_client_render::hud::sunset_streamer::set(Some(names.clone()));
            s.shown = Some(names);
        }
    });
}

// Each name to hide (lower case) and what shows in its place. Your names win over a player with the same one.
fn build(m: &Module, own: impl Iterator<Item = String>, others: impl Iterator<Item = String>) -> HashMap<String, String> {
    let mut out = HashMap::new();
    if m.b("Hide others") {
        let fixed = shown_as(m.t("Others' name"), "Player");
        let numbered = m.p("Others as") == "Numbered";
        state(|s| {
            for name in others {
                let name = bare(&name);
                if !is_name(name) {
                    continue;
                }
                let next = s.numbers.len() + 1;
                s.numbers.entry(name.to_ascii_lowercase()).or_insert(next);
            }
            for (key, n) in &s.numbers {
                out.insert(key.clone(), if numbered { format!("{fixed} {n}") } else { fixed.clone() });
            }
        });
    }
    if m.b("Hide your name") {
        let yours = shown_as(m.t("Your name"), "You");
        for name in own {
            let name = bare(&name);
            if is_name(name) {
                out.insert(name.to_ascii_lowercase(), yours.clone());
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn module() -> Module {
        defaults().remove(0)
    }

    #[test]
    fn yours_and_others_are_replaced_and_numbers_stay() {
        let m = module();
        let names = build(&m, ["vstxx".to_owned()].into_iter(), ["Notch".into(), "jeb_".into(), "bad name".into()].into_iter());
        assert_eq!(names.get("vstxx").map(String::as_str), Some("You"));
        let notch = names.get("notch").cloned().expect("listed");
        assert!(notch.starts_with("Player "));
        assert!(!names.contains_key("bad name"), "not a Minecraft name");
        let again = build(&m, std::iter::empty(), ["Notch".into(), ".Steve".into()].into_iter());
        assert_eq!(again.get("notch"), Some(&notch), "the same number while on");
        assert!(again.contains_key("jeb_"), "a player who left stays hidden");
        assert!(again.contains_key("steve"), "a Bedrock player's prefix is dropped");
    }

    #[test]
    fn replacements_are_one_short_line() {
        assert_eq!(shown_as("  ", "You"), "You");
        assert_eq!(shown_as("a\nb", "You"), "ab");
        assert_eq!(shown_as(&"x".repeat(40), "You").len(), 32);
        assert!(is_name("jeb_") && !is_name("a b") && !is_name(&"a".repeat(17)));
    }
}

// What goes in your main hand for a fight: Shield (Auto block: the shield up while a player who can hit you is near,
// down when an axe or a crit would get through it; Swap key: a shield in hand on a key, from the hotbar or the main
// inventory, and back on the next press) and Offhand's Double hand (a hotbar totem in hand when a blast or a smash
// near an enemy could take more than the health you have). All of it at the start of
// a tick, before its move packet, and only in a tick no other slot change went in.
use super::sunset::{Category, Module, gui_open, hold, with};
use super::sunset_util as util;
use super::Game;
use horizon_client::items::ItemStack;
use horizon_client::menu::Input;
use std::sync::Mutex;
use winit::event::MouseButton;

const NAME: &str = "Shield";

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new(NAME, Category::Combat, "Blocks with your shield in fights, or swaps one in on a key.")
            .bool("Auto block", true)
            .num("Target distance", 5.0, 1.0, 10.0, 0.5)
            .num("FOV", 90.0, 0.0, 180.0, 5.0)
            .num("Movement threshold", 0.1, 0.0, 10.0, 0.1)
            .num("Sword cooldown correction (%)", 10.0, 0.0, 30.0, 1.0)
            .bool("Disable tracker", true)
            .bool("Swap to sword", false)
            .text("Swap key", "None")
            .bool("From inventory", true)
            .pick("Block hit", &["Off", "Manual", "Predict"])
            .num("Block hit min chance (%)", 70.0, 0.0, 100.0, 1.0)
            .num("Block hit max chance (%)", 90.0, 0.0, 100.0, 1.0)
            .num("Block hit ticks", 3.0, 1.0, 10.0, 1.0)
            .num("Max hurt time (ms)", 50.0, 0.0, 500.0, 10.0)
            .bool("Include ping", true)
            .num("Hold after", 2.0, 0.0, 10.0, 1.0)
            .bool("Require mouse down", false),
    ]
}

// An item borrowed into the hand: the slot held before, the hotbar slot it is in, and the inventory slot it came from
// (swapped into the held slot) if it was not in the hotbar.
#[derive(Clone, Copy)]
struct Borrow {
    previous: usize,
    slot: usize,
    from: Option<usize>,
}

#[derive(Default)]
struct State {
    // Auto block holds the use button (Some(true)) or keeps it up (Some(false)); None: it is yours.
    pressed: Option<bool>,
    // Your last hit: Auto block looks again two ticks after it.
    hit_tick: u64,
    // Block hit: Manual's shield up until this tick after a hit; Predict's ticks you were hurt, the hurt time last tick.
    block_until: u64,
    hurts: Vec<u64>,
    hurt_was: i32,
    // The tick each player near you last started a swing, and their swing clock last tick.
    swings: Vec<(u32, u64, f32)>,
    // The shield's cooldown (disabled by an axe) seen last tick.
    disabled: bool,
    shield: Option<Borrow>,
    // Double hand: not again before this tick; the pearl cooldown seen last tick.
    double_next: u64,
    pearl_cooling: bool,
}

static STATE: Mutex<Option<State>> = Mutex::new(None);

pub(super) fn shutdown(game: &mut Game<'_>) {
    let shield = st(|s| s.shield.take());
    let_go(game);
    if let Some(b) = shield {
        put_back(game, b);
    }
    st(|s| *s = State::default());
}

fn st<R>(f: impl FnOnce(&mut State) -> R) -> R {
    f(STATE.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(State::default))
}

fn module(name: &str) -> Option<Module> {
    with(|s| s.module(name).filter(|m| m.on).cloned())
}

fn live(game: &Game<'_>) -> bool {
    game.remote.is_some()
        && game.native_playing()
        && !gui_open()
        && !game.spectator()
        && game.player.as_ref().is_some_and(|p| p.health.health() > 0.0)
        && util::inventory_idle(game)
}

fn is(stack: Option<&ItemStack>, name: &str) -> bool {
    stack.is_some_and(|s| util::short(&s.item) == name)
}

fn tagged(game: &Game<'_>, item: &str, tag: &str) -> bool {
    game.res.items().item_tags.get(tag).is_some_and(|t| t.contains(item))
}

// Puts `name` in hand: a hotbar one is selected; else, with `inventory`, one from the main inventory changes places
// with what you hold.
fn bring(game: &mut Game<'_>, name: &str, inventory: bool) -> Option<Borrow> {
    if is(game.held(), name) {
        return None;
    }
    let previous = game.selected;
    if let Some(slot) = (0..9).find(|&i| is(game.stack_in(i), name)) {
        hold(game, slot);
        return Some(Borrow { previous, slot, from: None });
    }
    // From the main inventory: a swap click, only while the server knows you stand still (Grim's MultiActionsC).
    let from = (9..36)
        .find(|&i| is(game.stack_in(i), name))
        .filter(|_| inventory && !super::sunset_loadouts::locked(previous) && super::remote::sunset_combat_remote::quiet(game))?;
    game.remote_menu_ops(&[(Some(from), previous as i32, Input::Swap)]);
    Some(Borrow { previous, slot: previous, from: Some(from) })
}

// What `bring` did, undone: the item goes back where it came from, or the slot you held before is held again.
fn put_back(game: &mut Game<'_>, b: Borrow) {
    match b.from {
        Some(from) => {
            game.remote_menu_ops(&[(Some(from), b.slot as i32, Input::Swap)]);
        }
        None if game.selected == b.slot => hold(game, b.previous),
        None => {}
    }
}

// The use button as you hold it.
fn yours(game: &mut Game<'_>) {
    let down = game.physical_buttons.contains(&MouseButton::Right);
    let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, down);
}

fn press(game: &mut Game<'_>, down: bool) {
    if st(|s| s.pressed) != Some(down) {
        let _ = super::remote::sunset_combat_remote::mouse(game, MouseButton::Right, down);
    }
    st(|s| s.pressed = Some(down));
}

fn let_go(game: &mut Game<'_>) {
    if st(|s| s.pressed.take()).is_some() {
        yours(game);
    }
}

// The key handler: Shield's Swap key.
pub(super) fn key(game: &mut Game<'_>, key: &str, pressed: bool) {
    if !pressed || !live(game) {
        return;
    }
    let pressed_key = super::sunset::key_from_text(key);
    let named = |m: &Module, setting: &str| super::sunset::key_from_text(m.t(setting)).is_some_and(|k| Some(k) == pressed_key);
    if let Some(m) = module(NAME).filter(|m| named(m, "Swap key")) {
        match st(|s| s.shield.take()) {
            Some(b) => put_back(game, b),
            None => {
                let b = bring(game, "shield", m.b("From inventory"));
                st(|s| s.shield = b);
            }
        }
    }
}

// The start of a tick; `busy`: a slot changed already in it (a hit's weapon, a slot coming back).
pub(super) fn pre_tick(game: &mut Game<'_>, busy: bool) {
    if !live(game) {
        st(|s| {
            s.shield = None;
            s.swings.clear();
        });
        let_go(game);
        return;
    }
    let busy = busy || !swap_key(game);
    note_swings(game);
    let busy = busy || double_hand(game, busy);
    let shield = module(NAME);
    let hit = shield.as_ref().filter(|m| m.p("Block hit") != "Off").and_then(|m| block_hit(game, m));
    match hit.or_else(|| shield.filter(|m| m.b("Auto block")).and_then(|m| block(game, &m, busy))) {
        Some(down) => press(game, down),
        None => let_go(game),
    }
}

// Swap key's shield: it goes back if you change slot or it leaves your hand. False: a slot changed.
fn swap_key(game: &mut Game<'_>) -> bool {
    let Some(b) = st(|s| s.shield) else {
        return true;
    };
    if module(NAME).is_none() || game.selected != b.slot || !is(game.stack_in(b.slot), "shield") {
        st(|s| s.shield = None);
        if b.from.is_some() && game.selected != b.slot {
            put_back(game, b);
            return false;
        }
    }
    true
}

// Each player's swing start, from their swing clock going up from rest.
fn note_swings(game: &Game<'_>) {
    let now = game.ticks;
    st(|s| {
        s.swings.retain(|(id, _, _)| game.mobs.iter().any(|m| m.id == *id));
        for mob in game.mobs.iter().filter(|m| m.kind.id == "minecraft:player") {
            let anim = mob.anim.attack_anim;
            match s.swings.iter_mut().find(|(id, _, _)| *id == mob.id) {
                Some((_, at, was)) => {
                    if anim > 0.0 && (*was == 0.0 || anim < *was) {
                        *at = now;
                    }
                    *was = anim;
                }
                None => s.swings.push((mob.id, 0, anim)),
            }
        }
    });
}

// Your hit: Auto block waits two ticks before looking again.
pub(super) fn hit(game: &Game<'_>) {
    st(|s| s.hit_tick = game.ticks);
    // Block hit Manual: a share of the hits (a chance rolled between the two) put the shield up for Block hit ticks.
    if let Some(m) = module(NAME).filter(|m| m.p("Block hit") == "Manual") {
        let roll = |salt: u64| super::sunset_rotation::Rng::new(game.ticks.wrapping_mul(0x9E37_79B9_7F4A_7C15) ^ salt).next();
        let (lo, hi) = (m.n("Block hit min chance (%)"), m.n("Block hit max chance (%)").max(m.n("Block hit min chance (%)")));
        if roll(0xB10C) * 100.0 < lo + roll(0xC4A7) * (hi - lo) {
            st(|s| s.block_until = game.ticks + m.n("Block hit ticks") as u64);
        }
    }
}

// Block hit (Sunset's BlockHit), each tick, with a sword, axe or mace in hand and a shield in the off hand: Manual
// keeps the shield up for Block hit ticks after a share of your hits; Predict times the next hit on you from the
// last three gaps between hurts (0.25 to 1.5 s) and puts the shield up from Max hurt time (plus the ping with Include
// ping) before it until Hold after ticks past it, with an enemy player within 6 blocks. With Require mouse down only
// while you hold the use button, and then the shield is down between. None: leave the button to Auto block or you.
fn block_hit(game: &Game<'_>, m: &Module) -> Option<bool> {
    let p = game.player.as_ref()?;
    let now = game.ticks;
    let hurt = p.health.hurt.hurt_time;
    st(|s| {
        if hurt > s.hurt_was {
            s.hurts.push(now);
            let over = s.hurts.len().saturating_sub(4);
            s.hurts.drain(..over);
        }
        s.hurt_was = hurt;
    });
    let held = game.held().map_or("", |h| &*h.item);
    let armed = tagged(game, held, "minecraft:swords") || tagged(game, held, "minecraft:axes") || held == "minecraft:mace";
    if !armed || !is(game.offhand.as_ref(), "shield") || p.fall_flying {
        return None;
    }
    let up = match m.p("Block hit") {
        "Manual" => now > st(|s| s.hit_tick) && now <= st(|s| s.block_until),
        _ => {
            let me = [p.position.x, p.position.y, p.position.z];
            let near = game.mobs.iter().any(|t| util::player_enemy(game, t) && util::dist(me, [t.position.x, t.position.y, t.position.z]) <= 6.0);
            let ping = if m.b("Include ping") { super::remote::sunset_combat_remote::latency(game).unwrap_or(0) } else { 0 };
            let lead = ((m.n("Max hurt time (ms)") + f64::from(ping)) / 50.0).ceil() as u64;
            let next = st(|s| {
                let gaps: Vec<u64> = s.hurts.windows(2).map(|w| w[1] - w[0]).filter(|g| (5..=30).contains(g)).collect();
                let last = *s.hurts.last()?;
                let gap = if gaps.is_empty() { 10 } else { gaps.iter().rev().take(3).sum::<u64>() / gaps.len().min(3) as u64 };
                Some(last + gap.max(10))
            });
            near && next.is_some_and(|at| now + lead >= at && now <= at + m.n("Hold after") as u64)
        }
    };
    if m.b("Require mouse down") {
        return game.physical_buttons.contains(&MouseButton::Right).then_some(up);
    }
    up.then_some(true)
}

// Auto block, each tick: Some(true) to hold the shield up, Some(false) to keep it down, None to leave the button to you.
fn block(game: &mut Game<'_>, m: &Module, busy: bool) -> Option<bool> {
    // Disable tracker: an axe took the shield out (its cooldown runs): the button is yours, and with Swap to sword the
    // sword comes out.
    let shield_down = game.cooldowns.is_on_cooldown("minecraft:shield");
    let newly = shield_down && !st(|s| std::mem::replace(&mut s.disabled, shield_down));
    if !shield_down {
        st(|s| s.disabled = false);
    }
    if m.b("Disable tracker") && shield_down {
        if newly
            && !busy
            && m.b("Swap to sword")
            && let Some(slot) = (0..9).find(|&i| game.stack_in(i).is_some_and(|s| tagged(game, &s.item, "minecraft:swords")))
        {
            hold(game, slot);
        }
        return None;
    }
    if game.ticks < st(|s| s.hit_tick) + 2 {
        return st(|s| s.pressed);
    }
    let p = game.player.as_ref()?;
    let held = game.held().map(|s| s.item.clone());
    let free_hand = held.as_ref().is_none_or(|h| tagged(game, h, "minecraft:swords") || tagged(game, h, "minecraft:axes") || &**h == "minecraft:mace");
    let shield = is(game.held(), "shield") || (is(game.offhand.as_ref(), "shield") && free_hand);
    if !shield || p.fall_flying {
        return None;
    }
    let eye = game.eye_position()?;
    let (yaw, pitch) = (f64::from(game.yaw).to_radians(), f64::from(game.pitch).to_radians());
    let look = [-yaw.sin() * pitch.cos(), -pitch.sin(), yaw.cos() * pitch.cos()];
    let me = [p.position.x, p.position.y, p.position.z];
    let target = game
        .mobs
        .iter()
        .filter(|t| util::player_enemy(game, t))
        .filter(|t| {
            let to = [t.position.x - eye[0], t.position.y + 0.9 - eye[1], t.position.z - eye[2]];
            let len = (to[0] * to[0] + to[1] * to[1] + to[2] * to[2]).sqrt().max(1e-9);
            let angle = ((0..3).map(|i| look[i] * to[i]).sum::<f64>() / len).clamp(-1.0, 1.0).acos().to_degrees();
            angle <= m.n("FOV")
        })
        .min_by(|a, b| util::dist(me, [a.position.x, a.position.y, a.position.z]).total_cmp(&util::dist(me, [b.position.x, b.position.y, b.position.z])))?;
    let away = util::dist(me, [target.position.x, target.position.y, target.position.z]);
    if away > m.n("Target distance") {
        return None;
    }
    let weapon = target.extra.main_hand.as_deref().unwrap_or("");
    // An axe would take the shield out; anything but a sword or a mace does little.
    if tagged(game, weapon, "minecraft:axes") || !(tagged(game, weapon, "minecraft:swords") || weapon == "minecraft:mace") {
        return Some(false);
    }
    // Your own crit on the way down: no shield in the way of it.
    let strength = super::sunset_melee::slot_strength(game, game.selected, 0.0).unwrap_or(0.0);
    if !p.ground.on_ground && p.fall_distance > 0.0 && strength > 0.94 {
        return Some(false);
    }
    // Their sword charged again (a little early, by the correction), and coming at you or within 3 blocks.
    let swung = st(|s| s.swings.iter().find(|(id, _, _)| *id == target.id).map_or(0, |(_, at, _)| *at));
    let ready = (game.ticks.saturating_sub(swung)) as f64 * 50.0 >= 625.0 * (0.94 - m.n("Sword cooldown correction (%)") / 100.0);
    let motion = [target.position.x - target.previous.x, target.position.y - target.previous.y, target.position.z - target.previous.z];
    let speed = (motion[0] * motion[0] + motion[1] * motion[1] + motion[2] * motion[2]).sqrt();
    let to_me = [me[0] - target.position.x, me[1] - target.position.y, me[2] - target.position.z];
    let coming = speed >= m.n("Movement threshold") / 10.0 && (0..3).map(|i| motion[i] * to_me[i]).sum::<f64>() > 0.0;
    if ready && (coming || away <= 3.0) {
        return Some(true);
    }
    // Going up from a jump, the shield stays up; otherwise it comes down.
    Some(!p.ground.on_ground && p.fall_distance <= 0.0)
}

// Offhand's Double hand, each tick (Reswap delay ticks apart): with a totem in the hotbar but not in hand, an enemy
// player within 10 blocks, and no shield up or combat module's hand in use, the totem goes in hand when a threat could
// take what health you have: a crystal there, a charged anchor within 5 of the enemy, (in the air) obsidian below you
// within 5 of them with room for a crystal (counted at half), their mace on the way down at you (6 and 5 a block
// fallen); scaled by Sensitivity. Also when they hold a sword or axe and you are under one health, and (Pearl) as
// you throw a pearl. True: the slot changed.
fn double_hand(game: &mut Game<'_>, busy: bool) -> bool {
    let cooling = game.cooldowns.is_on_cooldown("minecraft:ender_pearl");
    let thrown = cooling && !st(|s| std::mem::replace(&mut s.pearl_cooling, cooling));
    if !cooling {
        st(|s| s.pearl_cooling = false);
    }
    let Some(m) = module("Offhand").filter(|m| m.b("Double hand")) else {
        return false;
    };
    let on = |name: &str| util::listed(m.t("Double hand on"), name);
    if busy || game.ticks < st(|s| s.double_next) || is(game.held(), "totem_of_undying") || game.using.is_some() {
        return false;
    }
    if super::sunset_combat_control::owner().is_some() {
        return false;
    }
    let Some(slot) = (0..9).find(|&i| is(game.stack_in(i), "totem_of_undying")) else {
        return false;
    };
    let Some(p) = game.player.as_ref() else {
        return false;
    };
    let health = f64::from(p.health.health() + p.health.absorption());
    let (me, airborne) = ([p.position.x, p.position.y, p.position.z], !p.ground.on_ground);
    let enemy = game
        .mobs
        .iter()
        .filter(|t| util::player_enemy(game, t))
        .map(|t| (t, util::dist(me, [t.position.x, t.position.y, t.position.z])))
        .filter(|(_, d)| *d <= 10.0)
        .min_by(|a, b| a.1.total_cmp(&b.1))
        .map(|(t, _)| (t.id, [t.position.x, t.position.y, t.position.z], t.extra.main_hand.clone(), t.fall_distance));
    let pearl = thrown && on("pearl");
    let threat = enemy.as_ref().is_some_and(|(_, at, weapon, fall)| {
        let weapon = weapon.as_deref().unwrap_or("");
        let sword = tagged(game, weapon, "minecraft:swords") || tagged(game, weapon, "minecraft:axes");
        let worst = worst_threat(game, &on, *at, me, airborne, weapon == "minecraft:mace", *fall);
        worst * m.n("Double hand sensitivity") >= health || (on("sword") && sword && health < 1.0)
    });
    if !(threat || pearl) {
        return false;
    }
    hold(game, slot);
    st(|s| s.double_next = game.ticks + m.n("Reswap delay (ticks)").max(1.0) as u64);
    true
}

// The most a threat near the enemy at `at` could take from you, each counted by how sure it is.
fn worst_threat(game: &mut Game<'_>, on: &dyn Fn(&str) -> bool, at: [f64; 3], me: [f64; 3], airborne: bool, mace: bool, fall: f64) -> f64 {
    use super::sunset_explosive_damage::{Blast, observed_local_damage};
    let mut budget = super::sunset_explosive_policy::Budget::new(24);
    let mut worst: f64 = 0.0;
    let near = |p: [i32; 3]| util::dist(at, util::center_of(p)) < 5.0;
    if on("crystals") {
        let crystals: Vec<[f64; 3]> = game.crystals.iter().map(|c| [c.position.x, c.position.y, c.position.z]).collect();
        for c in crystals {
            worst = worst.max(observed_local_damage(game, Blast::explosion(c, 6.0), &mut budget).unwrap_or(0.0));
        }
    }
    let base = at.map(|v| v.floor() as i32);
    let mut anchors = Vec::new();
    let mut bases = Vec::new();
    for x in -5..=5 {
        for y in -5..=5 {
            for z in -5..=5 {
                let p = [base[0] + x, base[1] + y, base[2] + z];
                if !near(p) || !game.world.loaded(p[0], p[2]) {
                    continue;
                }
                let name = util::short(&util::facts(game, p).name);
                if name == "respawn_anchor" && on("anchors") && charged(game, p) {
                    anchors.push(p);
                } else if name == "obsidian" && on("obsidian") && airborne && f64::from(p[1]) < me[1] && util::is_air(game, [p[0], p[1] + 1, p[2]]) {
                    bases.push(p);
                }
            }
        }
    }
    for p in anchors {
        worst = worst.max(observed_local_damage(game, Blast::anchor(p), &mut budget).unwrap_or(0.0));
    }
    for p in bases {
        let crystal = [f64::from(p[0]) + 0.5, f64::from(p[1]) + 1.0, f64::from(p[2]) + 0.5];
        worst = worst.max(0.5 * observed_local_damage(game, Blast::explosion(crystal, 6.0), &mut budget).unwrap_or(0.0));
    }
    if on("mace") && mace && fall > 1.5 && at[1] > me[1] {
        worst = worst.max(6.0 + fall * 5.0);
    }
    worst
}

fn charged(game: &Game<'_>, p: [i32; 3]) -> bool {
    let b = game.world.block(p[0], p[1], p[2]);
    game.pack.assets.registry.state(b).and_then(|s| s.properties.get("charges")).is_some_and(|c| c != "0")
}

// Chest Swap's Take off: the elytra on (from anywhere in the inventory, a chestplate taken off to where it was), a
// jump (Auto jump) and the glide opened with a jump press in the air, a firework rocket (Firework: one from the main
// inventory is swapped into the hotbar first and back after), then with Auto disable the chestplate back on after
// Fly time and the module off; without it the module stays on (Firework on space fires one at each Space press
// while you glide) until you turn it off, which swaps back. One step a tick at most, Delay apart, at the start of a
// tick; clicks go with no screen open, as Chest Swap's do.
use super::Game;
use super::sunset::{Module, hold, say, toggle_named, wear, with};
use super::sunset_util as util;
use horizon_protocol::packets::play::{self, Serverbound as S};
use std::sync::Mutex;

const NAME: &str = "Chest Swap";

#[derive(Clone, Copy, PartialEq, Eq, Default)]
enum Stage {
    #[default]
    Idle,
    Arm,
    Equip,
    Rocket,
    Glide,
    Boost,
    Fly,
}

#[derive(Default)]
struct Takeoff {
    stage: Stage,
    next: u64,
    // Where the chestplate went; the rocket's main inventory slot and the hotbar slot it was swapped into.
    chest_back: Option<usize>,
    rocket_back: Option<(usize, usize)>,
    // The hotbar slot from before a rocket was held, and since when you glide.
    slot_back: Option<usize>,
    glide_since: Option<u64>,
    glide_try: u64,
    jump: bool,
    // Firework on space: a press waiting, and the tick the next may go.
    space: bool,
    space_ready: u64,
    roll: u64,
}

static TAKEOFF: Mutex<Option<Takeoff>> = Mutex::new(None);

pub(super) fn shutdown(game: &mut Game<'_>) {
    undo(game);
    st(|s| *s = Takeoff::default());
}

fn st<R>(f: impl FnOnce(&mut Takeoff) -> R) -> R {
    f(TAKEOFF.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Takeoff::default))
}

fn module() -> Option<Module> {
    with(|s| s.module(NAME).filter(|m| m.on && m.p("Mode") == "Take off").cloned())
}

fn item_at(game: &Game<'_>, item: &str) -> Option<usize> {
    (0..36).find(|&i| game.inventory.get(i).and_then(|s| s.as_ref()).is_some_and(|s| util::short(&s.item) == item))
}

fn worn(game: &Game<'_>) -> bool {
    game.armor[1].as_ref().is_some_and(|s| util::short(&s.item) == "elytra")
}

fn gliding(game: &Game<'_>) -> bool {
    game.player.as_ref().is_some_and(|p| p.fall_flying)
}

fn ms_ticks(ms: f64) -> u64 {
    (ms / 50.0).round().max(0.0) as u64
}

// Each step of the routine waits Delay (ticks) after the last.
fn after(game: &Game<'_>, m: &Module) -> u64 {
    game.ticks + (m.n("Delay (ticks)") as u64).max(1)
}

// The chestplate back on, the rocket back where it came from.
fn undo(game: &mut Game<'_>) {
    let (chest, rocket, slot) = st(|s| (s.chest_back.take(), s.rocket_back.take(), s.slot_back.take()));
    if !super::sunset::inventory_idle(game) {
        return;
    }
    if let Some(b) = slot.filter(|&b| b != game.selected) {
        hold(game, b);
    }
    if let Some(i) = chest.filter(|_| worn(game)) {
        wear(game, i, 1);
    }
    if let Some((from, to)) = rocket {
        game.remote_menu_ops(&[(Some(from), to as i32, horizon_client::menu::Input::Swap)]);
    }
}

pub(super) fn key(key: &str, pressed: bool) {
    if pressed && key == "key.keyboard.space" && module().is_some_and(|m| m.b("Firework on space")) {
        st(|s| s.space = s.stage == Stage::Fly);
    }
}

// A rocket used from the hotbar: held now, the slot from before back a step later.
fn rocket(game: &mut Game<'_>) -> bool {
    let Some(slot) = (0..9).find(|&i| game.inventory.get(i).and_then(|s| s.as_ref()).is_some_and(|s| util::short(&s.item) == "firework_rocket")) else {
        return false;
    };
    if game.selected != slot {
        let before = game.selected;
        st(|s| {
            s.slot_back.get_or_insert(before);
        });
        hold(game, slot);
    }
    let sequence = util::sequence(game);
    let yaw = super::sunset::wire_yaw(game, game.yaw);
    game.send(S::UseItem(play::UseItem { hand: 0, sequence, yaw, pitch: game.pitch }));
    game.swing_arm();
    true
}

pub(super) fn pre_input(game: &mut Game<'_>) {
    if st(|s| std::mem::take(&mut s.jump)) {
        super::sunset_melee::press_jump(game);
    }
}

pub(super) fn pre_tick(game: &mut Game<'_>, busy: bool) {
    let Some(m) = module().filter(|_| util::in_world(game)) else {
        if st(|s| s.stage != Stage::Idle) {
            undo(game);
            st(|s| *s = Takeoff { roll: s.roll, ..Takeoff::default() });
        }
        return;
    };
    let now = game.ticks;
    if st(|s| s.stage == Stage::Idle) {
        st(|s| {
            s.stage = Stage::Arm;
            s.next = now;
        });
    }
    if busy || now < st(|s| s.next) {
        return;
    }
    // A slot borrowed for a rocket comes back first.
    if let Some(b) = st(|s| s.slot_back.take()) {
        if b != game.selected {
            hold(game, b);
            st(|s| s.next = after(game, &m));
            return;
        }
    }
    let ground = game.player.as_ref().is_some_and(|p| p.ground.on_ground);
    let stage = st(|s| s.stage);
    match stage {
        Stage::Idle => {}
        Stage::Arm => {
            if !m.b("Require land") || ground {
                st(|s| s.stage = Stage::Equip);
            }
        }
        Stage::Equip => {
            let wants_rocket = m.b("Firework");
            if wants_rocket && item_at(game, "firework_rocket").is_none() {
                say(game, "Take off: no firework rockets.");
                return toggle_named(game, NAME, false);
            }
            if !worn(game) {
                let Some(i) = item_at(game, "elytra") else {
                    say(game, "Take off: no elytra in your inventory.");
                    return toggle_named(game, NAME, false);
                };
                // A click while moving is what Grim's MultiActionsC flags: the elytra waits until you stand still.
                if !super::sunset::inventory_idle(game) || !super::remote::sunset_combat_remote::quiet(game) {
                    return;
                }
                let had_chest = game.armor[1].is_some();
                wear(game, i, 1);
                st(|s| s.chest_back = had_chest.then_some(i));
            }
            st(|s| {
                s.stage = if wants_rocket { Stage::Rocket } else { Stage::Glide };
                s.next = after(game, &m);
            });
        }
        Stage::Rocket => {
            // A rocket only in the main inventory: swapped into an empty hotbar slot (or the held one).
            let in_hotbar = (0..9).any(|i| game.inventory.get(i).and_then(|s| s.as_ref()).is_some_and(|s| util::short(&s.item) == "firework_rocket"));
            if !in_hotbar && let Some(from) = item_at(game, "firework_rocket") {
                if !super::sunset::inventory_idle(game) || !super::remote::sunset_combat_remote::quiet(game) {
                    return;
                }
                let to = (0..9).find(|&i| game.inventory.get(i).is_some_and(Option::is_none)).unwrap_or(game.selected);
                game.remote_menu_ops(&[(Some(from), to as i32, horizon_client::menu::Input::Swap)]);
                st(|s| s.rocket_back = Some((from, to)));
            }
            st(|s| {
                s.stage = Stage::Glide;
                s.next = after(game, &m);
            });
        }
        Stage::Glide => {
            if !worn(game) {
                return;
            }
            if gliding(game) {
                st(|s| {
                    s.glide_since = Some(now);
                    s.stage = if m.b("Firework") { Stage::Boost } else { Stage::Fly };
                });
            } else if ground {
                if m.b("Auto jump") {
                    st(|s| s.jump = true);
                }
            } else if now >= st(|s| s.glide_try) + 8 {
                st(|s| {
                    s.glide_try = now;
                    s.jump = true;
                });
            }
        }
        Stage::Boost => {
            rocket(game);
            st(|s| {
                s.stage = Stage::Fly;
                s.next = after(game, &m);
            });
        }
        Stage::Fly => {
            let since = st(|s| s.glide_since).unwrap_or(now);
            if m.b("Auto disable") && now >= since + ms_ticks(m.n("Fly time (ms)")) {
                undo(game);
                st(|s| *s = Takeoff { roll: s.roll, ..Takeoff::default() });
                return toggle_named(game, NAME, false);
            }
            if st(|s| std::mem::take(&mut s.space)) && gliding(game) && now >= st(|s| s.space_ready) && rocket(game) {
                let (lo, hi) = (m.n("Shortest space cooldown (ms)"), m.n("Longest space cooldown (ms)").max(m.n("Shortest space cooldown (ms)")));
                let r = st(|s| {
                    s.roll = (s.roll ^ now.wrapping_mul(0x9E37_79B9_7F4A_7C15)) | 1;
                    s.roll ^= s.roll << 13;
                    s.roll ^= s.roll >> 7;
                    s.roll ^= s.roll << 17;
                    (s.roll >> 11) as f64 / (1u64 << 53) as f64
                });
                st(|s| {
                    s.space_ready = now + ms_ticks(lo + r * (hi - lo));
                    s.next = after(game, &m);
                });
            }
        }
    }
}

// Kill Aura's Target strafe: while Kill Aura has a target and a move key is held (Strafe when: always, while jump is
// held, or while Speed is on), the move across the ground goes round the target at Strafe radius instead of where the
// keys point, at the speed the move has anyway (walking, sprinting, or Speed's). Each tick it heads for the point of
// the circle a tick's move ahead, so from further out it closes in and from inside it backs out onto the circle. A or
// D picks the way round (to your left or right as you face the target); a wall turns it the other way, and with Avoid
// edges so does a drop of more than three blocks, lava, fire or the like where it is heading (neither way safe: no
// strafe). Riding, gliding or flying it leaves alone.
use super::Game;
use super::sunset::Module;
use super::sunset_util as util;
use std::sync::Mutex;
use winit::keyboard::KeyCode;

// Blocks it keeps you out of with Avoid edges.
const HAZARDS: [&str; 10] = [
    "lava", "fire", "soul_fire", "magma_block", "cactus", "campfire", "soul_campfire", "sweet_berry_bush", "wither_rose", "powder_snow",
];
// The deepest ground looked for under you and ahead, and the drop it lets you take.
const DEEPEST: i32 = 8;
const DROP: i32 = 3;
// Ticks between two turns at walls.
const TURN_TICKS: u64 = 10;

// The way round (1: to your left as you face the target, that is anticlockwise seen from above; -1: to your right)
// and the tick it last turned at a wall.
struct Way {
    side: f64,
    turned: u64,
}

static WAY: Mutex<Way> = Mutex::new(Way { side: 1.0, turned: 0 });

fn way<R>(f: impl FnOnce(&mut Way) -> R) -> R {
    f(&mut WAY.lock().unwrap_or_else(|e| e.into_inner()))
}

// The way (x, z, length 1) this tick's move goes, or None to leave it as it is. `speed_on`: Speed is on.
pub(super) fn direction(game: &Game<'_>, m: &Module, speed_on: bool) -> Option<[f64; 2]> {
    let id = super::sunset_aura::target_id()?;
    let target = game.mobs.iter().find(|t| t.id == id && t.alive() && !t.removed)?;
    let p = game.player.as_ref()?;
    if super::sunset::move_input(game) == (0.0, 0.0) || game.riding.is_some() || p.fall_flying || p.flying {
        return None;
    }
    let wanted = match m.p("Strafe when") {
        "Jump held" => game.physical_keys.contains(&KeyCode::Space),
        "Speed on" => speed_on,
        _ => true,
    };
    if !wanted {
        return None;
    }
    let (left, right) = (game.keys.contains(&KeyCode::KeyA), game.keys.contains(&KeyCode::KeyD));
    let ticks = game.ticks;
    let wall = p.collision.horizontal;
    let side = way(|w| {
        if left != right {
            w.side = if left { 1.0 } else { -1.0 };
        } else if wall && ticks.saturating_sub(w.turned) >= TURN_TICKS {
            w.side = -w.side;
            w.turned = ticks;
        }
        w.side
    });
    let here = [p.position.x, p.position.z];
    let centre = [target.position.x, target.position.z];
    let step = (p.position.x - game.previous_position.x).hypot(p.position.z - game.previous_position.z).clamp(0.1, 1.5);
    let radius = m.n("Strafe radius").max(0.1);
    let first = aim(here, centre, radius, step, side, game.yaw);
    if !m.b("Avoid edges") || safe(game, here, first, step, p.position.y) {
        return Some(first);
    }
    let other = aim(here, centre, radius, step, -side, game.yaw);
    if safe(game, here, other, step, p.position.y) {
        way(|w| w.side = -side);
        return Some(other);
    }
    None
}

// Toward the point of the circle round `centre` that is `step` along it from where you are, `side` round.
fn aim(here: [f64; 2], centre: [f64; 2], radius: f64, step: f64, side: f64, yaw: f32) -> [f64; 2] {
    let off = [here[0] - centre[0], here[1] - centre[1]];
    // Right on the target: out the way you face first.
    let angle = if off[0].hypot(off[1]) < 1e-3 {
        let yaw = f64::from(yaw).to_radians();
        (yaw.cos()).atan2(-yaw.sin())
    } else {
        off[1].atan2(off[0])
    };
    let next = angle + side * (step / radius).min(1.0);
    let point = [centre[0] + radius * next.cos(), centre[1] + radius * next.sin()];
    let to = [point[0] - here[0], point[1] - here[1]];
    let len = to[0].hypot(to[1]);
    if len < 1e-6 {
        // On the point already: along the circle.
        let tangent = [-next.sin() * side, next.cos() * side];
        return tangent;
    }
    [to[0] / len, to[1] / len]
}

// Where a few ticks' move along `dir` takes you is no hazard and no drop of more than three blocks below the ground
// under you now (over no ground already, any way is as good).
pub(super) fn safe(game: &Game<'_>, here: [f64; 2], dir: [f64; 2], step: f64, y: f64) -> bool {
    let ahead = (step * 3.0).clamp(0.6, 2.0);
    let at = [here[0] + dir[0] * ahead, here[1] + dir[1] * ahead];
    let feet = y.floor() as i32;
    let column = |x: f64, z: f64| [x.floor() as i32, z.floor() as i32];
    let [x, z] = column(at[0], at[1]);
    let hazard = |p: [i32; 3]| HAZARDS.contains(&util::short(&util::facts(game, p).name));
    if (-1..=1).any(|dy| hazard([x, feet + dy, z])) {
        return false;
    }
    let depth = |[cx, cz]: [i32; 2]| (1..=DEEPEST).find(|d| !util::is_air(game, [cx, feet - d, cz]));
    let Some(now) = depth(column(here[0], here[1])) else {
        return true;
    };
    depth([x, z]).is_some_and(|d| d <= now + DROP && !hazard([x, feet - d, z]))
}

// A text setting's draft while the GUI's editor is open (Rust's pull request #4): one line, edited at its caret,
// and the setting only changes when Apply is clicked.

pub(super) const MAX_BYTES: usize = 4096;

// One line, of at most MAX_BYTES bytes.
pub(super) fn check(text: &str) -> Result<(), &'static str> {
    if text.len() > MAX_BYTES {
        Err("4096 bytes at most")
    } else if text.chars().any(|c| c.is_control() || matches!(c, '\u{2028}' | '\u{2029}')) {
        Err("one line, no control characters")
    } else {
        Ok(())
    }
}

#[derive(Clone, Copy, Debug)]
pub(super) enum EditKey {
    Left,
    Right,
    Home,
    End,
    Backspace,
    Delete,
    SelectAll,
}

#[derive(Clone, Debug)]
pub(super) struct Draft {
    text: String,
    // A byte offset on a character boundary.
    caret: usize,
    selected: bool,
    pub(super) error: Option<&'static str>,
}

impl Draft {
    pub(super) fn new(text: &str) -> Result<Self, &'static str> {
        check(text)?;
        Ok(Self { text: text.to_owned(), caret: text.len(), selected: false, error: None })
    }
    pub(super) fn text(&self) -> &str {
        &self.text
    }
    pub(super) fn caret(&self) -> usize {
        self.caret
    }
    pub(super) fn selected(&self) -> bool {
        self.selected && !self.text.is_empty()
    }
    fn previous(&self) -> usize {
        self.text[..self.caret].char_indices().next_back().map_or(0, |(i, _)| i)
    }
    fn next(&self) -> usize {
        self.caret + self.text[self.caret..].chars().next().map_or(0, char::len_utf8)
    }
    // Typed text at the caret (over the whole text when it is selected); refused whole if it would break the rules.
    pub(super) fn insert(&mut self, text: &str) {
        let kept = if self.selected { 0 } else { self.text.len() };
        if let Err(e) = check(text).and_then(|()| if kept + text.len() > MAX_BYTES { Err("4096 bytes at most") } else { Ok(()) }) {
            self.error = Some(e);
            return;
        }
        if self.selected {
            self.text.clear();
            self.caret = 0;
        }
        self.text.insert_str(self.caret, text);
        self.caret += text.len();
        self.selected = false;
        self.error = None;
    }
    pub(super) fn key(&mut self, key: EditKey) {
        use EditKey::*;
        let selected = std::mem::take(&mut self.selected);
        match key {
            SelectAll => self.selected = true,
            Left => self.caret = if selected { 0 } else { self.previous() },
            Right => self.caret = if selected { self.text.len() } else { self.next() },
            Home => self.caret = 0,
            End => self.caret = self.text.len(),
            Backspace | Delete if selected => {
                self.text.clear();
                self.caret = 0;
            }
            Backspace => {
                let at = self.previous();
                self.text.replace_range(at..self.caret, "");
                self.caret = at;
            }
            Delete => {
                let end = self.next();
                self.text.replace_range(self.caret..end, "");
            }
        }
        self.error = None;
    }
}

// Pearl and wind charge throws: Pearl Catch's Catch key (Up, Fast, Offhand, Diagonal, Diagonal macro); Wind Jump's
// Elytra and Hit charges; Auto Gap's Auto pot and Soup; PvP Bot's escape pearl. A throw goes at the start of a tick, before its move packet, once the server has its look from the last
// one (asked a tick ahead); a hotbar item is held for it and the slot from before comes back at the start of a later
// tick, never after a use in the same one; one slot change a tick.
use super::sunset::{Module, hold, own_id, turn, with};
use super::sunset_rotation::Rng;
use super::sunset_util::{self as util, OFFHAND};
use super::{Game, Screen};
use horizon_client::projectiles::ProjectileKind;
use horizon_protocol::packets::play::{self, Clientbound as C, Serverbound as S};
use std::sync::Mutex;

const CATCH: &str = "Pearl Catch";
const WIND: &str = "Wind Jump";
const GAP: &str = "Auto Gap";
const BOT: &str = "PvP Bot";

// A pearl leaves at 1.5 blocks a tick, slowed by 0.99 and pulled down 0.03 a tick; a wind charge flies at 1.5.
const THROW_SPEED: f64 = 1.5;
const PEARL_DRAG: f64 = 0.99;
const PEARL_GRAVITY: f64 = 0.03;

#[derive(Clone, Copy, PartialEq, Eq)]
pub(super) enum Item {
    Pearl,
    Wind,
    // A splash potion of healing.
    HealPot,
    // Mushroom stew (soup servers heal with it at once).
    Soup,
}

// A splash potion's effect without its long_ or strong_ prefix.
fn potion_kind(s: &horizon_client::items::ItemStack) -> Option<&str> {
    (util::short(&s.item) == "splash_potion")
        .then(|| s.potion())
        .flatten()
        .map(|p| util::short(p).trim_start_matches("long_").trim_start_matches("strong_"))
}

// One step of Auto Gap's Soup run: use the item in a hotbar slot, or drop the bowl a soup left.
#[derive(Clone, Copy)]
enum Step {
    Use(usize, Item),
    Bowl(usize),
}

impl Item {
    fn is(self, s: &horizon_client::items::ItemStack) -> bool {
        match self {
            Self::Pearl => util::short(&s.item) == "ender_pearl",
            Self::Wind => util::short(&s.item) == "wind_charge",
            Self::HealPot => potion_kind(s) == Some("healing"),
            Self::Soup => util::short(&s.item) == "mushroom_stew",
        }
    }
}

// The look a throw goes with: a set one, or your yaw at a pitch.
#[derive(Clone, Copy)]
enum Aim {
    At(f32, f32),
    Pitch(f32),
}

impl Aim {
    fn look(self, game: &Game<'_>) -> (f32, f32) {
        match self {
            Self::At(yaw, pitch) => (yaw, pitch.clamp(-90.0, 90.0)),
            Self::Pitch(pitch) => (game.yaw, pitch.clamp(-90.0, 90.0)),
        }
    }
}

// One throw waiting: who asked, what, the look, not before tick `at` and not after `until`; and a jump with it from
// the ground.
#[derive(Clone, Copy)]
struct Single {
    owner: &'static str,
    item: Item,
    aim: Aim,
    at: u64,
    until: u64,
    jump: bool,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Mode {
    Up,
    Fast,
    Offhand,
    Diagonal,
    Macro,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Phase {
    Prep,
    Pearl,
    Wind,
    Restore,
}

// Pearl Catch's Catch key: the pearl and the wind charge after it. `wind_at` is the tick the charge goes; `thrown` the
// pearl's; `plan` Diagonal's charge look; `offhand_from` the hotbar slot Offhand swapped its charge from.
#[derive(Clone, Copy)]
struct Catch {
    mode: Mode,
    phase: Phase,
    yaw: f32,
    wind_at: u64,
    thrown: u64,
    plan: Option<(f32, f32)>,
    offhand_from: Option<usize>,
    until: u64,
}

// A pearl or wind charge in flight as first seen: where, when, whether near your eyes, and its owner's entity id when
// the server named one.
#[derive(Clone, Copy)]
struct Seen {
    id: u32,
    item: Item,
    first: [f64; 3],
    tick: u64,
    near_me: bool,
}

#[derive(Default)]
struct Throws {
    rng: Option<Rng>,
    single: Option<Single>,
    catch: Option<Catch>,
    // The slot held before the first borrowed one, the tick of the last use, and the combat lease held.
    back: Option<usize>,
    used: u64,
    lease: Option<&'static str>,
    // A jump in this tick's input.
    jump: bool,
    seen: Vec<Seen>,
    owners: Vec<(u32, u32)>,
    last_pearl: u64,
    last_wind: u64,
    last_pot: u64,
    // Wind Jump: the last charge hit, the last Elytra charge, the last glide try.
    hit_at: u64,
    elytra_at: u64,
    glide_at: u64,
    keys_down: Vec<String>,
    // Auto Gap's Soup run: what is left of it, whose it is, the tick its next step may
    // go, and the gap after each step (shortest and longest, ms).
    queue: std::collections::VecDeque<Step>,
    queue_owner: &'static str,
    queue_at: u64,
    queue_gap: (f64, f64),
}

impl Throws {
    // The last pearl, wind charge and healing potion used, for the gaps between them.
    fn note_use(&mut self, item: Item, now: u64) {
        match item {
            Item::Pearl => self.last_pearl = now,
            Item::Wind => self.last_wind = now,
            Item::HealPot => self.last_pot = now,
            Item::Soup => {}
        }
    }
}

static THROWS: Mutex<Option<Throws>> = Mutex::new(None);

fn st<R>(f: impl FnOnce(&mut Throws) -> R) -> R {
    f(THROWS.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Throws::default))
}

fn module(name: &str) -> Option<Module> {
    with(|s| s.module(name).filter(|m| m.on).cloned())
}

fn roll(game: &Game<'_>, lo: f64, hi: f64) -> f64 {
    let (lo, hi) = if lo <= hi { (lo, hi) } else { (hi, lo) };
    let r = st(|s| s.rng.get_or_insert_with(|| Rng::new(game.ticks ^ 0x5DEE_CE66_D1CE_4E5B)).next());
    lo + r * (hi - lo)
}

// Milliseconds as ticks.
fn ticks_of(ms: f64) -> u64 {
    (ms / 50.0).ceil().max(0.0) as u64
}

fn wrap(d: f32) -> f32 {
    (d + 180.0).rem_euclid(360.0) - 180.0
}

fn same_look(a: (f32, f32), b: (f32, f32)) -> bool {
    wrap(a.0 - b.0).abs() < 0.05 && (a.1 - b.1).abs() < 0.05
}

fn add(a: [f64; 3], b: [f64; 3]) -> [f64; 3] {
    [a[0] + b[0], a[1] + b[1], a[2] + b[2]]
}

fn scale(a: [f64; 3], k: f64) -> [f64; 3] {
    [a[0] * k, a[1] * k, a[2] * k]
}

fn look_to(from: [f64; 3], to: [f64; 3]) -> (f32, f32) {
    let d = [to[0] - from[0], to[1] - from[1], to[2] - from[2]];
    let flat = d[0].hypot(d[2]);
    ((-d[0]).atan2(d[2]).to_degrees() as f32, (-d[1].atan2(flat).to_degrees()) as f32)
}

fn live(game: &Game<'_>) -> bool {
    game.remote.is_some()
        && util::in_world(game)
        && !game.spectator()
        && game.player.as_ref().is_some_and(|p| p.health.health() > 0.0)
}

fn playing(game: &Game<'_>) -> bool {
    game.screen == Screen::Playing && !super::sunset::gui_open()
}

// Your movement along your yaw (blocks a tick).
fn forward_speed(game: &Game<'_>, yaw: f32) -> f32 {
    let Some(p) = game.player.as_ref() else {
        return 0.0;
    };
    let r = f64::from(yaw).to_radians();
    (p.velocity.x * -r.sin() + p.velocity.z * r.cos()) as f32
}

// ---- items

fn usable(game: &Game<'_>, slot: usize, item: Item) -> bool {
    game.stack_in(slot).is_some_and(|s| {
        item.is(s)
            && s.count > 0
            && !game.res.items().get(&s.item).is_some_and(|i| {
                game.cooldowns.is_on_cooldown(&horizon_client::cooldowns::group(s, i.use_cooldown.as_ref()))
            })
    })
}

fn has(game: &Game<'_>, slot: usize, item: Item) -> bool {
    game.stack_in(slot).is_some_and(|s| item.is(s) && s.count > 0)
}

// Where a throw of `item` comes from: the offhand if it holds one, else the held slot, else the hotbar.
fn slot_of(game: &Game<'_>, item: Item) -> Option<usize> {
    std::iter::once(OFFHAND).chain(std::iter::once(game.selected)).chain(0..9).find(|&s| has(game, s, item))
}

// ---- the throw

// Whether the server has `look` from the last move packet; it is asked for either way (this tick's move packet).
fn have_look(game: &Game<'_>, owner: &'static str, look: (f32, f32)) -> bool {
    let have = super::sunset_combat_wire::sent_look(game).unwrap_or((game.yaw, game.pitch));
    turn(owner, look.0, look.1);
    same_look(have, look)
}

// A throw of `item` from `slot` now: Some(true) thrown, Some(false) waiting (for the look or the hotbar), None it
// can't (gone, or on cooldown).
fn throw_from(game: &mut Game<'_>, owner: &'static str, slot: usize, item: Item, look: (f32, f32)) -> Option<bool> {
    if !usable(game, slot, item) {
        return None;
    }
    let held = st(|s| s.lease);
    if held != Some(owner) {
        if !super::sunset_combat_control::claim(owner) {
            return Some(false);
        }
        if let Some(old) = held {
            super::sunset_combat_control::release(old);
        }
        st(|s| s.lease = Some(owner));
    }
    if !have_look(game, owner, look) {
        return Some(false);
    }
    if slot != OFFHAND && game.selected != slot {
        let before = game.selected;
        st(|s| {
            s.back.get_or_insert(before);
        });
        hold(game, slot);
    }
    let sequence = util::sequence(game);
    let yaw = super::sunset::wire_yaw(game, look.0);
    game.send(S::UseItem(play::UseItem { hand: i32::from(slot == OFFHAND), sequence, yaw, pitch: look.1 }));
    game.swing_arm();
    game.use_delay = game.use_delay.max(2);
    game.clicks.right_click_delay = game.clicks.right_click_delay.max(2);
    let now = game.ticks;
    st(|s| {
        s.used = now;
        s.note_use(item, now);
    });
    Some(true)
}

fn throw(game: &mut Game<'_>, owner: &'static str, item: Item, look: (f32, f32)) -> Option<bool> {
    let slot = slot_of(game, item)?;
    throw_from(game, owner, slot, item, look)
}

// The slot from before comes back (a tick after the last use), and the lease goes, once nothing waits. Whether the
// slot changed.
fn settle(game: &mut Game<'_>) -> bool {
    let (idle, back, used, lease) =
        st(|s| (s.single.is_none() && s.catch.is_none() && s.queue.is_empty(), s.back, s.used, s.lease));
    if !idle || used >= game.ticks {
        return false;
    }
    st(|s| s.back = None);
    if let Some(owner) = lease {
        super::sunset_combat_control::release(owner);
        st(|s| s.lease = None);
    }
    match back {
        Some(b) if b < 9 && game.selected != b => {
            hold(game, b);
            true
        }
        _ => false,
    }
}

pub(super) fn reset(game: &mut Game<'_>) {
    let (back, lease) = st(|s| {
        s.queue.clear();
        (s.back.take(), s.lease.take())
    });
    if let Some(b) = back.filter(|&b| b < 9 && b != game.selected && game.player.is_some()) {
        hold(game, b);
    }
    if let Some(owner) = lease {
        super::sunset_combat_control::release(owner);
    }
    for owner in [CATCH, WIND, GAP, BOT] {
        super::sunset::cancel_turns(owner);
    }
    st(|s| {
        s.single = None;
        s.catch = None;
        s.jump = false;
    });
}

// ---- pearls and charges in flight

fn tracked(kind: &ProjectileKind) -> Option<Item> {
    match kind {
        ProjectileKind::EnderPearl => Some(Item::Pearl),
        ProjectileKind::WindCharge => Some(Item::Wind),
        _ => None,
    }
}

fn track(game: &Game<'_>) {
    let eye = game.eye_position();
    let now = game.ticks;
    let flying: Vec<(u32, Item, [f64; 3])> = game
        .creatures
        .projectiles
        .iter()
        .filter(|p| p.id != 0 && !p.stuck)
        .filter_map(|p| tracked(&p.kind).map(|item| (p.id, item, [p.position.x, p.position.y, p.position.z])))
        .collect();
    st(|s| {
        s.seen.retain(|x| flying.iter().any(|(id, ..)| *id == x.id));
        for &(id, item, at) in &flying {
            if !s.seen.iter().any(|x| x.id == id) {
                let near_me = eye.is_some_and(|e| util::dist(e, at) <= 3.0);
                s.seen.push(Seen { id, item, first: at, tick: now, near_me });
            }
        }
    });
}

fn owner_of(id: u32) -> Option<u32> {
    st(|s| s.owners.iter().rev().find(|(i, _)| *i == id).map(|(_, o)| *o)).filter(|&o| o != 0)
}

// Yours: the server named you its owner, or (no owner named) it showed up by your eyes within a few ticks of your
// own throw of one.
fn own(game: &Game<'_>, s: &Seen) -> bool {
    match owner_of(s.id) {
        Some(o) => Some(o) == own_id(game),
        None => {
            let last = st(|t| if s.item == Item::Pearl { t.last_pearl } else { t.last_wind });
            s.near_me && last > 0 && s.tick + 1 >= last && s.tick <= last + 8
        }
    }
}

// Who threw it: the owner the server named, or the nearest player within 3 blocks of where it first showed up (not by
// your eyes).
fn thrower<'a>(game: &'a Game<'_>, s: &Seen) -> Option<&'a horizon_client::mobs::Mob> {
    let me = own_id(game);
    match owner_of(s.id) {
        Some(o) => game.mobs.iter().find(|m| m.id == o && Some(m.id) != me),
        None if !s.near_me => game
            .mobs
            .iter()
            .filter(|m| m.kind.id == "minecraft:player" && Some(m.id) != me && m.alive() && !m.removed)
            .map(|m| (util::dist([m.position.x, m.position.y + 1.5, m.position.z], s.first), m))
            .filter(|(d, _)| *d <= 3.0)
            .min_by(|a, b| a.0.total_cmp(&b.0))
            .map(|(_, m)| m),
        None => None,
    }
}

// A pearl or charge seen for at least two ticks: its speed is the server's by then (the first can be off).
pub(super) fn settled(game: &Game<'_>, id: u32) -> bool {
    st(|s| s.seen.iter().any(|x| x.id == id && x.tick + 2 <= game.ticks))
}

// The entity id of an enemy player who threw the pearl or charge `id` (Anchor Aura's Pearl catch).
pub(super) fn enemy_thrower(game: &Game<'_>, id: u32) -> Option<u32> {
    let s = st(|t| t.seen.iter().find(|x| x.id == id).copied())?;
    if own(game, &s) {
        return None;
    }
    thrower(game, &s).filter(|by| util::player_enemy(game, by)).map(|by| by.id)
}

fn own_pearl_since(game: &Game<'_>, tick: u64) -> bool {
    let seen = st(|s| s.seen.clone());
    seen.iter().any(|s| s.item == Item::Pearl && s.tick + 1 >= tick && own(game, s))
}

// A pearl's flight from `pos` at `vel` until it meets a block: where, after how many ticks, and (with `keep`) the
// points it passes.
pub(super) struct Flight {
    pub(super) land: [f64; 3],
    pub(super) ticks: u32,
    pub(super) path: Vec<[f64; 3]>,
}

pub(super) fn pearl_flight(game: &Game<'_>, mut pos: [f64; 3], mut vel: [f64; 3], max: u32, keep: bool) -> Option<Flight> {
    let mut path = if keep { vec![pos] } else { Vec::new() };
    for tick in 1..=max {
        let next = add(pos, vel);
        let d = util::dist(pos, next);
        if d > 1e-9
            && let Some(hit) = game.clip_ray(pos, scale([next[0] - pos[0], next[1] - pos[1], next[2] - pos[2]], 1.0 / d), d)
        {
            if keep {
                path.push(hit.point);
            }
            return Some(Flight { land: hit.point, ticks: tick, path });
        }
        pos = next;
        if keep {
            path.push(pos);
        }
        vel = [vel[0] * PEARL_DRAG, vel[1] * PEARL_DRAG - PEARL_GRAVITY, vel[2] * PEARL_DRAG];
        if pos[1] < -128.0 {
            break;
        }
    }
    None
}

// A flying pearl's landing (Cart's Pearls, Trajectories).
pub(super) fn pearl_landing(game: &Game<'_>, id: u32, max: u32, keep: bool) -> Option<Flight> {
    let p = game.creatures.projectiles.iter().find(|p| p.id == id && !p.stuck)?;
    pearl_flight(game, [p.position.x, p.position.y, p.position.z], [p.velocity.x, p.velocity.y, p.velocity.z], max, keep)
}

// ---- hooks

// The packets of the last tick: owners of pearls and charges.
pub(super) fn packet(game: &Game<'_>, packet: &C) {
    match packet {
        C::AddEntity(p) => {
            let kind = game.remote.as_ref().and_then(|r| r.builtin.get("minecraft:entity_type")).and_then(|t| t.name(p.kind));
            if matches!(kind, Some("minecraft:ender_pearl" | "minecraft:wind_charge"))
                && let (Ok(id), Ok(owner)) = (u32::try_from(p.id), u32::try_from(p.data))
            {
                st(|s| {
                    s.owners.push((id, owner));
                    if s.owners.len() > 256 {
                        s.owners.remove(0);
                    }
                });
            }
        }
        _ => {}
    }
}

// PvP Bot's escape: one pearl along `look`, once the server has it. False: another throw is waiting.
pub(super) fn escape_pearl(game: &Game<'_>, look: (f32, f32)) -> bool {
    if st(|s| s.single.is_some()) {
        return false;
    }
    let at = game.ticks;
    st(|s| s.single = Some(Single { owner: BOT, item: Item::Pearl, aim: Aim::At(look.0, look.1), at, until: at + 10, jump: false }));
    true
}

// Pearl Catch's Catch key: a press starts its throw.
pub(super) fn key(game: &mut Game<'_>, key: &str, pressed: bool) {
    let fresh = st(|s| {
        let was = s.keys_down.iter().any(|k| k == key);
        if pressed && !was {
            s.keys_down.push(key.to_owned());
        } else if !pressed {
            s.keys_down.retain(|k| k != key);
        }
        pressed && !was
    });
    if !fresh || !live(game) || !playing(game) {
        return;
    }
    let named = |m: &Module, setting: &str| super::sunset::key_from_text(m.t(setting)).as_deref() == Some(key);
    if let Some(m) = module(CATCH).filter(|m| named(m, "Catch key")) {
        catch_start(game, &m);
    }
}

fn start_run(game: &Game<'_>, owner: &'static str, run: std::collections::VecDeque<Step>, gap: (f64, f64)) {
    let at = game.ticks;
    st(|s| {
        s.queue = run;
        s.queue_owner = owner;
        s.queue_at = at;
        s.queue_gap = gap;
    });
}

// Auto Gap's Soup (Sunset's AutoHeal, Legit): at or under Soup health, the first hotbar soup is used, and with Drop
// bowls its bowl dropped, Soup delay after the last.
fn auto_soup(game: &Game<'_>, m: &Module) {
    let health = game.player.as_ref().map_or(20.0, |p| f64::from(p.health.health()));
    let Some(slot) = (0..9).find(|&i| has(game, i, Item::Soup)).filter(|_| health <= m.n("Soup health")) else {
        return;
    };
    let mut run = std::collections::VecDeque::from([Step::Use(slot, Item::Soup)]);
    if m.b("Drop bowls") {
        run.push_back(Step::Bowl(slot));
    }
    let gap = m.n("Soup delay (ms)");
    start_run(game, GAP, run, (gap, gap));
}

// The next step of a run, its gap after the step before.
fn queue_step(game: &mut Game<'_>) {
    let Some(step) = st(|s| s.queue.front().copied()) else {
        return;
    };
    if game.ticks < st(|s| s.queue_at) {
        return;
    }
    let (owner, gap) = st(|s| (s.queue_owner, s.queue_gap));
    if module(owner).is_none() {
        st(|s| s.queue.clear());
        return;
    }
    let done = match step {
        Step::Use(slot, item) => match throw_from(game, owner, slot, item, (game.yaw, game.pitch)) {
            Some(false) => return,
            _ => true,
        },
        Step::Bowl(slot) => {
            if game.selected == slot && game.stack_in(slot).is_some_and(|s| util::short(&s.item) == "bowl") {
                game.remote_drop(false);
            }
            true
        }
    };
    if done {
        let wait = ticks_of(roll(game, gap.0, gap.1)).max(1);
        st(|s| {
            s.queue.pop_front();
            s.queue_at = game.ticks + wait;
        });
    }
}

// ---- the tick

// The start of a tick, before its move packet. `busy`: a hit or a slot change went already this tick.
pub(super) fn pre_tick(game: &mut Game<'_>, busy: bool) {
    let (catch_m, wind_m, bot_m) = (module(CATCH), module(WIND), module(BOT));
    let gap_m = module(GAP).filter(|m| m.b("Auto pot") || m.b("Soup"));
    if live(game) {
        track(game);
    }
    if !live(game) || (catch_m.is_none() && wind_m.is_none() && gap_m.is_none() && bot_m.is_none()) {
        if st(|s| s.back.is_some() || s.lease.is_some() || s.catch.is_some() || s.single.is_some()) {
            reset(game);
        }
        return;
    }
    if busy || !playing(game) {
        return;
    }
    if settle(game) {
        return;
    }
    if let Some(m) = &catch_m
        && st(|s| s.catch.is_some())
    {
        catch_step(game, m);
        return;
    }
    if st(|s| s.single.is_some()) {
        single_step(game);
        return;
    }
    if st(|s| !s.queue.is_empty()) {
        queue_step(game);
        return;
    }
    if let Some(m) = gap_m.as_ref().filter(|m| m.b("Auto pot")) {
        auto_pot(game, m);
    }
    if let Some(m) = gap_m.as_ref().filter(|m| m.b("Soup") && st(|s| s.single.is_none() && game.ticks >= s.queue_at)) {
        auto_soup(game, m);
    }
    if let Some(m) = &wind_m {
        if m.b("Elytra") {
            elytra(game);
        }
        if m.b("Hit charges") && st(|s| s.single.is_none()) {
            hit_charges(game, m);
        }
    }
}

// Auto Gap's Auto pot: a splash potion of healing thrown down at Pot pitch (rolled up to a degree under it), 300 ms
// (6 ticks) apart at least. Auto: at or under Pot health, one from the hotbar (the slot from before back a tick
// later). While holding: whenever you hold one.
fn auto_pot(game: &mut Game<'_>, m: &Module) {
    if game.ticks < st(|s| s.last_pot) + 6 {
        return;
    }
    let ready = match m.p("Pot mode") {
        "While holding" => has(game, game.selected, Item::HealPot),
        _ => {
            let health = game.player.as_ref().map_or(20.0, |p| f64::from(p.health.health()));
            health <= m.n("Pot health") && (0..9).chain(std::iter::once(OFFHAND)).any(|s| has(game, s, Item::HealPot))
        }
    };
    if !ready {
        return;
    }
    let pitch = m.n("Pot pitch") as f32 - 1.0 + roll(game, 0.0, 1.0) as f32;
    let at = game.ticks;
    st(|s| s.single = Some(Single { owner: GAP, item: Item::HealPot, aim: Aim::Pitch(pitch), at, until: at + 10, jump: false }));
}

// The jump a throw asked for, in this tick's input.
pub(super) fn pre_input(game: &mut Game<'_>) {
    if st(|s| std::mem::take(&mut s.jump)) {
        super::sunset_melee::press_jump(game);
    }
}

fn single_step(game: &mut Game<'_>) {
    let Some(one) = st(|s| s.single) else {
        return;
    };
    let now = game.ticks;
    if now > one.until || module(one.owner).is_none() {
        st(|s| s.single = None);
        return;
    }
    let look = one.aim.look(game);
    if now + 1 < one.at {
        return;
    }
    if now < one.at {
        turn(one.owner, look.0, look.1);
        return;
    }
    match throw(game, one.owner, one.item, look) {
        Some(true) => {
            let on_ground = game.player.as_ref().is_some_and(|p| p.ground.on_ground);
            st(|s| {
                s.single = None;
                s.jump = one.jump && on_ground;
            });
        }
        Some(false) => {}
        None => st(|s| s.single = None),
    }
}

// ---- Pearl Catch's Catch key

fn mode_of(m: &Module) -> Mode {
    match m.p("Key mode") {
        "Fast" => Mode::Fast,
        "Offhand" => Mode::Offhand,
        "Diagonal" => Mode::Diagonal,
        "Diagonal macro" => Mode::Macro,
        _ => Mode::Up,
    }
}

fn catch_start(game: &mut Game<'_>, m: &Module) {
    if st(|s| s.catch.is_some()) || game.using.is_some() {
        return;
    }
    let mode = mode_of(m);
    let pearl = (0..9).any(|s| has(game, s, Item::Pearl));
    let wind = (0..9).chain(std::iter::once(OFFHAND)).any(|s| has(game, s, Item::Wind));
    if !pearl || !wind {
        return;
    }
    let phase = if mode == Mode::Offhand && !has(game, OFFHAND, Item::Wind) { Phase::Prep } else { Phase::Pearl };
    let back = game.selected;
    st(|s| {
        s.back.get_or_insert(back);
        s.catch = Some(Catch { mode, phase, yaw: game.yaw, wind_at: 0, thrown: 0, plan: None, offhand_from: None, until: game.ticks + 60 });
    });
}

fn pearl_look(game: &Game<'_>, m: &Module, c: &Catch) -> (f32, f32) {
    match c.mode {
        Mode::Up => (c.yaw, -90.0),
        Mode::Fast => (c.yaw, -(m.n("Pearl angle") as f32)),
        Mode::Offhand => (c.yaw, -(m.n("Offhand pearl angle") as f32)),
        Mode::Diagonal | Mode::Macro => (game.yaw, game.pitch),
    }
}

fn wind_look(game: &Game<'_>, m: &Module, c: &Catch) -> (f32, f32) {
    let lean = forward_speed(game, c.yaw) * 1.6;
    match c.mode {
        Mode::Up => (c.yaw, -90.0 + lean),
        Mode::Fast => (c.yaw, -(m.n("Wind charge angle") as f32) + lean),
        Mode::Offhand => (c.yaw, -(m.n("Offhand wind charge angle") as f32) + lean),
        Mode::Macro => (game.yaw, game.pitch),
        Mode::Diagonal => match c.plan {
            Some(plan) if f64::from(wrap(plan.0 - game.yaw).abs()) <= m.n("Max yaw delta") => plan,
            _ => (game.yaw, game.pitch),
        },
    }
}

fn catch_end(m: &Module) {
    let swap_back = m.b("Swap back");
    st(|s| {
        s.catch = None;
        if !swap_back {
            s.back = None;
        }
    });
}

fn catch_step(game: &mut Game<'_>, m: &Module) {
    let Some(mut c) = st(|s| s.catch) else {
        return;
    };
    let now = game.ticks;
    if now > c.until || game.using.is_some() {
        if c.offhand_from.is_some() {
            c.phase = Phase::Restore;
        } else {
            catch_end(m);
            return;
        }
    }
    match c.phase {
        Phase::Prep => {
            let Some(slot) = (0..9).find(|&s| has(game, s, Item::Wind)) else {
                catch_end(m);
                return;
            };
            if game.selected != slot {
                hold(game, slot);
            }
            game.remote_swap_hands();
            c.offhand_from = Some(slot);
            c.phase = Phase::Pearl;
        }
        Phase::Pearl => {
            let look = pearl_look(game, m, &c);
            let Some(slot) = (0..9).find(|&s| has(game, s, Item::Pearl)) else {
                if c.offhand_from.is_some() {
                    c.phase = Phase::Restore;
                    st(|s| s.catch = Some(c));
                } else {
                    catch_end(m);
                }
                return;
            };
            if c.mode == Mode::Diagonal && c.plan.is_none() {
                match diagonal_plan(game, look) {
                    Some((wait, plan)) => {
                        c.plan = Some(plan);
                        c.wind_at = u64::from(wait);
                    }
                    None => {
                        catch_end(m);
                        return;
                    }
                }
            }
            match throw_from(game, CATCH, slot, Item::Pearl, look) {
                Some(true) => {
                    c.thrown = now;
                    c.wind_at = match c.mode {
                        Mode::Up | Mode::Macro => {
                            let moving = game.player.as_ref().is_some_and(|p| p.velocity.x != 0.0 || p.velocity.z != 0.0);
                            now + ticks_of(m.n(if moving && c.mode == Mode::Up { "Moving delay (ms)" } else { "Wind charge delay (ms)" })).max(1)
                        }
                        Mode::Diagonal => now + c.wind_at.max(1),
                        Mode::Fast | Mode::Offhand => now + 1,
                    };
                    c.until = c.wind_at + 30;
                    c.phase = Phase::Wind;
                }
                Some(false) => {}
                None => {
                    catch_end(m);
                    return;
                }
            }
        }
        Phase::Wind => {
            let look = wind_look(game, m, &c);
            let ready = now >= c.wind_at && (c.mode == Mode::Diagonal || own_pearl_since(game, c.thrown));
            if !ready {
                if now + 1 >= c.wind_at {
                    turn(CATCH, look.0, look.1);
                }
            } else {
                let slot = if c.mode == Mode::Offhand { Some(OFFHAND) } else { slot_of(game, Item::Wind) };
                match slot.and_then(|slot| throw_from(game, CATCH, slot, Item::Wind, look)) {
                    Some(false) => {}
                    _ if c.offhand_from.is_some() => c.phase = Phase::Restore,
                    _ => {
                        catch_end(m);
                        return;
                    }
                }
            }
        }
        Phase::Restore => {
            // A tick after the throw: the charge goes back to its hotbar slot, and the offhand gets back its own item.
            if st(|s| s.used) >= now {
                st(|s| s.catch = Some(c));
                return;
            }
            if let Some(slot) = c.offhand_from {
                if game.selected != slot {
                    hold(game, slot);
                }
                game.remote_swap_hands();
            }
            catch_end(m);
            return;
        }
    }
    st(|s| s.catch = Some(c));
}

// Diagonal: you and the pearl thrown with `look` simulated (you falling or standing, the pearl for 30 ticks); the tick
// (2 to 15 after) and the look of a wind charge (straight at 1.5, with your movement) whose path passes closest to the
// pearl, if within 0.4 of it.
fn diagonal_plan(game: &Game<'_>, look: (f32, f32)) -> Option<(u32, (f32, f32))> {
    let eye = game.eye_position()?;
    let p = game.player.as_ref()?;
    let ground = p.ground.on_ground;
    let inherit = |v: [f64; 3], ground: bool| [v[0], if ground { 0.0 } else { v[1] }, v[2]];
    // Standing, you stay where you are (your step slowing as on the ground); else you fall.
    let mut me = vec![(eye, [p.velocity.x, if ground { 0.0 } else { p.velocity.y }, p.velocity.z], ground)];
    for _ in 0..15 {
        let (pos, v, on) = me[me.len() - 1];
        let next = if on { [v[0] * 0.546, 0.0, v[2] * 0.546] } else { [v[0] * 0.91, (v[1] - 0.08) * 0.98, v[2] * 0.91] };
        me.push((add(pos, v), next, on));
    }
    let mut pearl = vec![add(eye, [0.0, -0.1, 0.0])];
    let mut v = add(scale(super::view_vector(look.0, look.1), THROW_SPEED), inherit(me[0].1, ground));
    for _ in 0..30 {
        let next = add(pearl[pearl.len() - 1], v);
        pearl.push(next);
        v = [v[0] * PEARL_DRAG, v[1] * PEARL_DRAG - PEARL_GRAVITY, v[2] * PEARL_DRAG];
    }
    // The closest a charge thrown at tick `at` with (yaw, pitch) comes to the pearl over `steps` ticks.
    let closest = |at: usize, yaw: f32, pitch: f32, steps: usize| -> f64 {
        let (from, mv, on) = me[at];
        let mut pos = from;
        let v = add(scale(super::view_vector(yaw, pitch), THROW_SPEED), inherit(mv, on));
        let mut best = f64::MAX;
        for j in 1..steps {
            if at + j >= pearl.len() {
                break;
            }
            pos = add(pos, v);
            best = best.min(util::dist(pos, pearl[at + j]));
        }
        best
    };
    let mut best: Option<(f64, usize, f32, f32)> = None;
    for at in 2..=15usize {
        if at + 1 >= pearl.len() {
            break;
        }
        for k in at + 1..pearl.len() {
            let (from, mv, on) = me[at];
            let need = add(add(pearl[k], scale(from, -1.0)), scale(inherit(mv, on), -((k - at) as f64)));
            if need.iter().map(|x| x * x).sum::<f64>() < 1e-6 {
                continue;
            }
            let (yaw0, pitch0) = look_to([0.0; 3], need);
            for pi in -10..=10 {
                for yi in -10..=10 {
                    let (yaw, pitch) = (yaw0 + yi as f32 * 0.5, pitch0 + pi as f32 * 0.5);
                    let d = closest(at, yaw, pitch, k - at + 4);
                    if best.is_none_or(|b| d < b.0) {
                        best = Some((d, at, yaw, pitch));
                    }
                }
            }
        }
    }
    let (mut d, at, mut yaw, mut pitch) = best?;
    let (y0, p0) = (yaw, pitch);
    for pi in -10..=10 {
        for yi in -10..=10 {
            let (y, p) = (y0 + yi as f32 * 0.1, p0 + pi as f32 * 0.05);
            let e = closest(at, y, p, pearl.len() - at);
            if e < d {
                (d, yaw, pitch) = (e, y, p);
            }
        }
    }
    (d <= 0.4).then_some((at as u32, (yaw, pitch.clamp(-90.0, 90.0))))
}

// ---- Wind Jump's Elytra and Hit charges

// Elytra: worn (used from the hotbar if not), a jump from the ground and another in the air to glide, and a wind
// charge straight down when the glide comes within reach of the ground (closer the faster you go forward), at most
// one every 8 ticks.
fn elytra(game: &mut Game<'_>) {
    let now = game.ticks;
    let worn = game.armor[1].as_ref().is_some_and(|s| util::short(&s.item) == "elytra");
    let Some(p) = game.player.as_ref() else {
        return;
    };
    let (ground, gliding, feet) = (p.ground.on_ground, p.fall_flying, [p.position.x, p.position.y, p.position.z]);
    if !worn {
        if let Some(slot) = (0..9).find(|&s| game.stack_in(s).is_some_and(|i| util::short(&i.item) == "elytra")) {
            if game.selected != slot {
                let before = game.selected;
                st(|s| {
                    s.back.get_or_insert(before);
                });
                hold(game, slot);
            }
            let sequence = util::sequence(game);
            game.send(S::UseItem(play::UseItem { hand: 0, sequence, yaw: game.yaw, pitch: game.pitch }));
            st(|s| s.used = now);
        }
        return;
    }
    if ground {
        st(|s| s.jump = true);
        return;
    }
    if !gliding {
        if now >= st(|s| s.glide_at) + 8 {
            st(|s| {
                s.glide_at = now;
                s.jump = true;
            });
        }
        return;
    }
    let above = game.clip_ray(feet, [0.0, -1.0, 0.0], 256.0).map_or(256.0, |h| feet[1] - h.point[1]);
    let lean = f64::from(forward_speed(game, game.yaw).clamp(0.0, 1.0));
    if above > 1.2 - 0.8 * lean || now < st(|s| s.elytra_at) + 8 || !(0..9).chain(std::iter::once(OFFHAND)).any(|s| has(game, s, Item::Wind)) {
        return;
    }
    let pitch = 87.0 + roll(game, 0.0, 3.0) as f32;
    st(|s| {
        s.elytra_at = now;
        s.single = Some(Single { owner: WIND, item: Item::Wind, aim: Aim::Pitch(pitch), at: now, until: now + 4, jump: false });
    });
    single_step(game);
}

// Hit charges: another's wind charge within 5 blocks, in sight and within Hit reach of your eyes, hit away; the look
// goes ahead of it (where it will be next tick) and the hit waits for a server look within 6 degrees of it (two
// ticks apart at least); not while you use an item, nor on the ground with In air only.
fn hit_charges(game: &mut Game<'_>, m: &Module) {
    let now = game.ticks;
    let Some(eye) = game.eye_position() else {
        return;
    };
    let on_ground = game.player.as_ref().is_some_and(|p| p.ground.on_ground);
    if game.using.is_some() || (m.b("In air only") && on_ground) || now < st(|s| s.hit_at) + 2 {
        return;
    }
    if super::sunset_combat_control::owner().is_some_and(|o| o != WIND) {
        return;
    }
    let seen = st(|s| s.seen.clone());
    let feet = game.player.as_ref().map(|p| [p.position.x, p.position.y, p.position.z]).unwrap_or(eye);
    let target = game
        .creatures
        .projectiles
        .iter()
        .filter(|c| c.kind == ProjectileKind::WindCharge && c.id != 0 && !c.stuck)
        .filter(|c| seen.iter().find(|s| s.id == c.id).is_some_and(|s| !own(game, s)))
        .map(|c| (c.id, [c.position.x, c.position.y + 0.156_25, c.position.z], [c.velocity.x, c.velocity.y, c.velocity.z]))
        .filter(|(_, at, _)| util::dist(feet, *at) <= 5.0)
        .min_by(|a, b| util::dist(feet, a.1).total_cmp(&util::dist(feet, b.1)));
    let Some((id, centre, vel)) = target else {
        return;
    };
    if f64::from(wrap(look_to(eye, centre).0 - game.yaw).abs()) > m.n("Max yaw") || !util::clear_line(game, centre, [i32::MIN; 3]) {
        return;
    }
    let (mut yaw, mut pitch) = look_to(eye, add(centre, vel));
    if m.b("Humanized aim") {
        let spread = (1.0 / util::dist(eye, centre).max(1.0)) as f32;
        yaw += (roll(game, -1.0, 1.0) as f32) * spread;
        pitch += (roll(game, -1.0, 1.0) as f32) * spread;
    }
    turn(WIND, yaw, pitch.clamp(-89.9, 89.9));
    let half = 0.156_25;
    let near = [0, 1, 2].map(|k| eye[k].clamp(centre[k] - half, centre[k] + half));
    let have = super::sunset_combat_wire::sent_look(game).unwrap_or((game.yaw, game.pitch));
    let now_look = look_to(eye, centre);
    if util::dist(eye, near) > m.n("Hit reach") || wrap(have.0 - now_look.0).abs() > 6.0 || (have.1 - now_look.1).abs() > 6.0 {
        return;
    }
    game.send(S::Attack(play::Attack { id: id as i32 }));
    game.swing_arm();
    game.send(S::Punch(horizon_protocol::packets::Empty));
    game.reset_attack_strength();
    st(|s| s.hit_at = now);
}

// Shared helpers for Sunset's modules: placing blocks, finding items in the
// hotbar, picking targets, seeing a block through the world.

use super::sunset::{Camera, Canvas, Module, hold, look_at, say, toggle, turn_then, with};
use super::sunset_visual::{Look, draw_box};
use super::{Game, Screen};
use horizon_protocol::packets::{
    Empty,
    play::{self, Serverbound as S},
};
use std::sync::Mutex;

// The next block-action sequence number, from the game's own counter.
pub(super) fn sequence(game: &mut Game<'_>) -> i32 {
    super::remote::sunset_remote::next(game)
}

// Boxes the modules want drawn this frame: where they will place or break.
static SHOW: Mutex<Vec<([i32; 3], u32)>> = Mutex::new(Vec::new());

pub(super) fn show_clear() {
    SHOW.lock().unwrap_or_else(|e| e.into_inner()).clear();
}

pub(super) fn show(pos: [i32; 3], argb: u32) {
    let mut v = SHOW.lock().unwrap_or_else(|e| e.into_inner());
    if v.len() < 600 {
        v.push((pos, argb));
    }
}

pub(super) fn draw_shown(cam: &Camera, out: &mut impl Canvas, lw: f32) {
    for &(p, c) in SHOW.lock().unwrap_or_else(|e| e.into_inner()).iter() {
        let lo = [f64::from(p[0]), f64::from(p[1]), f64::from(p[2])];
        draw_box(cam, out, &Look::BOXED, lo, [lo[0] + 1.0, lo[1] + 1.0, lo[2] + 1.0], c, lw);
    }
}

// ---- block searches spread over ticks

// About how many blocks a search reads in one tick: Block ESP's whole cube (65 blocks a side) takes a second instead
// of one long tick.
const SWEEP_BUDGET: usize = 12_000;
// What a search keeps, nearest first; the drawing stops at the module's Max long before.
const SWEEP_KEEP: usize = 16_384;

// A search of the blocks round the player (Block ESP, Hole ESP, Tunnel ESP, Void ESP, Light Overlay), a slice of
// columns (one x) at a time over as many ticks as it takes; each whole pass replaces what the last one found.
pub(super) struct Sweep<V> {
    // The last whole pass: where, and what the search noted there, nearest its centre first.
    pub(super) found: Vec<([i32; 3], V)>,
    next: Vec<([i32; 3], V)>,
    centre: [i32; 3],
    radius: i32,
    // The next slice while a pass runs.
    x: Option<i32>,
    // The settings the search is for, and the tick its last pass ended (0: none yet).
    key: u64,
    done: u64,
}

impl<V> Default for Sweep<V> {
    fn default() -> Self {
        Self::new()
    }
}

impl<V> Sweep<V> {
    pub(super) const fn new() -> Self {
        Self { found: Vec::new(), next: Vec::new(), centre: [0; 3], radius: 0, x: None, key: 0, done: 0 }
    }

    // One tick of the search round `at`, `radius` slices each way. A pass starts `every` ticks after the last one
    // ended, when the player is `moved` blocks from where it was made, or at once when `key` (what it looks for)
    // changes. `slice(centre, x, out)` searches the slice at `x` and says how many blocks it read. True when a pass
    // ended this tick.
    pub(super) fn tick(
        &mut self,
        ticks: u64,
        at: [i32; 3],
        radius: i32,
        key: u64,
        every: u64,
        moved: i32,
        mut slice: impl FnMut([i32; 3], i32, &mut Vec<([i32; 3], V)>) -> usize,
    ) -> bool {
        if key != self.key {
            self.found.clear();
            self.x = None;
        }
        if self.x.is_none() {
            let far = (0..3).any(|i| (at[i] - self.centre[i]).abs() >= moved);
            if self.done != 0 && key == self.key && ticks.saturating_sub(self.done) < every && !far {
                return false;
            }
            (self.key, self.centre, self.radius, self.x) = (key, at, radius, Some(at[0] - radius));
            self.next.clear();
        }
        let mut read = 0;
        while let Some(x) = self.x.filter(|x| *x <= self.centre[0] + self.radius) {
            read += slice(self.centre, x, &mut self.next);
            self.x = Some(x + 1);
            if self.next.len() > 2 * SWEEP_KEEP {
                self.nearest();
            }
            if read >= SWEEP_BUDGET {
                return false;
            }
        }
        self.nearest();
        std::mem::swap(&mut self.found, &mut self.next);
        self.next.clear();
        self.done = ticks.max(1);
        self.x = None;
        true
    }

    // The pass so far, nearest first and cut to what is kept.
    fn nearest(&mut self) {
        let c = self.centre;
        let far = |p: &[i32; 3]| (0..3).map(|i| i64::from(p[i] - c[i]).pow(2)).sum::<i64>();
        self.next.sort_unstable_by_key(|(p, _)| far(p));
        self.next.truncate(SWEEP_KEEP);
    }
}

// ---- names and lists

pub(super) fn short(name: &str) -> &str {
    name.strip_prefix("minecraft:").unwrap_or(name)
}

// Whether `name` is in a comma separated list (`obsidian, minecraft:anvil`).
pub(super) fn listed(list: &str, name: &str) -> bool {
    let name = short(name);
    list.split(',').any(|x| short(x.trim()) == name)
}

// A name passes a module's list: on it in List mode Whitelist, not on it in Blacklist.
pub(super) fn passes(m: &Module, list: &str, name: &str) -> bool {
    listed(m.t(list), name) != (m.p("List mode") == "Blacklist")
}

// A mob a module with kind switches wants: its kind switched on, with the Entities list adding mob types to that
// (List mode Whitelist) or taking them out of it (Blacklist).
pub(super) fn kind_wanted(of_kind: bool, list: &str, blacklist: bool, id: &str) -> bool {
    if blacklist { of_kind && !listed(list, id) } else { of_kind || listed(list, id) }
}

pub(super) fn toggle_off(game: &mut Game<'_>, name: &str) {
    if let Some(i) = with(|s| s.find(name)) {
        if with(|s| s.modules[i].on) {
            toggle(game, i, false);
        }
    }
}

// ---- blocks

pub(super) fn facts<'a>(game: &'a Game<'_>, p: [i32; 3]) -> &'a horizon_items::blocks::StateFacts {
    game.res.facts().get(game.world.block(p[0], p[1], p[2]))
}

pub(super) fn is_air(game: &Game<'_>, p: [i32; 3]) -> bool {
    game.res.facts().is_air(game.world.block(p[0], p[1], p[2]))
}

// `BlockState.canBeReplaced`: air, fluids, plants.
pub(super) fn replaceable(game: &Game<'_>, p: [i32; 3]) -> bool {
    is_air(game, p) || facts(game, p).replaceable
}

pub(super) fn center_of(p: [i32; 3]) -> [f64; 3] {
    [f64::from(p[0]) + 0.5, f64::from(p[1]) + 0.5, f64::from(p[2]) + 0.5]
}

pub(super) fn dist(a: [f64; 3], b: [f64; 3]) -> f64 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

pub(super) fn player_pos(game: &Game<'_>) -> Option<[f64; 3]> {
    let p = game.player.as_ref()?;
    Some([p.position.x, p.position.y, p.position.z])
}

pub(super) fn block_pos(game: &Game<'_>) -> Option<[i32; 3]> {
    let p = player_pos(game)?;
    Some([p[0].floor() as i32, p[1].floor() as i32, p[2].floor() as i32])
}

// The block the feet are in: on a slab, soul sand, a path, carpet or snow, the block of the position is the one stood
// on, so it is the one above.
pub(super) fn feet_block(game: &Game<'_>) -> Option<[i32; 3]> {
    let p = block_pos(game)?;
    Some(if replaceable(game, p) { p } else { [p[0], p[1] + 1, p[2]] })
}

// Center the player on the middle of its block. The move packet of
// the tick carries it (the server takes one a tick).
pub(super) fn center_player(game: &mut Game<'_>) {
    if let Some(p) = game.player.as_mut() {
        p.position.x = p.position.x.floor() + 0.5;
        p.position.z = p.position.z.floor() + 0.5;
    }
}

// A solid-ish block in the way between the eyes and `to`, sampled along the line.
pub(super) fn clear_line(game: &Game<'_>, to: [f64; 3], except: [i32; 3]) -> bool {
    let Some(eye) = game.eye_position() else {
        return false;
    };
    let d = dist(eye, to);
    let steps = (d * 8.0).ceil().max(1.0) as i32;
    for i in 1..steps {
        let t = f64::from(i) / f64::from(steps);
        let at = [
            (eye[0] + (to[0] - eye[0]) * t).floor() as i32,
            (eye[1] + (to[1] - eye[1]) * t).floor() as i32,
            (eye[2] + (to[2] - eye[2]) * t).floor() as i32,
        ];
        if at != except && !is_air(game, at) && facts(game, at).full_collision {
            return false;
        }
    }
    true
}

// Sunset's `isOutOfRange`, the other way round: within `range` of the eyes,
// and either in plain sight or within `walls`.
pub(super) fn in_reach(game: &Game<'_>, p: [i32; 3], range: f64, walls: f64) -> bool {
    let Some(eye) = game.eye_position() else {
        return false;
    };
    let c = center_of(p);
    let d = dist(eye, c);
    if d > range {
        return false;
    }
    clear_line(game, c, p) || d <= walls
}

// ---- placing

// The directions a block can be clicked from: where the neighbour is, and the
// face of it that points back.
const SIDES: [([i32; 3], i32); 6] = [
    ([0, -1, 0], 1),
    ([0, 1, 0], 0),
    ([0, 0, -1], 3),
    ([0, 0, 1], 2),
    ([-1, 0, 0], 5),
    ([1, 0, 0], 4),
];

// Find a neighbour to click, preferring the face toward the eyes.
pub(super) fn place_side(game: &Game<'_>, p: [i32; 3]) -> Option<([i32; 3], i32)> {
    let eye = game.eye_position()?;
    let c = center_of(p);
    let look = [c[0] - eye[0], c[1] - eye[1], c[2] - eye[2]];
    let mut best: Option<(f64, usize)> = None;
    for (i, (d, _)) in SIDES.iter().enumerate() {
        let n = [p[0] + d[0], p[1] + d[1], p[2] + d[2]];
        if is_air(game, n) {
            continue;
        }
        let f = facts(game, n);
        // A block you would open instead of placing against, or a fluid.
        if f.block_entity || f.fluid_level > 0 {
            continue;
        }
        let relevancy = look[0] * f64::from(d[0]) + look[1] * f64::from(d[1]) + look[2] * f64::from(d[2]);
        if best.is_none_or(|(b, _)| relevancy > b) {
            best = Some((relevancy, i));
        }
    }
    best.map(|(_, i)| {
        let (d, face) = SIDES[i];
        ([p[0] + d[0], p[1] + d[1], p[2] + d[2]], face)
    })
}

pub(super) fn has_support(game: &Game<'_>, p: [i32; 3]) -> bool {
    place_side(game, p).is_some()
}

// Entities that stop a block going in: the player and the living things.
fn obstructed(game: &Game<'_>, p: [i32; 3]) -> bool {
    let lo = [f64::from(p[0]), f64::from(p[1]), f64::from(p[2])];
    let hi = [lo[0] + 1.0, lo[1] + 1.0, lo[2] + 1.0];
    let hits = |a: horizon_core::geometry::Aabb| {
        let (l, h) = (a.min_position(), a.max_position());
        l.x < hi[0] && h.x > lo[0] && l.y < hi[1] && h.y > lo[1] && l.z < hi[2] && h.z > lo[2]
    };
    if game.player.as_ref().is_some_and(|pl| hits(pl.bounds())) {
        return true;
    }
    game.mobs.iter().any(|m| m.alive() && !m.removed && hits(m.bounds()))
}

// Check whether a block can be placed here.
pub(super) fn can_place(game: &Game<'_>, p: [i32; 3], check_entities: bool) -> bool {
    p[1] >= -64 && p[1] < 320 && replaceable(game, p) && (!check_entities || !obstructed(game, p))
}

// Put the block in hotbar `slot` (or the offhand's, slot OFFHAND) at `p`, clicking a
// neighbour (or the position itself when there is none, an air place).
pub(super) fn place_block(game: &mut Game<'_>, p: [i32; 3], slot: usize, rotate: bool, check_entities: bool) -> bool {
    if (slot > 8 && slot != OFFHAND) || game.remote.is_none() || !can_place(game, p, check_entities) {
        return false;
    }
    if game.eye_position().is_none() {
        return false;
    }
    let (neighbor, face) = place_side(game, p).unwrap_or((p, 1));
    let hit = if neighbor == p {
        let c = center_of(p);
        [c[0], c[1] + 0.5, c[2]]
    } else {
        let c = center_of(p);
        let d = [neighbor[0] - p[0], neighbor[1] - p[1], neighbor[2] - p[2]];
        [c[0] + f64::from(d[0]) * 0.5, c[1] + f64::from(d[1]) * 0.5, c[2] + f64::from(d[2]) * 0.5]
    };
    let cursor = [
        (hit[0] - f64::from(neighbor[0])) as f32,
        (hit[1] - f64::from(neighbor[1])) as f32,
        (hit[2] - f64::from(neighbor[2])) as f32,
    ];
    turned_to(game, "Place", rotate, hit, move |game| {
        let before = game.selected;
        let offhand = slot == OFFHAND;
        if !offhand {
            hold(game, slot);
        }
        let seq = sequence(game);
        game.send(S::UseItemOn(play::UseItemOn {
            hand: i32::from(offhand),
            pos: neighbor,
            face,
            cursor,
            inside: false,
            world_border: false,
            sequence: seq,
        }));
        game.swing_arm();
        game.send(S::Punch(Empty));
        if !offhand {
            hold(game, before);
        }
    });
    true
}

// Does `deed`, after the server's look has turned to `at` when `rotate` says so (see turn_then).
pub(super) fn turned_to(
    game: &mut Game<'_>,
    who: &'static str,
    rotate: bool,
    at: [f64; 3],
    deed: impl for<'a, 'b> FnOnce(&'a mut Game<'b>) + Send + 'static,
) {
    match game.eye_position().filter(|_| rotate) {
        Some(eye) => {
            let (yaw, pitch) = look_at(eye, at);
            turn_then(who, yaw, pitch, deed);
        }
        None => deed(game),
    }
}

// ---- items

// The first hotbar slot whose item matches.
pub(super) fn find_hotbar(game: &Game<'_>, want: impl Fn(&str) -> bool) -> Option<usize> {
    (0..9).find(|&i| {
        game.inventory
            .get(i)
            .and_then(|s| s.as_ref())
            .is_some_and(|s| want(short(&s.item)))
    })
}

// The offhand, as a slot place_block takes.
pub(super) const OFFHAND: usize = 40;

// Find a matching item in the offhand first, then the hand, then the rest of the hotbar.
pub(super) fn find_held(game: &Game<'_>, want: impl Fn(&str) -> bool) -> Option<usize> {
    if game.offhand.as_ref().is_some_and(|s| want(short(&s.item))) {
        return Some(OFFHAND);
    }
    let hand = game.inventory.get(game.selected).and_then(|s| s.as_ref()).is_some_and(|s| want(short(&s.item)));
    if hand { Some(game.selected) } else { find_hotbar(game, want) }
}

// Anywhere in the inventory (0 to 35): hotbar first.
pub(super) fn find_inventory(game: &Game<'_>, want: impl Fn(&str) -> bool) -> Option<usize> {
    (0..36).find(|&i| {
        game.inventory
            .get(i)
            .and_then(|s| s.as_ref())
            .is_some_and(|s| want(short(&s.item)))
    })
}

// ---- targets

#[derive(Clone, Debug)]
pub(super) struct Target {
    pub id: u32,
    pub pos: [f64; 3],
    pub prev: [f64; 3],
    pub health: f32,
    pub lo: [f64; 3],
    pub hi: [f64; 3],
    pub player: bool,
    pub kind: String,
}

pub(super) fn mob_target(m: &horizon_client::mobs::Mob) -> Target {
    let b = m.bounds();
    let (lo, hi) = (b.min_position(), b.max_position());
    Target {
        id: m.id,
        pos: [m.position.x, m.position.y, m.position.z],
        prev: [m.previous.x, m.previous.y, m.previous.z],
        health: m.health,
        lo: [lo.x, lo.y, lo.z],
        hi: [hi.x, hi.y, hi.z],
        player: m.kind.id == "minecraft:player",
        kind: m.kind.id.to_string(),
    }
}

// Every other player the client knows of, friends left out.
pub(super) fn other_players(game: &Game<'_>) -> Vec<Target> {
    let names = game.remote_player_names();
    let friends = with(|s| s.friends.clone());
    game.mobs
        .iter()
        .filter(|m| m.kind.id == "minecraft:player" && m.alive() && !m.removed)
        .filter_map(|m| {
            let name = names.iter().find(|(i, _)| *i == m.id).map(|(_, n)| n.clone())?;
            if friends.iter().any(|f| f.eq_ignore_ascii_case(&name)) {
                return None;
            }
            Some(mob_target(m))
        })
        .collect()
}

// A player Crystal Aura and Anchor Aura may hurt: listed as playing in survival or adventure, not a friend, and on no
// team that keeps you from hurting them.
pub(super) fn player_enemy(game: &Game<'_>, mob: &horizon_client::mobs::Mob) -> bool {
    if mob.kind.id != "minecraft:player"
        || !mob.health.is_finite()
        || !mob.alive()
        || mob.removed
        || Some(mob.id) == super::sunset::own_id(game)
        || game.riding == Some(mob.id)
        || !matches!(super::remote::sunset_combat_remote::player_mode(game, mob.id), Some(0 | 2))
    {
        return false;
    }
    let Some(name) = game.remote_player_name(mob.id) else {
        return false;
    };
    if with(|s| s.friends.iter().any(|friend| friend.eq_ignore_ascii_case(name))) {
        return false;
    }
    horizon_client::scoreboard::teams_allow_damage(
        game.score.board.players_team(&game.options.player_name()),
        game.mob_team(mob.id),
    )
}

// The key or mouse button a text setting names is held.
pub(super) fn setting_key_down(game: &Game<'_>, module: &Module, setting: &str) -> bool {
    let Some(name) = super::sunset::key_from_text(module.t(setting)) else {
        return false;
    };
    game.physical_keys.iter().chain(game.keys.iter()).any(|key| horizon_client::keybinds::key_name(*key) == Some(name.as_str()))
        || game.physical_buttons.iter().any(|button| horizon_client::keybinds::mouse_name(*button) == name)
}

// Where a look (yaw, pitch) meets the face (0 down, 1 up, 2 north, 3 south, 4 west, 5 east) of block `clicked`, within
// `range` and reach; None if it meets anything else first.
pub(super) fn block_contact(game: &Game<'_>, look: (f32, f32), clicked: [i32; 3], face: i32, range: f64) -> Option<[f64; 3]> {
    block_hit(game, look, clicked, range).filter(|hit| hit.0 == face).map(|hit| hit.1)
}

// The face (0 down .. 5 east) and point where the look from your eyes first meets the block at `clicked`, within
// `range`: for a click that any face of the block takes (an end crystal on obsidian).
pub(super) fn block_hit(game: &Game<'_>, look: (f32, f32), clicked: [i32; 3], range: f64) -> Option<(i32, [f64; 3])> {
    if !look.0.is_finite() || !look.1.is_finite() || !range.is_finite() {
        return None;
    }
    let (yaw, pitch) = (f64::from(look.0).to_radians(), f64::from(look.1).to_radians());
    let direction = [-yaw.sin() * pitch.cos(), -pitch.sin(), yaw.cos() * pitch.cos()];
    let hit = game.clip_ray(game.eye_position()?, direction, range.min(game.reach())).filter(|hit| hit.pos == clicked)?;
    let face = match hit.face {
        [0, -1, 0] => 0,
        [0, 1, 0] => 1,
        [0, 0, -1] => 2,
        [0, 0, 1] => 3,
        [-1, 0, 0] => 4,
        [1, 0, 0] => 5,
        _ => return None,
    };
    Some((face, hit.point))
}

pub(super) fn every_living(game: &Game<'_>) -> Vec<Target> {
    game.mobs.iter().filter(|m| m.alive() && !m.removed).map(mob_target).collect()
}

// What to call an entity: a player's name, a custom name, or what it is.
pub(super) fn display_name(game: &Game<'_>, mob: &horizon_client::mobs::Mob) -> String {
    let mut name = String::new();
    name_into(game, mob, &mut name);
    name
}

// The same, written over `out`: Nametags reuse one buffer for every mob of every frame.
pub(super) fn name_into(game: &Game<'_>, mob: &horizon_client::mobs::Mob, out: &mut String) {
    out.clear();
    if let Some(n) = game.remote_player_name(mob.id).or(mob.custom_name.as_deref()) {
        out.push_str(n);
        return;
    }
    // "minecraft:zombie_villager" as "Zombie Villager".
    for (i, part) in short(&mob.kind.id).split('_').enumerate() {
        if i > 0 {
            out.push(' ');
        }
        let mut c = part.chars();
        if let Some(f) = c.next() {
            out.extend(f.to_uppercase());
            out.push_str(c.as_str());
        }
    }
}

// Every automated targeting path reads the same cached classification.
pub(super) fn spared(game: &Game<'_>, m: &Module, id: u32, _player: bool) -> bool {
    super::sunset_antibot::blocked_for(id, m)
        || (m.b("Ignore teams")
        && horizon_client::scoreboard::teams_allied(game.score.board.players_team(&game.options.player_name()), game.mob_team(id))
        )
}

pub(super) fn combat_eligible(game: &Game<'_>, m: &Module, mob: &horizon_client::mobs::Mob) -> bool {
    let player = mob.kind.id == "minecraft:player";
    if !mob.alive() || !mob.health.is_finite() || mob.removed
        || Some(mob.id) == super::sunset::own_id(game) || game.riding == Some(mob.id)
        || spared(game, m, mob.id, player)
        || (player && super::remote::sunset_combat_remote::player_mode(game, mob.id) == Some(3))
    { return false; }
    let b = mob.bounds();
    let (lo, hi) = (b.min_position(), b.max_position());
    if [lo.x, lo.y, lo.z, hi.x, hi.y, hi.z].iter().any(|v| !v.is_finite())
        || lo.x >= hi.x || lo.y >= hi.y || lo.z >= hi.z
    { return false; }
    !player || !game.remote_player_name(mob.id).is_some_and(|name|
        with(|s| s.friends.iter().any(|friend| friend.eq_ignore_ascii_case(name))))
}

pub(super) const PRIORITIES: &[&str] = &["Lowest distance", "Highest distance", "Lowest health", "Closest angle"];

// Find the best player within `range` by priority.
pub(super) fn player_target(game: &Game<'_>, range: f64, priority: &str) -> Option<Target> {
    let eye = game.eye_position()?;
    let mut list: Vec<Target> = other_players(game)
        .into_iter()
        .filter(|t| t.health > 0.0 && dist(eye, t.pos) <= range)
        .collect();
    sort_targets(game, &mut list, priority);
    list.into_iter().next()
}

pub(super) fn sort_targets(game: &Game<'_>, list: &mut [Target], priority: &str) {
    let Some(eye) = game.eye_position() else {
        return;
    };
    let angle = |t: &Target| {
        let (yaw, pitch) = look_at(eye, [t.pos[0], t.pos[1] + (t.hi[1] - t.lo[1]) / 2.0, t.pos[2]]);
        let dy = ((yaw - game.yaw + 180.0).rem_euclid(360.0) - 180.0).abs();
        f64::from(dy + (pitch - game.pitch).abs())
    };
    match priority {
        "Highest distance" => list.sort_by(|a, b| dist(eye, b.pos).total_cmp(&dist(eye, a.pos))),
        "Lowest health" => list.sort_by(|a, b| a.health.total_cmp(&b.health)),
        "Closest angle" => list.sort_by(|a, b| angle(a).total_cmp(&angle(b))),
        _ => list.sort_by(|a, b| dist(eye, a.pos).total_cmp(&dist(eye, b.pos))),
    }
}

// A comma list's choices as Pick values need 'static: these are the shared ones.
pub(super) const TRAP_BLOCKS: &str = "obsidian,crying_obsidian,netherite_block";

// A module's own chat line, unless ClickGUI's Module messages is off.
pub(super) fn report(game: &mut Game<'_>, msg: &str) {
    if super::sunset::chat_lines("Module messages") {
        say(game, msg);
    }
}

pub(super) fn inventory_idle(game: &Game<'_>) -> bool {
    super::sunset::inventory_idle(game)
}

// The world or server played, as a number for file names: the world's folder in single player, the address on a server.
pub(super) fn world_hash(game: &Game<'_>) -> Option<u64> {
    let r = game.remote.as_ref()?;
    let address = horizon_client::net::shown_address(&r.session.address);
    let name = if address == "local" { game.world_root.display().to_string() } else { address };
    // FNV-1a.
    Some(name.bytes().fold(0xcbf2_9ce4_8422_2325_u64, |h, b| (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)))
}

pub(super) fn in_world(game: &Game<'_>) -> bool {
    game.native_playing() && game.remote.is_some() && game.player.is_some() && game.screen == Screen::Playing
}

// The most damage the nearest end crystal would do to something standing at `at`
// (a power 6 blast with nothing in the way and no armour, without a raycast).
pub(super) fn crystal_damage(game: &Game<'_>, at: [f64; 3]) -> f64 {
    let mut worst: f64 = 0.0;
    for c in &game.crystals {
        let from = [c.position.x, c.position.y, c.position.z];
        let d = dist(from, at) / 12.0;
        if d > 1.0 {
            continue;
        }
        let impact = 1.0 - d;
        worst = worst.max(((impact * impact + impact) / 2.0 * 7.0 * 12.0 + 1.0).floor());
    }
    worst
}

// Anti Vanish (Sunset's AntiVanish): a player who leaves the tab list with no chat line about them has likely gone
// into vanish, and one who comes back with none has come out of it. Completion check also asks the server which
// names a command (/msg) completes: a name it completes that the tab list doesn't show is online but hidden; it is said
// once it has come back Confirmations times in a row (a stale completion comes once). Watched players narrows all of
// it to some names; Server watchlists gives a server its own.
//
// What vanish plugins leave in the player info (after Donut Client 3.0's Staff Detector): Spectators, a player the
// server reports in spectator mode (staff watching from the camera); Invisible players, a player entity sent within
// Nearby range while invisible; Unlisted players, one the server keeps in the player info but hides from the tab list.
// Shop and lobby NPCs are unlisted players too, so that check needs a watchlist: it looks only at the names on it.
// Each is said once when it starts.

use super::Game;
use super::sunset::{Category, Module, with};
use horizon_protocol::buf::{Reader, Writer};
use horizon_protocol::packets::play::Serverbound as S;
use std::collections::HashMap;
use std::sync::Mutex;

pub(super) fn defaults() -> Vec<Module> {
    vec![
        Module::new("Anti Vanish", Category::Player, "Reports vanished players.")
            .num("Interval", 100.0, 20.0, 600.0, 10.0)
            .text("Watched players", "")
            .text("Server watchlists", "")
            .bool("Completion check", false)
            .text("Command", "msg")
            .num("Confirmations", 2.0, 1.0, 10.0, 1.0)
            .bool("Spectators", true)
            .bool("Invisible players", true)
            .num("Nearby range", 64.0, 8.0, 256.0, 8.0)
            .bool("Unlisted players", true),
    ]
}

pub(super) fn visible(m: &Module, name: &str) -> bool {
    match name {
        "Command" | "Confirmations" => m.b("Completion check"),
        "Nearby range" => m.b("Invisible players"),
        _ => true,
    }
}

// Sunset's completion requests: the game numbers its own up from 0.
const ASK: i32 = -0x5355;

#[derive(Default)]
struct Vs {
    // The server joined last (its address as typed), the ticks since the last check, the tab list's names then
    // (None before the first).
    server: String,
    timer: u32,
    tab: Option<Vec<String>>,
    // How many completions in a row have named each hidden name.
    streak: HashMap<String, u32>,
    // The players in spectator mode, invisible near you and unlisted at the last look.
    spectators: Vec<String>,
    invisible: Vec<String>,
    unlisted: Vec<String>,
}

static VS: Mutex<Option<Vs>> = Mutex::new(None);

fn vs<R>(f: impl FnOnce(&mut Vs) -> R) -> R {
    let mut g = VS.lock().unwrap_or_else(|e| e.into_inner());
    f(g.get_or_insert_with(Vs::default))
}

// A connection starts: everything known is the last server's.
pub(super) fn connecting(address: &str) {
    vs(|v| {
        *v = Vs {
            server: address.to_owned(),
            ..Vs::default()
        }
    });
}

// An address without its port, for comparing.
fn host(address: &str) -> &str {
    let address = address.trim();
    match address.rsplit_once(':') {
        Some((host, port)) if port.bytes().all(|b| b.is_ascii_digit()) => host,
        _ => address,
    }
}

// The names the module tells you about here: the server's own watchlist if it has one, else Watched players (empty:
// everyone).
fn watchlist<'a>(m: &'a Module, server: &str) -> &'a str {
    m.t("Server watchlists")
        .split(';')
        .filter_map(|entry| entry.split_once('='))
        .find(|(s, _)| host(s).eq_ignore_ascii_case(host(server)))
        .map_or(m.t("Watched players"), |(_, names)| names)
}

fn watched(m: &Module, server: &str, name: &str) -> bool {
    let list = watchlist(m, server);
    list.trim().is_empty() || list.split(',').any(|n| n.trim().eq_ignore_ascii_case(name))
}

// A name a player can have: up to 16 letters, digits and underscores (NPCs often have others).
fn player_name(name: &str) -> bool {
    (1..=16).contains(&name.len()) && name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_')
}

pub(super) fn tick(game: &mut Game<'_>, m: Option<&Module>) {
    let Some(m) = m.filter(|_| game.remote.is_some()) else {
        vs(|v| {
            v.timer = 0;
            v.tab = None;
            v.streak.clear();
            v.spectators.clear();
            v.invisible.clear();
            v.unlisted.clear();
        });
        return;
    };
    if game.ticks % 10 == 0 {
        presence(game, m);
    }
    let due = vs(|v| {
        v.timer += 1;
        v.timer >= m.n("Interval") as u32
    });
    if !due {
        return;
    }
    let now = super::remote::sunset_remote::tab_names(game);
    // A leave or join message names the player: the newest chat lines are where it would be.
    let chat = game.remote_chat(20).unwrap_or_default();
    let quiet = |name: &str| !chat.iter().any(|line| line.contains(name));
    let (server, before) = vs(|v| {
        v.timer = 0;
        (v.server.clone(), v.tab.replace(now.clone()))
    });
    let mut lines = Vec::new();
    for name in before.iter().flatten().filter(|n| !now.contains(n)) {
        if watched(m, &server, name) && quiet(name) {
            lines.push(format!("{name} left the tab list with no leave message: gone into vanish?"));
        }
    }
    for name in now.iter().filter(|n| before.as_ref().is_some_and(|b| !b.contains(n))) {
        if watched(m, &server, name) && quiet(name) {
            lines.push(format!("{name} came back to the tab list with no join message: out of vanish?"));
        }
    }
    if m.b("Completion check") {
        let mut w = Writer::new();
        w.varint(ASK);
        w.string(&format!("/{} ", m.t("Command").trim().trim_start_matches('/')));
        game.send(S::Unknown(horizon_protocol::ids::play::serverbound::COMMAND_SUGGESTION, w.data));
    }
    for line in lines {
        super::sunset_util::report(game, &line);
    }
}

// Spectators, Invisible players and Unlisted players: who each shows now, and a line for each new one.
fn presence(game: &mut Game<'_>, m: &Module) {
    let server = vs(|v| v.server.clone());
    let info = super::remote::sunset_remote::tab_presence(game);
    let spectators: Vec<String> = if m.b("Spectators") {
        info.iter().filter(|(n, mode, _)| *mode == 3 && watched(m, &server, n)).map(|(n, ..)| n.clone()).collect()
    } else {
        Vec::new()
    };
    let unlisted: Vec<String> = if m.b("Unlisted players") && !watchlist(m, &server).trim().is_empty() {
        info.iter().filter(|(n, _, listed)| !listed && player_name(n) && watched(m, &server, n)).map(|(n, ..)| n.clone()).collect()
    } else {
        Vec::new()
    };
    let mut invisible: Vec<(String, f64)> = Vec::new();
    if m.b("Invisible players") && let Some(here) = super::sunset_util::player_pos(game) {
        let me = super::sunset::own_id(game);
        for mob in game.mobs.iter().filter(|x| x.kind.id == "minecraft:player" && x.invisible && x.alive() && !x.removed && Some(x.id) != me) {
            let d = super::sunset_util::dist(here, [mob.position.x, mob.position.y, mob.position.z]);
            if d <= m.n("Nearby range") && let Some(name) = game.remote_player_name(mob.id).filter(|n| watched(m, &server, n)) {
                invisible.push((name.to_owned(), d));
            }
        }
    }
    let lines = vs(|v| {
        let mut lines = Vec::new();
        for n in spectators.iter().filter(|n| !v.spectators.contains(n)) {
            lines.push(format!("{n} is in spectator mode: watching?"));
        }
        for n in unlisted.iter().filter(|n| !v.unlisted.contains(n)) {
            lines.push(format!("{n} is online but kept out of the tab list: in vanish?"));
        }
        for (n, d) in invisible.iter().filter(|(n, _)| !v.invisible.contains(n)) {
            lines.push(format!("{n} is invisible {d:.0} m away"));
        }
        v.spectators = spectators;
        v.unlisted = unlisted;
        v.invisible = invisible.into_iter().map(|(n, _)| n).collect();
        lines
    });
    for line in lines {
        super::sunset_util::report(game, &line);
    }
}

// The server's completions for Sunset's request (true: the game never sees them): names it completes that the tab
// list doesn't show, each told once it has come back Confirmations times in a row, and once only while it stays hidden.
pub(super) fn completions(game: &mut Game<'_>, data: &[u8]) -> bool {
    let mut r = Reader::new(data);
    if r.varint().ok() != Some(ASK) {
        return false;
    }
    let names = (|| {
        r.varint().ok()?;
        r.varint().ok()?;
        let n = r.count(4096).ok()?;
        let mut names = Vec::with_capacity(n);
        for _ in 0..n {
            names.push(r.string(256).ok()?);
            if r.bool().ok()? {
                r.nbt().ok()?;
            }
        }
        Some(names)
    })()
    .unwrap_or_default();
    let tab = super::remote::sunset_remote::tab_names(game);
    let own = game.options.player_name();
    let Some(m) = with(|s| s.module("Anti Vanish").filter(|m| m.on).cloned()) else {
        return true;
    };
    let hidden: Vec<String> = names
        .into_iter()
        .filter(|n| n.len() <= 16 && !n.contains(' ') && *n != own && !tab.contains(n))
        .collect();
    let need = m.n("Confirmations").max(1.0) as u32;
    let (server, new) = vs(|v| {
        v.streak.retain(|n, _| hidden.contains(n));
        let mut new = Vec::new();
        for n in &hidden {
            let streak = v.streak.entry(n.clone()).or_default();
            *streak += 1;
            if *streak == need {
                new.push(n.clone());
            }
        }
        (v.server.clone(), new)
    });
    for name in new.iter().filter(|n| watched(&m, &server, n)) {
        super::sunset_util::report(game, &format!("{name} is online but not in the tab list: in vanish?"));
    }
    true
}

