// Things Sunset needs from the connection's private state.
use crate::game::Game;

// The game's own sequence counter (the server wants block-action sequence
// numbers that never go down), for Sunset's placing and breaking.
pub(crate) fn next(game: &mut Game<'_>) -> i32 {
    game.next_sequence()
}

// A right click for the tick's keybind pass (Minecraft's keyUse.consumeClick): it waits for no use delay, and the
// game places with its own sequence number and prediction, before the tick's movement. Scaffold's Godbridge.
pub(crate) fn press_use(game: &mut Game<'_>) {
    super::sunset_combat_remote::click(game, false);
}

// Where the game's own right click on `hit` with the stack in hotbar `slot` would put a block, as the game predicts it
// (the block item's placement context: the clicked block itself when it can be replaced, else the one past the face,
// and nothing when the block would not go in), or None. Dry: the world is not changed. Scaffold's Normal checks each
// click with it before pressing.
pub(crate) fn places_into(game: &mut Game<'_>, hit: &crate::game::Hit, slot: usize) -> Option<[i32; 3]> {
    let stack = game.stack_in(slot)?.clone();
    game.remote_can_place(hit, &stack).map(|(pos, _)| [pos.x, pos.y, pos.z])
}

// Telly clicks immediately before the movement pass. The native use owns sequencing, inventory consumption,
// interaction callbacks, prediction and the swing packet. Only the optional local arm animation is restored.
pub(crate) fn use_block(game: &mut Game<'_>, hit: crate::game::Hit, look: (f32, f32), swing: bool) {
    let previous_hit = game.forced_hit.replace(hit);
    let animation = game.swing;
    let view = (game.yaw, game.pitch);
    (game.yaw, game.pitch) = look;
    game.remote_use();
    (game.yaw, game.pitch) = view;
    game.forced_hit = previous_hit;
    if !swing {
        game.swing = animation;
    }
}

// A missing predicted block is only a rejection once the native prediction handler has settled it.
pub(crate) fn prediction_pending(game: &Game<'_>, cell: [i32; 3]) -> bool {
    game.remote
        .as_ref()
        .is_some_and(|r| r.predictions.contains_key(&cell))
}

// The held slot as the server knows it: true when `slot` is news to it (the caller sends the SetCarriedItem). The
// game sends one before anything the selected slot acts with whenever the selection differs from what it last told
// (`remote_send_carried`, MultiPlayerGameMode.ensureHasSentCarriedItem), so this keeps it from sending the same slot a
// second time (Grim BadPacketsA, Intave "sent slot twice"). False without a connection.
pub(crate) fn tell_carried(game: &mut Game<'_>, slot: usize) -> bool {
    game.remote.as_mut().is_some_and(|r| r.carried.replace(Some(slot)) != Some(slot))
}

// The wait the game puts between one block's breaking and the next (5 ticks).
pub(crate) fn clear_destroy_delay(game: &mut Game<'_>, wait: u32) {
    if let Some(r) = game.remote.as_mut() {
        r.destroy_delay = r.destroy_delay.min(wait);
    }
}

// The block being broken by hand and how far it is (0 to 1), for Speed Mine.
pub(crate) fn breaking(game: &Game<'_>) -> Option<([i32; 3], f32)> {
    game.remote.as_ref()?.destroying.map(|(pos, _, done)| (pos, done))
}

pub(crate) fn set_breaking(game: &mut Game<'_>, done: f32) {
    if let Some((_, _, d)) = game.remote.as_mut().and_then(|r| r.destroying.as_mut()) {
        *d = done;
    }
}

// No Break Reset: the item in hand is no longer the one the break began with (the game would start it again).
pub(crate) fn breaking_item_changed(game: &Game<'_>) -> bool {
    game.remote.as_ref().is_some_and(|r| r.destroying.is_some() && r.destroying_item != game.main_hand_key())
}

// ...so the break goes on with the new one.
pub(crate) fn keep_breaking(game: &mut Game<'_>) {
    let held = game.main_hand_key();
    if let Some(r) = game.remote.as_mut() {
        r.destroying_item = held;
    }
}

// Anti Vanish: the names in the tab list (the listed players, not you).
// Anti Vanish: everyone else the server's player info names, with their game mode and whether the tab list shows them.
pub(crate) fn tab_presence(game: &Game<'_>) -> Vec<(String, i32, bool)> {
    game.remote.as_ref().map_or_else(Vec::new, |r| {
        r.tab_players.values().filter(|p| p.uuid != r.profile).map(|p| (p.name.clone(), p.game_mode, r.listed.contains(&p.uuid))).collect()
    })
}

pub(crate) fn tab_names(game: &Game<'_>) -> Vec<String> {
    game.remote.as_ref().map_or_else(Vec::new, |r| {
        r.tab_players.values().filter(|p| p.uuid != r.profile && r.listed.contains(&p.uuid)).map(|p| p.name.clone()).collect()
    })
}

// Streamer Mode: your names (your profile's, and the last word of your listed display name, a nickname, when it is
// not your profile name) and everyone else's the same way from the server's player list, with the players in the world.
pub(crate) fn player_names(game: &Game<'_>) -> (Vec<String>, Vec<String>) {
    let Some(r) = game.remote.as_ref() else {
        return (Vec::new(), Vec::new());
    };
    let mut own = vec![r.profile_name.clone()];
    let mut others = Vec::new();
    for t in r.tab_players.values() {
        let list = if t.uuid == r.profile { &mut own } else { &mut others };
        list.push(t.name.clone());
        let shown = t.display_name.as_ref().map(horizon_client::scoreboard::comp_text).map(|text| text.plain());
        // A display name that shows the profile name is no nickname ("[VIP] Notch", "Notch [AFK]").
        let nick = shown.as_deref().and_then(|plain| {
            let words: Vec<&str> = plain.split(|c: char| !(c.is_ascii_alphanumeric() || c == '_')).filter(|w| !w.is_empty()).collect();
            (!words.iter().any(|w| w.eq_ignore_ascii_case(&t.name))).then(|| words.last().copied()).flatten()
        });
        if let Some(nick) = nick {
            list.push(nick.to_owned());
        }
    }
    others.extend(r.level_player_names.values().cloned());
    (own, others)
}

// Streamer Mode: what changes when a player joins, leaves or appears in the world (cheap enough for every frame).
pub(crate) fn players_changed_key(game: &Game<'_>) -> u128 {
    game.remote.as_ref().map_or(0, |r| {
        let listed = r.tab_players.keys().fold(0u128, |a, k| a ^ k.rotate_left(17));
        let level = r.level_player_names.keys().fold(0u128, |a, &k| a.wrapping_add(k as u128 * 0x9e37_79b9));
        listed ^ level ^ ((r.tab_players.len() as u128) << 96) ^ ((r.level_player_names.len() as u128) << 64)
    })
}

// Read the server's actual command dispatcher, never the vanilla fallback.
use crate::game::Game;
use horizon_client::command::{Dispatcher, NodeKind, Suggests};
use std::collections::VecDeque;
use std::sync::Mutex;

pub(crate) struct View {
    pub address: String,
    pub brand: String,
    // None until the server has sent its command tree.
    pub commands: Option<(Vec<String>, Vec<String>, Option<String>)>,
}

// What the server's own command tree holds. Remote keeps only the chat's tree (the server's with the mods'
// commands merged in), so it is read where that tree is built; a new connection, which has no tree yet, clears it.
static COMMANDS: Mutex<Option<(Vec<String>, Vec<String>, Option<String>)>> = Mutex::new(None);

pub(crate) fn server_tree(tree: Option<&Dispatcher>) {
    *COMMANDS.lock().unwrap_or_else(|e| e.into_inner()) = tree.map(extract);
}

pub(crate) fn view(game: &Game<'_>) -> Option<View> {
    let remote = game.remote.as_ref()?;
    Some(View {
        address: remote.session.address.clone(),
        brand: remote.brand.chars().take(128).collect(),
        commands: COMMANDS.lock().unwrap_or_else(|e| e.into_inner()).clone(),
    })
}

fn extract(tree: &Dispatcher) -> (Vec<String>, Vec<String>, Option<String>) {
    let mut roots = Vec::new();
    let mut literals = Vec::new();
    let mut suggestion = None;
    let mut queue = VecDeque::new();
    if let Some(root) = tree.nodes.first() {
        for &i in root.children.iter().take(512) {
            let Some(node) = tree.nodes.get(i) else {
                continue;
            };
            let NodeKind::Literal(root) = &node.kind else {
                continue;
            };
            if root.len() > 128 || !root.is_ascii() {
                continue;
            }
            roots.push(root.clone());
            if queue.len() < 512 {
                queue.push_back((i, root.clone(), 0u8));
            }
            // Only one low-rate request, on a visible version command whose argument explicitly
            // asks the server for suggestions (Bukkit's /version, aliases /ver and /about, completes
            // plugin names). Never guess hidden command names.
            if suggestion.is_none()
                && matches!(root.as_str(), "version" | "ver" | "about" | "bukkit:version" | "bukkit:ver" | "bukkit:about")
                && node
                    .children
                    .iter()
                    .filter_map(|&child| tree.nodes.get(child))
                    .any(|child| {
                        matches!(child.kind, NodeKind::Argument { .. })
                            && child.suggests == Some(Suggests::AskServer)
                    })
            {
                suggestion = Some(format!("/{root} "));
            }
        }
    }
    let mut visited = 0;
    while let Some((parent, path, depth)) = queue.pop_front() {
        visited += 1;
        if visited > 1024 || depth >= 4 || literals.len() >= 512 {
            break;
        }
        let Some(node) = tree.nodes.get(parent) else {
            continue;
        };
        for &child in &node.children {
            let Some(child_node) = tree.nodes.get(child) else {
                continue;
            };
            let (name, literal) = match &child_node.kind {
                NodeKind::Literal(name) => (name.as_str(), true),
                NodeKind::Argument { name, .. } => (name.as_str(), false),
                NodeKind::Root => continue,
            };
            if name.len() > 64 || !name.is_ascii() || path.len() + name.len() + 3 > 128 {
                continue;
            }
            let next = if literal {
                format!("{path} {name}")
            } else {
                format!("{path} <{name}>")
            };
            if literal {
                literals.push(next.clone());
            }
            if queue.len() < 512 {
                queue.push_back((child, next, depth + 1));
            }
            if literals.len() >= 512 {
                break;
            }
        }
    }
    (roots, literals, suggestion)
}

#[cfg(test)]
mod tests {
    use super::*;
    use horizon_client::command::{Node, args::ArgType};

    #[test]
    fn extracts_only_server_tree_roots_and_visible_suggestion_path() {
        let mut tree = Dispatcher::new();
        tree.nodes.push(Node {
            kind: NodeKind::Literal("luckperms:lp".into()),
            children: vec![4],
            command: None,
            redirect: None,
            permission: 0,
            restricted: false,
            suggests: None,
        });
        tree.nodes.push(Node {
            kind: NodeKind::Literal("version".into()),
            children: vec![3],
            command: None,
            redirect: None,
            permission: 0,
            restricted: false,
            suggests: None,
        });
        tree.nodes.push(Node {
            kind: NodeKind::Argument {
                name: "plugin".into(),
                ty: ArgType::Word,
            },
            children: vec![],
            command: None,
            redirect: None,
            permission: 0,
            restricted: false,
            suggests: Some(Suggests::AskServer),
        });
        tree.nodes.push(Node {
            kind: NodeKind::Literal("user".into()),
            children: vec![],
            command: None,
            redirect: None,
            permission: 0,
            restricted: false,
            suggests: None,
        });
        tree.nodes[0].children = vec![1, 2, 999];
        assert_eq!(
            extract(&tree),
            (
                vec!["luckperms:lp".into(), "version".into()],
                vec!["luckperms:lp user".into()],
                Some("/version ".into())
            )
        );
        assert_eq!(extract(&Dispatcher::new()), (vec![], vec![], None));
    }
}

// The game's collider ray (a module of game/spear.rs, where it is private): where a line from `from` to `to` first
// meets a block, for the melee modules and Kill Aura.
pub(crate) fn clip(
    game: &crate::game::Game<'_>,
    from: horizon_core::geometry::Vec3,
    to: horizon_core::geometry::Vec3,
) -> Option<horizon_core::geometry::Vec3> {
    game.clip_collider(from, to)
}

// What Sunset asks of the player's own movement, set once a tick by the game and read by the hooks on the
// movement code (the window's thread only, never a server's): Safe Walk keeps to edges as sneaking does (Sunset's
// ClipAtLedgeEvent), Speed sets the move across the ground (Sunset's PlayerMoveEvent), Velocity scales how
// flowing liquids push (the flow each fluid block gives, across and up), Flight sets the air's pull, GUI Move
// keeps a sprint going behind a screen, and Kill Aura's Target strafe turns the move across the ground.

use std::cell::Cell;

pub fn reset() {
    set_freeze(false);
    set_input_scale(None);
    set_block_use_scale(None);
    set_move_yaw(None);
    set_no_sprint(false);
    set_no_slow_grim(false);
    set_no_slow_skip(false);
    set_screen_keys(None);
    set_flying_speed(None);
    set_safe_walk(false);
    set_across(None);
    set_up(None);
    set_strafe_dir(None);
    set_liquid_flow(None);
    ATTACK_SLOW.with(|c| c.set((0, 0)));
}

thread_local! {
    // GUI Move's pending inventory transaction: one movement consumes the override,
    // while the matching PlayerInput remains empty through the end of this tick.
    static FREEZE_MOVE: Cell<bool> = const { Cell::new(false) };
    static FREEZE_INPUT: Cell<bool> = const { Cell::new(false) };
    static INPUT_SCALE: Cell<Option<f32>> = const { Cell::new(None) };
    static BLOCK_USE_SCALE: Cell<Option<f32>> = const { Cell::new(None) };
    static SAFE_WALK: Cell<bool> = const { Cell::new(false) };
    // Blocks a tick across the ground, x and z.
    static ACROSS: Cell<Option<[f64; 2]>> = const { Cell::new(None) };
    static UP: Cell<Option<f64>> = const { Cell::new(None) };
    // Legacy Speed requests a native ballistic jump at a scale of jump strength, with native block/Jump Boost factors.
    static BALLISTIC_JUMP: Cell<Option<f64>> = const { Cell::new(None) };
    static LEGACY_VELOCITY: Cell<Option<[f64; 2]>> = const { Cell::new(None) };
    // Target strafe: the way (x, z, length 1) the move across the ground goes this tick, at its own speed.
    static STRAFE_DIR: Cell<Option<[f64; 2]>> = const { Cell::new(None) };
    static LIQUID: Cell<Option<[f64; 2]>> = const { Cell::new(None) };
    // Flight's Velocity mode: the air's pull on your input (Player.getFlyingSpeed).
    static FLYING: Cell<Option<f32>> = const { Cell::new(None) };
    // GUI Move: the move keys held behind a screen, which the game would not take.
    static SCREEN_KEYS: Cell<Option<crate::sprint::Keys>> = const { Cell::new(None) };
    // GUI Move: the keys this tick's movement took behind a screen, for the tick's PlayerInput.
    static SCREEN_MOVED: Cell<Option<crate::sprint::Keys>> = const { Cell::new(None) };
    // No Slow's Skip: the item-use slowdown left out of this tick's move.
    static NO_SLOW_SKIP: Cell<bool> = const { Cell::new(false) };
    // No Slow's GrimAC mode keeps Speed's movement override out of item-use ticks.
    static NO_SLOW_GRIM: Cell<bool> = const { Cell::new(false) };
    // Knockback hits since the last movement, and the game tick of the last: each cuts the speed across to 0.6 and
    // stops the sprint.
    static ATTACK_SLOW: Cell<(u32, u64)> = const { Cell::new((0, 0)) };
    // Scaffold's movement correction: the yaw the next movement goes by (the look the server is told), so the move
    // matches the keys it is told at that yaw. Taken by that movement.
    static MOVE_YAW: Cell<Option<f32>> = const { Cell::new(None) };
    // Scaffold's Sprint Off: the next movement goes without a sprint. Taken by that movement.
    static NO_SPRINT: Cell<bool> = const { Cell::new(false) };
}

pub fn set_freeze(on: bool) {
    FREEZE_MOVE.with(|c| c.set(on));
    FREEZE_INPUT.with(|c| c.set(on));
}

pub fn take_freeze() -> bool { FREEZE_MOVE.with(Cell::take) }
pub fn frozen() -> bool { FREEZE_INPUT.with(Cell::get) }

pub fn set_input_scale(scale: Option<f32>) {
    INPUT_SCALE.with(|c| c.set(scale.filter(|s| s.is_finite()).map(|s| s.clamp(0.01, 1.0))));
}

pub fn take_input_scale() -> Option<f32> { INPUT_SCALE.with(Cell::take) }

pub fn set_move_yaw(yaw: Option<f32>) {
    MOVE_YAW.with(|c| c.set(yaw));
}

pub fn take_move_yaw() -> Option<f32> {
    MOVE_YAW.with(Cell::take)
}

pub fn set_no_sprint(on: bool) {
    NO_SPRINT.with(|c| c.set(on));
}

pub fn take_no_sprint() -> bool {
    NO_SPRINT.with(Cell::take)
}

pub fn set_no_slow_grim(on: bool) {
    NO_SLOW_GRIM.with(|c| c.set(on));
}

pub fn no_slow_grim() -> bool {
    NO_SLOW_GRIM.with(Cell::get)
}

pub fn set_no_slow_skip(on: bool) {
    NO_SLOW_SKIP.with(|c| c.set(on));
}

pub fn no_slow_skip() -> bool {
    NO_SLOW_SKIP.with(Cell::get)
}

pub fn add_attack_slow(tick: u64) {
    ATTACK_SLOW.with(|c| c.set((c.get().0.saturating_add(1), tick)));
}

// The start of a tick: hits from before the last tick's movement that no movement took (riding, dead) are gone.
pub fn expire_attack_slow(tick: u64) {
    ATTACK_SLOW.with(|c| {
        if c.get().1 < tick {
            c.set((0, 0));
        }
    });
}

// The knockback hits the next movement starts with (then none).
pub fn take_attack_slow() -> u32 {
    ATTACK_SLOW.with(|c| c.replace((0, 0)).0)
}

pub fn set_screen_keys(keys: Option<crate::sprint::Keys>) {
    SCREEN_KEYS.with(|c| c.set(keys));
    SCREEN_MOVED.with(|c| c.set(None));
}

// The keys a tick's movement takes behind a screen while GUI Move walks you: the ones held, when the game gave it none
// (a screen keeps them from it) and some are held. None: the keys as they are.
pub fn screen_keys(keys: crate::sprint::Keys) -> Option<crate::sprint::Keys> {
    if frozen() { return None; }
    let pressed = |k: crate::sprint::Keys| k.direction() != [0.0, 0.0] || k.jump || k.shift;
    let moved = SCREEN_KEYS.with(Cell::get).filter(|held| !pressed(keys) && pressed(*held));
    // Kept till the next tick: the move's call again with these keys passes through here too.
    if moved.is_some() {
        SCREEN_MOVED.with(|c| c.set(moved));
    }
    moved
}

// The PlayerInput flags a tick sends with the keys GUI Move moved with behind a screen added (the game's have none
// there, and the server predicts the move from them); None when that adds nothing.
pub fn screen_input(input: u8) -> Option<u8> {
    if frozen() { return (input != 0).then_some(0); }
    let k = SCREEN_MOVED.with(Cell::get)?;
    let with = input
        | u8::from(k.forward)
        | u8::from(k.backward) << 1
        | u8::from(k.left) << 2
        | u8::from(k.right) << 3
        | u8::from(k.jump) << 4
        | u8::from(k.shift) << 5
        | u8::from(k.sprint) << 6;
    (with != input).then_some(with)
}

pub fn set_flying_speed(speed: Option<f32>) {
    FLYING.with(|c| c.set(speed));
}

pub fn flying_speed(speed: f32) -> f32 {
    FLYING.with(Cell::get).unwrap_or(speed)
}

pub fn set_safe_walk(on: bool) {
    SAFE_WALK.with(|c| c.set(on));
}

pub fn set_across(across: Option<[f64; 2]>) {
    ACROSS.with(|c| c.set(across));
}

pub fn set_up(up: Option<f64>) {
    UP.with(|c| c.set(up));
    BALLISTIC_JUMP.with(|c| c.set(None));
    LEGACY_VELOCITY.with(|c| c.set(None));
}

pub fn set_block_use_scale(scale: Option<f32>) {
    BLOCK_USE_SCALE.with(|c| c.set(scale));
}

pub fn block_use_scale() -> Option<f32> { BLOCK_USE_SCALE.with(Cell::get) }

pub fn take_block_use_scale() -> Option<f32> { BLOCK_USE_SCALE.with(|c| c.take()) }

pub fn set_ballistic_jump(scale: Option<f64>) {
    set_up(None);
    BALLISTIC_JUMP.with(|c| c.set(scale));
}

pub fn take_ballistic_jump() -> Option<f64> {
    BALLISTIC_JUMP.with(|c| c.take())
}

pub fn set_legacy_velocity(across: Option<[f64; 2]>) {
    LEGACY_VELOCITY.with(|c| c.set(across));
}

pub fn take_legacy_velocity() -> Option<[f64; 2]> {
    LEGACY_VELOCITY.with(|c| c.take())
}

pub fn set_strafe_dir(dir: Option<[f64; 2]>) {
    STRAFE_DIR.with(|c| c.set(dir));
}

pub fn set_liquid_flow(share: Option<[f64; 2]>) {
    LIQUID.with(|c| c.set(share));
}

pub fn liquid_flow(flow: horizon_core::geometry::Vec3) -> horizon_core::geometry::Vec3 {
    match LIQUID.with(Cell::get) {
        Some([h, v]) => horizon_core::geometry::Vec3::new(flow.x * h, flow.y * v, flow.z * h),
        None => flow,
    }
}

pub fn clip_at_ledge(sneaking: bool) -> bool {
    sneaking || SAFE_WALK.with(Cell::get)
}

pub fn self_move(movement: horizon_core::geometry::Vec3) -> horizon_core::geometry::Vec3 {
    if frozen() { return movement; }
    let y = UP.with(Cell::get).unwrap_or(movement.y);
    let [x, z] = ACROSS.with(Cell::get).unwrap_or([movement.x, movement.z]);
    match STRAFE_DIR.with(Cell::get) {
        Some([dx, dz]) => {
            let speed = x.hypot(z);
            horizon_core::geometry::Vec3::new(dx * speed, y, dz * speed)
        }
        None => horizon_core::geometry::Vec3::new(x, y, z),
    }
}

