mod scan_tests {
    use super::*;

    #[test]
    fn scan_queue_is_bounded_and_marks_lost_evidence() {
        let mut queue = VecDeque::new();
        for _ in 0..1024 { scan_push_to(&mut queue, ScanEvent::Commands(1)); }
        assert!(queue.len() <= 256);
