static SEEN: Mutex<Vec<C>> = Mutex::new(Vec::new());

// The plugin API's: every packet (once a plugin listens for them, the last 4096 kept) and the connection's joins and
// ends, read by the game at its next tick and frame.
pub static PLUGIN_PACKETS: AtomicBool = AtomicBool::new(false);
static PLUGIN_IN: Mutex<VecDeque<C>> = Mutex::new(VecDeque::new());
pub enum Connection {
    Joined,
    // The reason, its translation key when it had one, and whether the server gave it.
    Left(String, Option<String>, bool),
}
static PLUGIN_CONNECTION: Mutex<Vec<Connection>> = Mutex::new(Vec::new());

pub fn plugin_packets() -> Vec<C> {
    PLUGIN_IN.lock().unwrap_or_else(|e| e.into_inner()).drain(..).collect()
}

pub fn plugin_connection() -> Vec<Connection> {
    std::mem::take(&mut *PLUGIN_CONNECTION.lock().unwrap_or_else(|e| e.into_inner()))
}

fn plugin_seen(event: &super::Event) {
    match event {
        super::Event::Joined { .. } => PLUGIN_CONNECTION.lock().unwrap_or_else(|e| e.into_inner()).push(Connection::Joined),
        super::Event::Disconnected { reason, key, from_server } => PLUGIN_CONNECTION
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push(Connection::Left(reason.chars().take(512).collect(), key.clone(), *from_server)),
        super::Event::Packet(p) if PLUGIN_PACKETS.load(Ordering::Relaxed) => {
            let mut queue = PLUGIN_IN.lock().unwrap_or_else(|e| e.into_inner());
            if queue.len() == 4096 {
                queue.pop_front();
            }
            queue.push_back((**p).clone());
        }
        _ => {}
    }
}

// Debug Report: the server's clock as it came (when, and its game time), for a TPS estimate, and the connections'
// ends with their reasons.
static CLOCK: Mutex<VecDeque<(Instant, i64)>> = Mutex::new(VecDeque::new());
static ENDS: Mutex<VecDeque<(std::time::SystemTime, String, bool)>> = Mutex::new(VecDeque::new());

fn debug_seen(event: &super::Event) {
    match event {
        super::Event::Joined { .. } => CLOCK.lock().unwrap_or_else(|e| e.into_inner()).clear(),
        super::Event::Disconnected { reason, from_server, .. } => {
            let mut ends = ENDS.lock().unwrap_or_else(|e| e.into_inner());
            if ends.len() == 20 {
                ends.pop_front();
            }
            ends.push_back((std::time::SystemTime::now(), reason.chars().take(512).collect(), *from_server));
        }
        super::Event::Packet(p) => {
            if let C::SetTime(t) = &**p {
                let mut clock = CLOCK.lock().unwrap_or_else(|e| e.into_inner());
                if clock.len() == 30 {
                    clock.pop_front();
                }
                clock.push_back((Instant::now(), t.game_time));
            }
        }
        _ => {}
    }
}

// The server's ticks a second over the clock updates kept (about the last 30 seconds), once they span 3 seconds, and
// the seconds they span.
pub fn tps() -> Option<(f64, f64)> {
    let clock = CLOCK.lock().unwrap_or_else(|e| e.into_inner());
    let (first, last) = (clock.front()?, clock.back()?);
    let seconds = last.0.duration_since(first.0).as_secs_f64();
    (seconds >= 3.0).then(|| ((last.1 - first.1) as f64 / seconds, seconds))
}

// The connections' ends kept (when, the reason, whether the server gave it), oldest first.
pub fn ends() -> Vec<(std::time::SystemTime, String, bool)> {
    ENDS.lock().unwrap_or_else(|e| e.into_inner()).iter().cloned().collect()
}

pub fn seen(events: &[super::Event]) {
    let scan_active = SCAN_ACTIVE.load(Ordering::Relaxed);
    let mut seen = SEEN.lock().unwrap_or_else(|e| e.into_inner());
    for event in events {
        scan_seen(event, scan_active);
        debug_seen(event);
        plugin_seen(event);
        if let super::Event::Packet(p) = event
            && matches!(
                **p,
                C::Login(_)
                    | C::Respawn(_)
                    | C::Disconnect(_)
                    | C::PlayerPosition(_)
                    | C::BlockUpdate(_)
                    | C::SectionBlocksUpdate(_)
                    | C::AddEntity(_)
                    | C::RemoveEntities(_)
                    | C::SetEntityData(_)
                    | C::PlayerInfoUpdate(_)
                    | C::PlayerInfoRemove(_)
                    | C::SetEquipment(_)
                    | C::DamageEvent(_)
                    | C::EntityEvent(_)
                    | C::SetEntityMotion(_)
                    | C::ContainerSetSlot(_)
                    | C::ContainerSetContent(_)
                    | C::SetPlayerInventory(_)
                    | C::SetCursorItem(_)
                    | C::ContainerClose(_)
                    | C::OpenScreen(_)
            )
            && seen.len() < 4096
        {
            seen.push((**p).clone());
        }
        if let super::Event::Packet(p) = event
            && SOUNDS_ON.load(Ordering::Relaxed)
            && matches!(
                **p,
                C::Sound(_)
                    | C::SoundEntity(_)
                    | C::BlockEvent(_)
                    | C::LevelEvent(_)
                    | C::BlockDestruction(_)
                    | C::TakeItemEntity(_)
                    | C::Explode(_)
            )
        {
            let mut sounds = SOUNDS.lock().unwrap_or_else(|e| e.into_inner());
            if sounds.len() < 512 {
                sounds.push((**p).clone());
            }
        }
    }
}

// Sound Detector's packets (sounds, block and level events, mining, pickups, explosions), kept apart from the rest so a
// noisy place can't push those out, and only while it is on: the last 512 till its next tick.
static SOUNDS_ON: AtomicBool = AtomicBool::new(false);
static SOUNDS: Mutex<Vec<C>> = Mutex::new(Vec::new());

pub fn sounds_on(on: bool) {
    if SOUNDS_ON.swap(on, Ordering::Relaxed) && !on {
        SOUNDS.lock().unwrap_or_else(|e| e.into_inner()).clear();
    }
}

pub fn take_sounds() -> Vec<C> {
    std::mem::take(&mut *SOUNDS.lock().unwrap_or_else(|e| e.into_inner()))
}

// No Interact's Anti trap: what it drops as it arrives, as Sunset's tick last told it (kept while told within 250
// ms): the spawns of these entity types within `range` of `at`, and the sign editor.
struct Trap {
    kinds: Vec<i32>,
    at: [f64; 3],
    range: f64,
    sign: bool,
    told: Instant,
}

static TRAP: Mutex<Option<Trap>> = Mutex::new(None);

pub fn trap(kinds: Vec<i32>, at: [f64; 3], range: f64, sign: bool) {
    *TRAP.lock().unwrap_or_else(|e| e.into_inner()) = Some(Trap { kinds, at, range, sign, told: Instant::now() });
}

pub fn trap_off() {
    *TRAP.lock().unwrap_or_else(|e| e.into_inner()) = None;
}

pub fn trap_filter(mut events: Vec<super::Event>) -> Vec<super::Event> {
    let guard = TRAP.lock().unwrap_or_else(|e| e.into_inner());
    let Some(trap) = guard.as_ref().filter(|t| t.told.elapsed() < Duration::from_millis(250)) else {
        return events;
    };
    events.retain(|event| {
        let super::Event::Packet(p) = event else {
            return true;
        };
        match &**p {
            C::OpenSignEditor(_) => !trap.sign,
            C::AddEntity(a) if trap.kinds.contains(&a.kind) => {
                let d2: f64 = (0..3).map(|k| (a.position[k] - trap.at[k]).powi(2)).sum();
                d2 > trap.range * trap.range
            }
            _ => true,
        }
    });
    events
}

pub fn take() -> Vec<C> {
    std::mem::take(&mut *SEEN.lock().unwrap_or_else(|e| e.into_inner()))
}

// Knockback Delay (Velocity's): the pushes on you (your velocity, an explosion's knockback) wait here, by chance, before
// the game takes them; the rest comes in on time. Sunset's tick says each tick how: whose pushes, the chance and the
// wait (ms). Its state is its own: Fake Lag's Knockback mode only sees a push once the game has taken it.
struct Delay {
    me: i32,
    chance: f64,
    wait: [u64; 2],
    told: Instant,
    link: Option<Link>,
    held: VecDeque<(Instant, super::Event)>,
    roll: u64,
    stats: QueueStats,
}

static DELAY: Mutex<Option<Delay>> = Mutex::new(None);

pub fn delay(me: i32, chance: f64, wait: [u64; 2]) {
    let mut d = DELAY.lock().unwrap_or_else(|e| e.into_inner());
    let d = d.get_or_insert_with(|| Delay {
        me,
        chance,
        wait,
        told: Instant::now(),
        link: None,
        held: VecDeque::new(),
        roll: 0x9e37_79b9_7f4a_7c15,
        stats: QueueStats::default(),
    });
    (d.me, d.chance, d.wait, d.told) = (me, chance, wait, Instant::now());
}

pub fn delay_off() {
    if let Some(d) = DELAY.lock().unwrap_or_else(|e| e.into_inner()).as_mut() {
        d.told -= Duration::from_secs(1);
    }
}

pub fn delay_stats() -> Option<QueueStats> {
    DELAY.lock().unwrap_or_else(|e| e.into_inner()).as_ref().map(|d| QueueStats { depth: d.held.len(), ..d.stats })
}

// Held packets of another Session never reach this one; true when they were thrown away.
fn rebind(link: &mut Option<Link>, session: &super::Session, held: usize, stats: &mut QueueStats) -> bool {
    let stale = link.as_ref().is_some_and(|l| l.to(Some(session)) == Linked::Other);
    if stale {
        stats.discarded_session += held as u64;
    }
    if link.is_none() || stale {
        *link = Some(Link::of(session));
    }
    stale
}

pub fn hold(session: &super::Session, events: Vec<super::Event>) -> Vec<super::Event> {
    let mut guard = DELAY.lock().unwrap_or_else(|e| e.into_inner());
    let Some(d) = guard.as_mut() else {
        return events;
    };
    if rebind(&mut d.link, session, d.held.len(), &mut d.stats) {
        d.held.clear();
    }
    // Sunset's tick stopped coming (off, a menu, no world): nothing waits.
    let now = Instant::now();
    let on = horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() && now - d.told < Duration::from_millis(250);
    if d.held.is_empty() && !on {
        return events;
    }
    let mut out = Vec::with_capacity(events.len() + d.held.len());
    let due = d.held.iter().take_while(|(at, _)| !on || *at <= now).count();
    d.stats.released += due as u64;
    out.extend(d.held.drain(..due).map(|(_, e)| e));
    for event in events {
        let super::Event::Packet(p) = &event else {
            // The connection's boundary: what was held goes first, in order.
            if boundary(&event) {
                flushed(&mut d.held, &mut d.stats, 0, &mut out);
            }
            out.push(event);
            continue;
        };
        match &**p {
            // A new world or life: the old one's pushes are no good.
            C::Login(_) | C::Respawn(_) => {
                d.stats.discarded_life += d.held.len() as u64;
                d.held.clear();
            }
            // A teleport: what came before it first.
            C::PlayerPosition(_) => flushed(&mut d.held, &mut d.stats, 1, &mut out),
            C::SetEntityMotion(m) if m.id == d.me => {}
            C::Explode(x) if x.knockback.is_some() => {}
            _ => {
                out.push(event);
                continue;
            }
        }
        if on && matches!(&**p, C::SetEntityMotion(_) | C::Explode(_)) {
            // One waiting already: this one goes after it; else the chance decides.
            let at = if let Some((last, _)) = d.held.back() {
                Some(*last)
            } else {
                d.roll ^= d.roll << 13;
                d.roll ^= d.roll >> 7;
                d.roll ^= d.roll << 17;
                let [lo, hi] = d.wait;
                let lucky = ((d.roll % 10_000) as f64) < d.chance * 100.0;
                (lucky && hi > 0).then(|| now + Duration::from_millis(lo + (d.roll >> 16) % (hi - lo + 1)))
            };
            if let Some(at) = at {
                d.held.push_back((at, event));
                d.stats.held += 1;
                d.stats.max_depth = d.stats.max_depth.max(d.held.len());
                continue;
            }
        }
        flushed(&mut d.held, &mut d.stats, 6, &mut out);
        out.push(event);
    }
    out
}

// Backtrack: while the player you last hit moves away from you, everything the server sends waits a little (each
// packet Shortest to Longest latency, in order), so the world, them included, reaches you that much later and stays in
// reach a moment longer; when they stop moving away, all of it comes at once. A teleport, your own velocity, a new
// world, the connection's boundaries, their removal or a new target lets it all through first. Sunset's tick says each
// tick whom, from where (your eyes) and how long; a tick that stops coming lets go of it all. Its state is its own: Fake
// Lag (outgoing) shares nothing with it.
struct Backtrack {
    me: i32,
    target: i32,
    eye: [f64; 3],
    latency: [u64; 2],
    told: Instant,
    link: Option<Link>,
    // Where the server has them, from what it sent, starting from where the game had them with nothing held.
    server: Option<[f64; 3]>,
    // A new target: what is held (the old one's world) goes before anything is held for the new one.
    switched: bool,
    away: bool,
    last_due: Option<Instant>,
    held: VecDeque<(Instant, super::Event)>,
    roll: u64,
    stats: QueueStats,
}

static BACKTRACK: Mutex<Option<Backtrack>> = Mutex::new(None);

pub fn backtrack(me: i32, target: i32, at: [f64; 3], eye: [f64; 3], latency: [u64; 2]) {
    let mut b = BACKTRACK.lock().unwrap_or_else(|e| e.into_inner());
    let b = b.get_or_insert_with(|| Backtrack {
        me,
        target,
        eye,
        latency,
        told: Instant::now(),
        link: None,
        server: None,
        switched: false,
        away: false,
        last_due: None,
        held: VecDeque::new(),
        roll: 0x2545_f491_4f6c_dd1d,
        stats: QueueStats::default(),
    });
    if b.target != target {
        // The game's position of the new target is behind what is held: track it only once that has gone.
        b.switched = !b.held.is_empty();
        b.server = None;
        b.away = false;
        b.stats.target_switches += 1;
    } else if b.server.is_none() && b.held.is_empty() && !b.switched {
        b.server = Some(at);
    }
    (b.me, b.target, b.eye, b.latency, b.told) = (me, target, eye, latency, Instant::now());
}

pub fn backtrack_off() {
    if let Some(b) = BACKTRACK.lock().unwrap_or_else(|e| e.into_inner()).as_mut() {
        b.told -= Duration::from_secs(1);
    }
}

// Where Backtrack's player really is, while it holds what came in.
pub fn backtrack_shown() -> Option<[f64; 3]> {
    BACKTRACK.lock().unwrap_or_else(|e| e.into_inner()).as_ref().filter(|b| !b.held.is_empty()).and_then(|b| b.server)
}

pub fn backtrack_stats() -> Option<QueueStats> {
    BACKTRACK.lock().unwrap_or_else(|e| e.into_inner()).as_ref().map(|b| QueueStats { depth: b.held.len(), ..b.stats })
}

fn far(eye: [f64; 3], at: [f64; 3]) -> f64 {
    let centre = [at[0], at[1] + 0.9, at[2]];
    (0..3).map(|i| (centre[i] - eye[i]).powi(2)).sum::<f64>().sqrt()
}

pub fn backtrack_hold(session: &super::Session, events: Vec<super::Event>) -> Vec<super::Event> {
    let mut guard = BACKTRACK.lock().unwrap_or_else(|e| e.into_inner());
    let Some(b) = guard.as_mut() else {
        return events;
    };
    if rebind(&mut b.link, session, b.held.len(), &mut b.stats) {
        b.held.clear();
        b.server = None;
        b.away = false;
        b.switched = false;
    }
    let now = Instant::now();
    let on = horizon_protocol::connection::sunset_lifecycle::RUNTIME.running() && now - b.told < Duration::from_millis(250);
    if b.held.is_empty() && !on {
        b.server = None;
        b.switched = false;
        return events;
    }
    let mut out = Vec::with_capacity(events.len() + b.held.len());
    if b.switched {
        flushed(&mut b.held, &mut b.stats, 4, &mut out);
        b.switched = false;
    }
    let due = b.held.iter().take_while(|(at, _)| on && *at <= now).count();
    if on && b.held.len() < 4096 {
        b.stats.released += due as u64;
        out.extend(b.held.drain(..due).map(|(_, e)| e));
    } else {
        flushed(&mut b.held, &mut b.stats, 6, &mut out);
    }
    for event in events {
        let super::Event::Packet(p) = &event else {
            flushed(&mut b.held, &mut b.stats, 0, &mut out);
            b.away = false;
            if boundary(&event) {
                b.server = None;
            }
            out.push(event);
            continue;
        };
        let flush = match &**p {
            C::Login(_) | C::Respawn(_) | C::Disconnect(_) => Some(0),
            C::PlayerPosition(_) => Some(1),
            C::SetEntityMotion(m) if m.id == b.me => Some(2),
            C::RemoveEntities(r) if r.ids.contains(&b.target) => Some(3),
            _ => None,
        };
        if flush.is_some() || !on {
            flushed(&mut b.held, &mut b.stats, flush.unwrap_or(6), &mut out);
            b.away = false;
            if flush.is_some_and(|f| f != 2) {
                b.server = None;
            }
            out.push(event);
            continue;
        }
        let moved = match &**p {
            C::MoveEntityPos(m) if m.0.id == b.target => b.server.zip(m.0.delta.as_ref()).map(|(at, d)| d.end(at)),
            C::MoveEntityPosRot(m) if m.0.id == b.target => b.server.zip(m.0.delta.as_ref()).map(|(at, d)| d.end(at)),
            C::TeleportEntity(t) if t.id == b.target && t.relatives == 0 => Some(t.position),
            C::EntityPositionSync(s) if s.id == b.target => Some(s.path.end()),
            _ => None,
        };
        if let Some(at) = moved {
            b.away = b.server.is_some_and(|was| far(b.eye, at) > far(b.eye, was) + 0.001);
            b.server = Some(at);
        }
        if !b.away {
            flushed(&mut b.held, &mut b.stats, 5, &mut out);
            out.push(event);
            continue;
        }
        b.roll ^= b.roll << 13;
        b.roll ^= b.roll >> 7;
        b.roll ^= b.roll << 17;
        let [lo, hi] = b.latency;
        let mut at = now + Duration::from_millis(lo + b.roll % (hi - lo + 1));
        if let Some(last) = b.last_due.filter(|last| at <= *last) {
            at = last + Duration::from_micros(1);
        }
        b.last_due = Some(at);
        b.held.push_back((at, event));
        b.stats.held += 1;
        b.stats.max_depth = b.stats.max_depth.max(b.held.len());
    }
    out
}

// Flight's Packet anti kick asks for the next move packet to carry the position (LocalPlayer.positionReminder = 20).
// And a move packet whose ground Sunset changed: what the server was told, so the game's next update compares with
// that and sends the real ground as soon as Sunset stops changing it (else the server keeps the changed one until
// the next move). The window's thread only.

use std::cell::Cell;

thread_local! {
    static REMIND: Cell<bool> = const { Cell::new(false) };
    static GROUND: Cell<Option<bool>> = const { Cell::new(None) };
}

pub fn remind() {
    REMIND.with(|c| c.set(true));
}

pub fn take() -> bool {
    REMIND.with(|c| c.replace(false))
}

pub fn told_ground(on_ground: bool) {
    GROUND.with(|c| c.set(Some(on_ground)));
}

pub fn take_ground() -> Option<bool> {
    GROUND.with(|c| c.take())
}

// Sunset's lifecycle for this game process, shared by the game, network and renderer crates:
// Running, then (Panic) Stopping, then Dormant, never back. Nothing is saved: the next game
// process starts Running. While Stopping, dispatch is closed and only cleanup runs; Dormant
// begins once no plugin callback is still executing. A token taken while Running stops being
// current at the first stop, so detached work started before Panic drops its result.
use std::sync::atomic::{AtomicU8, AtomicUsize, Ordering::SeqCst};

const RUNNING: u8 = 0;
const STOPPING: u8 = 1;
const DORMANT: u8 = 2;

pub struct Lifecycle {
    state: AtomicU8,
    callbacks: AtomicUsize,
}

pub static RUNTIME: Lifecycle = Lifecycle::new();

impl Lifecycle {
    pub const fn new() -> Self {
        Self { state: AtomicU8::new(RUNNING), callbacks: AtomicUsize::new(0) }
    }

    pub fn running(&self) -> bool { self.state.load(SeqCst) == RUNNING }
    pub fn stopping(&self) -> bool { self.state.load(SeqCst) == STOPPING }
    pub fn dormant(&self) -> bool { self.state.load(SeqCst) == DORMANT }
    pub fn idle(&self) -> bool { self.callbacks.load(SeqCst) == 0 }
    pub fn token(&self) -> u64 { u64::from(self.state.load(SeqCst)) }
    pub fn current(&self, token: u64) -> bool { token == u64::from(RUNNING) && self.running() }

    // Running -> Stopping. True for the one call that started the stop.
    pub fn request_stop(&self) -> bool {
        self.state.compare_exchange(RUNNING, STOPPING, SeqCst, SeqCst).is_ok()
    }

    // Stopping -> Dormant once no callback is in flight. True for the one call that finished it.
    pub fn finish_stop(&self) -> bool {
        self.idle() && self.state.compare_exchange(STOPPING, DORMANT, SeqCst, SeqCst).is_ok()
    }

    // A callback may run only while Running. The count is taken before the state is checked
    // again, so a stop requested in between either sees the callback or the callback sees it.
    pub fn enter(&self) -> Option<Callback<'_>> {
        if !self.running() { return None; }
        self.callbacks.fetch_add(1, SeqCst);
        let callback = Callback(self);
        self.running().then_some(callback)
    }
}

pub struct Callback<'a>(&'a Lifecycle);

impl Drop for Callback<'_> {
    fn drop(&mut self) { self.0.callbacks.fetch_sub(1, SeqCst); }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn stop_blocks_dispatch_and_waits_for_in_flight_callback() {
        let life = Lifecycle::new();
        let callback = life.enter().unwrap();
        assert!(life.request_stop());
        assert!(!life.request_stop());
        assert!(life.stopping() && !life.running());
        assert!(life.enter().is_none());
        assert!(!life.finish_stop());
        drop(callback);
        assert!(life.finish_stop());
        assert!(!life.finish_stop());
        assert!(life.dormant());
    }

    #[test]
    fn dormant_is_final() {
        let life = Lifecycle::new();
        let work = life.token();
        assert!(life.current(work));
        assert!(life.request_stop());
        assert!(!life.current(work));
        assert!(life.finish_stop());
        for _ in 0..4 {
            assert!(!life.request_stop());
            assert!(!life.finish_stop());
            assert!(life.enter().is_none());
            assert!(!life.current(work) && !life.current(life.token()));
            assert!(life.dormant() && !life.running() && !life.stopping());
        }
        assert!(life.idle());
    }

    #[test]
    fn only_one_of_many_threads_starts_or_finishes_the_stop() {
        let life = std::sync::Arc::new(Lifecycle::new());
        let wins: usize = (0..8)
            .map(|_| {
                let life = life.clone();
                std::thread::spawn(move || {
                    let entered = life.enter();
                    let started = usize::from(life.request_stop());
                    drop(entered);
                    started + 10 * usize::from(life.finish_stop())
                })
            })
            .collect::<Vec<_>>()
            .into_iter()
            .map(|t| t.join().unwrap())
            .sum();
        // Every thread's callback is gone: if no thread got to finish, the last caller does.
        let finished_late = usize::from(life.finish_stop());
        assert_eq!(wins % 10, 1, "exactly one thread starts the stop");
        assert_eq!(wins / 10 + finished_late, 1, "exactly one call finishes it");
        assert!(life.dormant() && life.idle());
    }
}

// Debug Report's packet log: the client's own packets as they go on the wire (after Sunset changed, held or added
// them, with the game's ClientTickEnd between ticks), each tagged with the number of client ticks ended before it; the
// last PlayerInput and the last move packet kept apart too, however long ago they went.
// The single player server's threads (horizon-lan-..., horizon-local-...) write here too and are skipped. Only the
// start of a long packet is kept; the report decodes what it can.

use std::collections::VecDeque;
use std::sync::Mutex;
use std::sync::atomic::{AtomicU64, Ordering};

const KEEP: usize = 2048;
const BODY: usize = 256;

#[derive(Clone)]
pub struct Sent {
    pub tick: u64,
    pub id: i32,
    // The packet after its id (cut at BODY bytes).
    pub payload: Vec<u8>,
    pub len: usize,
}

static TICKS: AtomicU64 = AtomicU64::new(0);
static LOG: Mutex<VecDeque<Sent>> = Mutex::new(VecDeque::new());
static LAST_INPUT: Mutex<Option<Sent>> = Mutex::new(None);
static LAST_MOVE: Mutex<Option<Sent>> = Mutex::new(None);

// The client tick's shape as the server reads it (the packets between two ClientTickEnds are one tick; GrimAC's
// TickTimer and Horizon's server both reject a second move in one): moves since the last ClientTickEnd, and the ticks
// that broke it, whatever sent them (the game, a module, Fake Lag's line).
#[derive(Clone, Copy, Debug, Default)]
pub struct Sequence {
    // Ticks that carried a second (or third...) move packet.
    pub extra_moves: u64,
    // The wire tick of the last few of them, newest last.
    pub last: [Option<u64>; 8],
}

static MOVES_THIS_TICK: AtomicU64 = AtomicU64::new(0);
static SEQUENCE: Mutex<Sequence> = Mutex::new(Sequence { extra_moves: 0, last: [None; 8] });

fn sequence_seen(id: i32, tick: u64) {
    use crate::ids::play::serverbound as ids;
    match id {
        ids::MOVE_PLAYER_POS | ids::MOVE_PLAYER_POS_ROT | ids::MOVE_PLAYER_ROT | ids::MOVE_PLAYER_STATUS_ONLY => {
            if MOVES_THIS_TICK.fetch_add(1, Ordering::Relaxed) == 1 {
                let mut s = SEQUENCE.lock().unwrap_or_else(|e| e.into_inner());
                s.extra_moves += 1;
                s.last.rotate_left(1);
                s.last[7] = Some(tick);
            }
        }
        ids::CLIENT_TICK_END => MOVES_THIS_TICK.store(0, Ordering::Relaxed),
        _ => {}
    }
}

pub fn sequence() -> Sequence {
    *SEQUENCE.lock().unwrap_or_else(|e| e.into_inner())
}

fn id(body: &[u8]) -> Option<(i32, usize)> {
    let mut value = 0i32;
    for (i, b) in body.iter().take(5).enumerate() {
        value |= i32::from(b & 0x7F) << (7 * i);
        if b & 0x80 == 0 {
            return Some((value, i + 1));
        }
    }
    None
}

pub fn sent(body: &[u8]) {
    if std::thread::current().name().is_some_and(|n| n.starts_with("horizon-lan") || n.starts_with("horizon-local")) {
        return;
    }
    let Some((id, start)) = id(body) else {
        return;
    };
    use crate::ids::play::serverbound as ids;
    let payload = body[start..].get(..BODY).unwrap_or(&body[start..]).to_vec();
    let sent = Sent { tick: TICKS.load(Ordering::Relaxed), id, payload, len: body.len() - start };
    sequence_seen(id, sent.tick);
    let last = match id {
        ids::PLAYER_INPUT => Some(&LAST_INPUT),
        ids::MOVE_PLAYER_POS | ids::MOVE_PLAYER_POS_ROT | ids::MOVE_PLAYER_ROT | ids::MOVE_PLAYER_STATUS_ONLY => Some(&LAST_MOVE),
        _ => None,
    };
    if let Some(last) = last {
        *last.lock().unwrap_or_else(|e| e.into_inner()) = Some(sent.clone());
    }
    let mut log = LOG.lock().unwrap_or_else(|e| e.into_inner());
    if log.len() == KEEP {
        log.pop_front();
    }
    log.push_back(sent);
    if id == ids::CLIENT_TICK_END {
        TICKS.fetch_add(1, Ordering::Relaxed);
    }
}

// The last PlayerInput and the last move packet sent.
pub fn last_input() -> Option<Sent> {
    LAST_INPUT.lock().unwrap_or_else(|e| e.into_inner()).clone()
}

pub fn last_move() -> Option<Sent> {
    LAST_MOVE.lock().unwrap_or_else(|e| e.into_inner()).clone()
}

// The client ticks ended so far, and the packets kept, oldest first.
pub fn recent() -> (u64, Vec<Sent>) {
    let log = LOG.lock().unwrap_or_else(|e| e.into_inner());
    (TICKS.load(Ordering::Relaxed), log.iter().cloned().collect())
}

// The client ticks ended so far.
pub fn ticks() -> u64 {
    TICKS.load(Ordering::Relaxed)
}

// Sunset's Ore Sim, the part that needs the bundle's own world presets: the decoration of a preset's dimension
// (built once and cached by the bundle, as a world opening builds it), handed to the replay.

pub use super::super::generator_decoration::sunset_ore_sim_replay::{KINDS, OreSim, SeenWorld};
use super::GeneratorData;
use std::sync::Arc;

// The ore roots of `preset`'s `dimension`, ready to replay for any seed: `build` is the level's build range
// (minimum, height), `generation` the generator's (minimum, height, sea level). None when the bundle has no
// features for it.
pub fn ore_sim(
    data: &Arc<GeneratorData>,
    preset: &str,
    dimension: &str,
    build: (i32, i32),
    generation: (i32, i32, i32),
) -> Result<Option<OreSim>, String> {
    let preset_json: serde_json::Value =
        serde_json::from_str(data.world_presets.get(preset).ok_or("no such world preset")?).map_err(|e| e.to_string())?;
    let source_json = preset_json["dimensions"][dimension]["generator"]["biome_source"].to_string();
    let source = data
        .source_catalog
        .decode(&source_json)
        .map_err(|e| e.to_string())?
        .resolve(&data.presets)
        .map_err(|e| e.to_string())?;
    let decoration = data.decoration_for(&source_json, &source).map_err(|e| e.to_string())?;
    let context = super::super::anchor::WorldGenerationContext::new(generation.0, generation.1, generation.2);
    Ok(decoration.map(|d| OreSim::new(d, data.registry(), data.biome_names(), build, context)))
}

// Sunset's Ore Sim, the part that needs decoration's own data: a dimension's ore roots (their placement, feature,
// step and step-local index) replayed for a chunk against the blocks a player sees, recording what each would set.
// The ores, counts, heights, sizes, air exposure and biome lists are the engine's (the worldgen bundle), not a table.

use super::{
    BlockStateId, Decoration, FeatureIdentity, FeaturePlacer, FeatureWorld, HeightmapType, PlacementContext,
    PlacementQueryError, WorldGenerationContext, WorldgenRandom, XoroshiroRandom,
};
use std::collections::{BTreeSet, HashMap};
use std::sync::Arc;

// The ore kinds, in the order Sunset's settings list them. A root's kind is the first whose word its name holds.
// A biome's features are a bitset (one bit a feature identity), as Horizon's own biome_allows_feature reads it.
fn has_feature(bits: &[u64], feature: FeatureIdentity) -> bool {
    bits.get(feature.0 as usize / 64).is_some_and(|w| w >> (feature.0 % 64) & 1 != 0)
}

pub const KINDS: [&str; 10] = ["coal", "copper", "iron", "lapis", "redstone", "gold", "diamond", "emerald", "quartz", "debris"];

// What the replay reads of the world the player sees.
pub trait SeenWorld {
    // The block at a position, None where no chunk is loaded.
    fn block(&self, p: [i32; 3]) -> Option<BlockStateId>;
    // The decoration biome (an index into the bundle's biome names) at a position.
    fn biome(&self, p: [i32; 3]) -> Option<u32>;
    // One above the highest solid block of a column (OCEAN_FLOOR_WG).
    fn floor(&self, x: i32, z: i32) -> Option<i32>;
    // The decoration biomes of the 3x3 chunks round this one, which choose the roots that run.
    fn biomes_near(&self) -> Vec<u32>;
}

struct Root {
    identity: u32,
    index: i32,
    step: i32,
    kind: u8,
}

pub struct OreSim {
    decoration: Arc<Decoration>,
    roots: Vec<Root>,
    // An ore block as the player sees it, mapped to what it replaced when it generated (stone, deepslate,
    // netherrack), so the replay's rules match where the server already shows the ore.
    hosts: HashMap<BlockStateId, BlockStateId>,
    biome_names: Vec<Arc<str>>,
    // The level's build range (minimum, height) and the generator's range (WorldGenerationContext).
    build: (i32, i32),
    generation: WorldGenerationContext,
}

impl OreSim {
    pub(in crate::worldgen) fn new(
        decoration: Arc<Decoration>,
        registry: &crate::registry::BlockRegistry,
        biome_names: &[Arc<str>],
        build: (i32, i32),
        generation: WorldGenerationContext,
    ) -> Self {
        let roots = decoration
            .names
            .iter()
            .filter_map(|name| {
                let short = name.strip_prefix("minecraft:ore_")?;
                let kind = KINDS.iter().position(|k| short.contains(k))? as u8;
                let (identity, index, step) = decoration.seed(name)?;
                decoration.features[identity as usize].as_ref().ok()?;
                Some(Root { identity, index, step, kind })
            })
            .collect();
        let host = |name: &str| registry.default_state(name);
        let (stone, deepslate, netherrack) =
            (host("minecraft:stone"), host("minecraft:deepslate"), host("minecraft:netherrack"));
        let mut hosts = HashMap::new();
        for id in 0..registry.len() as u32 {
            let id = BlockStateId(id);
            let Some(state) = registry.state(id) else { continue };
            let name = state.name.as_str();
            if !(name.ends_with("_ore") || name == "minecraft:ancient_debris") {
                continue;
            }
            let to = if name.starts_with("minecraft:deepslate_") {
                deepslate
            } else if name.starts_with("minecraft:nether_") || name == "minecraft:ancient_debris" {
                netherrack
            } else {
                stone
            };
            if let Some(to) = to {
                hosts.insert(id, to);
            }
        }
        Self { decoration, roots, hosts, biome_names: biome_names.to_vec(), build, generation }
    }

    // The decoration biome index of a biome name, for SeenWorld::biome.
    pub fn biome_index(&self, name: &str) -> Option<u32> {
        self.biome_names.iter().position(|b| &**b == name).map(|i| i as u32)
    }

    // How many ore roots this dimension runs (none: nothing to show here).
    pub fn roots(&self) -> usize {
        self.roots.len()
    }

    // Every block the dimension's ore roots would set in chunk (x, z) of a world made from `seed`, with its kind
    // (an index into KINDS).
    pub fn chunk(&self, seed: i64, x: i32, z: i32, seen: &impl SeenWorld) -> Vec<([i32; 3], u8)> {
        let present: BTreeSet<u32> = seen.biomes_near().into_iter().collect();
        let origin = [x.wrapping_shl(4), self.build.0, z.wrapping_shl(4)];
        let mut random = WorldgenRandom::new(XoroshiroRandom::new(0));
        let decoration_seed = random.set_decoration_seed(seed, origin[0], origin[2]);
        let mut world = Replay { sim: self, seen, placed: HashMap::new(), kind: 0 };
        let mut placer = FeaturePlacer::new();
        for root in &self.roots {
            let id = FeatureIdentity(root.identity);
            if !present.iter().any(|b| self.decoration.biome_features.get(*b as usize).is_some_and(|f| has_feature(f, id))) {
                continue;
            }
            let Ok(feature) = &self.decoration.features[root.identity as usize] else { continue };
            random.set_feature_seed(decoration_seed, root.index, root.step);
            world.kind = root.kind;
            let blocks = self.decoration.blocks;
            let _ = placer.place_with_biome_check(&feature.placement, &mut world, &mut random, origin, id, |w, r, p| {
                feature.feature.place(w, r, p, blocks)
            });
        }
        world.placed.into_iter().map(|(p, (_, kind))| (p, kind)).collect()
    }
}

// The world one chunk's replay runs on: the player's blocks under what the replay has set so far.
struct Replay<'a, S: SeenWorld> {
    sim: &'a OreSim,
    seen: &'a S,
    placed: HashMap<[i32; 3], (BlockStateId, u8)>,
    kind: u8,
}

impl<S: SeenWorld> Replay<'_, S> {
    fn read(&self, p: [i32; 3]) -> Option<BlockStateId> {
        if let Some((state, _)) = self.placed.get(&p) {
            return Some(*state);
        }
        let state = self.seen.block(p)?;
        Some(self.sim.hosts.get(&state).copied().unwrap_or(state))
    }

    fn set(&mut self, p: [i32; 3], state: BlockStateId) {
        self.placed.insert(p, (state, self.kind));
    }
}

impl<S: SeenWorld> FeatureWorld for Replay<'_, S> {
    type Error = ();
    fn block(&mut self, p: [i32; 3]) -> Result<BlockStateId, ()> {
        self.read(p).ok_or(())
    }
    fn set_block(&mut self, p: [i32; 3], state: BlockStateId, _: i32) -> Result<bool, ()> {
        self.set(p, state);
        Ok(true)
    }
}

impl<S: SeenWorld> PlacementContext for Replay<'_, S> {
    fn generation(&self) -> WorldGenerationContext {
        self.sim.generation
    }
    fn min_y(&mut self) -> Result<i32, PlacementQueryError> {
        Ok(self.sim.build.0)
    }
    fn max_y(&mut self) -> Result<i32, PlacementQueryError> {
        Ok(self.sim.build.0 + self.sim.build.1 - 1)
    }
    fn height(&mut self, _: HeightmapType, x: i32, z: i32) -> Result<i32, PlacementQueryError> {
        self.seen.floor(x, z).ok_or(PlacementQueryError::Unavailable)
    }
    fn biome_allows_feature(&mut self, p: [i32; 3], feature: FeatureIdentity) -> Result<bool, PlacementQueryError> {
        let biome = self.seen.biome(p).ok_or(PlacementQueryError::Unavailable)?;
        Ok(self.sim.decoration.biome_features.get(biome as usize).is_some_and(|f| has_feature(f, feature)))
    }
    fn block_state(&mut self, p: [i32; 3]) -> Result<BlockStateId, PlacementQueryError> {
        self.read(p).ok_or(PlacementQueryError::Unavailable)
    }
    fn set_section_block(&mut self, p: [i32; 3], state: BlockStateId) -> Result<(), PlacementQueryError> {
        self.set(p, state);
        Ok(())
    }
}
